@dataclass
class FieldInfo:
    structure: str
    field: str
    type: str
    path: str
    line: int
    source_file: str
    nested_structures: list[str]
    risk_terms: list[str]
    # Source spelling is navigation context only.  The field-safety receipt is
    # addressed through one of these elaborated declarations and a positional
    # constructor slot, so a renamed label cannot change proof/data treatment.
    constructor_fqn: str = ""
    # For constructor routes this is Lean's stored-field ordinal after the
    # constructor parameters.  Result-index binders of an indexed inductive
    # are deliberately not assigned an ordinal: Lean's `CtorInfo.numFields`
    # excludes them, and assigning one would shift a later real field.
    constructor_argument_index: int | None = None
    projection_fqn: str = ""


@dataclass
class StructureInfo:
    name: str
    source_file: str
    line: int
    fields: list[FieldInfo]
    parameters: list[str] = dataclass_field(default_factory=list)
    kind: str = "structure"
    constructor_count: int | None = None
    parameter_types: dict[str, str] = dataclass_field(default_factory=dict)
    # Inductive constructor field slots are Lean-owned.  The source parser may
    # use labels only for navigation, and it must leave an ambiguous result
    # index unresolved until `CtorInfo.numFields` has reconciled the slots.
    constructor_names: list[str] = dataclass_field(default_factory=list)
    unreconciled_constructor_slots: dict[str, str] = dataclass_field(
        default_factory=dict
    )


