def read_text(path: Path) -> str:
    return path.read_text(encoding="utf-8")


def source_text_from_snapshot(
    path: Path,
    source_text_by_path: Mapping[Path, str] | None,
) -> str:
    """Read a source, or require its exact run-local authenticated snapshot."""

    if source_text_by_path is None:
        return read_text(path)
    resolved = path.resolve()
    if resolved not in source_text_by_path:
        raise ValueError(f"source is absent from authenticated snapshot: {path}")
    return source_text_by_path[resolved]


def source_artifact_identity(
    root: Path, path: Path, *, content: bytes | None = None
) -> dict[str, str]:
    """Return a stable, auditable identity for a reviewed Lean source file."""

    try:
        display = str(path.resolve().relative_to(root.resolve()))
    except ValueError:
        display = str(path)
    return {
        "path": display,
        "sha256": hashlib.sha256(
            path.read_bytes() if content is None else content
        ).hexdigest(),
    }


def repository_relative_path(root: Path, path: Path) -> str:
    """Return a portable repository-relative path for generated audit payloads."""

    return path.resolve().relative_to(root.resolve()).as_posix()


def mask_lean_comments(text: str) -> str:
    """Mask Lean line/block comments without treating comment markers in strings as code.

    Declaration extraction operates on the resulting text, so comments must not
    become part of the preceding declaration's semantic surface.  Preserve every
    newline and every non-comment character, including string literals, to keep
    source locations stable and avoid changing a declaration's actual syntax.
    Lean block comments nest; line comments do not.
    """

    output: list[str] = []
    index = 0
    block_depth = 0
    in_line_comment = False
    in_string = False
    while index < len(text):
        char = text[index]

        if block_depth:
            if text.startswith("/-", index):
                block_depth += 1
                output.extend("  ")
                index += 2
                continue
            if text.startswith("-/", index):
                block_depth -= 1
                output.extend("  ")
                index += 2
                continue
            output.append("\n" if char == "\n" else " ")
            index += 1
            continue

        if in_line_comment:
            if char == "\n":
                in_line_comment = False
                output.append(char)
            else:
                output.append(" ")
            index += 1
            continue

        if in_string:
            output.append(char)
            if char == "\\" and index + 1 < len(text):
                output.append(text[index + 1])
                index += 2
                continue
            if char == '"':
                in_string = False
            index += 1
            continue

        if text.startswith("/-", index):
            block_depth = 1
            output.extend("  ")
            index += 2
            continue
        if text.startswith("--", index):
            in_line_comment = True
            output.extend("  ")
            index += 2
            continue
        if char == '"':
            in_string = True
        output.append(char)
        index += 1

    return "".join(output)




def normalize_ws(text: str) -> str:
    return " ".join(text.split())


ITEM_DIGEST_VOLATILE_KEYS = {"line", "source_record_item_sha256"}
AUDIT_SURFACE_DIGEST_VOLATILE_KEYS = {"source_record_item_sha256"}


def canonical_digest_payload(
    payload: object, *, volatile_keys: set[str] | frozenset[str] = frozenset()
) -> object:
    """Canonicalize audit surfaces before hashing.

    Source-record audit payloads are assembled from declaration traversals whose
    discovery order is intentionally not semantic.  The digest is used to decide
    whether human/agent source-record judgments match the current audit surface,
    so it must not change when the same items are discovered in a different
    order, or when unrelated helper insertions only move declaration line
    numbers.
    """

    if isinstance(payload, dict):
        return {
            key: canonical_digest_payload(value, volatile_keys=volatile_keys)
            for key, value in sorted(payload.items())
            if key not in volatile_keys
        }
    if isinstance(payload, list):
        canonical_items = [
            canonical_digest_payload(item, volatile_keys=volatile_keys) for item in payload
        ]
        return sorted(
            canonical_items,
            key=lambda item: json.dumps(item, sort_keys=True, separators=(",", ":")),
        )
    if isinstance(payload, tuple):
        return canonical_digest_payload(list(payload), volatile_keys=volatile_keys)
    return payload


def stable_digest(
    payload: object, *, volatile_keys: set[str] | frozenset[str] = frozenset()
) -> str:
    encoded = json.dumps(
        canonical_digest_payload(payload, volatile_keys=volatile_keys),
        sort_keys=True,
        separators=(",", ":"),
    ).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()


def canonical_governing_corrections(
    status: dict[str, Any],
) -> list[dict[str, Any]] | None:
    """Return the complete, order-insensitive corrected-model change record.

    Correction identifiers alone are not a sufficient approval boundary: a
    changed clause, source anchor, or Lean evidence changes the governing
    model.  Preserve every JSON field in each correction so future metadata
    extensions are also bound by the scope digest.
    """

    raw_corrections = status.get("governing_corrections")
    if not isinstance(raw_corrections, list) or not raw_corrections:
        return None
    corrections: list[dict[str, Any]] = []
    for correction in raw_corrections:
        if not isinstance(correction, dict):
            return None
        correction_id = str(correction.get("id") or "").strip()
        if not correction_id:
            return None
        corrections.append(canonical_digest_payload(correction))
    return sorted(
        corrections,
        key=lambda item: json.dumps(item, sort_keys=True, separators=(",", ":")),
    )


_SOURCE_RECORD_ITEM_IDENTITY_FIELDS = frozenset(
    {
        SOURCE_ASSUMPTION_ASSOCIATION_FIELD,
        "source_contract_association",
        "semantic_contract_source_association",
        "source_statement_association",
        "statement_source_component_association",
        SOURCE_CLAIM_ATOM_ASSOCIATION_FIELD,
        "semantic_contract_group",
        "recursive_field_explicit_parent_route",
    }
)

STATEMENT_SOURCE_COMPONENT_ASSOCIATION_FIELD = (
    "statement_source_component_association"
)
STATEMENT_SOURCE_COMPONENT_ASSOCIATION_SCHEMA = 2
STATEMENT_SOURCE_COMPONENT_IDENTITY_SCHEMA = 1
STATEMENT_SOURCE_COMPONENT_ASSOCIATION_ORIGIN = (
    "authenticated_v10_statement_source_component"
)
STATEMENT_SOURCE_COMPONENT_ASSOCIATION_ROLE = (
    "source_definition_component_semantic_route"
)
STATEMENT_SOURCE_COMPONENT_IDENTITY_FIELD = (
    "source_definition_component_semantic_identity"
)
STATEMENT_SOURCE_COMPONENT_SEMANTIC_ASSOCIATION_FIELD = (
    "component_semantic_association_sha256"
)
STATEMENT_AGGREGATE_SOURCE_REVIEW_RECEIPT_FIELD = (
    "statement_aggregate_source_review_receipt"
)
STATEMENT_AGGREGATE_SOURCE_REVIEW_RECEIPT_SCHEMA = 1
STATEMENT_AGGREGATE_SOURCE_REVIEW_RECEIPT_ORIGIN = (
    "authenticated_v10_aggregate_statement_source_routes"
)

# Recursive record fields receive source credit only through this explicitly
# scoped parent route.  It is intentionally distinct from a theorem input's
# source-contract association: a container route never implicitly credits an
# arbitrary nested field with the same short spelling.
RECURSIVE_FIELD_SOURCE_SCOPE_SCHEMA = 1
RECURSIVE_FIELD_EXPLICIT_PARENT_ROUTE_SCHEMA = 1
RECURSIVE_FIELD_EXPLICIT_PARENT_ROUTE_FIELD = (
    "recursive_field_explicit_parent_route"
)
RECURSIVE_FIELD_SCOPE_CONTAINER_FIELD = "recursive_field_source_scope"

# Item-level source-record reuse is permitted only through source-content
# identities emitted by generated associations.  These explicit source-map
# fields are the only way an item can cite source-proof ledger records.  They
# are not inferred from a map key, source location, prose wording, or Lean
# declaration name.
_SOURCE_RECORD_LEDGER_REFERENCE_FIELDS = {
    "model_convention_ids": "model_conventions",
    "source_defect_ids": "defects",
    "checked_proof_step_ids": "checked_proof_steps",
}
_SOURCE_RECORD_CORRECTED_TARGET_LEDGER_REFERENCE_FIELDS = {
    "governing_defect_ids": "defects",
}
_SOURCE_RECORD_MODEL_CONVENTION_REQUIRED_FIELDS = (
    "source_locator",
    "classification",
    "formal_meaning",
    "why_needed",
    "checked_scope",
)
_SOURCE_RECORD_ITEM_SCOPED_CONTEXT_SCHEMA = 1

# These fields locate an item or make its generated prose readable.  They are
# not the mathematical identity that permits a prior human judgment to survive
# an aggregate-audit refresh.  In particular, a row/binder/declaration rename
# cannot manufacture or preserve a source-record judgment by itself.
_SOURCE_RECORD_ITEM_SEMANTIC_IGNORED_FIELDS = frozenset(
    {
        "row",
        "judgment_key",
        "binder",
        "lean_source_declaration",
        "effective_lean_source_declaration",
        "qualified_declaration",
        "effective_qualified_declaration",
        "reviewed_declaration_identity",
        "reviewed_elaborated_signature_identities",
        "paper_statement_map_sha256",
        "source_contract_association",
        SOURCE_ASSUMPTION_ASSOCIATION_FIELD,
        "semantic_contract_source_association",
        "source_statement_association",
        "statement_source_component_association",
        SOURCE_CLAIM_ATOM_ASSOCIATION_FIELD,
        "semantic_contract_group",
        "source_file",
        "source_location",
        "source_key",
        "source_kind",
        "source_map_item_sha256",
        "source_map_item_keys",
        "source_map_item_keys_sha256",
        "source_map_item_sha256_by_key",
        "association_sha256",
        "paired_qualified_declaration",
        "declaration",
        "local_type_head",
        "record",
        "record_aliases",
        "structure",
        "field",
        "path",
        "line",
        "names",
        "required_check",
        # Lexical spelling hints are diagnostics only.  Semantic risk and
        # reuse are governed by the elaborated proposition/dependency graph.
        "risk_terms",
        "semantic_context_requirements_sha256",
    }
)


def source_record_item_source_semantic_identities(
    item: dict[str, Any],
) -> list[dict[str, str]]:
    """Return source-content IDs without map keys or Lean routes.

    The raw source-only projection excludes map keys and route fields while
    retaining literal source text, source anchors, claim status, target
    metadata, and every non-derived correspondence field.  The generated raw
    map-item digest is retained for integrity review, but never controls
    narrow item reuse.
    """

    candidate_lists: list[object] = []
    for field in _SOURCE_RECORD_ITEM_IDENTITY_FIELDS:
        association = item.get(field)
        if isinstance(association, dict):
            candidate_lists.append(association.get("source_item_identities"))
    identities: dict[str, dict[str, str]] = {}
    for raw_identities in candidate_lists:
        if not isinstance(raw_identities, list):
            continue
        for raw_identity in raw_identities:
            if not isinstance(raw_identity, dict):
                continue
            digest = str(
                raw_identity.get("source_semantic_sha256") or ""
            ).strip().lower()
            if SHA256_RE.fullmatch(digest):
                identities[digest] = {"source_semantic_sha256": digest}
    return [identities[digest] for digest in sorted(identities)]


def statement_source_component_semantic_association_digest(
    component_identity: Mapping[str, Any],
    reviewed_signature_identity: Mapping[str, Any],
) -> str:
    """Bind one source-definition clause to a name-free Lean endpoint."""

    signature_digest = str(
        reviewed_signature_identity.get("elaborated_signature_sha256") or ""
    ).strip().lower()
    if not SHA256_RE.fullmatch(signature_digest):
        return ""
    return stable_digest(
        {
            "schema": STATEMENT_SOURCE_COMPONENT_IDENTITY_SCHEMA,
            "source_definition_component_semantic_identity": dict(
                component_identity
            ),
            "elaborated_signature_sha256": signature_digest,
        }
    )


def source_record_item_statement_component_semantic_identity(
    item: Mapping[str, Any],
) -> tuple[dict[str, str] | None, list[str], bool]:
    """Validate the generated name-free component role used for narrow reuse."""

    association = item.get(STATEMENT_SOURCE_COMPONENT_ASSOCIATION_FIELD)
    if association is None:
        return None, [], False
    if not isinstance(association, Mapping):
        return None, ["statement source-component association is not an object"], True
    errors: list[str] = []
    if association.get("schema") != STATEMENT_SOURCE_COMPONENT_ASSOCIATION_SCHEMA:
        errors.append("statement source-component association has an unsupported schema")
    if (
        str(association.get("association_origin") or "").strip()
        != STATEMENT_SOURCE_COMPONENT_ASSOCIATION_ORIGIN
    ):
        errors.append("statement source-component association has an invalid origin")
    if (
        str(association.get("role") or "").strip()
        != STATEMENT_SOURCE_COMPONENT_ASSOCIATION_ROLE
    ):
        errors.append("statement source-component association has an invalid role")
    component_identity = association.get(STATEMENT_SOURCE_COMPONENT_IDENTITY_FIELD)
    if not isinstance(component_identity, Mapping):
        errors.append("statement source-component association has no component identity")
        component_identity = {}
    elif component_identity.get("schema") != STATEMENT_SOURCE_COMPONENT_IDENTITY_SCHEMA:
        errors.append("statement source-component identity has an unsupported schema")
    required_component_digests = (
        "source_component_semantic_sha256",
        "source_statement_sha256",
        "source_anchor_quote_identity_sha256",
        "source_target_sha256",
        "source_definition_partition_sha256",
        "source_definition_component_sha256",
        "source_component_anchor_sha256",
        "statement_manifest_structure_sha256",
        "statement_semantic_dependency_sha256",
        "statement_review_validator_identity_sha256",
        "statement_review_protocol_sha256",
        "statement_source_route_semantic_sha256",
    )
    for field in required_component_digests:
        if not SHA256_RE.fullmatch(
            str(component_identity.get(field) or "").strip().lower()
        ):
            errors.append(
                "statement source-component identity has no valid " + field
            )
    signature = association.get("reviewed_elaborated_signature_identity")
    if not isinstance(signature, Mapping):
        errors.append(
            "statement source-component association has no elaborated signature"
        )
        signature = {}
    expected = statement_source_component_semantic_association_digest(
        component_identity, signature
    )
    supplied = str(
        association.get(STATEMENT_SOURCE_COMPONENT_SEMANTIC_ASSOCIATION_FIELD)
        or ""
    ).strip().lower()
    if not expected or supplied != expected:
        errors.append(
            "statement source-component semantic association pin is missing or stale"
        )
    if (
        str(association.get("semantic_association_sha256") or "")
        .strip()
        .lower()
        != supplied
    ):
        errors.append(
            "statement source-component generic semantic association pin does not "
            "equal its component discriminator"
        )
    source_identities = association.get("source_item_identities")
    expected_parent = (
        semantic_source_association_digest(list(source_identities), signature)
        if isinstance(source_identities, list)
        else ""
    )
    if (
        not expected_parent
        or str(association.get("parent_semantic_association_sha256") or "")
        .strip()
        .lower()
        != expected_parent
    ):
        errors.append(
            "statement source-component parent semantic association pin is missing or stale"
        )
    full_supplied = str(association.get("association_sha256") or "").strip().lower()
    full_payload = dict(association)
    full_payload.pop("association_sha256", None)
    if not SHA256_RE.fullmatch(full_supplied) or full_supplied != stable_digest(
        full_payload
    ):
        errors.append("statement source-component full association pin is missing or stale")
    if errors:
        return None, sorted(set(errors)), True
    return {
        "statement_source_component_semantic_sha256": supplied,
    }, [], True


def source_record_item_claim_atom_semantic_identities(
    item: Mapping[str, Any],
) -> tuple[list[dict[str, str]], list[str], bool]:
    """Return atom-granular reuse identities for an atom-routed item.

    Parent source-map identities remain necessary for source-context and ledger
    lookup.  They are intentionally too coarse for a compound theorem: editing
    one atom must not invalidate a distinct atom routed to a different Lean
    proposition.  This helper validates the generated current quote contexts
    and returns their narrower source identities solely for the reusable item
    semantic ID.
    """

    association = item.get(SOURCE_CLAIM_ATOM_ASSOCIATION_FIELD)
    if association is None:
        return [], [], False
    if not isinstance(association, Mapping):
        return [], ["source-claim atom association is not an object"], True
    raw_contexts = item.get(SOURCE_CLAIM_ATOM_CONTEXTS_FIELD)
    if not isinstance(raw_contexts, list) or not raw_contexts:
        return [], ["source-claim atom association has no generated atom contexts"], True

    identities: dict[str, dict[str, str]] = {}
    errors: list[str] = []
    contexts: list[Mapping[str, Any]] = []
    for index, raw_context in enumerate(raw_contexts):
        if not isinstance(raw_context, Mapping):
            errors.append(f"source-claim atom context[{index}] is not an object")
            continue
        quote = raw_context.get("source_quote")
        quote_digest = str(raw_context.get("source_quote_sha256") or "").strip().lower()
        if not isinstance(quote, str) or not SHA256_RE.fullmatch(quote_digest):
            errors.append(
                f"source-claim atom context[{index}] lacks a valid current source quote pin"
            )
            continue
        if hashlib.sha256(quote.encode("utf-8")).hexdigest() != quote_digest:
            errors.append(
                f"source-claim atom context[{index}] source quote does not match its SHA-256"
            )
            continue
        expected = source_claim_atom_semantic_digest(raw_context)
        supplied = str(
            raw_context.get("source_claim_atom_semantic_sha256") or ""
        ).strip().lower()
        if not expected or supplied != expected:
            errors.append(
                f"source-claim atom context[{index}] semantic identity is missing or stale"
            )
            continue
        if supplied in identities:
            errors.append(
                f"source-claim atom contexts duplicate semantic identity `{supplied}`"
            )
            continue
        identities[supplied] = {"source_claim_atom_semantic_sha256": supplied}
        contexts.append(raw_context)

    signature = association.get("reviewed_elaborated_signature_identity")
    expected_association_pin = source_claim_atom_semantic_association_digest(
        contexts, signature if isinstance(signature, Mapping) else None
    )
    supplied_association_pin = str(
        association.get(SOURCE_CLAIM_ATOM_SEMANTIC_ASSOCIATION_FIELD) or ""
    ).strip().lower()
    if not expected_association_pin or supplied_association_pin != expected_association_pin:
        errors.append(
            "source-claim atom semantic association pin is missing or stale"
        )
    return [identities[digest] for digest in sorted(identities)], sorted(set(errors)), True


def source_record_source_map_semantic_index(
    paper_statement_map: Mapping[str, Any] | None,
    *,
    additional_source_items: Iterable[Mapping[str, Any]] = (),
) -> dict[str, list[dict[str, Any]]]:
    """Index source-map items by their keyless source-semantic identities.

    The index deliberately does not retain map keys as join material.  A
    generated source-record association already contains the source-content
    SHA-256 identities that it is allowed to review; those identities are the
    only selectors used below for item-scoped context and ledger pins.  Exact
    duplicate source presentations are retained together because their
    explicit semantic content, not their inventory spelling, governs reuse.
    """

    raw_items = (
        paper_statement_map.get("items")
        if isinstance(paper_statement_map, Mapping)
        else None
    )
    index: dict[str, list[dict[str, Any]]] = {}
    candidates: list[Mapping[str, Any]] = []
    if isinstance(raw_items, Mapping):
        candidates.extend(
            raw_item for raw_item in raw_items.values() if isinstance(raw_item, Mapping)
        )
    candidates.extend(
        raw_item for raw_item in additional_source_items if isinstance(raw_item, Mapping)
    )
    for raw_item in candidates:
        if not isinstance(raw_item, dict):
            raw_item = dict(raw_item)
        semantic_sha = source_record_source_item_semantic_sha256(
            dict(raw_item), ""
        )
        if SHA256_RE.fullmatch(semantic_sha):
            index.setdefault(semantic_sha, []).append(dict(raw_item))
    return index


def _source_record_context_semantic_projection(value: object) -> object:
    """Project one source-context entry without its navigation coordinates.

    Context anchors are byte-validated elsewhere.  Their path/range/hash are
    therefore navigation and integrity coordinates, while the literal quote,
    requirement kind, and explanation are the source semantics that an item
    judgment must retain.  This mirrors the source-item projection without
    consulting a source-map key or any Lean identifier.
    """

    if isinstance(value, Mapping):
        projected: dict[str, object] = {}
        for raw_key, raw_value in value.items():
            key = str(raw_key)
            normalized = key.strip().lower()
            if normalized == "source_location":
                continue
            if normalized == "source_anchor_evidence":
                if not isinstance(raw_value, list):
                    projected[key] = raw_value
                    continue
                anchors: list[object] = []
                for raw_anchor in raw_value:
                    if not isinstance(raw_anchor, Mapping):
                        anchors.append(raw_anchor)
                        continue
                    anchors.append(
                        {
                            str(anchor_key): _source_record_context_semantic_projection(
                                anchor_value
                            )
                            for anchor_key, anchor_value in raw_anchor.items()
                            if str(anchor_key).strip().lower()
                            not in {
                                "path",
                                "line_start",
                                "line_end",
                                "quoted_text_sha256",
                            }
                        }
                    )
                projected[key] = anchors
                continue
            projected[key] = _source_record_context_semantic_projection(raw_value)
        return projected
    if isinstance(value, list):
        return [_source_record_context_semantic_projection(item) for item in value]
    if isinstance(value, tuple):
        return [_source_record_context_semantic_projection(item) for item in value]
    return value


def _source_record_explicit_id_list(
    value: object, *, field: str
) -> tuple[list[str], str]:
    """Read a source-map ledger reference without a textual fallback."""

    if not isinstance(value, list):
        return [], f"source-map `{field}` must be a nonempty list of unique strings"
    ids = [entry.strip() for entry in value if isinstance(entry, str) and entry.strip()]
    if len(ids) != len(value) or not ids or len(set(ids)) != len(ids):
        return [], f"source-map `{field}` must be a nonempty list of unique strings"
    return sorted(ids), ""


def _source_record_item_associated_source_items(
    item: dict[str, Any],
    source_map_semantic_index: Mapping[str, list[dict[str, Any]]] | None,
) -> tuple[list[tuple[str, dict[str, Any]]], list[str]]:
    """Resolve generated source identities to current map items by SHA only."""

    source_identities = source_record_item_source_semantic_identities(item)
    source_semantic_shas = [
        identity["source_semantic_sha256"] for identity in source_identities
    ]
    if not source_semantic_shas:
        return [], ["no source-content semantic identity"]
    if source_map_semantic_index is None:
        return [], [
            "item-scoped source context cannot be resolved without the current source-map semantic index"
        ]
    associated: list[tuple[str, dict[str, Any]]] = []
    missing: list[str] = []
    for semantic_sha in source_semantic_shas:
        matches = source_map_semantic_index.get(semantic_sha)
        if not isinstance(matches, list) or not matches:
            missing.append(semantic_sha)
            continue
        for raw_item in matches:
            if isinstance(raw_item, dict):
                associated.append((semantic_sha, raw_item))
    if missing:
        return [], [
            "generated source semantic identity has no current source-map item: "
            + ", ".join(missing)
        ]
    return associated, []


def source_record_item_scoped_context_pins(
    item: dict[str, Any],
    *,
    source_map_semantic_index: Mapping[str, list[dict[str, Any]]] | None,
    source_proof_fidelity: Mapping[str, Any] | None,
) -> tuple[dict[str, Any] | None, dict[str, Any] | None, list[str]]:
    """Return only source context and ledger records cited by one item.

    This is intentionally an identity join, not a name join.  The generated
    item supplies keyless source-content SHA-256 identities; the current map
    supplies only entries with those exact identities.  Context requirements
    are then extracted from those entries, while ledger records are selected
    only through explicit ID fields on those same entries.  A missing or
    malformed explicit reference makes narrow reuse ineligible rather than
    falling back to a whole-ledger hash or a textual/name-based guess.
    """

    associated_items, errors = _source_record_item_associated_source_items(
        item, source_map_semantic_index
    )
    if errors:
        return None, None, errors

    context_by_source_semantic_sha: dict[str, set[str]] = {}
    ledger_ids_by_collection: dict[str, set[str]] = {}
    for semantic_sha, source_item in associated_items:
        raw_requirements = source_item.get("semantic_context_requirements")
        if raw_requirements is not None:
            if not isinstance(raw_requirements, list):
                errors.append(
                    "associated source-map semantic_context_requirements must be a list"
                )
            else:
                projected_requirements: set[str] = set()
                for raw_requirement in raw_requirements:
                    if not isinstance(raw_requirement, Mapping):
                        errors.append(
                            "associated source-map semantic_context_requirements contains a non-object entry"
                        )
                        continue
                    projected_requirements.add(
                        stable_digest(
                            _source_record_context_semantic_projection(raw_requirement)
                        )
                    )
                if projected_requirements:
                    context_by_source_semantic_sha.setdefault(semantic_sha, set()).update(
                        projected_requirements
                    )

        for field, collection in _SOURCE_RECORD_LEDGER_REFERENCE_FIELDS.items():
            if field not in source_item:
                continue
            ids, reference_error = _source_record_explicit_id_list(
                source_item.get(field), field=field
            )
            if reference_error:
                errors.append(reference_error)
                continue
            ledger_ids_by_collection.setdefault(collection, set()).update(ids)

        corrected_target = source_item.get("corrected_target")
        if corrected_target is not None:
            if not isinstance(corrected_target, Mapping):
                errors.append("associated source-map corrected_target must be an object")
            else:
                for (
                    field,
                    collection,
                ) in _SOURCE_RECORD_CORRECTED_TARGET_LEDGER_REFERENCE_FIELDS.items():
                    if field not in corrected_target:
                        continue
                    ids, reference_error = _source_record_explicit_id_list(
                        corrected_target.get(field), field=f"corrected_target.{field}"
                    )
                    if reference_error:
                        errors.append(reference_error)
                        continue
                    ledger_ids_by_collection.setdefault(collection, set()).update(ids)

    if errors:
        return None, None, sorted(set(errors))

    context_pin: dict[str, Any] | None = None
    if context_by_source_semantic_sha:
        context_pin = {
            "schema": _SOURCE_RECORD_ITEM_SCOPED_CONTEXT_SCHEMA,
            "requirement_sha256_by_source_semantic_sha256": {
                semantic_sha: stable_digest(sorted(requirement_digests))
                for semantic_sha, requirement_digests in sorted(
                    context_by_source_semantic_sha.items()
                )
            },
        }

    ledger_pin: dict[str, Any] | None = None
    if ledger_ids_by_collection:
        if not isinstance(source_proof_fidelity, Mapping):
            return None, None, [
                "associated source-map ledger references require a current source-proof-fidelity ledger"
            ]
        records_sha256_by_collection: dict[str, dict[str, str]] = {}
        for collection, ids in sorted(ledger_ids_by_collection.items()):
            raw_records = source_proof_fidelity.get(collection)
            if not isinstance(raw_records, list):
                errors.append(
                    f"source-proof-fidelity `{collection}` must be a list for associated item references"
                )
                continue
            records_by_id: dict[str, Mapping[str, Any]] = {}
            for raw_record in raw_records:
                if not isinstance(raw_record, Mapping):
                    continue
                record_id = str(raw_record.get("id") or "").strip()
                # The aggregate ledger validator owns unrelated malformed
                # records.  Narrow reuse must inspect only a record that this
                # item's explicit source-map identity actually cites.
                if record_id not in ids:
                    continue
                if record_id in records_by_id:
                    errors.append(
                        f"source-proof-fidelity `{collection}` duplicates id `{record_id}`"
                    )
                    continue
                records_by_id[record_id] = raw_record
            record_digests: dict[str, str] = {}
            for record_id in sorted(ids):
                record = records_by_id.get(record_id)
                if record is None:
                    errors.append(
                        f"associated source-map reference cites unknown source-proof-fidelity `{collection}` id `{record_id}`"
                    )
                    continue
                if collection == "model_conventions":
                    for field in _SOURCE_RECORD_MODEL_CONVENTION_REQUIRED_FIELDS:
                        if not str(record.get(field) or "").strip():
                            errors.append(
                                f"source-proof-fidelity model convention `{record_id}` lacks `{field}`"
                            )
                    record_digests[record_id] = model_convention_semantic_digest(record)
                else:
                    record_digests[record_id] = stable_digest(record)
            if record_digests:
                records_sha256_by_collection[collection] = record_digests
        if errors:
            return None, None, sorted(set(errors))
        ledger_pin = {
            "schema": _SOURCE_RECORD_ITEM_SCOPED_CONTEXT_SCHEMA,
            "record_sha256_by_collection": records_sha256_by_collection,
        }

    return context_pin, ledger_pin, []


def attach_transparent_subtype_domain_context_receipts(
    items: list[dict[str, Any]],
    *,
    source_map_semantic_index: Mapping[str, list[dict[str, Any]]] | None,
) -> None:
    """Attach the exact source-domain context required by subtype binders.

    A structurally harmless predicate such as a strict-order restriction can
    still narrow an advertised paper result.  Consequently, a subtype is not
    accepted merely because its local predicate is unrelated to the Lean
    result.  The exact generated source association must resolve, by
    source-content SHA rather than a map key or declaration suffix, to a
    byte-pinned source context explicitly marked ``restricted_subtype_domain``.
    The receipt carries the declaration, source-item, and elaborated-signature
    identities that are later required for nonpropositional-data acceptance.
    """

    for item in items:
        if not isinstance(item, dict) or item.get("kind") != (
            "transparent_subtype_domain_input"
        ):
            continue

        reasons: list[str] = []
        association = item.get("source_contract_association")
        if not isinstance(association, dict):
            reasons.append("no exact generated source-contract association")
            association = {}

        reviewed_identity = association.get("reviewed_declaration_identity")
        reviewed_key = reviewed_declaration_identity_key(reviewed_identity)
        if reviewed_key is None:
            reasons.append("association lacks an exact reviewed declaration identity")

        raw_signature = association.get("reviewed_elaborated_signature_identity")
        signature: dict[str, str] | None = None
        if not isinstance(raw_signature, dict):
            reasons.append("association lacks an exact elaborated review signature")
        else:
            signature_declaration = semantic_contract_fully_qualified_identity(
                raw_signature.get("qualified_declaration")
            )
            signature_digest = str(
                raw_signature.get("elaborated_signature_sha256") or ""
            ).strip().lower()
            if (
                reviewed_key is None
                or signature_declaration != reviewed_key[0]
                or not SHA256_RE.fullmatch(signature_digest)
            ):
                reasons.append(
                    "association elaborated signature does not bind the reviewed declaration"
                )
            else:
                signature = {
                    "qualified_declaration": signature_declaration,
                    "elaborated_signature_sha256": signature_digest,
                }

        source_identities, source_identity_errors = source_contract_source_identities(
            association.get("source_item_identities")
        )
        reasons.extend(source_identity_errors)
        if source_map_semantic_index is None:
            reasons.append("no current source-map semantic index")

        selected_contexts: list[dict[str, Any]] = []
        selected_by_source_semantic_sha: set[str] = set()
        if source_map_semantic_index is not None:
            for identity in source_identities:
                source_semantic_sha = str(
                    identity.get("source_semantic_sha256") or ""
                ).strip().lower()
                mapped_items = source_map_semantic_index.get(source_semantic_sha)
                if not isinstance(mapped_items, list) or not mapped_items:
                    reasons.append(
                        "association source semantic identity has no current source-map item: "
                        + source_semantic_sha
                    )
                    continue
                found_context = False
                for source_item in mapped_items:
                    if not isinstance(source_item, dict):
                        continue
                    raw_contexts = source_item.get("semantic_context_requirements")
                    if not isinstance(raw_contexts, list):
                        continue
                    for raw_context in raw_contexts:
                        if not isinstance(raw_context, dict):
                            continue
                        if (
                            str(raw_context.get("kind") or "").strip()
                            != RESTRICTED_SUBTYPE_DOMAIN_CONTEXT_KIND
                        ):
                            continue
                        anchors = raw_context.get("source_anchor_evidence")
                        if not isinstance(anchors, list) or not anchors:
                            reasons.append(
                                "restricted subtype-domain context has no byte-pinned source anchor"
                            )
                            continue
                        found_context = True
                        selected_by_source_semantic_sha.add(source_semantic_sha)
                        selected_contexts.append(
                            {
                                "source_semantic_sha256": source_semantic_sha,
                                "context_sha256": stable_digest(raw_context),
                                "semantic_context_sha256": stable_digest(
                                    _source_record_context_semantic_projection(
                                        raw_context
                                    )
                                ),
                                "kind": RESTRICTED_SUBTYPE_DOMAIN_CONTEXT_KIND,
                                "source_location": raw_context.get("source_location"),
                                "source_anchor_evidence": anchors,
                            }
                        )
                if not found_context:
                    reasons.append(
                        "association source context lacks required `restricted_subtype_domain` "
                        "semantic context"
                    )

        # A source route can reference multiple source presentations. Each is
        # part of the generated association, so none may silently lose its
        # domain convention. Duplicate map entries with identical semantic
        # content collapse by digest only after this all-identities check.
        if source_identities and len(selected_by_source_semantic_sha) != len(
            {
                str(identity.get("source_semantic_sha256") or "").strip().lower()
                for identity in source_identities
            }
        ):
            reasons.append(
                "not every associated source semantic identity supplied the required domain context"
            )

        deduped_contexts: dict[tuple[str, str], dict[str, Any]] = {}
        for context in selected_contexts:
            key = (
                str(context.get("source_semantic_sha256") or ""),
                str(context.get("context_sha256") or ""),
            )
            deduped_contexts[key] = context
        association_receipt: dict[str, Any] = {}
        if reviewed_key is not None:
            association_receipt["reviewed_declaration_identity"] = dict(
                reviewed_identity
            )
        if source_identities:
            association_receipt["source_item_identities"] = source_identities
        if signature is not None:
            association_receipt["reviewed_elaborated_signature_identity"] = signature
        semantic_association_sha = str(
            association.get("semantic_association_sha256") or ""
        ).strip().lower()
        if SHA256_RE.fullmatch(semantic_association_sha):
            association_receipt["semantic_association_sha256"] = (
                semantic_association_sha
            )

        status = "satisfied" if not reasons and deduped_contexts else "missing"
        item["subtype_domain_source_context"] = {
            "schema": TRANSPARENT_SUBTYPE_DOMAIN_CONTEXT_SCHEMA,
            "required_kind": RESTRICTED_SUBTYPE_DOMAIN_CONTEXT_KIND,
            "status": status,
            "association": association_receipt,
            "selected_contexts": [
                deduped_contexts[key] for key in sorted(deduped_contexts)
            ],
            "failure_reasons": sorted(set(reasons)),
        }
        item["domain_data_only"] = bool(
            item.get("subtype_domain_semantic_data_only") is True
            and status == "satisfied"
        )


def source_record_item_reviewed_signature_identities(
    item: dict[str, Any],
    *,
    row_qualified_names: dict[str, str],
    elaborated_signature_sha256_by_qualified: dict[str, str],
    semantic_dependency_sha256_by_qualified: Mapping[str, str] | None = None,
) -> list[dict[str, str]]:
    """Return exact current review-route signatures for one generated item.

    The only admissible route is a fully-qualified declaration that is both a
    configured current review row and present in the current Lean elaboration
    manifest.  Short names, map keys, and paired/source declaration names are
    intentionally not fallback routes.
    """

    candidates: set[str] = set()
    direct_identity = item.get("reviewed_declaration_identity")
    if isinstance(direct_identity, dict):
        qualified = semantic_contract_fully_qualified_identity(
            direct_identity.get("qualified_declaration")
        )
        if qualified:
            candidates.add(qualified)
    direct_qualified = semantic_contract_fully_qualified_identity(
        item.get("qualified_declaration")
    )
    if direct_qualified:
        candidates.add(direct_qualified)
    row = str(item.get("row") or "").strip()
    if row:
        qualified = semantic_contract_fully_qualified_identity(
            row_qualified_names.get(row)
        )
        if qualified:
            candidates.add(qualified)
    for field in _SOURCE_RECORD_ITEM_IDENTITY_FIELDS:
        association = item.get(field)
        if not isinstance(association, dict):
            continue
        identity = association.get("reviewed_declaration_identity")
        if field == RECURSIVE_FIELD_EXPLICIT_PARENT_ROUTE_FIELD:
            identity = association.get("parent_reviewed_declaration_identity")
        if not isinstance(identity, dict):
            continue
        qualified = semantic_contract_fully_qualified_identity(
            identity.get("qualified_declaration")
        )
        if qualified:
            candidates.add(qualified)

    current_configured = {
        semantic_contract_fully_qualified_identity(qualified)
        for qualified in row_qualified_names.values()
    }
    out: list[dict[str, str]] = []
    dependency_digests = semantic_dependency_sha256_by_qualified or {}
    require_dependency_digest = semantic_dependency_sha256_by_qualified is not None
    for qualified in sorted(candidates & current_configured):
        digest = str(
            elaborated_signature_sha256_by_qualified.get(qualified) or ""
        ).strip().lower()
        dependency_digest = str(
            dependency_digests.get(qualified) or ""
        ).strip().lower()
        if SHA256_RE.fullmatch(digest) and (
            not require_dependency_digest
            or SHA256_RE.fullmatch(dependency_digest)
        ):
            # The qualified spelling is exposed for human route verification,
            # but the digest below binds only the elaborated type fingerprint.
            identity = {
                    "qualified_declaration": qualified,
                    "elaborated_signature_sha256": digest,
                }
            if require_dependency_digest:
                identity["semantic_dependency_sha256"] = dependency_digest
            out.append(identity)
    return out


def source_record_item_semantic_projection(value: object) -> object:
    """Keep the full generated obligation while dropping navigation names.

    This projection is deliberately conservative about *content* but not about
    spelling.  In particular, the expanded input/binder type and the reviewed
    result type are semantic content, not navigation metadata: dropping them
    makes every boundary premise of one theorem share a reusable receipt.
    It retains detected semantic-shape flags, constructor compatibility
    results, result relations, and dependency hashes.  The exact Lean statement
    is bound separately by the name-independent elaborated manifest, so a
    declaration or binder label cannot manufacture freshness by itself.
    """

    if isinstance(value, dict):
        projected: dict[str, object] = {}
        for raw_key, raw_value in value.items():
            key = str(raw_key)
            normalized = key.strip().lower()
            if (
                normalized in _SOURCE_RECORD_ITEM_SEMANTIC_IGNORED_FIELDS
                or normalized.startswith("source_record_item_")
            ):
                continue
            projected[key] = source_record_item_semantic_projection(raw_value)
        return projected
    if isinstance(value, list):
        return [source_record_item_semantic_projection(item) for item in value]
    if isinstance(value, tuple):
        return [source_record_item_semantic_projection(item) for item in value]
    return value


def attach_source_record_item_digests(
    items: list[dict[str, Any]],
    *,
    paper_statement_map: Mapping[str, Any] | None = None,
    source_map_semantic_index: Mapping[str, list[dict[str, Any]]] | None = None,
    source_proof_fidelity: Mapping[str, Any] | None = None,
    semantic_context_digest: str = "",
    source_coverage_map_digest: str = "",
    formalization_scope_digest: str = "",
    source_proof_fidelity_digest: str = "",
    row_qualified_names: dict[str, str] | None = None,
    elaborated_signature_sha256_by_qualified: dict[str, str] | None = None,
    semantic_dependency_sha256_by_qualified: Mapping[str, str] | None = None,
    reusable_mirror_keys: set[str] | None = None,
) -> None:
    """Attach reusable item IDs only for source- and Lean-pinned surfaces.

    The aggregate audit remains the authoritative complete scan.  A sidecar
    may reuse one item only when its source statement has a source-content ID
    and its exact configured review route has a current elaborated Lean
    signature.  Items without either pin deliberately receive no item digest;
    they can still be accepted through a fresh aggregate audit but cannot gain
    narrow reuse by a row, binder, map-key, or function-name coincidence.
    """

    # These aggregate digests remain useful for full-audit freshness and the
    # judge-visible payload, but they must never become an item-level reuse
    # key.  A source-record item instead receives only the context entries and
    # source-proof records reached through its generated source-content
    # identities below.  Retaining the legacy parameters avoids silently
    # changing callers while making their former whole-map/whole-ledger effect
    # impossible.
    del semantic_context_digest, source_coverage_map_digest, source_proof_fidelity_digest
    row_qualified_names = row_qualified_names or {}
    reusable_mirror_keys = reusable_mirror_keys or set()
    elaborated_signature_sha256_by_qualified = (
        elaborated_signature_sha256_by_qualified or {}
    )
    if source_map_semantic_index is None and paper_statement_map is not None:
        source_map_semantic_index = source_record_source_map_semantic_index(
            paper_statement_map
        )
    current_coverage_protocol_digest = formalization_coverage_protocol_digest()

    generated_fields = (
        "source_record_item_digest_schema",
        "source_record_item_context_sha256",
        "source_record_item_semantic_id",
        "source_record_item_sha256",
        "reviewed_elaborated_signature_identities",
        "source_record_item_semantic_context_requirements_sha256",
        "source_record_item_source_proof_fidelity_records_sha256",
        # Legacy generated metadata.  A context digest from a prior whole-map
        # projection must not linger in the schema-5 semantic obligation.
        "semantic_context_requirements_sha256",
    )
    for item in items:
        if not isinstance(item, dict):
            continue
        for field in generated_fields:
            item.pop(field, None)
        source_identities = source_record_item_source_semantic_identities(item)
        (
            atom_reuse_identities,
            atom_reuse_identity_errors,
            has_atom_reuse_identity,
        ) = source_record_item_claim_atom_semantic_identities(item)
        (
            statement_component_identity,
            statement_component_identity_errors,
            has_statement_component_identity,
        ) = source_record_item_statement_component_semantic_identity(item)
        reviewed_signatures = source_record_item_reviewed_signature_identities(
            item,
            row_qualified_names=row_qualified_names,
            elaborated_signature_sha256_by_qualified=(
                elaborated_signature_sha256_by_qualified
            ),
            semantic_dependency_sha256_by_qualified=(
                semantic_dependency_sha256_by_qualified
            ),
        )
        blockers: list[str] = []
        if not source_identities:
            blockers.append("no source-content semantic identity")
        blockers.extend(atom_reuse_identity_errors)
        if has_atom_reuse_identity and not atom_reuse_identities:
            blockers.append("no valid source-claim atom semantic identity")
        blockers.extend(statement_component_identity_errors)
        if has_statement_component_identity and statement_component_identity is None:
            blockers.append("no valid statement source-component semantic identity")
        if not reviewed_signatures:
            blockers.append("no exact current elaborated review-route signature")
        # The canonical theorem-facing ledger mirrors an already reusable
        # specialized boundary/conclusion item by judgment identity. It is a
        # checked semantic view, not a second independent sidecar obligation:
        # requiring its own pin would needlessly invalidate valid item-level
        # reuse whenever this coverage ledger evolves. New result-only inputs
        # have no such mirror and retain their own normal receipt.
        if str(item.get("judgment_key") or "").strip() in reusable_mirror_keys:
            blockers.append(THEOREM_FACING_INPUT_MIRROR_REUSE_BLOCKER)
        scoped_context_pin: dict[str, Any] | None = None
        scoped_ledger_pin: dict[str, Any] | None = None
        if source_identities:
            (
                scoped_context_pin,
                scoped_ledger_pin,
                scoped_context_errors,
            ) = source_record_item_scoped_context_pins(
                item,
                source_map_semantic_index=source_map_semantic_index,
                source_proof_fidelity=source_proof_fidelity,
            )
            blockers.extend(scoped_context_errors)
        item["source_record_item_reuse_eligibility"] = {
            "eligible": not blockers,
            "blockers": blockers,
        }
        # The elaborated signature is a current exact Lean-route identity, not
        # itself an item-level source-evidence receipt.  Preserve it whenever
        # the generator can establish the route, even when this item remains
        # aggregate-only because it has no source-content identity.  Narrow
        # judgment reuse still requires ``eligible: true`` and the generated
        # item digest below.
        if reviewed_signatures:
            item["reviewed_elaborated_signature_identities"] = reviewed_signatures
        if blockers:
            continue

        semantic_identity = {
            "schema": SOURCE_RECORD_ITEM_DIGEST_SCHEMA,
            "source_record_policy_version": SOURCE_RECORD_PROMPT_VERSION,
            FORMALIZATION_COVERAGE_PROTOCOL_FIELD: (
                current_coverage_protocol_digest
            ),
            # A compound source item may carry multiple independent theorem
            # clauses. Parent identities still govern context/ledger lookup
            # above, while the reusable semantic judgment is atom-granular so
            # editing one clause cannot reopen a different routed clause.
            "source_item_semantic_identities": (
                atom_reuse_identities
                if has_atom_reuse_identity
                else source_identities
            ),
            # Declaration spellings are diagnostic only.  The semantic ID
            # contains exactly the Lean-owned, alpha/name-independent digest.
            "reviewed_elaborated_signature_sha256": sorted(
                signature["elaborated_signature_sha256"]
                for signature in reviewed_signatures
            ),
            "review_obligation": source_record_item_semantic_projection(item),
        }
        if statement_component_identity is not None:
            semantic_identity["statement_source_component_semantic_identity"] = (
                statement_component_identity
            )
        reviewed_dependency_digests = sorted(
            signature["semantic_dependency_sha256"]
            for signature in reviewed_signatures
            if "semantic_dependency_sha256" in signature
        )
        if reviewed_dependency_digests:
            semantic_identity["reviewed_semantic_dependency_sha256"] = (
                reviewed_dependency_digests
            )
        semantic_id = stable_digest(semantic_identity)
        scoped_context = {
            "schema": SOURCE_RECORD_ITEM_DIGEST_SCHEMA,
            "semantic_id": semantic_id,
            "formalization_scope_sha256": formalization_scope_digest,
        }
        if scoped_context_pin is not None:
            scoped_context["semantic_context_requirements"] = scoped_context_pin
            item["source_record_item_semantic_context_requirements_sha256"] = (
                stable_digest(scoped_context_pin)
            )
        if scoped_ledger_pin is not None:
            scoped_context["source_proof_fidelity_records"] = scoped_ledger_pin
            item["source_record_item_source_proof_fidelity_records_sha256"] = (
                stable_digest(scoped_ledger_pin)
            )
        item["source_record_item_digest_schema"] = SOURCE_RECORD_ITEM_DIGEST_SCHEMA
        item["source_record_item_semantic_id"] = semantic_id
        item["source_record_item_context_sha256"] = stable_digest(scoped_context)
        item["source_record_item_sha256"] = stable_digest(scoped_context)


def source_record_cache_file_identity(root: Path, path: Path) -> dict[str, str]:
    """Return a fail-closed identity for one cache dependency path."""

    try:
        display = repository_relative_path(root, path)
    except (OSError, RuntimeError, ValueError):
        display = str(path)
    if path.exists() and path.is_file():
        return {
            "path": display,
            "sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
            "status": "present",
        }
    return {"path": display, "sha256": "", "status": "missing"}


def _source_record_raw_generation_code_identity(
    *,
    entry_path: Path | None = None,
    repository_root: Path | None = None,
) -> dict[str, str]:
    """Hash the transitive producer closure from repository-relative bytes."""

    root = (repository_root or REPOSITORY_ROOT).resolve()
    entry = (entry_path or Path(__file__)).resolve()
    try:
        entry_relative = entry.relative_to(root).as_posix()
    except (OSError, RuntimeError, ValueError):
        return {
            "path": (
                "skills/econcs-formalizer/scripts/source_record_audit.py"
                "#fresh-raw-generation"
            ),
            "sha256": "",
            "status": "unavailable",
        }

    def read_bytes(relative_path: str) -> bytes | None:
        candidate = root / relative_path
        try:
            return candidate.read_bytes() if candidate.is_file() else None
        except OSError:
            return None

    return raw_generation_code_identity(
        read_bytes,
        entry_path=entry_relative,
        display_path=(
            "skills/econcs-formalizer/scripts/source_record_audit.py"
            "#fresh-raw-generation"
        ),
    )


_UNCACHED_SOURCE_RECORD_RAW_GENERATION_CODE_IDENTITY = (
    _source_record_raw_generation_code_identity
)


@lru_cache(maxsize=8)
def _registered_raw_generation_code_identity(
    engine_tree_sha256: str,
) -> tuple[str, str, str]:
    """Reuse provenance only under one exact clean registered engine tree."""

    # The key is deliberately consumed even though the underlying helper reads
    # the repository. Runtime engine validation proves that every tracked
    # production source has exactly the registered tree bytes. Dirty or
    # unregistered executions bypass this cache below.
    _ = engine_tree_sha256
    identity = _UNCACHED_SOURCE_RECORD_RAW_GENERATION_CODE_IDENTITY()
    return (
        str(identity.get("path") or ""),
        str(identity.get("sha256") or ""),
        str(identity.get("status") or ""),
    )



def source_record_raw_producer_code_identities(
    *,
    transparent_spec_positional_surface: bool = False,
    validated_vocabulary_direct_route_surface: bool = False,
) -> list[dict[str, str]]:
    """Return automatic code identities for the narrow raw-obligation producers.

    Use the repository that loaded this helper, rather than a paper fixture's
    ``root`` argument: cache validity depends on the code actually executing
    the generation pass.  Missing or unparsable producer code remains an
    identity but is rejected by the reuse guard below.

    Every new receipt records the actual marker-bounded producer bytes. The
    feature arguments are retained for callers that calculate the same
    fingerprint shape, but feature-scoped invalidation now belongs entirely to
    the structured `audit_engine_identities` list. Reuse checks the complete
    non-producer fingerprint or independently reproduces every receipt-bound
    semantic identity under the current registered verifier. This avoids
    paper-specific code-hash aliases while keeping exact code provenance on
    every raw receipt.
    """

    producer = _source_record_raw_generation_code_identity
    if producer is _UNCACHED_SOURCE_RECORD_RAW_GENERATION_CODE_IDENTITY:
        try:
            registration = validate_runtime_engine_registration(REPOSITORY_ROOT)
        except EngineRevisionError:
            identity = producer()
        else:
            path, sha256, status = _registered_raw_generation_code_identity(
                registration.engine_tree_sha256
            )
            identity = {"path": path, "sha256": sha256, "status": status}
    else:
        # Preserve explicit test/diagnostic injection and never let an earlier
        # production cache hide it.
        identity = producer()
    identities = [identity]
    for relative_path in SOURCE_RECORD_RAW_PRODUCER_EXTERNAL_CODE_PATHS:
        path = REPOSITORY_ROOT / relative_path
        identities.append(source_record_cache_file_identity(REPOSITORY_ROOT, path))
    # Keep the keyword-only feature inputs intentionally consumed: callers use
    # them to document that the same map-scoped semantic identities were
    # calculated before provenance is attached. They must not select a
    # paper-specific historical hash alias.
    _ = (
        transparent_spec_positional_surface,
        validated_vocabulary_direct_route_surface,
    )
    return sorted(identities, key=lambda identity: identity["path"])


def _source_record_raw_producer_code_identities_are_valid(value: object) -> bool:
    """Validate a producer-code identity list before it can authorize reuse."""

    if not isinstance(value, list) or not value:
        return False
    for identity in value:
        if not isinstance(identity, Mapping) or set(identity) != {
            "path",
            "sha256",
            "status",
        }:
            return False
        if (
            not isinstance(identity.get("path"), str)
            or not str(identity["path"]).strip()
            or not isinstance(identity.get("sha256"), str)
            or not SHA256_RE.fullmatch(str(identity["sha256"]).strip().lower())
            or identity.get("status") != "present"
        ):
            return False
    return True


def source_record_raw_producer_code_identity_matches(
    stored_fingerprint: object,
    current_fingerprint: Mapping[str, Any],
    *,
    repository_root: Path = REPOSITORY_ROOT,
    semantic_reuse: Mapping[str, Any] | None = None,
) -> bool:
    """Return whether a stored raw receipt has current semantic inputs.

    Test-only callers sometimes replace the complete input fingerprint with a
    small fixture.  Such a current fixture has no producer-code field and
    deliberately retains its existing test semantics.  Real fingerprints
    always carry this field. Producer hashes remain forensic provenance, not a
    second semantic validity authority. A differing implementation can reuse a
    receipt when either every non-producer input is exact or the current
    verifier has reproduced every receipt-bound semantic identity and the
    separately owned current gates cover map/status/fidelity coordinates. The
    executing engine must also be clean, committed, and registered. Actual
    audit semantics remain pinned by the structured protocol, source inputs,
    and feature identities inside that projection.
    """

    current_identities = current_fingerprint.get("raw_producer_code_identities")
    current_schema = current_fingerprint.get("raw_producer_code_identity_schema")
    if current_identities is None and current_schema is None:
        return (
            isinstance(stored_fingerprint, Mapping)
            and dict(stored_fingerprint) == dict(current_fingerprint)
        )
    if current_schema != SOURCE_RECORD_RAW_PRODUCER_CODE_IDENTITY_SCHEMA:
        return False
    if not _source_record_raw_producer_code_identities_are_valid(current_identities):
        return False
    if (
        isinstance(stored_fingerprint, Mapping)
        and stored_fingerprint.get("raw_producer_code_identity_schema")
        == SOURCE_RECORD_RAW_PRODUCER_CODE_IDENTITY_SCHEMA
        and _source_record_raw_producer_code_identities_are_valid(
            stored_fingerprint.get("raw_producer_code_identities")
        )
        and dict(stored_fingerprint) == dict(current_fingerprint)
    ):
        return True
    exact_nonproducer = (
        fingerprint_without_raw_producer_provenance(stored_fingerprint)
        == fingerprint_without_raw_producer_provenance(current_fingerprint)
    )
    semantic_noncontainer = (
        isinstance(semantic_reuse, Mapping)
        and semantic_reuse.get("schema") == 1
        and semantic_reuse.get("policy") == SOURCE_RECORD_SEMANTIC_REUSE_POLICY
        and semantic_reuse.get("paper") == current_fingerprint.get("paper")
        and semantic_reuse.get("current") is True
        and isinstance(semantic_reuse.get("reviewed_declaration_count"), int)
        and int(semantic_reuse.get("reviewed_declaration_count")) > 0
        and SHA256_RE.fullmatch(
            str(semantic_reuse.get("semantic_identity_sha256") or "")
        )
        and semantic_fingerprint_matches(stored_fingerprint, current_fingerprint)
    )
    if not (exact_nonproducer or semantic_noncontainer):
        return False
    # Implementation-only drift is never authorized from a dirty or
    # unregistered engine. The ledger authenticates the current verifier as an
    # operational matter; it does not create an engine-pair evidence bridge.
    try:
        validate_runtime_engine_registration(repository_root)
    except EngineRevisionError:
        return False
    return True


def source_record_dependency_identities(
    root: Path,
    paper_dir: Path,
    interface_path: Path,
    *,
    lean_import_closure: SourceRecordLeanImportClosure | None = None,
) -> list[dict[str, str]]:
    """Hash exactly the configured review interface's repository closure.

    Loose, alternate, and scratch modules beside ``PaperInterface.lean`` are
    useful ambient-worktree diagnostics, but they are not imported semantics.
    They therefore cannot affect a canonical raw receipt or its cache key.
    """

    try:
        if lean_import_closure is None:
            # Retained only for non-crediting diagnostics and small unit
            # fixtures. Every CLI cache, identity, and generation path passes
            # a Lean-owned closure explicitly.
            closure = {
                interface_path.resolve(),
                *diagnostic_imported_paper_lean_files(root, [interface_path]),
            }
        else:
            paper_interface_import_closure_lean_files(
                root,
                interface_path,
                lean_import_closure=lean_import_closure,
            )
            return sorted(
                (
                    {
                        "path": str(raw["path"]),
                        "sha256": str(raw["sha256"]),
                        "status": "present",
                    }
                    for raw in lean_import_closure.record.get("sources", [])
                    if isinstance(raw, Mapping)
                ),
                key=lambda identity: identity["path"],
            )
    except (OSError, RuntimeError, ValueError):
        # A malformed import closure must make the fingerprint differ from a
        # successfully computed one rather than silently reusing an old audit.
        return [{"path": "<unavailable Lean dependency closure>", "sha256": "", "status": "unavailable"}]
    return sorted(
        (source_record_cache_file_identity(root, path) for path in closure),
        key=lambda identity: identity["path"],
    )


def source_record_engine_identities(
    root: Path,
    *,
    paper_dir: Path | None = None,
    recursive_field_payload_surface: bool | None = None,
    lean_import_closure: SourceRecordLeanImportClosure | None = None,
    raw_audit_payload: Mapping[str, Any] | None = None,
) -> list[dict[str, str]]:
    """Return explicit semantic versions for raw-surface producers.

    ``root`` remains part of the public helper signature for callers and tests,
    but raw-surface producer versions deliberately do not hash implementation
    files.  A file-level hash conflates a harmless consumer/diagnostic edit
    with a change to generated obligations and turns every paper into an
    unnecessary Lean rescan.
    """

    identities = [
        {"path": path, "surface_semantic_version": version}
        for path, version in sorted(SOURCE_RECORD_SURFACE_ENGINE_VERSIONS.items())
    ]
    if paper_dir is not None:
        identities.extend(
            source_record_feature_scoped_engine_identities(
                root,
                paper_dir,
                lean_import_closure=lean_import_closure,
                raw_audit_payload=raw_audit_payload,
            )
        )
    if (
        recursive_field_payload_surface is True
        and RECURSIVE_FIELD_PAYLOAD_SAFETY_SURFACE_ENGINE_IDENTITY not in identities
    ):
        identities.append(dict(RECURSIVE_FIELD_PAYLOAD_SAFETY_SURFACE_ENGINE_IDENTITY))
    return sorted(identities, key=lambda identity: identity["path"])


def recursive_field_source_scope_engine_identities(
    source_proof_fidelity: Mapping[str, Any] | None,
) -> list[dict[str, str]]:
    """Return the opt-in producer identity for exact recursive field scopes.

    The feature changes only the generated route surface for papers that
    declare ``recursive_field_source_scope``.  Keeping this identity separate
    avoids invalidating raw receipts for papers that have only aggregate
    recursive fields.
    """

    if not isinstance(source_proof_fidelity, Mapping):
        return []
    conventions = source_proof_fidelity.get("model_conventions")
    if not isinstance(conventions, list):
        return []
    if any(
        isinstance(convention, Mapping)
        and "recursive_field_source_scope" in convention
        for convention in conventions
    ):
        return [dict(RECURSIVE_FIELD_SOURCE_SCOPE_SURFACE_ENGINE_IDENTITY)]
    return []


def _source_record_source_artifact_values(value: object) -> list[str]:
    """Collect declared source-artifact paths and byte-pinned anchor paths."""

    values: list[str] = []
    if isinstance(value, list):
        for child in value:
            values.extend(_source_record_source_artifact_values(child))
        return values
    if not isinstance(value, dict):
        return values
    for field in ("source_artifact_path", "canonical_source_artifact_path"):
        raw = value.get(field)
        if isinstance(raw, str) and raw.strip():
            values.append(raw.strip())
    anchors = value.get("source_anchor_evidence")
    if isinstance(anchors, list):
        for anchor in anchors:
            if not isinstance(anchor, dict):
                continue
            raw = anchor.get("path")
            if isinstance(raw, str) and raw.strip():
                values.append(raw.strip())
    for child in value.values():
        if isinstance(child, (dict, list)):
            values.extend(_source_record_source_artifact_values(child))
    return values


def _resolve_source_record_artifact_path(
    root: Path, paper_dir: Path, raw_path: str
) -> Path | None:
    """Resolve a declared source artifact under the repository without escape."""

    candidate = Path(raw_path)
    candidates = [candidate] if candidate.is_absolute() else [paper_dir / candidate, root / candidate]
    for raw_candidate in candidates:
        try:
            resolved = raw_candidate.resolve()
            resolved.relative_to(root.resolve())
        except (OSError, RuntimeError, ValueError):
            continue
        if resolved.exists() and resolved.is_file():
            return resolved
    return None


def source_record_feature_source_texts(
    root: Path,
    paper_dir: Path,
    statement_map: Mapping[str, Any],
) -> tuple[str, ...]:
    """Return the current canonical text artifact for selector features.

    The source-index selector reads the map's byte-pinned canonical artifact;
    it does not interpret every supporting file or anchor path as a complete
    paper.  Mirror that boundary here so a feature identity is neither
    name-based nor spuriously triggered by an unrelated cited text.
    """

    raw_path = statement_map.get("source_artifact_path")
    raw_digest = statement_map.get("source_artifact_sha256")
    if not isinstance(raw_path, str) or not raw_path.strip():
        return ()
    if not isinstance(raw_digest, str) or not SHA256_RE.fullmatch(raw_digest.strip()):
        return ()
    resolved = _resolve_source_record_artifact_path(root, paper_dir, raw_path.strip())
    if resolved is None or resolved.suffix.lower() not in {".tex", ".txt"}:
        return ()
    try:
        raw_bytes = resolved.read_bytes()
    except OSError:
        return ()
    if hashlib.sha256(raw_bytes).hexdigest() != raw_digest.strip().lower():
        return ()
    try:
        text = raw_bytes.decode("utf-8")
    except UnicodeDecodeError:
        return ()
    normalized = text.replace("\r\n", "\n").replace("\r", "\n")
    return (normalized,) if normalized else ()


def has_exact_schema_two_semantic_model_dimension_configuration(
    status: Mapping[str, Any],
) -> bool:
    """Whether the current status requests precisely the schema-2 surface."""

    review_surface = status.get("review_surface")
    if not isinstance(review_surface, Mapping):
        return False
    review = review_surface.get("semantic_model_review")
    if not isinstance(review, Mapping) or review.get("schema") != (
        SEMANTIC_MODEL_REVIEW_SCHEMA
    ):
        return False
    raw_dimensions = review.get("required_dimensions")
    if not isinstance(raw_dimensions, list):
        return False
    dimensions = [item.strip() if isinstance(item, str) else "" for item in raw_dimensions]
    return (
        len(dimensions) == len(SEMANTIC_MODEL_DIMENSION_ORDER)
        and len(set(dimensions)) == len(dimensions)
        and set(dimensions) == set(SEMANTIC_MODEL_DIMENSION_ORDER)
    )


def source_map_has_selected_direct_semantic_route(
    statement_map: Mapping[str, Any],
) -> bool:
    """Check the source-selected direct-route condition without Lean names.

    The route fields are structured source-map contracts.  Source selection is
    performed first by the ordinary/deep presentation policy; this helper does
    not inspect map keys or infer a route from a declaration's spelling.
    """

    if not isinstance(statement_map, dict):
        return False
    raw_items = statement_map.get("items")
    if not isinstance(raw_items, dict):
        return False
    mode, mode_error = source_coverage_mode_from_map(statement_map)
    if mode_error:
        return False
    selected_items = filter_source_map_items_for_coverage(
        raw_items,
        mode,
        declared_environment_kinds=source_named_result_environment_kinds_from_map(
            statement_map
        ),
    )
    presentation_aliases, _presentation_alias_errors = source_presentation_aliases(
        raw_items
    )
    semantic_contract_schema = statement_map.get("semantic_contract_schema")
    for raw_source_key, source_item in selected_items.items():
        source_key = str(raw_source_key).strip()
        if (
            not source_key
            or source_key in presentation_aliases
            or source_item.get("claim_bearing") is False
            or not str(source_item.get("source_location") or "").strip()
        ):
            continue
        raw_contract = source_item.get("semantic_contract")
        if raw_contract is not None:
            # Semantic contracts are authoritative.  Their route is only a
            # direct source-model route when both sides of the explicit pair
            # are present under the declared contract schema.
            if (
                not isinstance(raw_contract, Mapping)
                or source_item.get("claim_bearing") is not True
                or semantic_contract_schema not in SEMANTIC_CONTRACT_SCHEMAS
                or not str(raw_contract.get("evidence_mode") or "").strip()
                or not str(raw_contract.get("semantic_shape") or "").strip()
            ):
                continue
            evidence = semantic_contract_fully_qualified_identity(
                raw_contract.get("evidence_declaration")
            )
            spec = semantic_contract_fully_qualified_identity(
                raw_contract.get("spec_declaration")
            )
            if evidence and spec and evidence != spec:
                return True
            continue
        for field in EXPLICIT_DIRECT_SOURCE_ROUTE_FIELDS:
            routes = source_item.get(field)
            if not isinstance(routes, list):
                continue
            if any(semantic_contract_fully_qualified_identity(route) for route in routes):
                return True
    return False


def _source_record_feature_raw_audit_payload(
    paper_dir: Path,
    *,
    raw_audit_payload: Mapping[str, Any] | None = None,
) -> Mapping[str, Any]:
    """Return one caller-owned raw snapshot or load the canonical receipt.

    The optional snapshot is limited to a single identity calculation.  It is
    intentionally not a process cache: callers that need TOCTOU protection
    still own the final raw-byte comparison after every consumer has finished.
    """

    if raw_audit_payload is not None:
        return raw_audit_payload
    return load_json_object(canonical_source_record_audit_path(paper_dir))


def source_record_raw_has_empty_direct_semantic_model_dimensions(
    paper_dir: Path,
    *,
    raw_audit_payload: Mapping[str, Any] | None = None,
) -> bool:
    """Recognize only the emitted empty-dimension migration defect."""

    payload = _source_record_feature_raw_audit_payload(
        paper_dir, raw_audit_payload=raw_audit_payload
    )
    raw_items = payload.get("semantic_model_items")
    if not isinstance(raw_items, list):
        return False
    for item in raw_items:
        if not isinstance(item, Mapping) or item.get("dimensions") != []:
            continue
        for association_field, direct_roles in (
            ("source_statement_association", {EXPLICIT_DIRECT_SOURCE_ROUTE_ROLE}),
            ("semantic_contract_source_association", {"direct_evidence", "transparent_spec"}),
        ):
            association = item.get(association_field)
            if not isinstance(association, Mapping):
                continue
            if str(association.get("role") or "").strip() not in direct_roles:
                continue
            source_items = association.get("source_item_identities")
            if isinstance(source_items, list) and source_items:
                return True
    return False


def source_record_raw_has_semantic_model_dimension_configuration_identity(
    paper_dir: Path,
    *,
    raw_audit_payload: Mapping[str, Any] | None = None,
) -> bool:
    """Return whether a replacement receipt already carries the migration ID."""

    payload = _source_record_feature_raw_audit_payload(
        paper_dir, raw_audit_payload=raw_audit_payload
    )
    fingerprint = payload.get("source_record_input_fingerprint")
    if not isinstance(fingerprint, Mapping):
        return False
    identities = fingerprint.get("audit_engine_identities")
    if not isinstance(identities, list):
        return False
    return any(
        identity == SEMANTIC_MODEL_DIMENSION_CONFIGURATION_SURFACE_ENGINE_IDENTITY
        for identity in identities
    )


def semantic_model_dimension_configuration_migration_is_active(
    paper_dir: Path,
    statement_map: Mapping[str, Any],
    *,
    raw_audit_payload: Mapping[str, Any] | None = None,
) -> bool:
    """Activate the migration identity only for the observed defective surface.

    The direct route and exact schema-2 configuration are current semantic
    inputs.  The raw receipt makes this a one-time migration rather than a
    repository-wide producer-version bump: an old empty-dimensional receipt
    cannot cache-hit, while a corrected receipt remains stable only after it
    has recorded the same explicit identity.
    """

    status = load_json_object(paper_dir / "status.json")
    if not has_exact_schema_two_semantic_model_dimension_configuration(status):
        return False
    if not source_map_has_selected_direct_semantic_route(statement_map):
        return False
    return (
        source_record_raw_has_empty_direct_semantic_model_dimensions(
            paper_dir, raw_audit_payload=raw_audit_payload
        )
        or source_record_raw_has_semantic_model_dimension_configuration_identity(
            paper_dir, raw_audit_payload=raw_audit_payload
        )
    )


def _legacy_expanded_relation_valued_state_transition_type(type_text: object) -> bool:
    """Conservatively recognize a prior emitted endorelation type surface.

    This exists only to select old receipts for reissue.  The current audit
    trigger itself comes from Lean's canonical elaborated type manifest.  The
    legacy selector compares arrow structure and never a record, field,
    function, or declaration name.
    """

    current = strip_outer_group(normalize_ws(str(type_text or "")))
    domains: list[str] = []
    while (split := split_top_level_arrow(current)) is not None:
        domain, current = split
        domains.append(canonical_type(strip_outer_group(domain)))
        current = strip_outer_group(current)
    return bool(
        len(domains) >= 2
        and canonical_type(current) == "Prop"
        and domains[-1] == domains[-2]
    )


def source_record_raw_has_execution_state_refinement_surface(
    paper_dir: Path,
    *,
    raw_audit_payload: Mapping[str, Any] | None = None,
) -> bool:
    """Whether an older source-routed receipt lacks the new structural trigger."""

    payload = _source_record_feature_raw_audit_payload(
        paper_dir, raw_audit_payload=raw_audit_payload
    )
    fingerprint = payload.get("source_record_input_fingerprint")
    if isinstance(fingerprint, Mapping):
        identities = fingerprint.get("audit_engine_identities")
        if isinstance(identities, list) and any(
            identity == EXECUTION_STATE_REFINEMENT_SURFACE_ENGINE_IDENTITY
            for identity in identities
        ):
            return True

    raw_items = payload.get("semantic_model_items")
    if not isinstance(raw_items, list):
        return False
    for item in raw_items:
        if not isinstance(item, Mapping):
            continue
        if not semantic_model_item_has_explicit_source_route(item):
            continue
        flags = item.get("semantic_shape_flags")
        if isinstance(flags, Mapping) and (
            flags.get("elaborated_execution_state_refinement_surface") is True
            or flags.get(
                "elaborated_execution_state_refinement_scan_incomplete"
            )
            is True
        ):
            continue
        surface = item.get("expanded_lean_surface")
        if not isinstance(surface, Mapping):
            continue
        type_surfaces: list[str] = []
        for key in (
            "binder_domains",
            "record_parameter_types",
            "record_field_types",
        ):
            values = surface.get(key)
            if not isinstance(values, list):
                continue
            type_surfaces.extend(
                str(value.get("expanded_type") or "")
                for value in values
                if isinstance(value, Mapping)
            )
        terminal = surface.get("terminal_result")
        if isinstance(terminal, Mapping):
            type_surfaces.append(str(terminal.get("expanded_type") or ""))
        has_refl_trans_gen = any(
            re.search(r"(?<![\w.])Relation\.ReflTransGen(?![\w.])", value)
            for value in type_surfaces
        )
        has_relation_valued_transition = any(
            _legacy_expanded_relation_valued_state_transition_type(value)
            for value in type_surfaces
        )
        if has_refl_trans_gen and has_relation_valued_transition:
            return True
    return False


def source_record_raw_has_proposition_classified_data_terminal(
    paper_dir: Path,
    *,
    raw_audit_payload: Mapping[str, Any] | None = None,
) -> bool:
    """Recognize the emitted terminal-sort classification defect, not names.

    The predicate reads the prior generated field type and its serialized
    semantic kind. It deliberately does not inspect a declaration, record, or
    binder spelling: only a proposition label on a structurally known data
    terminal can activate the narrowly scoped migration.
    """

    payload = _source_record_feature_raw_audit_payload(
        paper_dir, raw_audit_payload=raw_audit_payload
    )
    dependencies = payload.get("conclusion_dependency_items")
    if not isinstance(dependencies, list):
        return False
    for dependency in dependencies:
        if not isinstance(dependency, Mapping):
            continue
        fields = dependency.get("conclusion_fields")
        if not isinstance(fields, list):
            continue
        for field in fields:
            if not isinstance(field, Mapping):
                continue
            if str(field.get("semantic_kind") or "").strip() != "proposition":
                continue
            type_text = field.get("type")
            if isinstance(type_text, str) and is_known_data_terminal_type(type_text):
                return True
    return False


def source_record_raw_has_data_terminal_classification_identity(
    paper_dir: Path,
    *,
    raw_audit_payload: Mapping[str, Any] | None = None,
) -> bool:
    """Return whether a corrected replacement receipt retains this migration."""

    payload = _source_record_feature_raw_audit_payload(
        paper_dir, raw_audit_payload=raw_audit_payload
    )
    fingerprint = payload.get("source_record_input_fingerprint")
    if not isinstance(fingerprint, Mapping):
        return False
    identities = fingerprint.get("audit_engine_identities")
    return isinstance(identities, list) and any(
        identity == DATA_TERMINAL_CLASSIFICATION_SURFACE_ENGINE_IDENTITY
        for identity in identities
    )


def data_terminal_classification_migration_is_active(
    paper_dir: Path,
    *,
    raw_audit_payload: Mapping[str, Any] | None = None,
) -> bool:
    """Keep the data-terminal repair sticky only for affected raw surfaces."""

    return (
        source_record_raw_has_proposition_classified_data_terminal(
            paper_dir, raw_audit_payload=raw_audit_payload
        )
        or source_record_raw_has_data_terminal_classification_identity(
            paper_dir, raw_audit_payload=raw_audit_payload
        )
    )


def conditional_constructor_antecedent_surface_identity(
    field: Mapping[str, Any],
) -> str | None:
    """Return the name-independent identity of one synthetic route antecedent.

    ``ConstructorInput`` is an audit-generated origin marker, not a Lean
    declaration.  Its field and path strings embed the helper declaration, so
    they must not participate in this migration matcher.  The source-facing
    semantic surface is the alpha-canonical proposition type; the origin keeps
    an ordinary record field of the same type out of this narrow migration.
    """

    structure = str(field.get("structure") or "").strip()
    type_text = str(field.get("type") or "").strip()
    if structure != "ConstructorInput" or not type_text:
        return None
    return stable_digest(
        {
            "origin": "conditional_constructor_input",
            "type": alpha_canonical_type(type_text),
        }
    )


def source_record_raw_has_promoted_conditional_constructor_antecedent(
    paper_dir: Path,
    *,
    raw_audit_payload: Mapping[str, Any] | None = None,
) -> bool:
    """Whether a prior raw globally promoted a hypothetical route antecedent.

    Candidate antecedents belong to a route only after the sidecar selects that
    exact route.  Older raws copied every such candidate field into
    ``recursive_field_items``.  Compare only the generated synthetic origin
    and alpha-canonical proposition type, so helper renaming cannot affect the
    migration and ordinary record fields remain outside it.
    """

    payload = _source_record_feature_raw_audit_payload(
        paper_dir, raw_audit_payload=raw_audit_payload
    )
    raw_fields = payload.get("recursive_field_items")
    dependencies = payload.get("conclusion_dependency_items")
    if not isinstance(raw_fields, list) or not isinstance(dependencies, list):
        return False
    recursive_surfaces = {
        identity
        for raw_field in raw_fields
        if isinstance(raw_field, Mapping)
        and (
            identity := conditional_constructor_antecedent_surface_identity(raw_field)
        )
        is not None
    }
    if not recursive_surfaces:
        return False
    candidate_surfaces: set[str] = set()
    for dependency in dependencies:
        if not isinstance(dependency, Mapping):
            continue
        candidates = dependency.get("conditional_constructors")
        if not isinstance(candidates, list):
            continue
        for candidate in candidates:
            if not isinstance(candidate, Mapping):
                continue
            fields = candidate.get("required_source_antecedent_fields")
            if not isinstance(fields, list):
                continue
            for field in fields:
                if not isinstance(field, Mapping):
                    continue
                identity = conditional_constructor_antecedent_surface_identity(field)
                if identity is not None:
                    candidate_surfaces.add(identity)
    return bool(recursive_surfaces & candidate_surfaces)


def source_record_raw_has_conditional_constructor_antecedent_diagnostic_identity(
    paper_dir: Path,
    *,
    raw_audit_payload: Mapping[str, Any] | None = None,
) -> bool:
    """Whether a replacement receipt already carries this sticky migration ID."""

    payload = _source_record_feature_raw_audit_payload(
        paper_dir, raw_audit_payload=raw_audit_payload
    )
    fingerprint = payload.get("source_record_input_fingerprint")
    if not isinstance(fingerprint, Mapping):
        return False
    identities = fingerprint.get("audit_engine_identities")
    return isinstance(identities, list) and any(
        identity == CONDITIONAL_CONSTRUCTOR_ANTECEDENT_DIAGNOSTIC_SURFACE_ENGINE_IDENTITY
        for identity in identities
    )


def conditional_constructor_antecedent_diagnostic_migration_is_active(
    paper_dir: Path,
    *,
    raw_audit_payload: Mapping[str, Any] | None = None,
) -> bool:
    """Keep the route-local-antecedent repair sticky after one replacement scan."""

    return (
        source_record_raw_has_promoted_conditional_constructor_antecedent(
            paper_dir, raw_audit_payload=raw_audit_payload
        )
        or source_record_raw_has_conditional_constructor_antecedent_diagnostic_identity(
            paper_dir, raw_audit_payload=raw_audit_payload
        )
    )


def source_map_uses_explicit_renumbered_presentation_alias(
    statement_map: Mapping[str, Any],
) -> bool:
    """Whether a current map exercises source-explicit label reconciliation.

    This reads only the declared source-presentation relation and its required
    byte-pinned evidence object. It does not infer equivalence from map keys,
    source labels, or Lean routes; the source-content validator separately
    verifies the quoted relation against current source bytes.
    """

    raw_items = statement_map.get("items") if isinstance(statement_map, Mapping) else None
    if not isinstance(raw_items, Mapping):
        return False
    _aliases, alias_errors = source_presentation_aliases(raw_items)
    if alias_errors:
        return False
    for item in raw_items.values():
        if not isinstance(item, Mapping):
            continue
        relation = item.get("source_presentation_alias")
        if not isinstance(relation, Mapping):
            continue
        if (
            relation.get(SOURCE_PRESENTATION_ALIAS_LABEL_RELATION_FIELD)
            != SOURCE_PRESENTATION_ALIAS_EXPLICIT_RENUMBERED_RESTATEMENT
        ):
            continue
        if isinstance(
            relation.get(SOURCE_PRESENTATION_ALIAS_RENUMBERED_EVIDENCE_FIELD),
            Mapping,
        ):
            return True
    return False


def source_map_uses_equality_defined_partition_context(
    statement_map: Mapping[str, Any],
) -> bool:
    """Return whether a map opts into the exact equality-partition review.

    This is a source-map context predicate only.  It neither searches for a
    familiar type/field name nor guesses that any equality-looking Lean type
    represents a partition.  A malformed opt-in remains active here so the
    ordinary context validator can fail closed rather than allowing an old raw
    receipt to cache-hit after the map attempted to add the obligation.
    """

    raw_items = statement_map.get("items") if isinstance(statement_map, Mapping) else None
    if not isinstance(raw_items, Mapping):
        return False
    for raw_item in raw_items.values():
        if not isinstance(raw_item, Mapping):
            continue
        raw_contexts = raw_item.get("semantic_context_requirements")
        if not isinstance(raw_contexts, list):
            continue
        for raw_context in raw_contexts:
            if not isinstance(raw_context, Mapping):
                continue
            if (
                raw_context.get("kind")
                == EQUALITY_DEFINED_PARTITION_CONTEXT_KIND
            ):
                return True
    return False


def source_map_uses_strategic_observation_totality_context(
    statement_map: Mapping[str, Any],
) -> bool:
    """Return whether a map opts into source-game observation totality review.

    This reads only an explicit source-map context. A malformed opt-in remains
    active so a stale raw receipt cannot survive an attempted new obligation;
    it never searches Lean names or source text for game vocabulary.
    """

    raw_items = statement_map.get("items") if isinstance(statement_map, Mapping) else None
    if not isinstance(raw_items, Mapping):
        return False
    for raw_item in raw_items.values():
        if not isinstance(raw_item, Mapping):
            continue
        raw_contexts = raw_item.get("semantic_context_requirements")
        if not isinstance(raw_contexts, list):
            continue
        if any(
            isinstance(raw_context, Mapping)
            and raw_context.get("kind")
            == STRATEGIC_OBSERVATION_TOTALITY_CONTEXT_KIND
            for raw_context in raw_contexts
        ):
            return True
    return False


def source_map_uses_conditioning_information_context(
    statement_map: Mapping[str, Any],
) -> bool:
    """Return whether a map requests source-vs-Lean information-set review.

    This examines only a declared source semantic context. A malformed opt-in
    remains active so a stale raw receipt cannot bypass the source-side schema
    check. It deliberately does not search source text or Lean names for words
    such as posterior, belief, conditional, or kernel.
    """

    raw_items = statement_map.get("items") if isinstance(statement_map, Mapping) else None
    if not isinstance(raw_items, Mapping):
        return False
    for raw_item in raw_items.values():
        if not isinstance(raw_item, Mapping):
            continue
        raw_contexts = raw_item.get("semantic_context_requirements")
        if not isinstance(raw_contexts, list):
            continue
        if any(
            isinstance(raw_context, Mapping)
            and raw_context.get("kind") == CONDITIONING_INFORMATION_CONTEXT_KIND
            for raw_context in raw_contexts
        ):
            return True
    return False


def source_map_uses_source_model_derivation_context(
    statement_map: Mapping[str, Any],
) -> bool:
    """Return whether a map opts into source primitive-to-conclusion review.

    This reads only explicit source-map context. A malformed opt-in remains
    active so a stale raw receipt cannot evade the new guard; it never scans
    Lean names or source prose for words such as cycle, process, trace, or law.
    """

    raw_items = statement_map.get("items") if isinstance(statement_map, Mapping) else None
    if not isinstance(raw_items, Mapping):
        return False
    for raw_item in raw_items.values():
        if not isinstance(raw_item, Mapping):
            continue
        raw_contexts = raw_item.get("semantic_context_requirements")
        if not isinstance(raw_contexts, list):
            continue
        if any(
            isinstance(raw_context, Mapping)
            and raw_context.get("kind") == SOURCE_MODEL_DERIVATION_CONTEXT_KIND
            for raw_context in raw_contexts
        ):
            return True
    return False


def source_map_uses_source_claim_atoms(statement_map: Mapping[str, Any]) -> bool:
    """Whether this map needs the atom-context raw-surface producer.

    Treat malformed opt-in metadata as active too.  Otherwise a paper could
    add an incomplete atom contract and cache-hit a receipt produced before
    atom-level source semantics were part of the review payload.
    """

    return source_claim_atoms_contract_present(statement_map)


def source_map_uses_direct_transparent_spec_contract(
    statement_map: Mapping[str, Any],
) -> bool:
    """Whether a map asks one semantic row to pair direct evidence with a Spec.

    This is a source-map opt-in predicate, not a declaration-name heuristic.
    A malformed paired contract remains active so it cannot reuse a raw
    generated before the paired identity rule was available.
    """

    raw_items = statement_map.get("items") if isinstance(statement_map, Mapping) else None
    if not isinstance(raw_items, Mapping):
        return False
    for raw_item in raw_items.values():
        if not isinstance(raw_item, Mapping) or raw_item.get("claim_bearing") is not True:
            continue
        contract = raw_item.get("semantic_contract")
        if not isinstance(contract, Mapping):
            continue
        if "evidence_declaration" in contract and "spec_declaration" in contract:
            return True
    return False


def source_map_uses_validated_vocabulary_direct_route_association(
    statement_map: Mapping[str, Any],
) -> bool:
    """Whether a map can exercise vocabulary-selected direct provenance.

    This is a conservative, source-map-structural cache trigger.  It does not
    infer anything from a Lean declaration or source-map key: a map must
    explicitly contain a prose-definition/standard-term relation on the same
    non-contract, non-atom item. That relation can change either a newly
    admitted one-route association *or* suppression of an invalid one-to-one
    association for zero/multi-route vocabulary definitions in deep mode.
    Therefore every attempted relation is active, including malformed input;
    a receipt generated before this association lane cannot cache-hit and hide
    a changed validator/error surface.
    """

    raw_items = statement_map.get("items") if isinstance(statement_map, Mapping) else None
    if not isinstance(raw_items, Mapping):
        return False
    for raw_item in raw_items.values():
        if not isinstance(raw_item, Mapping):
            continue
        if raw_item.get("semantic_contract") is not None:
            continue
        if source_claim_atom_authoritative_for_item(statement_map, raw_item):
            continue
        has_vocabulary_relation = any(
            field in raw_item
            for field in (
                SOURCE_PROSE_DEFINITION_RECONCILIATION_FIELD,
                SOURCE_STANDARD_TERM_INTERPRETATION_FIELD,
            )
        )
        if not has_vocabulary_relation:
            continue
        return True
    return False


def source_record_raw_has_recursive_field_payload_surface(
    paper_dir: Path,
    *,
    raw_audit_payload: Mapping[str, Any] | None = None,
) -> bool:
    """Whether a raw receipt exposes a recursive field surface.

    This is deliberately based on generated item structure, not a record,
    declaration, or field name.  A pre-payload-safety raw with any recursive
    field item must be regenerated; a paper with no such surface keeps its
    prior aggregate reuse eligibility.
    """

    payload = _source_record_feature_raw_audit_payload(
        paper_dir, raw_audit_payload=raw_audit_payload
    )
    fields = payload.get("recursive_field_items")
    if isinstance(fields, list) and any(isinstance(field, Mapping) for field in fields):
        return True
    semantic_items = payload.get("semantic_model_items")
    if isinstance(semantic_items, list) and any(
        isinstance(item, Mapping)
        and isinstance(item.get("record_input_bindings"), list)
        and bool(item.get("record_input_bindings"))
        for item in semantic_items
    ):
        # A prior parser may have missed all recursive fields while still
        # proving that the current review surface has a record carrier.  That
        # structural raw signal is enough to require the one-time payload
        # safety producer refresh without looking at a record/binder name.
        return True
    fingerprint = payload.get("source_record_input_fingerprint")
    identities = (
        fingerprint.get("audit_engine_identities")
        if isinstance(fingerprint, Mapping)
        else None
    )
    return isinstance(identities, list) and any(
        identity == RECURSIVE_FIELD_PAYLOAD_SAFETY_SURFACE_ENGINE_IDENTITY
        for identity in identities
    )


def source_record_current_has_record_constructor_surface(
    root: Path,
    paper_dir: Path,
    *,
    lean_import_closure: SourceRecordLeanImportClosure | None = None,
) -> bool:
    """Whether the current review import closure contains a record/class.

    This cache-selection check is deliberately sourced from the current Lean
    closure, never from `recursive_field_count` in a prior raw receipt.  A
    parser bug can make that historical count zero, notably by skipping every
    parenthesized stored field.  Any unreadable or malformed closure fails
    closed so it cannot preserve such a receipt.
    """

    try:
        status_path = paper_dir / "status.json"
        interface_path = review_source_path(root, paper_dir, status_path)
        if not interface_path.is_file():
            return True
        if lean_import_closure is None:
            # Diagnostic compatibility only. Canonical callers supply the
            # same Lean-authored receipt used by fingerprinting and parsing.
            closure = {interface_path.resolve()}
            closure.update(
                diagnostic_imported_paper_lean_files(root, [interface_path])
            )
        else:
            closure = set(
                paper_interface_import_closure_lean_files(
                    root,
                    interface_path,
                    lean_import_closure=lean_import_closure,
                )
            )
            source_text = source_record_lean_import_closure_source_text(
                lean_import_closure
            )
        for lean_file in closure:
            text = (
                read_text(lean_file)
                if lean_import_closure is None
                else source_text[lean_file.resolve()]
            )
            if RECORD_OR_CLASS_TOKEN_RE.search(mask_lean_comments(text)):
                return True
    except (OSError, RuntimeError, UnicodeError, ValueError, json.JSONDecodeError):
        return True
    return False


def source_record_feature_scoped_engine_identities(
    root: Path,
    paper_dir: Path,
    *,
    lean_import_closure: SourceRecordLeanImportClosure | None = None,
    raw_audit_payload: Mapping[str, Any] | None = None,
) -> list[dict[str, str]]:
    """Return producer identities only for exercised source-selection features.

    ``raw_audit_payload`` is a caller-owned immutable snapshot for one
    identity calculation.  It avoids reparsing the same canonical receipt for
    each sticky migration check; callers retain any final TOCTOU byte check.
    """

    statement_map = load_json_object(paper_dir / "audit" / "paper_statement_map.json")
    raw_items = statement_map.get("items") if isinstance(statement_map, Mapping) else None
    identities: list[dict[str, str]] = []
    if (
        source_record_current_has_record_constructor_surface(
            root,
            paper_dir,
            lean_import_closure=lean_import_closure,
        )
        or source_record_raw_has_recursive_field_payload_surface(
            paper_dir, raw_audit_payload=raw_audit_payload
        )
    ):
        identities.append(dict(RECURSIVE_FIELD_PAYLOAD_SAFETY_SURFACE_ENGINE_IDENTITY))
    if data_terminal_classification_migration_is_active(
        paper_dir, raw_audit_payload=raw_audit_payload
    ):
        identities.append(dict(DATA_TERMINAL_CLASSIFICATION_SURFACE_ENGINE_IDENTITY))
    if conditional_constructor_antecedent_diagnostic_migration_is_active(
        paper_dir, raw_audit_payload=raw_audit_payload
    ):
        identities.append(
            dict(CONDITIONAL_CONSTRUCTOR_ANTECEDENT_DIAGNOSTIC_SURFACE_ENGINE_IDENTITY)
        )
    if not isinstance(raw_items, Mapping):
        return identities
    if source_map_uses_source_claim_atoms(statement_map):
        identities.append(dict(SOURCE_CLAIM_ATOM_CONTEXT_SURFACE_ENGINE_IDENTITY))
    if source_map_uses_direct_transparent_spec_contract(statement_map):
        identities.append(
            dict(DIRECT_TRANSPARENT_SPEC_ROOT_IDENTITY_SURFACE_ENGINE_IDENTITY)
        )
    if source_map_uses_validated_vocabulary_direct_route_association(statement_map):
        identities.append(
            dict(VALIDATED_VOCABULARY_DIRECT_ROUTE_ASSOCIATION_SURFACE_ENGINE_IDENTITY)
        )
    if source_map_uses_conditional_antecedent_subpart_selection(
        statement_map,
        source_texts=source_record_feature_source_texts(root, paper_dir, statement_map),
    ):
        identities.append(dict(CONDITIONAL_ANTECEDENT_SUBPART_SURFACE_ENGINE_IDENTITY))
    if semantic_model_dimension_configuration_migration_is_active(
        paper_dir, statement_map, raw_audit_payload=raw_audit_payload
    ):
        identities.append(
            dict(SEMANTIC_MODEL_DIMENSION_CONFIGURATION_SURFACE_ENGINE_IDENTITY)
        )
    if source_record_raw_has_execution_state_refinement_surface(
        paper_dir, raw_audit_payload=raw_audit_payload
    ):
        identities.append(dict(EXECUTION_STATE_REFINEMENT_SURFACE_ENGINE_IDENTITY))
    if source_map_uses_explicit_renumbered_presentation_alias(statement_map):
        identities.append(dict(RENUMBERED_PRESENTATION_ALIAS_SURFACE_ENGINE_IDENTITY))
    if source_map_uses_equality_defined_partition_context(statement_map):
        identities.append(
            dict(EQUALITY_DEFINED_PARTITION_CONTEXT_SURFACE_ENGINE_IDENTITY)
        )
    if source_map_uses_strategic_observation_totality_context(statement_map):
        identities.append(
            dict(STRATEGIC_OBSERVATION_TOTALITY_CONTEXT_SURFACE_ENGINE_IDENTITY)
        )
    if source_map_uses_conditioning_information_context(statement_map):
        identities.append(dict(CONDITIONING_INFORMATION_CONTEXT_SURFACE_ENGINE_IDENTITY))
    if source_map_uses_source_model_derivation_context(statement_map):
        identities.append(dict(SOURCE_MODEL_DERIVATION_CONTEXT_SURFACE_ENGINE_IDENTITY))
    return sorted(identities, key=lambda identity: identity["path"])


def source_record_source_artifact_identities(
    root: Path, paper_dir: Path
) -> list[dict[str, str]]:
    """Hash every declared source artifact used to interpret the current map."""

    statement_map = load_json_object(paper_dir / "audit" / "paper_statement_map.json")
    raw_paths = sorted(set(_source_record_source_artifact_values(statement_map)))
    identities: list[dict[str, str]] = []
    for raw_path in raw_paths:
        resolved = _resolve_source_record_artifact_path(root, paper_dir, raw_path)
        if resolved is None:
            identities.append(
                {"path": raw_path, "sha256": "", "status": "unavailable"}
            )
        else:
            identities.append(source_record_cache_file_identity(root, resolved))
    return sorted(identities, key=lambda identity: identity["path"])


def paper_statement_map_cache_receipts(paper_dir: Path) -> tuple[str, str]:
    """Return full archival and narrow semantic receipts for the current map.

    The full byte hash remains the raw audit's provenance record.  The second
    receipt is used only for cache eligibility and excludes the explicitly
    administrative direct source-item metadata defined in
    ``source_coverage_scope``.  A malformed map gets no semantic receipt and
    therefore cannot take the administrative cache path.
    """

    map_path = paper_dir / "audit" / "paper_statement_map.json"
    try:
        contents = map_path.read_bytes()
    except OSError:
        return "", ""
    full_sha256 = hashlib.sha256(contents).hexdigest()
    try:
        payload = json.loads(contents)
    except json.JSONDecodeError:
        return full_sha256, ""
    return (
        full_sha256,
        source_map_cache_semantic_sha256(payload) if isinstance(payload, dict) else "",
    )


def source_record_legacy_v9_protocol_fingerprint(
    current_fingerprint: Mapping[str, Any], paper_dir: Path
) -> dict[str, Any] | None:
    """Reconstruct the immediately preceding monolithic protocol cache key.

    This compatibility projection is intentionally current-only: both its map
    receipt and protocol pin use the exact current whole protocol.  It cannot
    carry a schema-9 raw across any protocol edit, and the ordinary producer
    code identity check still runs before this projection can authorize reuse.
    """

    try:
        statement_map = json.loads(
            (paper_dir / "audit" / "paper_statement_map.json").read_text(
                encoding="utf-8"
            )
        )
    except (OSError, UnicodeDecodeError, json.JSONDecodeError):
        return None
    if not isinstance(statement_map, Mapping):
        return None
    legacy_map_digest = legacy_source_map_cache_semantic_sha256(statement_map)
    if not SHA256_RE.fullmatch(legacy_map_digest):
        return None
    legacy = dict(current_fingerprint)
    legacy["schema"] = 9
    legacy.pop(FORMALIZATION_COVERAGE_PROTOCOL_FIELD, None)
    legacy["formalization_protocol_sha256"] = formalization_protocol_digest()
    legacy["source_record_policy_version"] = SOURCE_RECORD_PROMPT_VERSION
    legacy["paper_statement_map_semantic_sha256"] = legacy_map_digest
    return legacy


def source_record_status_control_projection(
    paper_dir: Path,
    status_path: Path,
    status: Mapping[str, Any],
) -> dict[str, Any]:
    """Return only status controls that alter the generated raw surface.

    The aggregate source-record scan has two deliberately separate lanes.
    This projection binds configuration that changes generated review rows,
    auxiliary reachability, semantic-model obligations, or corrected-target
    selection.  Statement/coverage LLM policies and their sidecar locations do
    *not* belong here: saved direct-statement-ledger suppression is revalidated
    monotonically without Lean before a raw receipt is reused.  Rehashing those
    dynamic review policies would therefore turn an otherwise harmless audit
    or sidecar maintenance edit into an unnecessary raw scan.

    The values below are effective parser outputs where possible.  This avoids
    treating duplicate list entries, ordering-only JSON formatting, or ignored
    explanatory metadata as mathematical input while retaining every control
    consumed by the raw generator.  No declaration, map key, or function name
    is used as a semantic equivalence shortcut.
    """

    review_surface = status.get("review_surface")
    semantic_dimensions, semantic_errors = semantic_model_review_config(status_path)
    explicit_source_targets, explicit_source_target_errors = (
        explicit_source_target_declarations_for_semantic_review(status_path)
    )
    scope_targets, scope_target_errors = (
        formalization_scope_target_declarations_for_semantic_review(status_path)
    )
    if isinstance(review_surface, Mapping):
        quarantine_configuration: dict[str, Any] = {
            # These source reasons are generated auxiliary-routing evidence,
            # not display-only status prose.  Preserve their literal values.
            "quarantined_auxiliary_reason": review_surface.get(
                "quarantined_auxiliary_reason"
            ),
            "quarantined_auxiliary_source_reasons": review_surface.get(
                "quarantined_auxiliary_source_reasons"
            ),
        }
        review_surface_kind = "object"
    else:
        # The routing parser distinguishes an absent/non-object review surface
        # from an object with empty effective rows.  Keep that fail-closed
        # configuration state without serializing unrelated malformed data.
        quarantine_configuration = {"review_surface_kind": "not_object"}
        review_surface_kind = "not_object"

    return {
        "schema": 1,
        # The status label governs source-context validation and partial-only
        # closeout projections even when all listed rows are unchanged.
        "status": str(status.get("status") or "").strip(),
        "review_surface_kind": review_surface_kind,
        # The configured assumption file controls which declarations are
        # independently scanned as assumption support.  Retain this routing
        # choice in the narrow raw-audit identity: a legacy `Assumptions.lean`
        # must not remain part of the current review merely because it still
        # exists beside a paper-facing interface.
        "assumption_source_file": (
            review_surface.get("assumption_source_file")
            if isinstance(review_surface, Mapping)
            else None
        ),
        "configured_rows": parse_status_machine_rows(status_path),
        # The raw producer must bind the human semantic Specs and their
        # machine-only theorem endpoints.  Keep the two roles separate in the
        # receipt so an endpoint cannot inflate paper-review counts.
        "human_semantic_rows": parse_status_rows(status_path),
        "machine_proof_endpoint_rows": parse_status_proof_endpoint_rows(status_path),
        # ``parse_status_rows`` intentionally merges include and assumption
        # rows for semantic declaration routing.  The raw generator separately
        # treats an assumption-listed row as an independently selected
        # semantic-model obligation, so retain that role bit even when the
        # merged row list is unchanged.
        "assumption_rows": parse_status_review_surface_names(
            status_path, ("assumption_names",)
        ),
        "auxiliary_rows": parse_status_auxiliary_rows(status_path),
        "quarantined_auxiliary_rows": parse_status_quarantined_auxiliary_rows(
            status_path
        ),
        "quarantine_configuration": quarantine_configuration,
        # ``semantic_model_review_config`` is the exact raw-obligation
        # projection.  Unknown policy/annotation fields are intentionally
        # absent because the generator never reads them.
        "semantic_model_review": {
            "dimensions": semantic_dimensions,
            "configuration_errors": semantic_errors,
            "explicit_source_target_declarations": explicit_source_targets,
            "explicit_source_target_configuration_errors": (
                explicit_source_target_errors
            ),
        },
        # A malformed scope can change generated route errors even when the
        # complete governing scope context below is unavailable.
        "formalization_scope_target_selection": {
            "targets": scope_targets,
            "configuration_errors": scope_target_errors,
        },
        # ``formalization_scope.semantic_contract`` is derived from this raw
        # audit and intentionally omitted by ``formalization_scope_context``.
        # The remainder is a governing source target and must stay pinned.
        "formalization_scope": formalization_scope_context(paper_dir),
        "governing_corrections": canonical_governing_corrections(dict(status)),
    }


def source_record_proof_fidelity_semantic_sha256(paper_dir: Path) -> str:
    """Hash the complete fidelity projection consumed by raw generation.

    ``source_proof_fidelity_context`` is serialized into the raw receipt and
    supplied to source-record item construction.  Its projection intentionally
    retains all source/model/proof fields the generator reads.  The ledger may
    also carry policy templates and audit annotations that are not read by the
    raw generator; hashing the entire JSON file made those maintenance edits
    invalidate a Lean-backed scan for no semantic reason.
    """

    context = source_proof_fidelity_context(paper_dir)
    return stable_digest(context) if context is not None else ""


def assumption_semantic_parent_sidecar_projection(
    paper_dir: Path,
) -> dict[str, Any] | None:
    """Return only opt-in assumption-parent inputs consumed by generation.

    Storage keys and validation timestamps are navigation/provenance metadata,
    not mathematical identity.  Effective reviewer identity, accepted premise
    judgments, exact declaration/signature receipts, and source routes are all
    retained.  Returning ``None`` for an ordinary schema-1 assumption sidecar
    preserves existing aggregate cache identities.
    """

    payload = load_json_object(paper_dir / "audit" / "assumption_match_llm.json")
    raw_items = payload.get("items") if isinstance(payload, Mapping) else None
    if not isinstance(raw_items, Mapping):
        return None
    projected_items: list[dict[str, Any]] = []
    for raw_entry in raw_items.values():
        if not isinstance(raw_entry, Mapping) or (
            SOURCE_ASSUMPTION_SEMANTIC_PARENT_RECEIPT_FIELD not in raw_entry
        ):
            continue
        effective_prompt = str(
            raw_entry.get("prompt_version") or payload.get("prompt_version") or ""
        ).strip()
        effective_validator = str(
            raw_entry.get("validator")
            or raw_entry.get("model")
            or raw_entry.get("judge")
            or raw_entry.get("agent")
            or raw_entry.get("generator")
            or payload.get("validator")
            or payload.get("model")
            or payload.get("judge")
            or payload.get("agent")
            or payload.get("generator")
            or ""
        ).strip()
        effective_validator_type = str(
            raw_entry.get("validator_type")
            or raw_entry.get("generator_type")
            or payload.get("validator_type")
            or payload.get("generator_type")
            or ""
        ).strip()
        effective_validated_at = str(
            raw_entry.get("validated_at")
            or raw_entry.get("timestamp")
            or raw_entry.get("generated_at")
            or payload.get("validated_at")
            or payload.get("timestamp")
            or payload.get("generated_at")
            or ""
        ).strip()
        projected_items.append(
            {
                "judgment": raw_entry.get("judgment"),
                "lean_signature_sha256": raw_entry.get("lean_signature_sha256"),
                "premises": raw_entry.get("premises"),
                "premise_judgments": raw_entry.get("premise_judgments"),
                "source_routes": raw_entry.get("source_routes"),
                SOURCE_ASSUMPTION_SEMANTIC_PARENT_RECEIPT_FIELD: raw_entry.get(
                    SOURCE_ASSUMPTION_SEMANTIC_PARENT_RECEIPT_FIELD
                ),
                "reviewer_identity": {
                    "prompt_version": effective_prompt,
                    "validator": effective_validator,
                    "validator_type": effective_validator_type,
                    "validated_at_present": bool(effective_validated_at),
                },
            }
        )
    if not projected_items:
        return None
    return {
        "schema": 1,
        "sidecar_schema": payload.get("schema"),
        "paper": payload.get("paper"),
        "items": sorted(projected_items, key=stable_digest),
    }


def _source_record_input_fingerprint(
    args: argparse.Namespace,
    root: Path,
    paper_dir: Path,
    *,
    paper_statement_map_sha256: str,
    paper_statement_map_semantic_sha256: str | None = None,
    legacy_v7: bool,
    recursive_field_payload_surface: bool | None = None,
    lean_import_closure: SourceRecordLeanImportClosure | None = None,
    raw_audit_payload: Mapping[str, Any] | None = None,
) -> dict[str, Any] | None:
    """Return a current or historical effective expensive-audit identity.

    This is an aggregate cache key only.  It prevents needless repeat builds
    when nothing changed; item-level judgment reuse remains governed by the
    narrower versioned semantic digests attached after a fresh aggregate scan.
    """

    if paper_statement_map_semantic_sha256 is None:
        _full_map_sha256, paper_statement_map_semantic_sha256 = (
            paper_statement_map_cache_receipts(paper_dir)
        )
    status_path = paper_dir / "status.json"
    status = load_json_object(status_path)
    try:
        interface_path = review_source_path(root, paper_dir, status_path)
    except (OSError, ValueError):
        return None
    if not interface_path.exists() or not interface_path.is_file():
        return None
    assumptions_path = effective_source_record_assumption_path(
        root,
        paper_dir,
        status_path,
        interface_path=interface_path,
        lean_import_closure=None if legacy_v7 else lean_import_closure,
    )
    review_surface = status.get("review_surface") if isinstance(status, dict) else None
    if legacy_v7:
        # Reconstruct the former broad v7 identity exactly so an existing
        # unchanged receipt remains reusable after this cache-only upgrade.
        # It is a migration compatibility path, not a new acceptance rule.
        relevant_status: Mapping[str, Any] = {
            "status": status.get("status"),
            "review_surface": review_surface,
            "formalization_scope": formalization_scope_context(paper_dir),
            "governing_corrections": canonical_governing_corrections(status),
        }
        fidelity_path = source_proof_fidelity_path(paper_dir)
        source_proof_fidelity = (
            load_json_object(fidelity_path)
            if fidelity_path is not None and fidelity_path.is_file()
            else None
        )
        fidelity_sha256 = (
            hashlib.sha256(fidelity_path.read_bytes()).hexdigest()
            if fidelity_path is not None and fidelity_path.is_file()
            else ""
        )
        fingerprint_schema = 7
    else:
        relevant_status = source_record_status_control_projection(
            paper_dir, status_path, status
        )
        source_proof_fidelity = source_proof_fidelity_context(paper_dir)
        fidelity_sha256 = source_record_proof_fidelity_semantic_sha256(paper_dir)
        fingerprint_schema = 10
    engine_identities = source_record_engine_identities(
        root,
        paper_dir=paper_dir,
        recursive_field_payload_surface=recursive_field_payload_surface,
        lean_import_closure=lean_import_closure,
        raw_audit_payload=raw_audit_payload,
    )
    engine_identities += recursive_field_source_scope_engine_identities(
        source_proof_fidelity
    )
    transparent_spec_positional_surface = any(
        identity == DIRECT_TRANSPARENT_SPEC_ROOT_IDENTITY_SURFACE_ENGINE_IDENTITY
        for identity in engine_identities
    )
    validated_vocabulary_direct_route_surface = any(
        identity
        == VALIDATED_VOCABULARY_DIRECT_ROUTE_ASSOCIATION_SURFACE_ENGINE_IDENTITY
        for identity in engine_identities
    )
    fingerprint = {
        "schema": fingerprint_schema,
        "source_record_item_digest_schema": SOURCE_RECORD_ITEM_DIGEST_SCHEMA,
        "paper": args.paper,
        "review_interface_source": (
            source_record_lean_source_artifact_identity(
                root, interface_path, lean_import_closure
            )
            if lean_import_closure is not None
            else source_artifact_identity(root, interface_path)
        ),
        "review_assumption_source": (
            (
                source_record_lean_source_artifact_identity(
                    root, assumptions_path, lean_import_closure
                )
                if lean_import_closure is not None
                else source_artifact_identity(root, assumptions_path)
            )
            if assumptions_path is not None
            and assumptions_path.exists()
            and assumptions_path.is_file()
            else None
        ),
        # The full map SHA remains separately serialized on the raw audit as
        # archival provenance.  The cache identity uses only this narrow,
        # fail-closed semantic receipt so an administrative `source_status`
        # correction does not require another Lean/source scan.
        "paper_statement_map_semantic_sha256": paper_statement_map_semantic_sha256,
        "source_proof_fidelity_sha256": fidelity_sha256,
        "relevant_status_sha256": stable_digest(relevant_status),
        "lean_dependency_identities": source_record_dependency_identities(
            root,
            paper_dir,
            interface_path,
            lean_import_closure=lean_import_closure,
        ),
        "audit_engine_identities": engine_identities,
        "source_artifact_identities": source_record_source_artifact_identities(
            root, paper_dir
        ),
        "toolchain_identities": [
            source_record_cache_file_identity(root, root / filename)
            for filename in ("lakefile.lean", "lake-manifest.json", "lean-toolchain")
        ],
        "max_depth": args.max_depth,
        "no_lean": bool(args.no_lean),
    }
    assumption_parent_projection = assumption_semantic_parent_sidecar_projection(
        paper_dir
    )
    if assumption_parent_projection is not None:
        fingerprint["assumption_semantic_parent_sidecar_sha256"] = stable_digest(
            assumption_parent_projection
        )
        fingerprint["assumption_semantic_parent_generator_identity"] = (
            source_record_cache_file_identity(
                REPOSITORY_ROOT,
                REPOSITORY_ROOT
                / "scripts"
                / "source_record_assumption_association.py",
            )
        )
    if legacy_v7:
        # Historical reconstruction keeps the former monolithic review prompt
        # pin exactly. Current extraction fingerprints bind only inputs that
        # can alter the generated obligation surface.
        fingerprint["source_record_policy_version"] = SOURCE_RECORD_PROMPT_VERSION
    if not legacy_v7:
        fingerprint[SOURCE_RECORD_LEAN_IMPORT_CLOSURE_SHA256_FIELD] = (
            lean_import_closure.sha256
            if lean_import_closure is not None
            else ""
        )
        fingerprint[FORMALIZATION_COVERAGE_PROTOCOL_FIELD] = (
            formalization_coverage_protocol_digest()
        )
        # This is intentionally separate from manually managed semantic
        # versions above.  It prevents a raw receipt from cache-hitting after
        # the code that emitted its obligations has changed.
        fingerprint["raw_producer_code_identity_schema"] = (
            SOURCE_RECORD_RAW_PRODUCER_CODE_IDENTITY_SCHEMA
        )
        fingerprint["raw_producer_code_identities"] = (
            source_record_raw_producer_code_identities(
                transparent_spec_positional_surface=(
                    transparent_spec_positional_surface
                ),
                validated_vocabulary_direct_route_surface=(
                    validated_vocabulary_direct_route_surface
                ),
            )
        )
    return fingerprint


def source_record_input_fingerprint(
    args: argparse.Namespace,
    root: Path,
    paper_dir: Path,
    *,
    paper_statement_map_sha256: str,
    paper_statement_map_semantic_sha256: str | None = None,
    recursive_field_payload_surface: bool | None = None,
    lean_import_closure: SourceRecordLeanImportClosure | None = None,
    raw_audit_payload: Mapping[str, Any] | None = None,
) -> dict[str, Any] | None:
    """Return the content-addressed effective expensive-audit inputs.

    This is an aggregate cache key only.  It avoids repeated Lean-backed scans
    when all generated obligations are unchanged; item-level judgment reuse
    remains governed by narrower versioned semantic digests.
    """

    return _source_record_input_fingerprint(
        args,
        root,
        paper_dir,
        paper_statement_map_sha256=paper_statement_map_sha256,
        paper_statement_map_semantic_sha256=paper_statement_map_semantic_sha256,
        legacy_v7=False,
        recursive_field_payload_surface=recursive_field_payload_surface,
        lean_import_closure=lean_import_closure,
        raw_audit_payload=raw_audit_payload,
    )


def source_record_inputs_changed_during_scan_error(
    args: argparse.Namespace,
    root: Path,
    paper_dir: Path,
    *,
    scan_start_map_sha256: str,
    scan_start_semantic_map_sha256: str,
    scan_start_input_fingerprint: dict[str, Any] | None,
    lean_import_closure: SourceRecordLeanImportClosure | None = None,
) -> str:
    """Reject a long scan when any evidence-bearing input changed mid-run.

    The raw producer snapshots Lean declarations and source-map routes before
    its expensive elaboration work.  Recomputing the same input identity just
    before publication prevents a mixed receipt whose metadata reflects a
    later edit while its obligations came from an earlier surface.
    """

    current_map_sha256, current_semantic_map_sha256 = (
        paper_statement_map_cache_receipts(paper_dir)
    )
    changes: list[str] = []
    if current_map_sha256 != scan_start_map_sha256:
        changes.append("paper statement-map bytes changed during scan")
    if current_semantic_map_sha256 != scan_start_semantic_map_sha256:
        changes.append("paper statement-map semantic receipt changed during scan")

    current_input_fingerprint = source_record_input_fingerprint(
        args,
        root,
        paper_dir,
        paper_statement_map_sha256=current_map_sha256,
        paper_statement_map_semantic_sha256=current_semantic_map_sha256,
        lean_import_closure=lean_import_closure,
    )
    if scan_start_input_fingerprint is None:
        changes.append("could not establish a pre-scan input fingerprint")
    elif current_input_fingerprint is None:
        changes.append("could not establish a post-scan input fingerprint")
    elif current_input_fingerprint != scan_start_input_fingerprint:
        changes.append("review/source/toolchain input fingerprint changed during scan")
    return "; ".join(changes)


def source_record_legacy_v7_input_fingerprint(
    args: argparse.Namespace,
    root: Path,
    paper_dir: Path,
    *,
    paper_statement_map_sha256: str,
    paper_statement_map_semantic_sha256: str | None = None,
    lean_import_closure: SourceRecordLeanImportClosure | None = None,
    raw_audit_payload: Mapping[str, Any] | None = None,
) -> dict[str, Any] | None:
    """Recompute the pre-projection v7 identity for compatibility only."""

    return _source_record_input_fingerprint(
        args,
        root,
        paper_dir,
        paper_statement_map_sha256=paper_statement_map_sha256,
        paper_statement_map_semantic_sha256=paper_statement_map_semantic_sha256,
        legacy_v7=True,
        lean_import_closure=lean_import_closure,
        raw_audit_payload=raw_audit_payload,
    )


def source_record_saved_statement_ledger_coverages(
    payload: Mapping[str, Any],
) -> tuple[set[str], set[str]] | None:
    """Return the direct and precloseout portions of a saved ledger, fail closed.

    ``statement_ledger_covered_boundary_input_keys`` is deliberately a union:
    ordinary direct source-to-Lean coverage, an independently checked
    semantic-contract closeout bridge, and the narrow partial-status
    direct/Spec duplicate projection can all contribute keys.  The serialized
    precloseout list identifies only the last category; the remaining claimed
    direct portion is still revalidated entry by entry below.  In particular,
    a bridge-only key cannot inherit ordinary direct credit merely because it
    sits in this union.  Legacy raw receipts without either list predate this
    optimization and therefore have no saved suppression to revalidate.
    """

    has_ledger = "statement_ledger_covered_boundary_input_keys" in payload
    has_precloseout = "precloseout_contract_covered_boundary_input_keys" in payload
    if not has_ledger and not has_precloseout:
        return set(), set()
    if not has_ledger or not has_precloseout:
        return None

    raw_covered = payload.get("statement_ledger_covered_boundary_input_keys")
    raw_precloseout = payload.get("precloseout_contract_covered_boundary_input_keys")
    if not isinstance(raw_covered, list) or not isinstance(raw_precloseout, list):
        return None
    # No current suppression means there is no dynamic ledger credit to retain.
    # Older/minimal identity receipts may omit the otherwise useful generated
    # input inventory, and requiring it here would reject a status-transition
    # reuse path for no semantic-cache reason.
    if not raw_covered and not raw_precloseout:
        return set(), set()

    expected_raw = payload.get("expected_input_judgment_keys")
    if not isinstance(expected_raw, list):
        return None
    expected: set[str] = set()
    for raw_key in expected_raw:
        if not isinstance(raw_key, str) or not raw_key.strip():
            return None
        key = raw_key.strip()
        if key in expected:
            return None
        expected.add(key)

    def parse_subset(value: object) -> set[str] | None:
        if not isinstance(value, list):
            return None
        keys: set[str] = set()
        for raw_key in value:
            if not isinstance(raw_key, str) or not raw_key.strip():
                return None
            key = raw_key.strip()
            if key in keys or key not in expected:
                return None
            keys.add(key)
        return keys

    covered = parse_subset(raw_covered)
    precloseout = parse_subset(raw_precloseout)
    if covered is None or precloseout is None or not precloseout <= covered:
        return None
    return covered - precloseout, precloseout


def _source_record_static_current_direct_route(
    raw_route: object,
    *,
    qualified: str,
    current_interface_declarations: Mapping[str, tuple[str, str, int]],
) -> bool:
    """Recognize one exact configured direct-map route for ``qualified``.

    A semantic contract provides the authoritative fully-qualified endpoint.
    Some older source maps spell the matching ``lean_declarations`` selector
    locally.  Treat that spelling only as a selector for the already-known
    endpoint, and only when the current configured interface has exactly one
    declaration with that local component.  It never discovers a target by
    searching for a similarly named declaration.
    """

    if not isinstance(raw_route, str):
        return False
    route = raw_route.strip()
    if not route or qualified not in current_interface_declarations:
        return False
    if semantic_contract_fully_qualified_identity(route):
        return route == qualified
    if "." in route or route != qualified.rsplit(".", 1)[-1]:
        return False
    matching_current_routes = {
        current_qualified
        for current_qualified in current_interface_declarations
        if current_qualified.rsplit(".", 1)[-1] == route
    }
    return matching_current_routes == {qualified}


def _source_record_static_direct_route_list_has_current_route(
    raw_routes: object,
    *,
    qualified: str,
    current_interface_declarations: Mapping[str, tuple[str, str, int]],
) -> bool:
    """Require a well-formed explicit ``lean_declarations`` route list."""

    if not isinstance(raw_routes, list) or not raw_routes:
        return False
    has_current_route = False
    for raw_route in raw_routes:
        if not isinstance(raw_route, str) or not raw_route.strip():
            return False
        if _source_record_static_current_direct_route(
            raw_route,
            qualified=qualified,
            current_interface_declarations=current_interface_declarations,
        ):
            has_current_route = True
    return has_current_route


def _source_record_static_direct_statement_inventory(
    paper_dir: Path,
    dashboard: Any,
    *,
    current_interface_declarations: Mapping[str, tuple[str, str, int]],
) -> tuple[
    dict[str, dict[str, Any]],
    dict[str, set[str]],
    dict[str, list[dict[str, Any]]],
] | None:
    """Read current direct source routes without opening a source artifact.

    This is intentionally narrower than the ordinary dashboard inventory:
    source text that must be re-extracted from a PDF/TeX/text artifact is not
    cache evidence.  A raw audit with such a route can always regenerate its
    expensive surface, but cannot silently retain a suppressed input through a
    best-effort source-text fallback.
    """

    source_map = load_json_object(paper_dir / "audit" / "paper_statement_map.json")
    if not isinstance(source_map, dict):
        return None
    raw_items = source_map.get("items")
    if not isinstance(raw_items, dict):
        return None
    mode, mode_error = source_coverage_mode_from_map(source_map)
    if mode_error:
        return None
    selected_items = filter_source_map_items_for_coverage(
        raw_items,
        mode,
        declared_environment_kinds=source_named_result_environment_kinds_from_map(
            source_map
        ),
    )

    # The semantic ledger validator still checks every route carried by a
    # statement sidecar.  Give it only current map entries with an inline,
    # byte-computable source statement and locator; otherwise it must fail
    # closed instead of reading the source paper again.
    inventory: dict[str, dict[str, Any]] = {}
    for raw_key, raw_item in raw_items.items():
        if not isinstance(raw_item, dict):
            continue
        key = str(raw_key).strip()
        if not key:
            continue
        statement, statement_sha256 = dashboard._source_item_coverage_statement(
            raw_item
        )
        location = dashboard._source_item_coverage_location(raw_item)
        if not statement or not statement_sha256 or not location:
            continue
        inventory[key] = dict(raw_item)

    direct_source_keys_by_qualified: dict[str, set[str]] = {}
    semantic_contract_direct_evidence_identities_by_qualified: dict[
        str, list[dict[str, Any]]
    ] = {}
    raw_contract_schema = source_map.get("semantic_contract_schema")
    semantic_contract_schema = (
        raw_contract_schema
        if isinstance(raw_contract_schema, int)
        and not isinstance(raw_contract_schema, bool)
        and raw_contract_schema in SEMANTIC_CONTRACT_SCHEMAS
        else None
    )
    for raw_key, raw_item in selected_items.items():
        if not isinstance(raw_item, dict):
            continue
        key = str(raw_key).strip()
        if not key or key not in inventory:
            continue
        if raw_item.get("claim_bearing") is False:
            continue
        if (
            str(raw_item.get("coverage_status") or "").strip().lower()
            == "corrected_source_statement"
        ):
            # Corrected targets have a distinct closeout lane and never gain
            # ordinary direct-ledger suppression here.
            continue
        source_kind = str(raw_item.get("source_kind") or "").strip().lower()
        if source_kind not in DIRECT_SOURCE_RESULT_KINDS:
            continue
        for raw_declaration in dashboard.source_item_direct_coverage_declarations(
            raw_item
        ):
            for qualified in current_interface_declarations:
                if _source_record_static_current_direct_route(
                    raw_declaration,
                    qualified=qualified,
                    current_interface_declarations=current_interface_declarations,
                ):
                    direct_source_keys_by_qualified.setdefault(qualified, set()).add(
                        key
                    )

        # A semantic-contract group can supply direct-ledger credit only for
        # the direct evidence member.  Reconstruct that narrow route from the
        # current map and the authoritative fully-qualified contract endpoint;
        # do not infer it from a row, map key, or declaration suffix.
        raw_contract = raw_item.get("semantic_contract")
        if (
            raw_item.get("claim_bearing") is not True
            or semantic_contract_schema is None
            or not isinstance(raw_contract, dict)
            or semantic_contract_validation_errors(
                raw_contract, schema=semantic_contract_schema
            )
        ):
            continue
        evidence = semantic_contract_fully_qualified_identity(
            raw_contract.get("evidence_declaration")
        )
        spec = semantic_contract_fully_qualified_identity(
            raw_contract.get("spec_declaration")
        )
        if (
            not evidence
            or not spec
            or evidence == spec
            or spec not in current_interface_declarations
            or not _source_record_static_direct_route_list_has_current_route(
                raw_item.get("lean_declarations"),
                qualified=evidence,
                current_interface_declarations=current_interface_declarations,
            )
        ):
            continue
        semantic_contract_direct_evidence_identities_by_qualified.setdefault(
            evidence, []
        ).append(semantic_contract_source_identity(key, raw_item))
    return (
        inventory,
        direct_source_keys_by_qualified,
        semantic_contract_direct_evidence_identities_by_qualified,
    )


def _source_record_static_semantic_contract_direct_evidence_source_keys(
    association: Mapping[str, Any],
    *,
    qualified: str,
    signature: str,
    current_source_identities: Mapping[str, list[dict[str, Any]]],
) -> set[str] | None:
    """Return current source keys for one exact direct-evidence association.

    The saved schema-2 receipt is reusable only when its direct source member
    has the same source-content identity, the same current semantic-contract
    route, and the same elaborated direct-declaration signature.  Source-map
    keys and full item hashes are diagnostic provenance rather than semantic
    selectors, so an authenticated administrative key/status edit cannot
    manufacture or invalidate a route by itself.
    """

    if (
        association.get("association_mode") != "semantic_contract_group_member"
        or association.get("schema") != 2
        or str(association.get("semantic_contract_member_role") or "").strip()
        != "direct_evidence"
    ):
        return None

    stored_association_sha256 = str(
        association.get("association_sha256") or ""
    ).strip().lower()
    association_without_digest = dict(association)
    association_without_digest.pop("association_sha256", None)
    if (
        not SHA256_RE.fullmatch(stored_association_sha256)
        or stable_digest(association_without_digest) != stored_association_sha256
    ):
        return None

    source_identities, source_identity_errors = source_contract_source_identities(
        association.get("source_item_identities")
    )
    if source_identity_errors:
        return None
    source_keys = [str(identity["source_key"]) for identity in source_identities]
    source_hashes = {
        str(identity["source_key"]): str(identity["source_map_item_sha256"])
        for identity in source_identities
    }
    if (
        association.get("source_map_item_keys") != source_keys
        or association.get("source_map_item_keys_sha256") != stable_digest(source_keys)
        or association.get("source_map_item_sha256_by_key") != source_hashes
    ):
        return None

    associated_signature = association.get("reviewed_elaborated_signature_identity")
    if (
        not isinstance(associated_signature, dict)
        or semantic_contract_fully_qualified_identity(
            associated_signature.get("qualified_declaration")
        )
        != qualified
        or str(
            associated_signature.get("elaborated_signature_sha256") or ""
        ).strip().lower()
        != signature
    ):
        return None
    semantic_association_sha256 = semantic_source_association_digest(
        source_identities, associated_signature
    )
    if (
        not semantic_association_sha256
        or association.get("semantic_association_sha256")
        != semantic_association_sha256
    ):
        return None

    saved_by_semantic_sha: dict[str, dict[str, Any]] = {}
    for identity in source_identities:
        semantic_sha = str(identity.get("source_semantic_sha256") or "").strip().lower()
        contract = identity.get("semantic_contract")
        if semantic_sha in saved_by_semantic_sha or not isinstance(contract, dict):
            return None
        if (
            semantic_contract_fully_qualified_identity(
                contract.get("evidence_declaration")
            )
            != qualified
            or not semantic_contract_fully_qualified_identity(
                contract.get("spec_declaration")
            )
            or semantic_contract_fully_qualified_identity(
                contract.get("spec_declaration")
            )
            == qualified
            or not str(contract.get("evidence_mode") or "").strip()
            or not str(contract.get("semantic_shape") or "").strip()
        ):
            return None
        saved_by_semantic_sha[semantic_sha] = identity

    current_by_semantic_sha: dict[str, list[dict[str, Any]]] = {}
    for current_identity in current_source_identities.get(qualified, []):
        if not isinstance(current_identity, dict):
            return None
        semantic_sha = str(
            current_identity.get("source_semantic_sha256") or ""
        ).strip().lower()
        if not SHA256_RE.fullmatch(semantic_sha):
            return None
        current_by_semantic_sha.setdefault(semantic_sha, []).append(current_identity)
    if set(current_by_semantic_sha) != set(saved_by_semantic_sha):
        return None

    current_matched_identities: list[dict[str, Any]] = []
    current_source_keys: set[str] = set()
    for semantic_sha, saved_identity in saved_by_semantic_sha.items():
        candidates = current_by_semantic_sha.get(semantic_sha, [])
        if len(candidates) != 1:
            return None
        current_identity = candidates[0]
        if current_identity.get("semantic_contract") != saved_identity.get(
            "semantic_contract"
        ):
            return None
        source_key = str(current_identity.get("source_key") or "").strip()
        if not source_key or source_key in current_source_keys:
            return None
        current_source_keys.add(source_key)
        current_matched_identities.append(current_identity)

    if (
        semantic_source_association_digest(
            current_matched_identities, associated_signature
        )
        != semantic_association_sha256
    ):
        return None
    return current_source_keys


def _source_record_static_current_interface_declarations(
    root: Path, paper_dir: Path, dashboard: Any
) -> tuple[Path, str, dict[str, tuple[str, str, int]]] | None:
    """Return current configured-interface declaration coordinates without Lean.

    The generated raw identity hashes the *complete* parsed declaration, while
    a dashboard cache serializes only the declaration header it presents to a
    reviewer.  Validate both against one current lexical parse: the complete
    source hash prevents a same-signature neighbor from replacing the raw
    declaration, and the header/line pair prevents that neighbor's cached row
    from being replayed under this row label.  This reads the configured Lean
    interface only; it does not build Lean or inspect a paper source artifact.
    """

    status_path = paper_dir / "status.json"
    try:
        interface_path = review_source_path(root, paper_dir, status_path)
        if not interface_path.is_file():
            return None
        interface_text = interface_path.read_text(encoding="utf-8")
        local_declarations = parse_local_declarations(root, [interface_path])
        dashboard_declarations = dashboard.parse_review_source_declarations(
            interface_path
        )
    except (OSError, RuntimeError, ValueError):
        return None

    full_sources: dict[str, str] = {}
    for declaration in local_declarations:
        qualified = semantic_contract_fully_qualified_identity(declaration.name)
        if not qualified or qualified in full_sources or not declaration.source.strip():
            return None
        full_sources[qualified] = declaration.source

    headers: dict[str, tuple[str, int]] = {}
    for raw_declaration in dashboard_declarations:
        if not isinstance(raw_declaration, tuple) or len(raw_declaration) != 7:
            return None
        _kind, _name, raw_qualified, header, _comment, line, _source_path = (
            raw_declaration
        )
        qualified = semantic_contract_fully_qualified_identity(raw_qualified)
        if (
            not qualified
            or qualified in headers
            or not isinstance(header, str)
            or not header.strip()
            or not isinstance(line, int)
            or isinstance(line, bool)
            or line < 1
        ):
            return None
        headers[qualified] = (header.strip(), line)

    declarations: dict[str, tuple[str, str, int]] = {}
    for qualified, source in full_sources.items():
        header = headers.get(qualified)
        if header is None:
            continue
        declarations[qualified] = (
            hashlib.sha256(source.encode("utf-8")).hexdigest(),
            header[0],
            header[1],
        )
    return interface_path, dashboard.statement_digest(interface_text), declarations


def _source_record_static_statement_manifest_rows(
    paper_dir: Path,
    dashboard: Any,
    *,
    interface_path: Path,
    interface_source_sha256: str,
) -> dict[str, dict[str, Any]] | None:
    """Load previously checked manifests without rebuilding a review module.

    A cached manifest is usable only after its canonical digest is compared to
    the successful raw audit's exact elaborated-signature identity below.  This
    function intentionally never calls ``review_items_for_paper``: that API
    may build an import target when its manifest cache is cold.
    """

    cache_name = str(
        getattr(dashboard, "DEFAULT_PAPER_INTERFACE_CACHE_FILE", "paper_interface_cache.json")
    ).strip()
    if not cache_name:
        return None
    cache = load_json_object(paper_dir / ".review_traces" / cache_name)
    if (
        not isinstance(cache, dict)
        or cache.get("schema") != getattr(dashboard, "PAPER_INTERFACE_CACHE_SCHEMA", None)
        or cache.get("paper") != paper_dir.name
    ):
        return None
    cache_hashes = cache.get("hashes")
    if (
        not isinstance(cache_hashes, dict)
        or str(cache_hashes.get("review_source_file") or "").strip()
        != interface_path.name
        or str(cache_hashes.get("interface_sha256") or "").strip().lower()
        != interface_source_sha256
    ):
        return None
    raw_rows = cache.get("rows")
    if not isinstance(raw_rows, list):
        return None
    rows: dict[str, dict[str, Any]] = {}
    for raw_row in raw_rows:
        if not isinstance(raw_row, dict):
            return None
        row = str(raw_row.get("name") or "").strip()
        if not row or row in rows:
            return None
        rows[row] = raw_row
    return rows


_SOURCE_RECORD_PRIOR_MANIFEST_CONTEXT_FIELDS = (
    "schema",
    "import_module",
    "olean_fingerprint",
    "helper_fingerprint",
    "semantic_hash_tool_identity",
    "canonical_representation",
)

_SOURCE_RECORD_PRIOR_MANIFEST_ITEM_REVALIDATION_CONTEXT_FIELDS = (
    "schema",
    "import_module",
    "helper_fingerprint",
    "semantic_hash_tool_identity",
    "canonical_representation",
    "audit_modules",
)


def _source_record_prior_manifest_source_authority(
    raw_audit: Mapping[str, Any],
    *,
    source_map_semantic_index: Mapping[str, list[dict[str, Any]]],
    source_proof_fidelity: Mapping[str, Any] | None,
) -> set[str]:
    """Return roots whose prior manifest has a current source-content route.

    Declaration spellings only locate candidate rows.  Authorization requires
    the prior row's exact elaborated signature and semantic-dependency digest,
    an item-generated keyless source-content identity, and current item-scoped
    context/ledger pins.  Thus a name cannot preserve a manifest after either
    side of its mathematical association changes.
    """

    raw_rows = raw_audit.get("configured_review_rows")
    if not isinstance(raw_rows, list):
        return set()
    row_qualified_names: dict[str, str] = {}
    signatures: dict[str, str] = {}
    dependencies: dict[str, str] = {}
    for raw_row in raw_rows:
        if not isinstance(raw_row, Mapping):
            return set()
        row = str(raw_row.get("row") or "").strip()
        qualified = semantic_contract_fully_qualified_identity(
            raw_row.get("qualified_declaration")
        )
        signature = str(
            raw_row.get("elaborated_signature_sha256") or ""
        ).strip().lower()
        dependency = str(
            raw_row.get("semantic_dependency_sha256") or ""
        ).strip().lower()
        if (
            not row
            or not qualified
            or row in row_qualified_names
            or qualified in signatures
            or not SHA256_RE.fullmatch(signature)
            or not SHA256_RE.fullmatch(dependency)
        ):
            return set()
        row_qualified_names[row] = qualified
        signatures[qualified] = signature
        dependencies[qualified] = dependency

    authorized: set[str] = set()
    for section in SOURCE_RECORD_REUSABLE_ITEM_SECTIONS:
        raw_items = raw_audit.get(section)
        if not isinstance(raw_items, list):
            return set()
        for raw_item in raw_items:
            if not isinstance(raw_item, dict):
                return set()
            if not source_record_item_reuse_eligible(
                raw_item,
                expected_item_digest_schema=SOURCE_RECORD_ITEM_DIGEST_SCHEMA,
            ):
                continue
            if not source_record_item_source_semantic_identities(raw_item):
                continue
            context_pin, ledger_pin, pin_errors = (
                source_record_item_scoped_context_pins(
                    raw_item,
                    source_map_semantic_index=source_map_semantic_index,
                    source_proof_fidelity=source_proof_fidelity,
                )
            )
            if pin_errors:
                continue
            if (
                (
                    stable_digest(context_pin)
                    if context_pin is not None
                    else None
                )
                != raw_item.get(
                    "source_record_item_semantic_context_requirements_sha256"
                )
                or (
                    stable_digest(ledger_pin)
                    if ledger_pin is not None
                    else None
                )
                != raw_item.get(
                    "source_record_item_source_proof_fidelity_records_sha256"
                )
            ):
                continue
            for identity in source_record_item_reviewed_signature_identities(
                raw_item,
                row_qualified_names=row_qualified_names,
                elaborated_signature_sha256_by_qualified=signatures,
                semantic_dependency_sha256_by_qualified=dependencies,
            ):
                qualified = semantic_contract_fully_qualified_identity(
                    identity.get("qualified_declaration")
                )
                if qualified:
                    authorized.add(qualified)
    return authorized


def reusable_prior_review_signature_manifests(
    *,
    root: Path,
    paper_dir: Path,
    requested_declaration_sources: Mapping[str, str],
    requested_declaration_source_paths: Mapping[str, Path],
    source_contract_statement_map: Mapping[str, Any] | None,
    build_timeout_seconds: int = SOURCE_RECORD_LAKE_BUILD_TIMEOUT_SECONDS,
    progress_callback: Callable[[Mapping[str, Any]], None] | None = None,
) -> tuple[dict[str, dict[str, Any]], dict[str, Any]]:
    """Recover individually revalidated reviewed-root manifests.

    The canonical prior raw audit is the authority for the old signature,
    dependency, declaration, and source association.  The dashboard cache is
    only a carrier for the full Lean-emitted graph omitted from that raw audit.
    A carrier row is accepted only after its context is current, its graph is
    rebound to current reached-module artifacts, and both canonical digests
    exactly reproduce the authenticated raw row.  Missing or ambiguous data
    merely leaves that declaration for fresh Lean elaboration.

    This deliberately seeds configured reviewed roots only. Effective alias
    targets and recursively reached records have no independent canonical raw
    row/source association and therefore remain fresh.
    """

    diagnostics: dict[str, Any] = {
        "schema": 1,
        "requested_count": len(requested_declaration_sources),
        "accepted_count": 0,
        "accepted_manifest_pins_by_declaration": {},
        "rejected_by_reason": {},
    }
    rejected: dict[str, set[str]] = {}

    def reject(qualified: str, reason: str) -> None:
        rejected.setdefault(qualified, set()).add(reason)

    requested: dict[str, str] = {}
    for raw_qualified, source in requested_declaration_sources.items():
        qualified = semantic_contract_fully_qualified_identity(raw_qualified)
        if not qualified or not isinstance(source, str) or not source.strip():
            continue
        if qualified in requested:
            reject(qualified, "ambiguous_current_declaration")
            continue
        requested[qualified] = source
    if not requested:
        diagnostics["rejected_by_reason"] = {}
        return {}, diagnostics

    raw_audit = load_json_object(canonical_source_record_audit_path(paper_dir))
    if (
        raw_audit.get("paper") != paper_dir.name
        or source_record_audit_receipt_error(raw_audit)
        or source_record_raw_reusable_item_metadata_error(
            raw_audit,
            expected_item_digest_schema=SOURCE_RECORD_ITEM_DIGEST_SCHEMA,
        )
        or source_record_raw_scan_completeness_error(raw_audit)
    ):
        for qualified in requested:
            reject(qualified, "canonical_prior_raw_unavailable")
        diagnostics["rejected_by_reason"] = {
            key: sorted(value) for key, value in sorted(rejected.items())
        }
        return {}, diagnostics

    raw_rows_by_qualified: dict[str, Mapping[str, Any]] = {}
    duplicate_raw_rows: set[str] = set()
    raw_rows = raw_audit.get("configured_review_rows")
    if not isinstance(raw_rows, list):
        raw_rows = []
    for raw_row in raw_rows:
        if not isinstance(raw_row, Mapping):
            continue
        qualified = semantic_contract_fully_qualified_identity(
            raw_row.get("qualified_declaration")
        )
        if not qualified:
            continue
        if qualified in raw_rows_by_qualified:
            duplicate_raw_rows.add(qualified)
            continue
        raw_rows_by_qualified[qualified] = raw_row

    source_index = source_record_source_map_semantic_index(
        source_contract_statement_map
    )
    source_authorized = _source_record_prior_manifest_source_authority(
        raw_audit,
        source_map_semantic_index=source_index,
        source_proof_fidelity=source_proof_fidelity_context(paper_dir),
    )

    try:
        from scripts import review_dashboard as dashboard

        cache = load_json_object(dashboard.paper_interface_cache_file(paper_dir))
    except Exception:  # noqa: BLE001 - optional carriers fail closed.
        cache = {}
        dashboard = None
    if (
        dashboard is None
        or cache.get("schema")
        != getattr(dashboard, "PAPER_INTERFACE_CACHE_SCHEMA", None)
        or cache.get("paper") != paper_dir.name
        or not isinstance(cache.get("rows"), list)
        or not isinstance(cache.get("signature_contexts"), Mapping)
    ):
        for qualified in requested:
            reject(qualified, "dashboard_manifest_carrier_unavailable")
        diagnostics["rejected_by_reason"] = {
            key: sorted(value) for key, value in sorted(rejected.items())
        }
        return {}, diagnostics

    carrier_rows: dict[str, Mapping[str, Any]] = {}
    duplicate_carrier_rows: set[str] = set()
    for raw_row in cache["rows"]:
        if not isinstance(raw_row, Mapping):
            continue
        qualified = semantic_contract_fully_qualified_identity(
            raw_row.get("full_name")
        )
        if not qualified:
            continue
        if qualified in carrier_rows:
            duplicate_carrier_rows.add(qualified)
            continue
        carrier_rows[qualified] = raw_row

    context_cache: dict[
        str,
        tuple[
            Mapping[str, Any],
            Mapping[str, Any],
            str,
            tuple[str, ...],
        ]
        | None,
    ] = {}
    candidates: dict[str, dict[str, Any]] = {}
    candidate_contexts: dict[str, Mapping[str, Any]] = {}
    item_revalidation_candidates: dict[
        str,
        tuple[
            dict[str, Any],
            Mapping[str, Any],
            Mapping[str, Any],
            str,
            tuple[str, ...],
            str,
        ],
    ] = {}
    cached_contexts = cache["signature_contexts"]
    for qualified, current_source in requested.items():
        prior = raw_rows_by_qualified.get(qualified)
        carrier = carrier_rows.get(qualified)
        source_path = requested_declaration_source_paths.get(qualified)
        if qualified in duplicate_raw_rows or qualified in duplicate_carrier_rows:
            reject(qualified, "ambiguous_prior_identity")
            continue
        if prior is None or carrier is None:
            reject(qualified, "missing_prior_identity")
            continue
        if prior.get("lean_source_declaration") != current_source:
            reject(qualified, "declaration_source_changed")
            continue
        if qualified not in source_authorized:
            reject(qualified, "source_association_not_current")
            continue
        if not isinstance(source_path, Path):
            reject(qualified, "current_source_path_unavailable")
            continue
        try:
            context_key = source_path.resolve().relative_to(
                paper_dir.resolve()
            ).as_posix()
        except (OSError, ValueError):
            reject(qualified, "current_source_path_outside_paper")
            continue
        if context_key not in context_cache:
            cached_context = cached_contexts.get(context_key)
            try:
                source_module = dashboard.review_source_module(
                    paper_dir, source_path
                )
                dependency_modules = (
                    dashboard.paper_owned_module_names_in_import_closure(
                        root, paper_dir, source_module
                    )
                )
                current_context = (
                    signature_manifest_cache_context(
                        root,
                        source_module,
                        build_timeout_seconds=build_timeout_seconds,
                        semantic_dependency_modules=tuple(dependency_modules),
                    )
                    if dependency_modules
                    else None
                )
            except Exception:  # noqa: BLE001 - a context miss means fresh Lean.
                current_context = None
            if not isinstance(cached_context, Mapping) or not isinstance(
                current_context, Mapping
            ):
                context_cache[context_key] = None
            else:
                context_cache[context_key] = (
                    cached_context,
                    current_context,
                    source_module,
                    tuple(dependency_modules),
                )
        context_details = context_cache[context_key]
        if context_details is None:
            reject(qualified, "manifest_context_changed")
            continue
        cached_context, current_context, source_module, dependency_modules = (
            context_details
        )
        manifest = carrier.get("lean_signature_manifest")
        prior_signature = str(
            prior.get("elaborated_signature_sha256") or ""
        ).strip().lower()
        prior_proposition_graph_sha256 = (
            configured_review_row_proposition_graph_sha256(prior)
        )
        if (
            not isinstance(manifest, dict)
            or not SHA256_RE.fullmatch(prior_signature)
            or not prior_proposition_graph_sha256
            or str(carrier.get("lean_signature_sha256") or "").strip().lower()
            != prior_signature
            or signature_manifest_digest(manifest) != prior_signature
            or str(manifest.get("sha256") or "").strip().lower()
            != prior_signature
            or elaborated_proposition_graph_sha256(
                manifest.get("elaborated_proposition_graph")
            )
            != prior_proposition_graph_sha256
        ):
            reject(qualified, "carrier_signature_or_graph_mismatch")
            continue
        if all(
            cached_context.get(field) == current_context.get(field)
            for field in _SOURCE_RECORD_PRIOR_MANIFEST_CONTEXT_FIELDS
        ):
            candidates[qualified] = manifest
            candidate_contexts[qualified] = current_context
            continue
        if any(
            cached_context.get(field) != current_context.get(field)
            for field in (
                _SOURCE_RECORD_PRIOR_MANIFEST_ITEM_REVALIDATION_CONTEXT_FIELDS
            )
        ):
            reject(qualified, "manifest_context_changed")
            continue
        item_revalidation_candidates[qualified] = (
            manifest,
            cached_context,
            current_context,
            source_module,
            dependency_modules,
            context_key,
        )

    revalidation_groups: dict[
        str,
        tuple[
            str,
            tuple[str, ...],
            Mapping[str, Any],
            list[str],
        ],
    ] = {}
    for qualified, details in item_revalidation_candidates.items():
        _manifest, _prior_context, current_context, source_module, modules, key = (
            details
        )
        group = revalidation_groups.get(key)
        if group is None:
            revalidation_groups[key] = (
                source_module,
                modules,
                current_context,
                [qualified],
            )
        elif (
            group[0] == source_module
            and group[1] == modules
            and dict(group[2]) == dict(current_context)
        ):
            group[3].append(qualified)
        else:
            reject(qualified, "ambiguous_current_manifest_context")

    item_revalidated: set[str] = set()
    for source_module, modules, current_context, qualified_names in (
        revalidation_groups.values()
    ):
        try:
            receipts = run_lean_signature_manifest_revalidations(
                root,
                source_module,
                qualified_names,
                timeout_seconds=build_timeout_seconds,
                build_timeout_seconds=build_timeout_seconds,
                semantic_dependency_modules=modules,
                current_context=current_context,
                progress_callback=progress_callback,
            )
        except Exception:  # noqa: BLE001 - failed optimization stays a miss.
            receipts = {}
        for qualified in qualified_names:
            details = item_revalidation_candidates[qualified]
            manifest, prior_context, candidate_context = details[:3]
            receipt = receipts.get(qualified)
            if not isinstance(receipt, Mapping):
                reject(qualified, "manifest_item_revalidation_unavailable")
                continue
            if not signature_manifest_item_revalidation_matches(
                manifest,
                receipt,
                declaration=qualified,
                prior_context=prior_context,
                current_context=candidate_context,
            ):
                reject(qualified, "manifest_item_semantics_changed")
                continue
            # Keep the prior canonical atom/proposition payload only after the
            # compact check above proves it unchanged. Rebind dependency
            # routing from the *current* Lean graph so a semantically equal
            # imported terminal that moved modules cannot retain stale
            # artifact coordinates from the carrier.
            candidates[qualified] = {
                **manifest,
                "semantic_dependency_graph": dict(
                    receipt["semantic_dependency_graph"]
                ),
                "elaborated_execution_state_refinement_shape": dict(
                    receipt["elaborated_execution_state_refinement_shape"]
                ),
            }
            candidate_contexts[qualified] = candidate_context
            item_revalidated.add(qualified)

    try:
        rebound = reattach_semantic_dependency_module_identities(
            root,
            candidates,
            timeout_seconds=build_timeout_seconds,
        )
    except Exception:  # noqa: BLE001 - a rebind failure means fresh Lean.
        rebound = {}

    accepted: dict[str, dict[str, Any]] = {}
    for qualified, manifest in candidates.items():
        current_manifest = rebound.get(qualified)
        prior = raw_rows_by_qualified[qualified]
        if not isinstance(current_manifest, dict):
            reject(qualified, "current_dependency_artifacts_unavailable")
            continue
        dependency = semantic_dependency_manifest(current_manifest)
        prior_dependency = str(
            prior.get("semantic_dependency_sha256") or ""
        ).strip().lower()
        if (
            signature_manifest_digest(current_manifest)
            != str(prior.get("elaborated_signature_sha256") or "").strip().lower()
            or not isinstance(dependency, Mapping)
            or str(
                dependency.get("semantic_dependency_sha256") or ""
            ).strip().lower()
            != prior_dependency
        ):
            reject(qualified, "signature_or_dependency_closure_changed")
            continue
        current_manifest["semantic_dependency_manifest"] = dict(dependency)
        accepted[qualified] = current_manifest

    diagnostics["accepted_count"] = len(accepted)
    diagnostics["item_revalidation_requested_count"] = len(
        item_revalidation_candidates
    )
    diagnostics["item_revalidated_count"] = len(item_revalidated & set(accepted))
    diagnostics["accepted_manifest_pins_by_declaration"] = {
        qualified: {
            "manifest_cache_context_sha256": (
                signature_manifest_cache_context_sha256(
                    candidate_contexts[qualified]
                )
            ),
            "elaborated_signature_sha256": str(
                raw_rows_by_qualified[qualified].get(
                    "elaborated_signature_sha256"
                )
                or ""
            ).strip().lower(),
            "semantic_dependency_sha256": str(
                raw_rows_by_qualified[qualified].get(
                    "semantic_dependency_sha256"
                )
                or ""
            ).strip().lower(),
        }
        for qualified in sorted(accepted)
    }
    diagnostics["rejected_by_reason"] = {
        key: sorted(value)
        for key, value in sorted(rejected.items())
        if key not in accepted
    }
    return accepted, diagnostics


def seeded_prior_review_signature_manifests(
    manifests: Mapping[str, Mapping[str, Any]],
    seeded_declarations: Iterable[str],
) -> dict[str, dict[str, Any]]:
    """Keep only prior manifests independently accepted by cache seeding.

    The prior-raw carrier check and the context-cache seed check are separate
    authorities.  A manifest rejected by the latter must return to the fresh
    Lean request even if it passed the former; forwarding the larger carrier
    set as ``prevalidated_manifests`` would bypass that rejection.
    """

    seeded = {str(value).strip() for value in seeded_declarations if str(value).strip()}
    return {
        declaration: dict(manifest)
        for declaration, manifest in manifests.items()
        if declaration in seeded and isinstance(manifest, Mapping)
    }


def merge_prevalidated_review_signature_manifests(
    requested_declarations: Iterable[str],
    authenticated_manifests: Mapping[str, Mapping[str, Any]],
    legacy_manifests: Mapping[str, Mapping[str, Any]],
) -> tuple[dict[str, dict[str, Any]], dict[str, Any]]:
    """Merge exact current-root carriers without resolving conflicts by priority.

    Both inputs have already passed their own independent validators. This
    function only projects them onto the current requested surface and prevents
    two disagreeing carriers for the same exact declaration from receiving
    prevalidated status. A conflict therefore returns that root to fresh Lean.
    Declaration identities are routing coordinates only; no spelling controls
    how a manifest is interpreted.
    """

    requested = {
        qualified
        for raw_declaration in requested_declarations
        if (
            qualified := semantic_contract_fully_qualified_identity(
                raw_declaration
            )
        )
    }

    def selected(
        manifests: Mapping[str, Mapping[str, Any]],
    ) -> dict[str, dict[str, Any]]:
        candidates: dict[str, dict[str, Any]] = {}
        ambiguous: set[str] = set()
        for raw_declaration, raw_manifest in manifests.items():
            qualified = semantic_contract_fully_qualified_identity(
                raw_declaration
            )
            if (
                not qualified
                or qualified not in requested
                or not isinstance(raw_manifest, Mapping)
            ):
                continue
            if qualified in candidates:
                ambiguous.add(qualified)
                candidates.pop(qualified, None)
                continue
            if qualified not in ambiguous:
                candidates[qualified] = dict(raw_manifest)
        return candidates

    authenticated = selected(authenticated_manifests)
    legacy = selected(legacy_manifests)
    conflicts = {
        qualified
        for qualified in authenticated.keys() & legacy.keys()
        if authenticated[qualified] != legacy[qualified]
    }
    identical_overlaps = (
        authenticated.keys() & legacy.keys()
    ) - conflicts
    accepted = {
        qualified: manifest
        for qualified, manifest in authenticated.items()
        if qualified not in conflicts
    }
    for qualified, manifest in legacy.items():
        if qualified not in conflicts and qualified not in accepted:
            accepted[qualified] = manifest

    authenticated_accepted = set(authenticated) - conflicts
    legacy_only_accepted = set(legacy) - set(authenticated) - conflicts
    diagnostics = {
        "schema": 1,
        "requested_count": len(requested),
        "authenticated_candidate_count": len(authenticated),
        "legacy_candidate_count": len(legacy),
        "authenticated_accepted_count": len(authenticated_accepted),
        "legacy_only_accepted_count": len(legacy_only_accepted),
        "identical_overlap_count": len(identical_overlaps),
        "conflict_count": len(conflicts),
        "conflicting_declarations": sorted(conflicts),
        "accepted_count": len(accepted),
        "fresh_required_count": len(requested - set(accepted)),
    }
    return accepted, diagnostics


def source_record_current_manifest_resume_bindings(
    *,
    paper_dir: Path,
    qualified_row_refs: Mapping[str, str],
    selected_row_source_paths: Mapping[str, Path],
    source_text_by_path: Mapping[Path, str],
) -> tuple[dict[str, dict[str, Any]], set[str]]:
    """Build exact current journal bindings from the frozen review sources."""

    try:
        from scripts import review_dashboard as dashboard
    except Exception:  # noqa: BLE001 - unavailable parser is a cache miss.
        return {}, set(qualified_row_refs.values())
    return _current_manifest_resume_bindings(
        paper_dir=paper_dir,
        qualified_row_refs=qualified_row_refs,
        selected_row_source_paths=selected_row_source_paths,
        source_text_by_path=source_text_by_path,
        parse_review_source_declarations=(
            dashboard.parse_review_source_declarations
        ),
    )


def preprime_source_record_manifest_resume_cache(
    args: argparse.Namespace,
    root: Path,
    paper_dir: Path,
    *,
    lean_import_closure: SourceRecordLeanImportClosure,
) -> dict[str, dict[str, Any]]:
    """Prime only an authenticated current-source manifest cache before raw work.

    This is deliberately outside the marker-delimited raw producer.  It reads
    the same frozen source bytes that the producer will later consume, then
    permits reuse only through the tracked authority/carrier and an exact
    current context.  Its result is a performance hint: every unavailable,
    stale, or ambiguous binding returns an empty mapping and the raw producer
    obtains fresh Lean manifests normally.
    """

    if bool(args.no_lean):
        return {}
    try:
        authenticated_source_text = source_record_lean_import_closure_source_text(
            lean_import_closure
        )
        status_path = paper_dir / "status.json"
        interface_path = review_source_path(root, paper_dir, status_path)
        if not interface_path.exists():
            return {}
        interface_text = authenticated_source_text[interface_path.resolve()]
        import_module = lean_module_name(root, interface_path)
        row_namespace = first_declaration_namespace(
            interface_path, source_text=interface_text
        )
        configured_rows = parse_status_machine_rows(status_path)
        interface_declarations = parse_declarations(
            interface_path, source_text=interface_text
        )
        assumptions_path = effective_source_record_assumption_path(
            root,
            paper_dir,
            status_path,
            interface_path=interface_path,
            lean_import_closure=lean_import_closure,
        )
        assumption_declarations: dict[str, str] = {}
        assumption_namespace = ""
        if assumptions_path is not None and assumptions_path.exists():
            assumption_text = authenticated_source_text.get(
                assumptions_path.resolve()
            )
            if assumption_text is None:
                return {}
            assumption_namespace = first_declaration_namespace(
                assumptions_path, source_text=assumption_text
            )
            assumption_declarations = parse_declarations(
                assumptions_path, source_text=assumption_text
            )

        qualified_row_refs: dict[str, str] = {}
        selected_row_source_paths: dict[str, Path] = {}
        for row in configured_rows:
            try:
                interface_match = resolve_declaration_reference(
                    row,
                    interface_declarations,
                    preferred_namespace=row_namespace,
                )
                assumption_match = resolve_declaration_reference(
                    row,
                    assumption_declarations,
                    preferred_namespace=assumption_namespace,
                )
            except ValueError:
                continue
            matches = [
                name for name in (interface_match, assumption_match) if name
            ]
            if len(set(matches)) != 1:
                continue
            qualified = matches[0]
            qualified_row_refs[row] = qualified
            selected_row_source_paths[row] = (
                assumptions_path
                if qualified in assumption_declarations
                else interface_path
            )

        canonical_lean_files = paper_interface_import_closure_lean_files(
            root,
            interface_path,
            lean_import_closure=lean_import_closure,
        )
        local_lean_files = [
            path
            for path in canonical_lean_files
            if path == interface_path.resolve() or paper_dir.resolve() in path.parents
        ]
        semantic_dependency_modules = tuple(
            sorted(lean_module_name(root, path) for path in local_lean_files)
        )
        if not semantic_dependency_modules:
            return {}
        current_bindings, binding_duplicates = (
            source_record_current_manifest_resume_bindings(
                paper_dir=paper_dir,
                qualified_row_refs=qualified_row_refs,
                selected_row_source_paths=selected_row_source_paths,
                source_text_by_path=authenticated_source_text,
            )
        )
        for duplicate in binding_duplicates:
            current_bindings.pop(duplicate, None)
        local_declarations = parse_local_declarations(
            root,
            local_lean_files,
            source_text_by_path=authenticated_source_text,
        )
        local_bindings, local_binding_duplicates = (
            _local_declaration_manifest_bindings(
                root=root,
                paper_dir=paper_dir,
                declarations=local_declarations,
            )
        )
        for duplicate in local_binding_duplicates:
            local_bindings.pop(duplicate, None)
        # Configured review roots use the dashboard parser contract.  Every
        # other paper-local root uses the raw producer's exact frozen parser
        # coordinate, so the next raw scan can attest all reached manifests
        # rather than only the source-facing subset.
        local_bindings.update(current_bindings)
        current_bindings = local_bindings
        current_context = signature_manifest_cache_context(
            root,
            import_module,
            build_timeout_seconds=SOURCE_RECORD_LAKE_BUILD_TIMEOUT_SECONDS,
            semantic_dependency_modules=semantic_dependency_modules,
        )
        if not isinstance(current_context, Mapping):
            return {}
        manifests, diagnostics = prime_source_record_signature_manifest_store(
            root,
            paper_dir,
            import_module=import_module,
            semantic_dependency_modules=semantic_dependency_modules,
            current_context=current_context,
            current_bindings=current_bindings,
        )
        if diagnostics.get("seeded_count") != len(manifests):
            return {}
        rejected_by_reason = diagnostics.get("rejected_by_reason")
        rejection_summary = ""
        if isinstance(rejected_by_reason, Mapping) and rejected_by_reason:
            rejection_summary = "; misses: " + ", ".join(
                f"{reason}={len(declarations)}"
                for reason, declarations in sorted(rejected_by_reason.items())
                if isinstance(declarations, list)
            )
        source_record_progress(
            "authenticated manifest-store exact-context prime finished "
            f"({len(manifests)} roots seeded; "
            f"{int(diagnostics.get('fresh_required_count') or 0)} "
            f"require fresh Lean{rejection_summary})"
        )
        return manifests
    except Exception as exc:  # noqa: BLE001 - cache failure remains a miss.
        source_record_progress(
            "authenticated manifest-store exact-context prime unavailable: "
            + type(exc).__name__
        )
        return {}


def prime_source_record_signature_manifest_store(
    root: Path,
    paper_dir: Path,
    *,
    import_module: str | None = None,
    semantic_dependency_modules: tuple[str, ...] = (),
    current_context: Mapping[str, Any] | None = None,
    current_bindings: Mapping[str, Mapping[str, Any]] | None = None,
) -> tuple[dict[str, dict[str, Any]], dict[str, Any]]:
    """Prime current roots only through exact-context journal attestation.

    A stale source-record artifact cannot authenticate its own old rows.  The
    narrow compatibility route instead takes the current parser's exact
    declaration binding, requires the local checkpoint to match it exactly,
    and then asks the shared authority helper to validate the checkpoint's
    Lean payload against the tracked authority/carrier and current compiled
    context.  The journal alone remains non-crediting; absent or changed
    inputs return a normal fresh-Lean miss.
    """

    try:
        from scripts import review_dashboard as dashboard
        return _prime_signature_manifest_store(
            root=root,
            paper_dir=paper_dir,
            import_module=import_module,
            semantic_dependency_modules=semantic_dependency_modules,
            current_context=current_context,
            current_bindings=current_bindings,
            resume_records_provider=dashboard.current_manifest_resume_records,
            attester=prime_exact_context_attested_resume_manifests,
        )
    except Exception:  # noqa: BLE001 - failed cache optimization is a miss.
        binding_count = len(current_bindings or {})
        return {}, {
            "schema": 1,
            "paper": paper_dir.name,
            "candidate_count": 0,
            "context_count": 0,
            "accepted_context_count": 0,
            "context_provider_call_count": 0,
            "seeded_count": 0,
            "seeded_declarations": [],
            "fresh_required_count": binding_count,
            "rejected_by_reason": {},
            "store_status": "resume_attestation_unavailable",
        }


def publish_source_record_signature_manifest_store(
    *,
    root: Path,
    paper_dir: Path,
    import_module: str,
    semantic_dependency_modules: tuple[str, ...],
    configured_review_rows: Iterable[Mapping[str, Any]],
    manifests: Mapping[str, Mapping[str, Any]],
    context: Mapping[str, Any] | None = None,
    configured_source_bindings: Mapping[str, Mapping[str, Any]] | None = None,
) -> set[str]:
    """Merge every exact manifest validated by a successful full raw scan.

    Configured review roots retain their stronger raw-row binding. Effective
    analysis targets and structurally reached model declarations have no
    source-facing row of their own, so their cache authority binds the exact
    elaborated signature, semantic dependency closure, and proposition graph
    emitted by the same successful scan. Other producers can own additional
    review roots in the same authenticated store; a source-record subset must
    not delete those unmentioned entries. A later run still validates the
    complete store and projects entries onto its independently reconstructed
    current request set.
    """

    if context is None:
        context = signature_manifest_cache_context(
            root,
            import_module,
            build_timeout_seconds=SOURCE_RECORD_LAKE_BUILD_TIMEOUT_SECONDS,
            semantic_dependency_modules=semantic_dependency_modules,
        )
    if not isinstance(context, Mapping):
        return set()
    return _publish_signature_manifest_store(
        root=root,
        paper_dir=paper_dir,
        import_module=import_module,
        semantic_dependency_modules=semantic_dependency_modules,
        configured_review_rows=configured_review_rows,
        manifests=manifests,
        context=context,
        configured_source_bindings=configured_source_bindings,
        merger=merge_authenticated_manifest_store,
        signature_digest=signature_manifest_digest,
        dependency_manifest=semantic_dependency_manifest,
    )


def checkpoint_source_record_manifest_resume_cache(
    *,
    paper_dir: Path,
    context: Mapping[str, Any],
    published_declarations: Iterable[str],
    resume_bindings: Mapping[str, Mapping[str, Any]],
    manifests: Mapping[str, Mapping[str, Any]],
) -> set[str]:
    """Checkpoint only source-bound raw roots accepted by store publication.

    A completed source-record scan first writes its authority/carrier pair.
    This best-effort follow-up copies only the map-derived configured roots
    whose current raw manifest was accepted by that publication into the
    ignored resume journal.  The journal cannot grant evidence credit: the
    next run will independently reconstruct the same source binding and must
    still obtain the matching authority, carrier, compiled context, and Lean
    dependency artifacts through the shared attester.
    """

    try:
        from scripts import review_dashboard as dashboard
        return _checkpoint_manifest_resume_cache(
            paper_dir=paper_dir,
            context=context,
            published_declarations=published_declarations,
            resume_bindings=resume_bindings,
            manifests=manifests,
            checkpoint=dashboard.checkpoint_manifest_resume_records,
        )
    except Exception as exc:  # noqa: BLE001 - cache persistence is a miss.
        source_record_progress(
            "authenticated manifest-store resume checkpoint unavailable: "
            + type(exc).__name__
        )
        return set()


def publish_current_source_record_manifest_store(
    *,
    args: argparse.Namespace,
    root: Path,
    paper_dir: Path,
    import_module: str,
    semantic_dependency_modules: tuple[str, ...],
    configured_review_rows: Iterable[Mapping[str, Any]],
    manifests: Mapping[str, Mapping[str, Any]],
    resume_bindings: Mapping[str, Mapping[str, Any]] | None = None,
) -> set[str]:
    """Publish a successful canonical raw scan as future cache authority.

    This is deliberately orchestration outside the raw-producer identity.  It
    consumes the exact manifests that the completed raw scan already checked;
    publication and its non-authoritative resume checkpoint are performance
    optimizations, and no failed or diagnostic-only run may create durable
    cache authority or a new checkpoint.
    """

    if bool(args.no_lean) or bool(getattr(args, "stdout", False)):
        return set()
    try:
        context = signature_manifest_cache_context(
            root,
            import_module,
            build_timeout_seconds=SOURCE_RECORD_LAKE_BUILD_TIMEOUT_SECONDS,
            semantic_dependency_modules=semantic_dependency_modules,
        )
        if not isinstance(context, Mapping):
            return set()
        published = publish_source_record_signature_manifest_store(
            root=root,
            paper_dir=paper_dir,
            import_module=import_module,
            semantic_dependency_modules=semantic_dependency_modules,
            configured_review_rows=configured_review_rows,
            manifests=manifests,
            context=context,
            configured_source_bindings=resume_bindings,
        )
    except Exception as exc:  # noqa: BLE001 - publication must not alter a valid raw scan.
        source_record_progress(
            "authenticated manifest-store publication unavailable: "
            + type(exc).__name__
        )
        return set()
    source_record_progress(
        "authenticated manifest-store publication finished "
        f"({len(published)} manifests)"
    )
    if published and resume_bindings:
        checkpointed = checkpoint_source_record_manifest_resume_cache(
            paper_dir=paper_dir,
            context=context,
            published_declarations=published,
            resume_bindings=resume_bindings,
            manifests=manifests,
        )
        source_record_progress(
            "authenticated manifest-store resume checkpoint finished "
            f"({len(checkpointed)} source-bound manifests)"
        )
    return published


def _source_record_static_statement_sidecar_entry(
    paper_dir: Path, row: str, dashboard: Any
) -> dict[str, Any] | None:
    """Load one current statement-sidecar row without dashboard extraction."""

    try:
        path = dashboard.llm_statement_judgments_file(paper_dir)
    except (OSError, ValueError):
        return None
    payload = load_json_object(path)
    if (
        not isinstance(payload, dict)
        or payload.get("schema") != 1
        or payload.get("paper") not in {None, paper_dir.name}
        or dashboard.is_non_evidence_scaffold_payload(payload)
    ):
        return None
    items = payload.get("items")
    if not isinstance(items, dict):
        return None
    raw = items.get(row)
    if not isinstance(raw, dict):
        return None

    item_prompt = str(
        raw.get("prompt_version") or payload.get("prompt_version") or ""
    ).strip()
    if item_prompt != dashboard.REQUIRED_LLM_STATEMENT_PROMPT_VERSION:
        return None
    has_validator = bool(
        raw.get("validator")
        or raw.get("model")
        or raw.get("judge")
        or raw.get("agent")
        or raw.get("generator")
        or payload.get("validator")
        or payload.get("model")
        or payload.get("judge")
        or payload.get("agent")
        or payload.get("generator")
    )
    has_validated_at = bool(
        raw.get("validated_at")
        or raw.get("timestamp")
        or raw.get("generated_at")
        or payload.get("validated_at")
        or payload.get("timestamp")
        or payload.get("generated_at")
    )
    if not has_validator or not has_validated_at:
        return None
    return raw


def current_direct_statement_ledger_covered_boundary_input_keys_without_lean(
    root: Path,
    paper_dir: Path,
    raw_audit: Mapping[str, Any],
) -> set[str] | None:
    """Revalidate current direct-ledger credit with no Lean or source scan.

    The aggregate cache has already authenticated the raw audit, current source
    map semantic receipt, and current PaperInterface bytes.  This additional
    lane rereads only current map/sidecar files plus a previously generated
    signature-manifest cache.  Exact fully-qualified map routes and raw
    declaration/signature identities locate the relevant row; atom-by-atom
    statement evidence and source-route pins establish semantic credit.  It
    never infers coverage from a row or function name.

    ``None`` means the cheap lane lacks an authenticated static prerequisite,
    so callers must regenerate the raw Lean-checked surface.  It intentionally
    does not call the dashboard's current-signature API, which can run Lake.
    """

    saved_coverages = source_record_saved_statement_ledger_coverages(raw_audit)
    if saved_coverages is None:
        return None
    saved_direct_keys, _saved_precloseout_keys = saved_coverages
    if not saved_direct_keys:
        return set()

    boundary_items = raw_audit.get("boundary_input_items")
    dependencies = raw_audit.get("conclusion_dependency_items")
    if not isinstance(boundary_items, list) or not isinstance(dependencies, list):
        return None
    boundary_by_key: dict[str, dict[str, Any]] = {}
    for raw_item in boundary_items:
        if not isinstance(raw_item, dict):
            return None
        key = str(raw_item.get("judgment_key") or "").strip()
        if not key or key in boundary_by_key:
            return None
        boundary_by_key[key] = raw_item
    if not saved_direct_keys <= set(boundary_by_key):
        return None
    protected_dependency_keys: set[str] = set()
    for raw_item in dependencies:
        if not isinstance(raw_item, dict):
            return None
        key = str(raw_item.get("judgment_key") or "").strip()
        if key:
            protected_dependency_keys.add(key)

    try:
        root_text = str(root)
        if root_text not in sys.path:
            sys.path.insert(0, root_text)
        from scripts import review_dashboard as dashboard
    except Exception:
        return None
    current_interface = _source_record_static_current_interface_declarations(
        root, paper_dir, dashboard
    )
    if current_interface is None:
        return None
    (
        interface_path,
        interface_source_sha256,
        current_interface_declarations,
    ) = current_interface
    source_inventory_and_routes = _source_record_static_direct_statement_inventory(
        paper_dir,
        dashboard,
        current_interface_declarations=current_interface_declarations,
    )
    if source_inventory_and_routes is None:
        return None
    (
        source_inventory,
        direct_source_keys_by_qualified,
        semantic_contract_direct_evidence_identities_by_qualified,
    ) = source_inventory_and_routes
    manifest_rows = _source_record_static_statement_manifest_rows(
        paper_dir,
        dashboard,
        interface_path=interface_path,
        interface_source_sha256=interface_source_sha256,
    )
    if manifest_rows is None:
        return None
    try:
        drafts = dashboard.load_llm_lean_to_tex_drafts(paper_dir)
    except Exception:
        return None

    # Build only the exact row identities that previously suppressed at least
    # one input.  A malformed unrelated cached dashboard row cannot create or
    # remove credit for this raw audit.
    row_receipts: dict[str, tuple[str, str, str, set[str]]] = {}
    for key in sorted(saved_direct_keys):
        item = boundary_by_key[key]
        row = str(item.get("row") or "").strip()
        reviewed_identity = reviewed_declaration_identity_key(
            item.get("reviewed_declaration_identity")
        )
        if not row or reviewed_identity is None:
            return None
        qualified, declaration_sha256 = reviewed_identity
        current_declaration = current_interface_declarations.get(qualified)
        if (
            current_declaration is None
            or current_declaration[0] != declaration_sha256
        ):
            return None
        if str(item.get("effective_qualified_declaration") or "").strip() != qualified:
            return None
        raw_signatures = item.get("reviewed_elaborated_signature_identities")
        if not isinstance(raw_signatures, list):
            return None
        signatures = {
            str(raw_signature.get("elaborated_signature_sha256") or "").strip().lower()
            for raw_signature in raw_signatures
            if isinstance(raw_signature, dict)
            and semantic_contract_fully_qualified_identity(
                raw_signature.get("qualified_declaration")
            )
            == qualified
            and SHA256_RE.fullmatch(
                str(raw_signature.get("elaborated_signature_sha256") or "").strip()
            )
        }
        if len(signatures) != 1:
            return None
        signature = next(iter(signatures))
        association = item.get("source_contract_association")
        if (
            not isinstance(association, dict)
            or reviewed_declaration_identity_key(
                association.get("reviewed_declaration_identity")
            )
            != reviewed_identity
        ):
            return None
        associated_signature = association.get(
            "reviewed_elaborated_signature_identity"
        )
        if (
            not isinstance(associated_signature, dict)
            or semantic_contract_fully_qualified_identity(
                associated_signature.get("qualified_declaration")
            )
            != qualified
            or str(
                associated_signature.get("elaborated_signature_sha256") or ""
            ).strip().lower()
            != signature
        ):
            return None
        association_mode = str(association.get("association_mode") or "").strip()
        if association_mode == "explicit_source_map_direct_route":
            associated_keys_raw = association.get("source_map_item_keys")
            if not isinstance(associated_keys_raw, list):
                return None
            associated_keys = {
                str(source_key).strip()
                for source_key in associated_keys_raw
                if isinstance(source_key, str) and source_key.strip()
            }
            if len(associated_keys) != len(associated_keys_raw):
                return None
            current_source_keys = direct_source_keys_by_qualified.get(qualified, set())
            if (
                not associated_keys
                or not current_source_keys
                or not associated_keys <= current_source_keys
            ):
                return None
        elif association_mode == "semantic_contract_group_member":
            current_source_keys = (
                _source_record_static_semantic_contract_direct_evidence_source_keys(
                    association,
                    qualified=qualified,
                    signature=signature,
                    current_source_identities=(
                        semantic_contract_direct_evidence_identities_by_qualified
                    ),
                )
            )
            if current_source_keys is None:
                return None
        else:
            return None
        prior = row_receipts.get(row)
        receipt = (
            qualified,
            declaration_sha256,
            signature,
            set(current_source_keys),
        )
        if prior is not None and prior != receipt:
            return None
        row_receipts[row] = receipt

    current_covered_rows: set[str] = set()
    require_source_routes = dashboard.llm_statement_source_routes_required(paper_dir)
    require_direct_expression_semantics_review = (
        dashboard.llm_direct_expression_semantics_review_required(paper_dir)
    )
    for row, (qualified, declaration_sha256, signature, source_keys) in row_receipts.items():
        cached_row = manifest_rows.get(row)
        if not isinstance(cached_row, dict):
            return None
        current_declaration = current_interface_declarations.get(qualified)
        if current_declaration is None or current_declaration[0] != declaration_sha256:
            return None
        cached_header = str(cached_row.get("interface_source") or "").strip()
        cached_line = cached_row.get("line_number")
        if (
            not cached_header
            or cached_header != current_declaration[1]
            or not isinstance(cached_line, int)
            or isinstance(cached_line, bool)
            or cached_line != current_declaration[2]
        ):
            return None
        manifest = cached_row.get("lean_signature_manifest")
        if (
            not isinstance(manifest, dict)
            or str(cached_row.get("lean_signature_sha256") or "").strip().lower()
            != signature
            or str(manifest.get("sha256") or "").strip().lower() != signature
            or dashboard.signature_manifest_digest(manifest) != signature
        ):
            return None
        # The raw full-declaration digest and the cached current header above
        # jointly bind this manifest to the exact fully-qualified configured
        # declaration.  The manifest then binds its Lean-owned semantic atoms
        # to that coordinate without running another Lean process.

        source_statement_digests = {
            dashboard._source_item_coverage_statement(source_inventory[source_key])[1]
            for source_key in source_keys
            if source_key in source_inventory
        }
        if len(source_statement_digests) != 1 or not all(source_statement_digests):
            return None
        source_statement_sha256 = next(iter(source_statement_digests))
        if (
            dashboard.statement_digest(str(cached_row.get("paper_statement") or ""))
            != source_statement_sha256
        ):
            return None

        sidecar = _source_record_static_statement_sidecar_entry(
            paper_dir, row, dashboard
        )
        if sidecar is None:
            continue
        if dashboard._normalize_llm_match_judgment(
            sidecar.get("judgment")
            or sidecar.get("verdict")
            or sidecar.get("status")
            or sidecar.get("matches")
        ) != "matches":
            continue
        if (
            str(sidecar.get("lean_signature_sha256") or "").strip().lower()
            != signature
            or str(sidecar.get("paper_statement_sha256") or "").strip().lower()
            != source_statement_sha256
        ):
            continue
        agent_statement = str(
            drafts.get(row, cached_row.get("agent_statement") or "")
        )
        if (
            str(sidecar.get("tex_statement_sha256") or "").strip().lower()
            != dashboard.statement_digest(agent_statement)
        ):
            continue
        require_definition_review = bool(
            require_source_routes
            and dashboard.direct_source_definition_route_keys(
                sidecar,
                inventory=source_inventory,
                include_direct_expressions=(
                    require_direct_expression_semantics_review
                ),
            )
        )
        if dashboard.semantic_obligation_ledger_error(
            sidecar,
            manifest,
            require_source_definition_semantics_review=require_definition_review,
        ):
            continue
        if require_source_routes and dashboard.source_route_pin_error(
            sidecar,
            inventory=source_inventory,
            require_statement_target=True,
            require_verbatim_source_inputs=(
                dashboard.statement_review_requires_verbatim_source_inputs(
                    sidecar
                )
            ),
        ):
            continue
        current_covered_rows.add(row)

    return {
        key
        for key, item in boundary_by_key.items()
        if str(item.get("row") or "").strip() in current_covered_rows
        and key not in protected_dependency_keys
    }


def saved_source_record_lean_import_closure(
    payload: Mapping[str, Any] | None,
) -> object | None:
    """Return the raw audit's Lean-owned closure receipt, if present."""

    if not isinstance(payload, Mapping):
        return None
    return payload.get(SOURCE_RECORD_LEAN_IMPORT_CLOSURE_FIELD)


def source_record_lean_closure_entry_for_paper(
    root: Path,
    paper_dir: Path,
) -> Path:
    """Return the exact Lean module that exposes every configured audit row.

    ``PaperInterface`` owns the semantic specifications.  When exact proof
    endpoints live in a separate ``ProofInterface``, Lean's normal dependency
    direction is ``ProofInterface -> PaperInterface``.  The authenticated
    source snapshot must therefore be rooted at the proof module so it contains
    both files.  Embedded proof endpoints keep the interface itself as root.

    This selection is structural and paper-independent: it follows the
    configured proof-pair surface and the conventional/configured proof source,
    never a theorem name or a paper-specific exception.
    """

    status_path = paper_dir / "status.json"
    interface_path = review_source_path(root, paper_dir, status_path)
    if not parse_status_proof_endpoint_rows(status_path):
        return interface_path
    proof_path = proof_endpoint_source_path(
        root,
        paper_dir,
        status_path,
        interface_path=interface_path,
    )
    return proof_path or interface_path


def source_record_lean_import_closure_for_paper(
    root: Path,
    paper_dir: Path,
    *,
    provider: WorktreeImportClosureProvider,
    saved_payload: Mapping[str, Any] | None,
    allow_live_lean_graph: bool,
) -> tuple[SourceRecordLeanImportClosure | None, str]:
    """Acquire the one closure shared by fingerprinting and raw extraction."""

    try:
        closure_entry = source_record_lean_closure_entry_for_paper(root, paper_dir)
    except (OSError, ValueError) as exc:
        return None, f"review closure entry is unavailable: {exc}"
    return acquire_source_record_lean_import_closure(
        root,
        closure_entry,
        provider=provider,
        saved_closure=saved_source_record_lean_import_closure(saved_payload),
        allow_live_lean_graph=allow_live_lean_graph,
    )


def current_effective_source_record_review_declarations(
    paper_dir: Path,
    status_path: Path,
    current_preflight_rows: Iterable[Mapping[str, Any]],
) -> tuple[set[str] | None, str]:
    """Reconstruct the exact root set selected by the raw producer.

    ``status.include_names`` also drives displayed support and deep-review
    cards. Those names can belong to separate source/library evidence lanes
    and therefore are not automatically canonical raw roots. Semantic reuse
    must compare the receipt with the producer's effective selection.
    """

    current_preflight_rows = [
        row
        for row in current_preflight_rows
        if isinstance(row, Mapping)
        and str(row.get("row") or "").strip()
        and str(row.get("qualified_declaration") or "").strip()
    ]
    configured_present = [str(row["row"]).strip() for row in current_preflight_rows]
    qualified_row_refs = {
        str(row["row"]).strip(): str(row["qualified_declaration"]).strip()
        for row in current_preflight_rows
    }
    try:
        (
            source_selected_rows,
            _source_contract_statement_map,
            source_selection,
        ) = source_coverage_review_rows(
            paper_dir, configured_present, qualified_row_refs
        )
        explicit_targets, explicit_config_errors = (
            explicit_source_target_declarations_for_semantic_review(status_path)
        )
        explicit_rows, explicit_selection = explicit_source_target_review_rows(
            paper_dir,
            configured_present,
            qualified_row_refs,
            explicit_targets,
        )
        configured_assumption_references = set(
            parse_status_review_surface_names(status_path, ("assumption_names",))
        )
        configured_assumption_rows = [
            row for row in configured_present if row in configured_assumption_references
        ]
        scope_targets, scope_errors = (
            formalization_scope_target_declarations_for_semantic_review(status_path)
        )
        effective_rows, effective_selection = effective_source_record_review_rows(
            source_selected_rows=source_selected_rows,
            configured_present=configured_present,
            qualified_row_refs=qualified_row_refs,
            configured_assumption_rows=configured_assumption_rows,
            formalization_scope_targets=scope_targets,
            explicit_source_target_rows=explicit_rows,
        )
    except (OSError, RuntimeError, TypeError, ValueError) as exc:
        return None, f"current configured review roots are unavailable: {exc}"
    selection_errors = [
        str(source_selection.get("source_coverage_selection_error") or "").strip(),
        str(source_selection.get("source_coverage_mode_error") or "").strip(),
        *[
            str(error).strip()
            for error in source_selection.get("source_coverage_route_errors", [])
            if str(error).strip()
        ],
        *[str(error).strip() for error in explicit_config_errors if str(error).strip()],
        *[
            str(error).strip()
            for error in explicit_selection.get(
                "semantic_model_explicit_source_target_route_errors", []
            )
            if str(error).strip()
        ],
        *[str(error).strip() for error in scope_errors if str(error).strip()],
        *[
            str(error).strip()
            for error in effective_selection.get(
                "semantic_model_scope_target_route_errors", []
            )
            if str(error).strip()
        ],
    ]
    if any(selection_errors):
        return None, "current configured review-root selection is invalid"
    declarations = {
        qualified_row_refs[row] for row in effective_rows if row in qualified_row_refs
    }
    if not declarations:
        return None, "current configured review-root selection is empty"
    return declarations, ""


def current_source_record_semantic_reuse_identity(
    root: Path,
    paper_dir: Path,
    *,
    saved_payload: Mapping[str, Any],
) -> tuple[SourceRecordLeanImportClosure | None, dict[str, Any] | None, str]:
    """Validate a canonical raw receipt against current Lean semantics.

    This is the ordinary fallback after a whole-file closure hash misses.  It
    asks Lean to elaborate every canonical reviewed declaration in the current
    environment and delegates the declaration/dependency comparison to the
    version-independent semantic verifier.  It creates no receipt and no
    human judgment.  In particular, it does not first materialize the former
    whole-import-closure validator: doing so made a harmless source-container
    edit pay the memory and runtime cost of the very identity being replaced.
    """

    status_path = paper_dir / "status.json"
    try:
        interface_path = review_source_path(root, paper_dir, status_path)
    except (OSError, ValueError) as exc:
        return None, None, f"review interface is unavailable: {exc}"
    try:
        closure_entry = source_record_lean_closure_entry_for_paper(root, paper_dir)
    except (OSError, ValueError) as exc:
        return None, None, f"review closure entry is unavailable: {exc}"
    try:
        entrypoint = closure_entry.resolve().relative_to(root.resolve()).as_posix()
    except ValueError:
        return None, None, "review interface escapes the repository root"
    saved_closure = saved_source_record_lean_import_closure(saved_payload)
    try:
        validated_saved_closure = validated_lean_import_closure_payload(saved_closure)
    except ValueError as exc:
        return None, None, f"saved Lean import closure is malformed: {exc}"
    # This object exists only to compute the current schema-10 fingerprint.
    # Its closure-dependent fields are explicitly removed by
    # ``semantic_fingerprint_projection`` after Lean has checked all canonical
    # roots.  Current bytes keep the ordinary projection helpers deterministic;
    # the historical record remains provenance and is never accepted as a
    # current byte receipt on this path.
    projection_sources: list[Path] = []
    projection_source_bytes: list[tuple[Path, bytes]] = []
    for raw_source in validated_saved_closure["sources"]:
        if not isinstance(raw_source, Mapping):
            return None, None, "saved Lean import closure has a malformed source"
        relative = str(raw_source.get("path") or "")
        candidate = (root / relative).resolve()
        try:
            candidate.relative_to(root.resolve())
            content = candidate.read_bytes()
        except (OSError, ValueError):
            # Historical path coordinates are provenance. A declaration may
            # move; the current qualified-name elaboration below is authority.
            content = b""
        projection_sources.append(candidate)
        projection_source_bytes.append((candidate, content))
    if interface_path.resolve() not in projection_sources:
        projection_sources.append(interface_path.resolve())
        projection_source_bytes.append(
            (interface_path.resolve(), interface_path.read_bytes())
        )
    current_closure = SourceRecordLeanImportClosure(
        record=validated_saved_closure,
        repository_sources=tuple(sorted(projection_sources)),
        sha256=lean_import_closure_payload_sha256(validated_saved_closure),
        repository_source_bytes=tuple(
            sorted(projection_source_bytes, key=lambda item: item[0])
        ),
    )

    current_preflight = configured_review_reference_static_preflight(root, paper_dir)
    if current_preflight.get("status") != "static_passed":
        return None, None, "current configured review roots are unavailable"
    (
        current_configured_review_declarations,
        current_review_selection_error,
    ) = current_effective_source_record_review_declarations(
        paper_dir,
        status_path,
        current_preflight.get("configured_rows", []),
    )
    if current_configured_review_declarations is None:
        return None, None, current_review_selection_error
    current_semantic_dimensions, current_semantic_dimension_errors = (
        semantic_model_review_config(status_path)
    )
    if current_semantic_dimension_errors:
        return None, None, "current semantic-model review configuration is invalid"
    current_fidelity = source_proof_fidelity_context(paper_dir)
    current_fidelity_defects = (
        current_fidelity.get("defects", [])
        if isinstance(current_fidelity, Mapping)
        else []
    )
    statement_map = load_json_object(paper_dir / "audit" / "paper_statement_map.json")
    current_source_map_defect_ids = {
        str(defect_id).strip()
        for item in (
            statement_map.get("items", {}).values()
            if isinstance(statement_map.get("items"), Mapping)
            else []
        )
        if isinstance(item, Mapping)
        for defect_id in item.get("source_defect_ids", [])
        if isinstance(defect_id, str) and defect_id.strip()
    }
    # A tracked semantic authority is the durable result of this exact
    # declaration-level Lean comparison. Its loader rechecks the canonical raw
    # rows, their semantic identity, and every repository input watched by the
    # successful pass. Consume it before launching Lean again; the caller still
    # runs the independent current statement-map, correspondence, transparent-
    # pair, and strict closeout gates after this function returns.
    raw_path = paper_dir / "audit" / "source_record_audit.json"
    try:
        raw_bytes = raw_path.read_bytes()
        exact_raw_payload = json.loads(raw_bytes)
    except (OSError, UnicodeDecodeError, json.JSONDecodeError):
        exact_raw_payload = None
        raw_bytes = b""
    if exact_raw_payload == saved_payload and raw_bytes:
        authority = load_current_semantic_reuse_authority(
            root=root,
            paper_dir=paper_dir,
            raw_audit_file_sha256=hashlib.sha256(raw_bytes).hexdigest(),
            raw_audit=saved_payload,
        )
        authority_result = authority.result if authority is not None else None
        authority_semantic = (
            authority_result.get("semantic_receipt_reuse")
            if isinstance(authority_result, Mapping)
            else None
        )
        if (
            authority is not None
            and set(authority.reviewed_declarations)
            == current_configured_review_declarations
            and isinstance(authority_semantic, Mapping)
            and authority_semantic.get("current") is True
            and authority_semantic.get("reviewed_declaration_count")
            == len(current_configured_review_declarations)
            and authority_semantic.get("semantic_model_dimension_count")
            == len(current_semantic_dimensions)
            and authority_semantic.get("separately_routed_proof_defect_count")
            == len(current_fidelity_defects)
        ):
            return current_closure, dict(authority_semantic), ""
    try:
        current_import_module = lean_module_name(root, closure_entry)
        paper_relative = paper_dir.resolve().relative_to(root.resolve()).as_posix()
        current_semantic_dependency_modules = tuple(
            sorted(
                {
                    module
                    for relative in index_paths(root)
                    if relative.startswith(paper_relative + "/")
                    for module in (module_name_for_path(relative),)
                    if module is not None
                }
            )
        )
    except (OSError, RuntimeError, ValueError) as exc:
        return None, None, f"current Lean review environment is unavailable: {exc}"

    semantic_reuse, semantic_error = validate_current_semantic_reuse(
        root=root,
        paper_dir=paper_dir,
        raw_audit=saved_payload,
        current_import_module=current_import_module,
        current_semantic_dependency_modules=(
            current_semantic_dependency_modules
        ),
        current_configured_review_declarations=(
            current_configured_review_declarations
        ),
        current_semantic_model_dimension_ids=set(current_semantic_dimensions),
        current_source_proof_fidelity=current_fidelity,
        current_source_map_defect_ids=current_source_map_defect_ids,
        build_timeout_seconds=SOURCE_RECORD_LAKE_BUILD_TIMEOUT_SECONDS,
    )
    if semantic_error or semantic_reuse is None:
        return None, None, semantic_error or "current semantic reuse validation failed"
    return current_closure, semantic_reuse, ""


def reusable_source_record_audit(
    args: argparse.Namespace,
    root: Path,
    paper_dir: Path,
    *,
    paper_statement_map_sha256: str,
    paper_statement_map_semantic_sha256: str | None = None,
    _current_input_fingerprint_capture: list[dict[str, Any]] | None = None,
    lean_import_closure: SourceRecordLeanImportClosure | None = None,
    saved_payload: dict[str, Any] | None = None,
) -> dict[str, Any] | None:
    """Return a successful current aggregate audit when default reuse is safe.

    The private capture is used only by the under-lock fresh-scan caller. It
    receives an independent copy of the exact current fingerprint when this
    cache probe reaches fingerprinting, whether or not the canonical raw audit
    is reusable. Static configured-row blockers return before that expensive
    step. A final post-scan recomputation still owns mutation detection and
    publication.
    """

    if _current_input_fingerprint_capture is not None:
        _current_input_fingerprint_capture.clear()

    if (
        getattr(args, "force", False)
        or args.refresh_judgment_summary
        or args.ignore_current_judgments
        # A no-Lean run is strictly diagnostic.  It must not reuse or publish
        # a canonical audit artifact, even if a legacy no-Lean cache happens
        # to match its input fingerprint.
        or args.no_lean
    ):
        return None
    # Callers normally obtained these values immediately before invoking this
    # helper.  Recompute the inexpensive map receipts here nevertheless: a
    # stale caller-supplied pair must never let a semantic source-map edit
    # cache-hit between that earlier read and this aggregate-cache decision.
    # This is intentionally not a raw or Lean scan.
    current_map_sha256, current_semantic_map_sha256 = (
        paper_statement_map_cache_receipts(paper_dir)
    )
    supplied_semantic_map_sha256 = (
        str(paper_statement_map_semantic_sha256 or "").strip().lower()
        if paper_statement_map_semantic_sha256 is not None
        else None
    )
    if (
        not SHA256_RE.fullmatch(current_map_sha256.strip().lower())
        or not SHA256_RE.fullmatch(current_semantic_map_sha256.strip().lower())
        or paper_statement_map_sha256.strip().lower()
        != current_map_sha256.strip().lower()
        or (
            supplied_semantic_map_sha256 is not None
            and supplied_semantic_map_sha256
            != current_semantic_map_sha256.strip().lower()
        )
    ):
        return None
    paper_statement_map_sha256 = current_map_sha256
    paper_statement_map_semantic_sha256 = current_semantic_map_sha256
    if not (
        SHA256_RE.fullmatch(paper_statement_map_sha256.strip().lower())
        and SHA256_RE.fullmatch(
            str(paper_statement_map_semantic_sha256 or "").strip().lower()
        )
    ):
        return None
    # Resolve configured review references before computing the repository
    # closure/fingerprint. A stale or ambiguous status row is a parser-only
    # blocker and must not spend the expensive cache-admission work merely to
    # fail later with the same deterministic error.
    if configured_review_reference_static_error(root, paper_dir):
        return None
    fingerprint = source_record_input_fingerprint(
        args,
        root,
        paper_dir,
        paper_statement_map_sha256=paper_statement_map_sha256,
        paper_statement_map_semantic_sha256=paper_statement_map_semantic_sha256,
        lean_import_closure=lean_import_closure,
    )
    if fingerprint is None:
        return None
    if _current_input_fingerprint_capture is not None:
        _current_input_fingerprint_capture.append(deepcopy(fingerprint))
    # ``--out`` is a caller transport destination (often a temporary file in
    # audit_repository), never the cache lookup key.  Reusing the canonical
    # paper artifact keeps a fresh aggregate audit available to every caller.
    audit_path = canonical_source_record_audit_path(paper_dir)
    payload = (
        saved_payload
        if isinstance(saved_payload, dict)
        else load_json_object(audit_path)
    )
    if lean_import_closure is not None:
        try:
            stored_closure_sha256 = lean_import_closure_payload_sha256(
                payload.get(SOURCE_RECORD_LEAN_IMPORT_CLOSURE_FIELD)
            )
        except ValueError:
            return None
        if stored_closure_sha256 != lean_import_closure.sha256:
            return None
    stored_fingerprint = payload.get("source_record_input_fingerprint")
    # Exact non-producer identity is the normal fast path. A current semantic
    # verifier may also reproduce every receipt-bound declaration identity;
    # producer hashes remain provenance in either case. Older receipt schemas
    # and materially changed fingerprints take the normal fresh-raw path.
    if not source_record_raw_producer_code_identity_matches(
        stored_fingerprint,
        fingerprint,
        repository_root=REPOSITORY_ROOT,
    ):
        return None
    if (
        payload.get("paper") != args.paper
        or payload.get("prompt_version") != SOURCE_RECORD_PROMPT_VERSION
        or not SHA256_RE.fullmatch(
            str(payload.get("paper_statement_map_sha256") or "").strip().lower()
        )
        or not SHA256_RE.fullmatch(
            str(payload.get("source_record_audit_sha256") or "").strip().lower()
        )
        or source_record_audit_receipt_error(payload)
        or source_record_raw_reusable_item_metadata_error(
            payload,
            expected_item_digest_schema=SOURCE_RECORD_ITEM_DIGEST_SCHEMA,
        )
        or source_record_raw_scan_completeness_error(payload)
    ):
        return None
    lean_check = payload.get("lean_check")
    if not args.no_lean and (
        not isinstance(lean_check, dict) or lean_check.get("returncode") != 0
    ):
        return None
    # A raw source-record surface can suppress ordinary generated inputs when
    # a current direct source-to-Lean statement ledger already covers them.
    # That dynamic sidecar evidence is intentionally outside the expensive
    # input fingerprint, so revalidate it monotonically before reuse: gains
    # are harmless because this raw still retains its old surface, while a
    # loss must force a fresh raw audit.  The partial-status direct/Spec
    # projection has a different status-sensitive contract; until it has an
    # equally cheap exact validator, any saved projection credit disables this
    # aggregate cache path rather than risking retained suppression.
    saved_ledger_coverages = source_record_saved_statement_ledger_coverages(payload)
    if saved_ledger_coverages is None:
        return None
    saved_direct_ledger_keys, saved_precloseout_ledger_keys = saved_ledger_coverages
    if saved_precloseout_ledger_keys:
        return None
    if saved_direct_ledger_keys:
        current_direct_ledger_keys = (
            current_direct_statement_ledger_covered_boundary_input_keys_without_lean(
                root, paper_dir, payload
            )
        )
        if (
            current_direct_ledger_keys is None
            or not saved_direct_ledger_keys <= current_direct_ledger_keys
        ):
            return None
    # Judgments may have changed after the expensive surface was generated.
    # Refreshing this summary is cheap and preserves the exact aggregate audit.
    try:
        return refresh_existing_judgment_summary(
            paper_dir,
            args.paper,
            audit_path,
            paper_statement_map_sha256=paper_statement_map_sha256,
            paper_statement_map_semantic_sha256=paper_statement_map_semantic_sha256,
            write=False,
            payload_override=payload,
        )
    except SystemExit:
        return None


def source_map_semantic_context_requirements(
    paper_dir: Path,
) -> tuple[list[dict[str, Any]], list[str]]:
    """Return only byte-validated source-map context for source-record review.

    The context lane is intentionally separate from all Lean routes and source
    claim coverage. It exposes literal source conventions/domain facts to the
    reviewer, but never adds a judgment key, resolves a dependency, or makes a
    declaration/function name count as evidence.
    """

    map_path = paper_dir / "audit" / "paper_statement_map.json"
    payload = load_json_object(map_path)
    if not payload:
        return [], []
    status = str(load_json_object(paper_dir / "status.json").get("status") or "")
    findings = semantic_context_requirement_findings(
        paper_dir,
        status,
        map_path,
        payload,
        require_source_bytes=True,
    )
    if findings:
        return [], [finding.message for finding in findings]
    return semantic_context_requirements(payload), []


def formalization_scope_context(paper_dir: Path) -> dict[str, Any] | None:
    """Return the audit-relevant identity of an explicit governing target.

    A source-record judgment may only be reused while the governing source
    target is unchanged.  The context deliberately contains provenance and
    semantic scope, not a theorem-name heuristic.
    """

    status = load_json_object(paper_dir / "status.json")
    scope = status.get("formalization_scope")
    if not isinstance(scope, dict):
        return None
    approval = scope.get("approval")
    base_archive = scope.get("base_archive")
    if not isinstance(approval, dict) or not isinstance(base_archive, dict):
        return None
    correction_ids = scope.get("correction_ids")
    targets = scope.get("target_result_declarations")
    if not isinstance(correction_ids, list) or not isinstance(targets, list):
        return None
    model_bindings, model_binding_errors = corrected_model_scope_model_bindings(
        scope,
        target_result_declarations=targets,
    )
    if model_binding_errors or model_bindings is None:
        return None
    governing_corrections = canonical_governing_corrections(status)
    if governing_corrections is None:
        return None
    context = {
        "kind": str(scope.get("kind") or "").strip(),
        "scope_id": str(scope.get("scope_id") or "").strip(),
        "scope_role": str(scope.get("scope_role") or "").strip(),
        "whole_paper_closeout_claimed": scope.get("whole_paper_closeout_claimed"),
        "approval_artifact_path": str(approval.get("artifact_path") or "").strip(),
        "approval_artifact_sha256": str(approval.get("artifact_sha256") or "").strip(),
        "base_archive_path": str(base_archive.get("path") or "").strip(),
        "base_archive_sha256": str(base_archive.get("sha256") or "").strip(),
        "target_result_declarations": sorted(
            str(target).strip() for target in targets if str(target).strip()
        ),
        "correction_ids": sorted(
            str(correction_id).strip()
            for correction_id in correction_ids
            if str(correction_id).strip()
        ),
        "archival_equivalence_claimed": bool(
            scope.get("archival_equivalence_claimed")
        ),
        "governing_corrections_sha256": stable_digest(governing_corrections),
    }
    context.update(corrected_model_scope_model_metadata(model_bindings))
    if not all(
        context[key]
        for key in (
            "kind",
            "scope_id",
            "approval_artifact_path",
            "approval_artifact_sha256",
            "base_archive_path",
            "base_archive_sha256",
        )
    ):
        return None
    context["scope_sha256"] = stable_digest(context)
    return context


_SOURCE_RECORD_JUDGMENT_ITEM_SECTIONS = SOURCE_RECORD_REUSABLE_ITEM_SECTIONS


def current_item_judgment_keys(audit_payload: dict[str, Any]) -> set[str]:
    """Return generated judgment keys eligible under aggregate freshness."""

    keys: set[str] = set()
    for section in _SOURCE_RECORD_JUDGMENT_ITEM_SECTIONS:
        raw_items = audit_payload.get(section) or []
        if not isinstance(raw_items, list):
            continue
        for item in raw_items:
            if isinstance(item, dict):
                key = str(item.get("judgment_key") or "").strip()
                if key:
                    keys.add(key)
    return keys


def current_item_digest_candidates(audit_payload: dict[str, Any]) -> dict[str, set[str]]:
    """Return every eligible digest seen for each current judgment key.

    A key that occurs in multiple generated sections must retain one identical
    full item receipt to use scalar item freshness.  Whether another key shares
    that digest is deliberately not decided here: direct same-key reuse is
    safe, while key-independent remapping needs a separate uniqueness check.
    """

    candidate_digests: dict[str, set[str]] = {}
    for section in _SOURCE_RECORD_JUDGMENT_ITEM_SECTIONS:
        raw_items = audit_payload.get(section) or []
        if not isinstance(raw_items, list):
            continue
        for item in raw_items:
            if not isinstance(item, dict):
                continue
            if not source_record_item_reuse_eligible(
                item,
                expected_item_digest_schema=SOURCE_RECORD_ITEM_DIGEST_SCHEMA,
            ):
                continue
            key = str(item.get("judgment_key") or "").strip()
            digest = str(item.get("source_record_item_sha256") or "").strip()
            if key and digest:
                candidate_digests.setdefault(key, set()).add(digest)
    return candidate_digests


def current_item_digests(audit_payload: dict[str, Any]) -> dict[str, str]:
    """Return a single complete current receipt for each judgment key.

    A visible theorem input can also be a richer conclusion-dependency item.
    If the two generated surfaces have different digests, an item-level sidecar
    judgment cannot demonstrate which surface it reviewed. Such a key must
    therefore validate through the current aggregate audit digest, rather than
    inheriting freshness from the weaker boundary-only item.

    A digest shared by *different* keys does not invalidate direct reuse: the
    sidecar key selects the current item, and the complete receipt proves that
    item's source and Lean surfaces are unchanged.  It is deliberately not
    enough for a storage-key rename; see ``current_unique_item_digest_keys``.
    """

    return {
        key: next(iter(digests))
        for key, digests in current_item_digest_candidates(audit_payload).items()
        if len(digests) == 1
    }


def current_unique_item_digest_keys(audit_payload: dict[str, Any]) -> dict[str, str]:
    """Return only digest-to-key bindings safe for a name-independent remap.

    A renamed sidecar key has no direct current-key binding, so it can move
    only when its schema-5 item digest identifies exactly one current judgment
    key.  This is intentionally stricter than direct same-key reuse and never
    uses a theorem, binder, or source-map name as a tie-breaker.
    """

    keys_by_digest: dict[str, set[str]] = {}
    for key, digest in current_item_digests(audit_payload).items():
        keys_by_digest.setdefault(digest, set()).add(key)
    return {
        digest: next(iter(keys))
        for digest, keys in keys_by_digest.items()
        if len(keys) == 1
    }


def source_record_payload_is_non_evidence(payload: dict[str, Any]) -> bool:
    """Keep draft/candidate sidecars out of saved source-record evidence."""

    if any(
        bool(payload.get(marker))
        for marker in (
            "candidate_only",
            "not_evidence",
            "must_not_be_written_to_repository_sidecar",
            "non_evidence_scaffold",
        )
    ):
        return True
    artifact_kind = str(payload.get("artifact_kind") or "").strip().lower()
    if "candidate" in artifact_kind or "proposal" in artifact_kind:
        return True
    validator_type = str(payload.get("validator_type") or "").strip().lower()
    return "candidate" in validator_type or "proposal" in validator_type


def _authenticated_overlay_union_module() -> Any:
    """Load the one overlay authority only when a paper has an overlay."""

    try:
        from scripts import source_record_authenticated_overlay_union as overlay_union
    except ModuleNotFoundError:  # pragma: no cover - direct-script fallback.
        import source_record_authenticated_overlay_union as overlay_union
    return overlay_union


def current_source_record_judgments_from_payload(
    payload: dict[str, Any],
    paper: str,
    audit_payload: dict[str, Any],
    *,
    paper_dir: Path | None = None,
    authenticated_overlay_lane: object | None = None,
) -> dict[str, dict[str, Any]]:
    """Validate one ordinary sidecar or centrally loaded reuse overlay payload.

    The ordinary schema-5 path remains exactly as before, including its
    unique-digest rename handling. A loaded migration overlay is narrower: it
    has already recomputed an exact direct-key full-semantic descriptor, so it
    may never take the rename path even when a digest happens to be unique.
    A multi-surface item that overrides a stale sidecar root is narrower still:
    it needs a receipt-specific current validator rather than an aggregate-hash
    rewrite.
    """

    if payload.get("schema") != 1 or payload.get("paper") not in {None, paper}:
        return {}
    if source_record_payload_is_non_evidence(payload):
        return {}
    ordinary_protocol_current = formalization_judgment_review_protocol_is_current(
        audit_payload, payload
    )
    raw_items = payload.get("items") or payload.get("field_judgments") or {}
    if not isinstance(raw_items, dict):
        return {}
    overlay_union = None
    if authenticated_overlay_lane is not None:
        overlay_union = _authenticated_overlay_union_module()
        if (
            not isinstance(
                authenticated_overlay_lane,
                overlay_union.AuthenticatedCurrentOverlayLane,
            )
            or raw_items is not authenticated_overlay_lane.items
        ):
            return {}

    required_prompt_version = str(audit_payload.get("prompt_version") or "").strip()
    required_audit_digest = str(audit_payload.get("source_record_audit_sha256") or "").strip()
    if not required_audit_digest:
        return {}
    required_item_digests = current_item_digests(audit_payload)
    multi_surface_item_keys = {
        key
        for key, digests in current_item_digest_candidates(audit_payload).items()
        if len(digests) > 1
    }
    required_item_keys = current_item_judgment_keys(audit_payload)
    payload_prompt_version = str(payload.get("prompt_version") or "").strip()
    payload_audit_digest = str(payload.get("source_record_audit_sha256") or "").strip()
    payload_validator = payload.get("validator") or payload.get("model") or payload.get("judge")
    payload_timestamp = payload.get("validated_at") or payload.get("timestamp") or payload.get(
        "generated_at"
    )

    expected_key_by_unique_item_digest = current_unique_item_digest_keys(audit_payload)
    out: dict[str, dict[str, Any]] = {}

    for key, value in raw_items.items():
        if not isinstance(value, dict):
            continue
        if source_record_payload_is_non_evidence(value):
            continue
        if archived_source_record_transport_item_field(value):
            continue
        raw_key = str(key)
        loaded_overlay_entry = bool(
            authenticated_overlay_lane is not None
            and overlay_union is not None
            and overlay_union.authenticated_current_overlay_item(
                authenticated_overlay_lane, value
            )
        )
        if authenticated_overlay_lane is not None and not loaded_overlay_entry:
            continue
        if (
            authenticated_overlay_lane is None
            and serialized_source_record_overlay_labels(value)
        ):
            # A copied overlay JSON object is not ordinary schema-5 evidence.
            # Only the centralized loader can attach the private in-memory
            # authorization used by the overlay path below.
            continue
        if not loaded_overlay_entry and not ordinary_protocol_current:
            continue
        item_prompt_version = str(
            value.get("prompt_version") or payload_prompt_version
        ).strip()
        item_audit_digest = str(
            value.get("source_record_audit_sha256") or payload_audit_digest
        ).strip()
        item_digest = str(value.get("source_record_item_sha256") or "").strip()
        item_digest_schema = value.get("source_record_item_digest_schema")
        required_item_digest = required_item_digests.get(raw_key)
        if not item_audit_digest:
            continue
        audit_digest_current = bool(
            required_audit_digest and item_audit_digest == required_audit_digest
        )
        if (
            raw_key in multi_surface_item_keys
            and audit_digest_current
            and payload_audit_digest != required_audit_digest
        ):
            continue
        if (
            (loaded_overlay_entry and required_item_keys and raw_key not in required_item_keys)
            or (
                not loaded_overlay_entry
                and audit_digest_current
                and required_item_keys
                and raw_key not in required_item_keys
            )
        ):
            # A current aggregate digest does not authorize arbitrary extra
            # sidecar entries.  The entry must still correspond to a generated
            # current judgment key.
            continue
        if loaded_overlay_entry:
            # Authenticated overlays recompute a complete generated semantic
            # descriptor against ``audit_payload``. Do not let historical
            # aggregate provenance fall through to ordinary freshness/remap.
            item_digest_current = True
            audit_digest_current = False
        else:
            item_digest_current = source_record_item_judgment_current(
                aggregate_current=audit_digest_current,
                expected_item_digest=required_item_digest,
                judgment_item_digest=item_digest,
                judgment_item_digest_schema=item_digest_schema,
            )
        # A storage-key rename is not a mathematical change.  New-schema
        # judgments can therefore move to a current key only through one
        # unique source+signature+obligation digest, never through a matching
        # declaration suffix, binder spelling, or map key.
        resolved_key = raw_key
        if (
            not loaded_overlay_entry
            and not item_digest_current
            and not audit_digest_current
        ):
            candidate_key = expected_key_by_unique_item_digest.get(item_digest)
            if candidate_key is not None:
                item_digest_current = source_record_item_judgment_current(
                    aggregate_current=False,
                    expected_item_digest=required_item_digests.get(candidate_key),
                    judgment_item_digest=item_digest,
                    judgment_item_digest_schema=item_digest_schema,
                )
                if item_digest_current:
                    resolved_key = candidate_key
        if item_prompt_version != required_prompt_version or not item_digest_current:
            continue
        validator = (
            value.get("validator")
            or value.get("model")
            or value.get("judge")
            or payload_validator
        )
        timestamp = (
            value.get("validated_at")
            or value.get("timestamp")
            or value.get("generated_at")
            or payload_timestamp
        )
        if validator and timestamp:
            # Multiple stale sidecar keys must not race to satisfy one current
            # item.  An aggregate-current judgment retains its original key;
            # a semantic-ID remap is accepted only when it is unique above.
            if resolved_key in out:
                continue
            updates = {
                "prompt_version": item_prompt_version,
                "source_record_audit_sha256": item_audit_digest,
                "source_record_item_sha256": item_digest,
                "source_record_item_digest_schema": item_digest_schema,
            }
            out[resolved_key] = (
                overlay_union.copy_authenticated_current_overlay_item(
                    authenticated_overlay_lane, value, updates
                )
                if loaded_overlay_entry
                and overlay_union is not None
                and authenticated_overlay_lane is not None
                else {**value, **updates}
            )
    return out


def current_source_record_judgments(
    paper_dir: Path, paper: str, audit_payload: dict[str, Any]
) -> dict[str, dict[str, Any]]:
    """Load ordinary judgments plus authenticated narrow-reuse overlays."""

    if archived_source_record_transport_artifacts(paper_dir):
        return {}
    path = paper_dir / "audit" / "source_record_match_llm.json"
    if not path.exists():
        path = paper_dir / "source_record_match_llm.json"
    sidecar_payload = load_json_object(path)
    ordinary = current_source_record_judgments_from_payload(
        sidecar_payload, paper, audit_payload, paper_dir=paper_dir
    )
    consumed_overlay_labels = (
        "differential",
        "semantic_rebind",
    )
    present_overlay_labels = source_record_overlay_labels_with_artifacts(
        paper_dir, lane_labels=consumed_overlay_labels
    )
    overlay_current: dict[str, dict[str, dict[str, Any]]] = {}
    if present_overlay_labels:
        overlay_union = _authenticated_overlay_union_module()
        try:
            lanes = overlay_union.load_authenticated_current_overlay_lanes(
                paper_dir,
                paper,
                audit_payload,
                lane_labels=present_overlay_labels,
            )
        except overlay_union.SourceRecordAuthenticatedOverlayUnionError:
            return {}
        for lane in lanes:
            overlay_current[lane.label] = current_source_record_judgments_from_payload(
                {"schema": 1, "paper": paper, "items": lane.items},
                paper,
                audit_payload,
                authenticated_overlay_lane=lane,
            )
    # An overlay remains authoritative over stale ordinary evidence, but a
    # separately validated ordinary response with the exact live aggregate
    # receipt is newer evidence and must win over every overlay lane.
    current_raw_digest = str(audit_payload.get("source_record_audit_sha256") or "").strip()
    ordinary_with_current_receipt = {
        key: value
        for key, value in ordinary.items()
        if current_raw_digest
        and str(value.get("source_record_audit_sha256") or "").strip()
        == current_raw_digest
    }
    effective = {
        **ordinary,
        **overlay_current.get("differential", {}),
        # Schema 2 replays byte-pinned inputs and a full current semantic
        # descriptor, so it is stronger than the legacy differential lane.
        # Independently reviewed ordinary current evidence still wins last.
        **overlay_current.get("semantic_rebind", {}),
        **ordinary_with_current_receipt,
    }
    current_v10_surface = (
        audit_payload.get("prompt_version") == SOURCE_RECORD_PROMPT_VERSION
        and audit_payload.get("source_record_policy_version")
        == SOURCE_RECORD_PROMPT_VERSION
    )
    coverage_error = (
        canonical_source_record_sidecar_effective_coverage_error(
            audit_payload,
            sidecar_payload,
            effective_items=effective,
            paper_dir=paper_dir,
            sidecar_path=path,
        )
        if current_v10_surface
        else ""
    )
    if coverage_error:
        # A canonical sidecar may serialize a partial review only through the
        # explicit manual-complement provenance path.  Returning no current
        # judgments keeps the generator from turning an arbitrary fragment
        # into resolved proof debt or a refreshed aggregate summary.
        return {}
    return effective


def current_direct_statement_ledger_covered_rows(
    root: Path, paper_dir: Path
) -> set[str]:
    """Return current direct source-to-Lean rows eligible for ordinary input credit.

    This is deliberately a source-map and current-ledger check, not a name
    match.  Configured routes locate the paper-facing declaration, then the
    dashboard's current signature and gap-free statement judgment establish
    the source correspondence.  Callers still decide whether any generated
    input surface is semantically the same.
    """

    try:
        root_text = str(root)
        if root_text not in sys.path:
            sys.path.insert(0, root_text)
        from scripts import review_dashboard as dashboard

        _full_inventory, inventory, _mode, _mode_error = (
            dashboard.paper_coverage_inventory(paper_dir)
        )
        source_map = load_json_object(paper_dir / "audit" / "paper_statement_map.json")
        map_items = source_map.get("items") if isinstance(source_map, dict) else None
        if not isinstance(map_items, dict):
            return set()
        map_items = filter_source_map_items_for_coverage(
            map_items,
            _mode,
            declared_environment_kinds=source_named_result_environment_kinds_from_map(
                source_map
            ),
        )

        direct_source_keys_by_row: dict[str, set[str]] = {}
        for raw_key, raw_item in map_items.items():
            if not isinstance(raw_item, dict):
                continue
            key = str(raw_key).strip()
            if not key or key not in inventory:
                continue
            if raw_item.get("claim_bearing") is False:
                continue
            if (
                str(raw_item.get("coverage_status") or "").strip().lower()
                == "corrected_source_statement"
            ):
                # A local corrected target needs its dedicated archival/target
                # route audit. Do not let the record lane inherit ordinary
                # direct-source credit merely because a declaration name also
                # appears in the source map.
                continue
            source_kind = str(raw_item.get("source_kind") or "").strip().lower()
            if source_kind not in DIRECT_SOURCE_RESULT_KINDS:
                continue
            # Aliases are navigation-only whenever an explicit paper-facing
            # route exists. The dashboard helper retains an alias-only legacy
            # fallback, so the source-record ledger uses exactly the same
            # eligibility rule as source-to-Lean coverage.
            for name in dashboard.source_item_direct_coverage_declarations(raw_item):
                direct_source_keys_by_row.setdefault(name, set()).add(key)
                direct_source_keys_by_row.setdefault(
                    name.rsplit(".", 1)[-1], set()
                ).add(key)

        covered_rows: set[str] = set()
        rows = dashboard.review_items_for_paper(
            paper_dir, render_images=False, require_current_signatures=True
        )
        for row in rows:
            source_keys = direct_source_keys_by_row.get(row.name, set())
            if not source_keys:
                continue
            if str(row.llm_match_judgment or "").strip() != "matches":
                continue
            if bool(row.llm_match_stale):
                continue
            if any(
                getattr(row, field, None)
                for field in (
                    "llm_match_unmatched_source_conclusions",
                    "llm_match_unmatched_source_inputs",
                    "llm_match_unjustified_lean_inputs",
                    "llm_match_unmatched_lean_conclusions",
                )
            ):
                continue
            row_statement_digest = dashboard.statement_digest(row.paper_statement)
            if not all(
                str(inventory[key].get("statement_sha256") or "").strip()
                == row_statement_digest
                for key in source_keys
            ):
                continue
            covered_rows.add(row.name)
        return covered_rows
    except Exception:
        # A stale dashboard lane cannot manufacture direct-source credit.
        return set()


def statement_ledger_covered_boundary_input_keys(
    root: Path,
    paper_dir: Path,
    boundary_input_items: list[dict[str, Any]],
    *,
    qualified_row_refs: dict[str, str] | None = None,
    conclusion_dependency_items: list[dict[str, Any]],
    direct_covered_rows: set[str] | None = None,
) -> set[str]:
    """Return ordinary boundary inputs already audited by a direct statement ledger.

    The record lane must still recursively inspect record/certificate fields.
    It need not ask an agent to re-audit every ordinary theorem binder when a
    current source-routed statement ledger has already checked the exact elaborated
    declaration, its visible premises, and its conclusion atom by atom.  This
    is fail-closed: a row qualifies only through a current direct statement
    ledger or a whole-map exact semantic-contract audit. The latter binds the
    source map's byte-pinned source inventory to an independently transparent
    Spec, Lean-Meta exact evidence, and the AST wrapper gate. Declaration
    spelling only locates the configured fully-qualified identities; it does
    not establish equivalence.

    A direct ledger compares a source result with its paper-facing endpoint;
    it does not construct an input which the endpoint merely assumes. The
    caller therefore supplies the semantically derived conclusion-dependency
    surface, and no matching key from that surface may be suppressed here.
    This is deliberately keyed by the generated semantic dependency items,
    not theorem or binder names.
    """

    if not boundary_input_items:
        return set()
    protected_dependency_keys = {
        str(item.get("judgment_key") or "").strip()
        for item in conclusion_dependency_items
        if isinstance(item, dict) and str(item.get("judgment_key") or "").strip()
    }
    covered_rows = (
        set(direct_covered_rows)
        if direct_covered_rows is not None
        else current_direct_statement_ledger_covered_rows(root, paper_dir)
    )

    if qualified_row_refs:
        try:
            from scripts import audit_repository as repository

            status_payload = load_json_object(paper_dir / "status.json")
            status = str(status_payload.get("status") or "").strip()
            if repository.semantic_contract_closeout_bridge_is_current(
                paper_dir.name,
                paper_dir,
                status,
                status_payload,
            ):
                source_map = load_json_object(
                    paper_dir / "audit" / "paper_statement_map.json"
                )
                map_items = source_map.get("items") if isinstance(source_map, dict) else None
                if isinstance(map_items, dict):
                    qualified_rows = {
                        str(row): str(qualified)
                        for row, qualified in qualified_row_refs.items()
                        if str(row).strip() and str(qualified).strip()
                    }
                    for raw_item in map_items.values():
                        if not isinstance(raw_item, dict):
                            continue
                        if raw_item.get("claim_bearing") is False:
                            continue
                        if (
                            str(raw_item.get("coverage_status") or "").strip().lower()
                            == "corrected_source_statement"
                        ):
                            # Corrected targets retain their dedicated archival
                            # scope contract rather than inheriting this route.
                            continue
                        contract = raw_item.get("semantic_contract")
                        if not isinstance(contract, dict):
                            continue
                        identities = {
                            str(contract.get("spec_declaration") or "").strip(),
                            str(contract.get("evidence_declaration") or "").strip(),
                        } - {""}
                        for row, qualified in qualified_rows.items():
                            if qualified in identities:
                                covered_rows.add(row)
        except Exception:
            # This is a closeout optimization only. Any unavailable map,
            # import, or Lean-backed contract validation leaves the boundary
            # input on the ordinary fail-closed source-record surface.
            pass

    return {
        str(item.get("judgment_key") or "").strip()
        for item in boundary_input_items
        if str(item.get("row") or "").strip() in covered_rows
        and str(item.get("judgment_key") or "").strip()
        and str(item.get("judgment_key") or "").strip()
        not in protected_dependency_keys
    }


def precloseout_contract_pair_has_equal_signature_surface(
    evidence_declaration: str,
    spec_declaration: str,
    *,
    evidence_qualified: str,
    spec_qualified: str,
    proposition_aliases: dict[str, PropositionAliasInfo],
    type_aliases: dict[str, TypeAliasInfo] | None,
) -> bool:
    """Check a direct/Spec pair structurally before projecting binder credit.

    Lean Meta already checked the contract theorem.  This additional static
    comparison is intentionally narrower: it requires exactly one
    alpha-normalized direct signature to equal the transparent proposition
    body, including every header binder domain.  It prevents the source-record
    lane from treating a raw ``Spec : Prop`` wrapper or a nearby proposition as
    an interchangeable input surface.
    """

    return (
        semantic_contract_pair_structural_surfaces(
            evidence_qualified_name=evidence_qualified,
            evidence_source=evidence_declaration,
            spec_qualified_name=spec_qualified,
            spec_source=spec_declaration,
            proposition_aliases=proposition_aliases,
            type_aliases=type_aliases,
        )
        is not None
    )


def precloseout_boundary_input_surface(
    item: dict[str, Any],
    declaration: str,
    *,
    context_namespace: str,
    proposition_aliases: dict[str, PropositionAliasInfo],
    type_aliases: dict[str, TypeAliasInfo] | None,
) -> tuple[int, int, str, str] | None:
    """Return one alpha-normalized binder surface for duplicate-input pairing.

    The exact original binder occurrence chooses its position.  The comparison
    itself uses expanded types with prior binders alpha-renamed, so neither a
    binder name nor a declaration name can create duplicate-review credit.
    Ambiguous duplicate occurrences remain independently reviewable.
    """

    raw_input = item.get("input")
    if not isinstance(raw_input, dict):
        return None
    target_names = normalize_ws(str(raw_input.get("names") or ""))
    target_type = normalize_ws(str(raw_input.get("type") or ""))
    if not target_names or not target_type:
        return None

    header_binder_count = len(header_inputs_from_declaration(declaration))
    replacements: dict[str, str] = {}
    matches: list[tuple[int, int, str, str]] = []
    bound_index = 0
    for position, visible_input in enumerate(
        visible_inputs_from_declaration(declaration)
    ):
        names_text = normalize_ws(str(visible_input.get("names") or ""))
        type_text = normalize_ws(str(visible_input.get("type") or ""))
        names = binder_names(names_text)
        expanded_type = semantic_contract_expand_surface_type(
            type_text,
            proposition_aliases,
            type_aliases,
            context_namespace=context_namespace,
        )
        surface = alpha_canonical_type(
            semantic_contract_replace_bound_identifiers(expanded_type, replacements)
        )
        if (
            position < header_binder_count
            and names_text == target_names
            and type_text == target_type
        ):
            matches.append(
                (
                    position,
                    len(names),
                    surface,
                    str(item.get("kind") or "").strip(),
                )
            )
        for name in names:
            replacements[name] = f"_precloseoutBound{bound_index}"
            bound_index += 1
    return matches[0] if len(matches) == 1 else None


def precloseout_semantic_contract_groups(
    semantic_model_items: list[dict[str, Any]],
) -> dict[tuple[str, str], dict[str, Any]]:
    """Return unambiguous generated direct/Spec groups keyed by identities.

    The semantic-model generator already performs the conservative structural
    alpha comparison for direct/transparent-Spec pairs.  Reuse that generated
    semantic join here rather than inferring a pair from declaration suffixes
    or source-map spelling.  Any malformed, duplicate, or ungrouped route is
    deliberately absent from the projection.
    """

    candidates: dict[tuple[str, str], list[dict[str, Any]]] = {}
    for item in semantic_model_items:
        if not isinstance(item, dict):
            continue
        group = item.get("semantic_contract_group")
        if (
            not isinstance(group, dict)
            or group.get("schema") != 1
            or group.get("structural_alpha_normalized_equal") is not True
        ):
            continue
        raw_members = group.get("member_rows")
        if not isinstance(raw_members, list) or len(raw_members) != 2:
            continue
        members = {
            str(member.get("role") or "").strip(): str(
                member.get("qualified_declaration") or ""
            ).strip()
            for member in raw_members
            if isinstance(member, dict)
        }
        evidence = semantic_contract_fully_qualified_identity(
            members.get("direct_evidence")
        )
        spec = semantic_contract_fully_qualified_identity(
            members.get("transparent_spec")
        )
        identities = group.get("source_item_identities")
        if (
            not evidence
            or not spec
            or evidence == spec
            or not isinstance(identities, list)
            or not identities
        ):
            continue
        if not all(
            isinstance(identity, dict)
            and str(identity.get("source_key") or "").strip()
            for identity in identities
        ):
            continue
        candidates.setdefault((evidence, spec), []).append(group)
    return {
        pair: groups[0]
        for pair, groups in candidates.items()
        if len(groups) == 1
    }


def precloseout_contract_covered_boundary_input_keys(
    paper_dir: Path,
    boundary_input_items: list[dict[str, Any]],
    *,
    qualified_row_refs: dict[str, str],
    declarations: dict[str, str],
    proposition_aliases: dict[str, PropositionAliasInfo],
    type_aliases: dict[str, TypeAliasInfo] | None,
    conclusion_dependency_items: list[dict[str, Any]],
    semantic_model_items: list[dict[str, Any]],
    statement_ledger_covered_input_keys: set[str],
    projection_items: list[dict[str, Any]] | None = None,
) -> set[str]:
    """Project only exact direct/Spec duplicate *ordinary* input judgments.

    This is a precloseout optimization, not a status bridge. It runs only at
    ``partially formalized`` through the repository API, never touches
    conclusion dependencies, recursive fields, or semantic-model rows, and
    fails closed on any missing map, contract, declaration, or alpha-surface
    evidence. Corrected targets are excluded by the repository API.

    Crucially, this function never covers the direct binder. With a blank
    statement ledger that direct counterpart remains in the source-record
    judge prompt; with a current direct ledger, that separate current source
    statement judgment remains the only source-facing credit. The projection
    therefore removes only an exact duplicate Spec-side review and cannot
    bootstrap source correspondence from contract names alone.
    """

    if not boundary_input_items:
        return set()
    status_payload = load_json_object(paper_dir / "status.json")
    status = str(status_payload.get("status") or "").strip()
    if status != "partially formalized":
        return set()
    protected_dependency_keys = {
        str(item.get("judgment_key") or "").strip()
        for item in conclusion_dependency_items
        if isinstance(item, dict) and str(item.get("judgment_key") or "").strip()
    }

    try:
        from scripts import audit_repository as repository

        pairs = repository.semantic_contract_precloseout_exact_contract_pairs(
            paper_dir.name,
            paper_dir,
            status,
            status_payload,
        )
    except Exception:
        return set()
    if not pairs:
        return set()
    grouped_pairs = precloseout_semantic_contract_groups(semantic_model_items)
    if not grouped_pairs:
        return set()

    rows_by_qualified: dict[str, str] = {}
    duplicate_identities: set[str] = set()
    for row, raw_qualified in qualified_row_refs.items():
        qualified = semantic_contract_fully_qualified_identity(raw_qualified)
        if not qualified or row not in declarations:
            continue
        if qualified in rows_by_qualified:
            duplicate_identities.add(qualified)
            continue
        rows_by_qualified[qualified] = row
    for qualified in duplicate_identities:
        rows_by_qualified.pop(qualified, None)

    ordinary_items = [
        item
        for item in boundary_input_items
        if str(item.get("judgment_key") or "").strip()
        and str(item.get("judgment_key") or "").strip()
        not in protected_dependency_keys
        and not str(item.get("result_relation") or "").strip()
    ]
    covered: set[str] = set()
    receipts_by_projected_key: dict[str, dict[str, Any]] = {}
    for raw_pair in pairs:
        if not isinstance(raw_pair, tuple) or len(raw_pair) != 2:
            return set()
        evidence_qualified, spec_qualified = raw_pair
        group = grouped_pairs.get((evidence_qualified, spec_qualified))
        if group is None:
            continue
        evidence_row = rows_by_qualified.get(evidence_qualified)
        spec_row = rows_by_qualified.get(spec_qualified)
        if (
            evidence_row is None
            or spec_row is None
        ):
            continue
        evidence_declaration = declarations.get(evidence_row, "")
        spec_declaration = declarations.get(spec_row, "")
        if not evidence_declaration or not spec_declaration:
            continue
        if not precloseout_contract_pair_has_equal_signature_surface(
            evidence_declaration,
            spec_declaration,
            evidence_qualified=evidence_qualified,
            spec_qualified=spec_qualified,
            proposition_aliases=proposition_aliases,
            type_aliases=type_aliases,
        ):
            continue

        direct_surfaces: dict[tuple[int, int, str, str], list[str]] = {}
        for item in ordinary_items:
            if str(item.get("row") or "").strip() != evidence_row:
                continue
            surface = precloseout_boundary_input_surface(
                item,
                evidence_declaration,
                context_namespace=evidence_qualified.rsplit(".", 1)[0],
                proposition_aliases=proposition_aliases,
                type_aliases=type_aliases,
            )
            key = str(item.get("judgment_key") or "").strip()
            if surface is not None and key:
                direct_surfaces.setdefault(surface, []).append(key)
        for item in ordinary_items:
            if str(item.get("row") or "").strip() != spec_row:
                continue
            surface = precloseout_boundary_input_surface(
                item,
                spec_declaration,
                context_namespace=spec_qualified.rsplit(".", 1)[0],
                proposition_aliases=proposition_aliases,
                type_aliases=type_aliases,
            )
            key = str(item.get("judgment_key") or "").strip()
            # An exact direct row must contain exactly one matching ordinary
            # generated binder.  Multiple candidates or a missing surface are
            # ambiguity, not a reason to infer source-record coverage.
            direct_keys = direct_surfaces.get(surface, []) if surface is not None else []
            if key and len(direct_keys) == 1:
                covered.add(key)
                source_keys = sorted(
                    str(identity.get("source_key") or "").strip()
                    for identity in group.get("source_item_identities") or []
                    if isinstance(identity, dict)
                    and str(identity.get("source_key") or "").strip()
                )
                structural_surface = {
                    "surface_root": group.get("surface_root"),
                    "direct_evidence_type": group.get("direct_evidence_type"),
                }
                receipts_by_projected_key[key] = {
                    "source_item_keys": source_keys,
                    "evidence_qualified_declaration": evidence_qualified,
                    "spec_qualified_declaration": spec_qualified,
                    "direct_judgment_key": direct_keys[0],
                    "direct_source_record_judgment_required": (
                        direct_keys[0]
                        not in statement_ledger_covered_input_keys
                    ),
                    "projected_spec_judgment_key": key,
                    "structural_surface_sha256": stable_digest(structural_surface),
                }
    if projection_items is not None:
        projection_items.extend(
            receipts_by_projected_key[key] for key in sorted(receipts_by_projected_key)
        )
    return covered


def source_antecedents_with_classifications(
    judgments: dict[str, dict[str, Any]], classifications: set[str]
) -> set[str]:
    out: set[str] = set()
    for key, item in judgments.items():
        classification = str(
            item.get("classification")
            or item.get("judgment")
            or item.get("verdict")
            or item.get("status")
            or ""
        ).strip()
        location = str(
            item.get("source_location")
            or item.get("source_evidence")
            or ""
        ).strip()
        if classification in classifications and EXACT_SOURCE_LOCATOR_RE.search(location):
            out.add(key)
    return out


def exact_source_antecedents(judgments: dict[str, dict[str, Any]]) -> set[str]:
    return source_antecedents_with_classifications(
        judgments, {"validated_source_assumption"}
    )


def nonpropositional_source_data_antecedents(
    judgments: dict[str, dict[str, Any]]
) -> set[str]:
    return source_antecedents_with_classifications(
        judgments, {"nonpropositional_witness_data"}
    )


def current_approved_source_convention_antecedent_keys(
    paper_dir: Path,
    payload: Mapping[str, Any],
    judgments: Mapping[str, dict[str, Any]],
) -> tuple[set[str], set[str]]:
    """Return direct and recursive convention premises with current pins.

    This is deliberately a narrow route.  A convention may discharge an
    explicit non-result model premise only after the same current source-map,
    source-location, and model-convention ledger validation used by the
    evidence gate succeeds.  It never treats a record/result package or a
    constructor-produced value as a source antecedent.
    """

    statement_map = load_json_object(paper_dir / "audit" / "paper_statement_map.json")
    source_proof_fidelity = source_proof_fidelity_context(paper_dir)
    if not statement_map or source_proof_fidelity is None:
        return set(), set()
    # The raw receipt must describe the same current ledger that validates the
    # sidecar response.  A summary refresh is not allowed to bridge a changed
    # ledger without a fresh source-record scan.
    if payload.get("source_proof_fidelity") != source_proof_fidelity:
        return set(), set()
    status = str(load_json_object(paper_dir / "status.json").get("status") or "")

    def accepted(item: Mapping[str, Any]) -> bool:
        key = str(item.get("judgment_key") or "").strip()
        judgment = judgments.get(key)
        if not key or not isinstance(judgment, Mapping):
            return False
        location = str(
            judgment.get("source_location") or judgment.get("source_evidence") or ""
        ).strip()
        if not EXACT_SOURCE_LOCATOR_RE.search(location):
            return False
        return not approved_source_convention_antecedent_errors(
            item,
            judgment,
            statement_map=statement_map,
            source_proof_fidelity=source_proof_fidelity,
            status=status,
        )

    direct_keys = {
        str(item.get("judgment_key"))
        for item in payload.get("conclusion_dependency_items") or []
        if isinstance(item, Mapping) and accepted(item)
    }
    recursive_field_keys = {
        str(item.get("judgment_key"))
        for item in payload.get("recursive_field_items") or []
        if isinstance(item, Mapping) and accepted(item)
    }
    return direct_keys, recursive_field_keys


def current_approved_corrected_model_dependency_keys(
    paper_dir: Path,
    paper: str,
    payload: Mapping[str, Any],
) -> set[str]:
    """Return exact dependencies covered by the current corrected-model contract.

    The shared conclusion-provenance bridge validates the author-approved
    scope, governing artifact and archive hashes, canonical semantic-contract
    bytes, raw audit/integrity/scope receipts, complete target/model/field
    mappings, and exact declaration/signature/root/path identities.  This
    helper only projects those already validated occurrence identities into
    the source-record summary.  A classification string or corrected-looking
    declaration name is never an acceptance route.
    """

    try:
        from scripts import audit_conclusion_provenance as provenance

        bridge = provenance.corrected_model_conclusion_bridge(
            paper,
            dict(payload),
            folder=paper_dir,
        )
        if bridge is None:
            return set()
        raw_dependencies = payload.get("conclusion_dependency_items")
        if not isinstance(raw_dependencies, list):
            return set()
        covered: set[str] = set()
        for raw_dependency in raw_dependencies:
            if not isinstance(raw_dependency, dict):
                return set()
            key = str(raw_dependency.get("judgment_key") or "").strip()
            if not key:
                return set()
            if provenance.corrected_model_dependency_is_covered(
                bridge, raw_dependency
            ):
                covered.add(key)
        return covered
    except Exception:
        # A corrected-model waiver is an optimization over the ordinary
        # fail-closed field surface.  Missing imports, files, or stale receipts
        # therefore leave every dependency unresolved.
        return set()


def dependency_has_resolved_constructor(
    item: dict[str, Any],
    exact_antecedent_keys: set[str],
    judgments: dict[str, dict[str, Any]],
) -> bool:
    """Accept a non-record conclusion route only through checked evidence.

    The generated conditional-constructor list is evidence about possible Lean
    routes, not proof that the sidecar selected a non-circular route for this
    premise.  The sidecar must bind its ``proved_from_primitives`` verdict to
    one exact generated candidate and its exact source antecedent leaves.

    A builder returning a record type cannot establish an arbitrary visible
    record binder of that type. Such inputs require their own source-validated
    fields (or an explicit equality/reconstruction bridge exposed in the
    reviewed statement); neither a fresh-record builder nor a projection route
    identifies the caller's record.
    """

    if item.get("kind") == "record_conclusion_input":
        return False
    if item.get("valid_constructors"):
        return True
    key = str(item.get("judgment_key") or "").strip()
    return checked_projection_result(
        item,
        judgments.get(key),
        exact_antecedent_keys,
    ).accepted


def dependency_checked_projection_result(
    item: dict[str, Any],
    exact_antecedent_keys: set[str],
    judgments: dict[str, dict[str, Any]],
) -> CheckedProjectionResult:
    """Return the explicit projection-contract verdict for a dependency item."""

    key = str(item.get("judgment_key") or "").strip()
    return checked_projection_result(
        item,
        judgments.get(key),
        exact_antecedent_keys,
    )


def transparent_subtype_domain_input_is_accepted_source_data(
    item: dict[str, Any],
    data_antecedent_keys: set[str],
) -> bool:
    """Accept a restricted subtype only through its exact context receipt.

    This is deliberately stricter than the generic source-antecedent route:
    the subtype's stored proof may restrict a paper claim even when it does not
    syntactically imply the theorem result.  A current data judgment therefore
    needs the generated source association, source-item SHA identities,
    byte-pinned restricted-domain context, and the matching elaborated review
    signature in addition to the normal item-local receipt.
    """

    if item.get("kind") != "transparent_subtype_domain_input":
        return False
    if (
        item.get("domain_data_only") is not True
        or item.get("subtype_domain_semantic_data_only") is not True
        or item.get("subtype_expansion_complete") is not True
        or item.get("subtype_carrier_is_definitely_data") is not True
        or str(item.get("subtype_predicate_result_relation") or "").strip()
        or item.get("subtype_predicate_record_dependencies")
        or item.get("subtype_carrier_record_dependencies")
        or item.get("subtype_predicate_record_binder_dependencies")
        or not isinstance(item.get("subtype_predicate_result_bridges"), list)
        or item.get("subtype_predicate_result_bridges")
    ):
        return False
    expansion = item.get("subtype_predicate_proposition_alias_expansion")
    if not isinstance(expansion, dict) or expansion.get("blocked_routes"):
        return False
    if not source_record_item_reuse_eligible(
        item,
        expected_item_digest_schema=SOURCE_RECORD_ITEM_DIGEST_SCHEMA,
    ):
        return False

    reviewed_key = reviewed_declaration_identity_key(
        item.get("reviewed_declaration_identity")
    )
    if reviewed_key is None:
        return False
    reviewed_declaration, _declaration_sha = reviewed_key
    raw_signatures = item.get("reviewed_elaborated_signature_identities")
    if not isinstance(raw_signatures, list) or not raw_signatures:
        return False
    signatures: set[tuple[str, str]] = set()
    for raw_signature in raw_signatures:
        if not isinstance(raw_signature, dict):
            return False
        declaration = semantic_contract_fully_qualified_identity(
            raw_signature.get("qualified_declaration")
        )
        digest = str(raw_signature.get("elaborated_signature_sha256") or "").strip().lower()
        if declaration != reviewed_declaration or not SHA256_RE.fullmatch(digest):
            return False
        signatures.add((declaration, digest))
    if len(signatures) != len(raw_signatures):
        return False

    source_association = item.get("source_contract_association")
    if not isinstance(source_association, dict):
        return False
    association_identity = reviewed_declaration_identity_key(
        source_association.get("reviewed_declaration_identity")
    )
    source_identities, source_identity_errors = source_contract_source_identities(
        source_association.get("source_item_identities")
    )
    raw_association_signature = source_association.get(
        "reviewed_elaborated_signature_identity"
    )
    if (
        association_identity != reviewed_key
        or source_identity_errors
        or not isinstance(raw_association_signature, dict)
    ):
        return False
    source_identity_pairs = {
        (
            str(identity.get("source_map_item_sha256") or "").strip().lower(),
            str(identity.get("source_semantic_sha256") or "").strip().lower(),
        )
        for identity in source_identities
    }
    if len(source_identity_pairs) != len(source_identities):
        return False
    association_signature = (
        semantic_contract_fully_qualified_identity(
            raw_association_signature.get("qualified_declaration")
        ),
        str(
            raw_association_signature.get("elaborated_signature_sha256") or ""
        ).strip().lower(),
    )
    if (
        association_signature[0] != reviewed_declaration
        or not SHA256_RE.fullmatch(association_signature[1])
        or signatures != {association_signature}
    ):
        return False

    context = item.get("subtype_domain_source_context")
    if not isinstance(context, dict):
        return False
    if (
        context.get("schema") != TRANSPARENT_SUBTYPE_DOMAIN_CONTEXT_SCHEMA
        or context.get("required_kind") != RESTRICTED_SUBTYPE_DOMAIN_CONTEXT_KIND
        or context.get("status") != "satisfied"
    ):
        return False
    context_association = context.get("association")
    if not isinstance(context_association, dict):
        return False
    if reviewed_declaration_identity_key(
        context_association.get("reviewed_declaration_identity")
    ) != reviewed_key:
        return False
    context_identities, context_identity_errors = source_contract_source_identities(
        context_association.get("source_item_identities")
    )
    context_signature = context_association.get(
        "reviewed_elaborated_signature_identity"
    )
    context_identity_pairs = {
        (
            str(identity.get("source_map_item_sha256") or "").strip().lower(),
            str(identity.get("source_semantic_sha256") or "").strip().lower(),
        )
        for identity in context_identities
    }
    if (
        context_identity_errors
        or not isinstance(context_signature, dict)
        or len(context_identity_pairs) != len(context_identities)
        or context_identity_pairs != source_identity_pairs
    ):
        return False
    context_signature_key = (
        semantic_contract_fully_qualified_identity(
            context_signature.get("qualified_declaration")
        ),
        str(context_signature.get("elaborated_signature_sha256") or "").strip().lower(),
    )
    if context_signature_key != association_signature:
        return False

    selected_contexts = context.get("selected_contexts")
    if not isinstance(selected_contexts, list) or not selected_contexts:
        return False
    selected_source_semantic_shas: set[str] = set()
    seen_contexts: set[tuple[str, str]] = set()
    for selected in selected_contexts:
        if not isinstance(selected, dict):
            return False
        source_semantic_sha = str(
            selected.get("source_semantic_sha256") or ""
        ).strip().lower()
        context_sha = str(selected.get("context_sha256") or "").strip().lower()
        semantic_context_sha = str(
            selected.get("semantic_context_sha256") or ""
        ).strip().lower()
        anchors = selected.get("source_anchor_evidence")
        if (
            selected.get("kind") != RESTRICTED_SUBTYPE_DOMAIN_CONTEXT_KIND
            or not SHA256_RE.fullmatch(source_semantic_sha)
            or not SHA256_RE.fullmatch(context_sha)
            or not SHA256_RE.fullmatch(semantic_context_sha)
            or not isinstance(anchors, list)
            or not anchors
        ):
            return False
        context_key = (source_semantic_sha, context_sha)
        if context_key in seen_contexts:
            return False
        seen_contexts.add(context_key)
        selected_source_semantic_shas.add(source_semantic_sha)
    if selected_source_semantic_shas != {
        str(identity.get("source_semantic_sha256") or "").strip().lower()
        for identity in source_identities
    }:
        return False

    key = str(item.get("judgment_key") or "").strip()
    return bool(key and key in data_antecedent_keys)


def conclusion_input_is_accepted_source_antecedent(
    item: dict[str, Any],
    exact_antecedent_keys: set[str],
    data_antecedent_keys: set[str],
    approved_source_convention_keys: set[str] | None = None,
    *,
    judgments: Mapping[str, Mapping[str, Any]] | None = None,
) -> bool:
    if item.get("conclusion_fields"):
        return False
    if item.get("kind") == "transparent_subtype_domain_input":
        return transparent_subtype_domain_input_is_accepted_source_data(
            item, data_antecedent_keys
        )
    if item.get("kind") not in {
        "aliased_conclusion_bridge_input",
        "bool_certificate_input",
        "direct_conclusion_input",
        "selector_certificate_input",
        "unexpanded_local_reducible_type_input",
    }:
        return False
    key = str(item.get("judgment_key") or "").strip()
    return bool(
        key
        and (
            key in exact_antecedent_keys
            or key in data_antecedent_keys
            or key in (approved_source_convention_keys or set())
        )
    )


def current_validated_record_field_closure_completion_candidates(
    raw_audit: Mapping[str, Any] | None,
    judgments: Mapping[str, Mapping[str, Any]],
) -> tuple[RecordFieldClosureCompletionCandidate, ...]:
    """Return only current complete record-closure review receipts.

    The closure generator has already selected a unique direct source-bound
    semantic parent by exact declaration/signature, record-input binding, and
    recursive field-component identities.  This consumer independently checks
    the exact parent attestation and every materialized child receipt before
    exposing the candidate.  A field classification, declaration suffix,
    binder spelling, or function name cannot create closure credit.

    This remains the deliberately narrow v10 closure-completion transport.  It
    does not manufacture a v11 occurrence-level source-claim contract.
    """

    if not isinstance(raw_audit, Mapping):
        return ()
    candidates = current_record_field_closure_completion_candidates(raw_audit)
    accepted: list[RecordFieldClosureCompletionCandidate] = []
    for candidate in candidates:
        parent = judgments.get(candidate.semantic_model_judgment_key)
        if not isinstance(parent, Mapping):
            continue
        attestation = closure_attestation_for_candidate(
            parent, candidate=candidate
        )
        if attestation is None:
            continue
        attestation_digest = closure_attestation_sha256(attestation)
        complete = True
        for (
            field_key,
            component_key,
            component_sha,
            structural_type_sha,
        ) in candidate.field_components:
            field_judgment = judgments.get(field_key)
            if not isinstance(field_judgment, Mapping) or closure_completion_receipt_error(
                field_judgment.get(RECORD_FIELD_CLOSURE_COMPLETION_RECEIPT_FIELD),
                candidate=candidate,
                field_key=field_key,
                component_key=component_key,
                component_sha256=component_sha,
                structural_type_sha256=structural_type_sha,
                attestation_sha256=attestation_digest,
            ):
                complete = False
                break
        if complete:
            accepted.append(candidate)
    return tuple(accepted)


def _generated_dependency_binder_names(
    item: Mapping[str, Any],
) -> frozenset[str]:
    """Read one generated binder group as an exact coordinate only.

    The names never establish semantic correspondence.  They are used solely
    to bind a dependency occurrence back to the generator-owned record-input
    receipt that already carries the semantic evidence.
    """

    raw_names = item.get("binder_names")
    if raw_names is not None:
        if not isinstance(raw_names, list):
            return frozenset()
        names = [str(name).strip() for name in raw_names if str(name).strip()]
    else:
        names = [
            name
            for name in binder_names(str(item.get("binder") or ""))
            if name
        ]
    return (
        frozenset(names)
        if names and len(names) == len(set(names))
        else frozenset()
    )


def _dependency_elaborated_signature_identities(
    item: Mapping[str, Any],
    *,
    declaration: str,
) -> frozenset[tuple[str, str]] | None:
    """Parse only exact generator-owned elaborated signature identities."""

    raw_signatures = item.get("reviewed_elaborated_signature_identities")
    if not isinstance(raw_signatures, list) or not raw_signatures:
        return None
    signatures: set[tuple[str, str]] = set()
    for raw_signature in raw_signatures:
        if not isinstance(raw_signature, Mapping):
            return None
        qualified = semantic_contract_fully_qualified_identity(
            raw_signature.get("qualified_declaration")
        )
        digest = str(
            raw_signature.get("elaborated_signature_sha256") or ""
        ).strip().lower()
        identity = (qualified, digest)
        if (
            qualified != declaration
            or not SHA256_RE.fullmatch(digest)
            or identity in signatures
        ):
            return None
        signatures.add(identity)
    return frozenset(signatures)


def record_dependency_is_nonresult_source_model(
    item: Mapping[str, Any],
    *,
    closure_structural_data_field_keys: set[str] | None = None,
) -> bool:
    """Whether a record dependency is purely a source-model input surface."""

    if (
        item.get("kind") != "record_conclusion_input"
        or not semantic_contract_fully_qualified_identity(item.get("record"))
    ):
        return False
    fields = item.get("conclusion_fields")
    if not isinstance(fields, list) or not fields:
        return False
    closure_structural_data_field_keys = (
        closure_structural_data_field_keys or set()
    )
    for field in fields:
        if not isinstance(field, Mapping):
            return False
        key = str(field.get("judgment_key") or field.get("path") or "").strip()
        if not key:
            return False
        ordinary_source_model_field = bool(
            field.get("source_antecedent_eligible") is True
            and not str(field.get("relation_to_row_result") or "").strip()
        )
        if not ordinary_source_model_field and key not in (
            closure_structural_data_field_keys
        ):
            return False
    return True


def record_field_closure_structural_data_keys(
    raw_audit: Mapping[str, Any] | None,
    candidates: tuple[RecordFieldClosureCompletionCandidate, ...],
) -> set[str]:
    """Return closure fields Lean proved to be representation-invariant data."""

    if not isinstance(raw_audit, Mapping) or not candidates:
        return set()
    raw_fields = raw_audit.get("recursive_field_items")
    if not isinstance(raw_fields, list):
        return set()
    by_key: dict[str, Mapping[str, Any]] = {}
    for raw_field in raw_fields:
        if not isinstance(raw_field, Mapping):
            return set()
        key = str(raw_field.get("judgment_key") or "").strip()
        if not key or key in by_key:
            return set()
        by_key[key] = raw_field
    expected_structural_sha: dict[str, str] = {}
    for candidate in candidates:
        for (
            field_key,
            _component_key,
            _component_sha,
            structural_type_sha,
        ) in candidate.field_components:
            prior = expected_structural_sha.get(field_key)
            if prior is not None and prior != structural_type_sha:
                return set()
            expected_structural_sha[field_key] = structural_type_sha
    accepted: set[str] = set()
    for key, structural_sha in expected_structural_sha.items():
        field = by_key.get(key)
        receipt = field.get("elaborated_field_safety_receipt") if field else None
        if (
            isinstance(field, Mapping)
            and isinstance(receipt, Mapping)
            and field.get("proposition_sort") == "false"
            and field.get("payload_safety") == "structural_data"
            and str(field.get("structural_type_sha256") or "").strip().lower()
            == structural_sha
            and receipt.get("status") == "ok"
            and receipt.get("value_sort") == "false"
            and receipt.get("payload_safety") == "structural_data"
        ):
            accepted.add(key)
    return accepted


def dependency_matches_exact_closure_parent(
    item: Mapping[str, Any],
    candidate: RecordFieldClosureCompletionCandidate,
) -> bool:
    """Match a record dependency to one exact generated closure parent."""

    identity = reviewed_declaration_identity_key(
        item.get("reviewed_declaration_identity")
    )
    if identity != candidate.declaration_identity:
        return False
    signatures = _dependency_elaborated_signature_identities(
        item, declaration=identity[0]
    )
    raw_fields = item.get("conclusion_fields")
    if not isinstance(raw_fields, list) or not raw_fields:
        return False
    field_keys_list = [
        str(field.get("judgment_key") or field.get("path") or "").strip()
        if isinstance(field, Mapping)
        else ""
        for field in raw_fields
    ]
    if (
        any(not key for key in field_keys_list)
        or len(field_keys_list) != len(set(field_keys_list))
    ):
        return False
    field_keys = set(field_keys_list)
    return bool(
        signatures == frozenset({candidate.elaborated_signature_identity})
        and semantic_contract_fully_qualified_identity(item.get("record"))
        == candidate.record_root
        and _generated_dependency_binder_names(item) == candidate.binder_names
        and field_keys
        and field_keys.issubset(candidate.field_keys)
    )


def record_field_closure_completion_resolution_reason(
    item: dict[str, Any],
    exact_antecedent_keys: set[str],
    data_antecedent_keys: set[str],
    approved_source_convention_field_keys: set[str],
    candidates: tuple[RecordFieldClosureCompletionCandidate, ...],
    *,
    closure_structural_data_field_keys: set[str] | None = None,
) -> str:
    """Resolve one source-model record only through exact closure evidence.

    An exact closure parent owns its own generated occurrence.  Reuse at a
    different occurrence additionally requires that occurrence's own current
    exact source-antecedent judgment.  This prevents a shared field key from
    silently granting source credit to an unrelated theorem while still
    allowing a once-reviewed source-model record type to be consumed by other
    explicitly source-bound rows.
    """

    if item.get("kind") != "record_conclusion_input":
        return ""
    matching_parents = [
        candidate
        for candidate in candidates
        if dependency_matches_exact_closure_parent(item, candidate)
    ]
    if len(matching_parents) == 1:
        return "record_field_closure_completion_parent"
    if matching_parents:
        return ""

    key = str(item.get("judgment_key") or "").strip()
    if (
        not key
        or key not in exact_antecedent_keys
        or not record_dependency_is_nonresult_source_model(
            item,
            closure_structural_data_field_keys=(
                closure_structural_data_field_keys
            ),
        )
    ):
        return ""
    field_keys = {
        str(field.get("judgment_key") or field.get("path") or "").strip()
        for field in item.get("conclusion_fields") or []
        if isinstance(field, Mapping)
    }
    closure_field_keys = {
        field_key for candidate in candidates for field_key in candidate.field_keys
    }
    unresolved = unresolved_dependency_field_keys(
        item,
        exact_antecedent_keys,
        data_antecedent_keys,
        approved_source_convention_field_keys,
        record_field_closure_keys=closure_field_keys,
        record_field_closure_structural_data_keys=(
            closure_structural_data_field_keys
        ),
    )
    return (
        "accepted_source_record_with_closure_completion"
        if field_keys and not unresolved
        else ""
    )


def unresolved_dependency_field_keys(
    item: dict[str, Any],
    exact_antecedent_keys: set[str],
    data_antecedent_keys: set[str],
    approved_source_convention_field_keys: set[str] | None = None,
    *,
    record_field_closure_keys: set[str] | None = None,
    record_field_closure_structural_data_keys: set[str] | None = None,
) -> tuple[str, ...]:
    keys: list[str] = []
    for field in item.get("conclusion_fields") or []:
        if not isinstance(field, dict):
            continue
        key = str(field.get("judgment_key") or field.get("path") or "").strip()
        if not key:
            continue
        if key in (record_field_closure_keys or set()) and (
            (
                field.get("source_antecedent_eligible") is True
                and not str(field.get("relation_to_row_result") or "").strip()
            )
            or key in (record_field_closure_structural_data_keys or set())
        ):
            continue
        if field.get("source_antecedent_eligible") and key in exact_antecedent_keys:
            continue
        if (
            field.get("source_antecedent_eligible")
            and not str(field.get("relation_to_row_result") or "").strip()
            and key in (approved_source_convention_field_keys or set())
        ):
            continue
        semantic_kind = str(field.get("semantic_kind") or "").strip()
        if (
            field.get("source_antecedent_eligible")
            and semantic_kind != "proposition"
            and key in data_antecedent_keys
        ):
            continue
        keys.append(key)
    return tuple(keys)


def conclusion_dependency_resolution_reason(
    item: dict[str, Any],
    exact_antecedent_keys: set[str],
    data_antecedent_keys: set[str],
    judgments: dict[str, dict[str, Any]],
    approved_source_convention_input_keys: set[str] | None = None,
    approved_source_convention_field_keys: set[str] | None = None,
    record_field_closure_candidates: tuple[
        RecordFieldClosureCompletionCandidate, ...
    ] = (),
    record_field_closure_structural_data_field_keys: set[str] | None = None,
    approved_corrected_model_dependency_keys: set[str] | None = None,
) -> str:
    if conclusion_input_is_accepted_source_antecedent(
        item,
        exact_antecedent_keys,
        data_antecedent_keys,
        approved_source_convention_input_keys,
        judgments=judgments,
    ):
        key = str(item.get("judgment_key") or "").strip()
        if key in (approved_source_convention_input_keys or set()):
            return "accepted_source_convention"
        return "accepted_source_antecedent"
    if dependency_has_resolved_constructor(item, exact_antecedent_keys, judgments):
        return (
            "constructor"
            if item.get("valid_constructors")
            else "checked_projection"
        )
    closure_reason = record_field_closure_completion_resolution_reason(
        item,
        exact_antecedent_keys,
        data_antecedent_keys,
        approved_source_convention_field_keys or set(),
        record_field_closure_candidates,
        closure_structural_data_field_keys=(
            record_field_closure_structural_data_field_keys
        ),
    )
    if closure_reason:
        return closure_reason
    key = str(item.get("judgment_key") or "").strip()
    if key and key in (approved_corrected_model_dependency_keys or set()):
        return "approved_corrected_model_contract"
    all_fields = tuple(
        str(field.get("judgment_key") or field.get("path") or "")
        for field in item.get("conclusion_fields") or []
        if isinstance(field, dict)
    )
    if all_fields and not unresolved_dependency_field_keys(
        item,
        exact_antecedent_keys,
        data_antecedent_keys,
        approved_source_convention_field_keys,
    ):
        return "accepted_source_fields"
    return ""


def partition_conclusion_dependencies(
    items: list[dict[str, Any]],
    judgments: dict[str, dict[str, Any]],
    statement_ledger_covered_keys: set[str] | None = None,
    *,
    approved_source_convention_input_keys: set[str] | None = None,
    approved_source_convention_field_keys: set[str] | None = None,
    raw_audit: Mapping[str, Any] | None = None,
    approved_corrected_model_dependency_keys: set[str] | None = None,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:
    exact_antecedent_keys = exact_source_antecedents(judgments)
    data_antecedent_keys = nonpropositional_source_data_antecedents(judgments)
    # A direct statement ledger confirms that a source result and a reviewed
    # endpoint agree. It cannot establish a premise supplied to that endpoint.
    # Retain the parameter temporarily for helper compatibility, but never use
    # it to resolve the semantic conclusion-dependency surface.
    del statement_ledger_covered_keys
    approved_source_convention_input_keys = approved_source_convention_input_keys or set()
    approved_source_convention_field_keys = approved_source_convention_field_keys or set()
    approved_corrected_model_dependency_keys = (
        approved_corrected_model_dependency_keys or set()
    )
    record_field_closure_candidates = (
        current_validated_record_field_closure_completion_candidates(
            raw_audit, judgments
        )
    )
    record_field_closure_structural_data_field_keys = (
        record_field_closure_structural_data_keys(
            raw_audit, record_field_closure_candidates
        )
    )
    resolved: list[dict[str, Any]] = []
    unresolved: list[dict[str, Any]] = []
    for item in items:
        reason = conclusion_dependency_resolution_reason(
            item,
            exact_antecedent_keys,
            data_antecedent_keys,
            judgments,
            approved_source_convention_input_keys,
            approved_source_convention_field_keys,
            record_field_closure_candidates,
            record_field_closure_structural_data_field_keys,
            approved_corrected_model_dependency_keys,
        )
        if reason:
            resolved.append({**item, "resolution": reason})
            continue
        dependency_key = str(item.get("judgment_key") or "").strip()
        occurrence_can_use_closure = bool(
            record_dependency_is_nonresult_source_model(
                item,
                closure_structural_data_field_keys=(
                    record_field_closure_structural_data_field_keys
                ),
            )
            and (
                dependency_key in exact_antecedent_keys
                or any(
                    dependency_matches_exact_closure_parent(item, candidate)
                    for candidate in record_field_closure_candidates
                )
            )
        )
        record_field_closure_keys = (
            {
                field_key
                for candidate in record_field_closure_candidates
                for field_key in candidate.field_keys
            }
            if occurrence_can_use_closure
            else set()
        )
        fields = unresolved_dependency_field_keys(
            item,
            exact_antecedent_keys,
            data_antecedent_keys,
            approved_source_convention_field_keys,
            record_field_closure_keys=record_field_closure_keys,
            record_field_closure_structural_data_keys=(
                record_field_closure_structural_data_field_keys
            ),
        )
        key = str(item.get("judgment_key") or "").strip()
        judgment = judgments.get(key)
        projection = dependency_checked_projection_result(
            item, exact_antecedent_keys, judgments
        )
        unresolved.append(
            {
                **item,
                "unresolved_fields": list(fields),
                **(
                    {"checked_projection_error": projection.reason}
                    if projection.reason
                    and (
                        item.get("conditional_constructors")
                        or source_record_classification(judgment)
                        == "proved_from_primitives"
                    )
                    else {}
                ),
            }
        )
    return resolved, unresolved


def refresh_existing_judgment_summary(
    paper_dir: Path,
    paper: str,
    audit_path: Path,
    *,
    paper_statement_map_sha256: str,
    paper_statement_map_semantic_sha256: str | None = None,
    write: bool = True,
    payload_override: dict[str, Any] | None = None,
) -> dict[str, Any]:
    """Refresh judgment-derived fields without rebuilding the Lean audit surface.

    Cache reuse asks for an in-memory refresh so reading a canonical audit does
    not race with another process or dirty a tracked artifact.  The explicit
    ``--refresh-judgment-summary`` workflow retains its write behavior.
    """

    payload = (
        payload_override
        if isinstance(payload_override, dict)
        else load_json_object(audit_path)
    )
    if not payload:
        raise SystemExit(f"missing or invalid source-record audit at {audit_path}")
    if payload.get("paper") != paper:
        raise SystemExit(
            f"source-record audit paper mismatch at {audit_path}: "
            f"expected {paper!r}, found {payload.get('paper')!r}"
        )
    if payload.get("prompt_version") != SOURCE_RECORD_PROMPT_VERSION:
        raise SystemExit(
            f"source-record audit prompt is stale at {audit_path}: "
            f"expected {SOURCE_RECORD_PROMPT_VERSION!r}"
        )
    if not str(payload.get("source_record_audit_sha256") or "").strip():
        raise SystemExit(f"source-record audit digest is missing at {audit_path}")
    integrity_error = source_record_audit_receipt_error(payload)
    if integrity_error:
        raise SystemExit(
            "source-record judgment summary refresh requires an unmodified "
            f"generated raw audit at {audit_path}: {integrity_error}"
        )
    if paper_statement_map_semantic_sha256 is None:
        _full_map_sha256, paper_statement_map_semantic_sha256 = (
            paper_statement_map_cache_receipts(paper_dir)
        )
    current_map_digest = paper_statement_map_sha256.strip().lower()
    current_semantic_map_digest = str(
        paper_statement_map_semantic_sha256 or ""
    ).strip().lower()
    recorded_map_digest = str(
        payload.get("paper_statement_map_sha256") or ""
    ).strip().lower()
    if not SHA256_RE.fullmatch(current_map_digest):
        raise SystemExit(
            "source-record judgment summary refresh requires a readable current "
            "paper_statement_map.json"
        )
    if not SHA256_RE.fullmatch(recorded_map_digest):
        raise SystemExit(
            "source-record audit paper_statement_map_sha256 is missing or malformed "
            f"at {audit_path}"
        )
    stored_fingerprint = payload.get("source_record_input_fingerprint")
    recorded_semantic_map_digest = (
        str(
            stored_fingerprint.get("paper_statement_map_semantic_sha256") or ""
        ).strip().lower()
        if isinstance(stored_fingerprint, Mapping)
        else ""
    )
    administrative_map_only_change = (
        SHA256_RE.fullmatch(current_semantic_map_digest) is not None
        and recorded_semantic_map_digest == current_semantic_map_digest
    )
    if recorded_map_digest != current_map_digest and not administrative_map_only_change:
        raise SystemExit(
            "source-record audit paper_statement_map_sha256 is stale for a "
            "nonadministrative current map change at "
            f"{audit_path}; regenerate the Lean-checked audit surface"
        )
    lean_check_payload = payload.get("lean_check")
    if (
        not isinstance(lean_check_payload, dict)
        or lean_check_payload.get("returncode") != 0
    ):
        raise SystemExit(
            "source-record judgment summary refresh requires an existing "
            f"successful Lean check at {audit_path}"
        )

    judgments = current_source_record_judgments(paper_dir, paper, payload)
    conclusion_dependencies = payload.get("conclusion_dependency_items") or []
    if not isinstance(conclusion_dependencies, list):
        raise SystemExit(
            f"source-record conclusion dependencies are malformed at {audit_path}"
        )
    (
        approved_source_convention_input_keys,
        approved_source_convention_field_keys,
    ) = current_approved_source_convention_antecedent_keys(
        paper_dir,
        payload,
        judgments,
    )
    approved_corrected_model_dependency_keys = (
        current_approved_corrected_model_dependency_keys(
            paper_dir, paper, payload
        )
    )
    resolved, unresolved = partition_conclusion_dependencies(
        [item for item in conclusion_dependencies if isinstance(item, dict)],
        judgments,
        approved_source_convention_input_keys=approved_source_convention_input_keys,
        approved_source_convention_field_keys=approved_source_convention_field_keys,
        raw_audit=payload,
        approved_corrected_model_dependency_keys=(
            approved_corrected_model_dependency_keys
        ),
    )
    payload.update(
        {
            "current_source_record_judgment_count": len(judgments),
            "resolved_conclusion_dependency_count": len(resolved),
            "resolved_conclusion_dependency_items": resolved,
            "unresolved_conclusion_dependency_count": len(unresolved),
            "unresolved_conclusion_dependency_items": unresolved,
        }
    )
    # Prompt text is rendered on demand by the manual-review/template command.
    # It is not evidence and no longer belongs in the canonical carrier.
    payload.pop("llm_judge_prompt", None)
    if write:
        atomic_write_text_if_changed(
            audit_path, json.dumps(payload, indent=2, sort_keys=True) + "\n"
        )
    return payload


def binder_names(raw_names: str) -> list[str]:
    return [
        name
        for name in re.split(r"\s+", raw_names.strip())
        if name and name not in {"_", "inst"} and not name.startswith("[") and not name.endswith("]")
    ]


def declaration_header(declaration: str) -> str:
    """Return the declaration signature before the proof/body."""

    body_start = declaration_body_start_index(declaration)
    head = declaration[:body_start] if body_start is not None else declaration
    where_start = top_level_word_index(head, "where")
    if where_start is not None:
        head = head[:where_start]
    return head.strip()


def declaration_body_start_index(declaration: str) -> int | None:
    """Locate a declaration value without consuming a result-local ``let``.

    A declaration result is a Lean term, so its local ``let`` bindings use the
    same ``:=`` token as a command's value. The audit only needs a conservative
    lexical boundary, but it must first recognize a top-level local binding and
    skip *that* assignment. In particular, choosing the first assignment (or
    any later assignment whose RHS begins with ``by``) truncates valid term-style
    declarations such as ``theorem t : let n := 1; n = 1 := rfl``.

    This scanner tracks ordinary grouping, strings/comments, and layout blocks
    introduced by a result-local ``let ... := by``. The latter matters because
    tactic-local ``have h := ...`` assignments are not declaration values. It
    intentionally does not use declaration or theorem names as evidence.
    """

    def keyword_at(index: int, keyword: str) -> bool:
        if not declaration.startswith(keyword, index):
            return False
        before = declaration[index - 1] if index else " "
        after_index = index + len(keyword)
        after = declaration[after_index] if after_index < len(declaration) else " "
        return not (before.isalnum() or before in "_'") and not (
            after.isalnum() or after in "_'"
        )

    depth = 0
    index = 0
    line_start = True
    line_indent = 0
    in_string = False
    block_comment_depth = 0
    local_let_assignment_pending = False
    local_let_indent: int | None = None
    local_let_by_indent: int | None = None

    while index < len(declaration):
        char = declaration[index]

        if in_string:
            if char == "\\":
                index += 2
                continue
            if char == '"':
                in_string = False
            if char == "\n":
                line_start = True
                line_indent = 0
            index += 1
            continue

        if block_comment_depth:
            if declaration.startswith("/-", index):
                block_comment_depth += 1
                index += 2
                continue
            if declaration.startswith("-/", index):
                block_comment_depth -= 1
                index += 2
                continue
            if char == "\n":
                line_start = True
                line_indent = 0
            index += 1
            continue

        if char == "\n":
            line_start = True
            line_indent = 0
            index += 1
            continue

        if line_start and char in " \t":
            line_indent += 1
            index += 1
            continue

        if declaration.startswith("--", index):
            newline = declaration.find("\n", index + 2)
            if newline < 0:
                return None
            index = newline
            continue

        if declaration.startswith("/-", index):
            block_comment_depth = 1
            index += 2
            continue

        if line_start:
            # A comment-only line cannot terminate a tactic block. Once a
            # non-comment token dedents to the local-let column, the result
            # term resumes and assignments there are eligible declaration
            # values again.
            if local_let_by_indent is not None and line_indent <= local_let_by_indent:
                local_let_by_indent = None
            line_start = False

        if local_let_by_indent is not None:
            index += 1
            continue

        if char == '"':
            in_string = True
            index += 1
            continue
        if char in "([{⦃":
            depth += 1
            index += 1
            continue
        if char in ")]}⦄" and depth > 0:
            depth -= 1
            index += 1
            continue

        if depth == 0:
            if keyword_at(index, "letI"):
                local_let_assignment_pending = True
                local_let_indent = line_indent
                index += len("letI")
                continue
            if keyword_at(index, "let"):
                local_let_assignment_pending = True
                local_let_indent = line_indent
                index += len("let")
                continue
            if declaration.startswith(":=", index):
                if local_let_assignment_pending:
                    local_let_assignment_pending = False
                    suffix = declaration[index + 2 :].lstrip()
                    if re.match(r"by\b", suffix):
                        local_let_by_indent = local_let_indent
                    local_let_indent = None
                    index += 2
                    continue
                return index
        index += 1
    return None


def top_level_token_index(text: str, token: str) -> int | None:
    """Return the first top-level occurrence of `token`, ignoring binder interiors."""

    depth = 0
    index = 0
    while index < len(text):
        char = text[index]
        if char in "([{⦃":
            depth += 1
            index += 1
            continue
        if char in ")]}⦄" and depth > 0:
            depth -= 1
            index += 1
            continue
        if depth == 0 and text.startswith(token, index):
            return index
        index += 1
    return None


def top_level_word_index(text: str, word: str) -> int | None:
    """Return the first top-level occurrence of a standalone Lean keyword."""

    depth = 0
    index = 0
    while index < len(text):
        char = text[index]
        if char in "([{⦃":
            depth += 1
            index += 1
            continue
        if char in ")]}⦄" and depth > 0:
            depth -= 1
            index += 1
            continue
        if depth == 0 and text.startswith(word, index):
            before = text[index - 1] if index else " "
            after_index = index + len(word)
            after = text[after_index] if after_index < len(text) else " "
            if not (before.isalnum() or before == "_") and not (
                after.isalnum() or after == "_"
            ):
                return index
        index += 1
    return None


def split_top_level_colon(text: str) -> tuple[str, str] | None:
    depth = 0
    for index, char in enumerate(text):
        if char in "([{⦃":
            depth += 1
        elif char in ")]}⦄" and depth > 0:
            depth -= 1
        elif char == ":" and depth == 0:
            return text[:index].strip(), text[index + 1 :].strip()
    return None


def balanced_binder_spans_with_delimiters(text: str) -> list[tuple[str, str]]:
    """Return each top-level Lean binder opener and its contents."""

    spans: list[tuple[str, str]] = []
    pairs = {"(": ")", "{": "}", "[": "]", "⦃": "⦄"}
    index = 0
    while index < len(text):
        opener = text[index]
        closer = pairs.get(opener)
        if closer is None:
            index += 1
            continue
        depth = 1
        cursor = index + 1
        while cursor < len(text) and depth > 0:
            char = text[cursor]
            if char == opener:
                depth += 1
            elif char == closer:
                depth -= 1
            cursor += 1
        if depth == 0:
            spans.append((opener, text[index + 1 : cursor - 1]))
            index = cursor
        else:
            index += 1
    return spans


def balanced_binder_spans(text: str) -> list[str]:
    """Return top-level Lean binder contents from a declaration header."""

    return [span for _opener, span in balanced_binder_spans_with_delimiters(text)]


def top_level_forall_binder_group_prefix(
    text: str,
) -> tuple[list[tuple[str, str]], str] | None:
    """Split leading grouped forall binders from one optional bare tail.

    A result binder such as ``alpha : ProbabilityMeasure (Sphere E)`` contains
    balanced parentheses in its *domain*.  Those parentheses are not binder
    groups.  Parse grouped binders only from the beginning of the prefix and
    leave the first non-group token as one bare tail.  Thus both ``∀ x : T
    (U), ...`` and mixed syntax such as ``∀ (x : T) y : U (x), ...`` retain
    the domain that Lean actually associates with each binder.
    """

    pairs = {"(": ")", "{": "}", "[": "]", "⦃": "⦄"}
    closers = set(pairs.values())
    spans: list[tuple[str, str]] = []
    index = 0
    length = len(text)
    while True:
        while index < length and text[index].isspace():
            index += 1
        if index == length:
            return spans, ""
        opener = text[index]
        if opener not in pairs:
            return spans, text[index:].strip()
        stack = [pairs[opener]]
        cursor = index + 1
        while cursor < length and stack:
            char = text[cursor]
            if char in pairs:
                stack.append(pairs[char])
            elif char in closers:
                if char != stack[-1]:
                    return None
                stack.pop()
            cursor += 1
        if stack:
            return None
        spans.append((opener, text[index + 1 : cursor - 1]))
        index = cursor


def split_top_level_arrow(text: str) -> tuple[str, str] | None:
    """Split the first top-level Lean implication arrow, if present."""

    depth = 0
    index = 0
    while index < len(text):
        char = text[index]
        if char in "([{⦃":
            depth += 1
            index += 1
            continue
        if char in ")]}⦄" and depth > 0:
            depth -= 1
            index += 1
            continue
        # An unparenthesized quantifier owns the remainder of its expression.
        # In particular, neither the arrow in a binder type such as
        # `∀ rho : Fin 2 → Policy, ...` nor implications in the quantified
        # body are top-level arrows of an enclosing conjunction.
        if depth == 0 and (
            char in "∀∃"
            or re.match(r"(?:forall|exists)\b", text[index:])
        ):
            return None
        if depth == 0 and char == "→":
            return text[:index].strip(), text[index + 1 :].strip()
        # Do not reinterpret the tail of ASCII equivalence `<->` as an
        # implication. Equivalence is a result connective, not an anonymous
        # theorem premise.
        if (
            depth == 0
            and text.startswith("->", index)
            and not (index > 0 and text[index - 1] == "<")
        ):
            return text[:index].strip(), text[index + 2 :].strip()
        index += 1
    return None


def split_top_level_commas(text: str) -> list[str]:
    """Split a comma-delimited Lean clause without splitting applications."""

    pieces: list[str] = []
    depth = 0
    start = 0
    for index, char in enumerate(text):
        if char in "([{⦃":
            depth += 1
        elif char in ")]}⦄" and depth > 0:
            depth -= 1
        elif char == "," and depth == 0:
            piece = text[start:index].strip()
            if piece:
                pieces.append(piece)
            start = index + 1
    tail = text[start:].strip()
    if tail:
        pieces.append(tail)
    return pieces


def split_leading_forall(text: str) -> tuple[str, str] | None:
    """Split a leading result-level `forall`/`∀` binder from its body."""

    stripped = text.strip()
    # `∀ᵐ` and `∀ᶠ` are notation for an almost-everywhere/eventually
    # proposition, respectively—not outer Lean Pi binders.  Treating their
    # displayed bound variable as a caller-supplied/result telescope binder
    # creates a false arity mismatch against Lean's elaborated signature.
    # Their complete proposition remains in the terminal result surface.
    if stripped.startswith(("∀ᵐ", "∀ᶠ")):
        return None
    if stripped.startswith("∀"):
        binder_start = 1
    elif re.match(r"^forall\b", stripped):
        binder_start = len("forall")
    else:
        return None

    depth = 0
    index = binder_start
    while index < len(stripped):
        char = stripped[index]
        if char in "([{⦃":
            depth += 1
        elif char in ")]}⦄" and depth > 0:
            depth -= 1
        elif char == "," and depth == 0:
            return stripped[binder_start:index].strip(), stripped[index + 1 :].strip()
        index += 1
    return None


def result_type_starts_with_local_let(type_text: str) -> bool:
    """Return whether a result remainder begins with a local `let` expression.

    A theorem type may introduce definitions with ``let``/``letI`` before its
    terminal proposition.  Those definitions are scoped inside the result;
    they are not caller-supplied proof inputs.  In particular, arrows in a
    local definition's type or value must not be reinterpreted as theorem
    premises.  This is deliberately a syntactic scope check at the result
    head, after balanced outer parentheses are removed, and never relies on a
    declaration or binder name.
    """

    head = strip_outer_group(type_text).strip()
    return bool(re.match(r"^let(?:I)?(?:\s|$)", head))


def result_type_inputs(
    type_text: str, used_names: set[str] | None = None
) -> tuple[list[dict[str, str]], str]:
    """Extract leading forall/arrow premises and the terminal result.

    Lean permits theorem premises after the declaration colon, for example
    `: P -> Q`, `: P → Q`, or `: ∀ h : P, Q`. These are semantically the same
    as ordinary declaration binders and must enter the provenance audit. A
    leading result-local ``let`` is instead retained as the terminal semantic
    surface, without descending into its local definition types or values.

    Prefix negation deliberately remains terminal. Although Lean implements
    ``Not P`` as ``P → False``, a source-facing transparent ``Spec`` records
    the nonreducing proposition boundary in a Lean-owned presentation
    telescope. Reinterpreting ``¬ P`` textually as another caller premise
    loses that boundary and can disagree with the exact presentation
    telescope. The later manifest alignment, not this parser, owns the
    accepted binder and conclusion structure.
    """

    inputs: list[dict[str, str]] = []
    occupied = set(used_names or set())
    anonymous_index = 1
    remainder = normalize_ws(type_text)

    def fresh_anonymous_name() -> str:
        nonlocal anonymous_index
        while True:
            candidate = f"result_premise_{anonymous_index}"
            anonymous_index += 1
            if candidate not in occupied:
                occupied.add(candidate)
                return candidate

    while remainder:
        # A leading local let scopes only over the theorem result.  The static
        # source boundary lane must not parse arrows within a local definition
        # as anonymous theorem premises.  Keep the whole expression as the
        # terminal result so the semantic-model lane can still inspect its
        # definitions and terminal proposition.
        if result_type_starts_with_local_let(remainder):
            break

        # A positive existential introduces output data. Any arrows in its
        # body describe properties of that witness, not caller-supplied
        # premises. Strip only a wrapper around the whole result, so an
        # existential used as an implication antecedent, `(exists x, P x) -> Q`,
        # is still handled below as a premise.
        result_head = strip_outer_group(remainder).strip()
        if result_head.startswith("∃") or re.match(r"^exists\b", result_head):
            break

        outer_arrow_split = split_top_level_arrow(remainder)
        if outer_arrow_split is None and (
            result_head.startswith("¬") or re.match(r"^Not\b", result_head)
        ):
            break

        forall_split = split_leading_forall(remainder)
        if forall_split is not None:
            binder_text, body = forall_split
            parsed: list[tuple[list[str], str]] = []
            group_prefix = top_level_forall_binder_group_prefix(binder_text)

            def parse_bare_forall_binder(text: str) -> tuple[list[str], str]:
                split = split_top_level_colon(text)
                if split is not None:
                    names = binder_names(split[0])
                    if not names:
                        names = [fresh_anonymous_name()]
                    return names, normalize_ws(split[1])
                names = binder_names(text)
                if not names:
                    names = [fresh_anonymous_name()]
                return names, ""

            if group_prefix is not None:
                spans, bare_tail = group_prefix
                for opener, span in spans:
                    split = split_top_level_colon(span)
                    if split is None:
                        if opener == "[":
                            # An anonymous typeclass binder is one binder whose
                            # complete bracket contents are its inferred type;
                            # tokenizing that type as binder names inflates the
                            # Lean-telescope arity and drops the real domain.
                            parsed.append(
                                ([fresh_anonymous_name()], normalize_ws(span))
                            )
                            continue
                        # Lean can infer the domain of an untyped result
                        # binder, e.g. `∀ terminal, ...`.  Preserve its
                        # position and names for a later elaborated-manifest
                        # receipt, but do not invent a parsed type or treat it
                        # as an ordinary source premise.
                        names = binder_names(span)
                        if not names:
                            names = [fresh_anonymous_name()]
                        parsed.append((names, ""))
                        continue
                    names = binder_names(split[0])
                    if not names:
                        names = [fresh_anonymous_name()]
                    parsed.append((names, normalize_ws(split[1])))
                if bare_tail:
                    parsed.append(parse_bare_forall_binder(bare_tail))
            else:
                parsed.append(parse_bare_forall_binder(binder_text))
            for names, premise_type in parsed:
                occupied.update(names)
                inputs.append(
                    {
                        "names": " ".join(names),
                        "type": premise_type,
                        "input_origin": (
                            "result_forall"
                            if premise_type
                            else "result_forall_inferred_domain"
                        ),
                    }
                )
            remainder = normalize_ws(body)
            continue

        arrow_split = outer_arrow_split
        if arrow_split is None:
            break
        premise_type, body = arrow_split
        if premise_type:
            stripped_premise = normalize_ws(strip_outer_group(premise_type))
            starts_with_quantifier = bool(
                stripped_premise.startswith(("∃", "∀"))
                or re.match(r"^(?:exists|forall)\b", stripped_premise)
            )
            dependent = (
                None
                if starts_with_quantifier
                else split_top_level_colon(stripped_premise)
            )
            if dependent is not None:
                raw_names, raw_type = dependent
                names = binder_names(raw_names) or [fresh_anonymous_name()]
                occupied.update(names)
                inputs.append(
                    {
                        "names": " ".join(names),
                        "type": normalize_ws(raw_type),
                        "input_origin": "result_arrow",
                    }
                )
            else:
                inputs.append(
                    {
                        "names": fresh_anonymous_name(),
                        "type": stripped_premise,
                        "input_origin": "result_arrow",
                    }
                )
        remainder = normalize_ws(body)

    return inputs, remainder


def dependent_if_guard_inputs(
    type_text: str, used_names: set[str] | None = None
) -> list[dict[str, str]]:
    """Expose proposition guards bound inside dependent result-level ``if`` terms.

    A result such as ``if h : check x = true then Claim h else True`` is
    semantically conditional on the guard even though ``h`` is not a
    declaration-header binder.  Scan every nested ``if`` occurrence so moving
    the same guard into an ``else if`` cannot evade conclusion provenance.

    The returned names are synthetic and position-based.  Audit behavior
    therefore does not depend on the spelling of the Lean proof binder.
    Ordinary Boolean ``if check x then ...`` terms have no dependent binder and
    are intentionally ignored here.
    """

    text = normalize_ws(type_text)
    occupied = set(used_names or set())
    inputs: list[dict[str, str]] = []
    guard_index = 1

    def fresh_guard_name() -> str:
        nonlocal guard_index
        while True:
            candidate = f"result_guard_{guard_index}"
            guard_index += 1
            if candidate not in occupied:
                occupied.add(candidate)
                return candidate

    for match in re.finditer(r"(?<![\w'])if(?![\w'])", text, re.UNICODE):
        after_if = text[match.end() :].strip()
        then_index = top_level_word_index(after_if, "then")
        if then_index is None:
            continue
        guard_clause = after_if[:then_index].strip()
        dependent = split_top_level_colon(guard_clause)
        if dependent is None:
            continue
        raw_names, guard_type = dependent
        if not binder_names(raw_names) or not guard_type:
            continue
        inputs.append(
            {
                "names": fresh_guard_name(),
                "type": normalize_ws(guard_type),
                "input_origin": "dependent_if_guard",
            }
        )
    return inputs


def header_inputs_from_declaration(declaration: str) -> list[dict[str, str]]:
    """Best-effort extraction of binders written before the declaration colon.

    Anonymous bracketed instance binders have no ``name : type`` split, but
    they are still visible theorem inputs. Preserve them with stable synthetic
    names so source-record auditing cannot silently omit model assumptions such
    as probability-measure or finiteness instances.
    """

    inputs: list[dict[str, str]] = []
    anonymous_instance_index = 1
    header = declaration_header(declaration)
    type_split = split_top_level_colon(header)
    binder_prefix = type_split[0] if type_split is not None else header
    for opener, span in balanced_binder_spans_with_delimiters(binder_prefix):
        is_instance_binder = opener == "["
        # `[∀ C : Carrier, Class (family C)]` is one anonymous instance
        # parameter whose *type* is a dependent function.  The colon belongs
        # to that type, not to a named outer binder.  Treating `∀ C` as a
        # binder name overcounts the elaborated telescope and can make a
        # source-result path look malformed.
        if is_instance_binder and normalize_ws(span).startswith("∀"):
            inputs.append(
                {
                    "names": f"instance_{anonymous_instance_index}",
                    "type": normalize_ws(span),
                    "input_origin": "instance_binder",
                }
            )
            anonymous_instance_index += 1
            continue
        split = split_top_level_colon(span)
        if split is None:
            type_text = normalize_ws(span)
            if type_text:
                inputs.append(
                    {
                        "names": f"instance_{anonymous_instance_index}",
                        "type": type_text,
                        "input_origin": "instance_binder",
                    }
                )
                anonymous_instance_index += 1
            continue
        raw_names, raw_type = split
        names = binder_names(raw_names)
        type_text = normalize_ws(raw_type)
        if not names or not type_text:
            continue
        inputs.append(
            {
                "names": " ".join(names),
                "type": type_text,
                **({"input_origin": "instance_binder"} if is_instance_binder else {}),
            }
        )
    return inputs


def conclusion_inputs_from_declaration(
    declaration: str, used_names: set[str] | None = None
) -> list[dict[str, str]]:
    """Return proof inputs embedded in the explicit result type."""

    header = declaration_header(declaration)
    type_split = split_top_level_colon(header)
    if type_split is not None:
        result_inputs, terminal_result = result_type_inputs(
            type_split[1], used_names
        )
        occupied = set(used_names or set())
        for result_input in result_inputs:
            occupied.update(binder_names(result_input.get("names", "")))
        result_inputs.extend(
            dependent_if_guard_inputs(terminal_result, occupied)
        )
        return result_inputs
    return []


def visible_inputs_from_declaration(
    declaration: str, *, include_result_inputs: bool = True
) -> list[dict[str, str]]:
    """Best-effort visible binder extraction from a Lean declaration.

    By default this includes result-level forall/arrow binders because helper
    declarations and inductive constructors may write real consumed premises
    after the colon.  For configured paper rows, callers can set
    ``include_result_inputs=False`` so theorem conclusion shape such as
    ``: ∀ x, P x → Q x`` is not mislabeled as an external source assumption.
    """

    inputs = header_inputs_from_declaration(declaration)
    if include_result_inputs:
        used_names = {
            name
            for visible_input in inputs
            for name in binder_names(visible_input.get("names", ""))
        }
        inputs.extend(conclusion_inputs_from_declaration(declaration, used_names))
    return inputs


def declaration_type_variable_heads(declaration: str) -> set[str]:
    """Return binder heads whose declared kind is ``Type`` or ``Sort``.

    Generic carrier variables are data because of their binder kind, regardless
    of whether they happen to be called ``Group``, ``Outcome``, or an
    adversarially neutral name. Keeping this context local avoids a global
    function-name whitelist while allowing fields such as ``Applicant → Group``
    to be recognized as data.
    """

    heads: set[str] = set()
    for visible_input in visible_inputs_from_declaration(declaration):
        type_text = alpha_canonical_type(visible_input.get("type", ""))
        if not re.match(r"^(?:Type|Sort)(?:\b|\s|\*|[0-9_(])", type_text):
            continue
        heads.update(binder_names(visible_input.get("names", "")))
    return heads


def boundary_input_kind(
    row: str,
    visible_input: dict[str, str],
    *,
    proposition_heads: set[str],
    data_heads: set[str],
) -> str:
    """Classify every direct proof-like input from its instantiated type.

    Binder names and source-looking type suffixes do not participate. Parsed
    record inputs are audited through their fields; ordinary carrier/function
    data are excluded; proof-valued and unknown non-data inputs enter the
    enforceable judgment surface. A bare predicate parameter such as
    ``α → α → Prop`` is model data, not a proof that any proposition holds.
    """

    _ = row
    type_text = visible_input.get("type", "")
    if is_definitely_data_type(
        type_text,
        proposition_heads=proposition_heads,
        data_heads=data_heads,
    ):
        return ""
    if is_proposition_type(type_text, proposition_heads):
        return "semantic_proposition_premise"
    return "semantic_unknown_nondata_premise"


def structural_domain_refinement_kinds(
    type_text: str, *, input_origin: str
) -> list[str]:
    """Expose visible carrier restrictions without treating names as evidence.

    These are candidate routes only. A candidate never establishes that the
    source model is coherent or that a theorem premise was proved; it tells
    the generic semantic-restriction gate which structurally visible condition
    cannot be silently treated as unrestricted data.
    """

    normalized = normalize_ws(strip_outer_group(type_text))
    candidates: set[str] = set()
    if input_origin == "instance_binder":
        candidates.add("instance_constraint")
    if re.match(r"^(?:@?Subtype\b|\{[^|{}]+\|)", normalized):
        candidates.add("subtype_domain_refinement")
    if re.match(r"^(?:@?(?:Sigma|PSigma)\b|Σ)", normalized):
        candidates.add("dependent_sigma_domain_refinement")
    return sorted(candidates)


def semantic_restriction_metadata(
    *,
    proposition_sort: str,
    semantic_input_kind: str,
    input_origin: str,
    specialized_kinds: list[str] | tuple[str, ...] = (),
) -> tuple[str, list[str]]:
    """Return closure policy and structural candidate evidence for one input.

    The result deliberately separates extraction from policy. Lean's sort and
    the static structural routes below are candidates; a positive closure
    still requires an exact source disposition or a checked Lean construction.
    """

    candidates: set[str] = set()
    if proposition_sort == "true":
        candidates.add("lean_proposition_value")
    elif proposition_sort == "unknown":
        candidates.add("unavailable_or_opaque_lean_sort")
    if semantic_input_kind == "semantic_unknown_nondata_premise":
        candidates.add("unclassified_nondata_surface")
    candidates.update(
        "structural_" + kind for kind in specialized_kinds if kind
    )
    if input_origin == "dependent_if_guard":
        candidates.add("dependent_result_guard")
    if input_origin == "instance_binder":
        candidates.add("instance_constraint")

    if proposition_sort == "true" or specialized_kinds:
        return "requires_source_or_lean_closure", sorted(candidates)
    if (
        proposition_sort == "unknown"
        or semantic_input_kind == "semantic_unknown_nondata_premise"
        or input_origin == "instance_binder"
    ):
        return "unclassified", sorted(candidates)
    return "carrier_coherence_only", sorted(candidates)


def theorem_realization_component_ledger(
    *,
    theorem_inputs: list[dict[str, Any]],
    recursive_fields: list[dict[str, Any]],
    conclusion_dependencies: list[dict[str, Any]],
    type_certificates: list[dict[str, Any]],
    semantic_model_items: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Emit the complete generated source-claim component ledger.

    This is not a classifier of a finite set of mathematical patterns.  It is
    the union of all generated theorem-realization surfaces: every elaborated
    theorem input, recursively reached record/model field, result certificate,
    and dependency path. A dependency is retained even when it shares a source
    judgment with an input: source-key equality is not an occurrence identity.
    Transitive proof/local dependency closure is owned by the recursive Lean
    Spec graph and is deliberately not duplicated by the bounded Python model
    traversal.
    """

    components: list[dict[str, Any]] = []
    def occurrence_path(
        item: Mapping[str, Any], *, section: str, kind: str, ordinal: int
    ) -> dict[str, object]:
        """Return a name-free generated structural position for one node."""

        outer_indices = item.get("lean_outer_binder_indices")
        if not isinstance(outer_indices, list):
            outer_indices = []
        return {
            "schema": 1,
            "surface": section,
            "kind": kind,
            "elaborated_signature_sha256": str(
                item.get("elaborated_signature_sha256") or ""
            ).strip().lower(),
            "outer_telescope_indices": [
                index for index in outer_indices if isinstance(index, int)
            ],
            "outer_telescope_route": str(
                item.get("lean_outer_binder_route") or ""
            ).strip(),
            "input_section": str(item.get("input_section") or "").strip(),
            "input_origin": str(item.get("input_origin") or "").strip(),
            "recursive_projection_sort": str(
                (item.get("elaborated_projection_receipt") or {}).get(
                    "proposition_sort", ""
                )
                if isinstance(item.get("elaborated_projection_receipt"), Mapping)
                else ""
            ).strip(),
            "traversal_slot": ordinal,
        }

    def append_component(
        item: Mapping[str, Any], *, section: str, kind: str, ordinal: int = 0,
    ) -> None:
        source_key = str(
            item.get("source_judgment_key") or item.get("judgment_key") or ""
        ).strip()
        if not source_key:
            return
        structural = str(item.get("structural_type_sha256") or "").strip().lower()
        component_identity = {
            "schema": 2,
            "occurrence": occurrence_path(
                item, section=section, kind=kind, ordinal=ordinal
            ),
            "structural_type_sha256": structural,
            "proposition_sort": str(item.get("proposition_sort") or "").strip(),
        }
        # A type digest is not an occurrence identity: two same-typed binders
        # need independent source contracts.  Bind the signature plus generated
        # structural position in every receipt.
        component_sha = stable_digest(component_identity)
        components.append(
            {
                **dict(item),
                "judgment_key": (
                    "theorem-realization::"
                    + section
                    + "::"
                    + kind
                    + "::"
                    + component_sha
                ),
                "source_judgment_key": source_key,
                "source_component_section": section,
                "source_claim_component_role": "material",
                "source_claim_component_kind": kind,
                "source_claim_component_sha256": component_sha,
                "source_claim_component_occurrence": component_identity[
                    "occurrence"
                ],
                "source_claim_component_structural_type_sha256": structural,
                "required_check": (
                    "Complete source-claim semantic contract: this generated theorem-realization "
                    "component needs an exact source claim, explicit anchored correction/additional "
                    "assumption, current source-domain correspondence, or Lean-checked derivation. "
                    "Its declaration/field name is navigation only."
                ),
            }
        )

    for ordinal, item in enumerate(theorem_inputs):
        append_component(
            item,
            section="theorem_facing_input_items",
            kind="theorem_input",
            ordinal=ordinal,
        )
    for ordinal, item in enumerate(recursive_fields):
        append_component(
            item,
            section="recursive_field_items",
            kind="recursive_record_field",
            ordinal=ordinal,
        )
    for ordinal, item in enumerate(conclusion_dependencies):
        append_component(
            item,
            section="conclusion_dependency_items",
            kind="dependency_path",
            ordinal=ordinal,
        )
    for ordinal, item in enumerate(type_certificates):
        append_component(
            item,
            section="type_valued_certificate_result_items",
            kind="result_type_certificate",
            ordinal=ordinal,
        )

    # `semantic_model_items` remain a required input so the caller cannot
    # silently revert to a pre-semantic-model producer shape. Their transitive
    # local/proof dependency closure is checked by Lean's recursive Spec graph,
    # rather than reimplemented as a second occurrence ledger here.
    _ = semantic_model_items
    return components


def boundary_input_result_relation(
    declaration: str,
    visible_input: dict[str, str],
    *,
    proposition_heads: set[str],
    proposition_aliases: dict[str, PropositionAliasInfo] | None = None,
) -> str:
    """Relate a direct proof premise to the theorem's advertised result.

    This is intentionally type-shaped rather than name-shaped.  In particular,
    a theorem that accepts the feasibility, cost, or runtime conjuncts of its
    own advertised optimization result must expose that relationship to the
    source-coverage gate even when every declaration and binder is renamed.
    Ordinary model assumptions that are not a result component return ``""``.
    """

    input_type = visible_input.get("type", "")
    result_type = declaration_terminal_result_type(declaration)
    if is_definitely_data_type(
        input_type,
        proposition_heads=proposition_heads,
    ):
        return ""
    if not (
        is_proposition_type(input_type, proposition_heads)
        and is_proposition_type(result_type, proposition_heads)
    ):
        return ""
    return proposition_type_relation(
        input_type,
        result_type,
        proposition_aliases,
    )


def boundary_input_judgment_key(row: str, visible_input: dict[str, str]) -> str:
    names = normalize_ws(visible_input.get("names", ""))
    type_text = normalize_ws(visible_input.get("type", ""))
    return f"{row}.{names} : {type_text}"


def parse_status_review_surface_names(status_path: Path, keys: tuple[str, ...]) -> list[str]:
    if not status_path.exists():
        return []
    payload = json.loads(read_text(status_path))
    review_surface = payload.get("review_surface")
    if not isinstance(review_surface, dict):
        return []
    names: list[str] = []
    for key in keys:
        raw = review_surface.get(key)
        if isinstance(raw, list):
            names.extend(str(item) for item in raw if isinstance(item, str) and item.strip())
    return list(dict.fromkeys(names))


def parse_status_rows(status_path: Path) -> list[str]:
    """Return the human semantic-review rows, never proof endpoints.

    A paper may store exact-type theorem endpoints in ``ProofInterface.lean``.
    They are machine proof evidence for the Specs below, not second paper
    claims and therefore do not belong in the human review denominator.
    """

    return parse_status_review_surface_names(
        status_path, ("include_names", "assumption_names")
    )


def parse_status_proof_endpoint_rows(status_path: Path) -> list[str]:
    """Return the separately configured machine-only Spec proof endpoints."""

    if not status_path.exists():
        return []
    payload = load_json_object(status_path)
    review_surface = payload.get("review_surface")
    if not isinstance(review_surface, Mapping):
        return []
    raw = review_surface.get("proposition_spec_proofs")
    if not isinstance(raw, Mapping):
        return []
    return list(
        dict.fromkeys(
            str(proof).strip()
            for proof in raw.values()
            if isinstance(proof, str) and proof.strip()
        )
    )


def parse_status_machine_rows(status_path: Path) -> list[str]:
    """Return semantic rows plus their machine-only proof endpoints.

    This is intentionally internal to the source-record producer.  Consumers
    that render or count human paper claims continue to use
    :func:`parse_status_rows`.
    """

    return list(
        dict.fromkeys(
            [*parse_status_rows(status_path), *parse_status_proof_endpoint_rows(status_path)]
        )
    )


def parse_status_auxiliary_rows(status_path: Path) -> list[str]:
    return parse_status_review_surface_names(status_path, ("auxiliary_names",))


def parse_status_quarantined_auxiliary_rows(status_path: Path) -> list[str]:
    """Read helpers explicitly barred from paper-facing review credit."""

    return parse_status_review_surface_names(
        status_path, ("quarantined_auxiliary_names",)
    )


def semantic_model_review_config(
    status_path: Path,
) -> tuple[list[str], list[str]]:
    """Read the opt-in semantic model review configuration fail-closed.

    The recursive source-record lane is useful for every paper, while this
    stricter comparison lane is introduced for newly scaffolded papers and
    individual remediation passes.  Keeping it explicit avoids invalidating
    historical evidence merely because the workflow gained a new review
    dimension.  Once enabled, malformed configuration must not quietly turn
    the dimensions off.
    """

    payload = load_json_object(status_path)
    review_surface = payload.get("review_surface")
    if not isinstance(review_surface, dict):
        return [], []
    raw = review_surface.get("semantic_model_review")
    if raw is None:
        return [], []
    if not isinstance(raw, dict):
        return [], ["review_surface.semantic_model_review must be an object"]

    errors: list[str] = []
    schema = raw.get("schema")
    if schema not in {
        SEMANTIC_MODEL_REVIEW_LEGACY_SCHEMA,
        SEMANTIC_MODEL_REVIEW_SCHEMA,
    }:
        errors.append(
            "review_surface.semantic_model_review.schema must be "
            f"{SEMANTIC_MODEL_REVIEW_LEGACY_SCHEMA} (legacy) or "
            f"{SEMANTIC_MODEL_REVIEW_SCHEMA}"
        )
    dimensions = raw.get("required_dimensions")
    if not isinstance(dimensions, list) or not dimensions:
        errors.append(
            "review_surface.semantic_model_review.required_dimensions must be a "
            "nonempty list"
        )
        return [], errors
    normalized = [str(item).strip() for item in dimensions]
    unknown = sorted(
        {
            item
            for item in normalized
            if item not in SEMANTIC_MODEL_DIMENSION_CHECKS
        }
    )
    if unknown:
        errors.append(
            "review_surface.semantic_model_review.required_dimensions has "
            "unknown dimension(s): "
            + ", ".join(unknown)
        )
    if len(set(normalized)) != len(normalized):
        errors.append(
            "review_surface.semantic_model_review.required_dimensions must not "
            "repeat a dimension"
        )
    if schema == SEMANTIC_MODEL_REVIEW_LEGACY_SCHEMA:
        schema_two_dimensions = sorted(
            set(normalized) - set(SEMANTIC_MODEL_LEGACY_DIMENSION_ORDER)
        )
        if schema_two_dimensions:
            errors.append(
                "review_surface.semantic_model_review schema 1 is legacy and cannot "
                "request schema-2 dimension(s): "
                + ", ".join(schema_two_dimensions)
            )
    elif schema == SEMANTIC_MODEL_REVIEW_SCHEMA:
        missing = sorted(set(SEMANTIC_MODEL_DIMENSION_ORDER) - set(normalized))
        if missing:
            errors.append(
                "review_surface.semantic_model_review schema 2 must require every "
                "expanded-semantic dimension; missing: "
                + ", ".join(missing)
            )
    if errors:
        return [], errors
    # Preserve the stable workflow order even if a status file lists dimensions
    # in a different order. This is evidence ordering, not a mathematical
    # priority or a declaration-name heuristic.
    requested = set(normalized)
    return [
        dimension
        for dimension in SEMANTIC_MODEL_DIMENSION_ORDER
        if dimension in requested
    ], []


def explicit_source_target_declarations_for_semantic_review(
    status_path: Path,
) -> tuple[list[str], list[str]]:
    """Read opt-in non-normal source targets without name-based inference.

    Normal paper coverage deliberately remains the byte-pinned named-theory
    inventory.  A paper can additionally nominate an unnumbered but
    claim-bearing source-model/display result for the semantic-model lane.
    The declaration is only a selector: a later source-map resolver must
    prove that exactly one current source item, anchor, and semantic contract
    own it.  This parser therefore accepts neither short names nor a fallback
    inferred from the review surface.

    The field is optional so existing schema-1/schema-2 campaigns retain their
    present behavior.  When a paper uses it, require schema 2: the expanded
    semantic dimensions are the minimum review surface for a newly selected
    model result.
    """

    payload = load_json_object(status_path)
    review_surface = payload.get("review_surface")
    if not isinstance(review_surface, Mapping):
        return [], []
    raw = review_surface.get("semantic_model_review")
    if not isinstance(raw, Mapping):
        # ``semantic_model_review_config`` owns the malformed-container error.
        return [], []
    raw_targets = raw.get("explicit_source_target_declarations")
    if raw_targets is None:
        return [], []
    if not isinstance(raw_targets, list):
        return [], [
            "review_surface.semantic_model_review.explicit_source_target_declarations "
            "must be a list of exact fully-qualified Lean declarations"
        ]
    errors: list[str] = []
    if raw.get("schema") != SEMANTIC_MODEL_REVIEW_SCHEMA:
        errors.append(
            "review_surface.semantic_model_review.explicit_source_target_declarations "
            f"requires schema {SEMANTIC_MODEL_REVIEW_SCHEMA}"
        )
    targets: list[str] = []
    for index, raw_target in enumerate(raw_targets):
        target = semantic_contract_fully_qualified_identity(raw_target)
        if not target:
            errors.append(
                "review_surface.semantic_model_review.explicit_source_target_declarations["
                f"{index}] must be an exact fully-qualified Lean declaration"
            )
            continue
        if target in targets:
            errors.append(
                "review_surface.semantic_model_review.explicit_source_target_declarations "
                f"contains duplicate declaration {target!r}"
            )
            continue
        targets.append(target)
    return targets, errors


def review_source_path(root: Path, paper_dir: Path, status_path: Path) -> Path:
    """Return the Lean file that contains the configured review-surface rows."""

    def display_path(path: Path) -> str:
        try:
            return str(path.relative_to(root))
        except ValueError:
            return str(path)

    canonical = paper_dir / "PaperInterface.lean"
    if status_path.exists():
        payload = json.loads(read_text(status_path))
        review_surface = payload.get("review_surface")
        if isinstance(review_surface, dict):
            raw = review_surface.get("source_file")
            if isinstance(raw, str) and raw.strip():
                path = Path(raw.strip())
                if path.is_absolute():
                    resolved = path
                elif len(path.parts) == 1:
                    resolved = paper_dir / path
                else:
                    resolved = root / path
                if resolved.resolve() != canonical.resolve():
                    raise ValueError(
                        f"{status_path}: review_surface.source_file must resolve to "
                        f"{display_path(canonical)}; got {display_path(resolved)}"
                    )
    return canonical


def proof_endpoint_source_path(
    root: Path,
    paper_dir: Path,
    status_path: Path,
    *,
    interface_path: Path | None = None,
) -> Path | None:
    """Return the optional machine-only theorem-endpoint source.

    ``PaperInterface.lean`` remains the only semantic review surface.  A
    distinct ``ProofInterface.lean`` supplies exact-type proof endpoints, so
    raw audit tooling must read it without converting its theorems into extra
    source-review rows.
    """

    resolved = paper_dir / "ProofInterface.lean"
    configured = False
    if status_path.exists():
        payload = load_json_object(status_path)
        review_surface = payload.get("review_surface")
        if isinstance(review_surface, Mapping):
            raw = review_surface.get("proof_file")
            if isinstance(raw, str) and raw.strip():
                configured = True
                path = Path(raw.strip())
                if path.is_absolute():
                    resolved = path
                elif len(path.parts) == 1:
                    resolved = paper_dir / path
                else:
                    resolved = root / path
    if interface_path is not None and resolved.resolve() == interface_path.resolve():
        return None
    if configured and not resolved.is_file():
        raise ValueError(
            f"{status_path}: review_surface.proof_file is missing at {resolved}"
        )
    return resolved if resolved.is_file() else None


def assumption_source_path(
    root: Path,
    paper_dir: Path,
    status_path: Path,
    *,
    interface_path: Path | None = None,
) -> Path | None:
    """Return the separately reviewed assumption surface, if there is one.

    Most papers use the conventional paper-local ``Assumptions.lean``.  A
    compact interface may instead deliberately place every active premise in
    ``PaperInterface.lean``.  In that case the configured path is useful to
    other workflow consumers, but source-record generation must not parse the
    same declarations twice or silently fall back to a historical sibling
    ``Assumptions.lean``.
    """

    resolved = paper_dir / "Assumptions.lean"
    if status_path.exists():
        payload = json.loads(read_text(status_path))
        review_surface = payload.get("review_surface")
        if isinstance(review_surface, Mapping):
            raw = review_surface.get("assumption_source_file")
            if isinstance(raw, str) and raw.strip():
                configured = Path(raw.strip())
                if configured.is_absolute():
                    resolved = configured
                elif len(configured.parts) == 1:
                    resolved = paper_dir / configured
                else:
                    resolved = root / configured
    if interface_path is not None and resolved.resolve() == interface_path.resolve():
        return None
    return resolved


def effective_source_record_assumption_path(
    root: Path,
    paper_dir: Path,
    status_path: Path,
    *,
    interface_path: Path,
    lean_import_closure: SourceRecordLeanImportClosure | None,
) -> Path | None:
    """Return an assumption source that belongs to the active audit surface.

    A scaffold may retain an empty, unimported ``Assumptions.lean`` file.  It
    is not a paper premise merely because it exists beside the interface.  An
    assumption source becomes audit material when status explicitly selects an
    assumption row or Lean's loaded proof/interface closure reaches the file.
    The former case remains fail-closed when the configured source is not in
    the authenticated closure; the latter catches imported but accidentally
    unregistered support declarations.

    ``None`` for ``lean_import_closure`` preserves the conservative historical
    behavior used by static diagnostics that have not acquired Lean authority.
    """

    path = assumption_source_path(
        root,
        paper_dir,
        status_path,
        interface_path=interface_path,
    )
    if parse_status_review_surface_names(status_path, ("assumption_names",)):
        return path
    if lean_import_closure is None:
        return path
    closure_sources = {
        source.resolve() for source in lean_import_closure.repository_sources
    }
    return path if path.resolve() in closure_sources else None


def lean_module_name(root: Path, path: Path) -> str:
    """Return the Lean module name for a repository Lean file."""

    rel = path.resolve().relative_to(root).with_suffix("")
    parts = list(rel.parts)
    if parts and parts[0] == "papers":
        parts = parts[1:]
    return ".".join(parts)


def update_namespace_scopes(line: str, scopes: list[tuple[str, list[str]]]) -> bool:
    """Update namespace/section scopes; return whether the line was a scope command."""

    stripped = line.strip()
    if stripped.startswith("namespace "):
        raw = stripped.removeprefix("namespace ").strip()
        scopes.append(("namespace", [part for part in raw.split(".") if part]))
        return True
    if stripped == "section" or stripped.startswith("section "):
        scopes.append(("section", []))
        return True
    if stripped == "end" or stripped.startswith("end "):
        if scopes:
            scopes.pop()
        return True
    return False


def active_namespace(scopes: list[tuple[str, list[str]]]) -> str:
    parts = [part for kind, names in scopes if kind == "namespace" for part in names]
    return ".".join(parts)


def qualify_declaration_name(raw_name: str, scopes: list[tuple[str, list[str]]]) -> str:
    namespace = active_namespace(scopes)
    return f"{namespace}.{raw_name}" if namespace else raw_name


def declaration_match_at(lines: list[str], index: int) -> re.Match[str] | None:
    """Match a declaration head even when Lean puts its name on a later line.

    Lean permits both ``theorem name`` and ``theorem\n  name``.  The source
    audit must not silently lose a configured row merely because formatting
    changes, so parse a small declaration-head window rather than relying on
    a declaration name sharing the keyword's line.
    """

    if index >= len(lines) or not DECLARATION_START_RE.match(lines[index]):
        return None
    return DECL_RE.match("\n".join(lines[index : index + DECLARATION_HEAD_LOOKAHEAD_LINES]))


def structure_match_at(lines: list[str], index: int) -> re.Match[str] | None:
    """Match a structure/class head across ordinary Lean line wrapping."""

    if index >= len(lines) or not STRUCTURE_START_RE.match(lines[index]):
        return None
    return STRUCTURE_RE.match("\n".join(lines[index : index + DECLARATION_HEAD_LOOKAHEAD_LINES]))


def parse_declarations(
    interface_path: Path, *, source_text: str | None = None
) -> dict[str, str]:
    """Parse declarations keyed by namespace-qualified semantic identity."""

    lines = mask_lean_comments(
        read_text(interface_path) if source_text is None else source_text
    ).splitlines()
    decls: dict[str, str] = {}
    scopes: list[tuple[str, list[str]]] = []
    index = 0
    while index < len(lines):
        if update_namespace_scopes(lines[index], scopes):
            index += 1
            continue
        match = declaration_match_at(lines, index)
        if not match:
            index += 1
            continue
        name = qualify_declaration_name(match.group(2), scopes)
        start = index
        index += 1
        while index < len(lines) and not TOP_LEVEL_RE.match(lines[index]):
            index += 1
        if name in decls:
            raise ValueError(
                f"duplicate declaration identity {name!r} in {interface_path}"
            )
        decls[name] = "\n".join(lines[start:index]).strip()
    return decls


def lexical_name_candidates(
    reference: str,
    names: set[str],
    *,
    context_namespace: str = "",
) -> list[str]:
    """Resolve a relative Lean name through enclosing namespaces before suffixes.

    The audit parser does not elaborate terms, but it can preserve Lean's
    lexical namespace rule.  A short name in ``A.B`` is first searched as
    ``A.B.name`` and then ``A.name``.  Only when no lexical candidate exists do
    we expose all matching suffixes to the caller, which must fail closed on
    ambiguity rather than choose one by declaration spelling or traversal order.
    """

    namespace_parts = [part for part in context_namespace.split(".") if part]
    for index in range(len(namespace_parts), -1, -1):
        candidate = ".".join([*namespace_parts[:index], reference])
        if candidate in names:
            return [candidate]
    return sorted(name for name in names if name.endswith(f".{reference}"))


def resolve_declaration_reference(
    reference: str,
    declarations: dict[str, str],
    *,
    preferred_namespace: str = "",
) -> str | None:
    """Resolve one declaration reference, failing closed on short-name ambiguity."""

    matches = lexical_name_candidates(
        reference,
        set(declarations),
        context_namespace=preferred_namespace,
    )
    if len(matches) > 1:
        raise ValueError(
            f"ambiguous declaration reference {reference!r}: " + ", ".join(matches)
        )
    return matches[0] if matches else None


def unconfigured_review_declarations(
    declarations: dict[str, str],
    *,
    selected_names: set[str],
    auxiliary_names: set[str],
    quarantined_auxiliary_names: set[str],
) -> list[str]:
    """Return omitted declarations within one explicitly named review scope.

    `PaperInterface.lean` is the paper-facing surface.  `Assumptions.lean`
    contains support-model declarations that may be selected as premises, but
    is not itself a second paper interface.  Keeping the scopes separate here
    prevents an implementation declaration from being mislabeled as an
    unconfigured paper-facing row.  Once a structured selected or auxiliary
    root is covered, its projections are recursively audited with that root
    rather than becoming separately omitted rows.  The decision uses parsed
    declarations and declaration kinds, never declaration-name conventions.
    """

    selected_or_auxiliary_containers = {
        name
        for name in (
            selected_names | auxiliary_names | quarantined_auxiliary_names
        )
        if (match := DECL_RE.match(declarations.get(name, ""))) is not None
        and match.group(1) in {"structure", "class", "inductive"}
    }
    return [
        name
        for name in sorted(declarations)
        if name not in selected_names
        and name not in auxiliary_names
        and not any(
            name.startswith(f"{container}.")
            for container in selected_or_auxiliary_containers
        )
        and name not in quarantined_auxiliary_names
    ]


def parse_local_declarations(
    root: Path,
    lean_files: list[Path],
    *,
    source_text_by_path: Mapping[Path, str] | None = None,
) -> list[LocalDeclaration]:
    """Return declarations with stable paper-local source locations."""

    out: list[LocalDeclaration] = []
    for lean_file in lean_files:
        try:
            rel_file = str(lean_file.resolve().relative_to(root))
        except ValueError:
            rel_file = str(lean_file)
        source_text = source_text_from_snapshot(lean_file, source_text_by_path)
        text = mask_lean_comments(source_text)
        declarations = parse_declarations(lean_file, source_text=source_text)
        declaration_lines: dict[str, int] = {}
        scopes: list[tuple[str, list[str]]] = []
        lines = text.splitlines()
        for index, line_text in enumerate(lines):
            line_number = index + 1
            if update_namespace_scopes(line_text, scopes):
                continue
            line_match = declaration_match_at(lines, index)
            if line_match is not None:
                qualified = qualify_declaration_name(line_match.group(2), scopes)
                declaration_lines.setdefault(qualified, line_number)
        for name, source in declarations.items():
            match = DECL_RE.match(source)
            if match is None:
                continue
            out.append(
                LocalDeclaration(
                    name=name,
                    kind=match.group(1),
                    source=source,
                    source_file=rel_file,
                    line=declaration_lines.get(name, 1),
                )
            )
    return out


def declaration_result_type(declaration: str) -> str:
    """Return a normalized explicit result type from a Lean declaration."""

    split = split_top_level_colon(declaration_header(declaration))
    return normalize_ws(split[1]) if split is not None else ""


def declaration_terminal_result_type(declaration: str) -> str:
    """Return the consequent after result-level forall/arrow premises."""

    result_type = declaration_result_type(declaration)
    return result_type_inputs(result_type)[1] if result_type else ""


def declaration_body_text(declaration: str) -> str:
    body_start = declaration_body_start_index(declaration)
    if body_start is None:
        return ""
    return declaration[body_start + 2 :].strip()


def inferred_proposition_alias_body(body: str) -> bool:
    """Recognize only clear outer proposition syntax for inferred aliases.

    A computational definition such as ``if x = y then a else b`` contains an
    equality but does not return a proposition. Reject data-producing term
    introducers before using the ordinary outer-result classifier.
    """

    text = strip_outer_group(normalize_ws(body)).strip()
    if (
        not text
        or re.match(r"^(?:if|let|match|fun|do)\b", text)
        or "=>" in text
        or re.search(r"(?:→|->)\s*Prop\s*$", text)
    ):
        return False
    if text.startswith(("∀", "∃", "¬")) or re.match(
        r"^(?:forall|exists|Not|True|False)\b", text
    ):
        return True

    depth = 0
    index = 0
    while index < len(text):
        char = text[index]
        if char in "([{⦃":
            depth += 1
            index += 1
            continue
        if char in ")]}⦄" and depth > 0:
            depth -= 1
            index += 1
            continue
        if depth == 0:
            if text.startswith(("<->", "/\\", "\\/"), index):
                return True
            if char in "↔∧∨≠≤≥∈∉⊆⊂⊇⊃" or (
                char in "<>"
                and not (char == ">" and index > 0 and text[index - 1] in "-=")
            ):
                return True
            if (
                char == "="
                and not text.startswith(("=>", "=="), index)
                and (index == 0 or text[index - 1] not in ":=!<>")
            ):
                return True
        index += 1
    return False


def parse_proposition_aliases(
    declarations: list[LocalDeclaration],
) -> dict[str, PropositionAliasInfo]:
    """Return reducible ``def``/``abbrev`` aliases whose value is a proposition.

    These aliases must be unfolded before circularity comparison. Otherwise a
    constructor can accept ``Alias x`` where ``Alias x`` reduces to the target
    conclusion and appear to consume an unrelated source antecedent.
    """

    qualified_aliases: dict[str, PropositionAliasInfo] = {}
    aliases_by_short_name: dict[str, set[str]] = {}
    short_name_counts = local_declaration_short_name_counts(declarations)
    candidates = [
        declaration
        for declaration in declarations
        if declaration.kind in {"def", "abbrev"}
        and (body := declaration_body_text(declaration.source))
        and not body.startswith("by")
    ]

    def add_alias(declaration: LocalDeclaration) -> None:
        body = declaration_body_text(declaration.source)
        parameters = [
            name
            # A proposition alias's parameters are precisely its declaration
            # header binders.  Quantifiers in its body are part of the
            # proposition being expanded, not extra call arguments; treating
            # them as parameters can replace a real carrier with a synthetic
            # `__propArg` and conceal a direct/Spec equality mismatch.
            for visible_input in header_inputs_from_declaration(declaration.source)
            for name in binder_names(visible_input.get("names", ""))
        ]
        info = PropositionAliasInfo(
            name=declaration.name,
            parameters=parameters,
            body=body,
        )
        qualified_aliases[declaration.name] = info
        short_name = declaration.name.rsplit(".", 1)[-1]
        aliases_by_short_name.setdefault(short_name, set()).add(declaration.name)

    pending: list[LocalDeclaration] = []
    for declaration in candidates:
        result_type = declaration_result_type(declaration.source)
        if alpha_canonical_type(result_type) == "Prop" or (
            not result_type
            and inferred_proposition_alias_body(
                declaration_body_text(declaration.source)
            )
        ):
            add_alias(declaration)
        else:
            pending.append(declaration)

    # Infer only transparent chains whose outer head resolves uniquely to an
    # already classified proposition alias. This avoids global short-name
    # guesses when unrelated imported modules reuse neutral declaration names.
    while pending:
        next_pending: list[LocalDeclaration] = []
        changed = False
        for declaration in pending:
            body = strip_outer_group(
                declaration_body_text(declaration.source)
            ).strip()
            head_match = re.match(
                r"@?((?:[A-Za-z_][A-Za-z0-9_']*\.)*"
                r"[A-Za-z_][A-Za-z0-9_']*)\b",
                body,
            )
            if head_match is None:
                next_pending.append(declaration)
                continue
            raw_head = head_match.group(1)
            context_namespace = (
                declaration.name.rsplit(".", 1)[0]
                if "." in declaration.name
                else ""
            )
            head_matches = lexical_name_candidates(
                raw_head,
                set(qualified_aliases),
                context_namespace=context_namespace,
            )
            if len(head_matches) != 1:
                next_pending.append(declaration)
                continue
            add_alias(declaration)
            changed = True
        if not changed:
            break
        pending = next_pending

    aliases = dict(qualified_aliases)
    for short_name, qualified_names in aliases_by_short_name.items():
        if len(qualified_names) == 1:
            if short_name_counts[short_name] == 1:
                qualified_name = next(iter(qualified_names))
                aliases.setdefault(short_name, qualified_aliases[qualified_name])
            continue

        # A bare duplicate is deliberately left unresolved. Constructing a
        # synthetic disjunction would make the audit's conclusion relation
        # depend on declaration spelling rather than the namespace Lean uses.
        # Callers with a lexical context recover the correct qualified alias
        # through `proposition_aliases_in_namespace`; callers without one keep
        # the premise as an unknown proof-bearing boundary.
    return aliases


_PROPOSITION_ALIAS_IDENTIFIER_RE = re.compile(
    r"(?<![\w'])(@?(?:[^\W\d][\w']*\.)*[^\W\d][\w']*)(?![\w'])",
    re.UNICODE,
)
_PROPOSITION_ALIAS_ARGUMENT_STOP_CHARS = set(
    ",)]}⦄→↔∧∨=≠≤≥<>∈∉⊆⊂⊇⊃"
)


def _next_proposition_alias_argument_span(
    text: str, start: int
) -> tuple[int, int] | None:
    """Return the next surface application argument without crossing logic syntax."""

    cursor = start
    while cursor < len(text) and text[cursor].isspace():
        cursor += 1
    if cursor >= len(text):
        return None
    if text.startswith(("->", ":=", "=>"), cursor):
        return None
    if text[cursor] in _PROPOSITION_ALIAS_ARGUMENT_STOP_CHARS:
        return None
    pairs = {"(": ")", "[": "]", "{": "}", "⦃": "⦄"}
    opener = text[cursor]
    if opener in pairs:
        stack = [pairs[opener]]
        end = cursor + 1
        while end < len(text) and stack:
            char = text[end]
            if char in pairs:
                stack.append(pairs[char])
            elif char == stack[-1]:
                stack.pop()
            end += 1
        return (cursor, end) if not stack else None

    end = cursor
    while end < len(text):
        if text.startswith(("->", ":=", "=>"), end):
            break
        char = text[end]
        if char.isspace() or char in _PROPOSITION_ALIAS_ARGUMENT_STOP_CHARS:
            break
        end += 1
    return (cursor, end) if end > cursor else None


def _unfold_proposition_alias_once(
    type_text: str,
    aliases: dict[str, PropositionAliasInfo],
    *,
    missing_argument_bindings: Mapping[str, Mapping[str, str]] | None = None,
) -> str:
    """Unfold one reducible proposition alias application anywhere in a type."""

    text = normalize_ws(type_text)
    for match in _PROPOSITION_ALIAS_IDENTIFIER_RE.finditer(text):
        raw_head = match.group(1).lstrip("@")
        # Callers that need a relative declaration must first provide the
        # lexical namespace map above. Never reinterpret a qualified missing
        # head through an unrelated short-name alias.
        info = aliases.get(raw_head)
        if info is None:
            continue

        argument_spans: list[tuple[int, int]] = []
        cursor = match.end()
        for _ in info.parameters:
            span = _next_proposition_alias_argument_span(text, cursor)
            if span is None:
                break
            argument_spans.append(span)
            cursor = span[1]
        application_args = [text[start:end] for start, end in argument_spans]
        parameter_count = len(info.parameters)
        parameter_offset = max(0, parameter_count - len(application_args))
        raw_fallbacks = (
            (missing_argument_bindings or {}).get(info.name)
            if isinstance(missing_argument_bindings, Mapping)
            else None
        )
        fallbacks = (
            {
                str(parameter): str(argument)
                for parameter, argument in raw_fallbacks.items()
                if str(parameter).strip() and str(argument).strip()
            }
            if isinstance(raw_fallbacks, Mapping)
            else {}
        )
        substitutions = {
            parameter: (
                application_args[index - parameter_offset]
                if parameter_offset <= index < parameter_offset + len(application_args)
                else fallbacks.get(parameter, f"__propArg{index}")
            )
            for index, parameter in enumerate(info.parameters)
        }
        body = info.body
        for parameter, argument in substitutions.items():
            body = re.sub(
                rf"(?<![\w']){re.escape(parameter)}(?![\w'])",
                lambda _match, replacement=argument: replacement,
                body,
            )
        application_end = argument_spans[-1][1] if argument_spans else match.end()
        return normalize_ws(
            text[: match.start()] + f"({body})" + text[application_end:]
        )
    return text


def unfold_proposition_aliases(
    type_text: str,
    aliases: dict[str, PropositionAliasInfo] | None,
    *,
    missing_argument_bindings: Mapping[str, Mapping[str, str]] | None = None,
) -> str:
    """Unfold nested and multi-hop reducible proposition aliases in a type."""

    text = normalize_ws(type_text)
    if not aliases:
        return text
    seen: set[str] = set()
    for _ in range(64):
        key = canonical_type(text)
        if key in seen:
            break
        seen.add(key)
        unfolded = _unfold_proposition_alias_once(
            text,
            aliases,
            missing_argument_bindings=missing_argument_bindings,
        )
        if canonical_type(unfolded) == key:
            break
        text = unfolded
    return text


def proposition_aliases_in_namespace(
    aliases: dict[str, PropositionAliasInfo] | None,
    context_namespace: str,
) -> dict[str, PropositionAliasInfo] | None:
    """Resolve proposition-alias short names in a row's lexical namespace.

    A custom proposition wrapper is exactly the kind of spelling that must not
    hide a result-level certificate package.  Keep the qualified alias map,
    but route a duplicate short name as Lean would from the current namespace
    rather than accidentally unfolding an unrelated wrapper elsewhere.
    """

    if not aliases or not context_namespace:
        return aliases
    scoped = dict(aliases)
    namespace_parts = context_namespace.split(".")
    short_names = {
        name.rsplit(".", 1)[-1]
        for name in aliases
        if "." in name
    }
    for short_name in short_names:
        for index in range(len(namespace_parts), 0, -1):
            qualified = ".".join([*namespace_parts[:index], short_name])
            if qualified in aliases:
                scoped[short_name] = aliases[qualified]
                break
    return scoped


PROPOSITION_ALIAS_EXPANSION_MAX_STEPS = 64


def strict_lexical_declaration_identity(
    reference: str,
    identities: set[str],
    *,
    context_namespace: str = "",
) -> str | None:
    """Resolve one local declaration only through an exact lexical identity.

    This intentionally differs from the broader static-navigation resolver.
    It never chooses a suffix match such as ``Other.Condition`` for a bare
    ``Condition``.  A source-record expansion changes the mathematical surface
    given to the judge, so an unelaborated namespace guess would be worse than
    retaining an explicit proof obligation.
    """

    if reference in identities:
        return reference
    namespace_parts = [part for part in context_namespace.split(".") if part]
    for index in range(len(namespace_parts), -1, -1):
        candidate = ".".join([*namespace_parts[:index], reference])
        if candidate in identities:
            return candidate
    return None


def proposition_aliases_by_identity(
    aliases: dict[str, PropositionAliasInfo] | None,
) -> dict[str, PropositionAliasInfo]:
    """Return aliases keyed only by their declared semantic identities."""

    by_identity: dict[str, PropositionAliasInfo] = {}
    for info in (aliases or {}).values():
        # The parser also exposes selected short spellings for legacy callers.
        # Expansion must use the declaration's full identity instead.
        by_identity.setdefault(info.name, info)
    return by_identity


def _proposition_alias_application(
    text: str,
    match: re.Match[str],
    info: PropositionAliasInfo,
    body: str,
) -> tuple[str, int]:
    """Instantiate one proposition alias body at a parsed application site."""

    argument_spans: list[tuple[int, int]] = []
    cursor = match.end()
    for _ in info.parameters:
        span = _next_proposition_alias_argument_span(text, cursor)
        if span is None:
            break
        argument_spans.append(span)
        cursor = span[1]
    application_args = [text[start:end] for start, end in argument_spans]
    parameter_count = len(info.parameters)
    parameter_offset = max(0, parameter_count - len(application_args))
    substitutions = {
        parameter: (
            application_args[index - parameter_offset]
            if parameter_offset <= index < parameter_offset + len(application_args)
            else f"__propArg{index}"
        )
        for index, parameter in enumerate(info.parameters)
    }
    instantiated = body
    for parameter, argument in substitutions.items():
        instantiated = re.sub(
            rf"(?<![\w']){re.escape(parameter)}(?![\w'])",
            lambda _match, replacement=argument: replacement,
            instantiated,
        )
    application_end = argument_spans[-1][1] if argument_spans else match.end()
    return instantiated, application_end


def _proposition_alias_route_block(
    raw_head: str,
    *,
    declarations_by_identity: dict[str, LocalDeclaration],
    context_namespace: str,
    shadowed_names: set[str],
) -> dict[str, Any] | None:
    """Describe a local nontransparent/ambiguous proposition route, if any.

    Suffix candidates are collected only for a fail-closed diagnostic.  They
    never select a declaration for expansion.
    """

    if "." not in raw_head and raw_head in shadowed_names:
        return None
    identities = set(declarations_by_identity)
    resolved = strict_lexical_declaration_identity(
        raw_head, identities, context_namespace=context_namespace
    )
    if resolved is not None:
        declaration = declarations_by_identity[resolved]
        result_type = declaration_result_type(declaration.source)
        is_prop_route = (
            alpha_canonical_type(result_type) == "Prop"
            or inferred_proposition_alias_body(declaration_body_text(declaration.source))
        )
        if not is_prop_route:
            return None
        if declaration.kind in {"opaque", "constant", "axiom", "theorem", "lemma"}:
            return {
                "reason": "nontransparent_local_proposition_route",
                "declaration": declaration.name,
                "kind": declaration.kind,
                "source_file": declaration.source_file,
                "line": declaration.line,
            }
        if declaration.kind in {"def", "abbrev"}:
            return {
                "reason": "uninspectable_local_proposition_alias",
                "declaration": declaration.name,
                "kind": declaration.kind,
                "source_file": declaration.source_file,
                "line": declaration.line,
            }
        return None

    # Do not route an unqualified reference through these candidates. They are
    # evidence that static expansion is ambiguous/unresolved, not a fallback.
    suffix = f".{raw_head}"
    candidates = sorted(
        name
        for name, declaration in declarations_by_identity.items()
        if (name == raw_head or name.endswith(suffix))
        and (
            alpha_canonical_type(declaration_result_type(declaration.source))
            == "Prop"
            or inferred_proposition_alias_body(declaration_body_text(declaration.source))
        )
    )
    if candidates:
        return {
            "reason": "unresolved_local_proposition_alias_identity",
            "reference": raw_head,
            "candidates": candidates,
        }
    return None


def delta_expand_transparent_proposition_aliases(
    type_text: str,
    aliases: dict[str, PropositionAliasInfo] | None,
    semantic_declarations: list[LocalDeclaration],
    *,
    context_namespace: str = "",
    shadowed_names: set[str] | None = None,
) -> PropositionAliasExpansion:
    """Delta-expand transparent paper-local proposition aliases for auditing.

    Expansion follows only a declaration's exact qualified identity or the
    lexical namespace chain of the type where it occurs.  It deliberately does
    not use a global suffix/short-name fallback.  Opaque, theorem, ambiguous,
    tactic-body, cyclic, or bounded routes remain visible as blocked audit
    obligations rather than being rewritten into a guessed formula.
    """

    aliases_by_identity = proposition_aliases_by_identity(aliases)
    declarations_by_identity = {
        declaration.name: declaration for declaration in semantic_declarations
    }
    blocked_routes: list[dict[str, Any]] = []
    blocked_keys: set[str] = set()
    steps: list[dict[str, Any]] = []
    step_count = 0

    def add_block(block: dict[str, Any]) -> None:
        key = json.dumps(block, sort_keys=True, separators=(",", ":"))
        if key not in blocked_keys:
            blocked_keys.add(key)
            blocked_routes.append(block)

    def expand(
        text: str,
        *,
        namespace: str,
        shadowed: set[str],
        alias_stack: tuple[str, ...],
    ) -> str:
        nonlocal step_count
        current = normalize_ws(text)
        while True:
            changed = False
            for match in _PROPOSITION_ALIAS_IDENTIFIER_RE.finditer(current):
                raw_head = match.group(1).lstrip("@")
                if "." not in raw_head and raw_head in shadowed:
                    continue
                identity = strict_lexical_declaration_identity(
                    raw_head,
                    set(aliases_by_identity),
                    context_namespace=namespace,
                )
                if identity is None:
                    block = _proposition_alias_route_block(
                        raw_head,
                        declarations_by_identity=declarations_by_identity,
                        context_namespace=namespace,
                        shadowed_names=shadowed,
                    )
                    if block is not None:
                        add_block(block)
                    continue
                if identity in alias_stack:
                    add_block(
                        {
                            "reason": "transparent_proposition_alias_cycle",
                            "declaration": identity,
                            "dependency_chain": [*alias_stack, identity],
                        }
                    )
                    continue
                if step_count >= PROPOSITION_ALIAS_EXPANSION_MAX_STEPS:
                    add_block(
                        {
                            "reason": "transparent_proposition_alias_expansion_limit",
                            "max_steps": PROPOSITION_ALIAS_EXPANSION_MAX_STEPS,
                            "declaration": identity,
                        }
                    )
                    continue

                info = aliases_by_identity[identity]
                declaration = declarations_by_identity.get(identity)
                body_namespace = (
                    identity.rsplit(".", 1)[0] if "." in identity else ""
                )
                expanded_body = expand(
                    info.body,
                    namespace=body_namespace,
                    shadowed=set(info.parameters),
                    alias_stack=(*alias_stack, identity),
                )
                instantiated, application_end = _proposition_alias_application(
                    current, match, info, expanded_body
                )
                step_count += 1
                steps.append(
                    {
                        "declaration": identity,
                        "kind": declaration.kind if declaration is not None else "def_or_abbrev",
                        **(
                            {
                                "source_file": declaration.source_file,
                                "line": declaration.line,
                            }
                            if declaration is not None
                            else {}
                        ),
                    }
                )
                current = normalize_ws(
                    current[: match.start()] + f"({instantiated})" + current[application_end:]
                )
                changed = True
                break
            if not changed:
                return current

    expanded = strip_outer_group(
        expand(
            type_text,
            namespace=context_namespace,
            shadowed=set(shadowed_names or set()),
            alias_stack=(),
        )
    )
    return PropositionAliasExpansion(
        expanded_type=expanded,
        steps=steps,
        blocked_routes=blocked_routes,
    )


def proposition_alias_expansion_payload(
    expansion: PropositionAliasExpansion,
) -> dict[str, Any]:
    """Return stable audit metadata only when expansion discovered a route."""

    if not expansion.steps and not expansion.blocked_routes:
        return {}
    return {
        "proposition_alias_expansion": {
            "expanded_type": expansion.expanded_type,
            "transparent_steps": expansion.steps,
            "blocked_routes": expansion.blocked_routes,
        }
    }


def _unfold_type_alias_once(
    type_text: str,
    aliases: dict[str, TypeAliasInfo],
) -> str:
    """Unfold one transparent type-level alias application anywhere in a type.

    This deliberately mirrors proposition-alias expansion.  A local alias such
    as ``def Pebble (n : Nat) : Type := PMF (Fin n)`` must not hide the PMF
    carrier from the semantic-model lane merely because the alias has a neutral
    name.
    """

    text = normalize_ws(type_text)
    for match in _PROPOSITION_ALIAS_IDENTIFIER_RE.finditer(text):
        raw_head = match.group(1).lstrip("@")
        info = aliases.get(raw_head) or aliases.get(raw_head.rsplit(".", 1)[-1])
        if info is None:
            continue

        argument_spans: list[tuple[int, int]] = []
        cursor = match.end()
        for _ in info.parameters:
            span = _next_proposition_alias_argument_span(text, cursor)
            if span is None:
                break
            argument_spans.append(span)
            cursor = span[1]
        application_args = [text[start:end] for start, end in argument_spans]
        parameter_count = len(info.parameters)
        parameter_offset = max(0, parameter_count - len(application_args))
        substitutions = {
            parameter: (
                application_args[index - parameter_offset]
                if parameter_offset <= index < parameter_offset + len(application_args)
                else f"__typeAliasArg{index}"
            )
            for index, parameter in enumerate(info.parameters)
        }
        body = info.body
        for parameter, argument in substitutions.items():
            body = re.sub(
                rf"(?<![\w']){re.escape(parameter)}(?![\w'])",
                lambda _match, replacement=argument: replacement,
                body,
            )
        application_end = argument_spans[-1][1] if argument_spans else match.end()
        return normalize_ws(
            text[: match.start()] + f"({body})" + text[application_end:]
        )
    return text


def unfold_semantic_type_aliases(
    type_text: str,
    aliases: dict[str, TypeAliasInfo] | None,
) -> str:
    """Unfold nested transparent type aliases for semantic-model inspection."""

    text = normalize_ws(type_text)
    if not aliases:
        return text
    seen: set[str] = set()
    for _ in range(64):
        key = canonical_type(text)
        if key in seen:
            break
        seen.add(key)
        unfolded = _unfold_type_alias_once(text, aliases)
        if canonical_type(unfolded) == key:
            break
        text = unfolded
    return text


def semantic_type_aliases_in_namespace(
    aliases: dict[str, TypeAliasInfo] | None,
    context_namespace: str,
) -> dict[str, TypeAliasInfo] | None:
    """Resolve ambiguous short alias names according to the local namespace.

    The parser retains only an unqualified spelling when it is globally
    unambiguous.  Within a row or record field, Lean resolves a duplicate short
    spelling through the active namespace.  Recreate that routing here so
    placing an otherwise identical wrapper in two namespaces cannot make the
    semantic review silently lose its probability/rate surface.
    """

    if not aliases or not context_namespace:
        return aliases
    scoped = dict(aliases)
    namespace_parts = context_namespace.split(".")
    short_names = {
        name.rsplit(".", 1)[-1]
        for name in aliases
        if "." in name
    }
    for short_name in short_names:
        for index in range(len(namespace_parts), 0, -1):
            qualified = ".".join([*namespace_parts[:index], short_name])
            if qualified in aliases:
                scoped[short_name] = aliases[qualified]
                break
    return scoped


def canonical_type(type_text: str) -> str:
    """Normalize enough Lean surface syntax for conservative equality checks."""

    text = normalize_logic_syntax(type_text)
    text = re.sub(r"\s*([(){}\[\],:.])\s*", r"\1", text)
    text = re.sub(r"\s*(→|↔|∧|∨|=|≠|≤|≥|<|>)\s*", r"\1", text)
    while text.startswith("(") and text.endswith(")"):
        text = text[1:-1].strip()
    return text


def normalize_logic_syntax(type_text: str) -> str:
    """Normalize equivalent ASCII and Unicode Lean proposition syntax."""

    text = normalize_ws(type_text)
    for source, target in (
        ("<->", "↔"),
        ("->", "→"),
        ("/\\", "∧"),
        ("\\/", "∨"),
        ("<=", "≤"),
        (">=", "≥"),
        ("!=", "≠"),
    ):
        text = text.replace(source, target)
    text = re.sub(r"(?<![\w'])forall(?![\w'])", "∀", text)
    text = re.sub(r"(?<![\w'])exists(?![\w'])", "∃", text)
    return text


LEAN_IDENTIFIER_RE = re.compile(r"(?<![\w'])([^\W\d][\w']*)(?![\w'])", re.UNICODE)
# Lean permits Unicode identifier heads (for example the conventional finite
# carrier ``κ``).  Keep the head grammar shared with the data-carrier check so
# a carrier proven data by ``κ : Type*`` is not later misclassified merely
# because it appears in a result-level quantifier.
LEAN_IDENTIFIER_SEGMENT_PATTERN = r"[^\W\d][\w']*"
LEAN_TYPE_HEAD_RE = re.compile(
    rf"@?((?:{LEAN_IDENTIFIER_SEGMENT_PATTERN}\.)*"
    rf"{LEAN_IDENTIFIER_SEGMENT_PATTERN}|[ℕℤℚℝ])(?![\w'])",
    re.UNICODE,
)


def _binder_identifiers(text: str) -> list[str]:
    """Return identifier tokens from the name side of a Lean binder."""

    split = split_top_level_colon(text.strip().strip("(){}[]"))
    names = split[0] if split is not None else text
    return [
        match.group(1)
        for match in LEAN_IDENTIFIER_RE.finditer(names)
        if match.group(1) not in {"_", "inst"}
    ]


def quantified_binder_names(type_text: str) -> list[str]:
    """Collect bound names so proposition comparison is alpha-invariant.

    This is intentionally a surface parser, but it handles the forms used in
    theorem and structure fields: `forall x : T, ...`, `exists x, ...`, and
    dependent `(x : T) -> ...` binders.  Names are used only to erase alpha
    variation; predicate and function constants remain unchanged.
    """

    text = normalize_logic_syntax(type_text)
    names: list[str] = []
    index = 0
    while index < len(text):
        if text[index] not in {"∀", "∃"}:
            index += 1
            continue
        cursor = index + 1
        depth = 0
        while cursor < len(text):
            char = text[cursor]
            if char in "([{⦃":
                depth += 1
            elif char in ")]}⦄" and depth > 0:
                depth -= 1
            elif char == "," and depth == 0:
                break
            cursor += 1
        segment = text[index + 1 : cursor].strip()
        direct_split = split_top_level_colon(segment)
        spans = balanced_binder_spans(segment)
        if direct_split is not None and not segment.startswith(("(", "{", "[")):
            names.extend(_binder_identifiers(segment))
        elif spans:
            for span in spans:
                names.extend(_binder_identifiers(span))
        else:
            names.extend(_binder_identifiers(segment))
        index = cursor + 1

    # Dependent arrow binders are normally shallow in audited field types.
    for match in re.finditer(r"\(([^()]*)\)\s*(?:→|->)", text):
        names.extend(_binder_identifiers(match.group(1)))
    return list(dict.fromkeys(names))


def alpha_canonical_type(type_text: str) -> str:
    """Canonicalize proposition syntax modulo bound-variable renaming."""

    text = normalize_logic_syntax(type_text)
    for index, name in enumerate(quantified_binder_names(text)):
        text = re.sub(
            rf"(?<![\w']){re.escape(name)}(?![\w'])",
            f"_b{index}",
            text,
        )
    return canonical_type(text)


def abstract_free_identifiers(type_text: str, names: set[str]) -> str:
    """Erase declaration-binder spelling while preserving constant heads."""

    text = normalize_ws(type_text)
    ordered = sorted(
        (
            (text.find(name), name)
            for name in names
            if re.search(rf"(?<![\w']){re.escape(name)}(?![\w'])", text)
        ),
        key=lambda item: (item[0], item[1]),
    )
    for index, (_, name) in enumerate(ordered):
        text = re.sub(
            rf"(?<![\w']){re.escape(name)}(?![\w'])",
            f"_f{index}",
            text,
        )
    return alpha_canonical_type(text)


def structural_type_sha256(type_text: str, free_identifiers: set[str] | None = None) -> str:
    """Hash a binder-name-independent generated type surface.

    This is an obligation identity, not a pretty-print checksum.  It erases
    only declared/free binder spellings supplied by the surrounding generated
    context; constant heads and the full logical shape remain part of the
    digest.  Lean proposition-sort receipts independently establish whether
    that surface is proof-valued.
    """

    normalized = abstract_free_identifiers(type_text, free_identifiers or set())
    return hashlib.sha256(normalized.encode("utf-8")).hexdigest() if normalized else ""


def type_carries_conclusion(
    input_type: str,
    conclusion_type: str,
    proposition_aliases: dict[str, PropositionAliasInfo] | None = None,
) -> bool:
    """Whether an input is the conclusion itself or a provider of it."""

    input_key = alpha_canonical_type(
        unfold_proposition_aliases(input_type, proposition_aliases)
    )
    conclusion_key = alpha_canonical_type(
        unfold_proposition_aliases(conclusion_type, proposition_aliases)
    )
    if not input_key or not conclusion_key:
        return False
    if input_key == conclusion_key:
        return True
    if any(token in input_key for token in ("→", "->", "∀")):
        if conclusion_key in input_key:
            return True
    if any(token in input_key for token in ("∧", "∨", "↔", "∃")) or re.search(
        r"\b(?:And|Or|Iff|Exists)\b", input_key
    ):
        return conclusion_key in input_key
    return False


def is_logical_result_type(type_text: str) -> bool:
    """Recognize a proposition at the outer result, not inside data arguments."""

    text = normalize_ws(type_text).strip()
    if not text:
        return False
    # These Lean carrier notations contain a comparison glyph as part of the
    # printed type name. Mask them before scanning for logical relations, while
    # retaining ordinary formulas such as `x ≥ 0` unchanged.
    for atom in sorted(KNOWN_DATA_TYPE_ATOMS, key=len, reverse=True):
        text = text.replace(atom, "CarrierType")
    if text.startswith(("∀", "∃")):
        return True

    depth = 0
    last_arrow: int | None = None
    index = 0
    while index < len(text):
        char = text[index]
        if char in "([{⦃":
            depth += 1
            index += 1
            continue
        if char in ")]}⦄" and depth > 0:
            depth -= 1
            index += 1
            continue
        if depth == 0 and text.startswith("→", index):
            last_arrow = index + 1
        elif depth == 0 and text.startswith("->", index):
            last_arrow = index + 2
            index += 1
        index += 1
    if last_arrow is not None:
        return is_logical_result_type(text[last_arrow:])

    depth = 0
    for index, char in enumerate(text):
        if char in "([{⦃":
            depth += 1
        elif char in ")]}⦄" and depth > 0:
            depth -= 1
        elif depth == 0 and char in "↔∧∨=≠≤≥<>∈∉⊆⊂⊇⊃":
            return True
    return bool(re.search(r"\b(?:Prop|True|False|And|Or|Iff|Exists)\b", text))


def local_declaration_short_name_counts(
    declarations: list[LocalDeclaration],
) -> dict[str, int]:
    """Count local declaration tails so ambiguous type heads fail closed.

    Lean accepts the same tail in distinct namespaces.  A static classifier that
    flattens both ``Alpha.Token`` and ``Beta.Token`` to ``Token`` can quietly
    turn a proposition into carrier data (or the converse).  Count every local
    declaration rather than guessing which same-spelled value might be used as
    a type; losing a shortcut is preferable to suppressing an obligation.
    """

    counts: dict[str, int] = {}
    for declaration in declarations:
        short_name = declaration.name.rsplit(".", 1)[-1]
        counts[short_name] = counts.get(short_name, 0) + 1
    return counts


def proposition_type_heads(declarations: list[LocalDeclaration]) -> set[str]:
    """Return qualified Prop heads plus globally unambiguous short forms."""

    heads: set[str] = set()
    short_name_counts = local_declaration_short_name_counts(declarations)
    for declaration in declarations:
        if declaration.kind in {"theorem", "lemma", "structure", "class"}:
            continue
        result = declaration_result_type(declaration.source)
        if alpha_canonical_type(result) == "Prop":
            heads.add(declaration.name)
            short_name = declaration.name.rsplit(".", 1)[-1]
            if short_name_counts[short_name] == 1:
                heads.add(short_name)
    return heads


def proposition_wrapper_structure_names(
    declarations: list[LocalDeclaration],
) -> set[str]:
    """Return local Prop-valued records/inductives that can wrap a witness.

    This is intentionally separate from `proposition_type_heads`: the latter
    classifies proof *fields*, whereas this identifies a proposition whose
    constructor can hide a Type-valued record.  The result sort and constructor
    fields decide it; declaration names do not.
    """

    return {
        declaration.name
        for declaration in declarations
        if declaration.kind in {"structure", "class", "inductive"}
        and alpha_canonical_type(declaration_result_type(declaration.source)) == "Prop"
    }


KNOWN_DATA_TYPE_HEADS = {
    "Any",
    "Bool",
    "ByteArray",
    "Char",
    "Fin",
    "Finset",
    "Fintype",
    "Float",
    "Int",
    "Kernel",
    "List",
    "Measure",
    "Multiset",
    "Nat",
    "Option",
    "PMF",
    "Perm",
    "Prod",
    "Rat",
    "Real",
    "RCVBallot",
    "Set",
    "String",
    "Subtype",
    "Sum",
    "Sort",
    "Type",
    "Unit",
    "ENNReal",
    "Equiv.Perm",
    "ℕ",
    "ℤ",
    "ℚ",
    "ℝ",
}

# Keep namespace-qualified library carriers explicit. Treating arbitrary
# `Namespace.Perm`-style suffixes as data would recreate the collision bug that
# the qualified head resolver prevents.
KNOWN_QUALIFIED_DATA_TYPE_HEADS = {"Equiv.Perm"}

KNOWN_DATA_TYPE_ATOMS = {
    # Lean prints NNReal with this notation. The comparison glyph is part of
    # the carrier name, not a proposition connective.
    "ℝ≥0",
    # Lean pretty-prints ENNReal as this notation; the glyph is part of the
    # type name, not an inequality proposition.
    "ℝ≥0∞",
}


def data_type_heads(declarations: list[LocalDeclaration]) -> set[str]:
    """Infer repository-local carrier heads without relying on name suffixes."""

    heads = set(KNOWN_DATA_TYPE_HEADS) | set(KNOWN_QUALIFIED_DATA_TYPE_HEADS)
    short_name_counts = local_declaration_short_name_counts(declarations)
    # A local declaration can shadow a builtin head within its namespace.  With
    # no elaborator/context at this call site, retain neither interpretation by
    # bare name; qualified occurrences below remain classifiable.
    for short_name in short_name_counts:
        heads.discard(short_name)

    def add_data_head(name: str) -> None:
        heads.add(name)
        short_name = name.rsplit(".", 1)[-1]
        if short_name_counts.get(short_name, 0) == 1:
            heads.add(short_name)

    for declaration in declarations:
        result = alpha_canonical_type(declaration_result_type(declaration.source))
        if result == "Prop":
            continue
        if declaration.kind in {"structure", "class", "inductive"}:
            add_data_head(declaration.name)
        elif re.match(r"^(?:Type|Sort)(?:\b|[0-9_ ])", result):
            add_data_head(declaration.name)

    # Resolve simple inferred aliases such as `def TripPolicy := Set TripLength`.
    changed = True
    by_name = {declaration.name: declaration for declaration in declarations}
    while changed:
        changed = False
        for name, declaration in by_name.items():
            if (
                name in heads
                or declaration.kind not in {"def", "abbrev"}
            ):
                continue
            body = strip_outer_group(declaration_body_text(declaration.source))
            if is_definitely_data_type(body, data_heads=heads):
                add_data_head(name)
                changed = True
                continue
            match = re.match(
                r"@?((?:[A-Za-z_][A-Za-z0-9_']*\.)*[A-Za-z_][A-Za-z0-9_']*|[ℕℤℚℝ])(?![A-Za-z0-9_'])",
                body,
            )
            if match is not None and match.group(1) in heads:
                add_data_head(name)
                changed = True
    return heads


def declaration_returns_sort(declaration: LocalDeclaration) -> bool:
    """Whether a local declaration explicitly declares a type-valued result."""

    result = strip_outer_group(
        alpha_canonical_type(declaration_result_type(declaration.source))
    )
    return bool(re.match(r"^(?:Type|Sort)(?:\b|\s|\*|[0-9_(])", result))


def parse_semantic_type_aliases(
    declarations: list[LocalDeclaration],
) -> dict[str, TypeAliasInfo]:
    """Return transparent local aliases whose body is a carrier/type expression.

    The recursive source-record audit already follows aliases to parsed
    structures.  The semantic-model lane also needs plain aliases such as
    ``PMF (Fin n)`` and ``WithTop Real``: otherwise a wrapper can erase every
    probability or extended-rate signal before the source comparison is
    generated.  Only unambiguous short names are added; qualified names always
    remain available, so namespace collisions fail closed rather than choosing
    an arbitrary declaration.
    """

    aliases: dict[str, TypeAliasInfo] = {}
    aliases_by_short_name: dict[str, set[str]] = {}
    short_name_counts = local_declaration_short_name_counts(declarations)
    known_data_heads = data_type_heads(declarations)

    def parameters(declaration: LocalDeclaration) -> list[str]:
        return [
            name
            for visible_input in visible_inputs_from_declaration(
                declaration.source
            )
            for name in binder_names(visible_input.get("names", ""))
        ]

    def add_alias(declaration: LocalDeclaration) -> None:
        body = declaration_body_text(declaration.source)
        if not body:
            return
        aliases[declaration.name] = TypeAliasInfo(
            name=declaration.name,
            parameters=parameters(declaration),
            body=body,
        )
        aliases_by_short_name.setdefault(
            declaration.name.rsplit(".", 1)[-1], set()
        ).add(declaration.name)

    candidates = [
        declaration
        for declaration in declarations
        if declaration.kind in {"def", "abbrev"}
        and declaration_body_text(declaration.source)
        and alpha_canonical_type(declaration_result_type(declaration.source))
        != "Prop"
    ]
    pending: list[LocalDeclaration] = []
    for declaration in candidates:
        if declaration_returns_sort(declaration):
            add_alias(declaration)
        else:
            pending.append(declaration)

    # Inferred aliases omit `: Type`; admit only chains whose body is already
    # recognizably carrier-valued.  This preserves the existing fail-closed
    # treatment of ordinary value definitions.
    while pending:
        next_pending: list[LocalDeclaration] = []
        changed = False
        expanded_data_heads = known_data_heads | set(aliases)
        for declaration in pending:
            body = declaration_body_text(declaration.source)
            if is_definitely_data_type(body, data_heads=expanded_data_heads):
                add_alias(declaration)
                changed = True
            else:
                next_pending.append(declaration)
        if not changed:
            break
        pending = next_pending

    for short_name, qualified_names in aliases_by_short_name.items():
        if len(qualified_names) == 1 and short_name_counts[short_name] == 1:
            qualified_name = next(iter(qualified_names))
            aliases[short_name] = aliases[qualified_name]
    return aliases


def structure_parameter_data_heads(
    structure: StructureInfo | None,
) -> set[str]:
    """Return Type/Sort-valued structure parameters and their audit placeholders.

    Recursive field instantiation uses ``__argN`` placeholders when implicit
    structure parameters are not written in a binder type. Those placeholders
    should be data only when the corresponding structure parameter is a carrier
    kind such as ``Type`` or ``Sort``. Proposition-valued parameters remain
    fail-closed.
    """

    if structure is None:
        return set()
    heads: set[str] = set()
    for index, parameter in enumerate(structure.parameters):
        parameter_type = alpha_canonical_type(
            structure.parameter_types.get(parameter, "")
        )
        if re.match(r"^(?:Type|Sort)(?:\b|\s|\*|[0-9_(])", parameter_type):
            heads.add(parameter)
            heads.add(f"__arg{index}")
    return heads


def field_data_heads(
    field: FieldInfo,
    structures: dict[str, StructureInfo],
    base_heads: set[str] | None = None,
) -> set[str]:
    """Data heads available when classifying one parsed record field."""

    heads = set(base_heads or set())
    heads.update(structure_parameter_data_heads(structures.get(field.structure)))
    return heads


def is_known_data_terminal_type(
    type_text: str,
    data_heads: set[str] | None = None,
) -> bool:
    """Recognize an already-resolved carrier terminal without proof heuristics.

    This is intentionally narrower than ``is_definitely_data_type``: callers
    use it while deciding whether a quantified or function type is a proof.
    Looking only at the terminal carrier avoids mistaking the ``≥`` glyph in
    ``ℝ≥0`` or a Pi binder for logical syntax, while leaving unknown terminals
    fail-closed for the ordinary proposition classifier.
    """

    _inputs, terminal = result_type_inputs(type_text)
    candidate = strip_outer_group(normalize_ws(terminal or type_text)).strip()
    if candidate in KNOWN_DATA_TYPE_ATOMS:
        return True
    if is_logical_result_type(candidate):
        return False
    head_match = LEAN_TYPE_HEAD_RE.match(candidate.lstrip("({["))
    if head_match is None:
        return False
    heads = data_heads or KNOWN_DATA_TYPE_HEADS
    return head_match.group(1) in heads


def is_proposition_type(
    type_text: str,
    proposition_heads: set[str] | None = None,
    data_heads: set[str] | None = None,
) -> bool:
    """Recognize proposition-valued fields from syntax and declared codomains."""

    text = normalize_ws(type_text).strip()
    if strip_outer_group(text) in KNOWN_DATA_TYPE_ATOMS:
        return False
    inputs, terminal = result_type_inputs(text)
    if (
        terminal
        and alpha_canonical_type(terminal) != alpha_canonical_type(text)
        and is_known_data_terminal_type(terminal, data_heads)
    ):
        return False
    if inputs and terminal and alpha_canonical_type(terminal) != alpha_canonical_type(text):
        return is_proposition_type(terminal, proposition_heads, data_heads)
    if is_logical_result_type(type_text):
        return True
    head_text = text.lstrip("({[")
    head_match = re.match(
        r"@?((?:[A-Za-z_][A-Za-z0-9_']*\.)*[A-Za-z_][A-Za-z0-9_']*)\b",
        head_text,
    )
    if head_match is None:
        return False
    head = head_match.group(1)
    heads = proposition_heads or set()
    # Qualified references must retain their full semantic identity.  A short
    # fallback is safe only for an unqualified source occurrence, because the
    # head set contains short forms only when they were globally unique.
    return head in heads


def terminal_arrow_result(type_text: str) -> str:
    """Return the outermost function codomain from a Lean type."""

    text = normalize_ws(type_text).strip()
    depth = 0
    last_arrow: int | None = None
    index = 0
    while index < len(text):
        char = text[index]
        if char in "([{⦃":
            depth += 1
        elif char in ")]}⦄" and depth > 0:
            depth -= 1
        elif depth == 0 and text.startswith("→", index):
            last_arrow = index + 1
        elif depth == 0 and text.startswith("->", index):
            last_arrow = index + 2
            index += 1
        index += 1
    return text[last_arrow:].strip() if last_arrow is not None else text



def is_definitely_data_type(
    type_text: str,
    *,
    proposition_heads: set[str] | None = None,
    data_heads: set[str] | None = None,
) -> bool:
    """Recognize carrier/data types conservatively; unknown heads fail closed."""

    _inputs, pi_terminal = result_type_inputs(type_text)
    if pi_terminal and alpha_canonical_type(pi_terminal) != alpha_canonical_type(type_text):
        return is_definitely_data_type(
            pi_terminal,
            proposition_heads=proposition_heads,
            data_heads=data_heads,
        )

    terminal_result = strip_outer_group(terminal_arrow_result(type_text)).strip()
    if alpha_canonical_type(terminal_result) == "Prop":
        # `p : Prop` or `predicate : X → Prop` carries a formula/predicate as
        # data. It is not a proof of that formula. Concrete proposition fields
        # such as `h : ∀ x, P x` or `h : Convex X` remain proof-bearing below.
        return True
    if is_proposition_type(type_text, proposition_heads, data_heads):
        return False
    return is_known_data_terminal_type(terminal_result, data_heads)


def subtype_brace_components(body: str) -> tuple[str, str, str] | None:
    """Return ``(binder, carrier, predicate)`` for a brace subtype surface.

    This deliberately parses the structural subtype notation rather than a
    declaration or helper name.  A malformed binder is left unparsed so the
    caller can retain a fail-closed subtype obligation instead of inventing a
    carrier/predicate split.
    """

    text = strip_outer_group(normalize_ws(body)).strip()
    if not (text.startswith("{") and text.endswith("}")):
        return None
    inner = text[1:-1].strip()
    depth = 0
    index = 0
    while index < len(inner):
        char = inner[index]
        if char in "([{⦃":
            depth += 1
            index += 1
            continue
        if char in ")]}⦄" and depth > 0:
            depth -= 1
            index += 1
            continue
        if depth == 0 and inner.startswith("//", index):
            binder_split = split_top_level_colon(inner[:index])
            if binder_split is None:
                return None
            raw_names, carrier = binder_split
            names = binder_names(raw_names)
            predicate = normalize_ws(inner[index + 2 :]).strip()
            if len(names) != 1 or not carrier or not predicate:
                return None
            return names[0], normalize_ws(carrier), predicate
        index += 1
    return None


def is_structural_subtype_surface(type_text: str) -> bool:
    """Whether a type is written as a direct brace/core `Subtype` surface."""

    text = strip_outer_group(normalize_ws(type_text)).strip()
    if text.startswith("{") and text.endswith("}"):
        inner = text[1:-1]
        depth = 0
        for index, char in enumerate(inner):
            if char in "([{⦃":
                depth += 1
            elif char in ")]}⦄" and depth > 0:
                depth -= 1
            elif depth == 0 and inner.startswith("//", index):
                return True
    return bool(re.match(r"^@?Subtype(?:\b|\s|\()", text))


def subtype_hidden_property(body: str) -> str | None:
    """Extract the proof predicate from a simple Lean subtype carrier body."""

    components = subtype_brace_components(body)
    return components[2] if components is not None else None


def proposition_type_relation(
    source_type: str,
    target_type: str,
    proposition_aliases: dict[str, PropositionAliasInfo] | None = None,
) -> str:
    """Return a name-invariant logical relationship between propositions."""

    source_key = alpha_canonical_type(
        unfold_proposition_aliases(source_type, proposition_aliases)
    )
    target_key = alpha_canonical_type(
        unfold_proposition_aliases(target_type, proposition_aliases)
    )
    if not source_key or not target_key:
        return ""
    if source_key == target_key:
        return "equivalent"
    if type_carries_conclusion(source_type, target_type, proposition_aliases):
        return "provides_target"
    if type_carries_conclusion(target_type, source_type, proposition_aliases):
        return "component_of_target"
    return ""


def paper_import_file(root: Path, module: str) -> Path | None:
    parts = [part for part in module.split(".") if part]
    if len(parts) < 2:
        return None
    paper_dir = root / "papers" / parts[0]
    if not paper_dir.exists():
        return None
    path = paper_dir.joinpath(*parts[1:]).with_suffix(".lean")
    if path.exists():
        return path
    return None


def repository_import_file(root: Path, module: str) -> Path | None:
    """Resolve one exact current repository module for diagnostics only.

    Lean's authenticated loaded-module record, not this text resolver, owns the
    declaration universe credited by the audit.  Keeping the current library
    root in one constant prevents a project rename from leaving independent
    parser rules behind.
    """

    if module == REPOSITORY_LIBRARY_MODULE_ROOT:
        candidate = root / REPOSITORY_LIBRARY_ROOT_FILE
        return candidate if candidate.is_file() else None
    if module.startswith(f"{REPOSITORY_LIBRARY_MODULE_ROOT}."):
        candidate = root.joinpath(*module.split(".")).with_suffix(".lean")
        return candidate if candidate.is_file() else None
    imported = paper_import_file(root, module)
    if imported is not None:
        return imported
    aggregator = root / "papers" / f"{module}.lean"
    return aggregator if aggregator.is_file() else None


def repository_import_is_expected(root: Path, module: str) -> bool:
    """Whether an unresolved module spelling denotes this repository."""

    head = module.split(".", 1)[0]
    return bool(
        head == REPOSITORY_LIBRARY_MODULE_ROOT
        or (root / "papers" / head).exists()
        or (root / "papers" / f"{head}.lean").exists()
    )


def diagnostic_imported_paper_lean_files(
    root: Path, seed_files: list[Path]
) -> list[Path]:
    """Approximate repository imports for diagnostics only.

    This text parser can explain a likely missing or malformed import, but it
    never selects the credited source-record declaration universe. Lean's
    loaded-module record owns that decision; in particular, valid command
    layouts that this line-oriented parser does not recognize cannot remove a
    dependency from an audit.
    """

    out: list[Path] = []
    seen: set[Path] = set()
    queue = list(seed_files)
    while queue:
        path = queue.pop(0).resolve()
        if path in seen or not path.exists():
            continue
        seen.add(path)
        for line in mask_lean_comments(read_text(path)).splitlines():
            match = IMPORT_RE.match(line)
            if not match:
                continue
            raw_modules = match.group(1).split()
            if not raw_modules or any(
                not LEAN_IMPORT_MODULE_RE.fullmatch(module)
                for module in raw_modules
            ):
                raise ValueError(f"malformed Lean import command in {path}: {line.strip()}")
            for module in raw_modules:
                imported = repository_import_file(root, module)
                if imported is None:
                    if repository_import_is_expected(root, module):
                        raise ValueError(
                            f"unresolved repository Lean import `{module}` in {path}"
                        )
                    continue
                imported = imported.resolve()
                if imported not in seen:
                    out.append(imported)
                    queue.append(imported)
    return out


def source_record_lean_import_closure_from_record(
    root: Path,
    interface_path: Path,
    record: object,
    *,
    authenticated_source_bytes: Mapping[str, bytes] | None = None,
) -> SourceRecordLeanImportClosure:
    """Validate a closure's schema/source bytes and map repository sources.

    The issuing/reusing ``WorktreeImportClosureProvider`` separately owns Lake
    routing, external artifact, candidate-inventory, and final mutation checks.
    This projection is safe for downstream indexing, not independent authority.
    """

    root = root.resolve()
    interface_path = interface_path.resolve()
    try:
        entrypoint = interface_path.relative_to(root).as_posix()
    except ValueError as exc:
        raise ValueError("review interface escapes the repository root") from exc
    validated = validated_lean_import_closure_payload(record)
    if validated["entrypoint"] != entrypoint:
        raise ValueError(
            "Lean import-closure receipt belongs to a different review interface"
        )

    source_bytes: list[tuple[Path, bytes]] = []
    for raw_source in validated["sources"]:
        assert isinstance(raw_source, Mapping)
        relative = str(raw_source["path"])
        candidate = (root / relative).resolve()
        try:
            candidate.relative_to(root)
        except ValueError as exc:
            raise ValueError(
                f"Lean import-closure source escapes the repository: {relative}"
            ) from exc
        if authenticated_source_bytes is None:
            try:
                content = candidate.read_bytes()
            except OSError as exc:
                raise ValueError(
                    f"Lean import-closure source is unavailable: {relative}: {exc}"
                ) from exc
        else:
            content = authenticated_source_bytes.get(relative)
            if content is None:
                raise ValueError(
                    "provider source snapshot omits Lean import-closure source: "
                    + relative
                )
        if (
            len(content) != raw_source["byte_length"]
            or hashlib.sha256(content).hexdigest() != raw_source["sha256"]
        ):
            raise SourceRecordLeanImportClosureStaleError(
                f"Lean import-closure source bytes changed: {relative}"
            )
        source_bytes.append((candidate, content))
    sources = [path for path, _content in source_bytes]
    if interface_path not in sources:
        raise ValueError("Lean import-closure omits the configured review interface")
    if len(sources) != len(set(sources)):
        raise ValueError("Lean import-closure maps multiple modules to one source")
    return SourceRecordLeanImportClosure(
        record=validated,
        repository_sources=tuple(sorted(sources)),
        sha256=lean_import_closure_payload_sha256(validated),
        repository_source_bytes=tuple(sorted(source_bytes, key=lambda item: item[0])),
    )


def source_record_lean_import_closure_source_bytes(
    lean_import_closure: SourceRecordLeanImportClosure,
) -> dict[Path, bytes]:
    """Return the run-local exact-byte snapshot keyed by resolved source path."""

    sources = {
        path.resolve(): content
        for path, content in lean_import_closure.repository_source_bytes
    }
    expected = {path.resolve() for path in lean_import_closure.repository_sources}
    if sources.keys() != expected:
        raise ValueError("Lean import-closure exact-byte snapshot is incomplete")
    return sources


def source_record_lean_import_closure_source_text(
    lean_import_closure: SourceRecordLeanImportClosure,
) -> dict[Path, str]:
    """Decode each authenticated Lean source once for all run-local parsers."""

    try:
        return {
            path: content.decode("utf-8")
            for path, content in source_record_lean_import_closure_source_bytes(
                lean_import_closure
            ).items()
        }
    except UnicodeDecodeError as exc:
        raise ValueError("Lean import-closure source is not valid UTF-8") from exc


def source_record_lean_source_artifact_identity(
    root: Path,
    path: Path,
    lean_import_closure: SourceRecordLeanImportClosure,
) -> dict[str, str]:
    """Hash one closure-owned source from the acquisition snapshot."""

    try:
        relative = path.resolve().relative_to(root.resolve()).as_posix()
    except ValueError:
        return source_artifact_identity(root, path)
    for raw in lean_import_closure.record.get("sources", []):
        if isinstance(raw, Mapping) and raw.get("path") == relative:
            return {"path": relative, "sha256": str(raw["sha256"])}
    return source_artifact_identity(root, path)


def acquire_source_record_lean_import_closure(
    root: Path,
    interface_path: Path,
    *,
    provider: WorktreeImportClosureProvider,
    saved_closure: object | None = None,
    allow_live_lean_graph: bool,
) -> tuple[SourceRecordLeanImportClosure | None, str]:
    """Reuse a validated Lean closure, or ask Lean once on a fresh-scan path."""

    root = root.resolve()
    if provider.root != root:
        return None, "Lean import-closure provider belongs to a different repository"
    try:
        entrypoint = interface_path.resolve().relative_to(root).as_posix()
    except ValueError:
        return None, "review interface escapes the repository root"

    if saved_closure is not None:
        _digest, problem = provider.identity_from_saved_closure(
            entrypoint, saved_closure
        )
        if problem is None:
            try:
                return (
                    source_record_lean_import_closure_from_record(
                        root,
                        interface_path,
                        saved_closure,
                        authenticated_source_bytes=(
                            provider.repository_source_bytes_for_closure(saved_closure)
                        ),
                    ),
                    "",
                )
            except ValueError as exc:
                if not allow_live_lean_graph:
                    return None, str(exc)
        elif not allow_live_lean_graph:
            return None, problem.format()

    if not allow_live_lean_graph:
        return None, "saved raw audit has no current Lean import-closure receipt"
    record, problem = provider.record_for_entrypoint(entrypoint)
    if problem is not None:
        return None, problem.format()
    assert record is not None
    try:
        return (
            source_record_lean_import_closure_from_record(
                root,
                interface_path,
                record,
                authenticated_source_bytes=(
                    provider.repository_source_bytes_for_closure(record)
                ),
            ),
            "",
        )
    except ValueError as exc:
        return None, str(exc)


def source_record_lean_import_closure_finalization_error(
    provider: WorktreeImportClosureProvider,
) -> str:
    """Return the exact provider-owned end-of-transaction mutation error."""

    problems = provider.finalization_problems()
    return "; ".join(problem.format() for problem in problems)


def paper_interface_import_closure_lean_files(
    root: Path,
    interface_path: Path,
    *,
    lean_import_closure: SourceRecordLeanImportClosure,
) -> list[Path]:
    """Return the Lean-authored repository-source closure of a review interface.

    Recursive-field route reachability is about declarations available to the
    configured ``PaperInterface`` module, not every experimental, scratch, or
    alternate module stored beside it. The supplied record was emitted from
    Lean's loaded environment and byte-validated before this projection; this
    helper does not parse source-text imports or expand by declaration name.
    """

    root = root.resolve()
    interface_path = interface_path.resolve()
    if (
        lean_import_closure_payload_sha256(lean_import_closure.record)
        != lean_import_closure.sha256
    ):
        raise ValueError("Lean import-closure receipt identity changed")
    sources = tuple(path.resolve() for path in lean_import_closure.repository_sources)
    if interface_path not in sources:
        raise ValueError("Lean import-closure omits the configured review interface")
    for source in sources:
        try:
            source.relative_to(root)
        except ValueError as exc:
            raise ValueError(
                "Lean import-closure source escapes the repository"
            ) from exc
    # A validated closure owns one immutable byte snapshot. Calling this
    # projection repeatedly must not re-read every source, which was a major
    # source of closeout churn on large paper audit directories.
    source_record_lean_import_closure_source_bytes(lean_import_closure)
    return list(sources)


def first_declaration_namespace(
    interface_path: Path, *, source_text: str | None = None
) -> str:
    """Return the namespace prefix active at the first paper-interface declaration."""

    namespace_stack: list[str] = []
    lines = mask_lean_comments(
        read_text(interface_path) if source_text is None else source_text
    ).splitlines()
    for index, line in enumerate(lines):
        stripped = line.strip()
        if stripped.startswith("namespace "):
            raw = stripped.removeprefix("namespace ").strip()
            namespace_stack.extend(part for part in raw.split(".") if part)
            continue
        if stripped.startswith("end"):
            parts = stripped.split()
            if len(parts) == 1:
                if namespace_stack:
                    namespace_stack.pop()
            elif len(parts) == 2 and namespace_stack:
                end_parts = [part for part in parts[1].split(".") if part]
                if end_parts and namespace_stack[-len(end_parts) :] == end_parts:
                    del namespace_stack[-len(end_parts) :]
                else:
                    namespace_stack.pop()
            continue
        if declaration_match_at(lines, index):
            return ".".join(namespace_stack)
    return ""


def source_record_isolated_staging_root(root: Path) -> Path:
    """Return the ignored worktree-local root for fresh Lean overlays.

    A paper namespace can contain hundreds of megabytes of compiled artifacts.
    Staging it in shared ``/tmp`` makes source-record validation depend on
    unrelated temporary artifacts and per-user tmpfs quotas.  Lake already
    owns a worktree-local ignored build area, so keep these short-lived
    overlays adjacent to the artifacts they isolate.
    """

    staging_root = root.resolve() / ".lake" / "source-record-tmp"
    staging_root.mkdir(parents=True, exist_ok=True)
    return staging_root


def source_record_hardlink_or_copy(source: str, destination: str) -> str:
    """Stage immutable compiled artifacts without duplicating same-device bytes.

    The fresh overlay removes the reviewed module before recompiling it, so an
    artifact hard link is safe: unlinking the overlay path cannot alter the
    Lake build artifact.  Filesystems that do not permit hard links retain the
    previous byte-copy behavior.
    """

    try:
        os.link(source, destination)
        return destination
    except OSError as exc:
        if exc.errno not in {
            errno.EXDEV,
            errno.EPERM,
            errno.EOPNOTSUPP,
            errno.EMLINK,
        }:
            raise
    return shutil.copy2(source, destination)


def structure_parent_types(header: str) -> list[str]:
    """Return explicit parent applications from a structure `extends` clause."""

    extends_at = top_level_word_index(header, "extends")
    if extends_at is None:
        return []
    where_at = top_level_word_index(header, "where")
    end = where_at if where_at is not None and where_at > extends_at else len(header)
    clause = header[extends_at + len("extends") : end].strip()
    parents: list[str] = []
    for raw_parent in split_top_level_commas(clause):
        named_parent = split_top_level_colon(raw_parent)
        parent_type = named_parent[1] if named_parent is not None else raw_parent
        parent_type = normalize_ws(parent_type)
        if parent_type:
            parents.append(parent_type)
    return parents


INDUCTIVE_CONSTRUCTOR_HEAD_RE = re.compile(
    rf"^\s*({LEAN_NAME_COMPONENT_PATTERN})(?=$|[\s:({{\[])"
)


def split_top_level_constructor_chunks(body: str) -> list[tuple[str, int]]:
    """Split `| ctor` clauses, including multiple constructors on one line."""

    chunks: list[tuple[str, int]] = []
    depth = 0
    starts: list[int] = []
    for index, char in enumerate(body):
        if char in "([{⦃":
            depth += 1
        elif char in ")]}⦄" and depth > 0:
            depth -= 1
        elif char == "|" and depth == 0:
            starts.append(index)
    for offset, start in enumerate(starts):
        end = starts[offset + 1] if offset + 1 < len(starts) else len(body)
        chunks.append((body[start + 1 : end].strip(), body.count("\n", 0, start)))
    return chunks


def inductive_constructor_fields(
    declaration: LocalDeclaration,
) -> tuple[list[FieldInfo], list[str], dict[str, str]]:
    """Expose each explicit constructor argument as an auditable record field.

    An inductive value is data only after its constructors are inspected. A
    constructor may require a proposition, so treating every local inductive as
    proposition-free data lets a theorem recover a hidden conclusion by cases.
    This source parser is conservative: unrecognized constructor syntax leaves
    the inductive with no certified fields and is handled as a recursion failure
    by the caller.
    """

    where_at = top_level_word_index(declaration.source, "where")
    body = (
        declaration.source[where_at + len("where") :]
        if where_at is not None
        else declaration.source
    )
    chunks: list[tuple[str, str, int]] = []
    for raw_chunk, line_offset in split_top_level_constructor_chunks(body):
        match = INDUCTIVE_CONSTRUCTOR_HEAD_RE.match(raw_chunk)
        if match is None:
            continue
        chunks.append(
            (
                match.group(1),
                normalize_ws(raw_chunk[match.end() :]),
                declaration.line + line_offset,
            )
        )

    header_parameter_names = {
        parameter
        for visible_input in visible_inputs_from_declaration(
            declaration.source, include_result_inputs=False
        )
        for parameter in binder_names(visible_input.get("names", ""))
    }
    fields: list[FieldInfo] = []
    constructor_names: list[str] = []
    unreconciled_constructor_slots: dict[str, str] = {}
    for constructor_name, constructor_tail, line in chunks:
        constructor_fqn = f"{declaration.name}.{constructor_name}"
        constructor_names.append(constructor_fqn)
        result_split = split_top_level_colon(constructor_tail)
        binder_prefix = result_split[0] if result_split is not None else constructor_tail
        inputs: list[dict[str, str]] = []
        for binder in balanced_binder_spans(binder_prefix):
            binder_split = split_top_level_colon(binder)
            if binder_split is None:
                continue
            raw_names, raw_type = binder_split
            names = binder_names(raw_names)
            if raw_type and names:
                inputs.append({"names": " ".join(names), "type": normalize_ws(raw_type)})
        if result_split is not None:
            result_inputs, terminal_result = result_type_inputs(result_split[1])
            inputs.extend(result_inputs)
            # A direct top-level result argument is an unambiguous source
            # index, e.g. `Pack P n`.  Any constructor binder mentioned under
            # a projection, application, or other expression (`Mixed P w.val`,
            # `Foo (f n)`) may still be a Lean stored field.  Do not guess an
            # ordinal from spelling: leave the whole constructor unresolved
            # until the Lean `CtorInfo.numFields` reconciliation pass replaces
            # these labels with exact slots.
            candidate_names = {
                name
                for visible_input in inputs
                for name in binder_names(visible_input.get("names", ""))
                if name not in header_parameter_names
            }
            top_level_result_terms = set(
                split_top_level_terms(strip_outer_group(terminal_result))
            )
            direct_result_index_names = candidate_names & top_level_result_terms
            all_result_mentions = {
                match.group(1)
                for match in LEAN_IDENTIFIER_RE.finditer(terminal_result)
                if match.group(1) in candidate_names
            }
            ambiguous_result_mentions = all_result_mentions - direct_result_index_names
            if ambiguous_result_mentions:
                unreconciled_constructor_slots[constructor_fqn] = (
                    "constructor binder(s) occur in a non-direct result index expression: "
                    + ", ".join(sorted(ambiguous_result_mentions))
                )
                continue
            result_index_names = direct_result_index_names
        else:
            result_index_names = set()

        argument_index = 0
        for visible_input in inputs:
            input_type = normalize_ws(visible_input.get("type", ""))
            names = binder_names(visible_input.get("names", ""))
            if not names:
                names = [f"arg{argument_index}"]
            for argument_name in names:
                if argument_name in result_index_names:
                    continue
                field_name = f"{constructor_name}.{argument_name}"
                fields.append(
                    FieldInfo(
                        structure=declaration.name,
                        field=field_name,
                        type=input_type,
                        path=f"{declaration.name}.{field_name}",
                        line=line,
                        source_file=declaration.source_file,
                        nested_structures=[],
                        risk_terms=[],
                        constructor_fqn=constructor_fqn,
                        constructor_argument_index=argument_index,
                    )
                )
                argument_index += 1
    return fields, constructor_names, unreconciled_constructor_slots


def parse_structures(
    root: Path,
    lean_files: list[Path],
    *,
    source_text_by_path: Mapping[Path, str] | None = None,
    local_declarations: Iterable[LocalDeclaration] | None = None,
) -> dict[str, StructureInfo]:
    """Parse repository-local structures, classes, and inductive constructors."""

    structures: dict[str, StructureInfo] = {}
    for lean_file in lean_files:
        try:
            rel_file = str(lean_file.resolve().relative_to(root))
        except ValueError:
            rel_file = str(lean_file)
        lines = mask_lean_comments(
            source_text_from_snapshot(lean_file, source_text_by_path)
        ).splitlines()
        scopes: list[tuple[str, list[str]]] = []
        index = 0
        while index < len(lines):
            if update_namespace_scopes(lines[index], scopes):
                index += 1
                continue
            match = structure_match_at(lines, index)
            if not match:
                index += 1
                continue
            name = qualify_declaration_name(match.group(1), scopes)
            start_line = index + 1
            header_parts = [lines[index]]
            header_cursor = index + 1
            while (
                header_cursor < len(lines)
                and top_level_word_index(" ".join(header_parts), "where") is None
                and not TOP_LEVEL_RE.match(lines[header_cursor])
            ):
                header_parts.append(lines[header_cursor])
                header_cursor += 1
            header = " ".join(header_parts)
            parameter_types: dict[str, str] = {}
            for visible_input in visible_inputs_from_declaration(header):
                type_text = normalize_ws(visible_input.get("type", ""))
                for parameter_name in binder_names(visible_input.get("names", "")):
                    parameter_types[parameter_name] = type_text
            parameters = list(parameter_types)
            fields: list[FieldInfo] = [
                FieldInfo(
                    structure=name,
                    field=f"__extends_{parent_index}",
                    type=parent_type,
                    path=f"{name}.__extends_{parent_index}",
                    line=start_line,
                    source_file=rel_file,
                    nested_structures=[],
                    risk_terms=[],
                    constructor_fqn=f"{name}.mk",
                    constructor_argument_index=parent_index,
                )
                for parent_index, parent_type in enumerate(
                    structure_parent_types(header)
                )
            ]
            index = header_cursor
            current_name: str | None = None
            current_start_line = 0
            current_type_parts: list[str] = []
            field_indentation: int | None = None

            def flush_current() -> None:
                nonlocal current_name, current_start_line, current_type_parts
                if current_name is None:
                    return
                field_type = normalize_ws(" ".join(current_type_parts))
                fields.append(
                    FieldInfo(
                        structure=name,
                        field=current_name,
                        type=field_type,
                        path=f"{name}.{current_name}",
                        line=current_start_line,
                        source_file=rel_file,
                        nested_structures=[],
                        risk_terms=[],
                        constructor_fqn=f"{name}.mk",
                        constructor_argument_index=len(fields),
                        projection_fqn=f"{name}.{current_name}",
                    )
                )
                current_name = None
                current_start_line = 0
                current_type_parts = []

            while index < len(lines):
                line = lines[index]
                if TOP_LEVEL_RE.match(line):
                    break
                field_match = FIELD_RE.match(line)
                parenthesized_field_match = PARENTHESIZED_FIELD_RE.match(line)
                bracketed_field_match = BRACKETED_FIELD_RE.match(line)
                # `let` and `letI` can begin an indented dependent field type.
                # They are Lean term binders, not stored record fields, even
                # though their `name : type` prefix resembles field syntax.
                # Treating them as fields shifts every later constructor slot.
                matched_field = (
                    bracketed_field_match or parenthesized_field_match or field_match
                )
                is_local_type_binder = (
                    matched_field is not None
                    and matched_field.group(1) in {"let", "letI"}
                )
                indentation = len(line) - len(line.lstrip())
                is_stored_field_indentation = (
                    field_indentation is None or indentation == field_indentation
                )
                if (
                    matched_field is not None
                    and not is_local_type_binder
                    and is_stored_field_indentation
                ):
                    if field_indentation is None:
                        field_indentation = indentation
                    flush_current()
                    current_name = matched_field.group(1)
                    current_start_line = index + 1
                    current_type_parts = [matched_field.group(2).strip()]
                elif current_name is not None:
                    stripped = line.strip()
                    if stripped and not stripped.startswith("--"):
                        current_type_parts.append(stripped)
                index += 1
            flush_current()
            if name in structures:
                previous = structures[name]
                raise ValueError(
                    f"duplicate structure identity {name!r}: "
                    f"{previous.source_file} and {rel_file}"
                )
            structures[name] = StructureInfo(
                name=name,
                source_file=rel_file,
                line=start_line,
                fields=fields,
                parameters=parameters,
                parameter_types=parameter_types,
            )

    declarations_for_inductives = (
        list(local_declarations)
        if local_declarations is not None
        else parse_local_declarations(
            root, lean_files, source_text_by_path=source_text_by_path
        )
    )
    for declaration in declarations_for_inductives:
        if declaration.kind != "inductive":
            continue
        if declaration.name in structures:
            previous = structures[declaration.name]
            raise ValueError(
                f"duplicate record/inductive identity {declaration.name!r}: "
                f"{previous.source_file} and {declaration.source_file}"
            )
        parameter_types: dict[str, str] = {}
        for visible_input in visible_inputs_from_declaration(declaration.source):
            type_text = normalize_ws(visible_input.get("type", ""))
            for parameter_name in binder_names(visible_input.get("names", "")):
                parameter_types[parameter_name] = type_text
        parameters = list(parameter_types)
        (
            constructor_fields,
            constructor_names,
            unreconciled_constructor_slots,
        ) = inductive_constructor_fields(
            declaration
        )
        structures[declaration.name] = StructureInfo(
            name=declaration.name,
            source_file=declaration.source_file,
            line=declaration.line,
            fields=constructor_fields,
            parameters=parameters,
            kind="inductive",
            constructor_count=len(constructor_names),
            parameter_types=parameter_types,
            constructor_names=constructor_names,
            unreconciled_constructor_slots=unreconciled_constructor_slots,
        )
    return structures


def audit_candidate_structures(
    structures: dict[str, StructureInfo],
    paper_local_structures: dict[str, StructureInfo],
) -> set[str]:
    """Select every parsed repository record reachable from the review surface.

    Import traversal already excludes Mathlib internals. Restricting imported
    repository records by a suffix would make a neutral rename an audit
    evasion, so names play no role in this set.
    """

    _ = paper_local_structures
    return set(structures)


def structure_parameter_counts(
    structures: dict[str, StructureInfo],
) -> dict[str, int]:
    """Return declared type-parameter counts for semantic occurrence checks."""

    return {
        name: len(structure.parameters)
        for name, structure in structures.items()
    }


def parse_structure_aliases(
    lean_files: list[Path],
    structures: dict[str, StructureInfo],
    *,
    source_text_by_path: Mapping[Path, str] | None = None,
    local_declarations: Iterable[LocalDeclaration] | None = None,
) -> dict[str, str]:
    """Resolve reducible type aliases whose body is a parsed structure type.

    Paper interfaces frequently rename a large source record before using it in
    a reviewed theorem binder. Treating only literal structure names, or only
    ``abbrev`` aliases, as records lets an otherwise identical ``def`` type
    synonym hide all proposition-valued fields from recursive audit.

    An explicit non-sort result proves that a declaration is a value, even when
    its body starts with a projection or constructor whose short name is shared
    elsewhere. Inferred candidates are admitted only if their body head resolves
    through already admitted aliases to a parsed structure. Names are retained
    only to route occurrences back to the parsed type; they do not affect the
    audit classification.
    """

    raw_aliases: dict[str, str] = {}
    if local_declarations is None:
        declaration_items = []
        for lean_file in lean_files:
            source_text = source_text_from_snapshot(lean_file, source_text_by_path)
            declaration_items.extend(
                parse_declarations(lean_file, source_text=source_text).items()
            )
    else:
        declaration_items = [
            (declaration.name, declaration.source)
            for declaration in local_declarations
        ]
    for name, declaration in declaration_items:
        match = DECL_RE.match(declaration)
        if match is None or match.group(1) not in {"abbrev", "def"}:
            continue
        result_type = strip_outer_group(
            alpha_canonical_type(declaration_terminal_result_type(declaration))
        )
        if result_type and not re.match(
            r"^(?:Type|Sort)(?:\b|\s|\*|[0-9_(])", result_type
        ):
            continue
        body_start = top_level_token_index(declaration, ":=")
        if body_start is None:
            continue
        body = declaration[body_start + 2 :].lstrip()
        target_match = re.match(
            r"@?((?:[A-Za-z_][A-Za-z0-9_']*\.)*[A-Za-z_][A-Za-z0-9_']*)"
            r"(?![A-Za-z0-9_'])",
            body,
        )
        if target_match is not None:
            raw_aliases[name] = target_match.group(1)

    def resolve_name(reference: str, owner: str, names: set[str]) -> str | None:
        owner_namespace = owner.rsplit(".", 1)[0] if "." in owner else ""
        matches = lexical_name_candidates(
            reference,
            names,
            context_namespace=owner_namespace,
        )
        if len(matches) > 1:
            raise ValueError(
                f"ambiguous structure alias target {reference!r} for {owner!r}: "
                + ", ".join(matches)
            )
        return matches[0] if matches else None

    resolved: dict[str, str] = {}
    pending = dict(sorted(raw_aliases.items()))
    while pending:
        progressed = False
        for alias, reference in list(pending.items()):
            target = resolve_name(reference, alias, set(structures) | set(resolved))
            if target is None:
                continue
            resolved[alias] = resolved.get(target, target)
            del pending[alias]
            progressed = True
        if not progressed:
            break
    return resolved


def mentioned_structures(
    text: str,
    candidates: set[str],
    aliases: dict[str, str] | None = None,
    *,
    context_namespace: str = "",
    shadowed_names: set[str] | None = None,
    structure_parameter_counts: dict[str, int] | None = None,
) -> list[str]:
    """Resolve structure occurrences in a lexical binder environment.

    Resolution mirrors the namespace portion of Lean name lookup before a
    conservative suffix fallback.  In particular, a declaration inside
    ``A.B`` referring to ``Model`` first looks for ``A.B.Model`` and then
    ``A.Model``; it must not recursively audit an unrelated imported
    ``C.Model`` merely because the short names coincide.  When lexical lookup
    cannot decide the reference, every compatible suffix candidate is retained
    so traversal order never chooses an audit target.

    ``structure_parameter_counts`` is optional because some callers only have
    a set of candidate names.  When available, it removes a candidate only
    when the source occurrence visibly supplies more explicit arguments than
    the candidate declares.  This is a sound one-way filter: omitted implicit
    arguments remain admissible, while a nullary imported record cannot match
    a source type written as ``Model n``.

    Locally bound identifiers shadow unqualified global constants, as they do
    in Lean; qualification still makes a global structure explicit.
    """

    parameter_counts = structure_parameter_counts or {}

    def namespace_candidates(token: str) -> list[str]:
        """Return lexical namespace candidates from most to least local."""

        if not context_namespace:
            return [token]
        parts = [part for part in context_namespace.split(".") if part]
        return [".".join([*parts[:index], token]) for index in range(len(parts), -1, -1)]

    def visible_application_arity(text_after_head: str) -> int:
        """Count explicit type arguments immediately following one head.

        This deliberately needs only a lower bound.  It recognizes ordinary
        atoms and balanced explicit/named arguments, stopping at a type
        connective or delimiter.  It does not try to infer implicit arguments
        or elaborate terms; those omissions must never reject a compatible
        structure.
        """

        text_after_head = text_after_head.lstrip()
        # Universe parameters are not structure arguments.
        if text_after_head.startswith(".{"):
            depth = 0
            for index, char in enumerate(text_after_head):
                if char == "{":
                    depth += 1
                elif char == "}":
                    depth -= 1
                    if depth == 0:
                        text_after_head = text_after_head[index + 1 :].lstrip()
                        break

        count = 0
        index = 0
        stop_characters = ",:)=]}>"
        stop_tokens = ("→", "->", "↔", "∧", "∨", "=", "<", ">")
        paired = {"(": ")", "[": "]", "{": "}", "⦃": "⦄"}
        while index < len(text_after_head):
            while index < len(text_after_head) and text_after_head[index].isspace():
                index += 1
            if index >= len(text_after_head):
                break
            if any(text_after_head.startswith(token, index) for token in stop_tokens):
                break
            char = text_after_head[index]
            if char in stop_characters or char in ")]}⦄":
                break
            if char in paired:
                closing = paired[char]
                depth = 1
                index += 1
                while index < len(text_after_head) and depth:
                    nested = text_after_head[index]
                    if nested == char:
                        depth += 1
                    elif nested == closing:
                        depth -= 1
                    index += 1
                if depth:
                    break
                count += 1
                continue
            match = re.match(r"[^\s,:)=\]}>→↔∧∨<]+", text_after_head[index:])
            if match is None:
                break
            count += 1
            index += match.end()
        return count

    def compatible(names: list[str], explicit_arity: int) -> list[str]:
        return [
            name
            for name in names
            if name not in parameter_counts
            or explicit_arity <= parameter_counts[name]
        ]

    def matches(token: str, names: set[str], explicit_arity: int) -> list[str]:
        for preferred in namespace_candidates(token):
            if preferred in names and preferred in compatible([preferred], explicit_arity):
                return [preferred]
        suffix = f".{token}"
        return compatible([name for name in names if name.endswith(suffix)], explicit_arity)

    found: set[str] = set()
    alias_map = aliases or {}
    alias_names = set(alias_map)
    shadowed = shadowed_names or set()
    for match in re.finditer(
        r"(?<![A-Za-z0-9_'])([A-Za-z_][A-Za-z0-9_']*"
        r"(?:\.[A-Za-z_][A-Za-z0-9_']*)*)(?![A-Za-z0-9_'])",
        text,
    ):
        token = match.group(1)
        if "." not in token and token in shadowed:
            continue
        explicit_arity = visible_application_arity(text[match.end() :])
        found.update(matches(token, candidates, explicit_arity))
        for alias_name in matches(token, alias_names, explicit_arity):
            target = alias_map[alias_name]
            if target in candidates:
                found.add(target)
    return sorted(found)


def mentioned_structures_in_scoped_inputs(
    inputs: list[dict[str, str]],
    candidates: set[str],
    aliases: dict[str, str] | None = None,
    *,
    context_namespace: str = "",
    initial_shadowed_names: set[str] | None = None,
    structure_parameter_counts: dict[str, int] | None = None,
) -> list[str]:
    """Resolve records in dependent binders using Lean's left-to-right scope."""

    shadowed = set(initial_shadowed_names or set())
    found: set[str] = set()
    for visible_input in inputs:
        found.update(
            mentioned_structures(
                visible_input.get("type", ""),
                candidates,
                aliases,
                context_namespace=context_namespace,
                shadowed_names=shadowed,
                structure_parameter_counts=structure_parameter_counts,
            )
        )
        shadowed.update(binder_names(visible_input.get("names", "")))
    return sorted(found)


def mentioned_structures_in_delta_expanded_scoped_inputs(
    inputs: list[dict[str, str]],
    candidates: set[str],
    aliases: dict[str, str] | None,
    *,
    proposition_aliases: dict[str, PropositionAliasInfo] | None,
    semantic_declarations: list[LocalDeclaration],
    context_namespace: str = "",
    initial_shadowed_names: set[str] | None = None,
    structure_parameter_counts: dict[str, int] | None = None,
) -> list[str]:
    """Find record roots after exact transparent premise normalization.

    A conclusion antecedent can be an ordinary paper-local ``def``/``abbrev``
    whose proposition body contains a transition or record value.  Inspecting
    only the surface spelling after we have already expanded it elsewhere
    creates a name-dependent blind spot.  This helper follows the same exact
    lexical expansion route as the conclusion dependency item and deliberately
    keeps unresolved, opaque, cyclic, or bounded paths unexpanded.
    """

    shadowed = set(initial_shadowed_names or set())
    found: set[str] = set()
    for visible_input in inputs:
        expansion = delta_expand_transparent_proposition_aliases(
            visible_input.get("type", ""),
            proposition_aliases,
            semantic_declarations,
            context_namespace=context_namespace,
            shadowed_names=shadowed,
        )
        found.update(
            mentioned_structures(
                expansion.expanded_type,
                candidates,
                aliases,
                context_namespace=context_namespace,
                shadowed_names=shadowed,
                structure_parameter_counts=structure_parameter_counts,
            )
        )
        shadowed.update(binder_names(visible_input.get("names", "")))
    return sorted(found)


def unresolved_local_reducible_type_head(
    type_text: str,
    semantic_declarations: list[LocalDeclaration],
    aliases: dict[str, str],
    structures: dict[str, StructureInfo],
    *,
    context_namespace: str = "",
    proposition_heads: set[str] | None = None,
    data_heads: set[str] | None = None,
    shadowed_names: set[str] | None = None,
) -> LocalDeclaration | None:
    """Find an unexpanded local type-level def that could conceal a record.

    This is deliberately conservative. The static audit can recursively follow
    direct structure applications and plain aliases, but it cannot normalize a
    computed family such as ``if b then R x else Unit``. An unknown theorem
    binder headed by such a paper/repository-local ``def`` or ``abbrev`` must
    therefore remain an unresolved conclusion dependency instead of being
    blessable as generic data by free-text judgment.
    """

    stripped = strip_outer_group(alpha_canonical_type(type_text))
    match = re.match(
        r"^@?((?:[A-Za-z_][A-Za-z0-9_']*\.)*[A-Za-z_][A-Za-z0-9_']*)"
        r"(?![A-Za-z0-9_'])",
        stripped,
    )
    if match is None:
        return None
    head = match.group(1)
    if "." not in head and head in (shadowed_names or set()):
        return None
    if mentioned_structures(
        stripped,
        set(structures),
        aliases,
        context_namespace=context_namespace,
        shadowed_names=shadowed_names,
        structure_parameter_counts=structure_parameter_counts(structures),
    ):
        return None
    declarations_by_name = {
        declaration.name: declaration for declaration in semantic_declarations
    }
    matches = lexical_name_candidates(
        head,
        set(declarations_by_name),
        context_namespace=context_namespace,
    )
    resolved = matches[0] if len(matches) == 1 else ""
    if len(matches) > 1:
        candidates = [declarations_by_name[name] for name in matches]
        unresolved_candidates = [
            candidate
            for candidate in candidates
            if candidate.kind in {"def", "abbrev"}
            and not (
                declaration_body_text(candidate.source)
                and is_definitely_data_type(
                    declaration_body_text(candidate.source),
                    proposition_heads=proposition_heads,
                    data_heads=data_heads,
                )
            )
        ]
        if not unresolved_candidates:
            return None
        return LocalDeclaration(
            name="ambiguous:" + ",".join(matches),
            kind="def",
            source="ambiguous local reducible type head: " + ", ".join(matches),
            source_file="",
            line=0,
        )
    if not resolved:
        return None
    declaration = declarations_by_name[resolved]
    if declaration.kind not in {"def", "abbrev"}:
        return None
    body = declaration_body_text(declaration.source)
    if body and is_definitely_data_type(
        body,
        proposition_heads=proposition_heads,
        data_heads=data_heads,
    ):
        return None
    return declaration


def transparent_subtype_domain(
    type_text: str,
    semantic_declarations: list[LocalDeclaration],
    *,
    context_namespace: str = "",
    shadowed_names: set[str] | None = None,
) -> TransparentSubtypeDomain | None:
    """Expand a direct/local reducible subtype into carrier and predicate.

    This is intentionally narrower than general type normalization.  It follows
    only the lexical, transparent `def`/`abbrev` chain headed by the actual
    binder type and stops at the first structural subtype.  An opaque/ambiguous
    path is not guessed.  When source syntax explicitly says `Subtype` but the
    small structural parser cannot recover both projections, a deliberately
    incomplete domain is returned so the caller emits a visible fail-closed
    dependency instead of silently treating it as data.
    """

    original = normalize_ws(type_text).strip()
    current = strip_outer_group(original).strip()
    shadowed = set(shadowed_names or set())
    declarations_by_name = {
        declaration.name: declaration for declaration in semantic_declarations
    }
    expansion_steps: list[str] = []
    local_head = ""
    local_source = ""
    seen: set[str] = set()

    for _ in range(64):
        components = subtype_brace_components(current)
        if components is not None:
            value_binder, carrier, predicate = components
            return TransparentSubtypeDomain(
                expanded_type=normalize_ws(current),
                carrier_type=carrier,
                predicate=predicate,
                value_binder=value_binder,
                expansion_origin=(
                    "direct_subtype"
                    if not expansion_steps
                    else "local_reducible_subtype"
                ),
                local_type_head=local_head,
                local_type_source=local_source,
                expansion_steps=tuple(expansion_steps),
            )
        if is_structural_subtype_surface(current):
            return TransparentSubtypeDomain(
                expanded_type=normalize_ws(current),
                carrier_type="",
                predicate="",
                value_binder="",
                expansion_origin=(
                    "direct_subtype"
                    if not expansion_steps
                    else "local_reducible_subtype"
                ),
                local_type_head=local_head,
                local_type_source=local_source,
                expansion_steps=tuple(expansion_steps),
                expansion_complete=False,
                expansion_error=(
                    "the structural subtype surface could not be decomposed into "
                    "one carrier binder and one predicate"
                ),
            )

        head = expression_head(current)
        if not head or ("." not in head and head in shadowed):
            return None
        resolved = strict_lexical_declaration_identity(
            head,
            set(declarations_by_name),
            context_namespace=context_namespace,
        )
        if resolved is None:
            return None
        declaration = declarations_by_name[resolved]
        if declaration.kind not in {"def", "abbrev"}:
            return None
        body = declaration_body_text(declaration.source)
        if not body or body.startswith("by"):
            return None
        current_key = canonical_type(current)
        if current_key in seen:
            return None
        seen.add(current_key)
        parameters = [
            name
            for visible_input in header_inputs_from_declaration(declaration.source)
            if not str(visible_input.get("names") or "").startswith("instance_")
            for name in binder_names(visible_input.get("names", ""))
        ]
        alias_info = PropositionAliasInfo(
            name=declaration.name,
            parameters=parameters,
            body=body,
        )
        next_current = _unfold_proposition_alias_once(
            current,
            {
                declaration.name: alias_info,
                declaration.name.rsplit(".", 1)[-1]: alias_info,
            },
        )
        if canonical_type(next_current) == current_key:
            return None
        expansion_steps.append(declaration.name)
        local_head = declaration.name
        local_source = declaration.source
        current = strip_outer_group(next_current).strip()
    return None


def local_reducible_subtype_type_predicate(
    type_text: str,
    semantic_declarations: list[LocalDeclaration],
    aliases: dict[str, str],
    structures: dict[str, StructureInfo],
    *,
    context_namespace: str = "",
    proposition_heads: set[str] | None = None,
    data_heads: set[str] | None = None,
    shadowed_names: set[str] | None = None,
    subtype_alias_heads: set[str] | None = None,
) -> str | None:
    """Return the proposition stored by a direct or local reducible subtype.

    A subtype value has a data projection and a proof projection. Record-field
    auditing may classify the former as carrier data, but it must retain the
    latter as a proposition-bearing boundary obligation. In particular, the
    predicate cannot be discarded merely because it is not syntactically
    related to the reviewed row's result: a helper theorem may derive that
    result from the stored proof.
    """

    # Keep the legacy parameters for callers that classify record fields, but
    # route the actual structural expansion through the same source-independent
    # subtype parser used for theorem binders.
    del aliases, structures, proposition_heads, data_heads, subtype_alias_heads
    domain = transparent_subtype_domain(
        type_text,
        semantic_declarations,
        context_namespace=context_namespace,
        shadowed_names=shadowed_names,
    )
    if domain is None or not domain.expansion_complete:
        return None
    return domain.predicate


def expression_head(text: str) -> str:
    stripped = strip_outer_group(normalize_ws(text).strip())
    match = re.match(
        r"^@?((?:[A-Za-z_][A-Za-z0-9_']*\.)*[A-Za-z_][A-Za-z0-9_']*)"
        r"(?![A-Za-z0-9_'])",
        stripped,
    )
    return match.group(1) if match is not None else ""


def split_top_level_equality(text: str) -> tuple[str, str] | None:
    index = top_level_token_index(normalize_ws(text), "=")
    if index is None:
        return None
    normalized = normalize_ws(text)
    return normalized[:index].strip(), normalized[index + 1 :].strip()


def bool_equality_true_head(type_text: str) -> str:
    split = split_top_level_equality(type_text)
    if split is None:
        return ""
    left, right = split
    if strip_outer_group(right) == "true":
        return expression_head(left)
    if strip_outer_group(left) == "true":
        return expression_head(right)
    return ""


def option_equality_some_head(type_text: str) -> str:
    split = split_top_level_equality(type_text)
    if split is None:
        return ""
    left, right = split
    right_head = expression_head(strip_outer_group(right))
    left_head = expression_head(strip_outer_group(left))
    if right_head in {"some", "Option.some"}:
        return expression_head(left)
    if left_head in {"some", "Option.some"}:
        return expression_head(right)
    return ""


def resolve_local_declaration_head(
    head: str,
    semantic_declarations: list[LocalDeclaration],
    *,
    context_namespace: str = "",
) -> LocalDeclaration | None:
    if not head:
        return None
    declarations_by_name = {
        declaration.name: declaration for declaration in semantic_declarations
    }
    matches = lexical_name_candidates(
        head,
        set(declarations_by_name),
        context_namespace=context_namespace,
    )
    return declarations_by_name[matches[0]] if len(matches) == 1 else None


def decided_propositions_from_body(body: str) -> list[str]:
    """Return every explicit proposition argument to ``decide`` in source order."""

    text = normalize_ws(body)
    propositions: list[str] = []
    for match in re.finditer(
        r"(?<![A-Za-z0-9_'])decide(?![A-Za-z0-9_'])", text
    ):
        remainder = text[match.end() :].strip()
        if not remainder:
            continue
        if remainder[0] in "([{⦃":
            pairs = {"(": ")", "[": "]", "{": "}", "⦃": "⦄"}
            stack = [pairs[remainder[0]]]
            cursor = 1
            while cursor < len(remainder) and stack:
                char = remainder[cursor]
                if char in pairs:
                    stack.append(pairs[char])
                elif char == stack[-1]:
                    stack.pop()
                cursor += 1
            if stack:
                continue
            proposition = strip_outer_group(remainder[:cursor])
        else:
            stop = len(remainder)
            for token in ("&&", "||", ";", " then ", " else "):
                index = remainder.find(token)
                if index >= 0:
                    stop = min(stop, index)
            proposition = strip_outer_group(remainder[:stop])
        if proposition and proposition not in propositions:
            propositions.append(proposition)
    return propositions



def if_certificate_proposition_from_body(body: str, *, option_success: bool) -> str:
    """Extract ``P`` from proof-bearing Boolean/Option conditional encodings.

    This recognizes the semantic identities ``if P then true else false`` and
    ``if h : P then some value else none`` without depending on declaration or
    binder names.  It deliberately does not classify ordinary data-valued
    conditionals whose branches do not expose success/failure constructors.
    """

    text = normalize_ws(body)
    matches = list(re.finditer(r"(?<![\w'])if(?![\w'])", text, re.UNICODE))
    for match in reversed(matches):
        after_if = text[match.end() :].strip()
        then_index = top_level_word_index(after_if, "then")
        if then_index is None:
            continue
        guard_clause = after_if[:then_index].strip()
        after_then = after_if[then_index + len("then") :].strip()
        else_index = top_level_word_index(after_then, "else")
        if else_index is None:
            continue
        success_branch = strip_outer_group(after_then[:else_index].strip())
        failure_branch = strip_outer_group(
            after_then[else_index + len("else") :].strip()
        )
        if option_success:
            if expression_head(success_branch) not in {"some", "Option.some"}:
                continue
            if expression_head(failure_branch) not in {"none", "Option.none"}:
                continue
        elif success_branch != "true" or failure_branch != "false":
            continue

        dependent = split_top_level_colon(guard_clause)
        if dependent is not None and binder_names(dependent[0]) and dependent[1]:
            return strip_outer_group(dependent[1])
        return strip_outer_group(guard_clause)
    return ""


def referenced_local_declarations_in_body(
    body: str,
    semantic_declarations: list[LocalDeclaration],
    *,
    context_namespace: str = "",
    exclude: set[str] | None = None,
    shadowed_names: set[str] | None = None,
) -> list[LocalDeclaration]:
    """Return local def/abbrev declarations mentioned in a body, in occurrence order."""

    excluded = exclude or set()
    shadowed = shadowed_names or set()
    out: list[LocalDeclaration] = []
    seen: set[str] = set()
    for match in re.finditer(
        r"\b((?:[A-Za-z_][A-Za-z0-9_']*\.)*[A-Za-z_][A-Za-z0-9_']*)\b",
        body,
    ):
        head = match.group(1)
        if head.split(".", 1)[0] in shadowed:
            continue
        declaration = resolve_local_declaration_head(
            head,
            semantic_declarations,
            context_namespace=context_namespace,
        )
        if declaration is None:
            continue
        if declaration.kind not in {"def", "abbrev"}:
            continue
        if declaration.name in excluded or declaration.name in seen:
            continue
        seen.add(declaration.name)
        out.append(declaration)
    return out


def bool_certificate_from_declaration(
    declaration: LocalDeclaration,
    semantic_declarations: list[LocalDeclaration],
    *,
    context_namespace: str = "",
    chain: list[str] | None = None,
    seen: set[str] | None = None,
    max_depth: int = 4,
) -> dict[str, Any] | None:
    if declaration.kind not in {"def", "abbrev"}:
        return None
    active_chain = list(chain or [])
    active_seen = set(seen or set())
    if declaration.name in active_seen or max_depth < 0:
        return None
    active_chain.append(declaration.name)
    active_seen.add(declaration.name)
    body = declaration_body_text(declaration.source)
    propositions = decided_propositions_from_body(body)
    truth_if = if_certificate_proposition_from_body(body, option_success=False)
    if truth_if and truth_if not in propositions:
        propositions.append(truth_if)
    certificate_chain = list(active_chain)
    for referenced in referenced_local_declarations_in_body(
        body,
        semantic_declarations,
        context_namespace=context_namespace,
        exclude=active_seen,
        shadowed_names={
            name
            for visible_input in visible_inputs_from_declaration(
                declaration.source
            )
            for name in binder_names(visible_input.get("names", ""))
        },
    ):
        nested = bool_certificate_from_declaration(
            referenced,
            semantic_declarations,
            context_namespace=context_namespace,
            chain=active_chain,
            seen=active_seen,
            max_depth=max_depth - 1,
        )
        if nested is not None:
            nested_propositions = nested.get("decoded_propositions")
            if not isinstance(nested_propositions, list):
                nested_propositions = [nested.get("decoded_proposition")]
            for nested_proposition in nested_propositions:
                normalized = str(nested_proposition or "").strip()
                if normalized and normalized not in propositions:
                    propositions.append(normalized)
            for nested_name in nested.get("checker_chain") or []:
                normalized_name = str(nested_name or "").strip()
                if normalized_name and normalized_name not in certificate_chain:
                    certificate_chain.append(normalized_name)
    if not propositions:
        return None
    return {
        "checker": declaration.name,
        "checker_chain": certificate_chain,
        "decoded_propositions": propositions,
        "decoded_proposition": " /\\ ".join(propositions),
        "source_file": declaration.source_file,
        "line": declaration.line,
    }


def bool_certificate_decided_proposition(
    type_text: str,
    semantic_declarations: list[LocalDeclaration],
    *,
    context_namespace: str = "",
    max_depth: int = 4,
) -> dict[str, Any] | None:
    """Expose theorem premises of the form `checker ... = true`.

    A local Boolean checker can be a harmless data computation, but when it
    unfolds to `decide P`, `if P then true else false`, or a finite Boolean
    wrapper around either encoding, a proof of `checker = true` is proof-bearing.
    Treating that as opaque data lets theorem-shaped assumptions evade the
    semantic source audit.
    """

    head = bool_equality_true_head(type_text)
    if not head:
        return None
    declaration = resolve_local_declaration_head(
        head,
        semantic_declarations,
        context_namespace=context_namespace,
    )
    if declaration is None:
        return None
    return bool_certificate_from_declaration(
        declaration,
        semantic_declarations,
        context_namespace=context_namespace,
        max_depth=max_depth,
    )


def option_success_certificate_from_declaration(
    declaration: LocalDeclaration,
    semantic_declarations: list[LocalDeclaration],
    *,
    context_namespace: str = "",
    chain: list[str] | None = None,
    seen: set[str] | None = None,
    max_depth: int = 4,
) -> dict[str, Any] | None:
    if declaration.kind not in {"def", "abbrev"}:
        return None
    active_chain = list(chain or [])
    active_seen = set(seen or set())
    if declaration.name in active_seen or max_depth < 0:
        return None
    active_chain.append(declaration.name)
    active_seen.add(declaration.name)
    body = declaration_body_text(declaration.source)
    proposition = if_certificate_proposition_from_body(body, option_success=True)
    if proposition:
        return {
            "selector": declaration.name,
            "selector_chain": active_chain,
            "decoded_proposition": proposition,
            "source_file": declaration.source_file,
            "line": declaration.line,
        }
    for referenced in referenced_local_declarations_in_body(
        body,
        semantic_declarations,
        context_namespace=context_namespace,
        exclude=active_seen,
        shadowed_names={
            name
            for visible_input in visible_inputs_from_declaration(declaration.source)
            for name in binder_names(visible_input.get("names", ""))
        },
    ):
        nested = option_success_certificate_from_declaration(
            referenced,
            semantic_declarations,
            context_namespace=context_namespace,
            chain=active_chain,
            seen=active_seen,
            max_depth=max_depth - 1,
        )
        if nested is not None:
            return nested
    return None


def option_success_certificate_proposition(
    type_text: str,
    semantic_declarations: list[LocalDeclaration],
    *,
    context_namespace: str = "",
    max_depth: int = 4,
) -> dict[str, Any] | None:
    """Expose ``selector ... = some value`` when success is guarded by a Prop."""

    head = option_equality_some_head(type_text)
    if not head:
        return None
    declaration = resolve_local_declaration_head(
        head,
        semantic_declarations,
        context_namespace=context_namespace,
    )
    if declaration is None:
        return None
    return option_success_certificate_from_declaration(
        declaration,
        semantic_declarations,
        context_namespace=context_namespace,
        max_depth=max_depth,
    )


def field_risk_terms(field: FieldInfo) -> list[str]:
    haystack = f"{field.structure} {field.field} {field.type}".lower()
    return sorted(term for term in RISK_TERMS if term.lower() in haystack)


def semantic_model_surface_type(
    type_text: str,
    proposition_aliases: dict[str, PropositionAliasInfo],
    type_aliases: dict[str, TypeAliasInfo] | None = None,
    *,
    context_namespace: str = "",
    bound_names: set[str] | None = None,
) -> dict[str, str]:
    """Render one comparison type with alpha-invariant content beside it.

    The human-readable form is useful for the source judge, while the
    alpha-normalized form ensures that merely renaming a Lean binder cannot
    suppress a semantic-model review obligation.  Transparent local type
    aliases are expanded as well: a neutral wrapper around `PMF` or `WithTop`
    is part of the actual review surface, not a distinct source model.
    """

    scoped_type_aliases = semantic_type_aliases_in_namespace(
        type_aliases, context_namespace
    )
    expanded = normalize_ws(type_text)
    seen: set[str] = set()
    for _ in range(64):
        key = canonical_type(expanded)
        if key in seen:
            break
        seen.add(key)
        unfolded = unfold_proposition_aliases(expanded, proposition_aliases)
        unfolded = unfold_semantic_type_aliases(unfolded, scoped_type_aliases)
        if canonical_type(unfolded) == key:
            break
        expanded = unfolded
    return {
        "expanded_type": expanded,
        "alpha_normalized_type": abstract_free_identifiers(
            expanded, bound_names or set()
        ),
    }


def semantic_model_term_bound_names(
    text: str, *, declaration: LocalDeclaration | None = None
) -> set[str]:
    """Return local binders that must not be mistaken for Lean constructors.

    The source audit has no elaborated term AST here, so this deliberately
    handles the ordinary declaration, quantifier, lambda, and let forms.  It
    is used only to avoid a paper-local binder called ``PMF`` or ``Measure``
    manufacturing a model finding.  Failure to recognize an unusual binder
    remains conservative: it can add an audit obligation but never certify one.
    """

    names = set(quantified_binder_names(text))
    if declaration is not None:
        for visible_input in visible_inputs_from_declaration(
            declaration.source, include_result_inputs=False
        ):
            names.update(binder_names(str(visible_input.get("names") or "")))

    # This intentionally accepts only shallow lambda binders.  Nested and
    # pattern-matching forms are still bounded by the closure below; a missed
    # binder can create an extra review obligation, never erase one.
    lambda_pattern = re.compile(
        r"(?:\bfun\b|λ)\s+((?:(?:\([^()]*\))|[A-Za-z_][A-Za-z0-9_']*|\s)+)=>"
    )
    for match in lambda_pattern.finditer(text):
        binder_text = match.group(1).strip()
        spans = balanced_binder_spans(binder_text)
        if spans:
            for span in spans:
                names.update(_binder_identifiers(span))
        else:
            names.update(_binder_identifiers(binder_text))
    for match in re.finditer(
        r"\blet\s+(?:rec\s+)?([A-Za-z_][A-Za-z0-9_']*)", text
    ):
        names.add(match.group(1))
    return names


def semantic_model_term_free_surface(text: str, bound_names: set[str]) -> str:
    """Erase unqualified local binders before inspecting Lean term syntax."""

    surface = normalize_ws(text)
    for index, name in enumerate(sorted(bound_names)):
        # Do not rewrite a component of `Namespace.constant`: the namespace
        # qualification is semantic evidence, not a local variable occurrence.
        surface = re.sub(
            rf"(?<![\w'.]){re.escape(name)}(?![\w'.])",
            f"_termBound{index}",
            surface,
        )
    return surface


def semantic_model_standard_measure_kernel_carrier_type(type_text: str) -> bool:
    """Recognize an expanded standard Measure/Kernel carrier type surface."""

    normalized = strip_outer_group(normalize_ws(type_text))
    return bool(SEMANTIC_MODEL_STANDARD_MEASURE_KERNEL_CARRIER_TYPE_RE.match(normalized))


def semantic_model_measure_kernel_carrier_names(
    parameter_surfaces: list[dict[str, str]],
) -> set[str]:
    """Return binders whose expanded types establish a Measure/Kernel receiver."""

    names: set[str] = set()
    for surface in parameter_surfaces:
        type_text = str(surface.get("expanded_type") or "")
        if not semantic_model_standard_measure_kernel_carrier_type(type_text):
            continue
        names.update(binder_names(str(surface.get("names") or "")))
    return names


def semantic_model_measure_kernel_carrier_dot_transport_matches(
    text: str,
    known_measure_kernel_carrier_names: set[str] | None,
) -> list[re.Match[str]]:
    """Find transport dot calls whose receiver has a standard carrier type.

    This deliberately binds receiver spelling to a parameter's expanded type.
    It is therefore invariant under alpha-renaming a carrier binder, while a
    paper-local ``box.map`` or a namespace-qualified helper cannot manufacture
    the standard Measure/Kernel transport signal.
    """

    if not known_measure_kernel_carrier_names:
        return []
    return [
        match
        for match in SEMANTIC_MODEL_MEASURE_KERNEL_CARRIER_DOT_TRANSPORT_RE.finditer(
            text
        )
        if match.group("carrier") in known_measure_kernel_carrier_names
    ]


def semantic_model_term_construct_flags(
    text: str,
    *,
    known_measure_kernel_carrier_names: set[str] | None = None,
) -> dict[str, bool]:
    """Detect actual Lean probability/integration constructs in one term surface.

    The patterns intentionally name standard Lean mathematical constructors and
    notation only.  They do not inspect paper-local declaration spelling, so a
    local function called ``expectedUtility`` does not trigger this lane.
    """

    law = bool(SEMANTIC_MODEL_LAW_CONSTRUCT_RE.search(text))
    measure_kernel_carrier_transport = bool(
        SEMANTIC_MODEL_MEASURE_KERNEL_CARRIER_TRANSPORT_CONSTRUCT_RE.search(text)
    ) or bool(
        semantic_model_measure_kernel_carrier_dot_transport_matches(
            text, known_measure_kernel_carrier_names
        )
    )
    expectation = bool(SEMANTIC_MODEL_EXPECTATION_CONSTRUCT_RE.search(text))
    conditioning = bool(SEMANTIC_MODEL_CONDITIONING_CONSTRUCT_RE.search(text))
    extended = bool(re.search(r"\b(?:WithTop|WithBot|EReal|ENNReal)\b|ℝ≥0∞", text))
    finite_carrier = bool(re.search(r"\b(?:Fin|Fintype|Finite)\b", text))
    ordered = bool(
        re.search(r"[<≤>≥]", text)
        or re.search(r"\b(?:LT|LE|Preorder|PartialOrder|LinearOrder|Ord)\b", text)
    )
    finite_or_ordered_law = law and (finite_carrier or ordered)
    nontrivial_finite_index_expression = bool(
        re.search(
            r"\bFin\s*(?:\(\s*[^()\n]*(?:\+|Nat\.(?:succ|add))[^()\n]*\)|"
            r"[^\s,;)]*\s*\+\s*[^\s,;)]+)",
            text,
        )
    )
    return {
        "probability_law_construct": law,
        "measure_kernel_carrier_transport_construct": (
            measure_kernel_carrier_transport
        ),
        "integration_or_expectation_construct": expectation,
        "conditioning_or_partition_construct": conditioning,
        "extended_rate_construct": extended,
        "finite_carrier_construct": finite_carrier,
        "nontrivial_finite_index_expression_construct": (
            nontrivial_finite_index_expression
        ),
        "finite_or_ordered_probability_construct": finite_or_ordered_law,
        "model_semantics": law
        or measure_kernel_carrier_transport
        or expectation
        or conditioning,
    }


def semantic_model_term_fragments(
    text: str,
    *,
    known_measure_kernel_carrier_names: set[str] | None = None,
) -> list[dict[str, str]]:
    """Return bounded source fragments around semantic Lean constructs."""

    patterns = (
        ("probability_law_construct", SEMANTIC_MODEL_LAW_CONSTRUCT_RE),
        (
            "measure_kernel_carrier_transport_construct",
            SEMANTIC_MODEL_MEASURE_KERNEL_CARRIER_TRANSPORT_CONSTRUCT_RE,
        ),
        ("integration_or_expectation_construct", SEMANTIC_MODEL_EXPECTATION_CONSTRUCT_RE),
        ("conditioning_or_partition_construct", SEMANTIC_MODEL_CONDITIONING_CONSTRUCT_RE),
        (
            "extended_rate_construct",
            re.compile(r"\b(?:WithTop|WithBot|EReal|ENNReal)\b|ℝ≥0∞"),
        ),
    )
    fragments: list[dict[str, str]] = []
    seen: set[tuple[str, str]] = set()
    for construct, pattern in patterns:
        count = 0
        for match in pattern.finditer(text):
            start = max(0, match.start() - SEMANTIC_MODEL_TERM_FRAGMENT_MAX_CHARS // 2)
            end = min(len(text), match.end() + SEMANTIC_MODEL_TERM_FRAGMENT_MAX_CHARS // 2)
            fragment = normalize_ws(text[start:end])
            key = (construct, fragment)
            if not fragment or key in seen:
                continue
            seen.add(key)
            fragments.append({"construct": construct, "fragment": fragment})
            count += 1
            if count >= SEMANTIC_MODEL_TERM_FRAGMENT_MAX_PER_CONSTRUCT:
                break
    dot_transport_matches = semantic_model_measure_kernel_carrier_dot_transport_matches(
        text, known_measure_kernel_carrier_names
    )
    count = 0
    for match in dot_transport_matches:
        start = max(0, match.start() - SEMANTIC_MODEL_TERM_FRAGMENT_MAX_CHARS // 2)
        end = min(len(text), match.end() + SEMANTIC_MODEL_TERM_FRAGMENT_MAX_CHARS // 2)
        fragment = normalize_ws(text[start:end])
        key = ("measure_kernel_carrier_transport_construct", fragment)
        if not fragment or key in seen:
            continue
        seen.add(key)
        fragments.append(
            {
                "construct": "measure_kernel_carrier_transport_construct",
                "fragment": fragment,
            }
        )
        count += 1
        if count >= SEMANTIC_MODEL_TERM_FRAGMENT_MAX_PER_CONSTRUCT:
            break
    return fragments


def semantic_model_local_declaration_indexes(
    semantic_declarations: list[LocalDeclaration],
) -> tuple[dict[str, LocalDeclaration], dict[str, list[LocalDeclaration]]]:
    """Build stable local declaration indexes once per semantic review batch."""

    by_name = {declaration.name: declaration for declaration in semantic_declarations}
    by_short_name: dict[str, list[LocalDeclaration]] = {}
    for declaration in semantic_declarations:
        by_short_name.setdefault(declaration.name.rsplit(".", 1)[-1], []).append(
            declaration
        )
    for declarations in by_short_name.values():
        declarations.sort(key=lambda declaration: declaration.name)
    return by_name, by_short_name


def semantic_model_local_term_references(
    text: str,
    semantic_declarations: list[LocalDeclaration],
    *,
    context_namespace: str = "",
    shadowed_names: set[str] | None = None,
    declaration_index: dict[str, LocalDeclaration] | None = None,
    short_name_index: dict[str, list[LocalDeclaration]] | None = None,
) -> tuple[list[LocalDeclaration], list[dict[str, Any]]]:
    """Resolve paper-local transparent/opaque term heads without name heuristics.

    Imported constants are intentionally ignored here: their semantics belong
    to their typed interface or a checked bridge.  Ambiguous paper-local short
    heads are recorded rather than guessed, because guessing one namespace can
    erase a model dependency.
    """

    shadowed = shadowed_names or set()
    allowed_kinds = {"def", "abbrev", "opaque", "constant", "axiom"}
    if declaration_index is None or short_name_index is None:
        by_name, by_short_name = semantic_model_local_declaration_indexes(
            semantic_declarations
        )
    else:
        by_name = declaration_index
        by_short_name = short_name_index

    def resolve(head: str) -> LocalDeclaration | None:
        matches = lexical_name_candidates(
            head,
            set(by_name),
            context_namespace=context_namespace,
        )
        return by_name[matches[0]] if len(matches) == 1 else None

    found: list[LocalDeclaration] = []
    seen: set[str] = set()
    ambiguous: list[dict[str, Any]] = []
    seen_ambiguous: set[tuple[str, ...]] = set()
    for match in _PROPOSITION_ALIAS_IDENTIFIER_RE.finditer(text):
        head = match.group(1).lstrip("@")
        if not head or ("." not in head and head in shadowed):
            continue
        declaration = resolve(head)
        if declaration is not None:
            if declaration.kind in allowed_kinds and declaration.name not in seen:
                seen.add(declaration.name)
                found.append(declaration)
            continue
        if "." in head:
            continue
        candidates = [
            declaration.name
            for declaration in by_short_name.get(head, [])
            if declaration.kind in allowed_kinds
        ]
        if len(candidates) > 1:
            key = tuple(candidates)
            if key not in seen_ambiguous:
                seen_ambiguous.add(key)
                ambiguous.append(
                    {
                        "head": head,
                        "candidates": candidates,
                        "reason": "ambiguous_paper_local_term_head",
                    }
                )
    return found, ambiguous


def semantic_model_definition_signature_surface(
    declaration: LocalDeclaration,
    proposition_aliases: dict[str, PropositionAliasInfo],
    type_aliases: dict[str, TypeAliasInfo] | None,
) -> tuple[list[dict[str, str]], dict[str, str]]:
    """Render a local definition's parameter/result types for model review."""

    context_namespace = (
        declaration.name.rsplit(".", 1)[0] if "." in declaration.name else ""
    )
    parameter_surfaces: list[dict[str, str]] = []
    bound_names: set[str] = set()
    for visible_input in visible_inputs_from_declaration(
        declaration.source, include_result_inputs=False
    ):
        type_text = str(visible_input.get("type") or "")
        if not type_text:
            continue
        parameter_surfaces.append(
            {
                "names": normalize_ws(str(visible_input.get("names") or "")),
                **semantic_model_surface_type(
                    type_text,
                    proposition_aliases,
                    type_aliases,
                    context_namespace=context_namespace,
                    bound_names=bound_names,
                ),
            }
        )
        bound_names.update(binder_names(str(visible_input.get("names") or "")))
    return parameter_surfaces, semantic_model_surface_type(
        declaration_result_type(declaration.source),
        proposition_aliases,
        type_aliases,
        context_namespace=context_namespace,
        bound_names=bound_names,
    )


def semantic_model_terminal_definition_analysis(
    declaration: LocalDeclaration,
    semantic_declarations: list[LocalDeclaration],
    proposition_aliases: dict[str, PropositionAliasInfo],
    type_aliases: dict[str, TypeAliasInfo] | None,
    *,
    declaration_index: dict[str, LocalDeclaration],
    short_name_index: dict[str, list[LocalDeclaration]],
) -> dict[str, Any]:
    """Parse one local definition once for all reviewed terminal closures.

    The returned data has no row-specific path or relevance state.  Callers
    copy the node before attaching their own dependency chain, which keeps a
    shared imported definition's source digest stable while avoiding repeated
    scans of the same body for every paper-facing row.
    """

    parameter_surfaces, result_surface = semantic_model_definition_signature_surface(
        declaration, proposition_aliases, type_aliases
    )
    measure_kernel_carrier_names = semantic_model_measure_kernel_carrier_names(
        parameter_surfaces
    )
    body = declaration_body_text(declaration.source)
    body_bound_names = semantic_model_term_bound_names(body, declaration=declaration)
    inspectable_body = bool(body) and not re.match(r"^by\b", body.strip())
    body_surface = (
        semantic_model_term_free_surface(body, body_bound_names)
        if inspectable_body
        else ""
    )
    signature_surface = "\n".join(
        [
            *(surface["alpha_normalized_type"] for surface in parameter_surfaces),
            result_surface["alpha_normalized_type"],
        ]
    )
    semantic_surface = "\n".join(
        part for part in (signature_surface, body_surface) if part
    )
    context_namespace = (
        declaration.name.rsplit(".", 1)[0] if "." in declaration.name else ""
    )
    references: list[LocalDeclaration] = []
    ambiguous: list[dict[str, Any]] = []
    if inspectable_body:
        references, ambiguous = semantic_model_local_term_references(
            body,
            semantic_declarations,
            context_namespace=context_namespace,
            shadowed_names=body_bound_names,
            declaration_index=declaration_index,
            short_name_index=short_name_index,
        )
    return {
        "node": {
            "declaration": declaration.name,
            "kind": declaration.kind,
            "source_file": declaration.source_file,
            "line": declaration.line,
            "declaration_sha256": hashlib.sha256(
                normalize_ws(declaration.source).encode("utf-8")
            ).hexdigest(),
            "body_sha256": hashlib.sha256(
                normalize_ws(body).encode("utf-8")
            ).hexdigest(),
            "parameter_types": parameter_surfaces,
            "result_type": result_surface,
            "semantic_construct_flags": semantic_model_term_construct_flags(
                semantic_surface,
                known_measure_kernel_carrier_names=measure_kernel_carrier_names,
            ),
            "semantic_fragments": semantic_model_term_fragments(
                semantic_surface,
                known_measure_kernel_carrier_names=measure_kernel_carrier_names,
            ),
            "body_surface_inspectable": inspectable_body,
            "direct_local_dependencies": sorted(
                reference.name for reference in references
            ),
        },
        "references": references,
        "ambiguous": ambiguous,
    }


def semantic_model_terminal_term_dependency_surface(
    terminal_result_text: str,
    semantic_declarations: list[LocalDeclaration],
    proposition_aliases: dict[str, PropositionAliasInfo],
    type_aliases: dict[str, TypeAliasInfo] | None,
    *,
    context_namespace: str = "",
    initial_bound_names: set[str] | None = None,
    initial_measure_kernel_carrier_names: set[str] | None = None,
    max_depth: int = SEMANTIC_MODEL_TERM_DEPENDENCY_MAX_DEPTH,
    max_nodes: int = SEMANTIC_MODEL_TERM_DEPENDENCY_MAX_NODES,
    declaration_index: dict[str, LocalDeclaration] | None = None,
    short_name_index: dict[str, list[LocalDeclaration]] | None = None,
    definition_analysis_cache: dict[str, dict[str, Any]] | None = None,
) -> dict[str, Any]:
    """Expose a bounded transparent-definition closure from a theorem result.

    The terminal proposition may be syntactically only ``score < score'``.
    When either score is a paper-local transparent definition, inspect its
    signature and value body, then recursively inspect local transparent
    definitions it reaches.  Opaque/axiom/constant heads, tactic-mode bodies,
    ambiguous local resolution, and traversal bounds are fail-closed: they are
    retained as a semantic bridge requirement rather than treated as ordinary
    real-valued terms.
    """

    if max_depth < 0 or max_nodes < 1:
        raise ValueError("semantic term dependency limits must be nonnegative/nonzero")
    if declaration_index is None or short_name_index is None:
        declaration_index, short_name_index = semantic_model_local_declaration_indexes(
            semantic_declarations
        )
    if definition_analysis_cache is None:
        definition_analysis_cache = {}

    root_bound_names = set(initial_bound_names or set())
    root_bound_names.update(semantic_model_term_bound_names(terminal_result_text))
    root_surface = semantic_model_term_free_surface(
        terminal_result_text, root_bound_names
    )
    root_flags = semantic_model_term_construct_flags(
        root_surface,
        known_measure_kernel_carrier_names=initial_measure_kernel_carrier_names,
    )
    root_fragments = semantic_model_term_fragments(
        root_surface,
        known_measure_kernel_carrier_names=initial_measure_kernel_carrier_names,
    )
    root_references, root_ambiguous = semantic_model_local_term_references(
        terminal_result_text,
        semantic_declarations,
        context_namespace=context_namespace,
        shadowed_names=root_bound_names,
        declaration_index=declaration_index,
        short_name_index=short_name_index,
    )

    nodes: dict[str, dict[str, Any]] = {}
    edges: dict[str, set[str]] = {"__terminal_result__": set()}
    reverse_edges: dict[str, set[str]] = {}
    unexpanded: dict[tuple[str, str], dict[str, Any]] = {}
    incomplete_reasons: list[dict[str, Any]] = []
    queue: list[tuple[LocalDeclaration, list[str], int, str]] = []

    def add_reverse_edge(parent: str, child: str) -> None:
        edges.setdefault(parent, set()).add(child)
        reverse_edges.setdefault(child, set()).add(parent)

    def add_unexpanded(
        declaration: LocalDeclaration | None,
        *,
        reason: str,
        chain: list[str],
        parent: str,
        candidates: list[str] | None = None,
    ) -> None:
        name = declaration.name if declaration is not None else "<ambiguous>"
        key = (name, reason)
        payload = {
            "declaration": name,
            "kind": declaration.kind if declaration is not None else "ambiguous",
            "reason": reason,
            "dependency_chain": chain,
            "referenced_from": parent,
        }
        if declaration is not None:
            payload.update(
                {
                    "source_file": declaration.source_file,
                    "line": declaration.line,
                    "declaration_sha256": hashlib.sha256(
                        normalize_ws(declaration.source).encode("utf-8")
                    ).hexdigest(),
                }
            )
        if candidates:
            payload["candidates"] = sorted(candidates)
        unexpanded.setdefault(key, payload)

    def enqueue_reference(
        declaration: LocalDeclaration,
        *,
        chain: list[str],
        depth: int,
        parent: str,
    ) -> None:
        if declaration.kind in {"opaque", "constant", "axiom"}:
            add_unexpanded(
                declaration,
                reason="unexpanded_local_opaque_term_head",
                chain=[*chain, declaration.name],
                parent=parent,
            )
            return
        if declaration.name in nodes or any(
            queued.name == declaration.name for queued, _, _, _ in queue
        ):
            add_reverse_edge(parent, declaration.name)
            return
        if len(nodes) + len(queue) >= max_nodes:
            incomplete_reasons.append(
                {
                    "reason": "max_nodes_reached",
                    "max_nodes": max_nodes,
                    "dependency_chain": [*chain, declaration.name],
                    "referenced_from": parent,
                }
            )
            add_unexpanded(
                declaration,
                reason="terminal_term_dependency_max_nodes",
                chain=[*chain, declaration.name],
                parent=parent,
            )
            return
        add_reverse_edge(parent, declaration.name)
        queue.append((declaration, [*chain, declaration.name], depth, parent))

    for ambiguous in root_ambiguous:
        add_unexpanded(
            None,
            reason=str(ambiguous["reason"]),
            chain=[],
            parent="__terminal_result__",
            candidates=list(ambiguous["candidates"]),
        )
    for reference in root_references:
        enqueue_reference(
            reference,
            chain=[],
            depth=1,
            parent="__terminal_result__",
        )

    while queue:
        declaration, chain, depth, _parent = queue.pop(0)
        if declaration.name in nodes:
            continue
        analysis = definition_analysis_cache.get(declaration.name)
        if analysis is None:
            analysis = semantic_model_terminal_definition_analysis(
                declaration,
                semantic_declarations,
                proposition_aliases,
                type_aliases,
                declaration_index=declaration_index,
                short_name_index=short_name_index,
            )
            definition_analysis_cache[declaration.name] = analysis
        node = {**analysis["node"], "dependency_chain": chain}
        nodes[declaration.name] = node
        if not bool(node["body_surface_inspectable"]):
            add_unexpanded(
                declaration,
                reason="transparent_definition_tactic_body_requires_bridge",
                chain=chain,
                parent=declaration.name,
            )
            continue

        node_references = list(analysis["references"])
        node_ambiguous = list(analysis["ambiguous"])
        for ambiguous in node_ambiguous:
            add_unexpanded(
                None,
                reason=str(ambiguous["reason"]),
                chain=chain,
                parent=declaration.name,
                candidates=list(ambiguous["candidates"]),
            )
        if depth >= max_depth and node_references:
            incomplete_reasons.append(
                {
                    "reason": "max_depth_reached",
                    "max_depth": max_depth,
                    "dependency_chain": chain,
                    "referenced_from": declaration.name,
                }
            )
            for reference in node_references:
                add_unexpanded(
                    reference,
                    reason="terminal_term_dependency_max_depth",
                    chain=[*chain, reference.name],
                    parent=declaration.name,
                )
            continue
        for reference in node_references:
            enqueue_reference(
                reference,
                chain=chain,
                depth=depth + 1,
                parent=declaration.name,
            )

    relevant = {
        name
        for name, node in nodes.items()
        if bool(node["semantic_construct_flags"]["model_semantics"])
        or bool(node["semantic_construct_flags"]["extended_rate_construct"])
    }
    for item in unexpanded.values():
        parent = str(item.get("referenced_from") or "")
        if parent in nodes:
            relevant.add(parent)
    if incomplete_reasons:
        for item in incomplete_reasons:
            parent = str(item.get("referenced_from") or "")
            if parent in nodes:
                relevant.add(parent)
    pending = list(relevant)
    while pending:
        child = pending.pop()
        for parent in reverse_edges.get(child, set()):
            if parent == "__terminal_result__" or parent in relevant:
                continue
            relevant.add(parent)
            pending.append(parent)
    for name, node in nodes.items():
        node["semantic_relevant"] = name in relevant

    all_flags = [root_flags, *(node["semantic_construct_flags"] for node in nodes.values())]
    aggregate_flags = {
        key: any(bool(flags.get(key)) for flags in all_flags)
        for key in (
            "probability_law_construct",
            "measure_kernel_carrier_transport_construct",
            "integration_or_expectation_construct",
            "conditioning_or_partition_construct",
            "extended_rate_construct",
            "finite_carrier_construct",
            "nontrivial_finite_index_expression_construct",
            "finite_or_ordered_probability_construct",
            "model_semantics",
        )
    }
    return {
        "schema": 1,
        "scan_complete": not incomplete_reasons,
        "scan_limits": {"max_depth": max_depth, "max_nodes": max_nodes},
        "incomplete_reasons": incomplete_reasons,
        "terminal_result_semantic_construct_flags": root_flags,
        "terminal_result_semantic_fragments": root_fragments,
        "transparent_definitions": [nodes[name] for name in sorted(nodes)],
        "unexpanded_local_term_heads": [
            unexpanded[key] for key in sorted(unexpanded)
        ],
        "semantic_construct_flags": aggregate_flags,
    }


def semantic_model_unexpanded_local_type_heads(
    typed_surfaces: list[tuple[str, str]],
    declarations: list[LocalDeclaration],
) -> list[dict[str, Any]]:
    """Expose local opaque type heads that static expansion cannot inspect.

    A transparent `def`/`abbrev` is expanded above.  In contrast, a locally
    declared `opaque`, `constant`, or `axiom` of sort `Type` can conceal a
    probability model behind an arbitrary neutral spelling.  The semantic lane
    cannot safely infer that the support/process/rate checks are inapplicable,
    so it records the head and forces those dimensions for human/Lean review.
    """

    type_level_declarations = [
        declaration
        for declaration in declarations
        if declaration.kind in {"opaque", "constant", "axiom"}
        and declaration_returns_sort(declaration)
    ]
    if not type_level_declarations:
        return []
    found: dict[str, dict[str, Any]] = {}
    for surface, context_namespace in typed_surfaces:
        for match in _PROPOSITION_ALIAS_IDENTIFIER_RE.finditer(surface):
            declaration = resolve_local_declaration_head(
                match.group(1).lstrip("@"),
                type_level_declarations,
                context_namespace=context_namespace,
            )
            if declaration is None:
                continue
            found.setdefault(
                declaration.name,
                {
                    "declaration": declaration.name,
                    "kind": declaration.kind,
                    "source_file": declaration.source_file,
                    "line": declaration.line,
                },
            )
    return [found[name] for name in sorted(found)]


def semantic_model_elaborated_execution_state_refinement_shape(
    manifest: Mapping[str, Any] | None,
) -> dict[str, bool]:
    """Read Lean's bounded execution/refinement shape without local names.

    ``lean_signature_manifest`` computes this from the reviewed declaration's
    Lean-owned statement dependency graph. A structural path operator and an
    endorelation-valued transition must both occur. The historical
    ``has_refl_trans_gen_path`` label remains for receipt compatibility; schema
    2 does not match that declaration or any row, field, theorem, or function
    name.
    A malformed or unavailable manifest is handled by the enclosing
    elaboration error lane; this projection stays conservative for direct
    callers and test fixtures.
    """

    raw = (
        manifest.get("elaborated_execution_state_refinement_shape")
        if isinstance(manifest, Mapping)
        else None
    )
    if not isinstance(raw, Mapping) or raw.get("schema") not in {1, 2}:
        return {
            "elaborated_execution_state_refinement_surface": False,
            "elaborated_execution_state_refinement_scan_incomplete": False,
        }
    if raw.get("schema") == 2 and raw.get("detector_basis") != (
        "lean_statement_dependency_graph_structural_v1"
    ):
        return {
            "elaborated_execution_state_refinement_surface": False,
            "elaborated_execution_state_refinement_scan_incomplete": False,
        }
    scan_complete = raw.get("scan_complete")
    has_path = raw.get("has_refl_trans_gen_path")
    has_transition = raw.get("has_relation_valued_state_transition")
    detected = raw.get("detected")
    if not all(
        isinstance(value, bool)
        for value in (scan_complete, has_path, has_transition, detected)
    ):
        return {
            "elaborated_execution_state_refinement_surface": False,
            "elaborated_execution_state_refinement_scan_incomplete": False,
        }
    if detected != (scan_complete and has_path and has_transition):
        # The producer validates this invariant before a manifest reaches the
        # audit pipeline. Keep this direct helper equally fail-closed so a
        # malformed fixture or future caller cannot turn contradictory flags
        # into a semantic obligation.
        return {
            "elaborated_execution_state_refinement_surface": False,
            "elaborated_execution_state_refinement_scan_incomplete": False,
        }
    return {
        "elaborated_execution_state_refinement_surface": (
            bool(scan_complete) and bool(has_path) and bool(has_transition)
        ),
        # A bounded Lean-owned scan that could not finish cannot certify that
        # no state evolution is present.  Keep the joint-law review fail
        # closed without pretending the concrete paired shape was detected.
        "elaborated_execution_state_refinement_scan_incomplete": (
            not bool(scan_complete)
        ),
    }


def semantic_model_aggregate_execution_state_refinement_shape(
    manifests: Iterable[Mapping[str, Any]],
) -> dict[str, Any]:
    """Aggregate exact reachable record manifests for one source-facing row.

    A theorem can receive its run witness and transition rule through distinct
    but structurally reachable records.  The route remains one semantic model
    surface, so pair the Lean-elaborated path and relation shapes across those
    exact records.  This aggregates only generated manifest booleans; it never
    uses the names of the records or their fields as evidence.
    """

    shapes: list[Mapping[str, Any]] = []
    for manifest in manifests:
        raw = manifest.get("elaborated_execution_state_refinement_shape")
        if not isinstance(raw, Mapping) or raw.get("schema") not in {1, 2}:
            continue
        if raw.get("schema") == 2 and raw.get("detector_basis") != (
            "lean_statement_dependency_graph_structural_v1"
        ):
            continue
        if not all(
            isinstance(raw.get(field), bool)
            for field in (
                "scan_complete",
                "has_refl_trans_gen_path",
                "has_relation_valued_state_transition",
                "detected",
            )
        ):
            continue
        if raw["detected"] != (
            raw["scan_complete"]
            and raw["has_refl_trans_gen_path"]
            and raw["has_relation_valued_state_transition"]
        ):
            continue
        shapes.append(raw)
    if not shapes:
        return {}
    scan_complete = all(bool(shape["scan_complete"]) for shape in shapes)
    has_path = any(bool(shape["has_refl_trans_gen_path"]) for shape in shapes)
    has_transition = any(
        bool(shape["has_relation_valued_state_transition"]) for shape in shapes
    )
    schema = max(int(shape["schema"]) for shape in shapes)
    summary: dict[str, Any] = {
        "schema": schema,
        "scan_complete": scan_complete,
        "has_refl_trans_gen_path": has_path,
        "has_relation_valued_state_transition": has_transition,
        "detected": scan_complete and has_path and has_transition,
    }
    if schema == 2:
        summary["detector_basis"] = (
            "lean_statement_dependency_graph_structural_v1"
        )
    return summary


def semantic_model_feature_flags(
    binder_domains: list[dict[str, str]],
    terminal_result: dict[str, str],
    record_fields: list[dict[str, str]],
    record_parameters: list[dict[str, str]],
    unexpanded_local_type_heads: list[dict[str, Any]] | None = None,
    terminal_term_dependency_surface: dict[str, Any] | None = None,
    elaborated_execution_state_refinement_shape: Mapping[str, Any] | None = None,
) -> dict[str, bool]:
    """Detect semantic type/term shapes without consulting paper-local names.

    The flags are review hints, not verdicts. They only use elaborated-type
    constructors and logical/order notation. A paper-local theorem, function,
    binder, field, or record name cannot remove an obligation by being renamed.
    The schema-2 probability-semantics checks are construct-sensitive.  A
    conditioning/partition construct reaches the calibration and null-cell
    checks; an integration/expectation construct reaches the definedness
    check.  An opaque or incomplete local type/term path reaches all three,
    because the static audit cannot safely establish that any is inapplicable.
    A bare expanded PMF/Measure type still receives the ordinary law-surface
    checks, but does not by itself manufacture those narrower obligations.
    The bounded terminal term closure contributes only standard Lean
    law/integration constructs or an explicit incomplete/opaque path, never
    local declaration spelling.
    """

    all_types = [
        item["alpha_normalized_type"]
        for item in [
            *binder_domains,
            terminal_result,
            *record_parameters,
            *record_fields,
        ]
        if item.get("alpha_normalized_type")
    ]
    joined = "\n".join(all_types)
    carrier_text = "\n".join(
        item.get("alpha_normalized_type", "")
        for item in [*binder_domains, *record_parameters]
    )
    generic_carrier = bool(
        re.search(r"(?:^|\s)(?:Type|Sort)(?:\*|\b)", carrier_text)
    )
    restricted_carrier = bool(
        re.search(r"\b(?:Fin|Fintype|Finite|Subtype)\b", joined)
    )
    # `Subtype` can be an infinite restricted domain.  It still requires the
    # ordinary carrier/domain bridge, but it is not by itself evidence that a
    # source cardinality threshold has a finite boundary case.
    finite_carrier = bool(re.search(r"\b(?:Fin|Fintype|Finite)\b", joined))
    # This looks only at expanded type constructors and index expressions.  A
    # source cardinal parameter hidden behind a local name must still receive
    # the ordinary carrier bridge; visible nontrivial `Fin` arithmetic also
    # requires an explicit parameter-translation explanation.
    nontrivial_finite_index_expression = bool(
        re.search(
            r"\bFin\s*(?:\(\s*[^()\n]*(?:\+|Nat\.(?:succ|add))[^()\n]*\)|"
            r"[^\s,;)]*\s*\+\s*[^\s,;)]+)",
            carrier_text,
        )
    )
    probabilistic = bool(
        re.search(
            r"\b(?:PMF|Measure|ProbabilityTheory|Kernel|MarkovKernel|"
            r"ProbabilityMeasure)\b",
            joined,
        )
    )
    ordered = bool(
        re.search(r"[<≤>≥]", joined)
        or re.search(
            r"\b(?:LT|LE|Preorder|PartialOrder|LinearOrder|Ord)\b", joined
        )
    )
    extended = bool(
        re.search(r"\b(?:WithTop|WithBot|EReal|ENNReal)\b|ℝ≥0∞", joined)
    )
    unexpanded_local_type_surface = bool(unexpanded_local_type_heads)
    term_surface = terminal_term_dependency_surface or {}
    term_construct_flags = term_surface.get("semantic_construct_flags")
    if not isinstance(term_construct_flags, dict):
        term_construct_flags = {}
    terminal_term_model_surface = bool(
        term_construct_flags.get("model_semantics")
    )
    terminal_term_measure_kernel_carrier_transport_surface = bool(
        term_construct_flags.get("measure_kernel_carrier_transport_construct")
    )
    terminal_term_expectation_surface = bool(
        term_construct_flags.get("integration_or_expectation_construct")
    )
    terminal_term_conditioning_surface = bool(
        term_construct_flags.get("conditioning_or_partition_construct")
    )
    terminal_term_extended_rate_surface = bool(
        term_construct_flags.get("extended_rate_construct")
    )
    terminal_term_finite_or_ordered_probability_surface = bool(
        term_construct_flags.get("finite_or_ordered_probability_construct")
    )
    terminal_term_finite_carrier_surface = bool(
        term_construct_flags.get("finite_carrier_construct")
    )
    terminal_term_nontrivial_finite_index_surface = bool(
        term_construct_flags.get("nontrivial_finite_index_expression_construct")
    )
    unexpanded_local_term_surface = bool(
        term_surface.get("unexpanded_local_term_heads")
        or term_surface.get("incomplete_reasons")
        or term_surface.get("scan_complete") is False
    )
    probabilistic = probabilistic or terminal_term_model_surface
    extended = extended or terminal_term_extended_rate_surface
    opaque_or_incomplete_model_path = (
        unexpanded_local_type_surface or unexpanded_local_term_surface
    )
    execution_state_refinement = (
        semantic_model_elaborated_execution_state_refinement_shape(
            elaborated_execution_state_refinement_shape
        )
    )
    return {
        "generic_or_restricted_carrier": generic_carrier
        or restricted_carrier
        or unexpanded_local_type_surface
        or terminal_term_finite_carrier_surface,
        # Keep the finite-carrier trigger distinct from the broader carrier
        # bridge: only this structural shape needs an explicit small-cardinality
        # boundary analysis.  It is derived from type constructors, never a
        # declaration or function name.
        "finite_carrier": finite_carrier or terminal_term_finite_carrier_surface,
        "probabilistic_model": probabilistic,
        # Require both an expanded probabilistic surface and a standard
        # Measure/Kernel transport reached through the terminal definition
        # closure. A bare Measure type, or a paper-local function called
        # `map`, cannot create this obligation.
        "measure_kernel_carrier_transport_construct": (
            probabilistic
            and terminal_term_measure_kernel_carrier_transport_surface
        ),
        "finite_or_ordered_probability_domain": probabilistic
        and (
            restricted_carrier
            or ordered
            or terminal_term_finite_or_ordered_probability_surface
        ),
        "nontrivial_finite_index_expression": (
            nontrivial_finite_index_expression
            or terminal_term_nontrivial_finite_index_surface
        ),
        "extended_rate_codomain": extended,
        "unexpanded_local_type_surface": unexpanded_local_type_surface,
        "terminal_term_model_surface": terminal_term_model_surface,
        "terminal_term_measure_kernel_carrier_transport_surface": (
            terminal_term_measure_kernel_carrier_transport_surface
        ),
        "terminal_term_expectation_surface": terminal_term_expectation_surface,
        "terminal_term_conditioning_surface": terminal_term_conditioning_surface,
        "terminal_term_extended_rate_surface": terminal_term_extended_rate_surface,
        "terminal_term_finite_carrier_surface": terminal_term_finite_carrier_surface,
        "unexpanded_local_term_surface": unexpanded_local_term_surface,
        "elaborated_execution_state_refinement_surface": (
            execution_state_refinement[
                "elaborated_execution_state_refinement_surface"
            ]
        ),
        "elaborated_execution_state_refinement_scan_incomplete": (
            execution_state_refinement[
                "elaborated_execution_state_refinement_scan_incomplete"
            ]
        ),
        # These are terminal-construct obligations, not declaration-name or
        # broad probability-type heuristics. A transparent PMF/Measure type
        # alone does not establish that a row conditions, partitions, or takes
        # an expectation. Conversely, an opaque/incomplete local path remains
        # fail-closed because any of those constructs may be hidden there.
        "conditioning_and_calibration_semantics": (
            terminal_term_conditioning_surface or opaque_or_incomplete_model_path
        ),
        "expectation_definedness": (
            terminal_term_expectation_surface or opaque_or_incomplete_model_path
        ),
        "null_cell_totalization_and_partition_scope": (
            terminal_term_conditioning_surface or opaque_or_incomplete_model_path
        ),
    }


def semantic_model_dimension_shape_basis(
    dimension: str, flags: dict[str, bool]
) -> list[str]:
    """Describe type/term structural triggers without local-name inference.

    The basis is included in the generated item so an LLM/human cannot explain
    a match solely by a theorem, wrapper, field, or function name.  It is not a
    proof of fidelity; it says which alpha-normalized type or transparent-term
    shape made the comparison mandatory.
    """

    if dimension == "expanded_binders_and_domain":
        return ["expanded binder/result type surface"]
    if dimension == "carrier_and_domain":
        basis: list[str] = []
        if flags["generic_or_restricted_carrier"]:
            basis.append("generic, finite, subtype, or opaque carrier surface")
        if flags["finite_carrier"]:
            basis.append("expanded finite carrier requiring boundary-case review")
        if flags["nontrivial_finite_index_expression"]:
            basis.append("finite carrier with nontrivial index arithmetic")
        if flags["unexpanded_local_type_surface"]:
            basis.append("unexpanded local opaque/constant/axiom type surface")
        return basis
    if dimension == "probability_support_endpoints":
        basis: list[str] = []
        if flags["finite_or_ordered_probability_domain"]:
            basis.append("expanded probability-law type with finite or ordered carrier")
        if flags["terminal_term_model_surface"] and flags[
            "finite_or_ordered_probability_domain"
        ]:
            basis.append(
                "transparent terminal definition closure with finite or ordered probability construct"
            )
        return basis
    if dimension == "joint_law_and_state_evolution":
        basis: list[str] = []
        if flags["elaborated_execution_state_refinement_surface"]:
            basis.append(
                "Lean-elaborated ReflTransGen execution path with a relation-valued state transition"
            )
        if flags["elaborated_execution_state_refinement_scan_incomplete"]:
            basis.append(
                "bounded Lean execution/state-refinement scan was incomplete"
            )
        if flags["probabilistic_model"]:
            basis.append("expanded probability-law type surface")
        if flags["unexpanded_local_type_surface"]:
            basis.append(
                "unexpanded local opaque/constant/axiom type surface requiring a law refinement review"
            )
        if flags["terminal_term_model_surface"]:
            basis.append(
                "transparent terminal definition closure with probability or integration construct"
            )
        if flags["measure_kernel_carrier_transport_construct"]:
            basis.append(
                "transparent terminal definition closure with standard Measure/Kernel carrier transport"
            )
        if flags["unexpanded_local_term_surface"]:
            basis.append(
                "unexpanded or bounded terminal definition path requiring a semantic bridge"
            )
        return basis
    if dimension == "conditioning_and_calibration_semantics":
        basis = []
        if flags["unexpanded_local_type_surface"]:
            basis.append("unexpanded local opaque/constant/axiom type surface")
        if flags["terminal_term_conditioning_surface"]:
            basis.append(
                "transparent terminal definition closure with conditioning or partition construct"
            )
        if flags["unexpanded_local_term_surface"]:
            basis.append(
                "unexpanded or bounded terminal definition path requiring a semantic bridge"
            )
        return basis
    if dimension == "expectation_definedness":
        basis = []
        if flags["unexpanded_local_type_surface"]:
            basis.append("unexpanded local opaque/constant/axiom type surface")
        if flags["terminal_term_expectation_surface"]:
            basis.append(
                "transparent terminal definition closure with integration or expectation construct"
            )
        if flags["unexpanded_local_term_surface"]:
            basis.append(
                "unexpanded or bounded terminal definition path requiring a semantic bridge"
            )
        return basis
    if dimension == "null_cell_totalization_and_partition_scope":
        basis = []
        if flags["unexpanded_local_type_surface"]:
            basis.append("unexpanded local opaque/constant/axiom type surface")
        if flags["terminal_term_conditioning_surface"]:
            basis.append(
                "transparent terminal definition closure with conditioning or partition construct"
            )
        if flags["unexpanded_local_term_surface"]:
            basis.append(
                "unexpanded or bounded terminal definition path requiring a semantic bridge"
            )
        return basis
    if dimension == "extended_rate_codomain":
        basis = []
        if flags["extended_rate_codomain"]:
            basis.append("expanded extended-rate codomain surface")
        if flags["terminal_term_extended_rate_surface"]:
            basis.append("transparent terminal definition closure with extended-rate construct")
        return basis
    return []


def semantic_contract_fully_qualified_identity(value: object) -> str:
    """Return a usable fully-qualified Lean declaration identity or ``""``.

    Semantic-contract pairing is a source-map capability, not a navigation
    convenience.  In particular, a common final component such as ``result``
    must never pair two review rows from different namespaces.  The statement
    map validator owns the complete Lean-name grammar; this narrower check is
    deliberately conservative and makes an incomplete identity unusable here.
    """

    identity = str(value or "").strip()
    if "." not in identity:
        return ""
    if not re.fullmatch(LEAN_QUALIFIED_NAME_PATTERN, identity):
        return ""
    return identity


def source_claim_atoms_contract_present(statement_map: Mapping[str, Any] | None) -> bool:
    """Whether a map attempted to use the source-claim-atom contract.

    This is intentionally a map-shape check, not a theorem-name heuristic. A
    malformed opt-in remains visible so a legacy parent route cannot quietly
    substitute for a missing atom inventory.
    """

    if not isinstance(statement_map, Mapping):
        return False
    if SOURCE_CLAIM_ATOMS_SCHEMA_KEY in statement_map:
        return True
    raw_items = statement_map.get("items")
    return isinstance(raw_items, Mapping) and any(
        isinstance(item, Mapping) and SOURCE_CLAIM_ATOMS_KEY in item
        for item in raw_items.values()
    )


def source_claim_atoms_contract_enabled(statement_map: Mapping[str, Any] | None) -> bool:
    """Whether the exact versioned atom contract is active."""

    if not isinstance(statement_map, Mapping):
        return False
    schema = statement_map.get(SOURCE_CLAIM_ATOMS_SCHEMA_KEY)
    return (
        isinstance(schema, int)
        and not isinstance(schema, bool)
        and schema == SOURCE_CLAIM_ATOMS_SCHEMA
    )


def source_claim_atom_authoritative_for_item(
    statement_map: Mapping[str, Any] | None, source_item: Mapping[str, Any]
) -> bool:
    """Whether attempted atom metadata blocks legacy parent-route fallback.

    A malformed atom opt-in is still authoritative for this negative purpose:
    it must surface a route/schema error rather than quietly recover Spec
    coverage from an older parent contract.  The exact versioned schema is
    separately required before an atom route can gain a Spec companion.
    """

    # Support-only entries and quarantined false source statements stay in the
    # source inventory and can retain checked support declarations, but they do
    # not state a proved paper result through this direct source-to-Spec lane.
    # Use the shared route policy rather than inferring an obligation from a
    # theorem-like presentation label alone.
    route_policy = source_item_effective_route_policy(source_item)
    if bool(route_policy["is_support_only"]) or bool(
        route_policy["is_quarantined_source_defect"]
    ) or bool(
        route_policy["is_source_declared_open_nonresult"]
    ):
        return False

    # The normal atom obligation remains theorem-like: a plain source
    # definition does not become a theorem-realization obligation merely
    # because another item enabled the map-wide atom schema.  A source map may
    # nevertheless explicitly bind a definition-level atom to a transparent
    # Spec (for example, when that definition supplies material nodes of a
    # strict v11 occurrence closure).  Honor that explicit source-first
    # binding, including malformed payloads that must fail closed below.
    source_kind = str(source_item.get("source_kind") or "").strip().lower()
    explicitly_atomized = SOURCE_CLAIM_ATOMS_KEY in source_item
    return bool(
        source_claim_atoms_contract_present(statement_map)
        and (
            source_kind in SOURCE_CLAIM_ATOM_THEOREM_LIKE_KINDS
            or explicitly_atomized
        )
    )


def source_claim_atom_contract_errors(
    statement_map: Mapping[str, Any] | None,
) -> list[str]:
    """Return versioning errors before an atom route can receive source credit."""

    if not source_claim_atoms_contract_present(statement_map):
        return []
    if not isinstance(statement_map, Mapping):
        return ["source-claim atom contract has no readable source map"]
    schema = statement_map.get(SOURCE_CLAIM_ATOMS_SCHEMA_KEY)
    if (
        not isinstance(schema, int)
        or isinstance(schema, bool)
        or schema != SOURCE_CLAIM_ATOMS_SCHEMA
    ):
        return [
            "source-claim atom contract requires top-level "
            f"{SOURCE_CLAIM_ATOMS_SCHEMA_KEY}: {SOURCE_CLAIM_ATOMS_SCHEMA}"
        ]
    return []


def source_coverage_review_rows(
    paper_dir: Path,
    configured_present: list[str],
    qualified_row_refs: dict[str, str],
) -> tuple[list[str], dict[str, Any], dict[str, Any]]:
    """Select configured source-record rows from the source coverage policy.

    The selection is source-map-route based.  A selected source item contributes
    only the exact direct/Spec declarations it explicitly routes to; neither
    map keys nor Lean declaration spelling can manufacture a review target.
    In ordinary mode this deliberately leaves figures, captions, examples,
    remarks, and general prose to the explicit deep-paper mode.
    """

    statement_map = load_json_object(paper_dir / "audit" / "paper_statement_map.json")
    raw_items = statement_map.get("items") if isinstance(statement_map, dict) else None
    mode, mode_error = source_coverage_mode_from_map(statement_map)
    if not isinstance(raw_items, dict):
        # A missing source map must not silently make the review surface empty.
        # Retain the configured rows and surface the configuration problem.
        return (
            list(configured_present),
            statement_map,
            {
                "source_coverage_mode": mode,
                "source_coverage_mode_error": mode_error,
                "source_coverage_selected_source_items": [],
                "source_coverage_validated_vocabulary_binding_source_items": [],
                "source_coverage_validated_vocabulary_direct_route_source_items": [],
                "source_coverage_unrouted_source_items": [],
                "source_coverage_route_errors": [],
                "out_of_mode_review_surface_rows": [],
                "source_coverage_selection_error": (
                    "paper_statement_map.json has no items object; retained the "
                    "configured review surface rather than silently omitting rows"
                ),
            },
        )

    presentation_aliases, presentation_alias_errors = source_presentation_aliases(
        raw_items
    )
    (
        vocabulary_definition_binding_item_ids,
        prose_definition_inventory_errors,
    ) = source_vocabulary_definition_binding_item_ids(
        paper_dir,
        statement_map,
        repository_root=REPOSITORY_ROOT,
    )
    indexed_item_ids = source_index_byte_pinned_anchor_item_ids(
        paper_dir,
        statement_map,
        mode,
        repository_root=REPOSITORY_ROOT,
    )
    selected_items = filter_source_map_items_for_proof_obligations(
        raw_items,
        mode,
        declared_environment_kinds=source_named_result_environment_kinds_from_map(
            statement_map
        ),
        additional_selected_item_ids=indexed_item_ids,
    )
    # The source-only vocabulary lane is intentionally narrower than the
    # general byte-indexed presentation selector.  It contributes an opaque
    # source-item identity only after its independent source-domain binding
    # validates; the later association generator still requires one exact
    # source-map route and byte-verified current source evidence.
    selected_vocabulary_definition_binding_item_ids = (
        set(selected_items).intersection(vocabulary_definition_binding_item_ids)
    )
    selected_vocabulary_direct_route_item_ids: set[str] = set()
    # Match the canonical closeout selector's two source-first retention lanes.
    # The indexed lane admits an item only when its current byte-pinned anchor
    # reconciles to exactly one independently extracted named presentation; a
    # map key, declared kind, summary, or Lean route cannot add it.  Explicit
    # corrected/scope dispositions remain review obligations independently of
    # whether the archival presentation is selected by the legacy heading
    # predicate.  Valid repeated-presentation aliases stay route-free and do
    # not become duplicate paper-facing obligations.
    # ``filter_source_map_items_for_proof_obligations`` owns the same three
    # retention lanes as the closeout protocol: ordinary source items,
    # byte-pinned indexed presentations, and corrected targets.  In
    # particular, a visible user-approved scope exclusion remains independently
    # validated but does not become an unrouted Lean proof target.
    fully_qualified_routes: set[str] = set()
    unrouted_items: list[str] = []
    route_errors: list[str] = list(presentation_alias_errors)
    route_errors.extend(
        "source prose-definition inventory: " + error
        for error in prose_definition_inventory_errors
    )
    atom_contract_companions: list[dict[str, str]] = []
    semantic_contract_companions: list[dict[str, str]] = []
    route_errors.extend(source_claim_atom_contract_errors(statement_map))
    configured_by_qualified = {
        qualified: row
        for row, raw_qualified in qualified_row_refs.items()
        if (qualified := semantic_contract_fully_qualified_identity(raw_qualified))
    }

    def accept_route(
        raw_route: object, *, source_key: str, route_field: str
    ) -> str:
        """Resolve only an exact current configured review declaration."""

        route = str(raw_route or "").strip()
        if not route:
            return ""
        qualified = semantic_contract_fully_qualified_identity(route)
        if not qualified:
            route_errors.append(
                f"selected source-coverage item {source_key!r} has non-qualified "
                f"{route_field} route {route!r}"
            )
            return ""
        if qualified not in configured_by_qualified:
            route_errors.append(
                f"selected source-coverage item {source_key!r} routes {route_field} "
                f"to {qualified!r}, which is not an exact configured PaperInterface "
                "review declaration"
            )
            return ""
        return qualified

    for raw_key, source_item in selected_items.items():
        source_key = str(raw_key)
        if source_key in presentation_aliases:
            # A source-only repeated presentation is separately anchored for
            # inventory completeness, while its canonical item owns the
            # direct source-to-Lean review route.
            continue
        route_policy = source_item_effective_route_policy(source_item)
        if bool(route_policy["is_support_only"]) or bool(
            route_policy["is_quarantined_source_defect"]
        ) or bool(
            route_policy["is_source_declared_open_nonresult"]
        ):
            # Retain support-only and quarantined items in the selected source
            # inventory, but do not route either as a proved paper result.
            continue
        valid_routes: set[str] = set()
        if source_claim_atom_authoritative_for_item(statement_map, source_item):
            raw_atoms = source_item.get(SOURCE_CLAIM_ATOMS_KEY)
            atom_schema_enabled = source_claim_atoms_contract_enabled(statement_map)
            atom_routes_complete = False
            if atom_schema_enabled:
                atom_errors = source_claim_atoms_validation_errors(raw_atoms)
                atom_routes_complete = not atom_errors
                if atom_errors:
                    route_errors.extend(
                        f"selected source-coverage item {source_key!r} atom contract: {error}"
                        for error in atom_errors
                    )
                elif isinstance(raw_atoms, list):
                    for index, raw_atom in enumerate(raw_atoms):
                        assert isinstance(raw_atom, Mapping)
                        qualified = accept_route(
                            raw_atom.get("reviewed_lean_route"),
                            source_key=source_key,
                            route_field=(
                                f"{SOURCE_CLAIM_ATOMS_KEY}[{index}].reviewed_lean_route"
                            ),
                        )
                        if qualified:
                            valid_routes.add(qualified)
                        else:
                            atom_routes_complete = False
            if not valid_routes:
                unrouted_items.append(source_key)

            # Atom routes remain the sole source-facing conclusion coverage for
            # this source presentation.  A complete direct/transparent-Spec
            # contract may nevertheless contribute its transparent Spec as an
            # audit companion for the same exact evidence declaration.  This
            # is needed to inspect every elaborated premise of an atom-routed
            # theorem, while the atom contexts retain clause-level conclusion
            # accountability.  The route is deliberately rejected unless all
            # atoms select exactly that one evidence declaration; a multi-route
            # source item cannot safely borrow one parent-level Spec.
            raw_contract = source_item.get("semantic_contract")
            if (
                raw_contract is not None
                and atom_schema_enabled
            ):
                if source_item.get("claim_bearing") is not True:
                    route_errors.append(
                        f"selected source-coverage item {source_key!r} has an atom "
                        "contract companion but is not explicitly claim_bearing"
                    )
                elif not isinstance(raw_contract, Mapping):
                    route_errors.append(
                        f"selected source-coverage item {source_key!r} has a non-object "
                        "semantic_contract alongside authoritative source claim atoms"
                    )
                else:
                    contract_schema = statement_map.get("semantic_contract_schema")
                    if (
                        not isinstance(contract_schema, int)
                        or isinstance(contract_schema, bool)
                        or contract_schema not in SEMANTIC_CONTRACT_SCHEMAS
                    ):
                        route_errors.append(
                            f"selected source-coverage item {source_key!r} has an atom "
                            "contract companion but no supported semantic_contract_schema"
                        )
                    else:
                        contract_errors = semantic_contract_validation_errors(
                            raw_contract, schema=contract_schema
                        )
                        if contract_errors:
                            route_errors.extend(
                                f"selected source-coverage item {source_key!r} atom "
                                f"contract companion: {error}"
                                for error in contract_errors
                            )
                        else:
                            evidence = accept_route(
                                raw_contract.get("evidence_declaration"),
                                source_key=source_key,
                                route_field="semantic_contract.evidence_declaration",
                            )
                            spec = accept_route(
                                raw_contract.get("spec_declaration"),
                                source_key=source_key,
                                route_field="semantic_contract.spec_declaration",
                            )
                            if (
                                not evidence
                                or not spec
                                or not atom_routes_complete
                                or valid_routes != {evidence}
                            ):
                                route_errors.append(
                                    f"selected source-coverage item {source_key!r} atom "
                                    "contract companion requires every source-claim atom to "
                                    "route to its one exact evidence declaration"
                                )
                            else:
                                fully_qualified_routes.add(spec)
                                atom_contract_companions.append(
                                    {
                                        "source_item": source_key,
                                        "evidence_declaration": evidence,
                                        "spec_declaration": spec,
                                    }
                                )
                                semantic_contract_companions.append(
                                    {
                                        "source_item": source_key,
                                        "evidence_declaration": evidence,
                                        "spec_declaration": spec,
                                    }
                                )
            fully_qualified_routes.update(valid_routes)
            # Atom routes are source-first and authoritative for an opted-in
            # theorem-like presentation.  Parent route lists remain archival
            # navigation only; the only additional route above is a validated
            # transparent-Spec companion for the exact atom evidence route.
            continue
        contract = source_item.get("semantic_contract")
        contract_route_present = False
        contract_routes: dict[str, str] = {}
        if isinstance(contract, dict):
            for field in ("evidence_declaration", "spec_declaration"):
                if str(contract.get(field) or "").strip():
                    contract_route_present = True
                    qualified = accept_route(
                        contract.get(field),
                        source_key=source_key,
                        route_field=f"semantic_contract.{field}",
                    )
                    if qualified:
                        valid_routes.add(qualified)
                        contract_routes[field] = qualified
            contract_schema = statement_map.get("semantic_contract_schema")
            contract_errors = (
                semantic_contract_validation_errors(contract, schema=contract_schema)
                if isinstance(contract_schema, int)
                and not isinstance(contract_schema, bool)
                and contract_schema in SEMANTIC_CONTRACT_SCHEMAS
                else ["no supported semantic_contract_schema"]
            )
            if contract_route_present and contract_errors:
                route_errors.extend(
                    f"selected source-coverage item {source_key!r} semantic contract: {error}"
                    for error in contract_errors
                )
            evidence = contract_routes.get("evidence_declaration", "")
            spec = contract_routes.get("spec_declaration", "")
            if (
                contract_route_present
                and not contract_errors
                and evidence
                and spec
                and evidence != spec
            ):
                semantic_contract_companions.append(
                    {
                        "source_item": source_key,
                        "evidence_declaration": evidence,
                        "spec_declaration": spec,
                    }
                )
        # A semantic contract is authoritative where supplied.  Legacy route
        # lists remain supported only for maps that have no contract route at
        # all, and they too must resolve to a current fully-qualified row.
        if not contract_route_present:
            for field in (
                "lean_declarations",
                "proof_lean_declarations",
                "spec_lean_declarations",
            ):
                raw_routes = source_item.get(field)
                if not isinstance(raw_routes, list):
                    continue
                for raw_route in raw_routes:
                    qualified = accept_route(
                        raw_route,
                        source_key=source_key,
                        route_field=field,
                    )
                    if qualified:
                        valid_routes.add(qualified)
        if not valid_routes:
            unrouted_items.append(source_key)
        # A source-vocabulary item can legitimately support several public
        # declarations. It remains part of source coverage in that case, but
        # the direct association lane has a deliberately stricter one-source,
        # one-review-declaration contract. Select only exact non-contract,
        # non-atom one-route cases for that association; do not turn a valid
        # multi-route source definition into a raw-audit error.
        if (
            source_key in selected_vocabulary_definition_binding_item_ids
            and source_item.get("semantic_contract") is None
            and len(valid_routes) == 1
        ):
            selected_vocabulary_direct_route_item_ids.add(source_key)
        fully_qualified_routes.update(valid_routes)

    selected_rows = [
        row
        for row in configured_present
        if qualified_row_refs.get(row) in fully_qualified_routes
    ]
    out_of_mode_rows = [row for row in configured_present if row not in selected_rows]
    selected_map = {**statement_map, "items": selected_items}
    return (
        selected_rows,
        selected_map,
        {
            "source_coverage_mode": mode,
            "source_coverage_mode_error": mode_error,
            "source_coverage_selected_source_items": sorted(selected_items),
            "source_coverage_validated_vocabulary_binding_source_items": sorted(
                selected_vocabulary_definition_binding_item_ids
            ),
            "source_coverage_validated_vocabulary_direct_route_source_items": sorted(
                selected_vocabulary_direct_route_item_ids
            ),
            "source_coverage_unrouted_source_items": sorted(unrouted_items),
            "source_coverage_route_errors": sorted(set(route_errors)),
            "source_coverage_atom_contract_companions": sorted(
                atom_contract_companions,
                key=lambda route: (
                    route["source_item"],
                    route["evidence_declaration"],
                    route["spec_declaration"],
                ),
            ),
            "source_coverage_semantic_contract_companions": sorted(
                semantic_contract_companions,
                key=lambda route: (
                    route["source_item"],
                    route["evidence_declaration"],
                    route["spec_declaration"],
                ),
            ),
            "out_of_mode_review_surface_rows": out_of_mode_rows,
            "source_coverage_selection_error": "",
        },
    )


def explicit_source_target_source_anchor_errors(
    paper_dir: Path,
    statement_map: Mapping[str, Any] | None,
    *,
    source_keys: Iterable[str],
) -> list[str]:
    """Byte-validate exactly the non-normal source targets selected here.

    These targets are deliberately outside ordinary named-theory coverage, so
    the normal coverage selector cannot be used as their provenance check.
    Scope the existing source-anchor validator to the exact selected map items
    instead.  This validates the current source bytes and quote spans; a
    source-map key or FQN never substitutes for that evidence.
    """

    selected_keys = {
        str(source_key).strip() for source_key in source_keys if str(source_key).strip()
    }
    if not selected_keys:
        return []
    if not isinstance(statement_map, Mapping):
        return ["explicit semantic source target has no readable source map"]
    raw_items = statement_map.get("items")
    if not isinstance(raw_items, Mapping):
        return ["explicit semantic source target source map has no items object"]
    selected_items: dict[str, Any] = {}
    errors: list[str] = []
    for source_key in sorted(selected_keys):
        source_item = raw_items.get(source_key)
        if not isinstance(source_item, Mapping):
            errors.append(
                "explicit semantic source target source item "
                f"{source_key!r} is absent or malformed"
            )
            continue
        selected_items[source_key] = source_item
    if not selected_items:
        return errors
    scoped_map = dict(statement_map)
    scoped_map["items"] = selected_items
    # Anchor validation is mandatory even for maps that did not globally opt
    # into it: this is the only source evidence permitted for this supplemental
    # semantic lane.
    scoped_map["source_anchor_evidence_required"] = True
    map_path = paper_dir / "audit" / "paper_statement_map.json"
    status = str(load_json_object(paper_dir / "status.json").get("status") or "")
    try:
        findings = source_anchor_evidence_findings(
            paper_dir,
            status or "formalized",
            map_path,
            scoped_map,
        )
    except Exception as error:  # noqa: BLE001 - provenance must fail closed.
        return errors + [
            "explicit semantic source-target anchor validator failed: "
            f"{type(error).__name__}: {error}"
        ]
    return errors + sorted(str(finding.message) for finding in findings)


def explicit_source_target_review_rows(
    paper_dir: Path,
    configured_present: list[str],
    qualified_row_refs: Mapping[str, str],
    explicit_targets: Iterable[str],
) -> tuple[list[str], dict[str, Any]]:
    """Resolve opt-in source-model targets through current source semantics.

    The declaration list selects a narrowly approved non-normal audit lane;
    it does *not* make a result source-backed by spelling alone.  Each target
    must be the evidence endpoint of exactly one claim-bearing current source
    item, whose complete direct/Spec semantic contract and byte-pinned source
    anchor both validate.  The returned rows always include both contract
    members so the transparent Spec surface and its recursive model records
    receive the same semantic review as ordinary source routes.
    """

    targets = list(dict.fromkeys(str(target).strip() for target in explicit_targets if str(target).strip()))
    selection: dict[str, Any] = {
        "semantic_model_explicit_source_target_declarations": targets,
        "semantic_model_explicit_source_target_source_items": [],
        "semantic_model_explicit_source_target_rows": [],
        "semantic_model_explicit_source_target_route_errors": [],
        "semantic_model_explicit_source_target_semantic_contract_companions": [],
    }
    if not targets:
        return [], selection

    statement_map = load_json_object(paper_dir / "audit" / "paper_statement_map.json")
    raw_items = statement_map.get("items") if isinstance(statement_map, Mapping) else None
    if not isinstance(raw_items, Mapping):
        selection["semantic_model_explicit_source_target_route_errors"] = [
            "explicit semantic source target selection requires paper_statement_map.json "
            "with an items object"
        ]
        return [], selection

    rows_by_qualified: dict[str, list[str]] = {}
    for row in configured_present:
        qualified = semantic_contract_fully_qualified_identity(
            qualified_row_refs.get(row)
        )
        if qualified:
            rows_by_qualified.setdefault(qualified, []).append(row)

    contract_schema = statement_map.get("semantic_contract_schema")
    route_errors: list[str] = []
    selected_rows: list[str] = []
    selected_source_items: list[str] = []
    companions: list[dict[str, str]] = []

    def append_row(row: str) -> None:
        if row not in selected_rows:
            selected_rows.append(row)

    for target in targets:
        endpoint_items: list[tuple[str, Mapping[str, Any]]] = []
        claim_bearing_items: list[tuple[str, Mapping[str, Any]]] = []
        for raw_source_key, raw_source_item in raw_items.items():
            source_key = str(raw_source_key).strip()
            if not source_key or not isinstance(raw_source_item, Mapping):
                continue
            raw_contract = raw_source_item.get("semantic_contract")
            if not isinstance(raw_contract, Mapping):
                continue
            evidence = semantic_contract_fully_qualified_identity(
                raw_contract.get("evidence_declaration")
            )
            if evidence != target:
                continue
            endpoint_items.append((source_key, raw_source_item))
            if raw_source_item.get("claim_bearing") is True:
                claim_bearing_items.append((source_key, raw_source_item))

        if len(claim_bearing_items) != 1:
            if not claim_bearing_items and endpoint_items:
                route_errors.append(
                    "explicit semantic source target "
                    f"{target!r} is routed only by source-map item(s) without "
                    "claim_bearing: true"
                )
            elif not claim_bearing_items:
                route_errors.append(
                    "explicit semantic source target "
                    f"{target!r} has no source-map semantic-contract evidence endpoint"
                )
            else:
                route_errors.append(
                    "explicit semantic source target "
                    f"{target!r} has {len(claim_bearing_items)} claim-bearing "
                    "source-map semantic-contract evidence endpoints; exactly one is required"
                )
            continue

        source_key, source_item = claim_bearing_items[0]
        raw_contract = source_item.get("semantic_contract")
        assert isinstance(raw_contract, Mapping)
        if (
            not isinstance(contract_schema, int)
            or isinstance(contract_schema, bool)
            or contract_schema not in SEMANTIC_CONTRACT_SCHEMAS
        ):
            route_errors.append(
                "explicit semantic source target "
                f"{target!r} has no supported source-map semantic_contract_schema"
            )
            continue
        contract_errors = semantic_contract_validation_errors(
            raw_contract, schema=contract_schema
        )
        if contract_errors:
            route_errors.extend(
                "explicit semantic source target "
                f"{target!r} source item {source_key!r} semantic contract: {error}"
                for error in contract_errors
            )
            continue
        evidence = semantic_contract_fully_qualified_identity(
            raw_contract.get("evidence_declaration")
        )
        spec = semantic_contract_fully_qualified_identity(
            raw_contract.get("spec_declaration")
        )
        if evidence != target or not spec or evidence == spec:
            route_errors.append(
                "explicit semantic source target "
                f"{target!r} source item {source_key!r} must provide two distinct "
                "exact semantic-contract evidence/Spec declarations"
            )
            continue
        route_rows: dict[str, str] = {}
        route_is_valid = True
        for role, qualified in (("evidence", evidence), ("Spec", spec)):
            matches = rows_by_qualified.get(qualified, [])
            if len(matches) != 1:
                route_errors.append(
                    "explicit semantic source target "
                    f"{target!r} source item {source_key!r} {role} declaration "
                    f"{qualified!r} is not an exact unique configured PaperInterface "
                    "review declaration"
                )
                route_is_valid = False
                continue
            route_rows[role] = matches[0]
        if not route_is_valid:
            continue
        anchor_errors = explicit_source_target_source_anchor_errors(
            paper_dir,
            statement_map,
            source_keys=[source_key],
        )
        if anchor_errors:
            route_errors.extend(
                "explicit semantic source target "
                f"{target!r} source item {source_key!r} anchor: {error}"
                for error in anchor_errors
            )
            continue
        selected_source_items.append(source_key)
        append_row(route_rows["evidence"])
        append_row(route_rows["Spec"])
        companions.append(
            {
                "source_item": source_key,
                "evidence_declaration": evidence,
                "spec_declaration": spec,
            }
        )

    selection["semantic_model_explicit_source_target_source_items"] = sorted(
        set(selected_source_items)
    )
    selection["semantic_model_explicit_source_target_rows"] = selected_rows
    selection["semantic_model_explicit_source_target_route_errors"] = sorted(
        set(route_errors)
    )
    selection["semantic_model_explicit_source_target_semantic_contract_companions"] = sorted(
        {
            (
                route["source_item"],
                route["evidence_declaration"],
                route["spec_declaration"],
            )
            for route in companions
        }
    )
    selection["semantic_model_explicit_source_target_semantic_contract_companions"] = [
        {
            "source_item": source_item,
            "evidence_declaration": evidence,
            "spec_declaration": spec,
        }
        for source_item, evidence, spec in selection[
            "semantic_model_explicit_source_target_semantic_contract_companions"
        ]
    ]
    return selected_rows, selection


def explicit_source_target_semantic_model_item_errors(
    *,
    explicit_targets: Iterable[str],
    companion_routes: Iterable[Mapping[str, object]],
    semantic_model_items: Iterable[Mapping[str, object]],
) -> list[str]:
    """Ensure selected source targets survived into the generated item surface.

    This is an omission guard on exact declaration identities.  It does not
    infer a route from a declaration name: each expected source item is the
    contract/anchor-attested companion selected earlier, and the generated
    semantic-model item must carry that same source-item identity after any
    transparent-Spec collapse.
    """

    expected_sources_by_target: dict[str, set[str]] = {}
    for raw_route in companion_routes:
        if not isinstance(raw_route, Mapping):
            continue
        source_item = str(raw_route.get("source_item") or "").strip()
        target = semantic_contract_fully_qualified_identity(
            raw_route.get("evidence_declaration")
        )
        if source_item and target:
            expected_sources_by_target.setdefault(target, set()).add(source_item)

    items_by_target: dict[str, list[Mapping[str, object]]] = {}
    for item in semantic_model_items:
        if not isinstance(item, Mapping):
            continue
        target = semantic_contract_fully_qualified_identity(
            item.get("qualified_declaration")
        )
        if target:
            items_by_target.setdefault(target, []).append(item)

    def associated_source_items(item: Mapping[str, object]) -> set[str]:
        associations: list[object] = [
            item.get("semantic_contract_group"),
            item.get("semantic_contract_source_association"),
        ]
        keys: set[str] = set()
        for association in associations:
            if not isinstance(association, Mapping):
                continue
            identities = association.get("source_item_identities")
            if not isinstance(identities, list):
                continue
            for identity in identities:
                if isinstance(identity, Mapping):
                    source_item = str(identity.get("source_key") or "").strip()
                    if source_item:
                        keys.add(source_item)
        return keys

    errors: list[str] = []
    for raw_target in explicit_targets:
        target = semantic_contract_fully_qualified_identity(raw_target)
        if not target:
            continue
        expected_sources = expected_sources_by_target.get(target, set())
        if len(expected_sources) != 1:
            errors.append(
                "explicit semantic source target "
                f"{target!r} lacks one validated source-contract companion receipt"
            )
            continue
        items = items_by_target.get(target, [])
        if len(items) != 1:
            errors.append(
                "explicit semantic source target "
                f"{target!r} has {len(items)} generated semantic-model item(s); "
                "exactly one evidence endpoint is required"
            )
            continue
        source_item = next(iter(expected_sources))
        if source_item not in associated_source_items(items[0]):
            errors.append(
                "explicit semantic source target "
                f"{target!r} generated semantic-model item has no matching "
                f"source-contract association for source item {source_item!r}"
            )
    return sorted(set(errors))


def formalization_scope_target_declarations_for_semantic_review(
    status_path: Path,
) -> tuple[list[str], list[str]]:
    """Read exact governing-target identities without using declaration names.

    A corrected formalization scope is an independent semantic-review demand,
    not normal source-presentation coverage.  Keep malformed or non-qualified
    target entries visible as generated errors instead of falling back to a
    short name or silently omitting the target from model review.
    """

    status = load_json_object(status_path)
    scope = status.get("formalization_scope")
    if scope is None:
        return [], []
    if not isinstance(scope, dict):
        return [], ["formalization_scope must be an object to select semantic targets"]
    raw_targets = scope.get("target_result_declarations")
    if raw_targets is None:
        return [], []
    if not isinstance(raw_targets, list):
        return [], [
            "formalization_scope.target_result_declarations must be a list of exact fully-qualified declarations"
        ]
    targets: list[str] = []
    errors: list[str] = []
    for index, raw_target in enumerate(raw_targets):
        target = semantic_contract_fully_qualified_identity(raw_target)
        if not target:
            errors.append(
                "formalization_scope.target_result_declarations["
                f"{index}] must be an exact fully-qualified Lean declaration"
            )
            continue
        if target in targets:
            errors.append(
                "formalization_scope.target_result_declarations contains duplicate "
                f"declaration {target!r}"
            )
            continue
        targets.append(target)
    return targets, errors


def effective_source_record_review_rows(
    *,
    source_selected_rows: list[str],
    configured_present: list[str],
    qualified_row_refs: dict[str, str],
    configured_assumption_rows: list[str],
    formalization_scope_targets: list[str],
    explicit_source_target_rows: Iterable[str] = (),
) -> tuple[list[str], dict[str, Any]]:
    """Union normal source coverage with explicit non-coverage semantic rows.

    Normal coverage remains source-presentation-first.  Independently, a
    configured source-model premise and an exact governing corrected target
    both require model-level semantic review.  A premise is selected from the
    explicit review-surface configuration, not from the filename in which its
    declaration happens to live.  The latter joins only on the fully-qualified
    identity recorded in status; it never suffix-matches a row or infers a
    target from a function/declaration name.
    """

    configured_set = set(configured_present)
    rows: list[str] = []

    def append_rows(candidates: list[str]) -> None:
        for row in candidates:
            if row in configured_set and row not in rows:
                rows.append(row)

    append_rows(source_selected_rows)
    append_rows(configured_assumption_rows)

    rows_by_qualified: dict[str, list[str]] = {}
    for row in configured_present:
        qualified = semantic_contract_fully_qualified_identity(
            qualified_row_refs.get(row)
        )
        if qualified:
            rows_by_qualified.setdefault(qualified, []).append(row)

    scope_target_rows: list[str] = []
    scope_target_route_errors: list[str] = []
    for target in formalization_scope_targets:
        matches = rows_by_qualified.get(target, [])
        if len(matches) != 1:
            if not matches:
                scope_target_route_errors.append(
                    "formalization_scope target "
                    f"{target!r} is not an exact configured review declaration"
                )
            else:
                scope_target_route_errors.append(
                    "formalization_scope target "
                    f"{target!r} resolves to multiple configured review rows"
                )
            continue
        row = matches[0]
        scope_target_rows.append(row)
        append_rows([row])

    explicit_target_rows: list[str] = []
    explicit_target_route_errors: list[str] = []
    for raw_row in explicit_source_target_rows:
        row = str(raw_row).strip()
        if row not in configured_set:
            explicit_target_route_errors.append(
                "explicit semantic source target route "
                f"{row!r} is not an exact configured review declaration"
            )
            continue
        if row not in explicit_target_rows:
            explicit_target_rows.append(row)
        append_rows([row])

    return rows, {
        "semantic_model_source_selected_rows": list(source_selected_rows),
        "semantic_model_configured_assumption_rows": list(
            configured_assumption_rows
        ),
        "semantic_model_scope_target_declarations": list(
            formalization_scope_targets
        ),
        "semantic_model_scope_target_rows": scope_target_rows,
        "semantic_model_scope_target_route_errors": sorted(
            set(scope_target_route_errors)
        ),
        # This independent lane has already been source-map/anchor attested
        # before reaching this union.  Its rows must remain visibly distinct
        # from corrected targets so no status declaration can masquerade as a
        # source-presentation or user-approved-model route.
        "semantic_model_explicit_source_target_rows": explicit_target_rows,
        "semantic_model_explicit_source_target_effective_row_errors": sorted(
            set(explicit_target_route_errors)
        ),
    }


def recursive_field_rows_reachable_from_selected_review_routes(
    *,
    source_selected_rows: Iterable[str],
    formalization_scope_target_rows: Iterable[str],
    explicit_source_target_rows: Iterable[str] = (),
    effective_rows: Iterable[str],
    qualified_row_refs: Mapping[str, str],
    local_declarations: Iterable[LocalDeclaration],
    elaborated_signature_sha256_by_qualified: Mapping[str, str] | None = None,
    elaborated_manifests_by_qualified: Mapping[
        str, Mapping[str, Any]
    ] | None = None,
) -> dict[str, Any]:
    """Scope recursive fields from Lean's exact selected-root dependency graph.

    Declaration strings are used only to join configured rows to graph nodes.
    Source tokens, local/private naming heuristics, comments, and parser
    resolution never create or suppress reachability. Missing or malformed
    graph evidence fails closed by retaining every supplemental row.
    """

    _ = local_declarations
    configured_rows = list(
        dict.fromkeys(str(row) for row in effective_rows if str(row))
    )
    configured_set = set(configured_rows)
    route_roles: dict[str, set[str]] = {}

    def add_route_rows(rows: Iterable[str], role: str) -> None:
        for raw_row in rows:
            row = str(raw_row)
            if row in configured_set:
                route_roles.setdefault(row, set()).add(role)

    add_route_rows(source_selected_rows, "selected_source_route")
    add_route_rows(
        formalization_scope_target_rows,
        "selected_formalization_scope_target",
    )
    add_route_rows(
        explicit_source_target_rows,
        "selected_explicit_source_target",
    )
    route_rows = [row for row in configured_rows if row in route_roles]
    supplemental_rows = [row for row in configured_rows if row not in route_roles]
    signatures = elaborated_signature_sha256_by_qualified or {}
    manifests = elaborated_manifests_by_qualified or {}

    analysis_errors: list[str] = []
    rows_by_qualified: dict[str, list[str]] = {}
    qualified_by_row: dict[str, str] = {}
    for row in configured_rows:
        qualified = semantic_contract_fully_qualified_identity(
            qualified_row_refs.get(row)
        )
        if not qualified:
            analysis_errors.append(
                "selected-review recursive-field reachability has no exact "
                f"configured declaration identity for row {row!r}"
            )
            continue
        qualified_by_row[row] = qualified
        rows_by_qualified.setdefault(qualified, []).append(row)

    paths_by_row: dict[str, dict[tuple[str, ...], dict[str, Any]]] = {
        row: {} for row in configured_rows
    }
    for selected_row in route_rows:
        root = qualified_by_row.get(selected_row, "")
        manifest = manifests.get(root)
        graph = manifest.get("semantic_dependency_graph") if isinstance(
            manifest, Mapping
        ) else None
        if (
            not root
            or not isinstance(graph, Mapping)
            or graph.get("realization_complete") is not True
            or str(graph.get("root_declaration") or "").strip() != root
        ):
            analysis_errors.append(
                "selected-review recursive-field reachability lacks a complete "
                f"elaborated dependency graph for {root or selected_row!r}"
            )
            continue
        raw_nodes = graph.get("nodes")
        raw_edges = graph.get("edges")
        if not isinstance(raw_nodes, list) or not isinstance(raw_edges, list):
            analysis_errors.append(
                "selected-review recursive-field reachability has malformed "
                f"elaborated dependency graph for {root!r}"
            )
            continue
        nodes = {
            str(node.get("declaration") or "").strip()
            for node in raw_nodes
            if isinstance(node, Mapping)
            and str(node.get("declaration") or "").strip()
        }
        adjacency: dict[str, set[str]] = {}
        malformed = root not in nodes
        for edge in raw_edges:
            if not isinstance(edge, Mapping):
                malformed = True
                break
            source = str(edge.get("source") or "").strip()
            target = str(edge.get("target") or "").strip()
            role = str(edge.get("role") or "").strip()
            if source not in nodes or target not in nodes or not role:
                malformed = True
                break
            adjacency.setdefault(source, set()).add(target)
        if malformed:
            analysis_errors.append(
                "selected-review recursive-field reachability has malformed "
                f"elaborated dependency edges for {root!r}"
            )
            continue
        queue: deque[tuple[str, list[str]]] = deque([(root, [root])])
        seen: set[str] = set()
        while queue:
            current, chain = queue.popleft()
            if current in seen:
                continue
            seen.add(current)
            for reached_row in rows_by_qualified.get(current, []):
                route: dict[str, Any] = {
                    "selected_review_row": selected_row,
                    "selected_route_roles": sorted(
                        route_roles.get(selected_row, set())
                    ),
                    "selected_qualified_declaration": root,
                    "declaration_path": chain,
                    "reachability": (
                        "direct_selected_route"
                        if len(chain) == 1
                        else "elaborated_selected_route_dependency"
                    ),
                }
                signature = str(signatures.get(root) or "").strip().lower()
                if SHA256_RE.fullmatch(signature):
                    route["selected_elaborated_signature_sha256"] = signature
                paths_by_row[reached_row].setdefault(tuple(chain), route)
            for child in sorted(adjacency.get(current, set())):
                if child not in seen:
                    queue.append((child, [*chain, child]))

    fail_closed = bool(analysis_errors)
    included_rows = set(route_rows)
    if fail_closed:
        included_rows.update(supplemental_rows)
    else:
        included_rows.update(
            row for row in supplemental_rows if paths_by_row.get(row)
        )

    rows: list[dict[str, Any]] = []
    for row in configured_rows:
        route_paths = list(paths_by_row.get(row, {}).values())
        is_route_root = row in route_roles
        if is_route_root:
            disposition = "selected_review_route_root"
        elif fail_closed:
            disposition = "retained_due_to_incomplete_reachability_analysis"
        elif route_paths:
            disposition = "reachable_from_selected_review_route"
        else:
            disposition = "unreachable_supplemental_support"
        rows.append(
            {
                "row": row,
                "qualified_declaration": qualified_by_row.get(row, ""),
                "selection_roles": sorted(route_roles.get(row, set())),
                "supplemental_to_selected_routes": not is_route_root,
                "included_for_recursive_field_review": row in included_rows,
                "disposition": disposition,
                "selected_route_paths": route_paths,
            }
        )
    return {
        "schema": 1,
        "selected_route_rows": route_rows,
        "supplemental_rows": supplemental_rows,
        "reachability_analysis_complete": not fail_closed,
        "analysis_errors": sorted(set(analysis_errors)),
        "duplicate_declaration_identities": [],
        "included_rows": [row for row in configured_rows if row in included_rows],
        "excluded_unreachable_supplemental_rows": [
            row for row in supplemental_rows if row not in included_rows
        ],
        "rows": rows,
    }


def elaborated_review_signature_surfaces(
    *,
    root: Path,
    import_module: str,
    row_names: list[str],
    qualified_row_refs: dict[str, str],
    no_lean: bool,
    analysis_qualified_names: Iterable[str] = (),
    additional_qualified_names: Iterable[str] = (),
    semantic_dependency_modules: tuple[str, ...] | None = None,
    prevalidated_manifests: Mapping[str, Mapping[str, Any]] | None = None,
) -> tuple[dict[str, str], dict[str, dict[str, Any]], list[str]]:
    """Return exact Lean signatures plus bounded elaborated review surfaces.

    Source-map routes have already been checked against ``qualified_row_refs``.
    This second step asks Lean for the current elaborated type at those exact
    qualified declarations.  A complete transparent alias can have a distinct
    effective declaration whose result telescope is the only semantic surface
    eligible for result-path receipts; callers provide that exact identity in
    ``analysis_qualified_names``.  It intentionally never resolves a short
    name or derives a route from a declaration/function spelling.  The
    retained manifest surface is diagnostic input for structural semantic
    dimensions; its digest remains the sole item-level identity pin.
    """

    reviewed_requested: list[str] = []
    errors: list[str] = []
    for row in row_names:
        qualified = semantic_contract_fully_qualified_identity(
            qualified_row_refs.get(row)
        )
        if not qualified:
            errors.append(
                f"selected review row {row!r} has no exact fully-qualified PaperInterface declaration"
            )
            continue
        reviewed_requested.append(qualified)
    reviewed_requested = sorted(set(reviewed_requested))
    analysis_requested: list[str] = []
    for raw_qualified in analysis_qualified_names:
        qualified = semantic_contract_fully_qualified_identity(raw_qualified)
        if not qualified:
            errors.append(
                "effective semantic review surface has no exact fully-qualified Lean identity: "
                + str(raw_qualified)
            )
            continue
        analysis_requested.append(qualified)
    analysis_requested = sorted(set(analysis_requested))
    additional_requested: list[str] = []
    for raw_qualified in additional_qualified_names:
        qualified = semantic_contract_fully_qualified_identity(raw_qualified)
        if not qualified:
            errors.append(
                "structurally reachable model root has no exact fully-qualified Lean identity: "
                + str(raw_qualified)
            )
            continue
        additional_requested.append(qualified)
    requested = sorted(
        set(reviewed_requested) | set(analysis_requested) | set(additional_requested)
    )
    if not requested:
        return {}, {}, errors
    if no_lean:
        return (
            {},
            {},
            errors
            + [
                "exact elaborated review-signature verification was skipped by --no-lean; "
                "item-level source-record reuse is disabled"
            ],
        )
    try:
        from scripts.lean_signature_manifest import (
            run_lean_signature_manifests,
            semantic_dependency_manifest,
            signature_manifest_digest,
        )

        def report_manifest_batch_progress(event: Mapping[str, Any]) -> None:
            """Keep a long native graph request observable without changing evidence."""

            batch_number = event.get("batch_number")
            batch_total = event.get("batch_total")
            root_count = event.get("root_count")
            if event.get("status") == "started":
                source_record_progress(
                    "exact elaborated review-signature graph request "
                    f"{batch_number}/{batch_total} started ({root_count} roots)"
                )
                return
            source_record_progress(
                "exact elaborated review-signature graph request "
                f"{batch_number}/{batch_total} finished ({root_count} roots; "
                f"{event.get('completed_count')} complete; "
                f"{event.get('missing_count')} missing)"
            )

        reusable = {
            qualified: dict(manifest)
            for qualified, manifest in (prevalidated_manifests or {}).items()
            if qualified in requested and isinstance(manifest, Mapping)
        }
        fresh_requested = [
            qualified for qualified in requested if qualified not in reusable
        ]
        fresh = run_lean_signature_manifests(
            root,
            import_module,
            fresh_requested,
            timeout_seconds=SOURCE_RECORD_LEAN_ELABORATION_TIMEOUT_SECONDS,
            build_timeout_seconds=SOURCE_RECORD_LAKE_BUILD_TIMEOUT_SECONDS,
            semantic_dependency_modules=semantic_dependency_modules,
            progress_callback=report_manifest_batch_progress,
        )
        manifests = {**reusable, **fresh}
    except Exception as exc:  # noqa: BLE001 - a missing manifest is fail-closed.
        return {}, {}, errors + [
            "exact elaborated review-signature verification raised "
            f"{type(exc).__name__}: {exc}"
        ]
    digests: dict[str, str] = {}
    validated_manifests: dict[str, dict[str, Any]] = {}
    for qualified in requested:
        manifest = manifests.get(qualified)
        digest = (
            signature_manifest_digest(manifest)
            if isinstance(manifest, dict)
            else ""
        )
        recorded = str(manifest.get("sha256") or "").strip().lower() if isinstance(manifest, dict) else ""
        if not SHA256_RE.fullmatch(digest) or recorded != digest:
            errors.append(
                "exact elaborated review-signature manifest is missing or malformed for "
                + qualified
            )
            continue
        dependency_manifest = semantic_dependency_manifest(manifest)
        dependency_digest = (
            str(dependency_manifest.get("semantic_dependency_sha256") or "")
            .strip()
            .lower()
            if isinstance(dependency_manifest, Mapping)
            else ""
        )
        if not SHA256_RE.fullmatch(dependency_digest):
            errors.append(
                "exact elaborated transitive semantic-dependency manifest is "
                "missing or malformed for " + qualified
            )
            continue
        manifest["semantic_dependency_manifest"] = dependency_manifest
        execution_shape = manifest.get(
            "elaborated_execution_state_refinement_shape"
        )
        if not (
            isinstance(execution_shape, Mapping)
            and execution_shape.get("schema") in {1, 2}
            and (
                execution_shape.get("schema") == 1
                or execution_shape.get("detector_basis")
                == "lean_statement_dependency_graph_structural_v1"
            )
            and isinstance(execution_shape.get("scan_complete"), bool)
            and isinstance(execution_shape.get("has_refl_trans_gen_path"), bool)
            and isinstance(
                execution_shape.get("has_relation_valued_state_transition"), bool
            )
            and isinstance(execution_shape.get("detected"), bool)
            and execution_shape.get("detected")
            == (
                execution_shape.get("scan_complete")
                and execution_shape.get("has_refl_trans_gen_path")
                and execution_shape.get("has_relation_valued_state_transition")
            )
        ):
            errors.append(
                "exact elaborated review-signature manifest lacks a valid "
                "execution/state-refinement structural surface for " + qualified
            )
            continue
        # The wrapper remains the source-facing route.  An exact effective
        # alias target also needs its own digest because result-path receipts
        # bind its elaborated telescope, not the wrapper's empty alias type.
        # Ordinary structural record roots stay manifest-only and cannot gain
        # a review-route signature through this scan.
        if qualified in reviewed_requested or qualified in analysis_requested:
            digests[qualified] = digest
        validated_manifests[qualified] = manifest
    return digests, validated_manifests, errors



def _input_binder_arity(visible_input: Mapping[str, object]) -> int:
    """Return the structural binder multiplicity of one parsed input group."""

    names = binder_names(str(visible_input.get("names") or ""))
    return max(1, len(names))


def positional_manifest_binders_for_parsed_inputs(
    *,
    atoms: list[Mapping[str, Any]],
    parsed_arity: int,
) -> tuple[list[Mapping[str, Any]], list[str]]:
    """Align source-written input groups with Lean's outer telescope.

    A declaration may rely on Lean's ``autoImplicit`` insertion for leading
    carrier variables declared in its surrounding section.  Those generated
    binders are present in Lean's exact manifest but have no declaration-local
    source presentation to pair with a parsed input group.  They can be
    skipped only when every unmatched leading atom is an implicit parameter
    whose emitted type is ``Type`` or ``Sort``.  All other arity mismatches
    remain errors: in particular, this never discards an instance, an
    assumption, or an implicit value parameter.
    """

    if parsed_arity < 0 or parsed_arity > len(atoms):
        return [], [
            "Lean signature manifest binder arity does not match generated input groups"
        ]
    prefix_length = len(atoms) - parsed_arity
    prefix = atoms[:prefix_length]
    for index, atom in enumerate(prefix):
        display = normalize_ws(str(atom.get("display") or ""))
        is_inferred_type = display == "Type" or display == "Sort" or display.startswith(
            "Type "
        ) or display.startswith("Sort ")
        if (
            atom.get("ref") != f"b/{index}"
            or atom.get("role") != "parameter"
            or atom.get("binder_info") != "implicit"
            or not is_inferred_type
        ):
            return [], [
                "Lean signature manifest binder arity does not match generated input groups"
            ]
    selected = atoms[prefix_length:]
    for offset, atom in enumerate(selected, start=prefix_length):
        if (
            atom.get("ref") != f"b/{offset}"
            or atom.get("role") not in {"parameter", "assumption"}
        ):
            return [], ["Lean signature manifest outer binder atoms are malformed"]
    return selected, []


def lean_row_input_proposition_sorts(
    *,
    root: Path,
    import_module: str,
    row_inputs: Mapping[str, list[dict[str, str]]],
    row_conclusion_inputs: Mapping[str, list[dict[str, str]]],
    analysis_qualified_row_refs: Mapping[str, str],
    no_lean: bool,
    elaborated_signature_manifests: Mapping[str, Mapping[str, Any]] | None = None,
    semantic_dependency_modules: Iterable[str] = (),
    delegated_empty_input_rows: Mapping[str, Mapping[str, str]] | None = None,
    positional_signature_manifests_by_row: Mapping[
        str, Mapping[str, Any]
    ] | None = None,
) -> tuple[dict[tuple[str, str, int], str], list[str]]:
    """Classify visible theorem inputs from Lean manifest binder roles.

    The source scanner supplies only a positional map to the review surface;
    Lean owns the actual distinction between a proof-valued binder and a
    parameter/data binder through its elaborated ``isProp`` result.  Any
    mismatch, including a dependent result guard which is not an outer binder,
    is emitted as ``unknown`` and cannot silently become model data.
    """

    positions: dict[tuple[str, str, int], str] = {}
    errors: list[str] = []
    for row in sorted(analysis_qualified_row_refs):
        for section, inputs in (
            ("boundary_input_items", row_inputs.get(row, [])),
            ("conclusion_dependency_items", row_conclusion_inputs.get(row, [])),
        ):
            for index, visible_input in enumerate(inputs):
                positions[(row, section, index)] = "unknown"
    if no_lean:
        if positions:
            errors.append(
                "Lean row-binder proposition-sort verification was skipped by --no-lean"
            )
        return positions, errors

    requested = sorted(
        {
            semantic_contract_fully_qualified_identity(qualified)
            for qualified in analysis_qualified_row_refs.values()
            if semantic_contract_fully_qualified_identity(qualified)
        }
    )
    if not requested:
        if positions:
            errors.append("no exact analysis declaration was available for row-binder sorts")
        return positions, errors
    if elaborated_signature_manifests is not None:
        manifests = dict(elaborated_signature_manifests)
    else:
        try:
            manifests = run_lean_signature_manifests(
                root,
                import_module,
                requested,
                timeout_seconds=SOURCE_RECORD_LEAN_ELABORATION_TIMEOUT_SECONDS,
                build_timeout_seconds=SOURCE_RECORD_LAKE_BUILD_TIMEOUT_SECONDS,
                semantic_dependency_modules=semantic_dependency_modules,
            )
        except Exception as exc:  # noqa: BLE001 - sort evidence fails closed.
            return positions, [
                "Lean row-binder proposition-sort verification raised "
                + type(exc).__name__
                + ": "
                + str(exc)
            ]

    for row, qualified in sorted(analysis_qualified_row_refs.items()):
        exact = semantic_contract_fully_qualified_identity(qualified)
        delegation = (delegated_empty_input_rows or {}).get(row)
        if isinstance(delegation, Mapping):
            delegated_qualified = semantic_contract_fully_qualified_identity(
                delegation.get("analysis_qualified_declaration")
            )
            if (
                delegated_qualified != exact
                or row_inputs.get(row)
                or row_conclusion_inputs.get(row)
            ):
                errors.append(
                    "semantic-contract empty-input delegation is malformed for "
                    + exact
                )
            else:
                continue
        manifest = (positional_signature_manifests_by_row or {}).get(
            row, manifests.get(exact)
        )
        atoms = manifest.get("atoms") if isinstance(manifest, Mapping) else None
        if not isinstance(atoms, list) or not atoms:
            errors.append(
                "Lean row-binder proposition-sort manifest is missing for " + exact
            )
            continue
        binder_atoms: list[Mapping[str, Any]] = []
        malformed = False
        for atom in atoms:
            if not isinstance(atom, Mapping):
                malformed = True
                break
            role = str(atom.get("role") or "").strip()
            ref = str(atom.get("ref") or "").strip()
            if ref == "result":
                if atom is not atoms[-1]:
                    malformed = True
                continue
            if role not in {"parameter", "assumption"}:
                malformed = True
                break
            binder_atoms.append(atom)
        if malformed or not atoms[-1:] or not isinstance(atoms[-1], Mapping) or atoms[-1].get("ref") != "result":
            errors.append(
                "Lean row-binder proposition-sort manifest is malformed for " + exact
            )
            continue

        structural_inputs: list[tuple[str, int, dict[str, str], int]] = []
        for section, inputs in (
            ("boundary_input_items", row_inputs.get(row, [])),
            ("conclusion_dependency_items", row_conclusion_inputs.get(row, [])),
        ):
            for index, visible_input in enumerate(inputs):
                # A dependent result guard is a theorem-facing semantic
                # condition but not an outer Lean binder. It stays unknown
                # until a dedicated Lean extraction proves its role.
                if visible_input.get("input_origin") == "dependent_if_guard":
                    continue
                structural_inputs.append(
                    (section, index, visible_input, _input_binder_arity(visible_input))
                )
        expected_arity = sum(arity for _section, _index, _input, arity in structural_inputs)
        positional_binders, positional_errors = (
            positional_manifest_binders_for_parsed_inputs(
                atoms=binder_atoms,
                parsed_arity=expected_arity,
            )
        )
        if positional_errors:
            errors.append(
                "Lean row-binder proposition-sort arity does not match generated input groups for "
                + exact
            )
            continue
        binder_roles = [str(atom.get("role") or "") for atom in positional_binders]
        cursor = 0
        for section, index, _visible_input, arity in structural_inputs:
            roles = binder_roles[cursor : cursor + arity]
            cursor += arity
            if len(set(roles)) != 1:
                errors.append(
                    "Lean row-binder proposition-sort has inconsistent grouped binder roles for "
                    + exact
                )
                continue
            positions[(row, section, index)] = (
                "true" if roles[0] == "assumption" else "false"
            )
    return positions, sorted(set(errors))


def signature_manifest_atom_identity(atom: object) -> dict[str, str] | None:
    """Return the exact name-free identity of one Lean signature atom."""

    if not isinstance(atom, Mapping):
        return None
    ref = str(atom.get("ref") or "").strip()
    role = str(atom.get("role") or "").strip()
    canonical = atom.get("canonical")
    if not ref or not role or canonical is None:
        return None
    payload: dict[str, object] = {
        "ref": ref,
        "role": role,
        "canonical": canonical,
    }
    if role != "conclusion":
        binder_info = str(atom.get("binder_info") or "").strip()
        if not binder_info:
            return None
        payload["binder_info"] = binder_info
    digest = hashlib.sha256(
        json.dumps(
            payload, ensure_ascii=False, sort_keys=True, separators=(",", ":")
        ).encode("utf-8")
    ).hexdigest()
    return {
        "ref": ref,
        "role": role,
        "signature_atom_sha256": digest,
    }


def elaborated_visible_input_binder_atom_receipts(
    *,
    visible_inputs: list[dict[str, str]],
    manifest: Mapping[str, Any] | None,
) -> tuple[dict[int, list[dict[str, str]]], list[str]]:
    """Bind every parsed visible input group to Lean's outer Pi atoms.

    This is intentionally narrower than presentation parsing: the only
    accepted coordinate is an exact atom emitted by the elaborated signature
    manifest.  A dependent-if guard has no outer binder and remains excluded.
    The mapping is therefore stable under alpha-renaming of every source
    binder, while still rejecting any parsed/Lean telescope arity mismatch.
    """

    atom_groups, errors = elaborated_visible_input_binder_atom_groups(
        visible_inputs=visible_inputs,
        manifest=manifest,
    )
    if errors:
        return {}, errors
    receipts: dict[int, list[dict[str, str]]] = {}
    for index, raw_atoms in atom_groups.items():
        identities = [signature_manifest_atom_identity(atom) for atom in raw_atoms]
        if any(identity is None for identity in identities):
            return {}, [
                "Lean signature manifest has malformed atoms for visible-input atom receipt"
            ]
        receipts[index] = [
            identity for identity in identities if identity is not None
        ]
    return receipts, []


def elaborated_visible_input_binder_atom_groups(
    *,
    visible_inputs: list[dict[str, str]],
    manifest: Mapping[str, Any] | None,
) -> tuple[dict[int, list[Mapping[str, Any]]], list[str]]:
    """Bind parsed input groups to their exact Lean-emitted binder atoms."""

    if not isinstance(manifest, Mapping):
        return {}, ["Lean signature manifest is unavailable for visible-input atom receipt"]
    signature = str(manifest.get("sha256") or "").strip().lower()
    raw_atoms = manifest.get("atoms")
    if not SHA256_RE.fullmatch(signature) or not isinstance(raw_atoms, list):
        return {}, ["Lean signature manifest is malformed for visible-input atom receipt"]
    if not raw_atoms:
        return {}, ["Lean signature manifest has no atoms for visible-input atom receipt"]
    if any(
        not isinstance(atom, Mapping)
        or signature_manifest_atom_identity(atom) is None
        for atom in raw_atoms
    ):
        return {}, ["Lean signature manifest has malformed atoms for visible-input atom receipt"]
    atoms = [atom for atom in raw_atoms if isinstance(atom, Mapping)]
    if atoms[-1].get("ref") != "result" or atoms[-1].get("role") != "conclusion":
        return {}, ["Lean signature manifest has no terminal conclusion atom"]
    all_binder_atoms = atoms[:-1]

    structural_inputs = [
        (index, visible_input, _input_binder_arity(visible_input))
        for index, visible_input in enumerate(visible_inputs)
        if visible_input.get("input_origin") != "dependent_if_guard"
    ]
    binder_atoms, positional_errors = positional_manifest_binders_for_parsed_inputs(
        atoms=all_binder_atoms,
        parsed_arity=sum(arity for _index, _input, arity in structural_inputs),
    )
    if positional_errors:
        return {}, [
            "Lean signature manifest binder arity does not match generated visible input groups"
        ]

    groups: dict[int, list[Mapping[str, Any]]] = {}
    cursor = 0
    for index, _visible_input, arity in structural_inputs:
        current_atoms = binder_atoms[cursor : cursor + arity]
        cursor += arity
        if not current_atoms:
            return {}, ["generated visible input has no elaborated binder atom"]
        groups[index] = current_atoms
    return groups, []


def elaborated_result_input_path_receipts(
    *,
    header_inputs: list[dict[str, str]],
    conclusion_inputs: list[dict[str, str]],
    manifest: Mapping[str, Any] | None,
) -> tuple[dict[int, dict[str, Any]], list[str]]:
    """Bind parsed result binders to the exact elaborated Pi telescope.

    Source parsing only supplies presentation coordinates.  The receipt below
    is emitted only when every outer parsed binder group has exactly the same
    arity as Lean's elaborated telescope.  It records the result binder's
    exact atom(s), every preceding/following result atom, and the terminal
    conclusion atom.  Thus a later audit can distinguish a universally
    quantified outcome domain from an ordinary caller input without trusting
    synthetic binder names or textual type reconstruction.
    """

    if not isinstance(manifest, Mapping):
        return {}, ["Lean signature manifest is unavailable for result-path receipt"]
    signature = str(manifest.get("sha256") or "").strip().lower()
    raw_atoms = manifest.get("atoms")
    if not re.fullmatch(r"[0-9a-f]{64}", signature) or not isinstance(raw_atoms, list):
        return {}, ["Lean signature manifest is malformed for result-path receipt"]
    if not raw_atoms:
        return {}, ["Lean signature manifest has no atoms for result-path receipt"]

    atom_identities = [signature_manifest_atom_identity(atom) for atom in raw_atoms]
    if any(identity is None for identity in atom_identities):
        return {}, ["Lean signature manifest has malformed atoms for result-path receipt"]
    manifest_atoms = [
        atom for atom in raw_atoms if isinstance(atom, Mapping)
    ]
    atoms = [identity for identity in atom_identities if identity is not None]
    if (
        len(manifest_atoms) != len(atoms)
        or atoms[-1]["ref"] != "result"
        or atoms[-1]["role"] != "conclusion"
    ):
        return {}, ["Lean signature manifest has no terminal conclusion atom"]
    all_binder_atoms = manifest_atoms[:-1]

    outer_inputs: list[tuple[str, int, dict[str, str], int]] = []
    for index, item in enumerate(header_inputs):
        if item.get("input_origin") == "dependent_if_guard":
            continue
        outer_inputs.append(("header", index, item, _input_binder_arity(item)))
    for index, item in enumerate(conclusion_inputs):
        if item.get("input_origin") == "dependent_if_guard":
            continue
        outer_inputs.append(("result", index, item, _input_binder_arity(item)))
    selected_manifest_binders, positional_errors = (
        positional_manifest_binders_for_parsed_inputs(
            atoms=all_binder_atoms,
            parsed_arity=sum(
                arity for _section, _index, _item, arity in outer_inputs
            ),
        )
    )
    if positional_errors:
        return {}, [
            "Lean signature manifest binder arity does not match generated header/result input groups"
        ]
    binder_atoms = [
        signature_manifest_atom_identity(atom)
        for atom in selected_manifest_binders
    ]
    if any(atom is None for atom in binder_atoms):
        return {}, ["Lean signature manifest has malformed atoms for result-path receipt"]
    binder_atoms = [atom for atom in binder_atoms if atom is not None]

    cursor = 0
    receipts: dict[int, dict[str, Any]] = {}
    result_atoms: list[dict[str, str]] = []
    for section, index, item, arity in outer_inputs:
        current_atoms = binder_atoms[cursor : cursor + arity]
        cursor += arity
        if section != "result":
            continue
        origin = str(item.get("input_origin") or "").strip()
        connective = (
            "forall"
            if origin in {"result_forall", "result_forall_inferred_domain"}
            else "arrow"
            if origin == "result_arrow"
            else ""
        )
        if not connective:
            return {}, [
                "generated result input has no structural forall/arrow origin for result-path receipt"
            ]
        receipt: dict[str, Any] = {
            "schema": ELABORATED_RESULT_INPUT_PATH_SCHEMA,
            "manifest_signature_sha256": signature,
            "input_section": "result",
            "connective": connective,
            "result_input_ordinal": len(receipts),
            "binder_atoms": current_atoms,
            "preceding_result_binder_atoms": list(result_atoms),
            "following_result_binder_atoms": [],
            "terminal_conclusion_atom": atoms[-1],
        }
        receipts[index] = receipt
        result_atoms.extend(current_atoms)

    for receipt in receipts.values():
        current_refs = {
            atom["ref"] for atom in receipt["binder_atoms"]
            if isinstance(atom, Mapping)
        }
        preceding_refs = {
            atom["ref"] for atom in receipt["preceding_result_binder_atoms"]
            if isinstance(atom, Mapping)
        }
        receipt["following_result_binder_atoms"] = [
            atom
            for atom in result_atoms
            if atom["ref"] not in current_refs | preceding_refs
        ]
        digest_payload = {
            key: value for key, value in receipt.items() if key != "path_sha256"
        }
        receipt["path_sha256"] = hashlib.sha256(
            json.dumps(
                digest_payload,
                ensure_ascii=False,
                sort_keys=True,
                separators=(",", ":"),
            ).encode("utf-8")
        ).hexdigest()
    return receipts, []


def lean_recursive_field_proposition_sorts(
    *,
    root: Path,
    import_module: str,
    fields: list[FieldInfo],
    no_lean: bool,
    diagnostics_out: dict[str, Any] | None = None,
) -> tuple[dict[str, dict[str, object]], list[str]]:
    """Return exact Lean field-slot safety receipts for expanded fields.

    The source parser contributes only an elaborated projection declaration or
    constructor slot.  Lean then determines both direct proposition sort and
    whether non-Proposition data has a trusted structural-data route.  Field
    spelling never decides that semantic classification.
    """

    locators_by_key: dict[str, dict[str, object]] = {}
    errors: list[str] = []
    for field in fields:
        key = f"{field.structure}.{field.field}"
        if not field.structure.strip() or not field.field.strip() or key in locators_by_key:
            errors.append(f"recursive field has missing or duplicate identity: {key}")
            continue
        field_index = field.constructor_argument_index
        if type(field_index) is not int or field_index < 0:
            errors.append(f"{key}: no parsed constructor field ordinal")
            continue
        if field.projection_fqn.strip():
            material: dict[str, object] = {
                "schema": RECURSIVE_FIELD_SAFETY_LOCATOR_SCHEMA,
                "kind": "projection",
                "declaration": field.projection_fqn.strip(),
                "field_index": field_index,
            }
        elif field.constructor_fqn.strip():
            material = {
                "schema": RECURSIVE_FIELD_SAFETY_LOCATOR_SCHEMA,
                "kind": "constructor_argument",
                "constructor": field.constructor_fqn.strip(),
                "field_index": field_index,
            }
        else:
            errors.append(f"{key}: no elaborated projection or constructor locator")
            continue
        locator = {
            **material,
            "field_identity_sha256": recursive_field_safety_locator_identity(
                material
            ),
        }
        canonical = canonical_recursive_field_safety_locator(locator)
        if canonical is None:
            errors.append(f"{key}: malformed elaborated field-safety locator")
            continue
        locators_by_key[key] = canonical
    if errors:
        return {
            key: {
                "locator": locator,
                "receipt": {
                    "value_sort": "unknown",
                    "payload_safety": "unknown",
                    "status": "error",
                    "route": "locator_generation_error",
                    "reason_codes": ["locator_generation_error"],
                },
            }
            for key, locator in locators_by_key.items()
        }, errors
    if not locators_by_key:
        return {}, []
    if no_lean:
        return {
            key: {
                "locator": locator,
                "receipt": {
                    "value_sort": "unknown",
                    "payload_safety": "unknown",
                    "status": "error",
                    "route": "lean_skipped",
                    "reason_codes": ["lean_skipped"],
                },
            }
            for key, locator in locators_by_key.items()
        }, [
            "Lean recursive-field proposition-sort verification was skipped by --no-lean"
        ]
    try:
        receipts_by_identity = run_lean_recursive_field_proposition_sorts(
            root,
            import_module,
            list(locators_by_key.values()),
            timeout_seconds=SOURCE_RECORD_LEAN_ELABORATION_TIMEOUT_SECONDS,
            build_timeout_seconds=SOURCE_RECORD_LAKE_BUILD_TIMEOUT_SECONDS,
            diagnostics_out=diagnostics_out,
        )
    except Exception as exc:  # noqa: BLE001 - per-field evidence fails closed.
        return {
            key: {
                "locator": locator,
                "receipt": {
                    "value_sort": "unknown",
                    "payload_safety": "unknown",
                    "status": "error",
                    "route": "lean_exception",
                    "reason_codes": ["lean_exception"],
                },
            }
            for key, locator in locators_by_key.items()
        }, [
            "Lean recursive-field proposition-sort verification raised "
            + type(exc).__name__
            + ": "
            + str(exc)
        ]
    expected_identities = {
        str(locator["field_identity_sha256"])
        for locator in locators_by_key.values()
    }
    result: dict[str, dict[str, object]] = {}
    receipt_errors: list[str] = []
    unexpected_identities = set(receipts_by_identity) - expected_identities
    missing_identities = expected_identities - set(receipts_by_identity)
    if unexpected_identities:
        receipt_errors.append(
            "Lean recursive-field safety verification returned unexpected locators"
        )
    if missing_identities:
        receipt_errors.append(
            "Lean recursive-field safety verification did not return every requested locator; "
            f"{len(missing_identities)} exact slot receipt(s) are missing"
        )
    for key, locator in locators_by_key.items():
        identity = str(locator["field_identity_sha256"])
        receipt = receipts_by_identity.get(identity)
        if not isinstance(receipt, dict):
            result[key] = {
                "locator": locator,
                "receipt": {
                    "value_sort": "unknown",
                    "payload_safety": "unknown",
                    "status": "error",
                    "route": "missing_field_safety_receipt",
                    "reason_codes": ["missing_field_safety_receipt"],
                },
            }
            receipt_errors.append(f"{key}: missing Lean field-safety receipt")
            continue
        value_sort = str(receipt.get("value_sort") or "").strip()
        payload_safety = str(receipt.get("payload_safety") or "").strip()
        status = str(receipt.get("status") or "").strip()
        if (
            value_sort not in {"true", "false"}
            or payload_safety == "unknown"
            or status != "ok"
        ):
            receipt_errors.append(
                f"{key}: Lean field-safety receipt is not usable "
                f"(sort={value_sort or 'missing'}, payload={payload_safety or 'missing'}, "
                f"status={status or 'missing'})"
            )
        result[key] = {"locator": locator, "receipt": receipt}
    return result, receipt_errors


def constructor_field_slot_reconciliation_errors(
    *,
    root: Path,
    import_module: str,
    root_structures: Iterable[str],
    recursive_fields: list[FieldInfo],
    structures: Mapping[str, StructureInfo],
    field_safety_receipts: Mapping[str, Mapping[str, object]],
    no_lean: bool,
    diagnostics_out: dict[str, Any] | None = None,
) -> list[str]:
    """Require every reachable Lean-owned stored slot to have one receipt.

    The source parser contributes labels only as navigation.  Lean's
    constructor or structure metadata owns both existence and ordinal: every
    reachable inductive constructor and every reachable structure/class `.mk`
    constructor must have exactly one successful field-safety locator for each
    slot in its Lean-owned range before its fields can close a model record.
    """

    reachable_structures = {
        str(structure).strip()
        for structure in root_structures
        if str(structure).strip()
    }
    for field in recursive_fields:
        if field.structure.strip():
            reachable_structures.add(field.structure.strip())
        reachable_structures.update(
            nested.strip() for nested in field.nested_structures if nested.strip()
        )
    inductives = sorted(
        structure_name
        for structure_name in reachable_structures
        if structure_name in structures and structures[structure_name].kind == "inductive"
    )
    records = sorted(
        structure_name
        for structure_name in reachable_structures
        if structure_name in structures and structures[structure_name].kind != "inductive"
    )
    if not inductives and not records:
        return []
    if no_lean:
        return [
            "Lean constructor-slot reconciliation was skipped by --no-lean: "
            + ", ".join([*inductives, *records])
        ]
    inductive_diagnostics: dict[str, Any] = {}
    record_diagnostics: dict[str, Any] = {}
    try:
        counts_by_inductive = (
            run_lean_inductive_constructor_field_slot_counts(
                root,
                import_module,
                inductives,
                timeout_seconds=SOURCE_RECORD_LEAN_ELABORATION_TIMEOUT_SECONDS,
                build_timeout_seconds=SOURCE_RECORD_LAKE_BUILD_TIMEOUT_SECONDS,
                diagnostics_out=inductive_diagnostics,
            )
            if inductives
            else {}
        )
        record_constructors = [f"{record}.mk" for record in records]
        counts_by_record_constructor = (
            run_lean_constructor_field_slot_counts(
                root,
                import_module,
                record_constructors,
                timeout_seconds=SOURCE_RECORD_LEAN_ELABORATION_TIMEOUT_SECONDS,
                build_timeout_seconds=SOURCE_RECORD_LAKE_BUILD_TIMEOUT_SECONDS,
                diagnostics_out=record_diagnostics,
            )
            if record_constructors
            else {}
        )
    except Exception as exc:  # noqa: BLE001 - source slot proof debt fails closed.
        return [
            "Lean constructor-slot reconciliation raised "
            + type(exc).__name__
            + ": "
            + str(exc)
        ]
    if diagnostics_out is not None:
        diagnostics_out.clear()
        diagnostics_out.update(
            {
                "schema": 1,
                "stage": "constructor_field_slot_reconciliation",
                "stages": [
                    diagnostics
                    for diagnostics in (
                        inductive_diagnostics,
                        record_diagnostics,
                    )
                    if diagnostics
                ],
            }
        )
    if set(counts_by_inductive) != set(inductives):
        return [
            "Lean did not return exact InductInfo.ctors receipts for reachable inductives: "
            + ", ".join(inductives)
        ]
    if set(counts_by_record_constructor) != set(record_constructors):
        return [
            "Lean did not return exact StructureInfo.fieldNames receipts for reachable "
            "structure/class constructors: "
            + ", ".join(record_constructors)
        ]

    fields_by_constructor: dict[str, list[FieldInfo]] = {}
    for field in recursive_fields:
        if field.constructor_fqn.strip():
            fields_by_constructor.setdefault(field.constructor_fqn.strip(), []).append(field)

    errors: list[str] = []

    def require_exact_slots(
        constructor: str,
        expected_count: int,
        *,
        count_label: str,
    ) -> None:
        expected_slots = set(range(expected_count))
        observed_slots: list[int] = []
        for field in fields_by_constructor.get(constructor, []):
            key = f"{field.structure}.{field.field}"
            receipt_entry = field_safety_receipts.get(key)
            receipt = (
                receipt_entry.get("receipt")
                if isinstance(receipt_entry, Mapping)
                else None
            )
            index = field.constructor_argument_index
            if (
                type(index) is not int
                or index < 0
                or not isinstance(receipt, Mapping)
                or str(receipt.get("status") or "").strip() != "ok"
            ):
                errors.append(
                    f"{constructor}: field `{key}` lacks a successful exact Lean slot receipt"
                )
                continue
            observed_slots.append(index)
        if len(observed_slots) != len(set(observed_slots)):
            errors.append(
                f"{constructor}: duplicate source labels claimed one Lean stored-field slot"
            )
        observed_set = set(observed_slots)
        if observed_set != expected_slots:
            errors.append(
                f"{constructor}: source field locators cover {sorted(observed_set)} but "
                f"Lean {count_label}={expected_count} requires {sorted(expected_slots)}"
            )

    for inductive in inductives:
        structure = structures[inductive]
        counts = counts_by_inductive[inductive]
        source_constructors = {
            constructor.strip()
            for constructor in structure.constructor_names
            if constructor.strip()
        }
        lean_constructors = set(counts)
        if source_constructors != lean_constructors:
            errors.append(
                f"{inductive}: source parser constructors {sorted(source_constructors)} do not "
                f"match Lean InductInfo.ctors {sorted(lean_constructors)}"
            )
        for constructor, expected_count in counts.items():
            require_exact_slots(
                constructor,
                expected_count,
                count_label="CtorInfo.numFields",
            )
    for record in records:
        constructor = f"{record}.mk"
        require_exact_slots(
            constructor,
            counts_by_record_constructor[constructor],
            count_label="StructureInfo.fieldNames.size",
        )
    return sorted(set(errors))


def lean_type_witness_payload_safeties(
    *,
    root: Path,
    import_module: str,
    qualified_declarations: list[str],
    no_lean: bool,
    diagnostics_out: dict[str, Any] | None = None,
) -> tuple[dict[str, list[dict[str, object]]], list[str]]:
    """Return Lean receipts for Type witnesses produced by reviewed results.

    This closes the old parser-only certificate route.  `Nonempty`, `Exists`,
    and arbitrary proposition wrappers are traversed from the elaborated result
    expression.  Lean excludes witnesses that occur only in an implication
    antecedent or beneath `Not`; local source record names are only optional
    presentation data.
    """

    requested = [
        declaration.strip()
        for declaration in qualified_declarations
        if declaration.strip()
    ]
    declarations = sorted(set(requested))
    if len(declarations) != len(requested):
        return {}, ["duplicate elaborated Type-witness declaration identity"]
    if not declarations:
        return {}, []
    if no_lean:
        return {}, [
            "Lean Type-witness payload-safety verification was skipped by --no-lean"
        ]
    try:
        receipts = run_lean_type_witness_payload_safeties(
            root,
            import_module,
            declarations,
            timeout_seconds=SOURCE_RECORD_LEAN_ELABORATION_TIMEOUT_SECONDS,
            build_timeout_seconds=SOURCE_RECORD_LAKE_BUILD_TIMEOUT_SECONDS,
            diagnostics_out=diagnostics_out,
        )
    except Exception as exc:  # noqa: BLE001 - source proof debt fails closed.
        return {}, [
            "Lean Type-witness payload-safety verification raised "
            + type(exc).__name__
            + ": "
            + str(exc)
        ]
    errors: list[str] = []
    unexpected_declarations = sorted(set(receipts) - set(declarations))
    missing_declarations = sorted(set(declarations) - set(receipts))
    if unexpected_declarations:
        errors.append(
            "Lean Type-witness payload-safety verification returned unexpected "
            "reviewed declaration identities: "
            + ", ".join(unexpected_declarations)
        )
    # A successful declaration with no Type-valued witness is represented by
    # an empty *present* list.  An absent mapping entry is different: Lean
    # failed to provide a receipt for that exact reviewed result even after
    # the runner isolated it from any failed batch. Keep all independent
    # receipts, but make each unresolved declaration an explicit closeout
    # failure rather than silently accepting it as witness-free.
    for declaration in missing_declarations:
        errors.append(
            f"{declaration}: Lean Type-witness payload-safety verification "
            "returned no valid receipt after declaration-local isolation; "
            "this is not an empty witness list"
        )
    for declaration, declaration_receipts in receipts.items():
        if not isinstance(declaration_receipts, list):
            errors.append(f"{declaration}: malformed Type-witness receipt list")
            continue
        seen_paths: set[str] = set()
        for receipt in declaration_receipts:
            if not isinstance(receipt, dict):
                errors.append(f"{declaration}: malformed Type-witness receipt")
                continue
            path = str(receipt.get("path") or "").strip()
            occurrence_role = str(receipt.get("occurrence_role") or "").strip()
            witness_type_head = receipt.get("witness_type_head")
            value_sort = str(receipt.get("value_sort") or "").strip()
            payload_safety = str(receipt.get("payload_safety") or "").strip()
            status = str(receipt.get("status") or "").strip()
            if (
                not path
                or path in seen_paths
                or occurrence_role != "provided_result"
                or not isinstance(witness_type_head, str)
                or value_sort != "false"
                or payload_safety
                not in {
                    "structural_data",
                    "requires_source_or_lean_closure",
                    "requires_semantic_route",
                    "unknown",
                }
                or status not in {"ok", "error"}
            ):
                errors.append(
                    f"{declaration}: unusable Type-witness receipt at {path or '<missing path>'}"
                )
            seen_paths.add(path)
    return receipts, errors


def reviewed_declaration_identity(
    qualified_declaration: object, declaration_source: object
) -> dict[str, str] | None:
    """Return the content-pinned identity of one reviewed declaration.

    Source-contract projection deliberately matches only this pair.  A row
    label, binder spelling, short declaration name, or function name is not a
    semantic identity and must never route source credit between audit lanes.
    """

    qualified = semantic_contract_fully_qualified_identity(qualified_declaration)
    source = str(declaration_source or "")
    if not qualified or not source.strip():
        return None
    return {
        "qualified_declaration": qualified,
        "declaration_sha256": hashlib.sha256(source.encode("utf-8")).hexdigest(),
    }


def reviewed_declaration_identity_key(identity: object) -> tuple[str, str] | None:
    """Parse an exact generated declaration identity without name fallbacks."""

    if not isinstance(identity, dict):
        return None
    qualified = semantic_contract_fully_qualified_identity(
        identity.get("qualified_declaration")
    )
    source_digest = str(identity.get("declaration_sha256") or "").strip().lower()
    if not qualified or not re.fullmatch(r"[0-9a-f]{64}", source_digest):
        return None
    return qualified, source_digest


def reviewed_elaborated_signature_identity(
    reviewed_identity: object,
    elaborated_signature_sha256_by_qualified: dict[str, str],
) -> dict[str, str] | None:
    """Bind one generated association to its current configured Lean signature.

    The declaration spelling is retained for exact route validation, while the
    elaborated signature digest is the Lean-owned part of semantic reuse.  A
    missing or stale manifest deliberately makes the association exact-only;
    it never permits a human response to reconstruct a signature from a row,
    source-map key, or function name.
    """

    identity_key = reviewed_declaration_identity_key(reviewed_identity)
    if identity_key is None:
        return None
    qualified, _source_digest = identity_key
    signature_digest = str(
        elaborated_signature_sha256_by_qualified.get(qualified) or ""
    ).strip().lower()
    if not SHA256_RE.fullmatch(signature_digest):
        return None
    return {
        "qualified_declaration": qualified,
        "elaborated_signature_sha256": signature_digest,
    }


def semantic_source_association_digest(
    source_identities: list[dict[str, Any]],
    reviewed_signature_identity: object,
) -> str:
    """Return the keyless source-plus-signature identity for safe reuse.

    Full map-item hashes, source-map keys, and the current fully-qualified
    declaration remain in the surrounding association for aggregate route
    integrity. They are intentionally absent from this narrow digest, which
    is used only after the current generated route has been validated uniquely.
    Lean's elaborated signature, rather than a declaration spelling, is the
    Lean-side identity that permits semantic reuse.
    """

    if not isinstance(reviewed_signature_identity, dict):
        return ""
    qualified = semantic_contract_fully_qualified_identity(
        reviewed_signature_identity.get("qualified_declaration")
    )
    signature_digest = str(
        reviewed_signature_identity.get("elaborated_signature_sha256") or ""
    ).strip().lower()
    source_digests: list[str] = []
    for identity in source_identities:
        if not isinstance(identity, dict):
            return ""
        source_digest = str(
            identity.get("source_semantic_sha256") or ""
        ).strip().lower()
        if not SHA256_RE.fullmatch(source_digest):
            return ""
        source_digests.append(source_digest)
    if (
        not qualified
        or not SHA256_RE.fullmatch(signature_digest)
        or not source_digests
        or len(set(source_digests)) != len(source_digests)
    ):
        return ""
    source_digests.sort()
    return stable_digest(
        {
            "schema": 2,
            "source_item_semantic_sha256": source_digests,
            "elaborated_signature_sha256": signature_digest,
        }
    )


def semantic_contract_expand_surface_type(
    type_text: str,
    proposition_aliases: dict[str, PropositionAliasInfo],
    type_aliases: dict[str, TypeAliasInfo] | None,
    *,
    context_namespace: str,
    proposition_alias_missing_argument_bindings: (
        Mapping[str, Mapping[str, str]] | None
    ) = None,
) -> str:
    """Expand transparent proposition/type aliases for contract comparison.

    This is intentionally the same bounded transparent expansion used for the
    semantic-model surface.  It is not a theorem prover: an opaque or failed
    expansion remains syntactically visible and therefore prevents a mismatch
    from being collapsed accidentally.
    """

    scoped_proposition_aliases = proposition_aliases_in_namespace(
        proposition_aliases, context_namespace
    )
    scoped_type_aliases = semantic_type_aliases_in_namespace(
        type_aliases, context_namespace
    )
    expanded = normalize_ws(type_text)
    seen: set[str] = set()
    for _ in range(64):
        key = canonical_type(expanded)
        if key in seen:
            break
        seen.add(key)
        unfolded = unfold_proposition_aliases(
            expanded,
            scoped_proposition_aliases,
            missing_argument_bindings=proposition_alias_missing_argument_bindings,
        )
        unfolded = unfold_semantic_type_aliases(unfolded, scoped_type_aliases)
        if canonical_type(unfolded) == key:
            break
        expanded = unfolded
    return normalize_ws(expanded)


def semantic_contract_replace_bound_identifiers(
    text: str, replacements: dict[str, str]
) -> str:
    """Apply a declaration-signature alpha-renaming without touching namespaced heads."""

    normalized = normalize_ws(text)
    for source, target in sorted(
        replacements.items(), key=lambda item: (-len(item[0]), item[0])
    ):
        normalized = re.sub(
            rf"(?<![\w'.]){re.escape(source)}(?![\w'.])",
            target,
            normalized,
        )
    return normalized


def semantic_contract_aligned_header_alias_bindings(
    *,
    evidence_declaration: str,
    evidence_context_namespace: str,
    spec_declaration: str,
    spec_qualified_name: str,
    spec_context_namespace: str,
    proposition_aliases: dict[str, PropositionAliasInfo],
    type_aliases: dict[str, TypeAliasInfo] | None,
) -> dict[str, dict[str, str]] | None:
    """Bind omitted Spec arguments only after exact header-surface alignment.

    Lean normally infers leading implicit parameters when a theorem result
    applies a proposition-valued ``Spec`` with only its explicit arguments.
    The source-level alias expander cannot infer those terms on its own and
    otherwise emits ``__propArg*`` placeholders.  Within an explicit
    theorem/Spec contract pair, both declarations expose their full header
    telescopes.  We may therefore use the corresponding evidence binders only
    when every binder group's arity and alpha-normalized dependent domain agree
    in declaration order.  Any ambiguity, malformed binder, alias/header
    disagreement, or structural difference returns no binding and leaves the
    ordinary mismatch path intact.
    """

    evidence_inputs = header_inputs_from_declaration(evidence_declaration)
    spec_inputs = header_inputs_from_declaration(spec_declaration)
    if len(evidence_inputs) != len(spec_inputs):
        return None

    evidence_replacements: dict[str, str] = {}
    spec_replacements: dict[str, str] = {}
    evidence_names: list[str] = []
    spec_names: list[str] = []
    bound_index = 0
    for evidence_input, spec_input in zip(evidence_inputs, spec_inputs):
        current_evidence_names = binder_names(
            str(evidence_input.get("names") or "")
        )
        current_spec_names = binder_names(str(spec_input.get("names") or ""))
        if (
            not current_evidence_names
            or len(current_evidence_names) != len(current_spec_names)
        ):
            return None
        evidence_type = semantic_contract_expand_surface_type(
            str(evidence_input.get("type") or ""),
            proposition_aliases,
            type_aliases,
            context_namespace=evidence_context_namespace,
        )
        spec_type = semantic_contract_expand_surface_type(
            str(spec_input.get("type") or ""),
            proposition_aliases,
            type_aliases,
            context_namespace=spec_context_namespace,
        )
        if (
            not evidence_type
            or not spec_type
            or alpha_canonical_type(
                semantic_contract_replace_bound_identifiers(
                    evidence_type, evidence_replacements
                )
            )
            != alpha_canonical_type(
                semantic_contract_replace_bound_identifiers(
                    spec_type, spec_replacements
                )
            )
        ):
            return None
        for evidence_name, spec_name in zip(
            current_evidence_names, current_spec_names
        ):
            evidence_names.append(evidence_name)
            spec_names.append(spec_name)
            replacement = f"_contractBound{bound_index}"
            evidence_replacements[evidence_name] = replacement
            spec_replacements[spec_name] = replacement
            bound_index += 1

    aliases_by_identity = proposition_aliases_by_identity(proposition_aliases)
    spec_alias = aliases_by_identity.get(spec_qualified_name)
    if spec_alias is None:
        return {}
    parameters = list(spec_alias.parameters)
    if (
        parameters != spec_names
        or len(parameters) != len(evidence_names)
        or len(set(parameters)) != len(parameters)
        or len(set(evidence_names)) != len(evidence_names)
    ):
        return {}
    return {
        spec_alias.name: {
            parameter: evidence_name
            for parameter, evidence_name in zip(parameters, evidence_names)
        }
    }


def semantic_contract_scoped_alias_missing_argument_bindings(
    bindings: Mapping[str, Mapping[str, str]] | None,
    available_names: set[str],
) -> dict[str, dict[str, str]]:
    """Restrict omitted-alias substitutions to the current binder scope."""

    scoped: dict[str, dict[str, str]] = {}
    for alias, parameter_bindings in (bindings or {}).items():
        if not isinstance(parameter_bindings, Mapping):
            continue
        available = {
            str(parameter): str(argument)
            for parameter, argument in parameter_bindings.items()
            if str(parameter).strip()
            and str(argument).strip()
            and str(argument) in available_names
        }
        if available:
            scoped[str(alias)] = available
    return scoped


def semantic_contract_direct_positional_spec_application(
    type_text: str,
    *,
    spec_qualified_name: str,
    evidence_context_namespace: str,
    parameter_count: int,
) -> tuple[bool, int | None]:
    """Recognize one complete positional reference to the mapped Spec.

    The first result says whether the expression's head resolves to the exact
    mapped Spec.  The second is its positional argument count, or ``None``
    when that exact reference has a non-positional, partial, or otherwise
    unparseable application.  Callers must reject the latter rather than use
    surrounding binders to guess named arguments.
    """

    text = normalize_ws(strip_outer_group(type_text)).strip()
    match = _PROPOSITION_ALIAS_IDENTIFIER_RE.match(text)
    if match is None or match.start() != 0:
        return False, None
    raw_head = match.group(1).lstrip("@")
    if lexical_name_candidates(
        raw_head,
        {spec_qualified_name},
        context_namespace=evidence_context_namespace,
    ) != [spec_qualified_name]:
        return False, None

    cursor = match.end()
    argument_count = 0
    while True:
        while cursor < len(text) and text[cursor].isspace():
            cursor += 1
        if cursor == len(text):
            return True, argument_count
        span = _next_proposition_alias_argument_span(text, cursor)
        if span is None:
            return True, None
        start, end = span
        argument = text[start:end]
        if ":=" in argument or argument_count >= parameter_count:
            return True, None
        argument_count += 1
        cursor = end


def semantic_contract_missing_spec_argument_bindings_for_result(
    *,
    evidence_declaration: str,
    evidence_context_namespace: str,
    result_surface: str,
    spec_declaration: str,
    spec_qualified_name: str,
    spec_context_namespace: str,
    proposition_aliases: dict[str, PropositionAliasInfo],
    type_aliases: dict[str, TypeAliasInfo] | None,
) -> dict[str, dict[str, str]] | None:
    """Return safe omitted-parameter bindings for one direct Spec result.

    A non-Spec result has no special treatment.  An exact mapped Spec head
    must be a complete positional application and must have an exactly aligned
    theorem/Spec header before omitted leading parameters may be represented by
    the corresponding theorem binders.  This is intentionally narrower than
    arbitrary Lean elaboration: named, malformed, or structurally misaligned
    applications remain unmatched.
    """

    spec_alias = proposition_aliases_by_identity(proposition_aliases).get(
        spec_qualified_name
    )
    if spec_alias is None:
        return {}
    is_direct_spec, argument_count = (
        semantic_contract_direct_positional_spec_application(
            result_surface,
            spec_qualified_name=spec_qualified_name,
            evidence_context_namespace=evidence_context_namespace,
            parameter_count=len(spec_alias.parameters),
        )
    )
    if not is_direct_spec:
        return {}
    if argument_count is None:
        return None
    return semantic_contract_aligned_header_alias_bindings(
        evidence_declaration=evidence_declaration,
        evidence_context_namespace=evidence_context_namespace,
        spec_declaration=spec_declaration,
        spec_qualified_name=spec_qualified_name,
        spec_context_namespace=spec_context_namespace,
        proposition_aliases=proposition_aliases,
        type_aliases=type_aliases,
    )


def semantic_contract_signature_surface(
    declaration: str,
    result_surface: str,
    proposition_aliases: dict[str, PropositionAliasInfo],
    type_aliases: dict[str, TypeAliasInfo] | None,
    *,
    context_namespace: str,
    proposition_alias_missing_argument_bindings: (
        Mapping[str, Mapping[str, str]] | None
    ) = None,
) -> dict[str, Any]:
    """Render a declaration's actual signature modulo alpha-renaming.

    For an evidence theorem ``result_surface`` is its declared result type.
    For a transparent ``Spec`` declaration it is the body of the proposition,
    *not* the declaration's raw ``: Prop`` result.  Header-domain arity and
    every expanded dependent domain remain part of the comparison so changing
    a model input cannot be hidden behind an alpha-equivalent terminal formula.
    """

    replacements: dict[str, str] = {}
    binder_domains: list[dict[str, Any]] = []
    available_names: set[str] = set()
    bound_index = 0
    for visible_input in header_inputs_from_declaration(declaration):
        names = binder_names(str(visible_input.get("names") or ""))
        expanded_type = semantic_contract_expand_surface_type(
            str(visible_input.get("type") or ""),
            proposition_aliases,
            type_aliases,
            context_namespace=context_namespace,
            proposition_alias_missing_argument_bindings=(
                semantic_contract_scoped_alias_missing_argument_bindings(
                    proposition_alias_missing_argument_bindings,
                    available_names,
                )
            ),
        )
        binder_domains.append(
            {
                "arity": len(names),
                "alpha_normalized_type": alpha_canonical_type(
                    semantic_contract_replace_bound_identifiers(
                        expanded_type, replacements
                    )
                ),
            }
        )
        for name in names:
            replacements[name] = f"_contractBound{bound_index}"
            available_names.add(name)
            bound_index += 1
    expanded_result = semantic_contract_expand_surface_type(
        result_surface,
        proposition_aliases,
        type_aliases,
        context_namespace=context_namespace,
        proposition_alias_missing_argument_bindings=(
            proposition_alias_missing_argument_bindings
        ),
    )
    return {
        "binder_domains": binder_domains,
        "alpha_normalized_result": alpha_canonical_type(
            semantic_contract_replace_bound_identifiers(
                expanded_result, replacements
            )
        ),
    }


def semantic_contract_result_type_candidates(declaration: str) -> list[str]:
    """Return every syntactic result prefix before a top-level ``:=``.

    This exists only for direct/Spec structural comparison.  A theorem result
    can itself begin with ``let x := ...``; the ordinary declaration parser
    must stop at a declaration body marker for many unrelated callers, but a
    first textual assignment would truncate that theorem type.  Comparing each
    candidate against the transparent Spec body is conservative: only one
    alpha-equal candidate is accepted below, and any ambiguity leaves both
    semantic-model rows individual.
    """

    signature_split = split_top_level_colon(declaration)
    if signature_split is None:
        return []
    result_and_body = signature_split[1]
    candidates: list[str] = []
    depth = 0
    index = 0
    while index < len(result_and_body):
        char = result_and_body[index]
        if char in "([{⦃":
            depth += 1
            index += 1
            continue
        if char in (")", "]", "}", "⦄") and depth > 0:
            depth -= 1
            index += 1
            continue
        if depth == 0 and result_and_body.startswith(":=", index):
            candidate = normalize_ws(result_and_body[:index])
            if candidate:
                candidates.append(candidate)
            index += 2
            continue
        index += 1
    return list(dict.fromkeys(candidates))


def semantic_model_transparent_spec_body(declaration: str) -> str:
    """Return an inspectable ``def``/``abbrev`` proposition body, if present."""

    declaration_match = DECL_RE.match(declaration)
    if (
        declaration_match is None
        or declaration_match.group(1) not in {"def", "abbrev"}
        or canonical_type(declaration_result_type(declaration)) != "Prop"
    ):
        return ""
    body = declaration_body_text(declaration)
    if not body or re.match(r"^by\b", body.strip()):
        return ""
    return body


ELABORATED_BARE_SPEC_REFERENCE_MODE = (
    "lean_elaborated_bare_transparent_spec_reference"
)


def semantic_contract_bare_result_reference_matches(
    *,
    evidence_qualified_name: str,
    evidence_source: str,
    spec_qualified_name: str,
) -> bool:
    """Whether the evidence result is exactly the mapped declaration reference.

    The spelling is only a coordinate for Lean's dependency graph below.  A
    wrapper, application, implication, conjunction, or repeated occurrence is
    rejected even if it happens to mention the mapped Spec.  The explicit
    source-map identity supplies the sole resolution candidate, so neither a
    suffix convention nor a repository-wide short-name search participates.
    """

    result = strip_outer_group(declaration_result_type(evidence_source)).strip()
    match = re.fullmatch(
        rf"@?\s*({LEAN_QUALIFIED_NAME_PATTERN})\s*",
        result,
    )
    if match is None:
        return False
    context_namespace = (
        evidence_qualified_name.rsplit(".", 1)[0]
        if "." in evidence_qualified_name
        else ""
    )
    return lexical_name_candidates(
        match.group(1),
        {spec_qualified_name},
        context_namespace=context_namespace,
    ) == [spec_qualified_name]


def semantic_contract_elaborated_bare_spec_surfaces(
    *,
    evidence_qualified_name: str,
    evidence_source: str,
    evidence_manifest: Mapping[str, Any] | None,
    spec_qualified_name: str,
    spec_source: str,
    spec_manifest: Mapping[str, Any] | None,
) -> tuple[dict[str, Any], dict[str, Any]] | None:
    """Validate a bare theorem/Spec pair using Lean-owned semantic graphs.

    Tactic-bodied proposition definitions have no trustworthy text-parsed body,
    but Lean still exposes their transparent value as a complete rooted graph.
    Such a Spec can own a theorem's semantic surface only when the theorem's
    source result is a bare reference to the exact mapped identity and Lean's
    normalized dependency graph contains that identity as the theorem root's
    *only* direct type dependency.  This deliberately consumes the generic Lean
    graph protocol; it does not reconstruct a proposition or telescope in
    Python and does not inspect declaration-name patterns.
    """

    evidence_kind = DECL_RE.match(evidence_source)
    spec_kind = DECL_RE.match(spec_source)
    if (
        evidence_kind is None
        or evidence_kind.group(1) not in {"theorem", "lemma"}
        or spec_kind is None
        or spec_kind.group(1) not in {"def", "abbrev"}
        or canonical_type(declaration_result_type(spec_source)) != "Prop"
        or header_inputs_from_declaration(spec_source)
        or not isinstance(evidence_manifest, Mapping)
        or not isinstance(spec_manifest, Mapping)
        or evidence_manifest.get("declaration_kind") != "theorem"
        or spec_manifest.get("declaration_kind") != "definition"
        or spec_manifest.get("conclusion_mode") != "type_and_value"
        or not semantic_contract_bare_result_reference_matches(
            evidence_qualified_name=evidence_qualified_name,
            evidence_source=evidence_source,
            spec_qualified_name=spec_qualified_name,
        )
    ):
        return None

    dependency_graph = normalize_semantic_dependency_graph(
        evidence_manifest.get("semantic_dependency_graph")
    )
    transparent_graph = normalize_elaborated_proposition_graph(
        spec_manifest.get("elaborated_transparent_result_value_graph")
    )
    if (
        not isinstance(dependency_graph, Mapping)
        or dependency_graph.get("complete") is not True
        or dependency_graph.get("root_declaration") != evidence_qualified_name
        or not isinstance(transparent_graph, Mapping)
        or transparent_graph.get("complete") is not True
    ):
        return None

    direct_type_edges = [
        edge
        for edge in dependency_graph.get("edges", [])
        if isinstance(edge, Mapping)
        and edge.get("source") == evidence_qualified_name
        and edge.get("role") == "type_uses_constant"
    ]
    if direct_type_edges != [
        {
            "source": evidence_qualified_name,
            "target": spec_qualified_name,
            "role": "type_uses_constant",
        }
    ]:
        return None
    spec_nodes = [
        node
        for node in dependency_graph.get("nodes", [])
        if isinstance(node, Mapping)
        and node.get("declaration") == spec_qualified_name
        and node.get("statement_reachable") is True
        and node.get("declaration_kind") == "definition"
    ]
    transparent_roots = [
        node
        for node in transparent_graph.get("nodes", [])
        if isinstance(node, Mapping) and node.get("path") == "result"
    ]
    if len(spec_nodes) != 1 or len(transparent_roots) != 1:
        return None

    semantic_surface = {
        "schema": 1,
        "validation_mode": ELABORATED_BARE_SPEC_REFERENCE_MODE,
        "evidence_type_dependency_graph_sha256": dependency_graph[
            "semantic_graph_sha256"
        ],
        "spec_transparent_result_value_graph_sha256": transparent_graph[
            "semantic_graph_sha256"
        ],
        "spec_transparent_result_root_semantic_sha256": transparent_roots[0][
            "semantic_sha256"
        ],
    }
    return dict(semantic_surface), dict(semantic_surface)


def semantic_model_tactic_exact_presentation_body(declaration: str) -> str:
    """Extract a final ``exact`` term for display after Lean graph validation.

    This helper supplies binder spellings and source navigation only.  It must
    never establish transparency or equality; callers use it exclusively after
    :func:`semantic_contract_elaborated_bare_spec_surfaces` has authenticated
    the complete transparent value through Lean.
    """

    body = declaration_body_text(declaration)
    match = re.fullmatch(
        r"by(?:\s+classical)*\s+exact\s+([\s\S]+)",
        body.strip(),
    )
    return match.group(1).strip() if match is not None else ""


def semantic_model_strip_anonymous_layout_result_lets(term: str) -> tuple[str, int]:
    """Remove parser-only anonymous result lets whose body starts a forall.

    Lean's theorem manifest has already flattened these anonymous local-instance
    lets into the exact outer telescope.  The source parser needs only the
    following binder spellings.  We therefore remove a layout block solely when
    its head binds ``_`` and the next line at the same indentation begins a
    universal binder.  Named lets, inline lets, nested terms, and ambiguous
    layouts remain untouched and fail closed through the manifest arity checks.
    """

    lines = term.splitlines()
    kept: list[str] = []
    removed = 0
    index = 0
    while index < len(lines):
        line = lines[index]
        stripped = line.lstrip()
        indent = len(line) - len(stripped)
        if re.match(r"^let(?:I)?\s+_\s*(?::|:=)", stripped):
            next_index = index + 1
            while next_index < len(lines):
                candidate = lines[next_index]
                candidate_stripped = candidate.lstrip()
                if not candidate_stripped:
                    next_index += 1
                    continue
                candidate_indent = len(candidate) - len(candidate_stripped)
                if candidate_indent <= indent:
                    break
                next_index += 1
            if (
                next_index < len(lines)
                and len(lines[next_index]) - len(lines[next_index].lstrip()) == indent
                and (
                    lines[next_index].lstrip().startswith("∀")
                    or re.match(r"^forall\b", lines[next_index].lstrip())
                )
            ):
                removed += 1
                index = next_index
                continue
        kept.append(line)
        index += 1
    return "\n".join(kept), removed


def semantic_model_strip_classical_decidable_eq_layout_instance(term: str) -> str:
    """Expose a following universal body after one canonical local instance.

    A proposition ``Spec`` occasionally needs a local decidable equality only
    to elaborate a lower-level finite construction.  That instance is not a
    caller-supplied source assumption, and Lean flattens it before exposing the
    theorem's outer telescope.  The parser may therefore remove it *only* from
    its presentation projection after the caller has already established the
    exact direct/Spec structural pair.

    This is intentionally much narrower than general local-let reduction.  It
    accepts exactly an anonymous layout binding of the form

    ``letI : DecidableEq A := Classical.decEq A``

    whose immediately following layout body is a universal proposition.  The
    class head, canonical provider, and their argument must agree
    structurally.  Named instances, other classes, arbitrary providers,
    mismatched arguments, inline syntax, and non-universal bodies are retained
    unchanged.  In particular, this helper never decides semantic equality of
    a general local definition from source text.
    """

    lines = term.splitlines()
    if len(lines) < 2:
        return term

    binding_line = lines[0]
    binding_indent = len(binding_line) - len(binding_line.lstrip())
    binding = binding_line.strip()
    if not re.match(r"^letI(?:\s|:)", binding):
        return term
    suffix = binding[len("letI") :].strip()
    # An omitted binder name is important: a named local instance can be used
    # explicitly in the proposition body, so source presentation must retain
    # it even when its type happens to be a standard instance class.
    if not suffix.startswith(":"):
        return term
    assignment_index = top_level_token_index(suffix, ":=")
    if assignment_index is None:
        return term
    declared_type = suffix[1:assignment_index].strip()
    provider = suffix[assignment_index + 2 :].strip()
    declared_terms = split_top_level_terms(strip_outer_group(declared_type))
    provider_terms = split_top_level_terms(strip_outer_group(provider))
    if (
        len(declared_terms) != 2
        or declared_terms[0] != "DecidableEq"
        or len(provider_terms) != 2
        or provider_terms[0] not in {"Classical.decEq", "@Classical.decEq"}
        or canonical_type(declared_terms[1])
        != canonical_type(provider_terms[1])
    ):
        return term

    body_line = lines[1]
    body_indent = len(body_line) - len(body_line.lstrip())
    body_head = body_line.lstrip()
    if body_indent <= binding_indent or not (
        body_head.startswith("∀") or re.match(r"^forall\b", body_head)
    ):
        return term
    return "\n".join(lines[1:])


def semantic_model_spec_analysis_declaration(
    declaration: str,
    structural_surface: Mapping[str, Any],
) -> str:
    """Return a parser-facing Spec declaration without granting text credit."""

    presentation_body = declaration_body_text(declaration)
    if (
        structural_surface.get("validation_mode")
        == ELABORATED_BARE_SPEC_REFERENCE_MODE
        and not semantic_model_transparent_spec_body(declaration)
    ):
        presentation_body = semantic_model_tactic_exact_presentation_body(declaration)
    body_start = declaration_body_start_index(declaration)
    if not presentation_body or body_start is None:
        return ""
    # The direct/Spec structural gate above this projection has already
    # established the full proposition surface.  Remove only the narrow,
    # canonical classical instance recognized by the helper so the parser can
    # recover the same result binders Lean exposes in that verified surface.
    presentation_body = semantic_model_strip_classical_decidable_eq_layout_instance(
        presentation_body
    )
    presentation_body, _removed_lets = (
        semantic_model_strip_anonymous_layout_result_lets(presentation_body)
    )
    return declaration[: body_start + 2] + " " + presentation_body


def semantic_contract_pair_structural_surfaces(
    *,
    evidence_qualified_name: str,
    evidence_source: str,
    spec_qualified_name: str,
    spec_source: str,
    proposition_aliases: dict[str, PropositionAliasInfo],
    type_aliases: dict[str, TypeAliasInfo] | None,
    evidence_manifest: Mapping[str, Any] | None = None,
    spec_manifest: Mapping[str, Any] | None = None,
) -> tuple[dict[str, Any], dict[str, Any]] | None:
    """Return exact alpha-normalized evidence/Spec surfaces when they agree.

    This is the shared gate for grouping a proof theorem with a transparent
    proposition Spec and for using that Spec as the proof theorem's semantic
    binder surface.  It is entirely structural. An inspectable term body uses
    bounded alpha-normalized comparison; a tactic-bodied Spec instead requires
    a bare mapped result reference, Lean's exact type-dependency edge, and its
    complete transparent result-value graph. Declaration suffixes and function
    names play no role.
    """

    evidence_kind_match = DECL_RE.match(evidence_source)
    spec_kind_match = DECL_RE.match(spec_source)
    if (
        evidence_kind_match is None
        or evidence_kind_match.group(1) not in {"theorem", "lemma"}
        or spec_kind_match is None
        or spec_kind_match.group(1) not in {"def", "abbrev"}
        or canonical_type(declaration_result_type(spec_source)) != "Prop"
    ):
        return None
    spec_body = semantic_model_transparent_spec_body(spec_source)
    # A proof endpoint in a sibling ProofInterface commonly has the exact
    # source-facing Spec as its whole result type.  Its theorem text therefore
    # has no duplicated binders to compare against the transparent Spec body.
    # Accept that layout only through the complete Lean-owned direct type edge
    # and transparent-value graph; the helper rejects wrappers, applications,
    # and any additional type dependency.
    bare_surfaces = semantic_contract_elaborated_bare_spec_surfaces(
        evidence_qualified_name=evidence_qualified_name,
        evidence_source=evidence_source,
        evidence_manifest=evidence_manifest,
        spec_qualified_name=spec_qualified_name,
        spec_source=spec_source,
        spec_manifest=spec_manifest,
    )
    if bare_surfaces is not None:
        return bare_surfaces
    if not spec_body:
        return None
    evidence_context = evidence_qualified_name.rsplit(".", 1)[0]
    spec_context = spec_qualified_name.rsplit(".", 1)[0]
    spec_surface = semantic_contract_signature_surface(
        spec_source,
        spec_body,
        proposition_aliases,
        type_aliases,
        context_namespace=spec_context,
    )
    candidate_surfaces: dict[str, dict[str, Any]] = {}
    for result_candidate in semantic_contract_result_type_candidates(evidence_source):
        missing_argument_bindings = (
            semantic_contract_missing_spec_argument_bindings_for_result(
                evidence_declaration=evidence_source,
                evidence_context_namespace=evidence_context,
                result_surface=result_candidate,
                spec_declaration=spec_source,
                spec_qualified_name=spec_qualified_name,
                spec_context_namespace=spec_context,
                proposition_aliases=proposition_aliases,
                type_aliases=type_aliases,
            )
        )
        if missing_argument_bindings is None:
            continue
        candidate_surface = semantic_contract_signature_surface(
            evidence_source,
            result_candidate,
            proposition_aliases,
            type_aliases,
            context_namespace=evidence_context,
            proposition_alias_missing_argument_bindings=(
                missing_argument_bindings
            ),
        )
        candidate_surfaces.setdefault(
            json.dumps(candidate_surface, sort_keys=True, separators=(",", ":")),
            candidate_surface,
        )
    matching_surfaces = [
        surface for surface in candidate_surfaces.values() if surface == spec_surface
    ]
    if len(matching_surfaces) != 1:
        return None
    return matching_surfaces[0], spec_surface


def semantic_model_terminal_result_surface(declaration: str) -> tuple[str, str]:
    """Select the result audited for one row without treating ``Spec : Prop`` as data.

    A transparent proposition Spec has a semantically meaningful body while
    its raw declared result is just ``Prop``.  Expose that body to the model
    audit; opaque/tactic-defined wrappers remain ordinary (and therefore do
    not receive an unearned expansion).
    """

    transparent_spec_body = semantic_model_transparent_spec_body(declaration)
    if transparent_spec_body:
        return transparent_spec_body, "transparent_spec_body"
    return declaration_terminal_result_type(declaration), "declared_terminal_result"


ELABORATED_TERMINAL_RESULT_RECEIPT_SCHEMA = 1


def elaborated_terminal_result_receipt(
    manifest: Mapping[str, Any] | None,
) -> dict[str, Any] | None:
    """Return Lean's name-independent conclusion atom for one review row.

    Text parsing cannot recover the semantic value of declarations such as
    ``abbrev X (A : Type*) := A -> Real``: their declared result annotation is
    absent, while the elaborated result is itself a type-valued definition.
    Lean's signature manifest already owns the canonical conclusion atom.
    Preserve that atom and its manifest digest as semantic evidence; the
    pretty-printed display is retained only as a human-facing fallback.
    """

    if not isinstance(manifest, Mapping):
        return None
    manifest_digest = signature_manifest_digest(dict(manifest))
    atoms = manifest.get("atoms")
    if not SHA256_RE.fullmatch(manifest_digest) or not isinstance(atoms, list):
        return None
    conclusions = [
        atom
        for atom in atoms
        if isinstance(atom, Mapping)
        and str(atom.get("ref") or "").strip() == "result"
        and str(atom.get("role") or "").strip() == "conclusion"
    ]
    if len(conclusions) != 1:
        return None
    conclusion = conclusions[0]
    canonical = conclusion.get("canonical")
    if not isinstance(canonical, Mapping):
        return None
    canonical_value = deepcopy(dict(canonical))
    receipt: dict[str, Any] = {
        "schema": ELABORATED_TERMINAL_RESULT_RECEIPT_SCHEMA,
        "manifest_sha256": manifest_digest,
        "conclusion_atom_sha256": stable_digest(
            {
                "role": "conclusion",
                "canonical": canonical_value,
            }
        ),
        "canonical": canonical_value,
        "display": str(conclusion.get("display") or "").strip(),
    }
    receipt["type_valued_definition"] = bool(
        canonical_value.get("tag") == "definition"
        and isinstance(canonical_value.get("type"), Mapping)
        and canonical_value["type"].get("tag") == "sort"
        and isinstance(canonical_value.get("value"), Mapping)
    )
    return receipt


def elaborated_type_valued_result_display(
    receipt: Mapping[str, Any] | None,
) -> str:
    """Return a display-only type value authenticated by a canonical receipt."""

    if not isinstance(receipt, Mapping) or receipt.get("type_valued_definition") is not True:
        return ""
    display = str(receipt.get("display") or "").strip()
    _separator, marker, value = display.partition(":=")
    return normalize_ws(value) if marker and value.strip() else ""


SEMANTIC_MODEL_REVIEW_ALIAS_MAX_DEPTH = 16
SEMANTIC_MODEL_THIN_ALIAS_BODY_RE = re.compile(
    rf"^@?\s*({LEAN_QUALIFIED_NAME_PATTERN})$"
)


def semantic_model_thin_alias_target_reference(
    declaration: LocalDeclaration,
) -> str | None:
    """Return the target of a transparent bare declaration alias.

    This is intentionally narrower than transparent-definition expansion.  A
    review alias may preserve a target theorem's elaborated type exactly only
    when its complete body is a bare local declaration reference, optionally
    preceded by ``@``.  Applications, lambdas, tactics, projections, and
    arbitrary proposition-valued definitions must remain independently
    auditable surfaces.
    """

    if declaration.kind not in {"def", "abbrev"}:
        return None
    if semantic_model_transparent_spec_body(declaration.source):
        return None
    body = normalize_ws(declaration_body_text(declaration.source)).strip()
    match = SEMANTIC_MODEL_THIN_ALIAS_BODY_RE.fullmatch(body)
    if match is None:
        return None
    reference = match.group(1)
    # A dependent field projection such as `e.posteriorEstimateKernel` is a
    # computational definition over the declaration's own binder, not a
    # declaration alias.  The distinction follows binder scope, never a
    # field/function name.  Treating projections as aliases would both hide
    # their real type and create a spurious unresolved-local-target failure.
    bound_names = {
        name
        for visible_input in visible_inputs_from_declaration(
            declaration.source, include_result_inputs=False
        )
        for name in binder_names(visible_input.get("names", ""))
    }
    root = reference.split(".", 1)[0]
    return None if root in bound_names else reference


def semantic_model_review_alias_expansion(
    *,
    reviewed_qualified_name: str,
    reviewed_declaration: str,
    semantic_declarations: list[LocalDeclaration],
    max_depth: int = SEMANTIC_MODEL_REVIEW_ALIAS_MAX_DEPTH,
) -> tuple[LocalDeclaration, dict[str, Any]]:
    """Resolve a thin paper-facing alias without trusting its empty syntax.

    The source record keeps the ``PaperInterface`` declaration as the reviewed
    identity, while the semantic comparison must inspect the declaration that
    actually carries its binders and conclusion.  Resolution is lexical and
    fail-closed: imported/missing targets, ambiguous short names, cycles, and
    depth exhaustion are recorded as incomplete rather than guessed.
    """

    by_name, _ = semantic_model_local_declaration_indexes(semantic_declarations)
    parsed = DECL_RE.match(reviewed_declaration)
    current = by_name.get(reviewed_qualified_name)
    if current is None:
        current = LocalDeclaration(
            name=reviewed_qualified_name,
            kind=parsed.group(1) if parsed is not None else "unknown",
            source=reviewed_declaration,
            source_file="",
            line=0,
        )

    def payload(
        *,
        alias_present: bool,
        complete: bool,
        steps: list[dict[str, Any]],
        blocked_routes: list[dict[str, Any]],
        effective: LocalDeclaration,
    ) -> dict[str, Any]:
        return {
            "schema": 1,
            "reviewed_declaration": reviewed_qualified_name,
            "alias_present": alias_present,
            "complete": complete,
            "effective_declaration": effective.name,
            "effective_kind": effective.kind,
            "steps": steps,
            "blocked_routes": blocked_routes,
        }

    first_target = semantic_model_thin_alias_target_reference(current)
    if first_target is None:
        return current, payload(
            alias_present=False,
            complete=True,
            steps=[],
            blocked_routes=[],
            effective=current,
        )

    current_target = first_target
    current_declaration = current
    steps: list[dict[str, Any]] = []
    seen = {current.name}
    for _ in range(max_depth):
        context_namespace = (
            current_declaration.name.rsplit(".", 1)[0]
            if "." in current_declaration.name
            else ""
        )
        candidates = lexical_name_candidates(
            current_target,
            set(by_name),
            context_namespace=context_namespace,
        )
        if len(candidates) != 1:
            route_kind = (
                "unresolved_local_target"
                if not candidates
                else "ambiguous_local_target"
            )
            return current_declaration, payload(
                alias_present=True,
                complete=False,
                steps=steps,
                blocked_routes=[
                    {
                        "kind": route_kind,
                        "from": current_declaration.name,
                        "reference": current_target,
                        "candidates": candidates,
                    }
                ],
                effective=current_declaration,
            )
        target = by_name[candidates[0]]
        step = {
            "from": current_declaration.name,
            "reference": current_target,
            "to": target.name,
            "target_kind": target.kind,
            "source_file": target.source_file,
            "line": target.line,
        }
        if target.name in seen:
            return current_declaration, payload(
                alias_present=True,
                complete=False,
                steps=[*steps, step],
                blocked_routes=[
                    {
                        "kind": "cycle",
                        "from": current_declaration.name,
                        "reference": current_target,
                        "target": target.name,
                    }
                ],
                effective=current_declaration,
            )
        steps.append(step)
        seen.add(target.name)
        current_declaration = target
        next_target = semantic_model_thin_alias_target_reference(current_declaration)
        if next_target is None:
            return current_declaration, payload(
                alias_present=True,
                complete=True,
                steps=steps,
                blocked_routes=[],
                effective=current_declaration,
            )
        current_target = next_target

    return current_declaration, payload(
        alias_present=True,
        complete=False,
        steps=steps,
        blocked_routes=[
            {
                "kind": "max_depth",
                "from": current_declaration.name,
                "max_depth": max_depth,
            }
        ],
        effective=current_declaration,
    )


def semantic_model_review_effective_surface(
    *,
    reviewed_qualified_name: str,
    reviewed_declaration: str,
    semantic_declarations: list[LocalDeclaration],
) -> SemanticModelReviewSurface:
    """Return the source text that may supply a reviewed row's semantics.

    This is deliberately structural.  It follows only a complete bare local
    ``def``/``abbrev`` alias route established by
    :func:`semantic_model_review_alias_expansion`; it neither infers a target
    from names nor treats an application or bound-variable projection as an
    alias.  An unresolved route keeps the paper-facing wrapper as the analysis
    text, while the expansion payload makes the overall audit fail closed.
    """

    effective_declaration, review_alias_expansion = (
        semantic_model_review_alias_expansion(
            reviewed_qualified_name=reviewed_qualified_name,
            reviewed_declaration=reviewed_declaration,
            semantic_declarations=semantic_declarations,
        )
    )
    uses_effective_target = bool(
        review_alias_expansion["alias_present"]
        and review_alias_expansion["complete"]
    )
    analysis_declaration = (
        effective_declaration.source
        if uses_effective_target
        else reviewed_declaration
    )
    analysis_qualified_name = (
        effective_declaration.name
        if uses_effective_target
        else reviewed_qualified_name
    )
    header_inputs = visible_inputs_from_declaration(
        analysis_declaration, include_result_inputs=False
    )
    header_bound_names = {
        name
        for visible_input in header_inputs
        for name in binder_names(visible_input.get("names", ""))
    }
    conclusion_inputs = conclusion_inputs_from_declaration(
        analysis_declaration, header_bound_names
    )
    return SemanticModelReviewSurface(
        reviewed_qualified_name=reviewed_qualified_name,
        reviewed_declaration=reviewed_declaration,
        effective_declaration=effective_declaration,
        review_alias_expansion=review_alias_expansion,
        uses_effective_target=uses_effective_target,
        analysis_qualified_name=analysis_qualified_name,
        analysis_declaration=analysis_declaration,
        header_inputs=header_inputs,
        conclusion_inputs=conclusion_inputs,
    )


def semantic_model_review_contract_companion_surfaces(
    *,
    companion_routes: Iterable[Mapping[str, object]],
    semantic_declarations: list[LocalDeclaration],
    proposition_aliases: dict[str, PropositionAliasInfo],
    type_aliases: dict[str, TypeAliasInfo] | None,
    elaborated_manifests_by_qualified: Mapping[
        str, Mapping[str, Any]
    ] | None = None,
    defer_manifest_dependent_errors: bool = False,
) -> tuple[dict[str, SemanticModelReviewSurface], list[str]]:
    """Resolve exact source-selected evidence/Spec semantic surfaces.

    Lean reduces a theorem whose result is a transparent ``Spec`` before
    emitting its telescope.  Treating those reduced forall binders as if they
    were source-written theorem inputs duplicates the Spec's proposition and
    can manufacture assumptions.  This helper permits the Spec declaration to
    own that semantic surface only through an explicit fully-qualified source
    contract, an unambiguous one-to-one pair, and the same structural equality
    gate used by direct/Spec semantic-model grouping.

    Any malformed, ambiguous, missing, or unequal route is returned as a hard
    audit error.  No declaration-name or suffix heuristic is used.  The one
    exception is an explicitly provisional scheduling pass: when
    ``defer_manifest_dependent_errors`` is true, a tactic-bodied proposition
    pair whose equality can only be established from Lean's graphs is left
    unresolved without granting a surface or emitting a lasting error.  A
    caller using that mode must repeat this helper with the complete manifest
    set before consuming any generated binder or premise surface.
    """

    declarations_by_name, _ = semantic_model_local_declaration_indexes(
        semantic_declarations
    )
    elaborated_manifests_by_qualified = elaborated_manifests_by_qualified or {}
    source_items_by_pair: dict[tuple[str, str], set[str]] = {}
    pairs_by_member: dict[str, set[tuple[str, str]]] = {}
    errors: list[str] = []
    for raw_route in companion_routes:
        if not isinstance(raw_route, Mapping):
            errors.append("semantic-contract companion route is not an object")
            continue
        source_item = str(raw_route.get("source_item") or "").strip()
        evidence = semantic_contract_fully_qualified_identity(
            raw_route.get("evidence_declaration")
        )
        spec = semantic_contract_fully_qualified_identity(
            raw_route.get("spec_declaration")
        )
        if not source_item or not evidence or not spec or evidence == spec:
            errors.append(
                "semantic-contract companion route needs a source item and two "
                "distinct fully-qualified declaration identities"
            )
            continue
        pair = (evidence, spec)
        source_items_by_pair.setdefault(pair, set()).add(source_item)
        pairs_by_member.setdefault(evidence, set()).add(pair)
        pairs_by_member.setdefault(spec, set()).add(pair)

    ambiguous_members = {
        member: pairs
        for member, pairs in pairs_by_member.items()
        if len(pairs) != 1
    }
    for member, pairs in sorted(ambiguous_members.items()):
        errors.append(
            "semantic-contract companion declaration participates in multiple pairs: "
            + member
            + " -> "
            + ", ".join(f"{evidence} / {spec}" for evidence, spec in sorted(pairs))
        )

    surfaces: dict[str, SemanticModelReviewSurface] = {}
    for (evidence, spec), source_items in sorted(source_items_by_pair.items()):
        if evidence in ambiguous_members or spec in ambiguous_members:
            continue
        evidence_declaration = declarations_by_name.get(evidence)
        spec_declaration = declarations_by_name.get(spec)
        if evidence_declaration is None or spec_declaration is None:
            missing = evidence if evidence_declaration is None else spec
            errors.append(
                "semantic-contract companion declaration is outside the exact "
                "PaperInterface import closure: "
                + missing
            )
            continue
        structural_surfaces = semantic_contract_pair_structural_surfaces(
            evidence_qualified_name=evidence,
            evidence_source=evidence_declaration.source,
            spec_qualified_name=spec,
            spec_source=spec_declaration.source,
            proposition_aliases=proposition_aliases,
            type_aliases=type_aliases,
            evidence_manifest=elaborated_manifests_by_qualified.get(evidence),
            spec_manifest=elaborated_manifests_by_qualified.get(spec),
        )
        if structural_surfaces is None:
            if (
                defer_manifest_dependent_errors
                and not semantic_model_transparent_spec_body(
                    spec_declaration.source
                )
            ):
                # This pass only schedules the manifests and parser inputs.
                # Do not infer equality from source syntax, and do not let a
                # partial cache become a hard failure.  The complete-manifest
                # pass repeats every explicit pair and owns the error.
                continue
            errors.append(
                "semantic-contract companion is not an exact transparent "
                f"evidence/Spec structural pair: {evidence} / {spec}"
            )
            continue
        evidence_surface, spec_surface = structural_surfaces
        spec_analysis_declaration = semantic_model_spec_analysis_declaration(
            spec_declaration.source,
            spec_surface,
        )
        if not spec_analysis_declaration:
            errors.append(
                "semantic-contract companion has a complete Lean transparent "
                "graph but no bounded source presentation for its Spec: "
                f"{evidence} / {spec}"
            )
            continue
        route_receipt = {
            "schema": 2,
            "route_kind": "explicit_structurally_validated_semantic_contract_companion",
            "reviewed_declaration": evidence,
            "alias_present": False,
            "complete": True,
            "effective_declaration": spec,
            "effective_kind": spec_declaration.kind,
            "source_items": sorted(source_items),
            "structural_alpha_normalized_equal": True,
            "evidence_surface": evidence_surface,
            "spec_surface": spec_surface,
            "steps": [
                {
                    "from": evidence,
                    "to": spec,
                    "kind": "explicit_semantic_contract_companion",
                }
            ],
            "blocked_routes": [],
        }
        surfaces[evidence] = SemanticModelReviewSurface(
            reviewed_qualified_name=evidence,
            reviewed_declaration=evidence_declaration.source,
            effective_declaration=spec_declaration,
            review_alias_expansion=route_receipt,
            uses_effective_target=True,
            analysis_qualified_name=spec,
            analysis_declaration=spec_analysis_declaration,
            header_inputs=[],
            conclusion_inputs=[],
        )
        spec_body = semantic_model_transparent_spec_body(spec_analysis_declaration)
        spec_header_inputs = header_inputs_from_declaration(spec_analysis_declaration)
        spec_bound_names = {
            name
            for visible_input in spec_header_inputs
            for name in binder_names(visible_input.get("names", ""))
        }
        spec_body_inputs, spec_terminal_result = result_type_inputs(
            spec_body, spec_bound_names
        )
        occupied_names = set(spec_bound_names)
        for visible_input in spec_body_inputs:
            occupied_names.update(binder_names(visible_input.get("names", "")))
        spec_body_inputs.extend(
            dependent_if_guard_inputs(spec_terminal_result, occupied_names)
        )
        spec_route_receipt = {
            **route_receipt,
            "reviewed_declaration": spec,
            "effective_declaration": evidence,
            "effective_kind": evidence_declaration.kind,
            "surface_role": "transparent_spec_body_owner",
            "steps": [
                {
                    "from": spec,
                    "to": evidence,
                    "kind": "exact_evidence_telescope_for_transparent_spec_body",
                }
            ],
        }
        # The paired proof theorem's reduced telescope remains the semantic
        # and dependency receipt for this body.  A later positional adapter
        # may use the Spec definition-value telescope only after proving it is
        # an exact Lean-owned prefix of that proof surface.  Keep the proof
        # row input-free so each logical binder and recursively reached model
        # record is audited exactly once.
        surfaces[spec] = SemanticModelReviewSurface(
            reviewed_qualified_name=spec,
            reviewed_declaration=spec_declaration.source,
            effective_declaration=evidence_declaration,
            review_alias_expansion=spec_route_receipt,
            uses_effective_target=True,
            analysis_qualified_name=evidence,
            analysis_declaration=spec_analysis_declaration,
            header_inputs=spec_header_inputs,
            conclusion_inputs=spec_body_inputs,
        )
    return surfaces, sorted(set(errors))


def semantic_contract_delegated_empty_input_rows(
    review_surfaces: Mapping[str, SemanticModelReviewSurface],
) -> dict[str, dict[str, str]]:
    """Identify proof rows whose parsed input surface is owned by a Spec row.

    A validated direct/transparent-Spec companion deliberately leaves the
    proof theorem's parser inputs empty and assigns the reduced theorem
    telescope to its paired Spec row.  Positional Lean-binder consumers must
    not compare that intentionally empty proof surface against the Spec's
    declaration telescope.  This recognizes only the paired receipt topology
    emitted by :func:`semantic_model_review_contract_companion_surfaces`; a
    normal zero-input theorem has no such counterpart and is never delegated.
    """

    owners_by_pair: dict[tuple[str, str], list[str]] = {}
    for row, surface in review_surfaces.items():
        receipt = surface.review_alias_expansion
        if (
            receipt.get("schema") != 2
            or receipt.get("route_kind")
            != "explicit_structurally_validated_semantic_contract_companion"
            or receipt.get("complete") is not True
            or receipt.get("structural_alpha_normalized_equal") is not True
            or receipt.get("surface_role") != "transparent_spec_body_owner"
        ):
            continue
        evidence = surface.analysis_qualified_name
        spec = surface.reviewed_qualified_name
        if (
            not evidence
            or not spec
            or receipt.get("reviewed_declaration") != spec
            or receipt.get("effective_declaration") != evidence
        ):
            continue
        owners_by_pair.setdefault((evidence, spec), []).append(row)

    delegated: dict[str, dict[str, str]] = {}
    for row, surface in review_surfaces.items():
        receipt = surface.review_alias_expansion
        if (
            surface.header_inputs
            or surface.conclusion_inputs
            or receipt.get("schema") != 2
            or receipt.get("route_kind")
            != "explicit_structurally_validated_semantic_contract_companion"
            or receipt.get("complete") is not True
            or receipt.get("structural_alpha_normalized_equal") is not True
            or receipt.get("surface_role") is not None
        ):
            continue
        evidence = surface.reviewed_qualified_name
        spec = surface.analysis_qualified_name
        owners = owners_by_pair.get((evidence, spec), [])
        if (
            len(owners) != 1
            or receipt.get("reviewed_declaration") != evidence
            or receipt.get("effective_declaration") != spec
        ):
            continue
        delegated[row] = {
            "analysis_qualified_declaration": spec,
            "semantic_surface_owner_row": owners[0],
            "semantic_surface_owner_declaration": spec,
        }
    return delegated


def semantic_contract_positional_signature_manifests(
    *,
    review_surfaces: Mapping[str, SemanticModelReviewSurface],
    elaborated_manifests_by_qualified: Mapping[str, Mapping[str, Any]],
) -> tuple[dict[str, Mapping[str, Any]], dict[str, dict[str, str]], list[str]]:
    """Select Lean-owned positional surfaces for parsed source binders.

    The full reduced theorem manifest remains the authority for semantic
    graphs, dependency reachability, proof realization, and declaration
    identity. An exact schema-2 transparent-Spec owner instead uses its
    elaborated definition value's complete nonreducing telescope for
    source-presentation coordinates: both its binders and its terminal
    conclusion. The alternate telescope is accepted only when each binder
    atom is the exact prefix of the paired proof theorem's full reduced
    telescope and the separately Lean-validated Spec/proof relation is
    current. Thus reduction-introduced binders remain visible in the proof
    manifest without being misreported as source inputs or replacing a
    source-facing wrapper such as negation with its reduced ``False`` result.
    """

    positional: dict[str, Mapping[str, Any]] = {}
    routes: dict[str, dict[str, str]] = {}
    errors: list[str] = []
    for row, surface in review_surfaces.items():
        analysis_qualified = semantic_contract_fully_qualified_identity(
            surface.analysis_qualified_name
        )
        if not analysis_qualified:
            errors.append(
                f"{row}: semantic review surface has no exact analysis declaration"
            )
            continue
        full_manifest = elaborated_manifests_by_qualified.get(analysis_qualified)
        if not isinstance(full_manifest, Mapping):
            errors.append(
                f"{analysis_qualified}: Lean signature manifest is unavailable"
            )
            continue
        positional[row] = full_manifest

        receipt = surface.review_alias_expansion
        is_owner = (
            receipt.get("schema") == 2
            and receipt.get("route_kind")
            == "explicit_structurally_validated_semantic_contract_companion"
            and receipt.get("complete") is True
            and receipt.get("structural_alpha_normalized_equal") is True
            and receipt.get("surface_role") == "transparent_spec_body_owner"
        )
        if not is_owner:
            continue
        spec_qualified = semantic_contract_fully_qualified_identity(
            surface.reviewed_qualified_name
        )
        if (
            not spec_qualified
            or receipt.get("reviewed_declaration") != spec_qualified
            or receipt.get("effective_declaration") != analysis_qualified
        ):
            errors.append(
                f"{row}: transparent-Spec positional route is malformed"
            )
            continue
        spec_manifest = elaborated_manifests_by_qualified.get(spec_qualified)
        raw_presentation = (
            spec_manifest.get("transparent_value_presentation_telescope")
            if isinstance(spec_manifest, Mapping)
            else None
        )
        presentation = normalize_transparent_value_presentation_telescope(
            raw_presentation
        )
        if presentation is None:
            errors.append(
                f"{spec_qualified}: transparent definition-value presentation telescope is unavailable"
            )
            continue
        presentation_sha = str(presentation.get("sha256") or "").strip().lower()
        full_signature = str(full_manifest.get("sha256") or "").strip().lower()
        presentation_atoms = presentation.get("atoms")
        full_atoms = full_manifest.get("atoms")
        if (
            not SHA256_RE.fullmatch(presentation_sha)
            or not SHA256_RE.fullmatch(full_signature)
            or not isinstance(presentation_atoms, list)
            or not isinstance(full_atoms, list)
            or not presentation_atoms
            or not full_atoms
        ):
            errors.append(
                f"{spec_qualified}: transparent-Spec positional telescope is malformed"
            )
            continue
        presentation_binders = presentation_atoms[:-1]
        full_binders = full_atoms[:-1]
        presentation_identities = [
            signature_manifest_atom_identity(atom) for atom in presentation_binders
        ]
        full_prefix_identities = [
            signature_manifest_atom_identity(atom)
            for atom in full_binders[: len(presentation_binders)]
        ]
        if (
            presentation_atoms[-1].get("ref") != "result"
            or presentation_atoms[-1].get("role") != "conclusion"
            or full_atoms[-1].get("ref") != "result"
            or full_atoms[-1].get("role") != "conclusion"
            or len(presentation_binders) > len(full_binders)
            or any(identity is None for identity in presentation_identities)
            or any(identity is None for identity in full_prefix_identities)
            or presentation_identities != full_prefix_identities
        ):
            errors.append(
                f"{spec_qualified}: transparent definition-value binders are not an exact prefix of the paired proof telescope"
            )
            continue
        # The complete Lean-produced presentation telescope owns both the
        # source-written binder prefix and its terminal conclusion.  The
        # paired proof theorem may reduce a wrapper such as `Not P` to an
        # additional assumption and `False`; substituting that reduced
        # terminal here would erase the exact source-facing proposition
        # boundary.  The independently validated Spec/proof relation and the
        # recorded proof signature continue to authenticate the proof route.
        adapter = dict(full_manifest)
        adapter["atoms"] = deepcopy(presentation_atoms)
        adapter["sha256"] = presentation_sha
        adapter["positional_surface_kind"] = (
            "transparent_definition_value_outer_telescope"
        )
        adapter["paired_proof_signature_sha256"] = full_signature
        adapter["transparent_spec_presentation_telescope_sha256"] = presentation_sha
        positional[row] = adapter
        routes[row] = {
            "route_kind": "validated_transparent_spec_definition_value_telescope",
            "proof_signature_sha256": full_signature,
            "presentation_telescope_sha256": presentation_sha,
        }
    return positional, routes, sorted(set(errors))



def semantic_contract_source_identity(
    source_key: str, source_item: dict[str, Any]
) -> dict[str, Any]:
    """Keep every source-map identity that shares one direct/Spec pair."""

    raw_contract = source_item.get("semantic_contract")
    contract = raw_contract if isinstance(raw_contract, dict) else {}
    return {
        "source_key": source_key,
        "source_location": str(source_item.get("source_location") or "").strip(),
        "source_kind": str(source_item.get("source_kind") or "").strip(),
        # This is a raw-audit source-map item identity, not a bare source key.
        # It binds corrected targets, defect routes, semantic contracts, and
        # future map metadata, while deliberately excluding only the five
        # strict-source-to-Spec receipt hashes that are refreshed and checked
        # in their own closeout lane.
        "source_map_item_sha256": source_record_source_item_record_sha256(
            source_item
        ),
        # This source-only raw-lane projection deliberately excludes map keys,
        # Lean navigation routes, and the same refresh-only correspondence
        # hashes. Those hashes remain strict correspondence evidence rather
        # than a reason to reopen a source-record human judgment.
        "source_semantic_sha256": source_record_source_item_semantic_sha256(
            source_item, ""
        ),
        "semantic_contract": {
            field: str(contract.get(field) or "").strip()
            for field in (
                "evidence_declaration",
                "spec_declaration",
                "evidence_mode",
                "semantic_shape",
            )
        },
    }


def semantic_contract_source_association(
    *,
    source_identities: list[dict[str, Any]],
    role: str,
    paired_declaration: str,
    reviewed_identity: dict[str, str],
    reviewed_signature_identity: dict[str, str] | None = None,
) -> dict[str, Any]:
    """Describe an explicit source-map route without merging semantic reviews.

    A source-map contract is useful provenance even when the conservative
    direct/transparent-Spec structural comparison below cannot establish that
    the two surfaces are alpha-equal.  In particular, a Lean elaborator can
    infer an omitted implicit argument which a source-text parser cannot
    reconstruct safely.  This association records only the curated, fully
    qualified source route; it never says that one row's review discharges the
    other row or that the two propositions are structurally equal.
    """

    association: dict[str, Any] = {
        "schema": 1,
        "role": role,
        "reviewed_declaration_identity": reviewed_identity,
        "paired_qualified_declaration": paired_declaration,
        "source_item_identities": source_identities,
        "review_scope": "individual_row_only",
        "structural_pairing": "not_asserted_by_source_association",
    }
    semantic_digest = semantic_source_association_digest(
        source_identities, reviewed_signature_identity
    )
    if semantic_digest and reviewed_signature_identity is not None:
        association["schema"] = 2
        association["reviewed_elaborated_signature_identity"] = (
            reviewed_signature_identity
        )
        association["semantic_association_sha256"] = semantic_digest
    return association


def explicit_direct_source_route_association(
    *,
    source_identities: list[dict[str, Any]],
    reviewed_identity: dict[str, str],
    reviewed_signature_identity: dict[str, str],
) -> dict[str, Any]:
    """Return provenance for one source-selected direct statement route.

    This intentionally has a distinct field and shape from
    ``semantic_contract_source_association``.  It records one source item's
    explicitly curated direct route to one current review declaration, but
    does not represent a direct/Spec pair or claim structural equivalence.
    """

    association: dict[str, Any] = {
        "schema": 1,
        "association_origin": EXPLICIT_DIRECT_SOURCE_ROUTE_ORIGIN,
        "role": EXPLICIT_DIRECT_SOURCE_ROUTE_ROLE,
        "reviewed_declaration_identity": reviewed_identity,
        "source_item_identities": source_identities,
        "review_scope": "individual_row_only",
        "structural_pairing": "not_applicable_direct_source_route",
    }
    semantic_digest = semantic_source_association_digest(
        source_identities, reviewed_signature_identity
    )
    if semantic_digest:
        association["schema"] = 2
        association["reviewed_elaborated_signature_identity"] = (
            reviewed_signature_identity
        )
        association["semantic_association_sha256"] = semantic_digest
    return association


def explicit_direct_source_route_identities(
    statement_map: dict[str, Any] | None,
    *,
    row_qualified_names: dict[str, str],
    additional_selected_source_item_ids: Iterable[str] = (),
    validated_vocabulary_binding_source_item_ids: Iterable[str] | None = (),
    validated_vocabulary_direct_route_source_item_ids: Iterable[str] | None = (),
) -> tuple[dict[str, list[dict[str, Any]]], list[str]]:
    """Return semantic source identities for explicit non-contract map routes.

    This is deliberately narrower than a general route-name lookup.  The
    source-coverage selector first chooses source items solely from their own
    presentation.  An exact source-ledger scope may additionally nominate its
    source item for provenance without granting that item ordinary source
    coverage. A source-validated vocabulary binding is a distinct cause: it
    may cover several current review rows, but only a generated one-route
    subset can enter this one-to-one direct provenance lane. We then accept
    only the exact legacy direct-route fields that the selector already
    recognizes, and only when they resolve to one current, fully-qualified
    configured declaration. A map item carrying a semantic contract is left
    to the semantic-contract lane: a malformed or incomplete contract must
    not be bypassed by its incidental route list.
    """

    if not isinstance(statement_map, dict):
        return {}, []
    raw_items = statement_map.get("items")
    if not isinstance(raw_items, dict):
        return {}, ["paper_statement_map.json has no items object for explicit direct-route provenance"]
    presentation_aliases, presentation_alias_errors = source_presentation_aliases(
        raw_items
    )

    mode, mode_error = source_coverage_mode_from_map(statement_map)
    if mode_error:
        return {}, [
            "explicit direct-route provenance cannot select source items: "
            + mode_error
        ]
    declared_environment_kinds = source_named_result_environment_kinds_from_map(
        statement_map
    )
    selected_items = filter_source_map_items_for_coverage(
        raw_items,
        mode,
        declared_environment_kinds=declared_environment_kinds,
    )

    def selector_keys(
        raw_selector: Iterable[str] | None, *, selector_name: str
    ) -> tuple[set[str], list[str]]:
        keys: set[str] = set()
        selector_errors: list[str] = []
        if raw_selector is None:
            return keys, selector_errors
        if isinstance(raw_selector, (str, bytes)):
            return keys, [f"{selector_name} must be a sequence of source item ids"]
        for index, raw_source_key in enumerate(raw_selector):
            source_key = str(raw_source_key or "").strip()
            if not source_key:
                selector_errors.append(
                    f"{selector_name}[{index}] contains a blank source item id"
                )
                continue
            if source_key in keys:
                selector_errors.append(
                    f"{selector_name} repeats source item `{source_key}`"
                )
                continue
            if not isinstance(raw_items.get(source_key), dict):
                selector_errors.append(
                    f"{selector_name} names absent or malformed source item `{source_key}`"
                )
                continue
            keys.add(source_key)
        return keys, selector_errors

    (
        vocabulary_binding_source_keys,
        vocabulary_binding_selection_errors,
    ) = selector_keys(
        validated_vocabulary_binding_source_item_ids,
        selector_name="validated vocabulary binding selector",
    )
    (
        vocabulary_direct_route_source_keys,
        vocabulary_direct_route_selection_errors,
    ) = selector_keys(
        validated_vocabulary_direct_route_source_item_ids,
        selector_name="validated vocabulary direct-route selector",
    )
    invalid_vocabulary_direct_route_source_keys = (
        vocabulary_direct_route_source_keys - vocabulary_binding_source_keys
    )
    if invalid_vocabulary_direct_route_source_keys:
        vocabulary_direct_route_selection_errors.extend(
            "validated vocabulary direct-route selector names source item "
            f"`{source_key}` absent from the validated vocabulary binding selector"
            for source_key in sorted(invalid_vocabulary_direct_route_source_keys)
        )
        vocabulary_direct_route_source_keys -= (
            invalid_vocabulary_direct_route_source_keys
        )

    supplemental_source_keys: set[str] = set()
    additional_selection_errors: list[str] = []
    for raw_source_key in additional_selected_source_item_ids:
        source_key = str(raw_source_key or "").strip()
        if not source_key:
            additional_selection_errors.append(
                "supplemental direct-route source selection contains a blank "
                "source item id"
            )
            continue
        source_item = raw_items.get(source_key)
        if not isinstance(source_item, dict):
            additional_selection_errors.append(
                "supplemental direct-route source selection names absent or "
                f"malformed source item `{source_key}`"
            )
            continue
        supplemental_source_keys.add(source_key)
        selected_items[source_key] = source_item

    # A valid prose-definition/standard-term binding can explain more than
    # one paper-facing Lean declaration. It remains source coverage, but it
    # cannot manufacture a one-source/one-row direct association. Suppress it
    # only when it entered ordinary presentation selection and has no separate
    # recursive/convention provenance cause. The direct subset and independent
    # supplemental causes are then added explicitly below.
    for source_key in (
        vocabulary_binding_source_keys
        - vocabulary_direct_route_source_keys
        - supplemental_source_keys
    ):
        source_item = raw_items.get(source_key)
        # A supplied semantic contract is authoritative even when malformed.
        # Leave it to the existing contract validator rather than suppressing
        # a direct-route error merely because a vocabulary binding is broad.
        if isinstance(source_item, dict) and source_item.get("semantic_contract") is None:
            selected_items.pop(source_key, None)
    for source_key in vocabulary_direct_route_source_keys:
        source_item = raw_items.get(source_key)
        assert isinstance(source_item, dict)
        selected_items[source_key] = source_item

    rows_by_qualified: dict[str, list[str]] = {}
    for row, raw_qualified in row_qualified_names.items():
        qualified = semantic_contract_fully_qualified_identity(raw_qualified)
        if qualified:
            rows_by_qualified.setdefault(qualified, []).append(str(row))
    ambiguous_configured_routes = {
        qualified
        for qualified, rows in rows_by_qualified.items()
        if len(rows) != 1
    }

    identities_by_qualified: dict[str, dict[str, dict[str, Any]]] = {}
    qualified_routes_by_source_key: dict[str, set[str]] = {}
    malformed_route_source_keys: set[str] = set()
    errors: list[str] = [
        *presentation_alias_errors,
        *additional_selection_errors,
        *vocabulary_binding_selection_errors,
        *vocabulary_direct_route_selection_errors,
    ]
    errors.extend(source_claim_atom_contract_errors(statement_map))
    for raw_source_key, source_item in selected_items.items():
        source_key = str(raw_source_key).strip()
        if not source_key:
            continue
        if source_key in presentation_aliases:
            # The source-only alias still counts for presentation inventory,
            # but the canonical source item owns the one direct Lean route.
            continue
        route_policy = source_item_effective_route_policy(source_item)
        if bool(route_policy["is_support_only"]) or bool(
            route_policy["is_quarantined_source_defect"]
        ) or bool(
            route_policy["is_source_declared_open_nonresult"]
        ):
            # Support-only and quarantined items may document checked proof or
            # defect support, but never furnish direct source-result provenance.
            continue
        if source_claim_atom_authoritative_for_item(statement_map, source_item):
            # The atom collector below owns this theorem-like presentation.
            # In particular, do not collapse multiple source clauses back to
            # a parent item merely because its legacy route list happens to
            # contain one familiar declaration.
            continue
        if source_item.get("claim_bearing") is False:
            supplemental_nonclaim_context = (
                source_key in supplemental_source_keys
                and not source_item_in_coverage_scope(
                    source_item,
                    mode,
                    declared_environment_kinds=declared_environment_kinds,
                )
            )
            if not supplemental_nonclaim_context:
                errors.append(
                    f"selected source item `{source_key}` sets claim_bearing: false and cannot supply direct-route provenance"
                )
                continue
        if "claim_bearing" in source_item and not isinstance(
            source_item.get("claim_bearing"), bool
        ):
            errors.append(
                f"selected source item `{source_key}` has non-Boolean claim_bearing"
            )
            continue
        source_location = str(source_item.get("source_location") or "").strip()
        if not source_location:
            errors.append(
                f"selected source item `{source_key}` has no source_location for direct-route provenance"
            )
            continue

        # A supplied contract is authoritative even when it is malformed.  A
        # valid contract has its own direct/Spec association lane, while an
        # invalid or no-longer-current contract must surface as an error rather
        # than silently falling back to a legacy route list.  This is not a
        # name-based exemption: validate both exact, configured declarations
        # before leaving the item to the semantic-contract lane.
        raw_contract = source_item.get("semantic_contract")
        if raw_contract is not None:
            if not isinstance(raw_contract, dict):
                errors.append(
                    f"selected source item `{source_key}` has a non-object semantic_contract; direct-route fallback is forbidden"
                )
                continue
            contract_schema = statement_map.get("semantic_contract_schema")
            if (
                not isinstance(contract_schema, int)
                or isinstance(contract_schema, bool)
                or contract_schema not in SEMANTIC_CONTRACT_SCHEMAS
            ):
                errors.append(
                    f"selected source item `{source_key}` has semantic_contract metadata but the source map has no supported semantic_contract_schema"
                )
                continue
            contract_errors = semantic_contract_validation_errors(
                raw_contract, schema=contract_schema
            )
            if contract_errors:
                errors.extend(
                    f"selected source item `{source_key}` has invalid semantic_contract metadata: {error}"
                    for error in contract_errors
                )
                continue
            contract_routes: list[str] = []
            for field in ("evidence_declaration", "spec_declaration"):
                qualified = semantic_contract_fully_qualified_identity(
                    raw_contract.get(field)
                )
                if not qualified:
                    errors.append(
                        f"selected source item `{source_key}` semantic_contract.{field} is not an exact fully-qualified Lean declaration"
                    )
                    continue
                if qualified in ambiguous_configured_routes:
                    errors.append(
                        f"selected source item `{source_key}` semantic_contract.{field} routes to ambiguous configured declaration `{qualified}`"
                    )
                    continue
                if qualified not in rows_by_qualified:
                    errors.append(
                        f"selected source item `{source_key}` semantic_contract.{field} routes to `{qualified}`, which is not an exact configured review declaration"
                    )
                    continue
                contract_routes.append(qualified)
            if len(contract_routes) == 2 and contract_routes[0] == contract_routes[1]:
                errors.append(
                    f"selected source item `{source_key}` semantic_contract direct and Spec declarations must be distinct"
                )
            # A valid current contract is deliberately not a legacy direct
            # route.  Its direct/Spec association is produced by
            # ``collapse_semantic_model_contract_pairs`` below; attempting to
            # attach it here would fabricate a second provenance lane.
            continue

        identity = semantic_contract_source_identity(source_key, source_item)
        found_route = False
        for field in EXPLICIT_DIRECT_SOURCE_ROUTE_FIELDS:
            raw_routes = source_item.get(field)
            if raw_routes is None:
                continue
            if not isinstance(raw_routes, list):
                errors.append(
                    f"selected source item `{source_key}` has non-list {field} direct-route metadata"
                )
                malformed_route_source_keys.add(source_key)
                continue
            for index, raw_route in enumerate(raw_routes):
                route = str(raw_route or "").strip()
                if not route:
                    errors.append(
                        f"selected source item `{source_key}` has blank {field}[{index}] direct-route metadata"
                    )
                    malformed_route_source_keys.add(source_key)
                    continue
                qualified = semantic_contract_fully_qualified_identity(route)
                if not qualified:
                    errors.append(
                        f"selected source item `{source_key}` has non-qualified {field}[{index}] route `{route}`"
                    )
                    malformed_route_source_keys.add(source_key)
                    continue
                if qualified in ambiguous_configured_routes:
                    errors.append(
                        f"selected source item `{source_key}` routes to ambiguous configured declaration `{qualified}`"
                    )
                    malformed_route_source_keys.add(source_key)
                    continue
                if qualified not in rows_by_qualified:
                    errors.append(
                        f"selected source item `{source_key}` routes to `{qualified}`, which is not an exact configured review declaration"
                    )
                    malformed_route_source_keys.add(source_key)
                    continue
                found_route = True
                identities_by_qualified.setdefault(qualified, {})[source_key] = identity
                qualified_routes_by_source_key.setdefault(source_key, set()).add(
                    qualified
                )
        if not found_route:
            errors.append(
                f"selected source item `{source_key}` has no exact explicit direct-route declaration"
            )

    # This direct statement lane is intentionally one-to-one. A source item
    # spanning multiple review declarations needs an explicit semantic
    # contract or separate source inventory entries; otherwise there is no
    # safe way to know which expanded source-model judgment it discharges.
    for source_key, qualified_routes in sorted(qualified_routes_by_source_key.items()):
        if source_key in malformed_route_source_keys:
            for qualified in qualified_routes:
                identities_by_qualified.get(qualified, {}).pop(source_key, None)
            continue
        if len(qualified_routes) == 1:
            continue
        errors.append(
            f"selected source item `{source_key}` has {len(qualified_routes)} exact direct routes; direct-route provenance requires one source item per review declaration"
        )
        for qualified in qualified_routes:
            identities_by_qualified.get(qualified, {}).pop(source_key, None)

    for qualified in sorted(list(identities_by_qualified)):
        identities = identities_by_qualified[qualified]
        if len(identities) == 1:
            continue
        errors.append(
            f"fully-qualified direct route `{qualified}` has {len(identities)} selected source items; direct-route provenance requires one source item per review declaration"
        )
        identities_by_qualified.pop(qualified, None)

    return (
        {
            qualified: [
                identities_by_qualified[qualified][source_key]
                for source_key in sorted(identities_by_qualified[qualified])
            ]
            for qualified in sorted(identities_by_qualified)
        },
        sorted(set(errors)),
    )


def explicit_direct_source_route_anchor_errors(
    paper_dir: Path,
    statement_map: dict[str, Any] | None,
    *,
    source_keys: set[str],
) -> list[str]:
    """Byte-validate every source item proposed for direct-route reuse.

    A source-content digest intentionally ignores navigation coordinates so an
    unchanged theorem can survive an unrelated source-file edit.  That is safe
    only after the current anchor records prove that the theorem quote still
    equals the canonical source bytes.  This helper forces that validation for
    the exact candidate subset even when a legacy paper did not globally opt
    into full anchor evidence.
    """

    if not source_keys:
        return []
    if not isinstance(statement_map, dict):
        return ["explicit direct-route provenance has no readable source map"]
    raw_items = statement_map.get("items")
    if not isinstance(raw_items, dict):
        return ["explicit direct-route provenance has no source-map items object"]
    selected_items: dict[str, Any] = {}
    errors: list[str] = []
    for source_key in sorted(source_keys):
        source_item = raw_items.get(source_key)
        if not isinstance(source_item, dict):
            errors.append(
                f"explicit direct-route source item `{source_key}` is absent from the current source map"
            )
            continue
        selected_items[source_key] = source_item
    if not selected_items:
        return errors

    scoped_map = dict(statement_map)
    scoped_map["items"] = selected_items
    scoped_map["source_anchor_evidence_required"] = True
    map_path = paper_dir / "audit" / "paper_statement_map.json"
    status = str(load_json_object(paper_dir / "status.json").get("status") or "")
    try:
        findings = source_anchor_evidence_findings(
            paper_dir,
            status or "formalized",
            map_path,
            scoped_map,
        )
    except Exception as error:  # noqa: BLE001 - byte provenance must fail closed.
        return errors + [
            "explicit direct-route source-anchor validator failed: "
            f"{type(error).__name__}: {error}"
        ]
    return errors + sorted(str(finding.message) for finding in findings)


def attach_explicit_direct_source_route_associations(
    items: list[dict[str, Any]],
    *,
    paper_dir: Path,
    paper_statement_map: dict[str, Any] | None,
    declarations: dict[str, str],
    row_qualified_names: dict[str, str],
    elaborated_signature_sha256_by_qualified: dict[str, str],
    additional_selected_source_item_ids: Iterable[str] = (),
    validated_vocabulary_binding_source_item_ids: Iterable[str] | None = (),
    validated_vocabulary_direct_route_source_item_ids: Iterable[str] | None = (),
) -> tuple[list[dict[str, Any]], list[str], dict[str, int]]:
    """Attach exact source-map direct routes to individual semantic rows.

    Unlike a direct/Spec semantic contract, this association does not assert
    structural equality between two Lean declarations.  It only records the
    already-curated one-item-to-current-review-route provenance needed to bind
    corrected targets and safely reuse a semantic-model judgment.  The source
    item, its current byte-verified quote, and Lean's current elaborated
    signature all participate; row labels and declaration suffixes do not.
    """

    identities_by_qualified, route_errors = explicit_direct_source_route_identities(
        paper_statement_map,
        row_qualified_names=row_qualified_names,
        additional_selected_source_item_ids=additional_selected_source_item_ids,
        validated_vocabulary_binding_source_item_ids=(
            validated_vocabulary_binding_source_item_ids
        ),
        validated_vocabulary_direct_route_source_item_ids=(
            validated_vocabulary_direct_route_source_item_ids
        ),
    )
    source_keys = {
        str(identity.get("source_key") or "").strip()
        for identities in identities_by_qualified.values()
        for identity in identities
        if str(identity.get("source_key") or "").strip()
    }
    counts = {
        "explicit_direct_route_declaration_count": len(identities_by_qualified),
        "explicit_direct_route_source_item_count": len(source_keys),
        "explicit_direct_route_association_count": 0,
    }
    errors = list(route_errors)

    # Validate the byte-pinned evidence at the source-item granularity.  A
    # direct route is already constrained to exactly one source item, so an
    # invalid quote must suppress only that route.  Returning early for one
    # malformed source item used to remove independently valid associations
    # from the raw receipt, which made the receipt less precise without making
    # the malformed route any safer.  Keep every failure as a blocking receipt
    # error; do not attach the failed route or allow it to contribute source
    # credit downstream.
    unverified_source_keys: set[str] = set()
    for source_key in sorted(source_keys):
        anchor_errors = explicit_direct_source_route_anchor_errors(
            paper_dir,
            paper_statement_map,
            source_keys={source_key},
        )
        if not anchor_errors:
            continue
        unverified_source_keys.add(source_key)
        errors.extend(
            "explicit direct-route source item "
            f"`{source_key}` provenance is not byte-verified: {error}"
            for error in anchor_errors
        )

    if unverified_source_keys:
        identities_by_qualified = {
            qualified: [
                identity
                for identity in identities
                if str(identity.get("source_key") or "").strip()
                not in unverified_source_keys
            ]
            for qualified, identities in identities_by_qualified.items()
        }
        # ``explicit_direct_source_route_identities`` enforces one source item
        # per review declaration.  Retain the defensive filter in case a
        # future route collector relaxes that representation: an association
        # may never be built from a partial source route.
        identities_by_qualified = {
            qualified: identities
            for qualified, identities in identities_by_qualified.items()
            if len(identities) == 1
        }

    items_by_qualified: dict[str, list[dict[str, Any]]] = {}
    for item in items:
        if not isinstance(item, dict):
            continue
        qualified = semantic_contract_fully_qualified_identity(
            item.get("qualified_declaration")
        )
        if qualified:
            items_by_qualified.setdefault(qualified, []).append(item)

    for qualified, source_identities in identities_by_qualified.items():
        members = items_by_qualified.get(qualified, [])
        if len(members) != 1:
            errors.append(
                "explicit direct source route for fully-qualified declaration "
                f"`{qualified}` has {len(members)} generated semantic-model rows; association is ambiguous"
            )
            continue
        item = members[0]
        if isinstance(item.get("semantic_contract_group"), dict) or isinstance(
            item.get("semantic_contract_source_association"), dict
        ) or isinstance(item.get("source_statement_association"), dict):
            errors.append(
                "explicit direct source route for fully-qualified declaration "
                f"`{qualified}` collides with an existing semantic-contract association"
            )
            continue
        row = str(item.get("row") or "").strip()
        reviewed_identity = reviewed_declaration_identity(
            qualified,
            declarations.get(row, str(item.get("lean_source_declaration") or "")),
        )
        if reviewed_identity is None:
            errors.append(
                "explicit direct source route for fully-qualified declaration "
                f"`{qualified}` has no current declaration-content identity"
            )
            continue
        reviewed_signature = reviewed_elaborated_signature_identity(
            reviewed_identity,
            elaborated_signature_sha256_by_qualified,
        )
        if reviewed_signature is None:
            errors.append(
                "explicit direct source route for fully-qualified declaration "
                f"`{qualified}` has no current elaborated-signature identity"
            )
            continue
        association = explicit_direct_source_route_association(
            source_identities=source_identities,
            reviewed_identity=reviewed_identity,
            reviewed_signature_identity=reviewed_signature,
        )
        item["source_statement_association"] = association
        item["required_check"] = (
            str(item.get("required_check") or "")
            + " This individual row has an explicit source-presentation-selected "
            "direct map route. The association binds its byte-verified source "
            "item and current elaborated signature; it does not assert a "
            "direct/Spec structural equivalence."
        )
        counts["explicit_direct_route_association_count"] += 1

    return items, sorted(set(errors)), counts


def _statement_source_component_route_content_identity(
    value: Mapping[str, Any],
) -> tuple[str, str, str, str, str] | None:
    """Return the content coordinates of one definition-component route."""

    fields = (
        "source_statement_sha256",
        "source_definition_partition_sha256",
        "source_definition_component_sha256",
        "source_component_anchor_sha256",
    )
    digests = tuple(str(value.get(field) or "").strip().lower() for field in fields)
    location = str(value.get("source_location") or "").strip()
    if not location or any(not SHA256_RE.fullmatch(digest) for digest in digests):
        return None
    return (*digests, location)


def _statement_source_component_existing_owner_errors(
    item: Mapping[str, Any],
    elaborated_signature_sha256_by_qualified: Mapping[str, str],
) -> tuple[list[str], list[str]]:
    """Validate associations that already own one semantic-model row.

    The component lane runs after the direct/Spec, explicit-direct, and claim-
    atom association generators.  A content-joined statement review may also
    mention a component without being a component-only review.  In that case
    this lane may stand down only when an earlier generator already attached a
    current source-and-signature-bound association to the exact row.  Mere
    field presence is not ownership: every supported association is checked
    against the generated declaration identity and current Lean signature,
    and its semantic digest is recomputed.
    """

    owner_fields = (
        "semantic_contract_source_association",
        "source_statement_association",
        SOURCE_CLAIM_ATOM_ASSOCIATION_FIELD,
    )
    present = [field for field in owner_fields if item.get(field) is not None]
    if not present:
        return [], []

    item_identity = item.get("reviewed_declaration_identity")
    item_identity_key = reviewed_declaration_identity_key(item_identity)
    errors: list[str] = []
    if item_identity_key is None:
        return present, ["generated row has no current declaration-content identity"]

    for field in present:
        association = item.get(field)
        if not isinstance(association, Mapping):
            errors.append(f"{field} is not an object")
            continue
        association_identity = association.get("reviewed_declaration_identity")
        if reviewed_declaration_identity_key(association_identity) != item_identity_key:
            errors.append(
                f"{field} does not bind the generated declaration-content identity"
            )
            continue
        current_signature = reviewed_elaborated_signature_identity(
            association_identity,
            dict(elaborated_signature_sha256_by_qualified),
        )
        if current_signature is None or association.get(
            "reviewed_elaborated_signature_identity"
        ) != current_signature:
            errors.append(f"{field} does not bind the current elaborated signature")
            continue

        if field == SOURCE_CLAIM_ATOM_ASSOCIATION_FIELD:
            if (
                association.get("schema") != SOURCE_CLAIM_ATOM_ASSOCIATION_SCHEMA
                or str(association.get("association_origin") or "").strip()
                != SOURCE_CLAIM_ATOM_ROUTE_ORIGIN
                or str(association.get("role") or "").strip()
                != SOURCE_CLAIM_ATOM_ROUTE_ROLE
            ):
                errors.append(f"{field} has an unsupported schema, origin, or role")
                continue
            _identities, atom_errors, atom_present = (
                source_record_item_claim_atom_semantic_identities(item)
            )
            if not atom_present or atom_errors:
                errors.extend(f"{field}: {error}" for error in atom_errors)
                if not atom_present:
                    errors.append(f"{field} has no atom semantic identity")
                continue
            supplied_full_digest = str(
                association.get("association_sha256") or ""
            ).strip().lower()
            association_payload = dict(association)
            association_payload.pop("association_sha256", None)
            if (
                not SHA256_RE.fullmatch(supplied_full_digest)
                or supplied_full_digest != stable_digest(association_payload)
            ):
                errors.append(f"{field} has a missing or stale full association pin")
            continue

        if (
            field == "source_statement_association"
            and str(association.get("association_origin") or "").strip()
            == STATEMENT_SOURCE_REVIEW_ASSOCIATION_ORIGIN
            and str(association.get("role") or "").strip()
            == STATEMENT_SOURCE_REVIEW_ASSOCIATION_ROLE
        ):
            _pin, review_error = statement_source_review_effective_semantic_pin(
                association
            )
            if review_error:
                errors.append(f"{field} has an invalid statement review: {review_error}")
            continue

        expected_roles = (
            {"direct_evidence", "transparent_spec"}
            if field == "semantic_contract_source_association"
            else {EXPLICIT_DIRECT_SOURCE_ROUTE_ROLE}
        )
        if association.get("schema") != 2 or str(
            association.get("role") or ""
        ).strip() not in expected_roles:
            errors.append(f"{field} has an unsupported schema or role")
            continue
        if field == "source_statement_association" and str(
            association.get("association_origin") or ""
        ).strip() != EXPLICIT_DIRECT_SOURCE_ROUTE_ORIGIN:
            errors.append(f"{field} has an unsupported association origin")
            continue
        source_identities, identity_errors = source_contract_source_identities(
            association.get("source_item_identities")
        )
        if identity_errors:
            errors.extend(f"{field}: {error}" for error in identity_errors)
            continue
        expected_digest = semantic_source_association_digest(
            source_identities, current_signature
        )
        if not expected_digest or str(
            association.get("semantic_association_sha256") or ""
        ).strip().lower() != expected_digest:
            errors.append(f"{field} has a missing or stale semantic association pin")

    return present, sorted(set(errors))


def _validated_statement_source_route_receipt(
    *,
    paper_dir: Path,
    item: Mapping[str, Any],
    storage_key: str,
    entry: Mapping[str, Any],
    routes: list[Mapping[str, Any]],
    route_inventory: Mapping[str, Mapping[str, Any]],
    source_coverage_mode: str,
    source_proof_fidelity: Mapping[str, Any] | None,
    validator_identities: Mapping[str, str],
    validator_errors: Mapping[str, str],
    elaborated_signature_manifests_by_qualified: Mapping[
        str, Mapping[str, Any]
    ],
    elaborated_signature_sha256_by_qualified: Mapping[str, str],
) -> tuple[dict[str, Any] | None, str]:
    """Validate one exact v10 statement review and every current source pin."""

    from scripts import review_dashboard as dashboard
    from scripts import semantic_audit_reuse as reuse

    reviewed_identity = item.get("reviewed_declaration_identity")
    if not isinstance(reviewed_identity, Mapping):
        return None, "generated row has no reviewed declaration identity"
    qualified = semantic_contract_fully_qualified_identity(
        reviewed_identity.get("qualified_declaration")
    )
    manifest = elaborated_signature_manifests_by_qualified.get(qualified)
    signature_digest = str(
        elaborated_signature_sha256_by_qualified.get(qualified) or ""
    ).strip().lower()
    if not isinstance(manifest, Mapping) or not SHA256_RE.fullmatch(signature_digest):
        return None, "generated row has no current elaborated signature manifest"
    reviewed_signature = reviewed_elaborated_signature_identity(
        reviewed_identity, dict(elaborated_signature_sha256_by_qualified)
    )
    if reviewed_signature is None:
        return None, "generated row has no exact elaborated signature identity"
    if signature_manifest_digest(dict(manifest)) != signature_digest or str(
        entry.get("lean_signature_sha256") or ""
    ).strip().lower() != signature_digest:
        return None, "statement review has a stale elaborated signature receipt"

    validator_identity = str(validator_identities.get(storage_key) or "").strip()
    if not SHA256_RE.fullmatch(validator_identity):
        return None, (
            "statement review has no current reviewer identity: "
            + str(validator_errors.get(storage_key) or "unknown validator error")
        )
    if (
        str(entry.get("judgment") or "").strip().lower() != "matches"
        or entry.get("matches") is not True
        or any(
            isinstance(entry.get(field), list) and entry.get(field)
            for field in (
                "unmatched_source_conclusions",
                "unmatched_source_inputs",
                "unjustified_lean_inputs",
                "unmatched_lean_conclusions",
            )
        )
    ):
        return None, "statement review is not an accepted exact v10 match"
    require_definition_review = bool(
        dashboard.direct_source_definition_route_keys(
            dict(entry),
            inventory={str(key): dict(value) for key, value in route_inventory.items()},
            include_direct_expressions=(
                dashboard.llm_direct_expression_semantics_review_required(paper_dir)
            ),
        )
    )
    ledger_error = dashboard.semantic_obligation_ledger_error(
        dict(entry),
        dict(manifest),
        require_source_definition_semantics_review=require_definition_review,
    )
    route_error = dashboard.source_route_pin_error(
        dict(entry),
        inventory={str(key): dict(value) for key, value in route_inventory.items()},
        require_statement_target=True,
        require_verbatim_source_inputs=(
            dashboard.statement_review_requires_verbatim_source_inputs(entry)
        ),
    )
    if ledger_error or route_error:
        return None, "; ".join(
            error for error in (ledger_error, route_error) if error
        )

    route_semantic_digests = [reuse.route_semantic_sha256(route) for route in routes]
    if (
        any(not SHA256_RE.fullmatch(digest) for digest in route_semantic_digests)
        or len(set(route_semantic_digests)) != len(route_semantic_digests)
    ):
        return None, "statement review has duplicate or malformed semantic source routes"

    embedded_pin, embedded_error = reuse._reuse_pin_from_embedded(
        entry,
        routes,
        current_validator_identity_sha256=validator_identity,
    )
    if embedded_pin is None:
        return None, "statement review has no current semantic reuse receipt: " + embedded_error
    current_structure = reuse.manifest_structure_sha256(manifest)
    current_dependency, dependency_error = reuse.semantic_dependency_sha256(manifest)
    if (
        not current_structure
        or current_structure != embedded_pin.get("manifest_structure_sha256")
        or dependency_error
        or current_dependency != embedded_pin.get("semantic_dependency_sha256")
    ):
        return None, "statement review has a stale elaborated structure/dependency receipt"

    embedded_routes = embedded_pin.get("source_routes")
    if not isinstance(embedded_routes, list) or len(embedded_routes) != len(routes):
        return None, "statement review has no complete entry-local source-route pins"
    current_route_receipts: list[dict[str, Any]] = []
    for route, embedded_route_pin in zip(routes, embedded_routes, strict=True):
        if not isinstance(embedded_route_pin, Mapping):
            return None, "statement review has a malformed entry-local source-route pin"
        route_key = str(route.get("source_item") or "").strip()
        current_source_item = route_inventory.get(route_key)
        if not isinstance(current_source_item, Mapping):
            return None, "statement review source route is absent from current inventory"
        current_source_pin, source_pin_error = reuse.source_reuse_pin(
            current_source_item,
            source_coverage_mode,
            source_proof_fidelity=source_proof_fidelity,
        )
        if current_source_pin is None:
            return None, "statement review source route has no current source pin: " + source_pin_error
        expected_route_semantic = reuse.route_semantic_sha256(route)
        compared_embedded_pin = dict(embedded_route_pin)
        supplied_route_semantic = str(
            compared_embedded_pin.pop("route_semantic_sha256", "") or ""
        ).strip().lower()
        if (
            supplied_route_semantic != expected_route_semantic
            or compared_embedded_pin != current_source_pin
        ):
            return None, "statement review has stale entry-local source-route pins"
        current_route_receipts.append(
            {
                "route_semantic_sha256": supplied_route_semantic,
                "source_reuse_pin": current_source_pin,
            }
        )

    reuse_receipt = entry.get("semantic_reuse_v1")
    review_protocol_digest = (
        str(reuse_receipt.get("formalization_review_protocol_sha256") or "")
        .strip()
        .lower()
        if isinstance(reuse_receipt, Mapping)
        else ""
    )
    if not SHA256_RE.fullmatch(review_protocol_digest):
        return None, "statement review has no current formalization protocol receipt"
    return {
        "reviewed_declaration_identity": dict(reviewed_identity),
        "reviewed_elaborated_signature_identity": reviewed_signature,
        "manifest_structure_sha256": current_structure,
        "semantic_dependency_sha256": current_dependency,
        "review_validator_identity_sha256": validator_identity,
        "review_protocol_sha256": review_protocol_digest,
        "paper_statement_sha256": embedded_pin.get("paper_statement_sha256"),
        "tex_statement_sha256": embedded_pin.get("tex_statement_sha256"),
        "source_route_receipts": sorted(
            current_route_receipts,
            key=stable_digest,
        ),
    }, ""


def _statement_review_source_parent_receipts(
    *,
    routes: list[Mapping[str, Any]],
    receipt: Mapping[str, Any],
    route_inventory: Mapping[str, Mapping[str, Any]],
    raw_source_items: Mapping[str, Any],
    source_coverage_mode: str,
    source_proof_fidelity: Mapping[str, Any] | None,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]], str]:
    """Resolve reviewed routes to source parents by current content pins.

    Route and map keys authenticate navigation only after a unique current
    inventory object has been selected by its complete source-reuse pin.  This
    prevents a declaration, row, function, or source key from choosing the
    semantic parent while retaining exact diagnostics for stale navigation.
    """

    from scripts import semantic_audit_reuse as reuse

    raw_receipts = receipt.get("source_route_receipts")
    if not isinstance(raw_receipts, list) or len(raw_receipts) != len(routes):
        return [], [], "statement review lacks complete source-route receipts"
    receipts_by_semantic: dict[str, list[Mapping[str, Any]]] = {}
    for raw_receipt in raw_receipts:
        if not isinstance(raw_receipt, Mapping):
            return [], [], "statement review has a malformed source-route receipt"
        route_sha = str(
            raw_receipt.get("route_semantic_sha256") or ""
        ).strip().lower()
        if not SHA256_RE.fullmatch(route_sha):
            return [], [], "statement review has a malformed source-route semantic pin"
        receipts_by_semantic.setdefault(route_sha, []).append(raw_receipt)

    inventory_by_pin: dict[str, list[tuple[str, Mapping[str, Any], dict[str, Any]]]] = {}
    for raw_key, raw_item in route_inventory.items():
        if not isinstance(raw_item, Mapping):
            continue
        current_pin, _pin_error = reuse.source_reuse_pin(
            dict(raw_item),
            source_coverage_mode,
            source_proof_fidelity=source_proof_fidelity,
        )
        if not isinstance(current_pin, Mapping):
            continue
        pin = dict(current_pin)
        inventory_by_pin.setdefault(stable_digest(pin), []).append(
            (str(raw_key), raw_item, pin)
        )

    parent_identities_by_semantic: dict[str, dict[str, Any]] = {}
    bound_route_receipts: list[dict[str, Any]] = []
    for route in routes:
        route_sha = reuse.route_semantic_sha256(route)
        matching_receipts = receipts_by_semantic.get(route_sha, [])
        if len(matching_receipts) != 1:
            return [], [], "statement review route has no unique semantic receipt"
        source_reuse_pin = matching_receipts[0].get("source_reuse_pin")
        if not isinstance(source_reuse_pin, Mapping):
            return [], [], "statement review route has no source-reuse pin"
        source_reuse_pin = dict(source_reuse_pin)
        inventory_candidates = inventory_by_pin.get(
            stable_digest(source_reuse_pin), []
        )
        if len(inventory_candidates) != 1:
            return [], [], (
                "statement review route source content is ambiguous in the current inventory"
            )
        inventory_key, inventory_item, current_pin = inventory_candidates[0]
        if str(route.get("source_item") or "").strip() != inventory_key:
            return [], [], (
                "statement review route navigation key is stale after content resolution"
            )
        parent_key = str(
            inventory_item.get("source_component_of") or inventory_key
        ).strip()
        parent_item = raw_source_items.get(parent_key)
        if not isinstance(parent_item, Mapping):
            return [], [], "statement review route has no current source-map parent"
        parent_kind = str(parent_item.get("source_kind") or "").strip().lower()
        if parent_kind not in SOURCE_DOMAIN_PRESENTATION_KINDS:
            return [], [], (
                "whole-definition statement reviews may cite only definition, predicate, or model vocabulary"
            )
        parent_identity = semantic_contract_source_identity(
            parent_key, dict(parent_item)
        )
        parent_semantic_sha = str(
            parent_identity.get("source_semantic_sha256") or ""
        ).strip().lower()
        if not SHA256_RE.fullmatch(parent_semantic_sha):
            return [], [], "statement review source parent has no semantic identity"
        prior_parent = parent_identities_by_semantic.get(parent_semantic_sha)
        if prior_parent is not None and prior_parent != parent_identity:
            return [], [], (
                "statement review source parent identity is ambiguous by content"
            )
        parent_identities_by_semantic[parent_semantic_sha] = parent_identity
        bound_route_receipts.append(
            {
                "route_semantic_sha256": route_sha,
                "source_reuse_pin": current_pin,
                "source_reuse_pin_sha256": stable_digest(current_pin),
                "source_parent_semantic_sha256": parent_semantic_sha,
            }
        )

    return (
        [
            parent_identities_by_semantic[digest]
            for digest in sorted(parent_identities_by_semantic)
        ],
        sorted(bound_route_receipts, key=stable_digest),
        "",
    )


def _authenticated_statement_source_review_association(
    *,
    receipt: Mapping[str, Any],
    source_identities: list[dict[str, Any]],
    bound_route_receipts: list[dict[str, Any]],
) -> tuple[dict[str, Any] | None, str]:
    """Build one schema-2 whole-definition association from a v10 receipt."""

    reviewed_identity = receipt.get("reviewed_declaration_identity")
    reviewed_signature = receipt.get("reviewed_elaborated_signature_identity")
    if not isinstance(reviewed_identity, Mapping) or not isinstance(
        reviewed_signature, Mapping
    ):
        return None, "statement review receipt lacks declaration/signature identity"
    review_identity: dict[str, Any] = {
        "schema": STATEMENT_SOURCE_REVIEW_IDENTITY_SCHEMA,
        "declaration_content_sha256": str(
            reviewed_identity.get("declaration_sha256") or ""
        ).strip().lower(),
        "elaborated_signature_sha256": str(
            reviewed_signature.get("elaborated_signature_sha256") or ""
        ).strip().lower(),
        "manifest_structure_sha256": receipt.get("manifest_structure_sha256"),
        "semantic_dependency_sha256": receipt.get("semantic_dependency_sha256"),
        "review_validator_identity_sha256": receipt.get(
            "review_validator_identity_sha256"
        ),
        "review_protocol_sha256": receipt.get("review_protocol_sha256"),
        "paper_statement_sha256": receipt.get("paper_statement_sha256"),
        "tex_statement_sha256": receipt.get("tex_statement_sha256"),
        "source_route_receipts": bound_route_receipts,
    }
    semantic_pin = statement_source_review_semantic_association_digest(
        review_identity, source_identities, reviewed_signature
    )
    if not semantic_pin:
        return None, "statement review cannot form a semantic association pin"
    association: dict[str, Any] = {
        "schema": 2,
        "association_origin": STATEMENT_SOURCE_REVIEW_ASSOCIATION_ORIGIN,
        "role": STATEMENT_SOURCE_REVIEW_ASSOCIATION_ROLE,
        "reviewed_declaration_identity": dict(reviewed_identity),
        "reviewed_elaborated_signature_identity": dict(reviewed_signature),
        "source_item_identities": source_identities,
        STATEMENT_SOURCE_REVIEW_IDENTITY_FIELD: review_identity,
        "semantic_association_sha256": semantic_pin,
        "review_scope": "complete_whole_definition",
        "structural_pairing": "authenticated_statement_review_equivalence",
    }
    association["association_sha256"] = stable_digest(association)
    effective_pin, association_error = (
        statement_source_review_effective_semantic_pin(association)
    )
    if association_error or effective_pin != semantic_pin:
        return None, (
            "generated statement source-review association is invalid: "
            + (association_error or "semantic pin mismatch")
        )
    return association, ""


def _normalized_assumption_premise(value: object) -> str:
    """Normalize premise presentation without using it as semantic identity."""

    return normalize_ws(str(value or ""))


def _assumption_source_parent_receipts(
    *,
    routes: list[Mapping[str, Any]],
    raw_route_receipts: list[Mapping[str, Any]],
    route_inventory: Mapping[str, Mapping[str, Any]],
    raw_source_items: Mapping[str, Any],
    source_coverage_mode: str,
    source_proof_fidelity: Mapping[str, Any] | None,
) -> tuple[list[dict[str, Any]], list[dict[str, Any]], str]:
    """Resolve assumption routes by exact current content before navigation."""

    from scripts import semantic_audit_reuse as reuse

    receipts_by_semantic: dict[str, list[Mapping[str, Any]]] = {}
    for receipt in raw_route_receipts:
        route_sha = str(
            receipt.get("route_semantic_sha256") or ""
        ).strip().lower()
        if not SHA256_RE.fullmatch(route_sha):
            return [], [], "assumption review has a malformed route semantic pin"
        receipts_by_semantic.setdefault(route_sha, []).append(receipt)

    inventory_by_pin: dict[
        str, list[tuple[str, Mapping[str, Any], dict[str, Any]]]
    ] = {}
    for raw_key, raw_item in route_inventory.items():
        if not isinstance(raw_item, Mapping):
            continue
        current_pin, _pin_error = reuse.source_reuse_pin(
            dict(raw_item),
            source_coverage_mode,
            source_proof_fidelity=source_proof_fidelity,
        )
        if not isinstance(current_pin, Mapping):
            continue
        pin = dict(current_pin)
        inventory_by_pin.setdefault(stable_digest(pin), []).append(
            (str(raw_key), raw_item, pin)
        )

    parent_identities_by_semantic: dict[str, dict[str, Any]] = {}
    bound_route_receipts: list[dict[str, Any]] = []
    for route in routes:
        route_sha = reuse.route_semantic_sha256(route)
        matching_receipts = receipts_by_semantic.get(route_sha, [])
        if len(matching_receipts) != 1:
            return [], [], "assumption source route has no unique semantic receipt"
        recorded_pin = matching_receipts[0].get("source_reuse_pin")
        if not isinstance(recorded_pin, Mapping):
            return [], [], "assumption source route has no source-reuse pin"
        inventory_candidates = inventory_by_pin.get(
            stable_digest(dict(recorded_pin)), []
        )
        if len(inventory_candidates) != 1:
            return [], [], (
                "assumption source-route content is absent or ambiguous in the current inventory"
            )
        inventory_key, inventory_item, current_pin = inventory_candidates[0]
        # Only after unique content resolution may the route key authenticate
        # navigation to that object.
        if str(route.get("source_item") or "").strip() != inventory_key:
            return [], [], (
                "assumption source-route navigation key is stale after content resolution"
            )
        route_match_error = reuse._route_matches_item(route, inventory_item)
        if route_match_error:
            return [], [], "assumption source route is stale: " + route_match_error
        parent_key = str(
            inventory_item.get("source_component_of") or inventory_key
        ).strip()
        parent_item = raw_source_items.get(parent_key)
        if not isinstance(parent_item, Mapping):
            return [], [], "assumption source route has no current source-map parent"
        parent_identity = semantic_contract_source_identity(
            parent_key, dict(parent_item)
        )
        parent_semantic_sha = str(
            parent_identity.get("source_semantic_sha256") or ""
        ).strip().lower()
        if not SHA256_RE.fullmatch(parent_semantic_sha):
            return [], [], "assumption source parent has no semantic identity"
        prior_parent = parent_identities_by_semantic.get(parent_semantic_sha)
        if prior_parent is not None and prior_parent != parent_identity:
            return [], [], "assumption source-parent content identity is ambiguous"
        parent_identities_by_semantic[parent_semantic_sha] = parent_identity
        bound_route_receipts.append(
            {
                "route_semantic_sha256": route_sha,
                "source_reuse_pin": current_pin,
                "source_reuse_pin_sha256": stable_digest(current_pin),
                "source_parent_semantic_sha256": parent_semantic_sha,
            }
        )
    return (
        [
            parent_identities_by_semantic[digest]
            for digest in sorted(parent_identities_by_semantic)
        ],
        sorted(bound_route_receipts, key=stable_digest),
        "",
    )


def attach_assumption_source_review_associations(
    items: list[dict[str, Any]],
    *,
    paper_dir: Path,
    paper_statement_map: Mapping[str, Any] | None,
    source_proof_fidelity: Mapping[str, Any] | None,
    elaborated_signature_manifests_by_qualified: Mapping[
        str, Mapping[str, Any]
    ],
    elaborated_signature_sha256_by_qualified: Mapping[str, str],
) -> tuple[list[dict[str, Any]], list[str], dict[str, int]]:
    """Attach opt-in, authenticated assumption-review source parents.

    Candidate entries and generated rows are joined only by the exact current
    declaration-content SHA, then checked against Lean's elaborated signature
    and premise atoms.  Sidecar keys, declaration/function names, source-map
    keys, and premise spellings never select a semantic match.
    """

    counts = {
        "assumption_source_review_candidate_count": 0,
        "assumption_source_review_association_count": 0,
    }
    if not isinstance(paper_statement_map, Mapping):
        return items, [], counts
    raw_source_items = paper_statement_map.get("items")
    if not isinstance(raw_source_items, Mapping):
        return items, [
            "assumption source-review association has no current source-map items"
        ], counts

    from scripts import review_dashboard as dashboard
    from scripts import semantic_audit_reuse as reuse

    sidecar = load_json_object(paper_dir / "audit" / "assumption_match_llm.json")
    raw_sidecar_items = sidecar.get("items")
    if not isinstance(raw_sidecar_items, Mapping):
        return items, [], counts
    if sidecar.get("schema") != 1:
        return items, [
            "assumption source-review sidecar must retain schema 1"
        ], counts
    validator_identities, validator_errors = reuse.review_validator_identities(
        sidecar,
        expected_prompt_version=dashboard.REQUIRED_LLM_ASSUMPTION_PROMPT_VERSION,
    )
    mode, mode_error = source_coverage_mode_from_map(dict(paper_statement_map))
    if mode_error:
        return items, [
            "assumption source-review cannot read source coverage mode: "
            + mode_error
        ], counts

    route_inventory: dict[str, dict[str, Any]] = {}
    for inventory in (
        dashboard.paper_statement_inventory(paper_dir),
        dashboard.paper_source_component_route_inventory(paper_dir),
        dashboard.paper_source_definition_component_route_inventory(paper_dir),
    ):
        for raw_key, raw_item in inventory.items():
            if not isinstance(raw_item, Mapping):
                continue
            key = str(raw_key)
            item = dict(raw_item)
            if key in route_inventory and route_inventory[key] != item:
                return items, [
                    "assumption source-review route inventory has a key collision"
                ], counts
            route_inventory[key] = item

    items_by_declaration_sha: dict[str, list[dict[str, Any]]] = {}
    for item in items:
        reviewed_identity = item.get("reviewed_declaration_identity")
        declaration_sha = (
            str(reviewed_identity.get("declaration_sha256") or "")
            .strip()
            .lower()
            if isinstance(reviewed_identity, Mapping)
            else ""
        )
        if SHA256_RE.fullmatch(declaration_sha):
            items_by_declaration_sha.setdefault(declaration_sha, []).append(item)

    candidates_by_declaration_sha: dict[
        str, list[tuple[str, Mapping[str, Any], Mapping[str, Any]]]
    ] = {}
    for storage_key, raw_entry in raw_sidecar_items.items():
        if not isinstance(raw_entry, Mapping):
            continue
        raw_receipt = raw_entry.get(
            SOURCE_ASSUMPTION_SEMANTIC_PARENT_RECEIPT_FIELD
        )
        if not isinstance(raw_receipt, Mapping):
            continue
        counts["assumption_source_review_candidate_count"] += 1
        declaration_sha = str(
            raw_receipt.get("raw_lean_declaration_sha256") or ""
        ).strip().lower()
        if not SHA256_RE.fullmatch(declaration_sha):
            # An opt-in receipt with no exact content identity is an error, not
            # an invitation to fall back to the entry/declaration name.
            candidates_by_declaration_sha.setdefault("<malformed>", []).append(
                (str(storage_key), raw_entry, raw_receipt)
            )
            continue
        candidates_by_declaration_sha.setdefault(declaration_sha, []).append(
            (str(storage_key), raw_entry, raw_receipt)
        )

    errors: list[str] = []
    for declaration_sha, candidates in sorted(candidates_by_declaration_sha.items()):
        members = items_by_declaration_sha.get(declaration_sha, [])
        if len(candidates) != 1 or len(members) != 1:
            errors.append(
                "assumption review declaration-content identity is ambiguous "
                f"({len(candidates)} review candidates, {len(members)} semantic rows)"
            )
            continue
        storage_key, entry, receipt = candidates[0]
        item = members[0]
        competing = [
            field
            for field in _SOURCE_RECORD_ITEM_IDENTITY_FIELDS
            if field != SOURCE_ASSUMPTION_ASSOCIATION_FIELD
            and isinstance(item.get(field), Mapping)
        ]
        if competing:
            errors.append(
                "assumption review source route collides with another generated source association: "
                + ", ".join(sorted(competing))
            )
            continue
        if receipt.get("schema") != SOURCE_ASSUMPTION_SEMANTIC_PARENT_RECEIPT_SCHEMA:
            errors.append("assumption semantic-parent receipt must use schema 1")
            continue

        reviewed_identity = item.get("reviewed_declaration_identity")
        if not isinstance(reviewed_identity, Mapping):
            errors.append("assumption review row has no declaration-content identity")
            continue
        qualified = semantic_contract_fully_qualified_identity(
            reviewed_identity.get("qualified_declaration")
        )
        manifest = elaborated_signature_manifests_by_qualified.get(qualified)
        signature_sha = str(
            elaborated_signature_sha256_by_qualified.get(qualified) or ""
        ).strip().lower()
        reviewed_signature = reviewed_elaborated_signature_identity(
            reviewed_identity, dict(elaborated_signature_sha256_by_qualified)
        )
        if (
            not isinstance(manifest, Mapping)
            or reviewed_signature is None
            or not SHA256_RE.fullmatch(signature_sha)
            or signature_manifest_digest(dict(manifest)) != signature_sha
        ):
            errors.append("assumption review row has no current elaborated signature")
            continue
        if (
            str(receipt.get("lean_signature_sha256") or "").strip().lower()
            != signature_sha
            or str(entry.get("lean_signature_sha256") or "").strip().lower()
            != signature_sha
        ):
            errors.append("assumption review has a stale elaborated-signature receipt")
            continue
        current_structure = reuse.manifest_structure_sha256(manifest)
        current_dependency, dependency_error = reuse.semantic_dependency_sha256(
            manifest
        )
        if (
            not current_structure
            or str(receipt.get("manifest_structure_sha256") or "")
            .strip()
            .lower()
            != current_structure
            or dependency_error
            or str(receipt.get("semantic_dependency_sha256") or "")
            .strip()
            .lower()
            != current_dependency
        ):
            errors.append(
                "assumption review has a stale elaborated structure/dependency receipt"
            )
            continue
        validator_identity = str(
            validator_identities.get(storage_key) or ""
        ).strip().lower()
        if (
            not SHA256_RE.fullmatch(validator_identity)
            or str(receipt.get("review_validator_identity_sha256") or "")
            .strip()
            .lower()
            != validator_identity
        ):
            errors.append(
                "assumption review has no current reviewer identity: "
                + str(validator_errors.get(storage_key) or "stale receipt")
            )
            continue
        if not formalization_protocol_receipt_matches(receipt, scope="review"):
            errors.append("assumption review has no current formalization protocol pin")
            continue

        judgment = str(entry.get("judgment") or "").strip().lower()
        if judgment not in SOURCE_ASSUMPTION_ACCEPTED_JUDGMENTS:
            errors.append(
                "assumption semantic-parent review is not an accepted source assumption/condition"
            )
            continue
        raw_premises = entry.get("premises")
        premises = (
            [_normalized_assumption_premise(value) for value in raw_premises]
            if isinstance(raw_premises, list)
            else []
        )
        if any(not value for value in premises) or len(premises) != len(set(premises)):
            errors.append("assumption review has malformed or duplicate premises")
            continue
        raw_judgments = entry.get("premise_judgments")
        premise_judgments: dict[str, Mapping[str, Any]] = {}
        if isinstance(raw_judgments, Mapping):
            for raw_premise, raw_judgment in raw_judgments.items():
                premise = _normalized_assumption_premise(raw_premise)
                if (
                    not premise
                    or premise in premise_judgments
                    or not isinstance(raw_judgment, Mapping)
                ):
                    premise_judgments = {}
                    break
                premise_judgments[premise] = raw_judgment
        if set(premises) != set(premise_judgments):
            errors.append(
                "assumption review premise judgments do not exactly cover its declared premises"
            )
            continue

        raw_atoms = manifest.get("atoms")
        manifest_premise_atoms = sorted(
            dashboard.signature_manifest_atom_digest(atom)
            for atom in raw_atoms
            if isinstance(atom, dict)
            and str(atom.get("role") or "").strip().lower() == "assumption"
        ) if isinstance(raw_atoms, list) else []
        if any(not SHA256_RE.fullmatch(value) for value in manifest_premise_atoms):
            errors.append("assumption review has malformed current premise atoms")
            continue
        if str(manifest.get("declaration_kind") or "").strip() == "definition":
            lean_partition, partition_error = (
                transparent_conclusion_component_partition(manifest)
            )
            if lean_partition is None:
                lean_partition, type_partition_error = (
                    transparent_type_carrier_partition(manifest)
                )
                if lean_partition is not None:
                    partition_error = type_partition_error
                else:
                    partition_error = (
                        partition_error + "; " + type_partition_error
                    ).strip("; ")
        elif manifest_premise_atoms:
            lean_partition, partition_error = outer_assumption_atom_partition(
                manifest_premise_atoms
            )
        else:
            lean_partition, partition_error = (
                None,
                "nondefinition declaration has no elaborated assumption atoms",
            )
        if lean_partition is None or partition_error:
            errors.append(
                "assumption review has no complete Lean-derived semantic partition: "
                + (partition_error or "unknown partition failure")
            )
            continue
        recorded_partition = receipt.get("lean_semantic_partition")
        recorded_partition_errors = lean_semantic_partition_errors(
            recorded_partition
        )
        if (
            recorded_partition_errors
            or not isinstance(recorded_partition, Mapping)
            or str(recorded_partition.get("partition_sha256") or "")
            .strip()
            .lower()
            != str(lean_partition.get("partition_sha256") or "").strip().lower()
        ):
            errors.append(
                "assumption review has a stale or incomplete Lean semantic partition"
            )
            continue
        component_occurrence_shas = {
            str(component.get("component_occurrence_sha256") or "")
            .strip()
            .lower()
            for component in lean_partition.get("components", [])
            if isinstance(component, Mapping)
        }
        raw_component_map = receipt.get(
            "premise_component_occurrence_sha256s_by_premise"
        )
        component_map: dict[str, set[str]] = {}
        if isinstance(raw_component_map, Mapping):
            for raw_premise, raw_digests in raw_component_map.items():
                premise = _normalized_assumption_premise(raw_premise)
                digests = (
                    {
                        str(raw_digest or "").strip().lower()
                        for raw_digest in raw_digests
                    }
                    if isinstance(raw_digests, list)
                    else set()
                )
                if (
                    not premise
                    or premise in component_map
                    or not digests
                    or len(digests) != len(raw_digests or [])
                    or any(not SHA256_RE.fullmatch(value) for value in digests)
                    or not digests.issubset(component_occurrence_shas)
                ):
                    component_map = {}
                    break
                component_map[premise] = digests
        if set(component_map) != set(premises):
            errors.append(
                "assumption review does not map every premise presentation to Lean components"
            )
            continue

        raw_alias_groups = receipt.get("premise_alias_groups", [])
        alias_groups_by_premise_set: dict[frozenset[str], set[str]] = {}
        aliased_premises: set[str] = set()
        malformed_alias_group = False
        if not isinstance(raw_alias_groups, list):
            malformed_alias_group = True
            raw_alias_groups = []
        for raw_group in raw_alias_groups:
            if not isinstance(raw_group, Mapping):
                malformed_alias_group = True
                break
            raw_group_premises = raw_group.get("premises")
            group_premises = (
                {
                    _normalized_assumption_premise(value)
                    for value in raw_group_premises
                }
                if isinstance(raw_group_premises, list)
                else set()
            )
            raw_group_components = raw_group.get(
                "lean_component_occurrence_sha256s"
            )
            group_components = (
                {
                    str(value or "").strip().lower()
                    for value in raw_group_components
                }
                if isinstance(raw_group_components, list)
                else set()
            )
            premise_set = frozenset(group_premises)
            if (
                len(group_premises) < 2
                or len(group_premises) != len(raw_group_premises or [])
                or not group_premises.issubset(component_map)
                or group_premises & aliased_premises
                or not group_components
                or len(group_components) != len(raw_group_components or [])
                or not group_components.issubset(component_occurrence_shas)
                or any(
                    component_map[premise] != group_components
                    for premise in group_premises
                )
                or premise_set in alias_groups_by_premise_set
            ):
                malformed_alias_group = True
                break
            alias_groups_by_premise_set[premise_set] = group_components
            aliased_premises.update(group_premises)
        component_presentations: dict[str, set[str]] = {}
        for premise, component_shas in component_map.items():
            for component_sha in component_shas:
                component_presentations.setdefault(component_sha, set()).add(premise)
        if set(component_presentations) != component_occurrence_shas:
            errors.append(
                "assumption review premise mapping omits a Lean semantic component"
            )
            continue
        for component_sha, presentations in component_presentations.items():
            if len(presentations) <= 1:
                continue
            expected_alias_components = alias_groups_by_premise_set.get(
                frozenset(presentations)
            )
            if (
                expected_alias_components is None
                or component_sha not in expected_alias_components
            ):
                malformed_alias_group = True
                break
        if malformed_alias_group or any(
            all(len(component_presentations[value]) <= 1 for value in components)
            for components in alias_groups_by_premise_set.values()
        ):
            errors.append(
                "assumption review duplicates a Lean component without an exact explicit alias group"
            )
            continue

        raw_routes = entry.get("source_routes")
        routes = (
            [route for route in raw_routes if isinstance(route, Mapping)]
            if isinstance(raw_routes, list)
            else []
        )
        if not routes or len(routes) != len(raw_routes or []):
            errors.append("assumption review has no complete explicit source routes")
            continue
        route_semantic_shas = [reuse.route_semantic_sha256(route) for route in routes]
        if (
            any(not SHA256_RE.fullmatch(value) for value in route_semantic_shas)
            or len(route_semantic_shas) != len(set(route_semantic_shas))
        ):
            errors.append("assumption review has duplicate or malformed source routes")
            continue
        recorded_reviewed_routes = receipt.get(
            "reviewed_source_route_semantic_sha256s"
        )
        if (
            not isinstance(recorded_reviewed_routes, list)
            or sorted(str(value or "").strip().lower() for value in recorded_reviewed_routes)
            != sorted(route_semantic_shas)
        ):
            errors.append("assumption review does not bind its complete source-route set")
            continue
        raw_route_receipts = receipt.get("source_route_receipts")
        route_receipts = (
            [value for value in raw_route_receipts if isinstance(value, Mapping)]
            if isinstance(raw_route_receipts, list)
            else []
        )
        if len(route_receipts) != len(routes) or len(route_receipts) != len(
            raw_route_receipts or []
        ):
            errors.append("assumption review lacks complete source-route receipts")
            continue

        premise_receipts_by_sha: dict[str, dict[str, Any]] = {}
        premise_review_sha_by_presentation: dict[str, str] = {}
        premise_route_union: set[str] = set()
        malformed_premise = ""
        for premise in premises:
            raw_judgment = premise_judgments[premise]
            premise_judgment = str(
                raw_judgment.get("judgment") or ""
            ).strip().lower()
            reason = normalize_ws(str(raw_judgment.get("reason") or ""))
            raw_premise_routes = raw_judgment.get(
                "source_route_semantic_sha256s"
            )
            premise_routes = (
                sorted(str(value or "").strip().lower() for value in raw_premise_routes)
                if isinstance(raw_premise_routes, list)
                else []
            )
            if (
                premise_judgment
                not in SOURCE_ASSUMPTION_ACCEPTED_PREMISE_JUDGMENTS
                or not reason
                or not premise_routes
                or len(premise_routes) != len(set(premise_routes))
                or not set(premise_routes).issubset(route_semantic_shas)
            ):
                malformed_premise = premise
                break
            premise_route_union.update(premise_routes)
            premise_receipt: dict[str, Any] = {
                "lean_component_occurrence_sha256s": sorted(
                    component_map[premise]
                ),
                "judgment": premise_judgment,
                "reason": reason,
                "source_route_semantic_sha256s": premise_routes,
            }
            premise_receipt["premise_review_sha256"] = (
                source_assumption_premise_review_digest(premise_receipt)
            )
            premise_sha = str(premise_receipt["premise_review_sha256"])
            if not SHA256_RE.fullmatch(premise_sha):
                malformed_premise = premise
                break
            premise_review_sha_by_presentation[premise] = premise_sha
            existing_premise_receipt = premise_receipts_by_sha.get(premise_sha)
            if existing_premise_receipt is None:
                premise_receipt["presentation_count"] = 1
                premise_receipts_by_sha[premise_sha] = premise_receipt
            else:
                existing_premise_receipt["presentation_count"] = int(
                    existing_premise_receipt.get("presentation_count") or 0
                ) + 1
        premise_receipts = list(premise_receipts_by_sha.values())
        if malformed_premise or (
            premise_receipts and premise_route_union != set(route_semantic_shas)
        ):
            errors.append(
                "assumption premise judgments lack complete accepted source-route bindings"
                + (f" for `{malformed_premise}`" if malformed_premise else "")
            )
            continue

        alias_group_receipts: list[dict[str, Any]] = []
        for presentation_set, group_components in sorted(
            alias_groups_by_premise_set.items(),
            key=lambda item: sorted(item[0]),
        ):
            member_counts: dict[str, int] = {}
            for premise in presentation_set:
                premise_sha = premise_review_sha_by_presentation[premise]
                member_counts[premise_sha] = member_counts.get(premise_sha, 0) + 1
            alias_group_receipt: dict[str, Any] = {
                "lean_component_occurrence_sha256s": sorted(group_components),
                "members": [
                    {
                        "premise_review_sha256": premise_sha,
                        "presentation_count": count,
                    }
                    for premise_sha, count in sorted(member_counts.items())
                ],
                "presentation_count": len(presentation_set),
            }
            alias_group_receipt["alias_group_sha256"] = (
                source_assumption_alias_group_digest(alias_group_receipt)
            )
            if not SHA256_RE.fullmatch(
                str(alias_group_receipt["alias_group_sha256"])
            ):
                malformed_premise = "alias group"
                break
            alias_group_receipts.append(alias_group_receipt)
        if malformed_premise:
            errors.append("assumption review has a malformed semantic alias group")
            continue

        source_identities, bound_route_receipts, parent_error = (
            _assumption_source_parent_receipts(
                routes=routes,
                raw_route_receipts=route_receipts,
                route_inventory=route_inventory,
                raw_source_items=raw_source_items,
                source_coverage_mode=mode,
                source_proof_fidelity=source_proof_fidelity,
            )
        )
        if parent_error:
            errors.append(
                "assumption review has no exact current source parents: "
                + parent_error
            )
            continue
        anchor_errors = explicit_direct_source_route_anchor_errors(
            paper_dir,
            dict(paper_statement_map),
            source_keys={
                str(identity.get("source_key") or "").strip()
                for identity in source_identities
            },
        )
        if anchor_errors:
            errors.append(
                "assumption review has stale source bytes: "
                + "; ".join(anchor_errors)
            )
            continue

        review_semantic_payload = {
            "schema": SOURCE_ASSUMPTION_REVIEW_IDENTITY_SCHEMA,
            "judgment": judgment,
            "lean_semantic_partition_sha256": str(
                lean_partition.get("partition_sha256") or ""
            ).strip().lower(),
            "premise_reviews": sorted(
                (
                    {
                        "premise_review_sha256": str(
                            premise_receipt["premise_review_sha256"]
                        ),
                        "presentation_count": int(
                            premise_receipt["presentation_count"]
                        ),
                    }
                    for premise_receipt in premise_receipts
                ),
                key=lambda value: value["premise_review_sha256"],
            ),
            "premise_alias_group_sha256s": sorted(
                str(alias_receipt["alias_group_sha256"])
                for alias_receipt in alias_group_receipts
            ),
            "source_route_semantic_sha256s": sorted(route_semantic_shas),
        }
        review_identity: dict[str, Any] = {
            "schema": SOURCE_ASSUMPTION_REVIEW_IDENTITY_SCHEMA,
            "declaration_content_sha256": declaration_sha,
            "elaborated_signature_sha256": signature_sha,
            "manifest_structure_sha256": current_structure,
            "semantic_dependency_sha256": current_dependency,
            "review_validator_identity_sha256": validator_identity,
            "review_protocol_sha256": str(
                receipt.get("formalization_review_protocol_sha256") or ""
            ).strip().lower(),
            "judgment": judgment,
            "lean_semantic_partition": lean_partition,
            "premise_receipts": sorted(premise_receipts, key=stable_digest),
            "premise_alias_group_receipts": sorted(
                alias_group_receipts, key=stable_digest
            ),
            "source_route_receipts": bound_route_receipts,
            "assumption_review_semantic_sha256": stable_digest(
                review_semantic_payload
            ),
        }
        association, association_error = build_source_assumption_association(
            reviewed_declaration_identity=reviewed_identity,
            reviewed_signature_identity=reviewed_signature,
            source_item_identities=source_identities,
            review_identity=review_identity,
        )
        if association is None:
            errors.append(
                "assumption review cannot materialize a semantic parent: "
                + association_error
            )
            continue
        item[SOURCE_ASSUMPTION_ASSOCIATION_FIELD] = association
        item["required_check"] = (
            str(item.get("required_check") or "")
            + " This configured assumption row has an accepted, complete "
            "assumption-provenance review bound to its exact declaration "
            "content, elaborated signature and Lean-derived semantic "
            "components, and byte-pinned current source routes. Names are "
            "navigation only."
        )
        counts["assumption_source_review_association_count"] += 1

    return items, sorted(set(errors)), counts


def _dashboard_visible_statement_content_identity(
    item: Mapping[str, Any],
    *,
    dashboard: Any,
    elaborated_signature_sha256_by_qualified: Mapping[str, str],
) -> tuple[tuple[str, str], str] | None:
    """Return the dashboard statement/signature identity for a generated row.

    The generated source-record row owns the complete declaration, including a
    theorem proof body.  Statement review owns the dashboard projection, which
    deliberately removes that proof body.  Reuse the dashboard's collector so
    these two audit surfaces cannot drift onto subtly different parsers.

    The qualified declaration only navigates from an already generated row to
    its Lean-produced signature.  It is not compared with a sidecar key or
    declaration spelling; the resulting content tuple is the match selector.
    """

    reviewed_identity = item.get("reviewed_declaration_identity")
    declaration = item.get("lean_source_declaration")
    if not isinstance(reviewed_identity, Mapping) or not isinstance(
        declaration, str
    ):
        return None
    full_declaration_sha = str(
        reviewed_identity.get("declaration_sha256") or ""
    ).strip().lower()
    if (
        not SHA256_RE.fullmatch(full_declaration_sha)
        or hashlib.sha256(declaration.encode("utf-8")).hexdigest()
        != full_declaration_sha
    ):
        return None

    declaration_match = dashboard.DECL_RE.match(declaration)
    if declaration_match is None:
        return None
    collected = dashboard.collect_review_decl_text(
        declaration.splitlines(), 0, declaration_match.group("kind")
    )
    if collected is None:
        return None
    dashboard_statement, _next_line = collected
    if not dashboard_statement:
        return None

    qualified = semantic_contract_fully_qualified_identity(
        reviewed_identity.get("qualified_declaration")
    )
    signature_digest = str(
        elaborated_signature_sha256_by_qualified.get(qualified) or ""
    ).strip().lower()
    normalized_statement_digest = dashboard.statement_digest(
        dashboard_statement
    )
    if not SHA256_RE.fullmatch(signature_digest) or not SHA256_RE.fullmatch(
        normalized_statement_digest
    ):
        return None
    raw_statement_digest = hashlib.sha256(
        dashboard_statement.encode("utf-8")
    ).hexdigest()
    return (
        (normalized_statement_digest, signature_digest),
        raw_statement_digest,
    )


def attach_statement_source_component_associations(
    items: list[dict[str, Any]],
    *,
    paper_dir: Path,
    paper_statement_map: Mapping[str, Any] | None,
    source_proof_fidelity: Mapping[str, Any] | None,
    elaborated_signature_manifests_by_qualified: Mapping[
        str, Mapping[str, Any]
    ],
    elaborated_signature_sha256_by_qualified: Mapping[str, str],
) -> tuple[list[dict[str, Any]], list[str], dict[str, int]]:
    """Project authenticated v10 definition clauses onto semantic-model rows.

    The join from a statement judgment to a generated row uses a unique pair
    of dashboard-normalized statement content and current elaborated Lean
    signature.  The dashboard projection is derived from the generated row's
    exact full declaration with the dashboard's own parser, so proof-body-only
    changes do not invalidate a statement review.  The full declaration SHA is
    still retained in the emitted association.  The source role is then
    resolved uniquely from partition, component, clause, anchor, and
    source-location content.  Sidecar storage keys, row labels, declaration
    spellings, and function names are never match selectors.

    The resulting association deliberately keeps its parent source-map item
    only for scoped context/ledger lookup.  Its separate component identity is
    the reusable semantic discriminator; it does not claim that one clause is
    the whole parent definition for source-target disposition purposes.
    """

    counts = {
        "statement_source_component_candidate_count": 0,
        "statement_source_component_association_count": 0,
        "statement_source_component_existing_owner_skip_count": 0,
        "statement_source_review_candidate_count": 0,
        "statement_source_review_association_count": 0,
        "statement_aggregate_source_review_candidate_count": 0,
        "statement_aggregate_source_review_receipt_count": 0,
    }
    if not isinstance(paper_statement_map, Mapping):
        return items, [], counts
    raw_map_items = paper_statement_map.get("items")
    if not isinstance(raw_map_items, Mapping):
        return items, [
            "statement source-component association has no current source-map items"
        ], counts

    # These imports are lazy because the source-record generator is itself an
    # input to dashboard/reuse tooling.  Importing them at module load time
    # would create an avoidable audit-tool dependency cycle.
    from scripts import review_dashboard as dashboard
    from scripts import semantic_audit_reuse as reuse

    sidecar = load_json_object(paper_dir / "audit" / "statement_match_llm.json")
    raw_sidecar_items = sidecar.get("items")
    if not isinstance(raw_sidecar_items, Mapping):
        return items, [], counts
    validator_identities, validator_errors = reuse.review_validator_identities(
        sidecar,
        expected_prompt_version=dashboard.REQUIRED_LLM_STATEMENT_PROMPT_VERSION,
    )
    component_inventory = dashboard.paper_source_definition_component_route_inventory(
        paper_dir
    )
    components_by_content: dict[
        tuple[str, str, str, str, str], list[tuple[str, dict[str, Any]]]
    ] = {}
    for component_key, raw_component in component_inventory.items():
        if not isinstance(raw_component, Mapping):
            continue
        component = dict(raw_component)
        identity = _statement_source_component_route_content_identity(
            {
                "source_statement_sha256": component.get("statement_sha256"),
                "source_definition_partition_sha256": component.get(
                    "source_definition_partition_sha256"
                ),
                "source_definition_component_sha256": component.get(
                    "source_definition_component_sha256"
                ),
                "source_component_anchor_sha256": component.get(
                    "source_component_anchor_sha256"
                ),
                "source_location": component.get("source_location"),
            }
        )
        if identity is not None:
            components_by_content.setdefault(identity, []).append(
                (str(component_key), component)
            )

    mode, mode_error = source_coverage_mode_from_map(dict(paper_statement_map))
    if mode_error:
        return items, [
            "statement source-component association cannot read source coverage mode: "
            + mode_error
        ], counts

    items_by_statement_identity: dict[
        tuple[str, str], list[tuple[dict[str, Any], str]]
    ] = {}
    for item in items:
        if not isinstance(item, dict):
            continue
        content_identity = _dashboard_visible_statement_content_identity(
            item,
            dashboard=dashboard,
            elaborated_signature_sha256_by_qualified=(
                elaborated_signature_sha256_by_qualified
            ),
        )
        if content_identity is None:
            continue
        statement_identity, raw_statement_sha = content_identity
        items_by_statement_identity.setdefault(statement_identity, []).append(
            (item, raw_statement_sha)
        )

    errors: list[str] = []
    candidate_entries_by_statement_identity: dict[
        tuple[str, str],
        list[tuple[str, Mapping[str, Any], Mapping[str, Any]]],
    ] = {}
    whole_review_entries_by_statement_identity: dict[
        tuple[str, str],
        list[tuple[str, Mapping[str, Any], list[Mapping[str, Any]]]],
    ] = {}
    for storage_key, raw_entry in raw_sidecar_items.items():
        if not isinstance(raw_entry, Mapping):
            continue
        reuse_receipt = raw_entry.get("semantic_reuse_v1")
        normalized_statement_sha = (
            str(
                reuse_receipt.get("normalized_lean_statement_sha256") or ""
            )
            .strip()
            .lower()
            if isinstance(reuse_receipt, Mapping)
            else ""
        )
        signature_sha = str(
            raw_entry.get("lean_signature_sha256") or ""
        ).strip().lower()
        statement_identity = (normalized_statement_sha, signature_sha)
        # This narrow association lane starts from a unique semantic-content
        # join into the current generated model. Sidecar rows outside that
        # model remain the responsibility of their ordinary associations.
        # Storage keys and declaration names are intentionally not fallbacks.
        if (
            not SHA256_RE.fullmatch(normalized_statement_sha)
            or not SHA256_RE.fullmatch(signature_sha)
            or statement_identity not in items_by_statement_identity
        ):
            continue
        routes = raw_entry.get("source_routes")
        if not isinstance(routes, list):
            continue
        component_routes = [
            route
            for route in routes
            if isinstance(route, Mapping)
            and str(route.get("route_kind") or "").strip().lower()
            == "source_component"
        ]
        member_records = items_by_statement_identity.get(statement_identity, [])
        members = [member for member, _raw_sha in member_records]
        if len(members) == 1:
            owner_fields, owner_errors = (
                _statement_source_component_existing_owner_errors(
                    members[0], elaborated_signature_sha256_by_qualified
                )
            )
            if owner_fields:
                if owner_errors:
                    errors.extend(
                        "statement source-component candidate has an invalid existing "
                        f"source association ({', '.join(owner_fields)}): {error}"
                        for error in owner_errors
                    )
                else:
                    counts[
                        "statement_source_component_existing_owner_skip_count"
                    ] += 1
                continue
        if len(routes) > 1:
            counts["statement_source_review_candidate_count"] += 1
            counts["statement_aggregate_source_review_candidate_count"] += 1
            whole_review_entries_by_statement_identity.setdefault(
                statement_identity, []
            ).append((str(storage_key), raw_entry, routes))
            continue
        if not component_routes:
            if len(routes) == 1:
                # A source-indexed definition may be reviewed as one complete
                # statement rather than as a component partition.  Authenticate
                # that review through the same content/signature/source-pin lane
                # used by aggregate definitions; never fall back to its route,
                # storage, or declaration name as the semantic selector.
                counts["statement_source_review_candidate_count"] += 1
                whole_review_entries_by_statement_identity.setdefault(
                    statement_identity, []
                ).append((str(storage_key), raw_entry, routes))
            continue
        counts["statement_source_component_candidate_count"] += 1
        if len(routes) != 1 or len(component_routes) != 1:
            errors.append(
                "statement source-component candidate has multiple competing source routes"
            )
            continue
        candidate_entries_by_statement_identity.setdefault(
            statement_identity, []
        ).append((str(storage_key), raw_entry, component_routes[0]))

    # Statement reviews are issued against the dashboard's canonical ordinary
    # source inventory, not the source-map storage objects.  In particular,
    # the canonical projection normalizes optional presentation metadata and
    # derives the exact statement/anchor fields used by semantic reuse.  Keep
    # source-definition components in their separate route-only inventory and
    # combine the two projections only for validating an aggregate review.
    ordinary_route_inventory = dashboard.paper_statement_inventory(paper_dir)
    combined_route_inventory = dict(component_inventory)
    combined_route_inventory.update(
        {
            str(key): dict(value)
            for key, value in ordinary_route_inventory.items()
            if isinstance(value, Mapping)
        }
    )
    for statement_identity, candidates in sorted(
        whole_review_entries_by_statement_identity.items()
    ):
        member_records = items_by_statement_identity.get(statement_identity, [])
        members = [member for member, _raw_sha in member_records]
        if len(candidates) != 1 or len(members) != 1:
            errors.append(
                "aggregate statement source-route statement/signature identity is "
                f"ambiguous ({len(candidates)} statement candidates, {len(members)} semantic rows)"
            )
            continue
        storage_key, entry, _review_routes = candidates[0]
        reuse_receipt = entry.get("semantic_reuse_v1")
        reviewed_raw_statement_sha = (
            str(reuse_receipt.get("raw_lean_statement_sha256") or "")
            .strip()
            .lower()
            if isinstance(reuse_receipt, Mapping)
            else ""
        )
        if reviewed_raw_statement_sha != member_records[0][1]:
            errors.append(
                "aggregate statement source-route candidate has a stale "
                "dashboard-visible raw statement receipt"
            )
            continue
        raw_routes = entry.get("source_routes")
        routes = (
            [route for route in raw_routes if isinstance(route, Mapping)]
            if isinstance(raw_routes, list)
            else []
        )
        if len(routes) != len(raw_routes or []) or not routes:
            errors.append(
                "whole-definition statement source-route candidate has malformed or incomplete routes"
            )
            continue
        item = members[0]
        receipt, receipt_error = _validated_statement_source_route_receipt(
            paper_dir=paper_dir,
            item=item,
            storage_key=storage_key,
            entry=entry,
            routes=routes,
            route_inventory=combined_route_inventory,
            source_coverage_mode=mode,
            source_proof_fidelity=source_proof_fidelity,
            validator_identities=validator_identities,
            validator_errors=validator_errors,
            elaborated_signature_manifests_by_qualified=(
                elaborated_signature_manifests_by_qualified
            ),
            elaborated_signature_sha256_by_qualified=(
                elaborated_signature_sha256_by_qualified
            ),
        )
        if receipt is None:
            errors.append(
                "aggregate statement source-route candidate failed current v10 validation: "
                + receipt_error
            )
            continue
        source_identities, bound_route_receipts, parent_error = (
            _statement_review_source_parent_receipts(
                routes=routes,
                receipt=receipt,
                route_inventory=combined_route_inventory,
                raw_source_items=raw_map_items,
                source_coverage_mode=mode,
                source_proof_fidelity=source_proof_fidelity,
            )
        )
        if parent_error:
            errors.append(
                "aggregate statement source-route candidate has no exact current "
                "source parents: "
                + parent_error
            )
            continue
        anchor_errors = explicit_direct_source_route_anchor_errors(
            paper_dir,
            dict(paper_statement_map),
            source_keys={
                str(identity.get("source_key") or "").strip()
                for identity in source_identities
            },
        )
        if anchor_errors:
            errors.append(
                "aggregate statement source-route candidate has stale source bytes: "
                + "; ".join(anchor_errors)
            )
            continue
        source_review_association, association_error = (
            _authenticated_statement_source_review_association(
                receipt=receipt,
                source_identities=source_identities,
                bound_route_receipts=bound_route_receipts,
            )
        )
        if source_review_association is None:
            errors.append(
                "aggregate statement source-route candidate cannot materialize "
                "a whole-definition association: "
                + association_error
            )
            continue
        item["source_statement_association"] = source_review_association
        counts["statement_source_review_association_count"] += 1

        signature = receipt["reviewed_elaborated_signature_identity"]
        semantic_receipt = {
            "schema": STATEMENT_AGGREGATE_SOURCE_REVIEW_RECEIPT_SCHEMA,
            "elaborated_signature_sha256": signature[
                "elaborated_signature_sha256"
            ],
            "manifest_structure_sha256": receipt["manifest_structure_sha256"],
            "semantic_dependency_sha256": receipt[
                "semantic_dependency_sha256"
            ],
            "review_validator_identity_sha256": receipt[
                "review_validator_identity_sha256"
            ],
            "review_protocol_sha256": receipt["review_protocol_sha256"],
            "paper_statement_sha256": receipt["paper_statement_sha256"],
            "tex_statement_sha256": receipt["tex_statement_sha256"],
            "source_route_receipts": receipt["source_route_receipts"],
        }
        if len(routes) > 1:
            aggregate_receipt: dict[str, Any] = {
                "schema": STATEMENT_AGGREGATE_SOURCE_REVIEW_RECEIPT_SCHEMA,
                "receipt_origin": STATEMENT_AGGREGATE_SOURCE_REVIEW_RECEIPT_ORIGIN,
                **receipt,
                "semantic_receipt_sha256": stable_digest(semantic_receipt),
            }
            aggregate_receipt["receipt_sha256"] = stable_digest(aggregate_receipt)
            item[STATEMENT_AGGREGATE_SOURCE_REVIEW_RECEIPT_FIELD] = aggregate_receipt
            counts["statement_aggregate_source_review_receipt_count"] += 1
        item["required_check"] = (
            str(item.get("required_check") or "")
            + " This row is a complete statement review rather than a "
            "single-component route. Its complete v10 obligation ledger, "
            "current elaborated signature/dependency graph, every source route "
            "and source pin, and entry-local reuse receipt were validated "
            "together. Its whole-definition association is distinct from "
            "one-component reuse and does not give any route credit by name."
        )

    for statement_identity, candidates in sorted(
        candidate_entries_by_statement_identity.items()
    ):
        member_records = items_by_statement_identity.get(statement_identity, [])
        members = [member for member, _raw_sha in member_records]
        if len(candidates) != 1 or len(members) != 1:
            errors.append(
                "statement source-component statement/signature identity is "
                f"ambiguous ({len(candidates)} statement candidates, {len(members)} semantic rows)"
            )
            continue
        storage_key, entry, route = candidates[0]
        reuse_receipt = entry.get("semantic_reuse_v1")
        reviewed_raw_statement_sha = (
            str(reuse_receipt.get("raw_lean_statement_sha256") or "")
            .strip()
            .lower()
            if isinstance(reuse_receipt, Mapping)
            else ""
        )
        if reviewed_raw_statement_sha != member_records[0][1]:
            errors.append(
                "statement source-component candidate has a stale "
                "dashboard-visible raw statement receipt"
            )
            continue
        item = members[0]
        competing_fields = [
            field
            for field in _SOURCE_RECORD_ITEM_IDENTITY_FIELDS
            if field != STATEMENT_SOURCE_COMPONENT_ASSOCIATION_FIELD
            and isinstance(item.get(field), Mapping)
        ]
        if competing_fields:
            errors.append(
                "statement source-component route collides with another generated "
                "source association: " + ", ".join(sorted(competing_fields))
            )
            continue

        content_identity = _statement_source_component_route_content_identity(route)
        component_candidates = (
            components_by_content.get(content_identity, [])
            if content_identity is not None
            else []
        )
        if len(component_candidates) != 1:
            errors.append(
                "statement source-component route has no unique current component-content identity"
            )
            continue
        component_key, component = component_candidates[0]
        # The route key is checked only after content selected the unique
        # component.  It authenticates navigation; it never chooses semantics.
        if str(route.get("source_item") or "").strip() != component_key:
            errors.append(
                "statement source-component route navigation key is stale after content resolution"
            )
            continue

        reviewed_identity = item.get("reviewed_declaration_identity")
        if not isinstance(reviewed_identity, Mapping):
            errors.append(
                "statement source-component row has no reviewed declaration identity"
            )
            continue
        qualified = semantic_contract_fully_qualified_identity(
            reviewed_identity.get("qualified_declaration")
        )
        manifest = elaborated_signature_manifests_by_qualified.get(qualified)
        signature_digest = str(
            elaborated_signature_sha256_by_qualified.get(qualified) or ""
        ).strip().lower()
        if not isinstance(manifest, Mapping) or not SHA256_RE.fullmatch(
            signature_digest
        ):
            errors.append(
                "statement source-component row has no current elaborated signature manifest"
            )
            continue
        reviewed_signature = reviewed_elaborated_signature_identity(
            reviewed_identity,
            dict(elaborated_signature_sha256_by_qualified),
        )
        if reviewed_signature is None:
            errors.append(
                "statement source-component row has no exact elaborated signature identity"
            )
            continue
        if signature_manifest_digest(dict(manifest)) != signature_digest or str(
            entry.get("lean_signature_sha256") or ""
        ).strip().lower() != signature_digest:
            errors.append(
                "statement source-component row has a stale elaborated signature receipt"
            )
            continue

        validator_identity = validator_identities.get(storage_key, "")
        if not SHA256_RE.fullmatch(validator_identity):
            errors.append(
                "statement source-component candidate has no current reviewer identity: "
                + str(validator_errors.get(storage_key) or "unknown validator error")
            )
            continue
        if (
            str(entry.get("judgment") or "").strip().lower() != "matches"
            or entry.get("matches") is not True
            or any(
                isinstance(entry.get(field), list) and entry.get(field)
                for field in (
                    "unmatched_source_conclusions",
                    "unmatched_source_inputs",
                    "unjustified_lean_inputs",
                    "unmatched_lean_conclusions",
                )
            )
        ):
            errors.append(
                "statement source-component candidate is not an accepted exact v10 match"
            )
            continue
        ledger_error = dashboard.semantic_obligation_ledger_error(
            dict(entry),
            dict(manifest),
            require_source_definition_semantics_review=True,
        )
        route_error = dashboard.source_route_pin_error(
            dict(entry),
            inventory=combined_route_inventory,
            require_statement_target=True,
            require_verbatim_source_inputs=(
                dashboard.statement_review_requires_verbatim_source_inputs(entry)
            ),
        )
        if ledger_error or route_error:
            errors.append(
                "statement source-component candidate failed current v10 validation: "
                + "; ".join(error for error in (ledger_error, route_error) if error)
            )
            continue

        embedded_pin, embedded_error = reuse._reuse_pin_from_embedded(
            entry,
            [route],
            current_validator_identity_sha256=validator_identity,
        )
        if embedded_pin is None:
            errors.append(
                "statement source-component candidate has no current semantic reuse receipt: "
                + embedded_error
            )
            continue
        current_structure = reuse.manifest_structure_sha256(manifest)
        current_dependency, dependency_error = reuse.semantic_dependency_sha256(
            manifest
        )
        if (
            not current_structure
            or current_structure != embedded_pin.get("manifest_structure_sha256")
            or dependency_error
            or current_dependency
            != embedded_pin.get("semantic_dependency_sha256")
        ):
            errors.append(
                "statement source-component candidate has a stale elaborated structure/dependency receipt"
            )
            continue
        current_component_pin, component_pin_error = reuse.source_reuse_pin(
            component,
            mode,
            source_proof_fidelity=source_proof_fidelity,
        )
        embedded_routes = embedded_pin.get("source_routes")
        embedded_route_pin = (
            embedded_routes[0]
            if isinstance(embedded_routes, list)
            and len(embedded_routes) == 1
            and isinstance(embedded_routes[0], Mapping)
            else None
        )
        if current_component_pin is None or embedded_route_pin is None:
            errors.append(
                "statement source-component candidate lacks a current source pin: "
                + component_pin_error
            )
            continue
        component_target_disposition = current_component_pin.get(
            "source_target_disposition"
        )
        if not isinstance(component_target_disposition, Mapping) or str(
            component_target_disposition.get("kind") or ""
        ).strip() != "ordinary_or_convention":
            errors.append(
                "statement source-component candidate is outside the current "
                "ordinary/convention component target contract"
            )
            continue
        expected_route_semantic = reuse.route_semantic_sha256(route)
        compared_embedded_pin = dict(embedded_route_pin)
        supplied_route_semantic = str(
            compared_embedded_pin.pop("route_semantic_sha256", "") or ""
        ).strip().lower()
        if (
            supplied_route_semantic != expected_route_semantic
            or compared_embedded_pin != current_component_pin
        ):
            errors.append(
                "statement source-component candidate has stale component source-route pins"
            )
            continue

        parent_key = str(component.get("source_component_of") or "").strip()
        parent_item = raw_map_items.get(parent_key)
        if not isinstance(parent_item, Mapping):
            errors.append(
                "statement source-component candidate has no current parent source item"
            )
            continue
        anchor_errors = explicit_direct_source_route_anchor_errors(
            paper_dir,
            dict(paper_statement_map),
            source_keys={parent_key},
        )
        if anchor_errors:
            errors.append(
                "statement source-component candidate has stale source bytes: "
                + "; ".join(anchor_errors)
            )
            continue

        reuse_receipt = entry.get("semantic_reuse_v1")
        review_protocol_digest = (
            str(
                reuse_receipt.get("formalization_review_protocol_sha256") or ""
            )
            .strip()
            .lower()
            if isinstance(reuse_receipt, Mapping)
            else ""
        )
        component_identity: dict[str, Any] = {
            "schema": STATEMENT_SOURCE_COMPONENT_IDENTITY_SCHEMA,
            "source_component_semantic_sha256": current_component_pin[
                "source_item_semantic_sha256"
            ],
            "source_statement_sha256": str(component.get("statement_sha256") or "")
            .strip()
            .lower(),
            "source_anchor_quote_identity_sha256": current_component_pin[
                "source_anchor_quote_identity_sha256"
            ],
            "source_target_sha256": current_component_pin["source_target_sha256"],
            "source_target_disposition": current_component_pin[
                "source_target_disposition"
            ],
            "source_definition_partition_sha256": str(
                component.get("source_definition_partition_sha256") or ""
            )
            .strip()
            .lower(),
            "source_definition_component_sha256": str(
                component.get("source_definition_component_sha256") or ""
            )
            .strip()
            .lower(),
            "source_component_anchor_sha256": str(
                component.get("source_component_anchor_sha256") or ""
            )
            .strip()
            .lower(),
            "statement_manifest_structure_sha256": current_structure,
            "statement_semantic_dependency_sha256": current_dependency,
            "statement_review_validator_identity_sha256": validator_identity,
            "statement_review_protocol_sha256": review_protocol_digest,
            "statement_source_route_semantic_sha256": supplied_route_semantic,
            "statement_obligation_ledger_validated": True,
            "statement_source_definition_semantics_validated": True,
        }
        if "source_model_convention_pins" in current_component_pin:
            component_identity["source_model_convention_pins"] = (
                current_component_pin["source_model_convention_pins"]
            )
        component_semantic_association = (
            statement_source_component_semantic_association_digest(
                component_identity, reviewed_signature
            )
        )
        parent_identity = semantic_contract_source_identity(
            parent_key, dict(parent_item)
        )
        association: dict[str, Any] = {
            "schema": STATEMENT_SOURCE_COMPONENT_ASSOCIATION_SCHEMA,
            "association_origin": STATEMENT_SOURCE_COMPONENT_ASSOCIATION_ORIGIN,
            "role": STATEMENT_SOURCE_COMPONENT_ASSOCIATION_ROLE,
            "reviewed_declaration_identity": dict(reviewed_identity),
            "reviewed_elaborated_signature_identity": reviewed_signature,
            "source_item_identities": [parent_identity],
            STATEMENT_SOURCE_COMPONENT_IDENTITY_FIELD: component_identity,
            STATEMENT_SOURCE_COMPONENT_SEMANTIC_ASSOCIATION_FIELD: (
                component_semantic_association
            ),
            # Generic response/currentness transport must carry the component
            # discriminator.  The ordinary parent source+endpoint identity is
            # retained separately for current source-map/context validation.
            "semantic_association_sha256": component_semantic_association,
            "parent_semantic_association_sha256": semantic_source_association_digest(
                [parent_identity], reviewed_signature
            ),
            "review_scope": "individual_source_definition_component_only",
            "structural_pairing": "authenticated_statement_component_equivalence",
        }
        association["association_sha256"] = stable_digest(association)
        item[STATEMENT_SOURCE_COMPONENT_ASSOCIATION_FIELD] = association
        item["required_check"] = (
            str(item.get("required_check") or "")
            + " This row is content-bound to one independently accepted v10 "
            "source-definition component. The declaration-content, elaborated "
            "signature/dependency graph, complete obligation ledger, source "
            "partition/component/anchor, and any convention records must all "
            "remain current; no row, function, or source-map key selects the "
            "semantic match."
        )
        counts["statement_source_component_association_count"] += 1

    return items, sorted(set(errors)), counts


def source_claim_atom_semantic_digest(context: Mapping[str, Any]) -> str:
    """Return the route-independent semantic identity of one source atom.

    The atom identifier and Lean route remain useful navigation and structural
    route checks, but neither says what the paper claimed.  Reuse instead
    binds the curator's source-facing semantic clause and the hash of the
    exact current source bytes extracted from its locator.
    """

    claim = normalize_ws(str(context.get("semantic_claim") or ""))
    quote_digest = str(context.get("source_quote_sha256") or "").strip().lower()
    if not claim or not SHA256_RE.fullmatch(quote_digest):
        return ""
    return stable_digest(
        {
            "schema": SOURCE_CLAIM_ATOM_ASSOCIATION_SCHEMA,
            "semantic_claim": claim,
            "source_quote_sha256": quote_digest,
        }
    )


def source_claim_atom_semantic_association_digest(
    contexts: list[Mapping[str, Any]],
    reviewed_signature_identity: Mapping[str, Any] | None,
) -> str:
    """Bind atom semantics and a Lean-owned signature without route spelling.

    This is deliberately distinct from the legacy parent-map association pin.
    The latter remains available to consumers that validate source-map rows by
    key.  This atom-specific pin is the reusable semantic receipt: renaming a
    Lean declaration with an unchanged elaborated proposition leaves it
    unchanged, while changing either the advertised atom text or its current
    quoted source bytes invalidates it.
    """

    if not isinstance(reviewed_signature_identity, Mapping):
        return ""
    signature_digest = str(
        reviewed_signature_identity.get("elaborated_signature_sha256") or ""
    ).strip().lower()
    atom_digests = [
        str(context.get("source_claim_atom_semantic_sha256") or "")
        .strip()
        .lower()
        for context in contexts
    ]
    if (
        not SHA256_RE.fullmatch(signature_digest)
        or not atom_digests
        or any(not SHA256_RE.fullmatch(digest) for digest in atom_digests)
        or len(set(atom_digests)) != len(atom_digests)
    ):
        return ""
    return stable_digest(
        {
            "schema": SOURCE_CLAIM_ATOM_ASSOCIATION_SCHEMA,
            "source_claim_atom_semantic_sha256": sorted(atom_digests),
            "elaborated_signature_sha256": signature_digest,
        }
    )


def source_claim_atom_current_quote_context(
    *,
    paper_dir: Path,
    statement_map: Mapping[str, Any],
    source_key: str,
    raw_atom: Mapping[str, Any],
    source_text_cache: dict[Path, str],
) -> tuple[dict[str, Any] | None, list[str]]:
    """Extract one atom's exact current source quote from its declared span.

    The source-map atom supplies a locator and semantic summary.  This helper
    reads the current canonical artifact itself, so neither a map key nor a
    Lean route can stand in for the source bytes that the reviewer receives.
    """

    atom_id = str(raw_atom.get("id") or "").strip()
    locator = str(raw_atom.get("source_locator") or "").strip()
    semantic_claim = str(raw_atom.get("semantic_claim") or "").strip()
    errors: list[str] = []
    for error in source_file_line_anchor_errors(paper_dir, locator):
        errors.append(f"source atom `{source_key}:{atom_id}` source_locator {error}")
    for error in canonical_artifact_source_span_errors(
        paper_dir,
        locator,
        source_artifact_path=statement_map.get("source_artifact_path"),
    ):
        errors.append(f"source atom `{source_key}:{atom_id}` source_locator {error}")
    matches = list(SOURCE_FILE_LINE_RE.finditer(locator))
    if len(matches) != 1:
        errors.append(
            f"source atom `{source_key}:{atom_id}` source_locator must resolve to exactly one file:line span"
        )
        return None, sorted(set(errors))
    if errors:
        return None, sorted(set(errors))

    match = matches[0]
    source_path, path_error = resolve_paper_source_path(
        paper_dir, match.group("path")
    )
    if source_path is None:
        return None, [
            f"source atom `{source_key}:{atom_id}` source_locator {path_error}"
        ]
    try:
        source_text = source_text_cache.get(source_path)
        if source_text is None:
            source_text = normalized_source_text(source_path.read_bytes())
            source_text_cache[source_path] = source_text
    except (OSError, UnicodeDecodeError) as error:
        return None, [
            f"source atom `{source_key}:{atom_id}` source bytes cannot be read: {error}"
        ]
    line_start = int(match.group("start"))
    line_end = int(match.group("end") or line_start)
    quote = normalized_source_line_excerpt(
        normalized_source_lines(source_text), line_start, line_end
    )
    if quote is None:
        return None, [
            f"source atom `{source_key}:{atom_id}` source_locator cannot produce an exact current source quote"
        ]
    context: dict[str, Any] = {
        "schema": SOURCE_CLAIM_ATOM_ASSOCIATION_SCHEMA,
        "id": atom_id,
        "source_locator": locator,
        "semantic_claim": semantic_claim,
        "source_quote": quote,
        "source_quote_sha256": hashlib.sha256(quote.encode("utf-8")).hexdigest(),
    }
    semantic_digest = source_claim_atom_semantic_digest(context)
    if not semantic_digest:
        return None, [
            f"source atom `{source_key}:{atom_id}` has no usable semantic claim/quote identity"
        ]
    context["source_claim_atom_semantic_sha256"] = semantic_digest
    return context, []


def source_claim_atom_route_contexts(
    *,
    paper_dir: Path,
    statement_map: Mapping[str, Any] | None,
    row_qualified_names: Mapping[str, str],
) -> tuple[dict[str, list[dict[str, Any]]], list[str]]:
    """Collect atom contexts by exact current reviewed declaration.

    Source clauses are selected first from their opt-in theorem-like source
    presentations.  Only then does this routine resolve the explicitly
    declared route against a configured fully-qualified declaration.  It never
    infers an atom from a Lean identifier, row label, or declaration suffix.
    """

    if not source_claim_atoms_contract_present(statement_map):
        return {}, []
    if not isinstance(statement_map, Mapping):
        return {}, ["source-claim atom contract has no readable source map"]
    errors = source_claim_atom_contract_errors(statement_map)
    if errors:
        return {}, errors
    raw_items = statement_map.get("items")
    if not isinstance(raw_items, Mapping):
        return {}, ["source-claim atom contract has no source-map items object"]

    presentation_aliases, presentation_alias_errors = source_presentation_aliases(
        raw_items
    )
    errors.extend(presentation_alias_errors)
    rows_by_qualified: dict[str, list[str]] = {}
    for row, raw_qualified in row_qualified_names.items():
        qualified = semantic_contract_fully_qualified_identity(raw_qualified)
        if qualified:
            rows_by_qualified.setdefault(qualified, []).append(str(row))

    status = str(
        load_json_object(paper_dir / "status.json").get("status") or "formalized"
    ).strip()
    map_path = paper_dir / "audit" / "paper_statement_map.json"
    pin_findings = source_artifact_pin_findings(
        paper_dir,
        status or "formalized",
        map_path,
        dict(statement_map),
        require_source_bytes=True,
    )
    if pin_findings:
        return {}, errors + [
            "source-claim atom canonical source pin is not byte-verified: "
            + str(finding.message)
            for finding in pin_findings
        ]

    source_text_cache: dict[Path, str] = {}
    contexts_by_qualified: dict[str, list[dict[str, Any]]] = {}
    for raw_source_key, raw_source_item in raw_items.items():
        if not isinstance(raw_source_item, Mapping):
            continue
        source_key = str(raw_source_key).strip()
        if not source_key or source_key in presentation_aliases:
            continue
        if not source_claim_atom_authoritative_for_item(
            statement_map, raw_source_item
        ):
            continue
        raw_atoms = raw_source_item.get(SOURCE_CLAIM_ATOMS_KEY)
        atom_errors = source_claim_atoms_validation_errors(raw_atoms)
        if atom_errors:
            errors.extend(
                f"source atom contract `{source_key}`: {error}"
                for error in atom_errors
            )
            continue
        assert isinstance(raw_atoms, list)
        parent_identity = semantic_contract_source_identity(
            source_key, dict(raw_source_item)
        )
        for index, raw_atom in enumerate(raw_atoms):
            assert isinstance(raw_atom, Mapping)
            atom_id = str(raw_atom.get("id") or index).strip()
            route = semantic_contract_fully_qualified_identity(
                raw_atom.get("reviewed_lean_route")
            )
            if not route:
                errors.append(
                    f"source atom `{source_key}:{atom_id}` has no exact fully-qualified reviewed Lean route"
                )
                continue
            route_rows = rows_by_qualified.get(route, [])
            if len(route_rows) != 1:
                detail = (
                    "is not an exact configured review declaration"
                    if not route_rows
                    else "resolves to multiple configured review declarations"
                )
                errors.append(
                    f"source atom `{source_key}:{atom_id}` route `{route}` {detail}"
                )
                continue
            context, quote_errors = source_claim_atom_current_quote_context(
                paper_dir=paper_dir,
                statement_map=statement_map,
                source_key=source_key,
                raw_atom=raw_atom,
                source_text_cache=source_text_cache,
            )
            if quote_errors:
                errors.extend(quote_errors)
                continue
            assert context is not None
            contexts_by_qualified.setdefault(route, []).append(
                {
                    "source_identity": parent_identity,
                    "atom_context": context,
                    "reviewed_lean_route": route,
                }
            )

    return (
        {
            route: sorted(
                contexts,
                key=lambda context: (
                    str(context["source_identity"].get("source_key") or ""),
                    str(context["atom_context"].get("id") or ""),
                ),
            )
            for route, contexts in sorted(contexts_by_qualified.items())
        },
        sorted(set(errors)),
    )


def attach_source_claim_atom_associations(
    items: list[dict[str, Any]],
    *,
    paper_dir: Path,
    paper_statement_map: Mapping[str, Any] | None,
    declarations: Mapping[str, str],
    row_qualified_names: Mapping[str, str],
    elaborated_signature_sha256_by_qualified: Mapping[str, str],
) -> tuple[list[dict[str, Any]], list[str], dict[str, int]]:
    """Attach source-first atom contexts to their exact semantic-model rows.

    The parent source-map identity remains in the generated association for
    existing validator compatibility.  The separate atom semantic association
    binds each literal atom claim and freshly extracted quote to the current
    elaborated Lean signature, which is the narrow receipt used by item-level
    source-record reuse.
    """

    routes, errors = source_claim_atom_route_contexts(
        paper_dir=paper_dir,
        statement_map=paper_statement_map,
        row_qualified_names=row_qualified_names,
    )
    counts = {
        "source_claim_atom_route_declaration_count": len(routes),
        "source_claim_atom_context_count": sum(len(value) for value in routes.values()),
        "source_claim_atom_association_count": 0,
    }
    if not routes:
        return items, sorted(set(errors)), counts

    items_by_qualified: dict[str, list[dict[str, Any]]] = {}
    for item in items:
        if not isinstance(item, dict):
            continue
        qualified = semantic_contract_fully_qualified_identity(
            item.get("qualified_declaration")
        )
        if qualified:
            items_by_qualified.setdefault(qualified, []).append(item)

    for qualified, route_contexts in routes.items():
        members = items_by_qualified.get(qualified, [])
        if len(members) != 1:
            errors.append(
                "source-claim atom route for fully-qualified declaration "
                f"`{qualified}` has {len(members)} generated semantic-model rows; association is ambiguous"
            )
            continue
        item = members[0]
        row = str(item.get("row") or "").strip()
        reviewed_identity = reviewed_declaration_identity(
            qualified,
            declarations.get(row, str(item.get("lean_source_declaration") or "")),
        )
        if reviewed_identity is None:
            errors.append(
                "source-claim atom route for fully-qualified declaration "
                f"`{qualified}` has no current declaration-content identity"
            )
            continue
        reviewed_signature = reviewed_elaborated_signature_identity(
            reviewed_identity, dict(elaborated_signature_sha256_by_qualified)
        )
        if reviewed_signature is None:
            errors.append(
                "source-claim atom route for fully-qualified declaration "
                f"`{qualified}` has no current elaborated-signature identity"
            )
            continue

        source_identities_by_key: dict[str, dict[str, Any]] = {}
        atom_contexts: list[dict[str, Any]] = []
        atom_routes: list[dict[str, Any]] = []
        for route_context in route_contexts:
            source_identity = route_context["source_identity"]
            assert isinstance(source_identity, dict)
            source_key = str(source_identity.get("source_key") or "").strip()
            if not source_key:
                errors.append(
                    f"source-claim atom route `{qualified}` has a parent source identity without a source key"
                )
                continue
            prior_identity = source_identities_by_key.get(source_key)
            if prior_identity is not None and prior_identity != source_identity:
                errors.append(
                    f"source-claim atom route `{qualified}` has conflicting parent identities for `{source_key}`"
                )
                continue
            source_identities_by_key[source_key] = dict(source_identity)
            atom_context = dict(route_context["atom_context"])
            atom_contexts.append(atom_context)
            atom_routes.append(
                {
                    "source_key": source_key,
                    "atom_id": atom_context.get("id"),
                    "reviewed_lean_route": route_context["reviewed_lean_route"],
                    "source_claim_atom_semantic_sha256": atom_context.get(
                        "source_claim_atom_semantic_sha256"
                    ),
                }
            )
        atom_contexts.sort(
            key=lambda context: (
                str(context.get("source_claim_atom_semantic_sha256") or ""),
                str(context.get("id") or ""),
            )
        )
        atom_routes.sort(
            key=lambda route: (
                str(route.get("source_key") or ""),
                str(route.get("atom_id") or ""),
            )
        )
        atom_semantic_pin = source_claim_atom_semantic_association_digest(
            atom_contexts, reviewed_signature
        )
        if not atom_semantic_pin:
            errors.append(
                "source-claim atom route for fully-qualified declaration "
                f"`{qualified}` has duplicate or malformed atom semantic identities"
            )
            continue
        source_identities = [
            source_identities_by_key[source_key]
            for source_key in sorted(source_identities_by_key)
        ]
        if not source_identities:
            errors.append(
                "source-claim atom route for fully-qualified declaration "
                f"`{qualified}` has no parent source-map identity"
            )
            continue
        association: dict[str, Any] = {
            "schema": SOURCE_CLAIM_ATOM_ASSOCIATION_SCHEMA,
            "association_origin": SOURCE_CLAIM_ATOM_ROUTE_ORIGIN,
            "role": SOURCE_CLAIM_ATOM_ROUTE_ROLE,
            "reviewed_declaration_identity": reviewed_identity,
            "reviewed_elaborated_signature_identity": reviewed_signature,
            "source_item_identities": source_identities,
            "source_claim_atom_routes": atom_routes,
            SOURCE_CLAIM_ATOM_SEMANTIC_ASSOCIATION_FIELD: atom_semantic_pin,
            "review_scope": "individual_row_only",
            "structural_pairing": "not_asserted_by_source_claim_atom_route",
        }
        association["association_sha256"] = stable_digest(association)
        item[SOURCE_CLAIM_ATOM_ASSOCIATION_FIELD] = association
        item[SOURCE_CLAIM_ATOM_CONTEXTS_FIELD] = atom_contexts
        item["required_check"] = (
            str(item.get("required_check") or "")
            + " This row has source-first claim-atom context. Audit every listed "
            "semantic_claim against its extracted current source_quote and the "
            "expanded Lean surface; declaration, row, and route spellings are "
            "navigation only and do not establish the atom's mathematics."
        )
        counts["source_claim_atom_association_count"] += 1

    return items, sorted(set(errors)), counts


def collapse_semantic_model_contract_pairs(
    items: list[dict[str, Any]],
    *,
    paper_dir: Path,
    declarations: dict[str, str],
    row_qualified_names: dict[str, str],
    proposition_aliases: dict[str, PropositionAliasInfo],
    type_aliases: dict[str, TypeAliasInfo] | None,
    paper_statement_map: dict[str, Any] | None = None,
    elaborated_signature_sha256_by_qualified: dict[str, str] | None = None,
    elaborated_manifests_by_qualified: Mapping[
        str, Mapping[str, Any]
    ] | None = None,
) -> list[dict[str, Any]]:
    """Associate every explicit contract route; collapse only exact pairs.

    Every unambiguous, fully-qualified source-map direct/Spec route is first
    attached to its individual direct and Spec rows.  That linkage is
    provenance only: it does not depend on declaration suffixes and it does
    not provide duplicate-review credit.  A paired ``Spec`` row is then
    removed only when the direct signature is structurally alpha-equal to the
    transparent Spec body.  Thus a raw ``Spec : Prop`` wrapper, an omitted
    implicit argument the static parser cannot reconstruct, a common
    declaration suffix, or a map typo cannot erase an independent
    source-record obligation.
    """

    if not items or not declarations or not row_qualified_names:
        return items
    elaborated_signature_sha256_by_qualified = (
        elaborated_signature_sha256_by_qualified or {}
    )
    elaborated_manifests_by_qualified = elaborated_manifests_by_qualified or {}
    statement_map = paper_statement_map
    if statement_map is None:
        statement_map = load_json_object(
            paper_dir / "audit" / "paper_statement_map.json"
        )
    if not isinstance(statement_map, dict) or statement_map.get(
        "semantic_contract_schema"
    ) not in SEMANTIC_CONTRACT_SCHEMAS:
        return items
    raw_source_items = statement_map.get("items")
    if not isinstance(raw_source_items, dict):
        return items

    rows_by_qualified: dict[str, str] = {}
    duplicate_row_identities: set[str] = set()
    for row, raw_qualified in row_qualified_names.items():
        qualified = semantic_contract_fully_qualified_identity(raw_qualified)
        if not qualified or row not in declarations:
            continue
        if qualified in rows_by_qualified:
            duplicate_row_identities.add(qualified)
            continue
        rows_by_qualified[qualified] = row
    if duplicate_row_identities:
        for qualified in duplicate_row_identities:
            rows_by_qualified.pop(qualified, None)

    # Collect each exact pair once, retaining all source inventory identities
    # that intentionally route to that same pair.  A declaration participating
    # in distinct pairs is ambiguous and makes every such pair ineligible.
    pairs: dict[tuple[str, str], list[dict[str, Any]]] = {}
    pairs_by_member: dict[str, set[tuple[str, str]]] = {}
    for raw_source_key, raw_source_item in raw_source_items.items():
        if not isinstance(raw_source_item, dict):
            continue
        if raw_source_item.get("claim_bearing") is not True:
            continue
        raw_contract = raw_source_item.get("semantic_contract")
        if not isinstance(raw_contract, dict):
            continue
        if not all(
            str(raw_contract.get(field) or "").strip()
            for field in ("evidence_mode", "semantic_shape")
        ):
            continue
        evidence = semantic_contract_fully_qualified_identity(
            raw_contract.get("evidence_declaration")
        )
        spec = semantic_contract_fully_qualified_identity(
            raw_contract.get("spec_declaration")
        )
        if not evidence or not spec or evidence == spec:
            continue
        pair = (evidence, spec)
        source_key = str(raw_source_key).strip()
        if not source_key:
            continue
        pairs.setdefault(pair, []).append(
            semantic_contract_source_identity(source_key, raw_source_item)
        )
        pairs_by_member.setdefault(evidence, set()).add(pair)
        pairs_by_member.setdefault(spec, set()).add(pair)

    items_by_qualified: dict[str, dict[str, Any]] = {}
    for item in items:
        qualified = semantic_contract_fully_qualified_identity(
            item.get("qualified_declaration")
        )
        if qualified and qualified not in items_by_qualified:
            items_by_qualified[qualified] = item

    # A schema-2 conditional-composition contract needs one current
    # elaborated-signature association for its direct evidence row. Do not
    # collapse it into the historical direct/Spec group, whose group-level
    # receipt intentionally has no single signature pin.
    composition_pairs = {
        pair
        for pair, source_identities in pairs.items()
        if any(
            str(
                identity.get("semantic_contract", {}).get("semantic_shape")
                if isinstance(identity.get("semantic_contract"), dict)
                else ""
            ).strip()
            == CONDITIONAL_PROBABILITY_COMPOSITION_SEMANTIC_SHAPE
            for identity in source_identities
        )
    }

    associated_pairs: dict[tuple[str, str], dict[str, Any]] = {}
    eligible_pairs: dict[tuple[str, str], dict[str, Any]] = {}
    for pair, source_identities in pairs.items():
        evidence, spec = pair
        if (
            len(pairs_by_member.get(evidence, set())) != 1
            or len(pairs_by_member.get(spec, set())) != 1
        ):
            continue
        evidence_row = rows_by_qualified.get(evidence)
        spec_row = rows_by_qualified.get(spec)
        if evidence_row is None or spec_row is None:
            continue
        evidence_item = items_by_qualified.get(evidence)
        spec_item = items_by_qualified.get(spec)
        # A source-map route must point to two generated individual review
        # rows before it can supply provenance to either.  Otherwise retain
        # the standalone rows with no inferred association.
        if evidence_item is None or spec_item is None:
            continue
        evidence_source = declarations.get(evidence_row, "")
        spec_source = declarations.get(spec_row, "")
        evidence_identity = reviewed_declaration_identity(evidence, evidence_source)
        spec_identity = reviewed_declaration_identity(spec, spec_source)
        evidence_kind_match = DECL_RE.match(evidence_source)
        spec_kind_match = DECL_RE.match(spec_source)
        if (
            evidence_identity is None
            or spec_identity is None
            or evidence_kind_match is None
            or evidence_kind_match.group(1) not in {"theorem", "lemma"}
            or spec_kind_match is None
            or spec_kind_match.group(1) not in {"def", "abbrev"}
            or canonical_type(declaration_result_type(spec_source)) != "Prop"
        ):
            continue
        associated_pairs[pair] = {
            "source_identities": sorted(
                source_identities,
                key=lambda identity: str(identity.get("source_key") or ""),
            ),
            "evidence_row": evidence_row,
            "spec_row": spec_row,
            "evidence_identity": evidence_identity,
            "spec_identity": spec_identity,
        }
        structural_surfaces = semantic_contract_pair_structural_surfaces(
            evidence_qualified_name=evidence,
            evidence_source=evidence_source,
            spec_qualified_name=spec,
            spec_source=spec_source,
            proposition_aliases=proposition_aliases,
            type_aliases=type_aliases,
            evidence_manifest=elaborated_manifests_by_qualified.get(evidence),
            spec_manifest=elaborated_manifests_by_qualified.get(spec),
        )
        if structural_surfaces is None:
            continue
        evidence_surface, spec_surface = structural_surfaces
        if pair not in composition_pairs:
            eligible_pairs[pair] = {
                **associated_pairs[pair],
                "evidence_row": evidence_row,
                "spec_row": spec_row,
                "evidence_surface": evidence_surface,
                "spec_surface": spec_surface,
            }

    if not associated_pairs:
        return items

    associations_by_member: dict[str, dict[str, Any]] = {}
    for (evidence, spec), pair in associated_pairs.items():
        associations_by_member[evidence] = semantic_contract_source_association(
            source_identities=pair["source_identities"],
            role="direct_evidence",
            paired_declaration=spec,
            reviewed_identity=pair["evidence_identity"],
            reviewed_signature_identity=reviewed_elaborated_signature_identity(
                pair["evidence_identity"], elaborated_signature_sha256_by_qualified
            ),
        )
        associations_by_member[spec] = semantic_contract_source_association(
            source_identities=pair["source_identities"],
            role="transparent_spec",
            paired_declaration=evidence,
            reviewed_identity=pair["spec_identity"],
            reviewed_signature_identity=reviewed_elaborated_signature_identity(
                pair["spec_identity"], elaborated_signature_sha256_by_qualified
            ),
        )

    collapsed_specs: set[str] = set()
    grouped_evidence: dict[str, dict[str, Any]] = {}
    for (evidence, spec), group in eligible_pairs.items():
        evidence_item = items_by_qualified.get(evidence)
        spec_item = items_by_qualified.get(spec)
        # An incomplete generated item set must leave both rows individually
        # auditable rather than trusting a map entry alone.
        if evidence_item is None or spec_item is None:
            continue
        collapsed_specs.add(spec)
        grouped_evidence[evidence] = {
            "semantic_root_item": spec_item,
            "group": {
                # A collapsed direct/Spec group has two review routes.  Keep
                # it on schema 1 exact-route freshness until a single reviewed
                # elaborated signature can be proved unambiguous; a semantic
                # cache may not pick one merely because their source texts are
                # related.
                "schema": 1,
                "source_item_identities": group["source_identities"],
                "member_rows": [
                    {
                        "role": "direct_evidence",
                        "row": group["evidence_row"],
                        "qualified_declaration": evidence,
                        "reviewed_declaration_identity": group["evidence_identity"],
                    },
                    {
                        "role": "transparent_spec",
                        "row": group["spec_row"],
                        "qualified_declaration": spec,
                        "reviewed_declaration_identity": group["spec_identity"],
                    },
                ],
                "surface_root": {
                    "kind": "transparent_spec_body",
                    "qualified_declaration": spec,
                    "structural_alpha_normalized_surface": group["spec_surface"],
                },
                "direct_evidence_type": {
                    "qualified_declaration": evidence,
                    "structural_alpha_normalized_surface": group["evidence_surface"],
                },
                "structural_alpha_normalized_equal": True,
            },
        }

    collapsed: list[dict[str, Any]] = []
    for item in items:
        qualified = semantic_contract_fully_qualified_identity(
            item.get("qualified_declaration")
        )
        if qualified in collapsed_specs:
            continue
        grouping = grouped_evidence.get(qualified)
        if grouping is None:
            association = associations_by_member.get(qualified)
            if association is None:
                collapsed.append(item)
            else:
                collapsed.append(
                    {
                        **item,
                        "semantic_contract_source_association": association,
                        "required_check": str(item.get("required_check") or "")
                        + " This individual row has an explicit fully-qualified "
                        "source-map contract route. That association preserves the "
                        "listed source identities but does not merge this review with "
                        "its paired declaration or assert structural equality.",
                    }
                )
            continue
        semantic_root_item = grouping["semantic_root_item"]
        group = grouping["group"]
        assert isinstance(semantic_root_item, dict)
        assert isinstance(group, dict)
        collapsed.append(
            {
                **semantic_root_item,
                # The direct declaration remains the judgment identity. Its
                # exact structural equality to the body-root below is recorded
                # in semantic_contract_group, while the source-model surface
                # is the inspectable transparent proposition rather than
                # `Spec : Prop`.
                "row": item.get("row"),
                "qualified_declaration": item.get("qualified_declaration"),
                "judgment_key": item.get("judgment_key"),
                "lean_source_declaration": item.get("lean_source_declaration"),
                # The collapsed item is owned by the direct evidence theorem.
                # Its semantic surface deliberately comes from the paired
                # transparent `Spec` body, but every generated declaration and
                # manifest route must remain attached to the direct theorem.
                # Otherwise a result-level execution path on that theorem
                # cannot be joined to the model review without guessing across
                # the paired declarations.
                "reviewed_declaration_identity": item.get(
                    "reviewed_declaration_identity"
                ),
                "semantic_surface_origin": {
                    "kind": "transparent_spec_body",
                    "qualified_declaration": group["surface_root"][
                        "qualified_declaration"
                    ],
                },
                "semantic_contract_group": group,
                "semantic_contract_source_association": associations_by_member[
                    qualified
                ],
                "required_check": str(semantic_root_item.get("required_check") or "")
                + " This item is the single semantic-model review for the listed "
                "explicit source-map direct/transparent-Spec pair; the judgment must "
                "cover every preserved source identity and must not treat the raw "
                "`Spec : Prop` declaration as the review surface.",
            }
        )
    return collapsed


def attach_semantic_contract_executable_terminal_receipts(
    items: list[dict[str, Any]],
    *,
    root: Path,
    paper_dir: Path,
    import_module: str,
    paper_modules: tuple[str, ...],
    no_lean: bool,
    paper_statement_map: Mapping[str, Any] | None,
    elaborated_signature_sha256_by_qualified: Mapping[str, str],
    semantic_dependency_sha256_by_qualified: Mapping[str, str],
) -> tuple[list[dict[str, Any]], list[str], dict[str, int]]:
    """Attach exact generated receipts for executable recursive Spec leaves.

    Generic transparency remains a failure when it reaches a fully applied
    recursive data executor.  This optional raw-record receipt is the narrow
    bridge used by the closeout policy: it binds every Lean-reported terminal
    occurrence to one direct theorem/transparent-Spec source route and to the
    current elaborated signature plus transitive dependency graph.  The route
    is established entirely by current source-content identities and fully
    qualified endpoints; neither a recursive function name nor a row label is
    a selector.
    """

    counts = {
        "semantic_contract_executable_terminal_candidate_count": 0,
        "semantic_contract_executable_terminal_receipt_count": 0,
    }
    if no_lean or not items or not isinstance(paper_statement_map, Mapping):
        return items, [], counts
    raw_source_items = paper_statement_map.get("items")
    if not isinstance(raw_source_items, Mapping):
        return items, [], counts

    routes_by_evidence: dict[str, list[dict[str, Any]]] = {}
    specifications: set[str] = set()
    errors: list[str] = []
    for raw_source_key, raw_source_item in raw_source_items.items():
        if not isinstance(raw_source_item, dict):
            continue
        raw_contract = raw_source_item.get("semantic_contract")
        if not isinstance(raw_contract, Mapping):
            continue
        source_key = str(raw_source_key).strip()
        evidence = semantic_contract_fully_qualified_identity(
            raw_contract.get("evidence_declaration")
        )
        spec = semantic_contract_fully_qualified_identity(
            raw_contract.get("spec_declaration")
        )
        mode = str(raw_contract.get("evidence_mode") or "").strip()
        shape = str(raw_contract.get("semantic_shape") or "").strip()
        if not source_key or not evidence or not spec or not mode or not shape:
            continue
        identity = semantic_contract_source_identity(source_key, raw_source_item)
        if any(
            not str(identity.get(field) or "").strip()
            for field in (
                "source_key",
                "source_kind",
                "source_location",
                "source_map_item_sha256",
                "source_semantic_sha256",
            )
        ):
            errors.append(
                "executable-recursion terminal route has no complete source identity for "
                + source_key
            )
            continue
        routes_by_evidence.setdefault(evidence, []).append(
            {
                "source_key": source_key,
                "identity": identity,
                "spec_declaration": spec,
                "evidence_declaration": evidence,
            }
        )
        specifications.add(spec)

    if not routes_by_evidence:
        return items, sorted(set(errors)), counts
    try:
        transparency_checks = run_lean_semantic_contract_transparency_checks(
            root,
            import_module,
            sorted(specifications),
            paper_modules,
            timeout_seconds=SOURCE_RECORD_LEAN_ELABORATION_TIMEOUT_SECONDS,
            build_timeout_seconds=SOURCE_RECORD_LAKE_BUILD_TIMEOUT_SECONDS,
        )
    except Exception as exc:  # noqa: BLE001 - receipt generation fails closed.
        return items, sorted(
            set(
                errors
                + [
                    "executable-recursion terminal transparency extraction raised "
                    + type(exc).__name__
                ]
            )
        ), counts

    def route_association_contains(
        association: object, expected_identity: Mapping[str, Any]
    ) -> bool:
        if not isinstance(association, Mapping):
            return False
        identities, identity_errors = source_contract_source_identities(
            association.get("source_item_identities")
        )
        return not identity_errors and any(
            identity == dict(expected_identity) for identity in identities
        )

    attached: list[dict[str, Any]] = []
    for item in items:
        if not isinstance(item, dict):
            attached.append(item)
            continue
        evidence = semantic_contract_fully_qualified_identity(
            item.get("qualified_declaration")
        )
        routes = routes_by_evidence.get(evidence or "", [])
        if not routes:
            attached.append(item)
            continue
        group = item.get("semantic_contract_group")
        association = item.get("semantic_contract_source_association")
        receipts: list[dict[str, Any]] = []
        for route in routes:
            spec = str(route["spec_declaration"])
            identity = route["identity"]
            transparency = transparency_checks.get(spec)
            if not isinstance(transparency, Mapping):
                errors.append(
                    "executable-recursion terminal route has no current Lean transparency receipt for "
                    + spec
                )
                continue
            if transparency.get("passes") is True:
                continue
            if str(transparency.get("failure_tag") or "").strip() != (
                "recursive_executable_terminal"
            ):
                continue
            terminals = canonical_semantic_contract_executable_terminals(
                transparency.get("recursive_executable_terminals")
            )
            terminal_digest = semantic_contract_executable_terminal_receipt_sha256(
                terminals
            )
            failure_declaration = str(
                transparency.get("failure_declaration") or ""
            ).strip()
            if (
                transparency.get("passes") is not False
                or terminals is None
                or not terminals
                or not terminal_digest
                or failure_declaration
                not in {
                    str(terminal["declaration"])
                    for terminal in terminals
                }
            ):
                errors.append(
                    "executable-recursion terminal route has a malformed Lean occurrence receipt for "
                    + spec
                )
                continue
            counts["semantic_contract_executable_terminal_candidate_count"] += 1
            if not (
                route_association_contains(group, identity)
                and route_association_contains(association, identity)
            ):
                errors.append(
                    "executable-recursion terminal route has no exact generated direct/Spec source association for "
                    + str(route["source_key"])
                )
                continue
            signature = str(
                elaborated_signature_sha256_by_qualified.get(evidence) or ""
            ).strip().lower()
            dependency = str(
                semantic_dependency_sha256_by_qualified.get(evidence) or ""
            ).strip().lower()
            reviewed_identity = association.get("reviewed_declaration_identity") if isinstance(
                association, Mapping
            ) else None
            association_signature = association.get(
                "reviewed_elaborated_signature_identity"
            ) if isinstance(association, Mapping) else None
            if (
                not SHA256_RE.fullmatch(signature)
                or not SHA256_RE.fullmatch(dependency)
                or reviewed_declaration_identity_key(reviewed_identity) is None
                or reviewed_declaration_identity_key(reviewed_identity)[0] != evidence
                or not isinstance(association_signature, Mapping)
                or str(
                    association_signature.get("qualified_declaration") or ""
                ).strip()
                != evidence
                or str(
                    association_signature.get("elaborated_signature_sha256") or ""
                ).strip().lower()
                != signature
            ):
                errors.append(
                    "executable-recursion terminal route has no current direct signature/dependency pin for "
                    + evidence
                )
                continue
            receipt = {
                "schema": SEMANTIC_CONTRACT_EXECUTABLE_TERMINAL_RECEIPT_SCHEMA,
                "source_item_identity": identity,
                "spec_declaration": spec,
                "evidence_declaration": evidence,
                "reviewed_elaborated_signature_identity": {
                    "qualified_declaration": evidence,
                    "elaborated_signature_sha256": signature,
                    "semantic_dependency_sha256": dependency,
                },
                "transparency": {
                    "schema": SEMANTIC_CONTRACT_EXECUTABLE_TERMINAL_SCHEMA,
                    "passes": False,
                    "failure_tag": "recursive_executable_terminal",
                    "failure_declaration": failure_declaration,
                    "terminals": terminals,
                    "terminal_receipt_sha256": terminal_digest,
                },
            }
            receipts.append(receipt)
            counts["semantic_contract_executable_terminal_receipt_count"] += 1
        if receipts:
            receipts.sort(key=lambda receipt: stable_digest(receipt))
            attached.append(
                {
                    **item,
                    SEMANTIC_CONTRACT_EXECUTABLE_TERMINAL_RECEIPT_FIELD: receipts,
                }
            )
        else:
            attached.append(item)
    return attached, sorted(set(errors)), counts


def attach_conditional_probability_composition_requirements(
    items: list[dict[str, Any]],
    *,
    paper_statement_map: dict[str, Any] | None,
    elaborated_signature_sha256_by_qualified: dict[str, str],
) -> tuple[list[dict[str, Any]], list[str], dict[str, int]]:
    """Add source-pinned composition review obligations to direct evidence rows.

    A schema-2 composition contract records three independently byte-pinned
    source clauses: an outer selector law, a conditional outcome law, and the
    resulting objective or expectation.  The selected Lean theorem may expose
    only a scalar equality, so an expanded-type scan alone cannot safely decide
    that probability semantics are irrelevant.  This helper therefore joins a
    source clause to a generated direct-evidence row only through the existing
    source-content identity and current elaborated-signature association.  It
    never infers a route from a row label, short declaration name, or theorem
    function name.
    """

    counts = {
        "conditional_probability_composition_source_item_count": 0,
        "conditional_probability_composition_requirement_count": 0,
    }
    if not isinstance(paper_statement_map, dict):
        return items, [], counts
    raw_source_items = paper_statement_map.get("items")
    if not isinstance(raw_source_items, dict):
        return items, [], counts

    errors: list[str] = []
    marker = paper_statement_map.get("semantic_contract_schema")
    composition_sources: dict[str, dict[str, Any]] = {}
    route_by_source_semantic_digest: dict[str, tuple[str, str]] = {}
    for raw_source_key, raw_source_item in raw_source_items.items():
        if not isinstance(raw_source_item, dict):
            continue
        raw_contract = raw_source_item.get("semantic_contract")
        if not isinstance(raw_contract, dict) or str(
            raw_contract.get("semantic_shape") or ""
        ).strip() != CONDITIONAL_PROBABILITY_COMPOSITION_SEMANTIC_SHAPE:
            continue
        if marker != SEMANTIC_CONTRACT_SCHEMA_2:
            errors.append(
                "conditional-probability composition contract requires top-level "
                "semantic_contract_schema 2"
            )
            continue
        contract_errors = semantic_contract_validation_errors(
            raw_contract, schema=SEMANTIC_CONTRACT_SCHEMA_2
        )
        if contract_errors:
            errors.extend(
                "conditional-probability composition contract is malformed: " + error
                for error in contract_errors
            )
            continue
        if raw_source_item.get("claim_bearing") is not True:
            errors.append(
                "conditional-probability composition contract must be on a claim-bearing "
                "source item"
            )
            continue
        source_identity = semantic_contract_source_identity(
            str(raw_source_key), raw_source_item
        )
        source_semantic_digest = str(
            source_identity.get("source_semantic_sha256") or ""
        ).strip().lower()
        if not SHA256_RE.fullmatch(source_semantic_digest):
            errors.append(
                "conditional-probability composition contract has no source-content "
                "semantic identity"
            )
            continue
        evidence = semantic_contract_fully_qualified_identity(
            raw_contract.get("evidence_declaration")
        )
        spec = semantic_contract_fully_qualified_identity(
            raw_contract.get("spec_declaration")
        )
        if not evidence or not spec:
            # The contract-shape validator reports the source-map issue.  This
            # explicit branch keeps source-record generation fail-closed too.
            errors.append(
                "conditional-probability composition contract has no exact direct/Spec "
                "review route"
            )
            continue
        prior_route = route_by_source_semantic_digest.get(source_semantic_digest)
        if prior_route is not None and prior_route != (evidence, spec):
            errors.append(
                "one source-content composition identity is routed to multiple direct/Spec "
                "declaration pairs; it cannot select a semantic review by name"
            )
            continue
        route_by_source_semantic_digest[source_semantic_digest] = (evidence, spec)
        composition_sources.setdefault(
            source_semantic_digest,
            {
                "source_identity": source_identity,
                "composition": raw_contract.get(
                    CONDITIONAL_PROBABILITY_COMPOSITION_FIELD
                ),
            },
        )

    counts["conditional_probability_composition_source_item_count"] = len(
        composition_sources
    )
    if not composition_sources:
        return items, sorted(set(errors)), counts

    source_digests = set(composition_sources)
    candidates_by_source_digest: dict[str, list[dict[str, Any]]] = {
        digest: [] for digest in source_digests
    }
    for item in items:
        if not isinstance(item, dict):
            continue
        association = item.get("semantic_contract_source_association")
        if not isinstance(association, dict):
            continue
        if str(association.get("role") or "").strip() != "direct_evidence":
            continue
        associated_identities, association_identity_errors = (
            source_contract_source_identities(
                association.get("source_item_identities")
            )
        )
        associated_source_digests = {
            str(identity.get("source_semantic_sha256") or "").strip().lower()
            for identity in associated_identities
        }
        matched_source_digests = sorted(associated_source_digests & source_digests)
        if not matched_source_digests:
            continue

        qualified = semantic_contract_fully_qualified_identity(
            item.get("qualified_declaration")
        )
        reviewed_identity = association.get("reviewed_declaration_identity")
        reviewed_key = reviewed_declaration_identity_key(reviewed_identity)
        current_signature = reviewed_elaborated_signature_identity(
            reviewed_identity, elaborated_signature_sha256_by_qualified
        )
        association_signature = association.get(
            "reviewed_elaborated_signature_identity"
        )
        expected_association_pin = semantic_source_association_digest(
            associated_identities, current_signature
        )
        association_errors: list[str] = list(association_identity_errors)
        if association.get("schema") != 2:
            association_errors.append("has no schema-2 source/signature association")
        if reviewed_key is None or qualified != reviewed_key[0]:
            association_errors.append(
                "reviewed declaration identity does not match the generated direct row"
            )
        if current_signature is None or association_signature != current_signature:
            association_errors.append(
                "has no current elaborated signature for the generated direct row"
            )
        if (
            not expected_association_pin
            or str(association.get("semantic_association_sha256") or "").strip().lower()
            != expected_association_pin
        ):
            association_errors.append(
                "semantic association pin does not match the current source identities "
                "and elaborated signature"
            )
        if association_errors:
            errors.extend(
                "conditional-probability composition direct route is unusable: " + error
                for error in association_errors
            )
            continue
        assert isinstance(reviewed_identity, dict)
        assert current_signature is not None
        for source_semantic_digest in matched_source_digests:
            candidates_by_source_digest[source_semantic_digest].append(
                {
                    "item": item,
                    "reviewed_identity": dict(reviewed_identity),
                    "signature": dict(current_signature),
                }
            )

    requirements_by_item: dict[int, dict[str, Any]] = {}
    for source_semantic_digest in sorted(source_digests):
        candidates = candidates_by_source_digest[source_semantic_digest]
        if len(candidates) != 1:
            errors.append(
                "conditional-probability composition source identity has "
                f"{len(candidates)} current direct-evidence rows; exactly one "
                "source/signature-pinned row is required"
            )
            continue
        candidate = candidates[0]
        item = candidate["item"]
        assert isinstance(item, dict)
        bucket = requirements_by_item.setdefault(
            id(item),
            {
                "item": item,
                "reviewed_identity": candidate["reviewed_identity"],
                "signature": candidate["signature"],
                "source_digests": [],
            },
        )
        if (
            bucket["reviewed_identity"] != candidate["reviewed_identity"]
            or bucket["signature"] != candidate["signature"]
        ):
            errors.append(
                "conditional-probability composition sources disagree about the current "
                "direct-evidence signature"
            )
            continue
        bucket["source_digests"].append(source_semantic_digest)

    for requirement in requirements_by_item.values():
        item = requirement["item"]
        assert isinstance(item, dict)
        dimensions = item.get("dimensions")
        if not isinstance(dimensions, list):
            errors.append(
                "conditional-probability composition direct row has no generated semantic "
                "dimensions"
            )
            continue
        if any(
            isinstance(dimension, dict)
            and str(dimension.get("id") or "").strip()
            == SOURCE_MODEL_COMPOSITION_DIMENSION
            for dimension in dimensions
        ):
            errors.append(
                "conditional-probability composition direct row already has a composition "
                "dimension; refusing an ambiguous generated requirement"
            )
            continue
        selected_source_digests = sorted(set(requirement["source_digests"]))
        selected_identities = [
            composition_sources[digest]["source_identity"]
            for digest in selected_source_digests
        ]
        signature = requirement["signature"]
        assert isinstance(signature, dict)
        association_pin = semantic_source_association_digest(
            selected_identities, signature
        )
        if not association_pin:
            errors.append(
                "conditional-probability composition direct row cannot derive a current "
                "source/signature semantic association pin"
            )
            continue
        clauses: list[dict[str, Any]] = []
        malformed_clause_requirement = False
        for source_semantic_digest in selected_source_digests:
            source = composition_sources[source_semantic_digest]
            composition = source["composition"]
            if not isinstance(composition, dict):
                malformed_clause_requirement = True
                break
            clauses.append(
                {
                    "source_semantic_sha256": source_semantic_digest,
                    "selector_law": composition.get("selector_law"),
                    "conditional_outcome_law": composition.get(
                        "conditional_outcome_law"
                    ),
                    "composed_objective_or_expectation": composition.get(
                        "composed_objective_or_expectation"
                    ),
                }
            )
        if malformed_clause_requirement:
            errors.append(
                "conditional-probability composition direct row has malformed source clauses"
            )
            continue
        reviewed_identity = requirement["reviewed_identity"]
        assert isinstance(reviewed_identity, dict)
        dimensions.append(
            {
                "id": SOURCE_MODEL_COMPOSITION_DIMENSION,
                # This is intentionally false: a scalar Lean conclusion can
                # still need the review because its *source* model is two-stage.
                "detected_from_expanded_surface": False,
                "required_from_source_pinned_contract": True,
                "source_contract_basis": (
                    "schema-2 byte-pinned selector law, conditional outcome law, "
                    "and composed objective/expectation"
                ),
                "required_check": (
                    "Compare the byte-pinned selector law, conditional outcome law, "
                    "and composed objective/expectation as one source model. Establish "
                    "the current direct Lean endpoint from source primitives by either a "
                    "checked two-stage finite expectation or a checked joint-law "
                    "factorization; a scalar conclusion or declaration name alone is not "
                    "a bridge."
                ),
                "requires_checked_bridge_when_detected": False,
                "requires_checked_bridge_when_required": True,
                "requires_source_model_composition_analysis": True,
                "source_model_composition": {
                    "schema": SOURCE_MODEL_COMPOSITION_REQUIREMENT_SCHEMA,
                    "clauses": clauses,
                },
                SOURCE_MODEL_COMPOSITION_ASSOCIATION_FIELD: {
                    "schema": 2,
                    "source_item_semantic_sha256": selected_source_digests,
                    "reviewed_declaration_identity": reviewed_identity,
                    "reviewed_elaborated_signature_identity": signature,
                    "semantic_association_sha256": association_pin,
                },
            }
        )
        item["required_check"] = (
            str(item.get("required_check") or "")
            + " This row has a schema-2 source-pinned conditional-probability "
            "composition requirement; do not infer the outer/inner law bridge from "
            "the declaration name or scalar result type."
        )
        counts["conditional_probability_composition_requirement_count"] += 1

    return items, sorted(set(errors)), counts


def attach_equality_defined_partition_requirements(
    items: list[dict[str, Any]],
    *,
    paper_statement_map: dict[str, Any] | None,
    elaborated_signature_sha256_by_qualified: dict[str, str],
) -> tuple[list[dict[str, Any]], list[str], dict[str, int]]:
    """Attach source-pinned two-direction partition obligations.

    A map opts in only with a byte-pinned ``equality_defined_partition``
    context.  The context is joined to one current semantic-model row through
    the existing source-content plus elaborated-signature association.  No map
    key, theorem label, binder spelling, structure name, or field name is used
    to select the row or to decide either implication.
    """

    counts = {
        "equality_defined_partition_context_count": 0,
        "equality_defined_partition_requirement_count": 0,
    }
    if not isinstance(paper_statement_map, dict):
        return items, [], counts
    raw_source_items = paper_statement_map.get("items")
    if not isinstance(raw_source_items, dict):
        return items, [], counts

    errors: list[str] = []
    partition_sources: dict[str, dict[str, Any]] = {}
    for raw_source_key, raw_source_item in raw_source_items.items():
        if not isinstance(raw_source_item, dict):
            continue
        raw_contexts = raw_source_item.get("semantic_context_requirements")
        if not isinstance(raw_contexts, list):
            continue
        selected_contexts = [
            raw_context
            for raw_context in raw_contexts
            if isinstance(raw_context, dict)
            and raw_context.get("kind") == EQUALITY_DEFINED_PARTITION_CONTEXT_KIND
        ]
        if not selected_contexts:
            continue
        source_identity = semantic_contract_source_identity(
            str(raw_source_key), raw_source_item
        )
        source_semantic_digest = str(
            source_identity.get("source_semantic_sha256") or ""
        ).strip().lower()
        if not SHA256_RE.fullmatch(source_semantic_digest):
            errors.append(
                "equality-defined partition context has no source-content semantic identity"
            )
            continue
        if len(selected_contexts) != 1:
            errors.append(
                "one source-content identity has multiple equality-defined partition "
                "contexts; declare one exact feature/class equivalence contract per "
                "source route"
            )
            continue
        context = selected_contexts[0]
        for error in equality_defined_partition_context_contract_errors(context):
            errors.append("equality-defined partition context is malformed: " + error)
        anchors = context.get("source_anchor_evidence")
        if not isinstance(anchors, list) or not anchors:
            errors.append(
                "equality-defined partition context has no byte-pinned source anchor"
            )
        if not str(context.get("source_location") or "").strip():
            errors.append("equality-defined partition context has no source location")
        if not str(context.get("explanation") or "").strip():
            errors.append("equality-defined partition context has no semantic explanation")
        if source_semantic_digest in partition_sources:
            errors.append(
                "multiple source-map items have the same equality-defined partition "
                "source-content identity; source route selection is ambiguous"
            )
            continue
        partition_sources[source_semantic_digest] = {
            "source_identity": source_identity,
            "context": context,
        }

    counts["equality_defined_partition_context_count"] = len(partition_sources)
    if not partition_sources:
        return items, sorted(set(errors)), counts

    partition_source_digests = set(partition_sources)
    candidates_by_source_digest: dict[str, list[dict[str, Any]]] = {
        digest: [] for digest in partition_source_digests
    }
    for item in items:
        if not isinstance(item, dict):
            continue
        for association_field in (
            "source_statement_association",
            "semantic_contract_source_association",
        ):
            association = item.get(association_field)
            if not isinstance(association, dict):
                continue
            role = str(association.get("role") or "").strip()
            if association_field == "source_statement_association":
                if (
                    role != EXPLICIT_DIRECT_SOURCE_ROUTE_ROLE
                    or str(association.get("association_origin") or "").strip()
                    != EXPLICIT_DIRECT_SOURCE_ROUTE_ORIGIN
                ):
                    continue
            elif role not in {"direct_evidence", "transparent_spec"}:
                continue
            source_identities, association_errors = source_contract_source_identities(
                association.get("source_item_identities")
            )
            associated_digests = {
                str(identity.get("source_semantic_sha256") or "").strip().lower()
                for identity in source_identities
            }
            matched_source_digests = sorted(
                associated_digests & partition_source_digests
            )
            if not matched_source_digests:
                continue
            qualified = semantic_contract_fully_qualified_identity(
                item.get("qualified_declaration")
            )
            reviewed_identity = association.get("reviewed_declaration_identity")
            reviewed_key = reviewed_declaration_identity_key(reviewed_identity)
            current_signature = reviewed_elaborated_signature_identity(
                reviewed_identity, elaborated_signature_sha256_by_qualified
            )
            association_signature = association.get(
                "reviewed_elaborated_signature_identity"
            )
            expected_association_pin = semantic_source_association_digest(
                source_identities, current_signature
            )
            route_errors = list(association_errors)
            if association.get("schema") != 2:
                route_errors.append("has no schema-2 source/signature association")
            if reviewed_key is None or qualified != reviewed_key[0]:
                route_errors.append(
                    "reviewed declaration identity does not match the generated direct row"
                )
            if current_signature is None or association_signature != current_signature:
                route_errors.append(
                    "has no current elaborated signature for the generated direct row"
                )
            if (
                not expected_association_pin
                or str(association.get("semantic_association_sha256") or "")
                .strip()
                .lower()
                != expected_association_pin
            ):
                route_errors.append(
                    "semantic association pin does not match the current source "
                    "identities and elaborated signature"
                )
            if route_errors:
                errors.extend(
                    "equality-defined partition direct route is unusable: " + error
                    for error in route_errors
                )
                continue
            assert isinstance(reviewed_identity, dict)
            assert current_signature is not None
            for source_semantic_digest in matched_source_digests:
                candidates_by_source_digest[source_semantic_digest].append(
                    {
                        "item": item,
                        "reviewed_identity": dict(reviewed_identity),
                        "signature": dict(current_signature),
                    }
                )

    requirements_by_item: dict[int, dict[str, Any]] = {}
    for source_semantic_digest in sorted(partition_source_digests):
        candidates = candidates_by_source_digest[source_semantic_digest]
        if len(candidates) != 1:
            errors.append(
                "equality-defined partition source identity has "
                f"{len(candidates)} current direct-evidence rows; exactly one "
                "source/signature-pinned semantic row is required"
            )
            continue
        candidate = candidates[0]
        item = candidate["item"]
        assert isinstance(item, dict)
        bucket = requirements_by_item.setdefault(
            id(item),
            {
                "item": item,
                "reviewed_identity": candidate["reviewed_identity"],
                "signature": candidate["signature"],
                "source_digests": [],
            },
        )
        if (
            bucket["reviewed_identity"] != candidate["reviewed_identity"]
            or bucket["signature"] != candidate["signature"]
        ):
            errors.append(
                "equality-defined partition source contexts disagree about the "
                "current direct-evidence signature"
            )
            continue
        bucket["source_digests"].append(source_semantic_digest)

    for requirement in requirements_by_item.values():
        item = requirement["item"]
        assert isinstance(item, dict)
        dimensions = item.get("dimensions")
        if not isinstance(dimensions, list):
            errors.append(
                "equality-defined partition direct row has no generated semantic dimensions"
            )
            continue
        if any(
            isinstance(dimension, dict)
            and str(dimension.get("id") or "").strip()
            == SOURCE_EQUALITY_PARTITION_DIMENSION
            for dimension in dimensions
        ):
            errors.append(
                "equality-defined partition direct row already has a partition "
                "dimension; refusing an ambiguous generated requirement"
            )
            continue
        selected_source_digests = sorted(set(requirement["source_digests"]))
        selected_identities = [
            partition_sources[digest]["source_identity"]
            for digest in selected_source_digests
        ]
        signature = requirement["signature"]
        assert isinstance(signature, dict)
        association_pin = semantic_source_association_digest(
            selected_identities, signature
        )
        if not association_pin:
            errors.append(
                "equality-defined partition direct row cannot derive a current "
                "source/signature semantic association pin"
            )
            continue
        contracts = [
            {
                "source_semantic_sha256": digest,
                "source_location": partition_sources[digest]["context"].get(
                    "source_location"
                ),
                "explanation": partition_sources[digest]["context"].get(
                    "explanation"
                ),
                "source_anchor_evidence": partition_sources[digest]["context"].get(
                    "source_anchor_evidence"
                ),
                EQUALITY_DEFINED_PARTITION_CONTRACT_FIELD: partition_sources[
                    digest
                ]["context"].get(EQUALITY_DEFINED_PARTITION_CONTRACT_FIELD),
            }
            for digest in selected_source_digests
        ]
        reviewed_identity = requirement["reviewed_identity"]
        assert isinstance(reviewed_identity, dict)
        dimensions.append(
            {
                "id": SOURCE_EQUALITY_PARTITION_DIMENSION,
                # The source context can require this review even when a
                # scalar theorem result does not expose its model record.
                "detected_from_expanded_surface": False,
                "required_from_source_pinned_context": True,
                "source_context_basis": (
                    "byte-pinned source contract defining class labels exactly "
                    "by equality of the stated feature"
                ),
                "required_check": (
                    "Audit both directions of the source-defined partition: "
                    "feature equality must imply class equality and class equality "
                    "must imply feature equality. A within-class agreement field or "
                    "a declaration/function name establishes only one direction. "
                    "Expose each implication in the expanded formal model or provide "
                    "a checked bridge from source primitives."
                ),
                "requires_checked_bridge_when_detected": False,
                "requires_checked_bridge_when_required": True,
                "requires_source_equality_partition_analysis": True,
                "source_equality_partition": {
                    "schema": SOURCE_EQUALITY_PARTITION_REQUIREMENT_SCHEMA,
                    "contracts": contracts,
                },
                SOURCE_EQUALITY_PARTITION_ASSOCIATION_FIELD: {
                    "schema": 2,
                    "source_item_semantic_sha256": selected_source_digests,
                    "reviewed_declaration_identity": reviewed_identity,
                    "reviewed_elaborated_signature_identity": signature,
                    "semantic_association_sha256": association_pin,
                },
            }
        )
        item["required_check"] = (
            str(item.get("required_check") or "")
            + " This row has a byte-pinned source equality-defined-partition "
            "requirement; do not treat only same-class feature agreement as "
            "the source's exact partition."
        )
        counts["equality_defined_partition_requirement_count"] += 1

    return items, sorted(set(errors)), counts


def attach_strategic_observation_totality_requirements(
    items: list[dict[str, Any]],
    *,
    paper_statement_map: dict[str, Any] | None,
    elaborated_signature_sha256_by_qualified: dict[str, str],
) -> tuple[list[dict[str, Any]], list[str], dict[str, int]]:
    """Attach source-pinned off-path observation obligations to direct rows.

    The context is selected from byte-pinned source semantics first. It is
    then joined to exactly one current direct evidence surface using only the
    generated source-content identity and elaborated declaration signature.
    It never searches a Lean theorem/predicate/function name for equilibrium
    terminology, so renaming the formal model cannot suppress this review.
    """

    counts = {
        "strategic_observation_totality_context_count": 0,
        "strategic_observation_totality_requirement_count": 0,
    }
    if not isinstance(paper_statement_map, dict):
        return items, [], counts
    raw_source_items = paper_statement_map.get("items")
    if not isinstance(raw_source_items, dict):
        return items, [], counts

    errors: list[str] = []
    contexts_by_digest: dict[str, dict[str, Any]] = {}
    for raw_source_key, raw_source_item in raw_source_items.items():
        if not isinstance(raw_source_item, dict):
            continue
        raw_contexts = raw_source_item.get("semantic_context_requirements")
        if not isinstance(raw_contexts, list):
            continue
        selected_contexts = [
            raw_context
            for raw_context in raw_contexts
            if isinstance(raw_context, dict)
            and raw_context.get("kind")
            == STRATEGIC_OBSERVATION_TOTALITY_CONTEXT_KIND
        ]
        if not selected_contexts:
            continue
        source_identity = semantic_contract_source_identity(
            str(raw_source_key), raw_source_item
        )
        source_semantic_digest = str(
            source_identity.get("source_semantic_sha256") or ""
        ).strip().lower()
        if not SHA256_RE.fullmatch(source_semantic_digest):
            errors.append(
                "strategic-observation-totality context has no source-content "
                "semantic identity"
            )
            continue
        if len(selected_contexts) != 1:
            errors.append(
                "one source-content identity has multiple strategic-observation-totality "
                "contexts; declare one exact totality contract per source route"
            )
            continue
        context = selected_contexts[0]
        for error in strategic_observation_totality_context_contract_errors(context):
            errors.append("strategic-observation-totality context is malformed: " + error)
        anchors = context.get("source_anchor_evidence")
        if not isinstance(anchors, list) or not anchors:
            errors.append(
                "strategic-observation-totality context has no byte-pinned source anchor"
            )
        if not str(context.get("source_location") or "").strip():
            errors.append("strategic-observation-totality context has no source location")
        if not str(context.get("explanation") or "").strip():
            errors.append(
                "strategic-observation-totality context has no semantic explanation"
            )
        if source_semantic_digest in contexts_by_digest:
            errors.append(
                "multiple source-map items have the same strategic-observation-totality "
                "source-content identity; source route selection is ambiguous"
            )
            continue
        contexts_by_digest[source_semantic_digest] = {
            "source_identity": source_identity,
            "context": context,
        }

    counts["strategic_observation_totality_context_count"] = len(contexts_by_digest)
    if not contexts_by_digest:
        return items, sorted(set(errors)), counts

    requested_digests = set(contexts_by_digest)
    candidates_by_digest: dict[str, list[dict[str, Any]]] = {
        digest: [] for digest in requested_digests
    }
    for item in items:
        if not isinstance(item, dict):
            continue
        for association_field in (
            "source_statement_association",
            "semantic_contract_source_association",
        ):
            association = item.get(association_field)
            if not isinstance(association, dict):
                continue
            role = str(association.get("role") or "").strip()
            if association_field == "source_statement_association":
                if (
                    role != EXPLICIT_DIRECT_SOURCE_ROUTE_ROLE
                    or str(association.get("association_origin") or "").strip()
                    != EXPLICIT_DIRECT_SOURCE_ROUTE_ORIGIN
                ):
                    continue
            elif role not in {"direct_evidence", "transparent_spec"}:
                continue
            source_identities, association_errors = source_contract_source_identities(
                association.get("source_item_identities")
            )
            associated_digests = {
                str(identity.get("source_semantic_sha256") or "").strip().lower()
                for identity in source_identities
            }
            matched_digests = sorted(associated_digests & requested_digests)
            if not matched_digests:
                continue
            qualified = semantic_contract_fully_qualified_identity(
                item.get("qualified_declaration")
            )
            reviewed_identity = association.get("reviewed_declaration_identity")
            reviewed_key = reviewed_declaration_identity_key(reviewed_identity)
            current_signature = reviewed_elaborated_signature_identity(
                reviewed_identity, elaborated_signature_sha256_by_qualified
            )
            association_signature = association.get(
                "reviewed_elaborated_signature_identity"
            )
            expected_association_pin = semantic_source_association_digest(
                source_identities, current_signature
            )
            route_errors = list(association_errors)
            if association.get("schema") != 2:
                route_errors.append("has no schema-2 source/signature association")
            if reviewed_key is None or qualified != reviewed_key[0]:
                route_errors.append(
                    "reviewed declaration identity does not match the generated direct row"
                )
            if current_signature is None or association_signature != current_signature:
                route_errors.append(
                    "has no current elaborated signature for the generated direct row"
                )
            if (
                not expected_association_pin
                or str(association.get("semantic_association_sha256") or "")
                .strip()
                .lower()
                != expected_association_pin
            ):
                route_errors.append(
                    "semantic association pin does not match the current source "
                    "identities and elaborated signature"
                )
            if route_errors:
                errors.extend(
                    "strategic-observation-totality direct route is unusable: " + error
                    for error in route_errors
                )
                continue
            assert isinstance(reviewed_identity, dict)
            assert current_signature is not None
            for source_semantic_digest in matched_digests:
                candidates_by_digest[source_semantic_digest].append(
                    {
                        "item": item,
                        "reviewed_identity": dict(reviewed_identity),
                        "signature": dict(current_signature),
                    }
                )

    requirements_by_item: dict[int, dict[str, Any]] = {}
    for source_semantic_digest in sorted(requested_digests):
        candidates = candidates_by_digest[source_semantic_digest]
        if len(candidates) != 1:
            errors.append(
                "strategic-observation-totality source identity has "
                f"{len(candidates)} current direct-evidence rows; exactly one "
                "source/signature-pinned semantic row is required"
            )
            continue
        candidate = candidates[0]
        item = candidate["item"]
        assert isinstance(item, dict)
        bucket = requirements_by_item.setdefault(
            id(item),
            {
                "item": item,
                "reviewed_identity": candidate["reviewed_identity"],
                "signature": candidate["signature"],
                "source_digests": [],
            },
        )
        if (
            bucket["reviewed_identity"] != candidate["reviewed_identity"]
            or bucket["signature"] != candidate["signature"]
        ):
            errors.append(
                "strategic-observation-totality source contexts disagree about the "
                "current direct-evidence signature"
            )
            continue
        bucket["source_digests"].append(source_semantic_digest)

    for requirement in requirements_by_item.values():
        item = requirement["item"]
        assert isinstance(item, dict)
        dimensions = item.get("dimensions")
        if not isinstance(dimensions, list):
            errors.append(
                "strategic-observation-totality direct row has no generated semantic "
                "dimensions"
            )
            continue
        if any(
            isinstance(dimension, dict)
            and str(dimension.get("id") or "").strip()
            == STRATEGIC_OBSERVATION_TOTALITY_DIMENSION
            for dimension in dimensions
        ):
            errors.append(
                "strategic-observation-totality direct row already has a totality "
                "dimension; refusing an ambiguous generated requirement"
            )
            continue
        selected_source_digests = sorted(set(requirement["source_digests"]))
        selected_identities = [
            contexts_by_digest[digest]["source_identity"]
            for digest in selected_source_digests
        ]
        signature = requirement["signature"]
        assert isinstance(signature, dict)
        association_pin = semantic_source_association_digest(
            selected_identities, signature
        )
        if not association_pin:
            errors.append(
                "strategic-observation-totality direct row cannot derive a current "
                "source/signature semantic association pin"
            )
            continue
        contracts = [
            {
                "source_semantic_sha256": digest,
                "source_location": contexts_by_digest[digest]["context"].get(
                    "source_location"
                ),
                "explanation": contexts_by_digest[digest]["context"].get(
                    "explanation"
                ),
                "source_anchor_evidence": contexts_by_digest[digest]["context"].get(
                    "source_anchor_evidence"
                ),
                STRATEGIC_OBSERVATION_TOTALITY_CONTRACT_FIELD: contexts_by_digest[
                    digest
                ]["context"].get(STRATEGIC_OBSERVATION_TOTALITY_CONTRACT_FIELD),
            }
            for digest in selected_source_digests
        ]
        reviewed_identity = requirement["reviewed_identity"]
        assert isinstance(reviewed_identity, dict)
        dimensions.append(
            {
                "id": STRATEGIC_OBSERVATION_TOTALITY_DIMENSION,
                # A scalar theorem conclusion can hide the action/payoff game.
                "detected_from_expanded_surface": False,
                "required_from_source_pinned_context": True,
                "source_context_basis": (
                    "byte-pinned source contract for a feasible-action equilibrium "
                    "with an observation-contingent conditional value, selected "
                    "conditioning population, action history, and conditionalization scopes"
                ),
                "required_check": (
                    "Audit the source equilibrium action domain, every observation "
                    "branch induced by a feasible action, and the definedness of the "
                    "conditional/posterior value on zero-probability branches. A full "
                    "match requires a checked source-backed totalization, positivity, "
                    "infeasibility, or explicit equilibrium-domain restriction; a Lean-only "
                    "off-path payoff/belief completion is not source credit. Also pin the "
                    "source conditioning population/carrier, every sequential action-history "
                    "component of the selected event, measurability and null status of the "
                    "action/observation event, and the a.e. base/fibre scope of any RCD or "
                    "disintegration. When the source route uses several conditionalization "
                    "modes, give source-vs-Lean evidence for each declared mode; a chosen "
                    "pointwise version is not source credit."
                ),
                "requires_checked_bridge_when_detected": False,
                "requires_checked_bridge_when_required": True,
                "requires_strategic_observation_totality_analysis": True,
                STRATEGIC_OBSERVATION_TOTALITY_REQUIREMENT_FIELD: {
                    "schema": STRATEGIC_OBSERVATION_TOTALITY_REQUIREMENT_SCHEMA,
                    "contracts": contracts,
                },
                STRATEGIC_OBSERVATION_TOTALITY_ASSOCIATION_FIELD: {
                    "schema": 2,
                    "source_item_semantic_sha256": selected_source_digests,
                    "reviewed_declaration_identity": reviewed_identity,
                    "reviewed_elaborated_signature_identity": signature,
                    "semantic_association_sha256": association_pin,
                },
            }
        )
        item["required_check"] = (
            str(item.get("required_check") or "")
            + " This row has a byte-pinned strategic-observation-totality "
            "requirement; do not assume an off-path conditional value is defined "
            "because Lean selected a default completion, a subgroup/access carrier is "
            "implicit, an event is measurable, or an a.e. conditional version applies "
            "pointwise."
        )
        counts["strategic_observation_totality_requirement_count"] += 1

    return items, sorted(set(errors)), counts


def attach_conditioning_information_requirements(
    items: list[dict[str, Any]],
    *,
    paper_statement_map: dict[str, Any] | None,
    elaborated_signature_sha256_by_qualified: dict[str, str],
) -> tuple[list[dict[str, Any]], list[str], dict[str, int]]:
    """Attach source-pinned conditional-information obligations to direct rows.

    The source context supplies semantic observed-component IDs, ordered action
    selection stages, raw-vs-selected law population, and conditionalization
    scope. It is joined to exactly one current direct semantic row through the
    existing source-content identity and elaborated signature. No Lean function,
    theorem, field, or binder name selects the obligation or can make a missing
    information component look harmless.
    """

    counts = {
        "conditioning_information_context_count": 0,
        "conditioning_information_requirement_count": 0,
    }
    if not isinstance(paper_statement_map, dict):
        return items, [], counts
    raw_source_items = paper_statement_map.get("items")
    if not isinstance(raw_source_items, dict):
        return items, [], counts

    errors: list[str] = []
    contexts_by_digest: dict[str, dict[str, Any]] = {}
    for raw_source_key, raw_source_item in raw_source_items.items():
        if not isinstance(raw_source_item, dict):
            continue
        raw_contexts = raw_source_item.get("semantic_context_requirements")
        if not isinstance(raw_contexts, list):
            continue
        selected_contexts = [
            raw_context
            for raw_context in raw_contexts
            if isinstance(raw_context, dict)
            and raw_context.get("kind") == CONDITIONING_INFORMATION_CONTEXT_KIND
        ]
        if not selected_contexts:
            continue
        source_identity = semantic_contract_source_identity(
            str(raw_source_key), raw_source_item
        )
        source_semantic_digest = str(
            source_identity.get("source_semantic_sha256") or ""
        ).strip().lower()
        if not SHA256_RE.fullmatch(source_semantic_digest):
            errors.append(
                "conditioning-information context has no source-content semantic identity"
            )
            continue
        if len(selected_contexts) != 1:
            errors.append(
                "one source-content identity has multiple conditioning-information "
                "contexts; declare one exact information contract per source route"
            )
            continue
        context = selected_contexts[0]
        for error in conditioning_information_context_contract_errors(context):
            errors.append("conditioning-information context is malformed: " + error)
        anchors = context.get("source_anchor_evidence")
        if not isinstance(anchors, list) or not anchors:
            errors.append("conditioning-information context has no byte-pinned source anchor")
        if not str(context.get("source_location") or "").strip():
            errors.append("conditioning-information context has no source location")
        if not str(context.get("explanation") or "").strip():
            errors.append("conditioning-information context has no semantic explanation")
        if source_semantic_digest in contexts_by_digest:
            errors.append(
                "multiple source-map items have the same conditioning-information "
                "source-content identity; source route selection is ambiguous"
            )
            continue
        contexts_by_digest[source_semantic_digest] = {
            "source_identity": source_identity,
            "context": context,
        }

    counts["conditioning_information_context_count"] = len(contexts_by_digest)
    if not contexts_by_digest:
        return items, sorted(set(errors)), counts

    requested_digests = set(contexts_by_digest)
    candidates_by_digest: dict[str, list[dict[str, Any]]] = {
        digest: [] for digest in requested_digests
    }
    for item in items:
        if not isinstance(item, dict):
            continue
        for association_field in (
            "source_statement_association",
            "semantic_contract_source_association",
        ):
            association = item.get(association_field)
            if not isinstance(association, dict):
                continue
            role = str(association.get("role") or "").strip()
            if association_field == "source_statement_association":
                if (
                    role != EXPLICIT_DIRECT_SOURCE_ROUTE_ROLE
                    or str(association.get("association_origin") or "").strip()
                    != EXPLICIT_DIRECT_SOURCE_ROUTE_ORIGIN
                ):
                    continue
            elif role not in {"direct_evidence", "transparent_spec"}:
                continue
            source_identities, association_errors = source_contract_source_identities(
                association.get("source_item_identities")
            )
            associated_digests = {
                str(identity.get("source_semantic_sha256") or "").strip().lower()
                for identity in source_identities
            }
            matched_digests = sorted(associated_digests & requested_digests)
            if not matched_digests:
                continue
            qualified = semantic_contract_fully_qualified_identity(
                item.get("qualified_declaration")
            )
            reviewed_identity = association.get("reviewed_declaration_identity")
            reviewed_key = reviewed_declaration_identity_key(reviewed_identity)
            current_signature = reviewed_elaborated_signature_identity(
                reviewed_identity, elaborated_signature_sha256_by_qualified
            )
            association_signature = association.get(
                "reviewed_elaborated_signature_identity"
            )
            expected_association_pin = semantic_source_association_digest(
                source_identities, current_signature
            )
            route_errors = list(association_errors)
            if association.get("schema") != 2:
                route_errors.append("has no schema-2 source/signature association")
            if reviewed_key is None or qualified != reviewed_key[0]:
                route_errors.append(
                    "reviewed declaration identity does not match the generated direct row"
                )
            if current_signature is None or association_signature != current_signature:
                route_errors.append(
                    "has no current elaborated signature for the generated direct row"
                )
            if (
                not expected_association_pin
                or str(association.get("semantic_association_sha256") or "")
                .strip()
                .lower()
                != expected_association_pin
            ):
                route_errors.append(
                    "semantic association pin does not match the current source "
                    "identities and elaborated signature"
                )
            if route_errors:
                errors.extend(
                    "conditioning-information direct route is unusable: " + error
                    for error in route_errors
                )
                continue
            assert isinstance(reviewed_identity, dict)
            assert current_signature is not None
            for source_semantic_digest in matched_digests:
                candidates_by_digest[source_semantic_digest].append(
                    {
                        "item": item,
                        "reviewed_identity": dict(reviewed_identity),
                        "signature": dict(current_signature),
                    }
                )

    requirements_by_item: dict[int, dict[str, Any]] = {}
    for source_semantic_digest in sorted(requested_digests):
        candidates = candidates_by_digest[source_semantic_digest]
        if len(candidates) != 1:
            errors.append(
                "conditioning-information source identity has "
                f"{len(candidates)} current direct-evidence rows; exactly one "
                "source/signature-pinned semantic row is required"
            )
            continue
        candidate = candidates[0]
        item = candidate["item"]
        assert isinstance(item, dict)
        bucket = requirements_by_item.setdefault(
            id(item),
            {
                "item": item,
                "reviewed_identity": candidate["reviewed_identity"],
                "signature": candidate["signature"],
                "source_digests": [],
            },
        )
        if (
            bucket["reviewed_identity"] != candidate["reviewed_identity"]
            or bucket["signature"] != candidate["signature"]
        ):
            errors.append(
                "conditioning-information source contexts disagree about the current "
                "direct-evidence signature"
            )
            continue
        bucket["source_digests"].append(source_semantic_digest)

    for requirement in requirements_by_item.values():
        item = requirement["item"]
        assert isinstance(item, dict)
        dimensions = item.get("dimensions")
        if not isinstance(dimensions, list):
            errors.append(
                "conditioning-information direct row has no generated semantic dimensions"
            )
            continue
        if any(
            isinstance(dimension, dict)
            and str(dimension.get("id") or "").strip()
            == CONDITIONING_INFORMATION_DIMENSION
            for dimension in dimensions
        ):
            errors.append(
                "conditioning-information direct row already has an information "
                "dimension; refusing an ambiguous generated requirement"
            )
            continue
        selected_source_digests = sorted(set(requirement["source_digests"]))
        selected_identities = [
            contexts_by_digest[digest]["source_identity"]
            for digest in selected_source_digests
        ]
        signature = requirement["signature"]
        assert isinstance(signature, dict)
        association_pin = semantic_source_association_digest(
            selected_identities, signature
        )
        if not association_pin:
            errors.append(
                "conditioning-information direct row cannot derive a current "
                "source/signature semantic association pin"
            )
            continue
        contracts = [
            {
                "source_semantic_sha256": digest,
                "source_location": contexts_by_digest[digest]["context"].get(
                    "source_location"
                ),
                "explanation": contexts_by_digest[digest]["context"].get(
                    "explanation"
                ),
                "source_anchor_evidence": contexts_by_digest[digest]["context"].get(
                    "source_anchor_evidence"
                ),
                CONDITIONING_INFORMATION_CONTRACT_FIELD: contexts_by_digest[digest][
                    "context"
                ].get(CONDITIONING_INFORMATION_CONTRACT_FIELD),
            }
            for digest in selected_source_digests
        ]
        reviewed_identity = requirement["reviewed_identity"]
        assert isinstance(reviewed_identity, dict)
        dimensions.append(
            {
                "id": CONDITIONING_INFORMATION_DIMENSION,
                # A scalar theorem can hide the exact observation sigma-algebra.
                "detected_from_expanded_surface": False,
                "required_from_source_pinned_context": True,
                "source_context_basis": (
                    "byte-pinned source contract for a conditional expectation, "
                    "Bayesian/PBO belief, or conditional law"
                ),
                "required_check": (
                    "Compare source and Lean conditioning information semantically: "
                    "identify the conditional-value kind, enumerate every observed "
                    "source component, every ordered action selection stage, whether "
                    "the law is raw or selected, and the positive-event, pointwise, "
                    "or a.e. conditionalization scope. A direct match requires all "
                    "five to agree. A raw posterior cannot stand in for a posterior "
                    "after source action selection, and an a.e. conditional-law version "
                    "cannot silently become pointwise."
                ),
                "requires_checked_bridge_when_detected": False,
                "requires_checked_bridge_when_required": True,
                "requires_conditioning_information_analysis": True,
                CONDITIONING_INFORMATION_REQUIREMENT_FIELD: {
                    "schema": CONDITIONING_INFORMATION_REQUIREMENT_SCHEMA,
                    "contracts": contracts,
                },
                CONDITIONING_INFORMATION_ASSOCIATION_FIELD: {
                    "schema": 2,
                    "source_item_semantic_sha256": selected_source_digests,
                    "reviewed_declaration_identity": reviewed_identity,
                    "reviewed_elaborated_signature_identity": signature,
                    "semantic_association_sha256": association_pin,
                },
            }
        )
        item["required_check"] = (
            str(item.get("required_check") or "")
            + " This row has a byte-pinned conditioning-information requirement; do "
            "not treat a different conditional-value kind, raw/unselected conditional "
            "law, coarser observed map, omitted action stage, or changed a.e./pointwise "
            "scope as a direct source match."
        )
        counts["conditioning_information_requirement_count"] += 1

    return items, sorted(set(errors)), counts


def source_pinned_context_direct_row_buckets(
    items: list[dict[str, Any]],
    *,
    paper_statement_map: dict[str, Any] | None,
    elaborated_signature_sha256_by_qualified: dict[str, str],
    context_kind: str,
    context_validator: Callable[[object], list[str]],
    context_label: str,
) -> tuple[dict[str, dict[str, Any]], list[dict[str, Any]], list[str]]:
    """Join one declared source context to exactly one direct semantic row.

    This is deliberately source-identity/signature based. The source-map key
    is used only to fetch the byte-pinned semantic identity, while the Lean
    row is selected through an already generated exact direct association. No
    theorem, record, function, field, or binder spelling determines the join.
    """

    if not isinstance(paper_statement_map, dict):
        return {}, [], []
    raw_source_items = paper_statement_map.get("items")
    if not isinstance(raw_source_items, dict):
        return {}, [], []

    contexts_by_digest: dict[str, dict[str, Any]] = {}
    errors: list[str] = []
    for raw_source_key, raw_source_item in raw_source_items.items():
        if not isinstance(raw_source_item, dict):
            continue
        raw_contexts = raw_source_item.get("semantic_context_requirements")
        if not isinstance(raw_contexts, list):
            continue
        selected_contexts = [
            context
            for context in raw_contexts
            if isinstance(context, dict) and context.get("kind") == context_kind
        ]
        if not selected_contexts:
            continue
        source_identity = semantic_contract_source_identity(
            str(raw_source_key), raw_source_item
        )
        source_digest = str(
            source_identity.get("source_semantic_sha256") or ""
        ).strip().lower()
        if not SHA256_RE.fullmatch(source_digest):
            errors.append(
                f"{context_label} context has no source-content semantic identity"
            )
            continue
        if len(selected_contexts) != 1:
            errors.append(
                f"one source-content identity has multiple {context_label} contexts; "
                "declare one exact context per source route"
            )
            continue
        context = selected_contexts[0]
        for error in context_validator(context):
            errors.append(f"{context_label} context is malformed: {error}")
        if not isinstance(context.get("source_anchor_evidence"), list) or not context.get(
            "source_anchor_evidence"
        ):
            errors.append(f"{context_label} context has no byte-pinned source anchor")
        if not str(context.get("source_location") or "").strip():
            errors.append(f"{context_label} context has no source location")
        if not str(context.get("explanation") or "").strip():
            errors.append(f"{context_label} context has no semantic explanation")
        if source_digest in contexts_by_digest:
            errors.append(
                f"multiple source-map items have the same {context_label} "
                "source-content identity; source route selection is ambiguous"
            )
            continue
        contexts_by_digest[source_digest] = {
            "source_identity": source_identity,
            "context": context,
        }

    if not contexts_by_digest:
        return contexts_by_digest, [], sorted(set(errors))

    requested_digests = set(contexts_by_digest)
    candidates_by_digest: dict[str, list[dict[str, Any]]] = {
        digest: [] for digest in requested_digests
    }
    for item in items:
        if not isinstance(item, dict):
            continue
        for association_field in (
            "source_statement_association",
            "semantic_contract_source_association",
        ):
            association = item.get(association_field)
            if not isinstance(association, dict):
                continue
            role = str(association.get("role") or "").strip()
            if association_field == "source_statement_association":
                if (
                    role != EXPLICIT_DIRECT_SOURCE_ROUTE_ROLE
                    or str(association.get("association_origin") or "").strip()
                    != EXPLICIT_DIRECT_SOURCE_ROUTE_ORIGIN
                ):
                    continue
            elif role not in {"direct_evidence", "transparent_spec"}:
                continue
            source_identities, association_errors = source_contract_source_identities(
                association.get("source_item_identities")
            )
            associated_digests = {
                str(identity.get("source_semantic_sha256") or "").strip().lower()
                for identity in source_identities
            }
            matched_digests = sorted(associated_digests & requested_digests)
            if not matched_digests:
                continue
            qualified = semantic_contract_fully_qualified_identity(
                item.get("qualified_declaration")
            )
            reviewed_identity = association.get("reviewed_declaration_identity")
            reviewed_key = reviewed_declaration_identity_key(reviewed_identity)
            current_signature = reviewed_elaborated_signature_identity(
                reviewed_identity, elaborated_signature_sha256_by_qualified
            )
            association_signature = association.get(
                "reviewed_elaborated_signature_identity"
            )
            expected_association_pin = semantic_source_association_digest(
                source_identities, current_signature
            )
            route_errors = list(association_errors)
            if association.get("schema") != 2:
                route_errors.append("has no schema-2 source/signature association")
            if reviewed_key is None or qualified != reviewed_key[0]:
                route_errors.append(
                    "reviewed declaration identity does not match the generated direct row"
                )
            if current_signature is None or association_signature != current_signature:
                route_errors.append(
                    "has no current elaborated signature for the generated direct row"
                )
            if (
                not expected_association_pin
                or str(association.get("semantic_association_sha256") or "")
                .strip()
                .lower()
                != expected_association_pin
            ):
                route_errors.append(
                    "semantic association pin does not match the current source "
                    "identities and elaborated signature"
                )
            if route_errors:
                errors.extend(
                    f"{context_label} direct route is unusable: {error}"
                    for error in route_errors
                )
                continue
            assert isinstance(reviewed_identity, dict)
            assert isinstance(current_signature, dict)
            for source_digest in matched_digests:
                candidates_by_digest[source_digest].append(
                    {
                        "item": item,
                        "reviewed_identity": dict(reviewed_identity),
                        "signature": dict(current_signature),
                    }
                )

    buckets_by_item: dict[int, dict[str, Any]] = {}
    for source_digest in sorted(requested_digests):
        candidates = candidates_by_digest[source_digest]
        if len(candidates) != 1:
            errors.append(
                f"{context_label} source identity has {len(candidates)} current "
                "direct-evidence rows; exactly one source/signature-pinned row is required"
            )
            continue
        candidate = candidates[0]
        item = candidate["item"]
        assert isinstance(item, dict)
        bucket = buckets_by_item.setdefault(
            id(item),
            {
                "item": item,
                "reviewed_identity": candidate["reviewed_identity"],
                "signature": candidate["signature"],
                "source_digests": [],
            },
        )
        if (
            bucket["reviewed_identity"] != candidate["reviewed_identity"]
            or bucket["signature"] != candidate["signature"]
        ):
            errors.append(
                f"{context_label} source contexts disagree about the current "
                "direct-evidence signature"
            )
            continue
        bucket["source_digests"].append(source_digest)

    return contexts_by_digest, list(buckets_by_item.values()), sorted(set(errors))


def attach_source_model_derivation_requirements(
    items: list[dict[str, Any]],
    *,
    paper_statement_map: dict[str, Any] | None,
    elaborated_signature_sha256_by_qualified: dict[str, str],
) -> tuple[list[dict[str, Any]], list[str], dict[str, int]]:
    """Attach primitive-to-consequence audit obligations to direct source rows.

    A map must explicitly declare this source-pinned context. The resulting
    semantic row cannot receive `matches_source_model` credit by saying that a
    process/cycle/conditional law was supplied in a record: only a structured,
    signature-bound checked derivation from every declared source primitive is
    a safe route.
    """

    counts = {
        "source_model_derivation_context_count": 0,
        "source_model_derivation_requirement_count": 0,
    }
    contexts_by_digest, buckets, errors = source_pinned_context_direct_row_buckets(
        items,
        paper_statement_map=paper_statement_map,
        elaborated_signature_sha256_by_qualified=(
            elaborated_signature_sha256_by_qualified
        ),
        context_kind=SOURCE_MODEL_DERIVATION_CONTEXT_KIND,
        context_validator=source_model_derivation_context_contract_errors,
        context_label="source-model-derivation",
    )
    counts["source_model_derivation_context_count"] = len(contexts_by_digest)
    if not contexts_by_digest:
        return items, errors, counts

    for requirement in buckets:
        item = requirement["item"]
        assert isinstance(item, dict)
        dimensions = item.get("dimensions")
        if not isinstance(dimensions, list):
            errors.append(
                "source-model-derivation direct row has no generated semantic dimensions"
            )
            continue
        if any(
            isinstance(dimension, dict)
            and str(dimension.get("id") or "").strip()
            == SOURCE_MODEL_DERIVATION_DIMENSION
            for dimension in dimensions
        ):
            errors.append(
                "source-model-derivation direct row already has a derivation "
                "dimension; refusing an ambiguous generated requirement"
            )
            continue
        source_digests = sorted(set(requirement["source_digests"]))
        source_identities = [
            contexts_by_digest[digest]["source_identity"] for digest in source_digests
        ]
        signature = requirement["signature"]
        assert isinstance(signature, dict)
        association_pin = semantic_source_association_digest(source_identities, signature)
        if not association_pin:
            errors.append(
                "source-model-derivation direct row cannot derive a current "
                "source/signature semantic association pin"
            )
            continue
        contracts = [
            {
                "source_semantic_sha256": digest,
                "source_location": contexts_by_digest[digest]["context"].get(
                    "source_location"
                ),
                "explanation": contexts_by_digest[digest]["context"].get(
                    "explanation"
                ),
                "source_anchor_evidence": contexts_by_digest[digest]["context"].get(
                    "source_anchor_evidence"
                ),
                SOURCE_MODEL_DERIVATION_CONTRACT_FIELD: contexts_by_digest[digest][
                    "context"
                ].get(SOURCE_MODEL_DERIVATION_CONTRACT_FIELD),
            }
            for digest in source_digests
        ]
        reviewed_identity = requirement["reviewed_identity"]
        assert isinstance(reviewed_identity, dict)
        # This structural result is generated from the expanded input surface,
        # not supplied by a map author or reviewer. A source-pinned
        # primitive-to-consequence review is fail-closed when that surface
        # already carries a derived construction package: the current generic
        # audit has no machine-generated proof-dependency receipt for a
        # separate primitive-level bridge theorem. A response narrative or
        # route label therefore cannot restore a direct match.
        caller_supplied_basis = caller_supplied_model_construction_basis(item)
        dimensions.append(
            {
                "id": SOURCE_MODEL_DERIVATION_DIMENSION,
                "detected_from_expanded_surface": False,
                "required_from_source_pinned_context": True,
                "source_context_basis": (
                    "byte-pinned source primitive basis and required derived model "
                    "conclusion"
                ),
                "required_check": (
                    "Map every declared source primitive to a Lean primitive role and "
                    "identify a checked derivation of the declared process, cycle, trace, "
                    "or conditional-law conclusion. A record field that merely supplies "
                    "that conclusion is an open boundary, not a source-model match."
                ),
                "caller_supplied_model_construction_basis": caller_supplied_basis,
                "requires_checked_bridge_when_detected": False,
                "requires_checked_bridge_when_required": True,
                "requires_source_model_derivation_analysis": True,
                SOURCE_MODEL_DERIVATION_REQUIREMENT_FIELD: {
                    "schema": SOURCE_MODEL_DERIVATION_REQUIREMENT_SCHEMA,
                    "contracts": contracts,
                },
                SOURCE_MODEL_DERIVATION_ASSOCIATION_FIELD: {
                    "schema": 2,
                    "source_item_semantic_sha256": source_digests,
                    "reviewed_declaration_identity": reviewed_identity,
                    "reviewed_elaborated_signature_identity": signature,
                    "semantic_association_sha256": association_pin,
                },
            }
        )
        item["required_check"] = (
            str(item.get("required_check") or "")
            + " This row has a byte-pinned source-model-derivation requirement; a "
            "caller-supplied conclusion record cannot substitute for a checked primitive "
            "derivation."
        )
        counts["source_model_derivation_requirement_count"] += 1

    return items, sorted(set(errors)), counts


def source_contract_source_identities(
    raw_identities: object,
) -> tuple[list[dict[str, Any]], list[str]]:
    """Normalize the generator-owned source-map identities for one route."""

    if not isinstance(raw_identities, list) or not raw_identities:
        return [], ["semantic-contract route has no source_item_identities"]
    identities: list[dict[str, Any]] = []
    seen_keys: set[str] = set()
    errors: list[str] = []
    for index, raw_identity in enumerate(raw_identities):
        if not isinstance(raw_identity, dict):
            errors.append(f"source_item_identities[{index}] is not an object")
            continue
        source_key = str(raw_identity.get("source_key") or "").strip()
        source_digest = str(
            raw_identity.get("source_map_item_sha256") or ""
        ).strip().lower()
        source_semantic_digest = str(
            raw_identity.get("source_semantic_sha256") or ""
        ).strip().lower()
        if not source_key:
            errors.append(f"source_item_identities[{index}].source_key is missing")
            continue
        if not re.fullmatch(r"[0-9a-f]{64}", source_digest):
            errors.append(
                f"source_item_identities[{index}].source_map_item_sha256 is missing or malformed"
            )
            continue
        if not SHA256_RE.fullmatch(source_semantic_digest):
            errors.append(
                f"source_item_identities[{index}].source_semantic_sha256 is missing or malformed"
            )
            continue
        if source_key in seen_keys:
            errors.append(f"source_item_identities duplicates source-map key `{source_key}`")
            continue
        seen_keys.add(source_key)
        identities.append(dict(raw_identity))
    return sorted(identities, key=lambda identity: str(identity["source_key"])), errors


def source_contract_association_payload(
    *,
    association_mode: str,
    semantic_model_judgment_key: str,
    member_role: str,
    reviewed_identity: dict[str, str],
    source_identities: list[dict[str, Any]],
    reviewed_signature_identity: dict[str, str] | None = None,
) -> dict[str, Any]:
    """Create the hash-pinned association copied to input audit surfaces."""

    source_keys = [str(identity["source_key"]) for identity in source_identities]
    source_digests = {
        str(identity["source_key"]): str(identity["source_map_item_sha256"])
        for identity in source_identities
    }
    source_semantic_digests = sorted(
        {
            str(identity.get("source_semantic_sha256") or "").strip().lower()
            for identity in source_identities
            if SHA256_RE.fullmatch(
                str(identity.get("source_semantic_sha256") or "").strip().lower()
            )
        }
    )
    association: dict[str, Any] = {
        "schema": 1,
        "association_mode": association_mode,
        "semantic_model_judgment_key": semantic_model_judgment_key,
        "semantic_contract_member_role": member_role,
        "reviewed_declaration_identity": reviewed_identity,
        "source_item_identities": source_identities,
        "source_map_item_keys": source_keys,
        "source_map_item_sha256_by_key": source_digests,
        "source_map_item_keys_sha256": stable_digest(source_keys),
    }
    semantic_digest = semantic_source_association_digest(
        source_identities, reviewed_signature_identity
    )
    if semantic_digest and reviewed_signature_identity is not None:
        association["schema"] = 2
        association["reviewed_elaborated_signature_identity"] = (
            reviewed_signature_identity
        )
        association["semantic_association_sha256"] = semantic_digest
    elif source_semantic_digests:
        # Schema 1 remains name/key-exact only.  Expose the source semantic
        # projection for diagnostics, but do not label it a reusable semantic
        # association without a current configured Lean signature.
        association["source_item_semantic_sha256"] = source_semantic_digests
    association["association_sha256"] = stable_digest(association)
    return association


def attach_input_reviewed_declaration_identities(
    items: list[dict[str, Any]],
    *,
    declarations: dict[str, str],
    row_qualified_names: dict[str, str],
) -> None:
    """Materialize declaration-content identities before source-route matching.

    A generated item retains its row for human navigation, but the row is not
    an association key.  This separate preparation step means the source
    contract projection below sees only a fully-qualified declaration and the
    SHA-256 of that declaration's exact generated source.
    """

    for item in items:
        if not isinstance(item, dict):
            continue
        row = str(item.get("row") or "").strip()
        identity = reviewed_declaration_identity(
            row_qualified_names.get(row, row), declarations.get(row, "")
        )
        if identity is not None:
            item["reviewed_declaration_identity"] = identity


def attach_source_contract_associations(
    *,
    boundary_input_items: list[dict[str, Any]],
    conclusion_dependency_items: list[dict[str, Any]],
    semantic_model_items: list[dict[str, Any]],
    paper_statement_map: dict[str, Any] | None,
    elaborated_signature_sha256_by_qualified: dict[str, str],
    theorem_facing_input_items: list[dict[str, Any]] | None = None,
    type_valued_certificate_result_items: list[dict[str, Any]] | None = None,
) -> tuple[list[str], dict[str, int]]:
    """Attach source-map provenance to inputs by declaration content.

    The only association join is ``(fully qualified declaration,
    declaration SHA-256)``.  Row labels are used solely to retrieve the
    already-generated declaration source for an item; binder spellings, short
    names, and function names never participate in the route.  Both explicit
    direct/Spec contracts and source-presentation-selected direct map routes
    must have one generated semantic member. A missing or ambiguous member is
    a generated error, rather than an opportunity to reuse a similarly named
    surface.
    """

    direct_route_declarations: set[str] = set()
    raw_source_items: object = (
        paper_statement_map.get("items")
        if isinstance(paper_statement_map, dict)
        else None
    )
    if isinstance(raw_source_items, dict):
        for raw_source_item in raw_source_items.values():
            if not isinstance(raw_source_item, dict):
                continue
            if raw_source_item.get("claim_bearing") is not True:
                continue
            raw_contract = raw_source_item.get("semantic_contract")
            if not isinstance(raw_contract, dict):
                continue
            for field in ("evidence_declaration", "spec_declaration"):
                qualified = semantic_contract_fully_qualified_identity(
                    raw_contract.get(field)
                )
                if qualified:
                    direct_route_declarations.add(qualified)

    errors: list[str] = []
    candidates: dict[tuple[str, str], list[dict[str, Any]]] = {}
    for semantic_item in semantic_model_items:
        if not isinstance(semantic_item, dict):
            continue
        semantic_key = str(semantic_item.get("judgment_key") or "").strip()
        if not semantic_key:
            continue
        group = semantic_item.get("semantic_contract_group")
        association = semantic_item.get("semantic_contract_source_association")
        if not isinstance(association, dict):
            association = semantic_item.get("source_statement_association")
        if not isinstance(association, dict):
            association = semantic_item.get(SOURCE_ASSUMPTION_ASSOCIATION_FIELD)
        if isinstance(group, dict):
            source_identities, identity_errors = source_contract_source_identities(
                group.get("source_item_identities")
            )
            if identity_errors:
                errors.extend(
                    f"semantic-model item `{semantic_key}` {error}"
                    for error in identity_errors
                )
                continue
            raw_members = group.get("member_rows")
            if not isinstance(raw_members, list) or not raw_members:
                errors.append(
                    f"semantic-model item `{semantic_key}` semantic_contract_group has no member_rows"
                )
                continue
            for member_index, raw_member in enumerate(raw_members):
                if not isinstance(raw_member, dict):
                    errors.append(
                        f"semantic-model item `{semantic_key}` semantic_contract_group.member_rows[{member_index}] is not an object"
                    )
                    continue
                identity = raw_member.get("reviewed_declaration_identity")
                identity_key = reviewed_declaration_identity_key(identity)
                if identity_key is None:
                    errors.append(
                        f"semantic-model item `{semantic_key}` semantic_contract_group.member_rows[{member_index}] lacks a valid reviewed declaration identity"
                    )
                    continue
                member_role = str(raw_member.get("role") or "").strip()
                if not member_role:
                    errors.append(
                        f"semantic-model item `{semantic_key}` semantic_contract_group.member_rows[{member_index}] lacks role"
                    )
                    continue
                candidates.setdefault(identity_key, []).append(
                    source_contract_association_payload(
                        association_mode="semantic_contract_group_member",
                        semantic_model_judgment_key=semantic_key,
                        member_role=member_role,
                        reviewed_identity=dict(identity),
                        source_identities=source_identities,
                        reviewed_signature_identity=(
                            reviewed_elaborated_signature_identity(
                                identity,
                                elaborated_signature_sha256_by_qualified,
                            )
                        ),
                    )
                )
            continue
        if not isinstance(association, dict):
            continue
        source_identities, identity_errors = source_contract_source_identities(
            association.get("source_item_identities")
        )
        if identity_errors:
            errors.extend(
                f"semantic-model item `{semantic_key}` {error}"
                for error in identity_errors
            )
            continue
        identity = association.get("reviewed_declaration_identity")
        identity_key = reviewed_declaration_identity_key(identity)
        if identity_key is None:
            errors.append(
                f"semantic-model item `{semantic_key}` source association lacks a valid reviewed declaration identity"
            )
            continue
        member_role = str(association.get("role") or "").strip()
        if not member_role:
            errors.append(
                f"semantic-model item `{semantic_key}` source association lacks role"
            )
            continue
        association_origin = str(
            association.get("association_origin") or ""
        ).strip()
        if association_origin in {
            EXPLICIT_DIRECT_SOURCE_ROUTE_ORIGIN,
            SOURCE_ASSUMPTION_ASSOCIATION_ORIGIN,
        }:
            direct_route_declarations.add(identity_key[0])
        candidates.setdefault(identity_key, []).append(
            source_contract_association_payload(
                association_mode=(
                    association_origin
                    if association_origin
                    in {
                        EXPLICIT_DIRECT_SOURCE_ROUTE_ORIGIN,
                        SOURCE_ASSUMPTION_ASSOCIATION_ORIGIN,
                    }
                    else "semantic_contract_individual_row"
                ),
                semantic_model_judgment_key=semantic_key,
                member_role=member_role,
                reviewed_identity=dict(identity),
                source_identities=source_identities,
                reviewed_signature_identity=(
                    reviewed_elaborated_signature_identity(
                        identity,
                        elaborated_signature_sha256_by_qualified,
                    )
                ),
            )
        )

    candidates_by_declaration: dict[str, int] = {}
    for qualified, _source_digest in candidates:
        candidates_by_declaration[qualified] = (
            candidates_by_declaration.get(qualified, 0) + 1
        )
    for qualified in sorted(direct_route_declarations):
        if candidates_by_declaration.get(qualified, 0) == 0:
            errors.append(
                "current v10 direct source-map route for fully-qualified declaration "
                f"`{qualified}` has no generated semantic-contract member identity"
            )

    associated_counts = {
        "direct_route_declaration_count": len(direct_route_declarations),
        "semantic_contract_member_identity_count": sum(
            len(value) for value in candidates.values()
        ),
        "boundary_input_association_count": 0,
        "theorem_facing_input_association_count": 0,
        "conclusion_dependency_association_count": 0,
        "type_valued_certificate_result_association_count": 0,
    }
    for surface_name, surface_items in (
        ("boundary_input", boundary_input_items),
        ("theorem_facing_input", theorem_facing_input_items or []),
        ("conclusion_dependency", conclusion_dependency_items),
        (
            "type_valued_certificate_result",
            type_valued_certificate_result_items or [],
        ),
    ):
        for item in surface_items:
            if not isinstance(item, dict):
                continue
            identity = item.get("reviewed_declaration_identity")
            identity_key = reviewed_declaration_identity_key(identity)
            if identity_key is None:
                continue
            if identity_key[0] not in direct_route_declarations:
                continue
            matches = candidates.get(identity_key, [])
            key = str(item.get("judgment_key") or "unknown judgment").strip()
            if len(matches) != 1:
                if not matches:
                    errors.append(
                        f"{surface_name} item `{key}` has a current v10 direct route but no source-map association with the same fully-qualified declaration and declaration SHA-256"
                    )
                else:
                    errors.append(
                        f"{surface_name} item `{key}` has {len(matches)} source-map associations with the same fully-qualified declaration and declaration SHA-256; association is ambiguous"
                    )
                continue
            item["source_contract_association"] = dict(matches[0])
            associated_counts[f"{surface_name}_association_count"] += 1
    return sorted(set(errors)), associated_counts


def theorem_facing_semantic_contract_coverage(
    *,
    theorem_facing_input_items: list[dict[str, Any]],
    type_valued_certificate_result_items: list[dict[str, Any]],
    semantic_model_items: list[dict[str, Any]],
) -> tuple[set[str], list[dict[str, Any]], list[str], dict[str, int]]:
    """Return input keys already reviewed by an exact whole-statement contract.

    The elaborated theorem-input inventory is intentionally complete: it is
    how the audit detects a premise moved between a header, result telescope,
    or dependent guard.  It does *not* follow that every binder needs a second
    human response when an exact source-anchored semantic-model review already
    compares the complete declaration, including its expanded binder surface.

    This is a declaration-content association, not a row, binder, or function
    name heuristic.  An input is suppressible only when the generator has
    already attached its exact source-contract association and that association
    points to the generated whole-statement semantic review.  All unassociated
    occurrences remain independent source-record obligations.  If one shared
    judgment key has any unassociated occurrence, it remains required.
    """

    semantic_by_key: dict[str, dict[str, Any]] = {}
    for semantic_item in semantic_model_items:
        if not isinstance(semantic_item, dict):
            continue
        semantic_key = str(semantic_item.get("judgment_key") or "").strip()
        if semantic_key:
            semantic_by_key[semantic_key] = semantic_item

    covered_keys: set[str] = set()
    standalone_keys: set[str] = set()
    coverage_items: list[dict[str, Any]] = []
    errors: list[str] = []

    for component_kind, items in (
        ("theorem_facing_input", theorem_facing_input_items),
        (
            "type_valued_certificate_result",
            type_valued_certificate_result_items,
        ),
    ):
        for item in items:
            if not isinstance(item, dict):
                continue
            judgment_key = str(
                item.get("source_judgment_key") or item.get("judgment_key") or ""
            ).strip()
            if not judgment_key:
                continue
            occurrence: dict[str, Any] = {
                "schema": 1,
                "component_kind": component_kind,
                "source_judgment_key": judgment_key,
            }
            association = item.get("source_contract_association")
            if not isinstance(association, Mapping):
                standalone_keys.add(judgment_key)
                occurrence["mode"] = "standalone_source_record_judgment"
                occurrence["reason"] = "no exact source-contract association"
                coverage_items.append(occurrence)
                continue

            semantic_key = str(
                association.get("semantic_model_judgment_key") or ""
            ).strip()
            semantic_item = semantic_by_key.get(semantic_key)
            item_identity = reviewed_declaration_identity_key(
                item.get("reviewed_declaration_identity")
            )
            association_identity = reviewed_declaration_identity_key(
                association.get("reviewed_declaration_identity")
            )
            if (
                not semantic_key
                or semantic_item is None
                or item_identity is None
                or item_identity != association_identity
            ):
                standalone_keys.add(judgment_key)
                occurrence["mode"] = "invalid_source_contract_association"
                occurrence["semantic_model_judgment_key"] = semantic_key
                coverage_items.append(occurrence)
                errors.append(
                    "theorem-facing item `"
                    + judgment_key
                    + "` has a source-contract association that does not resolve to "
                    "the same generated whole-statement semantic review"
                )
                continue

            semantic_identity = reviewed_declaration_identity_key(
                semantic_item.get("reviewed_declaration_identity")
            )

            # A grouped semantic contract is one whole-statement review with
            # two distinct declaration identities: direct evidence and its
            # transparent proposition body.  The latter may validly supply a
            # theorem-facing binder, but only when its exact declaration
            # content is a unique member of the generated structural-equality
            # group.  This is deliberately an identity/role join, not a
            # declaration-name convention.
            group = semantic_item.get("semantic_contract_group")
            if isinstance(group, Mapping):
                raw_members = group.get("member_rows")
                group_members: list[tuple[tuple[str, str], str]] = []
                malformed_member = False
                if isinstance(raw_members, list):
                    for member in raw_members:
                        if not isinstance(member, Mapping):
                            malformed_member = True
                            continue
                        member_identity = reviewed_declaration_identity_key(
                            member.get("reviewed_declaration_identity")
                        )
                        member_role = str(member.get("role") or "").strip()
                        if member_identity is None or not member_role:
                            malformed_member = True
                            continue
                        group_members.append((member_identity, member_role))

                direct_members = [
                    member
                    for member in group_members
                    if member[1] == "direct_evidence"
                ]
                associated_members = [
                    member
                    for member in group_members
                    if member[0] == association_identity
                ]
                association_role = str(
                    association.get("semantic_contract_member_role") or ""
                ).strip()
                group_is_current = (
                    association.get("association_mode")
                    == "semantic_contract_group_member"
                    and group.get("structural_alpha_normalized_equal") is True
                    and not malformed_member
                    and len(direct_members) == 1
                    and semantic_identity is not None
                    and direct_members[0][0] == semantic_identity
                    and len(associated_members) == 1
                    and bool(association_role)
                    and associated_members[0][1] == association_role
                )
                if not group_is_current:
                    standalone_keys.add(judgment_key)
                    occurrence["mode"] = "invalid_source_contract_association"
                    occurrence["semantic_model_judgment_key"] = semantic_key
                    coverage_items.append(occurrence)
                    errors.append(
                        "theorem-facing item `"
                        + judgment_key
                        + "` points to a semantic-contract group without an exact "
                        "current member identity, semantic role, and direct-evidence "
                        "review identity"
                    )
                    continue
            elif semantic_identity != association_identity:
                standalone_keys.add(judgment_key)
                occurrence["mode"] = "invalid_source_contract_association"
                occurrence["semantic_model_judgment_key"] = semantic_key
                coverage_items.append(occurrence)
                errors.append(
                    "theorem-facing item `"
                    + judgment_key
                    + "` has a source-contract association that does not resolve to "
                    "the same generated whole-statement semantic review"
                )
                continue

            association_sha256 = str(association.get("association_sha256") or "").strip()
            if not SHA256_RE.fullmatch(association_sha256):
                standalone_keys.add(judgment_key)
                occurrence["mode"] = "invalid_source_contract_association"
                occurrence["semantic_model_judgment_key"] = semantic_key
                coverage_items.append(occurrence)
                errors.append(
                    "theorem-facing item `"
                    + judgment_key
                    + "` has a source-contract association without an integrity receipt"
                )
                continue

            covered_keys.add(judgment_key)
            occurrence.update(
                {
                    "mode": "covered_by_exact_source_contract_semantic_review",
                    "semantic_model_judgment_key": semantic_key,
                    "association_sha256": association_sha256,
                    "reviewed_declaration_identity": {
                        "qualified_declaration": association_identity[0],
                        "declaration_sha256": association_identity[1],
                    },
                }
            )
            coverage_items.append(occurrence)

    # A shared key may arise at multiple generated occurrences.  It can be
    # suppressed only when every occurrence has the exact semantic route.
    covered_keys -= standalone_keys
    coverage_items.sort(
        key=lambda item: (
            str(item.get("source_judgment_key") or ""),
            str(item.get("component_kind") or ""),
            str(item.get("mode") or ""),
        )
    )
    return (
        covered_keys,
        coverage_items,
        sorted(set(errors)),
        {
            "theorem_facing_semantic_contract_covered_input_count": len(
                covered_keys
            ),
            "theorem_facing_standalone_input_count": len(standalone_keys),
            "theorem_facing_semantic_contract_coverage_error_count": len(
                set(errors)
            ),
        },
    )


_RECURSIVE_FIELD_SCOPE_ENTRY_FIELDS = frozenset(
    {
        "source_item",
        "root_record",
        "field_chain",
        "source_locator",
        "permitted_classifications",
    }
)
_RECURSIVE_FIELD_CHAIN_LINK_FIELDS = frozenset({"structure", "field"})
_RECURSIVE_FIELD_SELECTOR_RE = re.compile(r"[A-Za-z_][A-Za-z0-9_']*")
_RECURSIVE_FIELD_PARENT_ASSOCIATION_FIELDS = (
    "source_statement_association",
    "semantic_contract_source_association",
    SOURCE_CLAIM_ATOM_ASSOCIATION_FIELD,
)
# A single semantic-model judgment can carry complementary receipts for the
# same source presentation: the complete direct/Spec route and an atom route
# for a clause inside that presentation.  They are not competing parent
# theorems.  When both validate against the exact same one-item source
# contract, select the canonical complete route deterministically.  Distinct
# semantic-model judgments still remain distinct candidates and therefore
# fail closed as ambiguous below.
_RECURSIVE_FIELD_PARENT_ASSOCIATION_PRECEDENCE = {
    "semantic_contract_source_association": 0,
    "source_statement_association": 1,
    SOURCE_CLAIM_ATOM_ASSOCIATION_FIELD: 2,
}
_RECURSIVE_FIELD_SEMANTIC_CONTRACT_PARENT_ROLES = frozenset(
    {"direct_evidence", "transparent_spec"}
)


def _recursive_field_scope_locator_anchor_error(
    scope: Mapping[str, Any], source_item: Mapping[str, Any]
) -> str:
    """Require every scoped field anchor to lie in its source/convention union.

    A scope must not use a nearby, self-consistent source locator merely
    because its convention is otherwise current.  The source-map item is the
    paper-facing parent and the convention is the explicitly selected model
    reading, so their exact line spans form the only allowed anchor union.
    """

    field_scope = scope.get("field_scope")
    if not isinstance(field_scope, Mapping):
        return "has malformed parsed field scope"
    return recursive_field_scope_locator_anchor_error(
        field_scope.get("source_locator"),
        source_item_locator=source_item.get("source_location"),
        convention_locator=scope.get("convention_source_locator"),
    )


def recursive_field_source_scope_digest(scope: Mapping[str, Any]) -> str:
    """Digest one ordered recursive-field scope without sorting its chain.

    A field chain is a structural route, so its order is mathematical
    provenance rather than an inventory ordering.  The repository's general
    ``stable_digest`` intentionally normalizes lists; use this narrowly
    ordered encoding for a scope receipt instead.
    """

    return recursive_field_source_scope_record_digest(scope)


def recursive_field_source_scope_entries(
    source_proof_fidelity: Mapping[str, Any] | None,
) -> tuple[list[dict[str, Any]], list[str]]:
    """Parse exact recursive-field scopes from source-proof conventions.

    This parser intentionally accepts no aliases, wildcards, short record
    names, or inferred field paths.  An author who wants a recursive field to
    inherit a source route must enumerate its exact root and every structural
    selector in the schema-1 convention record.
    """

    if source_proof_fidelity is None:
        return [], []
    if not isinstance(source_proof_fidelity, Mapping):
        return [], ["recursive-field source scope ledger is not an object"]
    raw_conventions = source_proof_fidelity.get("model_conventions")
    if raw_conventions is None:
        return [], []
    if not isinstance(raw_conventions, list):
        return [], [
            "recursive-field source scope ledger model_conventions must be a list"
        ]

    entries: list[dict[str, Any]] = []
    errors: list[str] = []
    convention_ids: set[str] = set()
    seen_scopes: set[tuple[str, str]] = set()
    for convention_index, raw_convention in enumerate(raw_conventions):
        if not isinstance(raw_convention, Mapping):
            continue
        convention_id = str(raw_convention.get("id") or "").strip()
        # Reject duplicate convention identities across the complete ledger,
        # rather than only among conventions that happen to carry a recursive
        # field scope.  Otherwise a duplicate convention without a scope could
        # change the semantic meaning of the scoped convention invisibly.
        if convention_id:
            if convention_id in convention_ids:
                errors.append(
                    "recursive-field source scope ledger duplicates model convention id "
                    f"`{convention_id}`"
                )
                continue
            convention_ids.add(convention_id)
        raw_scope_container = raw_convention.get(
            RECURSIVE_FIELD_SCOPE_CONTAINER_FIELD
        )
        if raw_scope_container is None:
            continue
        if not convention_id:
            errors.append(
                "recursive-field source scope convention at index "
                f"{convention_index} has no id"
            )
            continue
        for required_field in _SOURCE_RECORD_MODEL_CONVENTION_REQUIRED_FIELDS:
            if not str(raw_convention.get(required_field) or "").strip():
                errors.append(
                    "recursive-field source scope convention "
                    f"`{convention_id}` lacks `{required_field}`"
                )
        if not isinstance(raw_scope_container, Mapping):
            errors.append(
                "recursive-field source scope convention "
                f"`{convention_id}` must use an object container"
            )
            continue
        if set(raw_scope_container) != {"schema", "entries"}:
            errors.append(
                "recursive-field source scope convention "
                f"`{convention_id}` must contain exactly `schema` and `entries`"
            )
            continue
        if raw_scope_container.get("schema") != RECURSIVE_FIELD_SOURCE_SCOPE_SCHEMA:
            errors.append(
                "recursive-field source scope convention "
                f"`{convention_id}` has unsupported scope schema"
            )
            continue
        raw_entries = raw_scope_container.get("entries")
        if not isinstance(raw_entries, list) or not raw_entries:
            errors.append(
                "recursive-field source scope convention "
                f"`{convention_id}` entries must be a nonempty list"
            )
            continue
        for entry_index, raw_entry in enumerate(raw_entries):
            prefix = (
                "recursive-field source scope convention "
                f"`{convention_id}` entries[{entry_index}]"
            )
            if not isinstance(raw_entry, Mapping):
                errors.append(prefix + " must be an object")
                continue
            if set(raw_entry) != _RECURSIVE_FIELD_SCOPE_ENTRY_FIELDS:
                errors.append(
                    prefix
                    + " must contain exactly source_item, root_record, field_chain, "
                    "source_locator, and permitted_classifications"
                )
                continue
            source_item = str(raw_entry.get("source_item") or "").strip()
            root_record = semantic_contract_fully_qualified_identity(
                raw_entry.get("root_record")
            )
            source_locator = str(raw_entry.get("source_locator") or "").strip()
            if not source_item:
                errors.append(prefix + " has no exact source_item")
                continue
            if not root_record:
                errors.append(prefix + " has no fully-qualified root_record")
                continue
            if not source_locator or not EXACT_SOURCE_LOCATOR_RE.search(source_locator):
                errors.append(prefix + " has no exact source_locator")
                continue
            raw_classifications = raw_entry.get("permitted_classifications")
            if not isinstance(raw_classifications, list):
                errors.append(prefix + " permitted_classifications must be a nonempty list")
                continue
            permitted_classifications = [
                value.strip()
                for value in raw_classifications
                if isinstance(value, str) and value.strip()
            ]
            if (
                len(permitted_classifications) != len(raw_classifications)
                or not permitted_classifications
                or len(set(permitted_classifications)) != len(permitted_classifications)
            ):
                errors.append(
                    prefix
                    + " permitted_classifications must be unique nonempty strings"
                )
                continue
            raw_chain = raw_entry.get("field_chain")
            if not isinstance(raw_chain, list) or not raw_chain:
                errors.append(prefix + " field_chain must be a nonempty list")
                continue
            field_chain: list[dict[str, str]] = []
            malformed_chain = False
            for link_index, raw_link in enumerate(raw_chain):
                if (
                    not isinstance(raw_link, Mapping)
                    or set(raw_link) != _RECURSIVE_FIELD_CHAIN_LINK_FIELDS
                ):
                    errors.append(
                        prefix
                        + f" field_chain[{link_index}] must contain exactly structure and field"
                    )
                    malformed_chain = True
                    break
                structure = semantic_contract_fully_qualified_identity(
                    raw_link.get("structure")
                )
                field = str(raw_link.get("field") or "").strip()
                if not structure or not _RECURSIVE_FIELD_SELECTOR_RE.fullmatch(field):
                    errors.append(
                        prefix
                        + f" field_chain[{link_index}] has no exact fully-qualified structure/field selector"
                    )
                    malformed_chain = True
                    break
                field_chain.append({"structure": structure, "field": field})
            if malformed_chain:
                continue
            if field_chain[0]["structure"] != root_record:
                errors.append(prefix + " field_chain must start at root_record")
                continue
            normalized_scope = {
                "source_item": source_item,
                "root_record": root_record,
                "field_chain": field_chain,
                "source_locator": source_locator,
                "permitted_classifications": permitted_classifications,
            }
            scope_digest = recursive_field_source_scope_digest(normalized_scope)
            scope_key = (convention_id, scope_digest)
            if scope_key in seen_scopes:
                errors.append(prefix + " duplicates an exact convention field scope")
                continue
            seen_scopes.add(scope_key)
            entries.append(
                {
                    "convention_id": convention_id,
                    "convention_sha256": model_convention_record_digest(
                        raw_convention
                    ),
                    "convention_source_locator": str(
                        raw_convention.get("source_locator") or ""
                    ).strip(),
                    "field_scope": normalized_scope,
                    "field_scope_sha256": scope_digest,
                }
            )
    return (
        sorted(
            entries,
            key=lambda entry: (
                str(entry["convention_id"]), str(entry["field_scope_sha256"])
            ),
        ),
        sorted(set(errors)),
    )


def _recursive_field_item_index(
    field_items: list[dict[str, Any]],
    *,
    required_coordinates: set[tuple[str, str]],
) -> tuple[dict[tuple[str, str], dict[str, Any]], list[str]]:
    """Index only coordinates explicitly needed by declared field scopes.

    Recursive expansion also preserves legacy aggregate-only fields whose
    generator cannot recover an exact structural coordinate.  Those fields
    have no declared source route, so treating them as malformed source-route
    candidates would turn an unrelated legacy surface into a false audit
    failure.  A declared scope, by contrast, can match only an exact
    coordinate in ``required_coordinates``; a missing or malformed scoped
    coordinate therefore still fails closed when that scope finds no exact
    generated chain.
    """

    indexed: dict[tuple[str, str], dict[str, Any]] = {}
    errors: list[str] = []
    for index, item in enumerate(field_items):
        if not isinstance(item, dict):
            errors.append(f"recursive-field item[{index}] is not an object")
            continue
        structure = semantic_contract_fully_qualified_identity(item.get("structure"))
        field = str(item.get("field") or "").strip()
        if not structure or not _RECURSIVE_FIELD_SELECTOR_RE.fullmatch(field):
            continue
        key = (structure, field)
        if key not in required_coordinates:
            continue
        if key in indexed:
            errors.append(
                "recursive-field items duplicate exact structural coordinate "
                f"`{structure}.{field}`"
            )
            continue
        indexed[key] = item
    return indexed, errors


def recursive_field_item_structural_chain(
    item: Mapping[str, Any],
    *,
    field_index: Mapping[tuple[str, str], Mapping[str, Any]],
) -> tuple[str, list[dict[str, str]], str]:
    """Parse and validate a generated recursive path as an exact field chain."""

    raw_path = str(item.get("path") or "").strip()
    segments = [segment.strip() for segment in raw_path.split(" -> ")]
    if len(segments) < 2 or any(not segment for segment in segments):
        return "", [], "has no complete generated structural path"
    root_record = semantic_contract_fully_qualified_identity(segments[0])
    if not root_record:
        return "", [], "has a non-qualified generated root record"
    chain: list[dict[str, str]] = []
    for segment_index, segment in enumerate(segments[1:]):
        if "." not in segment:
            return "", [], "has a structural path segment without a field selector"
        structure_text, field = segment.rsplit(".", 1)
        structure = semantic_contract_fully_qualified_identity(structure_text)
        if not structure or not _RECURSIVE_FIELD_SELECTOR_RE.fullmatch(field):
            return "", [], "has a malformed structural path segment"
        chain.append({"structure": structure, "field": field})
        if segment_index == 0 and structure != root_record:
            return "", [], "does not begin with a field of its generated root record"
    expected_structure = semantic_contract_fully_qualified_identity(item.get("structure"))
    expected_field = str(item.get("field") or "").strip()
    if (
        not expected_structure
        or not _RECURSIVE_FIELD_SELECTOR_RE.fullmatch(expected_field)
        or chain[-1] != {"structure": expected_structure, "field": expected_field}
    ):
        return "", [], "does not end at its exact generated field coordinate"
    for link_index, link in enumerate(chain[:-1]):
        parent = field_index.get((link["structure"], link["field"]))
        if not isinstance(parent, Mapping):
            return "", [], "has an unindexed intermediate structural field"
        raw_nested = parent.get("nested_structures")
        if not isinstance(raw_nested, list):
            return "", [], "has an intermediate field without generated nested structure data"
        nested = {
            semantic_contract_fully_qualified_identity(value)
            for value in raw_nested
            if semantic_contract_fully_qualified_identity(value)
        }
        if chain[link_index + 1]["structure"] not in nested:
            return "", [], "has a field chain not supported by generated nesting data"
    return root_record, chain, ""


def _recursive_field_scope_source_item(
    scope: Mapping[str, Any],
    *,
    paper_statement_map: Mapping[str, Any] | None,
) -> tuple[dict[str, Any] | None, str]:
    """Resolve one explicitly named source item and its listed convention."""

    if not isinstance(paper_statement_map, Mapping):
        return None, "has no current paper statement map"
    raw_items = paper_statement_map.get("items")
    if not isinstance(raw_items, Mapping):
        return None, "paper statement map has no items object"
    field_scope = scope.get("field_scope")
    if not isinstance(field_scope, Mapping):
        return None, "has malformed parsed field scope"
    source_key = str(field_scope.get("source_item") or "").strip()
    source_item = raw_items.get(source_key)
    if not isinstance(source_item, Mapping):
        return None, f"source item `{source_key}` is not present in the current map"
    convention_id = str(scope.get("convention_id") or "").strip()
    convention_ids, reference_error = _source_record_explicit_id_list(
        source_item.get("model_convention_ids"), field="model_convention_ids"
    )
    if reference_error:
        return None, (
            f"source item `{source_key}` does not explicitly list usable model conventions"
        )
    if convention_id not in convention_ids:
        return None, (
            f"source item `{source_key}` does not explicitly list convention `{convention_id}`"
        )
    return dict(source_item), ""


def _recursive_field_direct_parent_route_candidates(
    semantic_model_items: list[dict[str, Any]],
    *,
    root_record: str,
    source_item_key: str,
    source_item: Mapping[str, Any],
    elaborated_signature_sha256_by_qualified: Mapping[str, str],
) -> list[dict[str, Any]]:
    """Return only fully pinned direct parent routes for one exact scope.

    This is deliberately a declaration/signature/record-binding join.  It
    never searches row names, binder names, short record names, source text,
    or field names to discover a parent route.
    """

    expected_source_map_digest = source_record_source_item_record_sha256(source_item)
    expected_source_semantic_digest = source_record_source_item_semantic_sha256(
        source_item, ""
    )
    candidates: list[dict[str, Any]] = []
    for semantic_item in semantic_model_items:
        if not isinstance(semantic_item, dict):
            continue
        semantic_judgment_key = str(semantic_item.get("judgment_key") or "").strip()
        if not semantic_judgment_key:
            continue
        parent_identity = semantic_item.get("reviewed_declaration_identity")
        parent_identity_key = reviewed_declaration_identity_key(parent_identity)
        parent_qualified = semantic_contract_fully_qualified_identity(
            semantic_item.get("qualified_declaration")
        )
        if parent_identity_key is None or parent_qualified != parent_identity_key[0]:
            continue
        raw_bindings = semantic_item.get("record_input_bindings")
        if not isinstance(raw_bindings, list):
            continue
        matching_bindings: list[dict[str, Any]] = []
        for raw_binding in raw_bindings:
            if not isinstance(raw_binding, Mapping):
                continue
            raw_roots = raw_binding.get("record_roots")
            if raw_roots != [root_record]:
                continue
            root_input_type = canonical_type(
                str(raw_binding.get("fully_qualified_expanded_type_canonical") or "")
            )
            if not root_input_type:
                continue
            direct_head = fully_qualified_record_input_type_surface(
                root_input_type, root_record
            )
            if direct_head != root_input_type:
                continue
            matching_bindings.append(
                {
                    "root_input_type_canonical": root_input_type,
                    "record_input_binding": dict(raw_binding),
                }
            )
        if len(matching_bindings) != 1:
            continue
        semantic_item_candidates: list[dict[str, Any]] = []
        for association_field in _RECURSIVE_FIELD_PARENT_ASSOCIATION_FIELDS:
            association = semantic_item.get(association_field)
            if not isinstance(association, Mapping):
                continue
            if association_field == "source_statement_association":
                if association.get("schema") != 2:
                    continue
                if (
                    str(association.get("association_origin") or "").strip()
                    != EXPLICIT_DIRECT_SOURCE_ROUTE_ORIGIN
                    or str(association.get("role") or "").strip()
                    != EXPLICIT_DIRECT_SOURCE_ROUTE_ROLE
                ):
                    continue
            elif association_field == "semantic_contract_source_association":
                if association.get("schema") != 2:
                    continue
                # A semantic-contract association identifies either endpoint
                # of one explicit direct/transparent-Spec pair.  Helper,
                # support, or future route roles are not source-producing
                # parents for a recursive field, even when they carry an
                # otherwise well-formed source identity.
                if (
                    str(association.get("role") or "").strip()
                    not in _RECURSIVE_FIELD_SEMANTIC_CONTRACT_PARENT_ROLES
                    or str(association.get("association_origin") or "").strip()
                ):
                    continue
            else:
                # Atom routes are the direct, source-first provenance lane
                # for one clause of a compound presentation.  They do not
                # fall back to a declaration name: require the generator's
                # exact source item, quote/atom receipt, and route record
                # before they can parent a convention-scoped record field.
                if (
                    association.get("schema") != SOURCE_CLAIM_ATOM_ASSOCIATION_SCHEMA
                    or str(association.get("association_origin") or "").strip()
                    != SOURCE_CLAIM_ATOM_ROUTE_ORIGIN
                    or str(association.get("role") or "").strip()
                    != SOURCE_CLAIM_ATOM_ROUTE_ROLE
                ):
                    continue
                association_payload = dict(association)
                supplied_full_digest = str(
                    association_payload.pop("association_sha256", "") or ""
                ).strip().lower()
                if (
                    not SHA256_RE.fullmatch(supplied_full_digest)
                    or supplied_full_digest != stable_digest(association_payload)
                ):
                    continue
                _atom_identities, atom_errors, atom_route_present = (
                    source_record_item_claim_atom_semantic_identities(semantic_item)
                )
                if atom_errors or not atom_route_present:
                    continue
                raw_atom_routes = association.get("source_claim_atom_routes")
                if not isinstance(raw_atom_routes, list) or not any(
                    isinstance(raw_atom_route, Mapping)
                    and str(raw_atom_route.get("source_key") or "").strip()
                    == source_item_key
                    and semantic_contract_fully_qualified_identity(
                        raw_atom_route.get("reviewed_lean_route")
                    )
                    == parent_identity_key[0]
                    and SHA256_RE.fullmatch(
                        str(
                            raw_atom_route.get(
                                "source_claim_atom_semantic_sha256"
                            )
                            or ""
                        )
                        .strip()
                        .lower()
                    )
                    for raw_atom_route in raw_atom_routes
                ):
                    continue
            association_identity = association.get("reviewed_declaration_identity")
            if reviewed_declaration_identity_key(association_identity) != parent_identity_key:
                continue
            raw_signature = association.get("reviewed_elaborated_signature_identity")
            if not isinstance(raw_signature, Mapping):
                continue
            signature_qualified = semantic_contract_fully_qualified_identity(
                raw_signature.get("qualified_declaration")
            )
            signature_digest = str(
                raw_signature.get("elaborated_signature_sha256") or ""
            ).strip().lower()
            expected_signature = str(
                elaborated_signature_sha256_by_qualified.get(parent_identity_key[0])
                or ""
            ).strip().lower()
            if (
                signature_qualified != parent_identity_key[0]
                or not SHA256_RE.fullmatch(signature_digest)
                or signature_digest != expected_signature
            ):
                continue
            signature = {
                "qualified_declaration": signature_qualified,
                "elaborated_signature_sha256": signature_digest,
            }
            source_identities, source_identity_errors = source_contract_source_identities(
                association.get("source_item_identities")
            )
            if source_identity_errors or len(source_identities) != 1:
                continue
            source_identity = source_identities[0]
            if (
                str(source_identity.get("source_key") or "").strip()
                != source_item_key
                or str(source_identity.get("source_map_item_sha256") or "").strip().lower()
                != expected_source_map_digest
                or str(source_identity.get("source_semantic_sha256") or "").strip().lower()
                != expected_source_semantic_digest
            ):
                continue
            expected_association_digest = semantic_source_association_digest(
                source_identities, signature
            )
            association_digest = (
                expected_association_digest
                if association_field == SOURCE_CLAIM_ATOM_ASSOCIATION_FIELD
                else str(association.get("semantic_association_sha256") or "").strip().lower()
            )
            if association_digest != expected_association_digest:
                continue
            semantic_item_candidates.append(
                {
                    "association_field": association_field,
                    "parent_semantic_model_judgment_key": semantic_judgment_key,
                    "parent_reviewed_declaration_identity": dict(parent_identity),
                    "parent_elaborated_signature_identity": signature,
                    "parent_source_association_sha256": association_digest,
                    "parent_source_association_role": str(
                        association.get("role") or ""
                    ).strip(),
                    "parent_source_association_origin": str(
                        association.get("association_origin") or ""
                    ).strip(),
                    "source_item_identities": source_identities,
                    **matching_bindings[0],
                }
            )
        if semantic_item_candidates:
            # Multiple valid lanes attached to *this same semantic-model
            # item* are redundant descriptions of one reviewed parent.  This
            # is deliberately scoped per item: duplicated semantic items,
            # even if byte-identical, are still separate parent candidates
            # and are rejected by the caller's exact-cardinality check.
            semantic_item_candidates.sort(
                key=lambda candidate: _RECURSIVE_FIELD_PARENT_ASSOCIATION_PRECEDENCE[
                    str(candidate["association_field"])
                ]
            )
            candidates.append(semantic_item_candidates[0])
    return candidates


def recursive_field_explicit_parent_route_payload(
    scope: Mapping[str, Any],
    parent_route: Mapping[str, Any],
) -> dict[str, Any]:
    """Build the receipt attached to one exact scoped recursive field."""

    field_scope = scope["field_scope"]
    assert isinstance(field_scope, Mapping)
    receipt: dict[str, Any] = {
        "schema": RECURSIVE_FIELD_EXPLICIT_PARENT_ROUTE_SCHEMA,
        "inheritance_mode": "explicit_parent_route_and_field_scope",
        "source_item": field_scope["source_item"],
        "source_item_identities": parent_route["source_item_identities"],
        "root_record": field_scope["root_record"],
        "root_input_type_canonical": parent_route["root_input_type_canonical"],
        "field_chain": field_scope["field_chain"],
        "source_locator": field_scope["source_locator"],
        "permitted_classifications": field_scope["permitted_classifications"],
        "convention_id": scope["convention_id"],
        "convention_sha256": scope["convention_sha256"],
        "field_scope_sha256": scope["field_scope_sha256"],
        "parent_association_field": parent_route["association_field"],
        "parent_semantic_model_judgment_key": parent_route[
            "parent_semantic_model_judgment_key"
        ],
        "parent_source_association_role": parent_route[
            "parent_source_association_role"
        ],
        "parent_source_association_origin": parent_route[
            "parent_source_association_origin"
        ],
        "parent_reviewed_declaration_identity": parent_route[
            "parent_reviewed_declaration_identity"
        ],
        "parent_elaborated_signature_identity": parent_route[
            "parent_elaborated_signature_identity"
        ],
        "parent_source_association_sha256": parent_route[
            "parent_source_association_sha256"
        ],
    }
    receipt["association_sha256"] = recursive_field_source_scope_digest(receipt)
    return receipt


def recursive_field_scope_classification_error(
    scope: Mapping[str, Any], field_item: Mapping[str, Any]
) -> str:
    """Return the structural classification error for one matched scope.

    A scope for a generated nested-record field is intentionally a container
    receipt, not an implicit source route for every leaf below it.  Conversely,
    a proposition/data leaf cannot receive a container classification merely
    because a similarly named field elsewhere has nested children.  This uses
    only the generated ``nested_structures`` relation and the exact scoped
    coordinate, never a field-name heuristic.
    """

    field_scope = scope.get("field_scope")
    if not isinstance(field_scope, Mapping):
        return "has malformed parsed field scope"
    raw_permitted = field_scope.get("permitted_classifications")
    if not isinstance(raw_permitted, list):
        return "has malformed permitted classifications"
    permitted = [str(value).strip() for value in raw_permitted]
    raw_nested = field_item.get("nested_structures")
    if not isinstance(raw_nested, list):
        return "matches a generated field without nested-structure data"
    has_nested_record = any(str(value or "").strip() for value in raw_nested)
    if has_nested_record:
        if permitted != ["container_recursively_audited"]:
            return (
                "matches a generated nested-record field, so its permitted "
                "classifications must be exactly [container_recursively_audited]"
            )
        return ""
    if "container_recursively_audited" in permitted:
        return (
            "matches a generated non-container leaf, which cannot permit "
            "container_recursively_audited"
        )
    return ""


def attach_recursive_field_explicit_parent_route_associations(
    *,
    field_items: list[dict[str, Any]],
    semantic_model_items: list[dict[str, Any]],
    paper_statement_map: Mapping[str, Any] | None,
    source_proof_fidelity: Mapping[str, Any] | None,
    elaborated_signature_sha256_by_qualified: Mapping[str, str],
) -> tuple[list[str], dict[str, int]]:
    """Attach only exact convention-scoped source routes to recursive fields.

    A scope is useful only when one current field path, one current direct
    parent route, one exact record-input binding, and one convention explicitly
    listed by the selected source item all agree.  Every other field remains
    aggregate-only; no source route is inherited through a container.
    """

    scopes, errors = recursive_field_source_scope_entries(source_proof_fidelity)
    counts = {
        "recursive_field_source_scope_count": len(scopes),
        "recursive_field_scope_source_item_count": 0,
        "recursive_field_scope_association_count": 0,
    }
    if not scopes:
        return errors, counts
    required_coordinates = {
        (str(link["structure"]), str(link["field"]))
        for scope in scopes
        for link in scope["field_scope"]["field_chain"]
    }
    field_index, index_errors = _recursive_field_item_index(
        field_items,
        required_coordinates=required_coordinates,
    )
    errors.extend(index_errors)
    parsed_paths: dict[int, tuple[str, list[dict[str, str]], str]] = {}
    assigned_field_ids: set[int] = set()
    for scope in scopes:
        field_scope = scope["field_scope"]
        assert isinstance(field_scope, Mapping)
        convention_id = str(scope["convention_id"])
        scope_label = (
            f"recursive-field source scope `{convention_id}`/"
            f"`{field_scope['source_item']}`"
        )
        source_item, source_item_error = _recursive_field_scope_source_item(
            scope, paper_statement_map=paper_statement_map
        )
        if source_item_error:
            errors.append(scope_label + " " + source_item_error)
            continue
        anchor_error = _recursive_field_scope_locator_anchor_error(
            scope, source_item
        )
        if anchor_error:
            errors.append(scope_label + " " + anchor_error)
            continue
        counts["recursive_field_scope_source_item_count"] += 1
        matching_fields: list[dict[str, Any]] = []
        for field_item in field_items:
            if not isinstance(field_item, dict):
                continue
            cache_key = id(field_item)
            parsed = parsed_paths.get(cache_key)
            if parsed is None:
                parsed = recursive_field_item_structural_chain(
                    field_item, field_index=field_index
                )
                parsed_paths[cache_key] = parsed
            root_record, field_chain, path_error = parsed
            if path_error:
                continue
            if (
                root_record == field_scope["root_record"]
                and field_chain == field_scope["field_chain"]
            ):
                matching_fields.append(field_item)
        if len(matching_fields) != 1:
            errors.append(
                scope_label
                + " has "
                + str(len(matching_fields))
                + " generated fields with its exact root/field chain"
            )
            continue
        field_item = matching_fields[0]
        classification_error = recursive_field_scope_classification_error(
            scope, field_item
        )
        if classification_error:
            errors.append(scope_label + " " + classification_error)
            continue
        candidates = _recursive_field_direct_parent_route_candidates(
            semantic_model_items,
            root_record=str(field_scope["root_record"]),
            source_item_key=str(field_scope["source_item"]),
            source_item=source_item,
            elaborated_signature_sha256_by_qualified=(
                elaborated_signature_sha256_by_qualified
            ),
        )
        if len(candidates) != 1:
            errors.append(
                scope_label
                + " has "
                + str(len(candidates))
                + " exact current direct parent routes"
            )
            continue
        if id(field_item) in assigned_field_ids or isinstance(
            field_item.get(RECURSIVE_FIELD_EXPLICIT_PARENT_ROUTE_FIELD), Mapping
        ):
            errors.append(
                scope_label
                + " would attach a second explicit parent route to one field"
            )
            continue
        field_item[RECURSIVE_FIELD_EXPLICIT_PARENT_ROUTE_FIELD] = (
            recursive_field_explicit_parent_route_payload(scope, candidates[0])
        )
        assigned_field_ids.add(id(field_item))
        counts["recursive_field_scope_association_count"] += 1
    return sorted(set(errors)), counts


def fully_qualified_record_input_type_surface(
    expanded_type: str, record_root: str
) -> str:
    """Qualify a direct generated record input without a suffix lookup.

    The source-level semantic surface keeps local display spelling so a human
    can read it, while Lean's expanded `#check` surface writes the record head
    fully qualified.  A binding may bridge those two representations only when
    its generated root is the direct outer constructor.  We never rewrite an
    already-qualified different root or search for a same-suffix declaration.
    """

    normalized = normalize_ws(expanded_type)
    match = re.match(
        r"^(@?)([A-Za-z_][A-Za-z0-9_']*(?:\.[A-Za-z_][A-Za-z0-9_']*)*)",
        normalized,
    )
    if match is None:
        return ""
    at_prefix, head = match.groups()
    if head == record_root:
        return canonical_type(normalized)
    if "." in head or head != record_root.rsplit(".", 1)[-1]:
        return ""
    return canonical_type(
        at_prefix + record_root + normalized[match.end() :]
    )


def fully_qualified_record_input_type_from_elaborated_binder(
    *,
    visible_inputs: list[dict[str, str]],
    visible_input_index: int,
    manifest: Mapping[str, Any] | None,
    reviewed_declaration: str,
    record_root: str,
    structure_aliases: Mapping[str, str],
) -> str:
    """Resolve a record alias only through its exact Lean binder graph.

    Source parsing may identify a reducible type alias as a record occurrence,
    but that parser result is only a routing candidate.  The canonical binding
    below is emitted only when the exact positional binder atom names a fully
    qualified alias and Lean's complete statement-dependency graph has one
    structural route from that alias to the generated record root.  Declaration
    spellings are graph coordinates; the authenticated atom identity, node
    identities, and graph topology supply the evidence.
    """

    if not isinstance(manifest, Mapping):
        return ""
    atom_groups, atom_errors = elaborated_visible_input_binder_atom_groups(
        visible_inputs=visible_inputs,
        manifest=manifest,
    )
    raw_atoms = atom_groups.get(visible_input_index)
    if atom_errors or not raw_atoms:
        return ""
    displays = {
        canonical_type(str(atom.get("display") or ""))
        for atom in raw_atoms
        if str(atom.get("display") or "").strip()
    }
    if len(displays) != 1:
        return ""
    display = next(iter(displays))
    head_match = re.match(
        r"^(\(*\s*)(@?)([A-Za-z_][A-Za-z0-9_']*(?:\.[A-Za-z_][A-Za-z0-9_']*)*)",
        display,
    )
    if head_match is None:
        return ""
    alias = head_match.group(3)
    if "." not in alias or structure_aliases.get(alias) != record_root:
        return ""

    graph = normalize_semantic_dependency_graph(
        manifest.get("semantic_dependency_graph")
    )
    if (
        not isinstance(graph, Mapping)
        or graph.get("complete") is not True
        or str(graph.get("root_declaration") or "").strip()
        != reviewed_declaration
    ):
        return ""
    raw_nodes = graph.get("nodes")
    raw_edges = graph.get("edges")
    if not isinstance(raw_nodes, list) or not isinstance(raw_edges, list):
        return ""
    nodes = {
        str(node.get("declaration") or "").strip()
        for node in raw_nodes
        if isinstance(node, Mapping)
        and str(node.get("declaration") or "").strip()
    }
    if not {reviewed_declaration, alias, record_root}.issubset(nodes):
        return ""
    semantic_adjacency: dict[str, set[str]] = {}
    for edge in raw_edges:
        if not isinstance(edge, Mapping):
            return ""
        source = str(edge.get("source") or "").strip()
        target = str(edge.get("target") or "").strip()
        role = str(edge.get("role") or "").strip()
        if (
            source in nodes
            and target in nodes
            and role in {"type_uses_constant", "value_uses_constant"}
        ):
            semantic_adjacency.setdefault(source, set()).add(target)

    def has_unique_path(
        start: str, target: str, allowed_nodes: set[str]
    ) -> bool:
        """Count at most two simple paths after pruning dead graph branches."""

        if start not in allowed_nodes or target not in allowed_nodes:
            return False
        reverse: dict[str, set[str]] = {}
        for source, targets in semantic_adjacency.items():
            if source not in allowed_nodes:
                continue
            for child in targets:
                if child in allowed_nodes:
                    reverse.setdefault(child, set()).add(source)
        can_reach_target = {target}
        pending = [target]
        while pending:
            current = pending.pop()
            for parent in reverse.get(current, set()):
                if parent not in can_reach_target:
                    can_reach_target.add(parent)
                    pending.append(parent)
        if start not in can_reach_target:
            return False

        path_count = 0

        def visit(current: str, seen: frozenset[str]) -> None:
            nonlocal path_count
            if path_count > 1:
                return
            if current == target:
                path_count += 1
                return
            for child in sorted(semantic_adjacency.get(current, set())):
                if child in can_reach_target and child not in seen:
                    visit(child, seen | {child})

        visit(start, frozenset({start}))
        return path_count == 1

    # A theorem may expose a binder through a transparent Spec, so the exact
    # positional alias need not be a direct child of the reviewed declaration.
    # The degenerate case in which the reviewed declaration is that alias is
    # the unique zero-edge path.
    if not has_unique_path(reviewed_declaration, alias, nodes):
        return ""

    route_nodes = {
        candidate
        for candidate, target in structure_aliases.items()
        if target == record_root and candidate in nodes
    } | {record_root}
    if not has_unique_path(alias, record_root, route_nodes):
        return ""
    resolved = canonical_type(
        head_match.group(1)
        + head_match.group(2)
        + record_root
        + display[head_match.end() :]
    )
    return (
        resolved
        if fully_qualified_record_input_type_surface(resolved, record_root)
        == resolved
        else ""
    )


def semantic_model_audit_items(
    *,
    row_names: list[str],
    declarations: dict[str, str],
    row_inputs: dict[str, list[dict[str, str]]],
    row_records: dict[str, list[str]],
    fields_by_root: dict[str, list[FieldInfo]],
    proposition_aliases: dict[str, PropositionAliasInfo],
    dimensions: list[str],
    type_aliases: dict[str, TypeAliasInfo] | None = None,
    structures: dict[str, StructureInfo] | None = None,
    structure_aliases: dict[str, str] | None = None,
    row_qualified_names: dict[str, str] | None = None,
    semantic_declarations: list[LocalDeclaration] | None = None,
    elaborated_signature_manifests: Mapping[str, Mapping[str, Any]] | None = None,
    review_surfaces: Mapping[str, SemanticModelReviewSurface] | None = None,
) -> list[dict[str, Any]]:
    """Create name-invariant source-model comparison obligations per row.

    This is intentionally not a theorem-name classifier. It records the
    expanded binder and result types, a bounded transparent terminal-term
    dependency closure, and recursively reached model-field types for a
    human/LLM semantic comparison. The baseline dimensions force reviewers to
    answer the support, joint-law, extended-rate, and carrier questions even
    when wrappers make those facts visually disappear from the top-level row.
    Schema-2 rows trigger conditioning/null-cell review only when the terminal
    closure reaches a conditioning or partition construct, and expectation
    review only when it reaches an integration or expectation construct.
    Opaque or incomplete local type/term paths remain fail-closed for all
    three dimensions.
    """

    items: list[dict[str, Any]] = []
    structures = structures or {}
    structure_aliases = structure_aliases or {}
    row_qualified_names = row_qualified_names or {}
    semantic_declarations = semantic_declarations or []
    elaborated_signature_manifests = elaborated_signature_manifests or {}
    review_surfaces = review_surfaces or {}
    (
        terminal_term_declaration_index,
        terminal_term_short_name_index,
    ) = semantic_model_local_declaration_indexes(semantic_declarations)
    terminal_term_definition_analysis_cache: dict[str, dict[str, Any]] = {}
    candidate_structures = set(structures)
    candidate_structure_parameter_counts = structure_parameter_counts(structures)
    for row in row_names:
        reviewed_qualified_name = row_qualified_names.get(row, row)
        review_surface = review_surfaces.get(row)
        if review_surface is None:
            review_surface = semantic_model_review_effective_surface(
                reviewed_qualified_name=reviewed_qualified_name,
                reviewed_declaration=declarations[row],
                semantic_declarations=semantic_declarations,
            )
        # Keep a direct review declaration's caller-provided parsed inputs for
        # backwards-compatible callers and fixtures.  A resolved transparent
        # alias, however, must be audited through the target declaration: its
        # wrapper has intentionally empty binders and no terminal formula.
        use_effective_surface = review_surface.uses_effective_target
        analysis_declaration = review_surface.analysis_declaration
        analysis_qualified_name = review_surface.analysis_qualified_name
        analysis_row_inputs = (
            review_surface.visible_inputs
            if use_effective_surface
            else row_inputs.get(row, [])
        )
        analysis_manifest = elaborated_signature_manifests.get(
            analysis_qualified_name
        )
        (
            visible_input_binder_atoms,
            _visible_input_binder_atom_errors,
        ) = elaborated_visible_input_binder_atom_receipts(
            visible_inputs=analysis_row_inputs,
            manifest=analysis_manifest,
        )
        context_namespace = (
            analysis_qualified_name.rsplit(".", 1)[0]
            if "." in analysis_qualified_name
            else ""
        )
        analysis_row_records = set(row_records.get(row, []))
        if use_effective_surface:
            analysis_row_records = set(
                mentioned_structures_in_scoped_inputs(
                    analysis_row_inputs,
                    candidate_structures,
                    structure_aliases,
                    context_namespace=context_namespace,
                    structure_parameter_counts=candidate_structure_parameter_counts,
                )
            )
        binder_domains: list[dict[str, str]] = []
        # Keep the per-input surface alongside the aggregate binder list.  A
        # record root alone is not enough to identify a model premise: the
        # instantiated parameters of `Model ...` are part of the audited
        # condition.  The later `record_input_bindings` projection retains
        # this exact generated surface for provenance consumers.
        input_surfaces: list[dict[str, str] | None] = []
        row_bound_names: set[str] = set()
        row_measure_kernel_carrier_names: set[str] = set()
        for visible_input in analysis_row_inputs:
            input_binder_names = binder_names(
                str(visible_input.get("names") or "")
            )
            input_type = str(visible_input.get("type") or "")
            if input_type.strip():
                input_surface = semantic_model_surface_type(
                    input_type,
                    proposition_aliases,
                    type_aliases,
                    context_namespace=context_namespace,
                    bound_names=row_bound_names,
                )
                binder_domains.append(input_surface)
                input_surfaces.append(input_surface)
                if semantic_model_standard_measure_kernel_carrier_type(
                    input_surface["expanded_type"]
                ):
                    row_measure_kernel_carrier_names.update(input_binder_names)
            else:
                input_surfaces.append(None)
            row_bound_names.update(input_binder_names)
        terminal_result_text, terminal_result_origin = (
            semantic_model_terminal_result_surface(analysis_declaration)
        )
        terminal_result_receipt = elaborated_terminal_result_receipt(
            analysis_manifest
        )
        elaborated_type_value = elaborated_type_valued_result_display(
            terminal_result_receipt
        )
        if elaborated_type_value:
            terminal_result_text = elaborated_type_value
            terminal_result_origin = "elaborated_type_valued_definition"
        terminal_result = semantic_model_surface_type(
            terminal_result_text,
            proposition_aliases,
            type_aliases,
            context_namespace=context_namespace,
            bound_names=row_bound_names,
        )
        terminal_term_dependency_surface = (
            semantic_model_terminal_term_dependency_surface(
                terminal_result_text,
                semantic_declarations,
                proposition_aliases,
                type_aliases,
                context_namespace=context_namespace,
                initial_bound_names=row_bound_names,
                initial_measure_kernel_carrier_names=(
                    row_measure_kernel_carrier_names
                ),
                declaration_index=terminal_term_declaration_index,
                short_name_index=terminal_term_short_name_index,
                definition_analysis_cache=terminal_term_definition_analysis_cache,
            )
        )
        reached_fields: list[FieldInfo] = []
        seen_fields: set[tuple[str, str, str]] = set()
        record_roots = set(analysis_row_records)
        record_input_bindings: list[dict[str, Any]] = []
        for input_index, visible_input in enumerate(analysis_row_inputs):
            input_binder_names = binder_names(str(visible_input.get("names") or ""))
            input_record_roots = mentioned_structures_in_scoped_inputs(
                [visible_input],
                candidate_structures,
                structure_aliases,
                context_namespace=context_namespace,
                structure_parameter_counts=candidate_structure_parameter_counts,
            )
            input_surface = input_surfaces[input_index]
            if input_binder_names and input_record_roots and input_surface is not None:
                fully_qualified_type = ""
                if len(input_record_roots) == 1:
                    fully_qualified_type = fully_qualified_record_input_type_surface(
                        input_surface["expanded_type"], input_record_roots[0]
                    )
                    if not fully_qualified_type:
                        fully_qualified_type = (
                            fully_qualified_record_input_type_from_elaborated_binder(
                                visible_inputs=analysis_row_inputs,
                                visible_input_index=input_index,
                                manifest=analysis_manifest,
                                reviewed_declaration=analysis_qualified_name,
                                record_root=input_record_roots[0],
                                structure_aliases=structure_aliases,
                            )
                        )
                binding: dict[str, Any] = {
                    "binder_names": sorted(input_binder_names),
                    "record_roots": input_record_roots,
                    # This is deliberately more specific than a root
                    # identity.  `source_type_canonical` rejects a record
                    # at the wrong index/parameter, while the expanded
                    # pair binds that source spelling to the generated
                    # semantic surface and the current elaborated review
                    # signature.
                    "source_type_canonical": canonical_type(
                        str(visible_input.get("type") or "")
                    ),
                    "expanded_type": input_surface["expanded_type"],
                    "alpha_normalized_type": input_surface[
                        "alpha_normalized_type"
                    ],
                    "fully_qualified_expanded_type_canonical": fully_qualified_type,
                }
                # The legacy display names remain available for ordinary
                # human-facing diagnostics.  Operational outcome-domain
                # routing consumes only this atom receipt.
                binder_atoms = visible_input_binder_atoms.get(input_index)
                if binder_atoms is not None:
                    binding["elaborated_outer_binder_atoms"] = binder_atoms
                record_input_bindings.append(binding)
        # A model record can occur only in an existential/result quantifier.
        # It is still part of the source theorem's carrier and must contribute
        # its fields and parameter domains to the semantic comparison.
        if candidate_structures:
            record_roots.update(
                mentioned_structures(
                    terminal_result_text,
                    candidate_structures,
                    structure_aliases,
                    context_namespace=context_namespace,
                    structure_parameter_counts=candidate_structure_parameter_counts,
                )
            )
        for record in sorted(record_roots):
            root_fields = fields_by_root.get(record)
            if root_fields is None and record in structures:
                root_fields, _ = recursively_collect_fields(
                    record,
                    structures,
                    candidate_structures,
                    structure_aliases,
                    max_depth=4,
                )
            for field in root_fields or []:
                key = (field.structure, field.field, field.type)
                if key not in seen_fields:
                    seen_fields.add(key)
                    reached_fields.append(field)
        ordered_reached_fields = sorted(
            reached_fields,
            key=lambda item: (item.path, item.structure, item.field, item.type),
        )
        record_fields = [
            {
                "path": field.path,
                **semantic_model_surface_type(
                    field.type,
                    proposition_aliases,
                    type_aliases,
                    context_namespace=(
                        field.structure.rsplit(".", 1)[0]
                        if "." in field.structure
                        else ""
                    ),
                    bound_names=(
                        set(structures[field.structure].parameters)
                        if field.structure in structures
                        else set()
                    ),
                ),
            }
            for field in ordered_reached_fields
        ]
        reached_structures = set(record_roots)
        reached_structures.update(field.structure for field in reached_fields)
        record_parameters: list[dict[str, str]] = []
        for structure_name in sorted(reached_structures):
            structure = structures.get(structure_name)
            if structure is None:
                continue
            parameter_bound_names: set[str] = set()
            for parameter, parameter_type in sorted(structure.parameter_types.items()):
                record_parameters.append(
                    {
                        "structure": structure_name,
                        "parameter": parameter,
                        **semantic_model_surface_type(
                            parameter_type,
                            proposition_aliases,
                            type_aliases,
                            context_namespace=(
                                structure_name.rsplit(".", 1)[0]
                                if "." in structure_name
                                else ""
                            ),
                            bound_names=parameter_bound_names,
                        ),
                    }
                )
                parameter_bound_names.add(parameter)
        typed_surfaces = [
            (surface["expanded_type"], context_namespace)
            for surface in binder_domains
        ]
        typed_surfaces.append((terminal_result["expanded_type"], context_namespace))
        typed_surfaces.extend(
            (
                surface["expanded_type"],
                field.structure.rsplit(".", 1)[0]
                if "." in field.structure
                else "",
            )
            for field, surface in zip(ordered_reached_fields, record_fields)
        )
        typed_surfaces.extend(
            (
                surface["expanded_type"],
                str(surface.get("structure") or "").rsplit(".", 1)[0]
                if "." in str(surface.get("structure") or "")
                else "",
            )
            for surface in record_parameters
        )
        unexpanded_local_type_heads = semantic_model_unexpanded_local_type_heads(
            typed_surfaces, semantic_declarations
        )
        elaborated_execution_shape = (
            semantic_model_aggregate_execution_state_refinement_shape(
                manifest
                for declaration in sorted(
                    {reviewed_qualified_name, *reached_structures}
                )
                if isinstance(
                    (manifest := elaborated_signature_manifests.get(declaration)),
                    Mapping,
                )
            )
        )
        flags = semantic_model_feature_flags(
            binder_domains,
            terminal_result,
            record_fields,
            record_parameters,
            unexpanded_local_type_heads,
            terminal_term_dependency_surface,
            {
                "elaborated_execution_state_refinement_shape": (
                    elaborated_execution_shape
                )
            },
        )
        flags["type_valued_result"] = bool(
            isinstance(terminal_result_receipt, Mapping)
            and terminal_result_receipt.get("type_valued_definition") is True
        )
        dimension_items: list[dict[str, Any]] = []
        for dimension in dimensions:
            detected = {
                "expanded_binders_and_domain": True,
                "carrier_and_domain": flags["generic_or_restricted_carrier"],
                "probability_support_endpoints": flags[
                    "finite_or_ordered_probability_domain"
                ],
                # An opaque local carrier can conceal a PMF, measure, or kernel.
                # Treat it as a law surface until a checked refinement says
                # otherwise; a declaration name must not decide that question.
                "joint_law_and_state_evolution": flags[
                    "probabilistic_model"
                ] or flags["unexpanded_local_type_surface"] or flags[
                    "unexpanded_local_term_surface"
                ] or flags["elaborated_execution_state_refinement_surface"] or flags[
                    "elaborated_execution_state_refinement_scan_incomplete"
                ],
                "conditioning_and_calibration_semantics": flags[
                    "conditioning_and_calibration_semantics"
                ],
                "expectation_definedness": flags["expectation_definedness"],
                "null_cell_totalization_and_partition_scope": flags[
                    "null_cell_totalization_and_partition_scope"
                ],
                "extended_rate_codomain": flags["extended_rate_codomain"],
            }[dimension]
            requires_checked_bridge = dimension in {
                "probability_support_endpoints",
                "joint_law_and_state_evolution",
                "conditioning_and_calibration_semantics",
                "expectation_definedness",
                "null_cell_totalization_and_partition_scope",
                "extended_rate_codomain",
            } or (
                dimension == "carrier_and_domain"
                and flags["generic_or_restricted_carrier"]
            )
            dimension_items.append(
                {
                    "id": dimension,
                    "detected_from_expanded_surface": detected,
                    "expanded_shape_basis": semantic_model_dimension_shape_basis(
                        dimension, flags
                    ),
                    "required_check": SEMANTIC_MODEL_DIMENSION_CHECKS[dimension],
                    "requires_checked_bridge_when_detected": requires_checked_bridge,
                    "requires_parameter_translation_when_detected": (
                        dimension == "carrier_and_domain"
                        and flags["nontrivial_finite_index_expression"]
                    ),
                    "requires_cardinality_boundary_analysis_when_detected": (
                        dimension == "carrier_and_domain" and flags["finite_carrier"]
                    ),
                    "requires_transformed_law_analysis_when_detected": (
                        dimension == "joint_law_and_state_evolution"
                        and (
                            flags["probabilistic_model"]
                            or flags["unexpanded_local_type_surface"]
                            or flags["unexpanded_local_term_surface"]
                        )
                    ),
                    "requires_distribution_parameterization_analysis_when_detected": (
                        dimension == "joint_law_and_state_evolution"
                        and (
                            flags["probabilistic_model"]
                            or flags["unexpanded_local_type_surface"]
                            or flags["unexpanded_local_term_surface"]
                        )
                    ),
                    "requires_source_carrier_coherence_analysis_when_detected": (
                        dimension == "joint_law_and_state_evolution"
                        and detected
                        and flags[
                            "measure_kernel_carrier_transport_construct"
                        ]
                    ),
                }
            )
        items.append(
            {
                "row": row,
                "qualified_declaration": reviewed_qualified_name,
                **(
                    {
                        "reviewed_declaration_identity": identity,
                    }
                    if (
                        identity := reviewed_declaration_identity(
                            reviewed_qualified_name, declarations[row]
                        )
                    )
                    is not None
                    else {}
                ),
                "kind": "semantic_model_comparison",
                "judgment_key": f"semantic-model::{row}",
                "lean_source_declaration": declarations[row],
                "effective_lean_source_declaration": analysis_declaration,
                "expanded_lean_surface": {
                    "review_alias_expansion": review_surface.review_alias_expansion,
                    "binder_domains": binder_domains,
                    "terminal_result": terminal_result,
                    "terminal_result_origin": terminal_result_origin,
                    "elaborated_terminal_result_receipt": (
                        terminal_result_receipt
                    ),
                    "record_roots": sorted(record_roots),
                    "record_parameter_types": record_parameters,
                    "record_field_types": record_fields,
                    "unexpanded_local_type_heads": unexpanded_local_type_heads,
                    "terminal_term_dependency_surface": terminal_term_dependency_surface,
                    "elaborated_execution_state_refinement_shape": (
                        elaborated_execution_shape
                    ),
                },
                "record_input_bindings": record_input_bindings,
                "semantic_shape_flags": flags,
                "dimensions": dimension_items,
                "required_check": (
                    "Judge the listed dimensions from the expanded Lean surface and the "
                    "pinned source text, including transparent type aliases, record "
                    "parameter domains, result-only model records, and the bounded terminal "
                    "definition dependency surface. Treat any listed local "
                    "opaque/constant/axiom type head as requiring a checked carrier/refinement "
                    "bridge before it is ordinary model data. Treat every opaque, ambiguous, "
                    "tactic-body, or bounded terminal term path as requiring a checked semantic "
                    "bridge before it is treated as an ordinary numeric or propositional result. "
                    "Do not infer a source model from any local Lean name. For every dimension, record a source locator, a concrete semantic "
                    "comparison, and Lean evidence; a detected support, joint-law/state-evolution, "
                    "conditioning/calibration, expectation-definedness, null-cell/partition, or "
                    "extended-rate shape also needs a checked bridge declaration or constructor "
                    "route. For every detected probability-law surface, explicitly compare "
                    "the source and Lean parameterizations rather than merely saying their "
                    "parameters are positively related: state both scale/rate/variance "
                    "conventions, the translation formula, and a checked law or outcome bridge."
                    " When the generated joint-law dimension requests source-carrier "
                    "coherence analysis, identify the source and Lean random-variable "
                    "carriers, explain why stagewise clocks are one joint source draw (or "
                    "a source-defined kernel composition) rather than resampling, classify "
                    "the measure transport, and record any all-rate family bridge. "
                    "When the Lean-elaborated surface lists a ReflTransGen execution path "
                    "and relation-valued state transition, identify the literal source "
                    "executor, its initial/terminal states, and its transition relation, "
                    "then provide a checked construction, simulation, or refinement from "
                    "the source primitives. A caller-supplied trace or refinement package "
                    "is not that bridge."
                ),
            }
        )
    return items


def semantic_model_item_has_explicit_source_route(item: Mapping[str, Any]) -> bool:
    """Whether one generated model item is tied to a selected source route.

    The association is generated from exact source-map routing and declaration
    identity.  This deliberately avoids using its row label, local record
    name, or the spelling of a Lean theorem as a source-facing signal.
    """

    for field, roles in (
        (
            STATEMENT_SOURCE_COMPONENT_ASSOCIATION_FIELD,
            {STATEMENT_SOURCE_COMPONENT_ASSOCIATION_ROLE},
        ),
        (
            "source_statement_association",
            {EXPLICIT_DIRECT_SOURCE_ROUTE_ROLE},
        ),
        (
            SOURCE_CLAIM_ATOM_ASSOCIATION_FIELD,
            {SOURCE_CLAIM_ATOM_ROUTE_ROLE},
        ),
        (
            "semantic_contract_source_association",
            {"direct_evidence", "transparent_spec"},
        ),
    ):
        association = item.get(field)
        if not isinstance(association, Mapping):
            continue
        if association.get("role") not in roles:
            continue
        source_items = association.get("source_item_identities")
        if isinstance(source_items, list) and source_items:
            return True
    return False


def semantic_model_item_has_execution_state_refinement_surface(
    item: Mapping[str, Any],
) -> bool:
    """Read the generated Lean-elaborated process trigger from one item."""

    flags = item.get("semantic_shape_flags")
    return bool(
        isinstance(flags, Mapping)
        and (
            flags.get("elaborated_execution_state_refinement_surface") is True
            or flags.get(
                "elaborated_execution_state_refinement_scan_incomplete"
            )
            is True
        )
    )


def semantic_model_dimension_configuration_errors(
    semantic_model_items: list[dict[str, Any]], dimensions: list[str]
) -> list[str]:
    """Reject missing model dimensions for source-routed semantic surfaces.

    The direct-route receipt is generated from the source map and elaborated
    declaration identity. It is therefore the semantic requirement signal;
    an empty local configuration must not turn that requirement into a
    vacuous review. Rows without such a generated source route remain outside
    this opt-in lane until a paper explicitly enables it.
    """

    required_rows: list[str] = []
    execution_state_refinement_rows: list[str] = []
    for item in semantic_model_items:
        if not semantic_model_item_has_explicit_source_route(item):
            continue
        row = str(item.get("row") or item.get("judgment_key") or "unknown")
        required_rows.append(row)
        if semantic_model_item_has_execution_state_refinement_surface(item):
            execution_state_refinement_rows.append(row)

    errors: list[str] = []
    if required_rows and not dimensions:
        errors.append(
            "explicit source-routed semantic-model item(s) require "
            "review_surface.semantic_model_review schema 2 with every requested "
            "dimension; no semantic dimensions were configured: "
            + ", ".join(sorted(set(required_rows)))
        )
    if (
        execution_state_refinement_rows
        and "joint_law_and_state_evolution" not in dimensions
    ):
        errors.append(
            "source-routed Lean-elaborated execution/state-refinement item(s) "
            "contain a ReflTransGen path and relation-valued state transition, "
            "so review_surface.semantic_model_review must require "
            "joint_law_and_state_evolution: "
            + ", ".join(sorted(set(execution_state_refinement_rows)))
        )
    return errors


def recursively_collect_fields(
    root_structure: str,
    structures: dict[str, StructureInfo],
    candidate_structures: set[str],
    aliases: dict[str, str],
    max_depth: int,
    *,
    proposition_heads: set[str] | None = None,
    data_heads: set[str] | None = None,
) -> tuple[list[FieldInfo], list[RecursionFailure]]:
    collected: list[FieldInfo] = []
    failures: list[RecursionFailure] = []
    seen: set[tuple[str, str]] = set()
    expanded: set[str] = set()
    candidate_structure_parameter_counts = structure_parameter_counts(structures)

    def walk(structure_name: str, prefix: list[str], stack: list[str], depth: int) -> None:
        if depth > max_depth:
            failures.append(
                RecursionFailure(
                    kind="max_depth",
                    structure=structure_name,
                    path=" -> ".join(prefix),
                    message=f"recursive source-record expansion exceeded max depth {max_depth}",
                )
            )
            return
        structure = structures.get(structure_name)
        if structure is None:
            failures.append(
                RecursionFailure(
                    kind="missing_structure",
                    structure=structure_name,
                    path=" -> ".join(prefix),
                    message="source-shaped nested structure was mentioned but not parsed from paper-local or selected library Lean files",
                )
            )
            return
        if structure.kind == "inductive" and structure.unreconciled_constructor_slots:
            failures.append(
                RecursionFailure(
                    kind="unreconciled_inductive_constructor_slots",
                    structure=structure_name,
                    path=" -> ".join(prefix),
                    message=(
                        "inductive constructor slot mapping is ambiguous until Lean "
                        "reconciles its stored fields: "
                        + "; ".join(
                            f"{constructor}: {reason}"
                            for constructor, reason in sorted(
                                structure.unreconciled_constructor_slots.items()
                            )
                        )
                    ),
                )
            )
            return
        if not structure.fields:
            if structure.kind == "inductive" and structure.constructor_count:
                # A constructor-only enum is ordinary data. Its constructors
                # have been enumerated and none accepts a proposition-bearing
                # or otherwise non-data argument.
                expanded.add(structure_name)
                return
            failures.append(
                RecursionFailure(
                    kind=(
                        "empty_or_unparsed_inductive"
                        if structure.kind == "inductive"
                        else "empty_structure"
                    ),
                    structure=structure_name,
                    path=" -> ".join(prefix),
                    message=(
                        "inductive type has no parsed constructor arguments or constructors; "
                        "an empty/unparsed inductive premise can provide ex-falso evidence"
                        if structure.kind == "inductive"
                        else "source-shaped nested structure has no parsed fields, so recursion cannot reach primitive source assumptions"
                    ),
                )
            )
            return
        if structure_name in expanded:
            return
        expanded.add(structure_name)
        shadowed_fields = set(structure.parameters)
        for raw_field in structure.fields:
            field_namespace = (
                raw_field.structure.rsplit(".", 1)[0]
                if "." in raw_field.structure
                else ""
            )
            nested = mentioned_structures(
                raw_field.type,
                candidate_structures,
                aliases,
                context_namespace=field_namespace,
                shadowed_names=shadowed_fields,
                structure_parameter_counts=candidate_structure_parameter_counts,
            )
            # Do not infer a recursive source-record obligation from a spelling
            # such as `Model` or `Certificate`. A parsed structure is expanded
            # above; an unparsed unknown field remains on the direct auditable
            # surface below and is fail-closed as nondata where it feeds a row.
            field = FieldInfo(
                structure=raw_field.structure,
                field=raw_field.field,
                type=raw_field.type,
                path=" -> ".join(prefix + [raw_field.path]),
                line=raw_field.line,
                source_file=raw_field.source_file,
                nested_structures=nested,
                risk_terms=field_risk_terms(raw_field),
                constructor_fqn=raw_field.constructor_fqn,
                constructor_argument_index=raw_field.constructor_argument_index,
                projection_fqn=raw_field.projection_fqn,
            )
            key = (field.structure, field.field)
            if key not in seen:
                seen.add(key)
                collected.append(field)
            for nested_structure in nested:
                if nested_structure == structure_name:
                    continue
                if nested_structure in stack:
                    failures.append(
                        RecursionFailure(
                            kind="cycle",
                            structure=nested_structure,
                            path=" -> ".join(prefix + [raw_field.path, nested_structure]),
                            message="recursive source-record expansion found a cycle before reaching primitive source assumptions",
                        )
                    )
                    continue
                walk(nested_structure, prefix + [raw_field.path], stack + [nested_structure], depth + 1)
            shadowed_fields.add(raw_field.field)

    walk(root_structure, [root_structure], [root_structure], 0)
    return collected, failures


def dedupe_recursion_failures(
    failures: list[RecursionFailure],
) -> list[RecursionFailure]:
    """Remove repeated traversal failures without merging distinct paths."""

    unique: list[RecursionFailure] = []
    seen: set[tuple[str, str, str, str]] = set()
    for failure in failures:
        key = (failure.kind, failure.structure, failure.path, failure.message)
        if key in seen:
            continue
        seen.add(key)
        unique.append(failure)
    return unique


def names_for_structure(structure: str, aliases: dict[str, str]) -> set[str]:
    names = {structure}
    names.add(structure.rsplit(".", 1)[-1])
    names.update(alias for alias, target in aliases.items() if target == structure)
    return names


def type_mentions_any_structure(
    type_text: str,
    structure_names: set[str],
    aliases: dict[str, str],
    *,
    context_namespace: str = "",
    shadowed_names: set[str] | None = None,
    structure_parameter_counts: dict[str, int] | None = None,
) -> bool:
    return bool(
        mentioned_structures(
            type_text,
            structure_names,
            aliases,
            context_namespace=context_namespace,
            shadowed_names=shadowed_names,
            structure_parameter_counts=structure_parameter_counts,
        )
    )


def strip_outer_group(text: str) -> str:
    """Strip balanced outer parentheses without changing inner applications."""

    text = normalize_ws(text).strip()
    while text.startswith("(") and text.endswith(")"):
        depth = 0
        closes_at_end = False
        for index, char in enumerate(text):
            if char == "(":
                depth += 1
            elif char == ")":
                depth -= 1
                if depth == 0:
                    closes_at_end = index == len(text) - 1
                    break
        if not closes_at_end:
            break
        text = text[1:-1].strip()
    return text


def split_top_level_terms(text: str) -> list[str]:
    """Split a Lean application at whitespace outside delimiters."""

    terms: list[str] = []
    start: int | None = None
    depth = 0
    for index, char in enumerate(text):
        if char in "([{⦃":
            depth += 1
        elif char in ")]}⦄" and depth > 0:
            depth -= 1
        if char.isspace() and depth == 0:
            if start is not None:
                terms.append(text[start:index])
                start = None
        elif start is None:
            start = index
    if start is not None:
        terms.append(text[start:])
    return terms


def structure_application_arguments(
    type_text: str,
    structure_name: str,
    aliases: dict[str, str],
    parameter_count: int,
) -> list[str]:
    """Return explicit arguments at a routed structure occurrence."""

    routed_names = names_for_structure(structure_name, aliases)
    occurrence: re.Match[str] | None = None
    for routed_name in sorted(routed_names, key=lambda item: (-len(item), item)):
        match = re.search(
            rf"(?<![A-Za-z0-9_'])"
            rf"(?:[A-Za-z_][A-Za-z0-9_']*\.)*{re.escape(routed_name)}"
            rf"(?![A-Za-z0-9_'])",
            strip_outer_group(type_text),
        )
        if match is not None:
            occurrence = match
            break
    if occurrence is None or parameter_count <= 0:
        return []
    suffix = strip_outer_group(type_text)[occurrence.end() :].strip()
    return split_top_level_terms(suffix)[:parameter_count]


def substitute_structure_parameters(
    field_type: str,
    structure: StructureInfo,
    instance_type: str,
    aliases: dict[str, str],
) -> str:
    """Instantiate a parsed field type at a concrete structure application."""

    arguments = structure_application_arguments(
        instance_type, structure.name, aliases, len(structure.parameters)
    )
    substitutions = {
        parameter: arguments[index] if index < len(arguments) else f"__arg{index}"
        for index, parameter in enumerate(structure.parameters)
    }
    instantiated = field_type
    for parameter, argument in substitutions.items():
        instantiated = re.sub(
            rf"(?<![\w']){re.escape(parameter)}(?![\w'])",
            argument,
            instantiated,
        )
    return normalize_ws(instantiated)


def recursively_collect_instantiated_fields(
    root_structure: str,
    instance_type: str,
    structures: dict[str, StructureInfo],
    aliases: dict[str, str],
    max_depth: int = 8,
    *,
    shadowed_names: set[str] | None = None,
) -> list[FieldInfo]:
    """Expand one constructor input semantically through nested records."""

    collected: list[FieldInfo] = []
    seen: set[tuple[str, str, str]] = set()
    candidate_structure_parameter_counts = structure_parameter_counts(structures)

    def walk(
        structure_name: str,
        current_instance: str,
        prefix: list[str],
        stack: list[str],
        depth: int,
    ) -> None:
        if depth > max_depth:
            return
        structure = structures.get(structure_name)
        if structure is None:
            return
        instance_key = alpha_canonical_type(current_instance)
        seen_key = (structure_name, instance_key, " -> ".join(prefix))
        if seen_key in seen:
            return
        seen.add(seen_key)
        shadowed_fields = set(shadowed_names or set()) | set(structure.parameters)
        for raw_field in structure.fields:
            instantiated_type = substitute_structure_parameters(
                raw_field.type, structure, current_instance, aliases
            )
            nested = mentioned_structures(
                instantiated_type,
                set(structures),
                aliases,
                context_namespace=(
                    raw_field.structure.rsplit(".", 1)[0]
                    if "." in raw_field.structure
                    else ""
                ),
                shadowed_names=shadowed_fields,
                structure_parameter_counts=candidate_structure_parameter_counts,
            )
            field = FieldInfo(
                structure=raw_field.structure,
                field=raw_field.field,
                type=instantiated_type,
                path=" -> ".join(prefix + [raw_field.path]),
                line=raw_field.line,
                source_file=raw_field.source_file,
                nested_structures=nested,
                risk_terms=field_risk_terms(raw_field),
                constructor_fqn=raw_field.constructor_fqn,
                constructor_argument_index=raw_field.constructor_argument_index,
                projection_fqn=raw_field.projection_fqn,
            )
            collected.append(field)
            for nested_structure in nested:
                if nested_structure in stack:
                    continue
                walk(
                    nested_structure,
                    instantiated_type,
                    prefix + [raw_field.path],
                    stack + [nested_structure],
                    depth + 1,
                )
            shadowed_fields.add(raw_field.field)

    walk(root_structure, instance_type, [root_structure], [root_structure], 0)
    return collected


def _leading_balanced_type_term(text: str) -> str:
    """Return the first type atom/application after a logical wrapper.

    Parenthesized applications preserve all explicit structure arguments.  The
    unparenthesized fallback deliberately returns just the head; callers that
    resolve it to a structure can then recover precisely that structure's
    explicit arity without guessing from declaration names.
    """

    stripped = text.lstrip()
    if not stripped:
        return ""
    if stripped[0] not in "([{":
        terms = split_top_level_terms(stripped)
        return terms[0] if terms else ""
    opening = stripped[0]
    closing = {"(": ")", "[": "]", "{": "}"}[opening]
    depth = 0
    for index, char in enumerate(stripped):
        if char == opening:
            depth += 1
        elif char == closing:
            depth -= 1
            if depth == 0:
                return strip_outer_group(stripped[: index + 1])
    return ""


def _outer_type_head(type_text: str) -> str:
    """Return the outer type constructor without inspecting its spelling."""

    match = re.match(
        r"^@?((?:[A-Za-z_][A-Za-z0-9_']*\.)*"
        r"[A-Za-z_][A-Za-z0-9_']*)(?![A-Za-z0-9_'])",
        strip_outer_group(type_text),
    )
    return match.group(1) if match is not None else ""


def _existential_type_witnesses(result_type: str) -> list[tuple[str, str]]:
    """Expose explicit Type witness domains beneath result-level existentials.

    This parses the logical binder shape, not declaration or field names.  A
    witness such as `Fin n` is harmless later because it has no recursively
    reachable proposition-valued record fields.
    """

    text = normalize_logic_syntax(result_type)
    witnesses: list[tuple[str, str]] = []
    for index, char in enumerate(text):
        if char != "∃":
            continue
        cursor = index + 1
        depth = 0
        while cursor < len(text):
            current = text[cursor]
            if current in "([{⦃":
                depth += 1
            elif current in ")]}⦄" and depth > 0:
                depth -= 1
            elif current == "," and depth == 0:
                break
            cursor += 1
        if cursor >= len(text):
            continue
        binder = strip_outer_group(text[index + 1 : cursor]).strip()
        split = split_top_level_colon(binder)
        if split is None:
            continue
        _names, witness_type = split
        witness_type = normalize_ws(witness_type)
        if witness_type:
            witnesses.append(("exists_type_witness", witness_type))
    return witnesses


def _exists_constructor_type_witnesses(result_type: str) -> list[tuple[str, str]]:
    """Expose typed witnesses written with raw `Exists (fun ... => ...)`.

    Paper-facing source can use either notation.  The parser deliberately
    looks for the lambda binder shape and its domain, not a theorem or
    certificate name.  An untyped lambda is left alone because its inferred
    domain is unavailable from the source text; normal notation retains the
    domain explicitly and is handled by `_existential_type_witnesses`.
    """

    text = normalize_logic_syntax(result_type)
    pattern = re.compile(
        r"(?<![A-Za-z0-9_'])@?(?:(?:[A-Za-z_][A-Za-z0-9_']*\.)*)"
        r"Exists(?![A-Za-z0-9_'])"
    )
    witnesses: list[tuple[str, str]] = []
    for match in pattern.finditer(text):
        suffix = text[match.end() :].lstrip()
        if suffix.startswith("("):
            suffix = _leading_balanced_type_term(suffix)
        lambda_text = strip_outer_group(suffix).strip()
        if lambda_text.startswith("fun") and (
            len(lambda_text) == len("fun")
            or lambda_text[len("fun")].isspace()
        ):
            binder_text = lambda_text[len("fun") :]
        elif lambda_text.startswith("λ"):
            binder_text = lambda_text[1:]
        else:
            continue
        arrow_at = top_level_token_index(binder_text, "=>")
        if arrow_at is None:
            continue
        binder = strip_outer_group(binder_text[:arrow_at]).strip()
        split = split_top_level_colon(binder)
        if split is None:
            continue
        _names, witness_type = split
        witness_type = normalize_ws(witness_type)
        if witness_type:
            witnesses.append(("exists_type_witness", witness_type))
    return witnesses


def _nonempty_type_witnesses(result_type: str) -> list[tuple[str, str]]:
    """Expose Type witnesses placed beneath `Nonempty` in a proposition result."""

    text = normalize_ws(result_type)
    pattern = re.compile(
        r"(?<![A-Za-z0-9_'])@?(?:(?:[A-Za-z_][A-Za-z0-9_']*\.)*)"
        r"Nonempty(?![A-Za-z0-9_'])"
    )
    witnesses: list[tuple[str, str]] = []
    for match in pattern.finditer(text):
        witness_type = _leading_balanced_type_term(text[match.end() :])
        if witness_type:
            witnesses.append(("nonempty_type_witness", witness_type))
    return witnesses


def _provided_result_type_witness_receipts(
    receipts: object,
    *,
    structure_names: Iterable[str],
    context_namespace: str,
    wrapper: str,
) -> list[dict[str, object]]:
    """Select Lean-owned productive witnesses for source-parser presentation.

    The source parser can recover record fields and source locations, but it
    cannot decide logical polarity reliably.  In production, an exact present
    receipt list is therefore authoritative: an empty list means every lexical
    occurrence was assumption-side (for example beneath `Not` or in an
    implication antecedent).  Structure identities only join that Lean result
    to parser-owned field presentation; they never establish positivity.
    """

    if not isinstance(receipts, list):
        return []
    qualified_structures: set[str] = set()
    for raw_name in structure_names:
        name = str(raw_name or "").strip()
        if not name:
            continue
        if "." in name or not context_namespace:
            qualified_structures.add(name)
        else:
            qualified_structures.add(f"{context_namespace}.{name}")
    matches: list[dict[str, object]] = []
    for receipt in receipts:
        if not isinstance(receipt, dict):
            continue
        if str(receipt.get("occurrence_role") or "").strip() != "provided_result":
            continue
        witness_head = str(receipt.get("witness_type_head") or "").strip()
        path = str(receipt.get("path") or "").strip()
        if not witness_head or witness_head not in qualified_structures or not path:
            continue
        if wrapper == "nonempty_type_witness" and not path.endswith("/nonempty"):
            continue
        if wrapper == "exists_type_witness" and not path.endswith("/exists"):
            continue
        matches.append(receipt)
    return matches


def type_valued_certificate_result_items(
    *,
    row_names: list[str],
    declarations: dict[str, str],
    structures: dict[str, StructureInfo],
    aliases: dict[str, str],
    proposition_heads: set[str],
    row_qualified_names: dict[str, str] | None = None,
    proposition_aliases: dict[str, PropositionAliasInfo] | None = None,
    proposition_wrapper_structures: set[str] | None = None,
    elaborated_type_witness_receipts: Mapping[str, list[dict[str, object]]] | None = None,
) -> list[dict[str, Any]]:
    """Find result propositions that hide proof fields inside Type witnesses.

    A theorem with result `Nonempty C` proves only inhabitance of a Type-valued
    certificate `C`; it does not put the certificate's individual mathematical
    obligations on the paper-facing theorem surface.  The same issue occurs
    for an existential whose witness is such a record.  A local proposition
    inductive can also hide a Type-valued record in a constructor. Detect these
    shapes from the elaborated source type shape, recursively expose their
    proof-valued fields, and leave the source-map gate to require direct
    field-level theorem rows.

    This intentionally does *not* classify by suffixes such as `Certificate`.
    A renamed record with proposition fields is detected, while ordinary data
    witnesses such as `Fin n`, `Matching`, or a record with only data fields
    are not flagged.  When exact elaborated receipts are present, Lean's
    proposition traversal is authoritative for whether a witness is produced;
    the source parser supplies only record-field presentation.
    """

    row_qualified_names = row_qualified_names or {}
    proposition_wrapper_structures = proposition_wrapper_structures or set()
    elaborated_type_witness_receipts = elaborated_type_witness_receipts or {}
    candidates = set(structures)
    candidate_structure_parameter_counts = structure_parameter_counts(structures)
    items: list[dict[str, Any]] = []
    seen: set[tuple[str, str, str, str]] = set()
    for row in row_names:
        declaration = declarations.get(row, "")
        terminal_result = declaration_terminal_result_type(declaration)
        if not terminal_result:
            continue
        qualified_row = row_qualified_names.get(row, row)
        has_elaborated_receipt_entry = (
            qualified_row in elaborated_type_witness_receipts
        )
        row_elaborated_receipts = elaborated_type_witness_receipts.get(
            qualified_row, []
        )
        context_namespace = (
            qualified_row.rsplit(".", 1)[0] if "." in qualified_row else ""
        )
        header_bound_names = {
            name
            for visible_input in visible_inputs_from_declaration(
                declaration, include_result_inputs=False
            )
            for name in binder_names(visible_input.get("names", ""))
        }
        expanded_terminal_result = unfold_proposition_aliases(
            terminal_result,
            proposition_aliases_in_namespace(
                proposition_aliases, context_namespace
            ),
        )
        witnesses = [
            *_nonempty_type_witnesses(expanded_terminal_result),
            *_existential_type_witnesses(expanded_terminal_result),
            *_exists_constructor_type_witnesses(expanded_terminal_result),
        ]
        outer_result = strip_outer_group(expanded_terminal_result)
        if _outer_type_head(outer_result):
            witnesses.append(("proposition_wrapper_type_witness", outer_result))
        for wrapper, raw_witness_type in witnesses:
            head = _outer_type_head(raw_witness_type)
            if not head:
                continue
            roots = mentioned_structures(
                raw_witness_type,
                candidates,
                aliases,
                context_namespace=context_namespace,
                shadowed_names=header_bound_names,
                structure_parameter_counts=candidate_structure_parameter_counts,
            )
            for root in roots:
                if (
                    wrapper == "proposition_wrapper_type_witness"
                    and root not in proposition_wrapper_structures
                ):
                    continue
                structure = structures.get(root)
                if structure is None:
                    continue
                witness_type = raw_witness_type
                # Source declarations commonly write `Nonempty Record a`
                # without parentheses. Recover exactly this record's explicit
                # arguments rather than treating later logical connectives as
                # arguments to the type witness.
                if raw_witness_type == head and structure.parameters:
                    suffix = normalize_ws(
                        terminal_result.split(raw_witness_type, 1)[-1]
                    )
                    terms = [
                        term
                        for term in split_top_level_terms(suffix)
                        if term not in {"∧", "∨", "→", "↔", ","}
                    ]
                    if terms:
                        witness_type = normalize_ws(
                            " ".join([head, *terms[: len(structure.parameters)]])
                        )
                key = (
                    row,
                    wrapper,
                    root,
                    alpha_canonical_type(witness_type),
                )
                if key in seen:
                    continue
                seen.add(key)
                fields = recursively_collect_instantiated_fields(
                    root,
                    witness_type,
                    structures,
                    aliases,
                    shadowed_names=header_bound_names,
                )
                proposition_fields = [
                    field
                    for field in fields
                    if is_proposition_type(field.type, proposition_heads)
                    and not is_definitely_data_type(
                        field.type,
                        proposition_heads=proposition_heads,
                        data_heads=field_data_heads(field, structures),
                    )
                ]
                if wrapper == "proposition_wrapper_type_witness":
                    # A local Prop wrapper is relevant here only when its
                    # constructor reaches a *Type*-valued package. A wrapper
                    # around a direct proof field has no hidden certificate
                    # carrier and belongs to the ordinary proposition audit.
                    proposition_fields = [
                        field
                        for field in proposition_fields
                        if field.structure != root
                        and field.structure not in proposition_wrapper_structures
                    ]
                if not proposition_fields:
                    continue
                hidden_type_records = sorted(
                    {
                        field.structure
                        for field in proposition_fields
                        if field.structure not in proposition_wrapper_structures
                    }
                )
                matching_elaborated_receipts = (
                    _provided_result_type_witness_receipts(
                        row_elaborated_receipts,
                        structure_names=(
                            hidden_type_records
                            if wrapper == "proposition_wrapper_type_witness"
                            else [root]
                        ),
                        context_namespace=context_namespace,
                        wrapper=wrapper,
                    )
                    if has_elaborated_receipt_entry
                    else []
                )
                # With an exact Lean result in hand, source-level spelling is
                # diagnostic only.  In particular, a lexical `Nonempty C` in
                # `¬ Nonempty C` or in an implication domain cannot create a
                # certificate finding.  Legacy parser-only callers retain the
                # structural diagnostic surface; production separately fails
                # closed if an exact declaration receipt is absent.
                if has_elaborated_receipt_entry and not matching_elaborated_receipts:
                    continue
                items.append(
                    {
                        "row": row,
                        # This identifier is generated from the exact row,
                        # wrapper shape, record root, and alpha-normalized
                        # witness type. It locates a sidecar response only;
                        # source/Lean acceptance below remains structural.
                        "judgment_key": (
                            f"{row}.type_valued_certificate_result."
                            f"{wrapper}.{root}."
                            f"{structural_type_sha256(witness_type, header_bound_names)}"
                        ),
                        "source_judgment_key": (
                            f"{row}.type_valued_certificate_result."
                            f"{wrapper}.{root}."
                            f"{structural_type_sha256(witness_type, header_bound_names)}"
                        ),
                        "qualified_declaration": qualified_row,
                        "kind": "type_valued_certificate_result",
                        "source_claim_component_role": "material",
                        "source_claim_component_kind": "result_type_certificate",
                        "result_wrapper": wrapper,
                        **(
                            {
                                "result_occurrence_role": "provided_result",
                                "elaborated_witness_paths": sorted(
                                    {
                                        str(receipt.get("path") or "").strip()
                                        for receipt in matching_elaborated_receipts
                                    }
                                ),
                            }
                            if has_elaborated_receipt_entry
                            else {}
                        ),
                        "row_result_type": terminal_result,
                        "expanded_row_result_type": expanded_terminal_result,
                        "witness_type": witness_type,
                        "structural_type_sha256": structural_type_sha256(
                            witness_type, header_bound_names
                        ),
                        "proposition_sort": "true",
                        "proposition_sort_evidence": (
                            "structural_hidden_proposition_field"
                        ),
                        "theorem_facing_semantic_role": "proof_bearing",
                        "semantic_restriction_role": (
                            "requires_source_or_lean_closure"
                        ),
                        "semantic_restriction_candidates": [
                            "type_valued_certificate_with_hidden_proposition_fields"
                        ],
                        "record": (
                            hidden_type_records[0]
                            if wrapper == "proposition_wrapper_type_witness"
                            and hidden_type_records
                            else root
                        ),
                        **(
                            {"proposition_wrapper": root}
                            if wrapper == "proposition_wrapper_type_witness"
                            else {}
                        ),
                        "proposition_fields": [
                            {
                                "structure": field.structure,
                                "field": field.field,
                                "path": field.path,
                                "type": field.type,
                                "source_file": field.source_file,
                                "line": field.line,
                            }
                            for field in proposition_fields
                        ],
                        "required_check": (
                            "This theorem result proves existence or nonemptiness of a "
                            "Type-valued record with hidden proposition fields. It is an "
                            "auxiliary certificate package, not canonical source-theorem "
                            "evidence. Expose direct paper-facing theorem/lemma endpoints "
                            "for the relevant proposition fields and route source claims to "
                            "those endpoints."
                        ),
                    }
                )
    # The source parser above can expand local certificate records for useful
    # presentation.  It is not, however, authoritative for `Nonempty`,
    # `Exists`, imported proposition wrappers, or opaque Type heads.  Append
    # every nonstructural elaborated witness as its own proof-bearing item so
    # those routes cannot become raw data merely because a local record parser
    # did not recognize a name.
    for row in row_names:
        qualified_row = row_qualified_names.get(row, row)
        receipts = elaborated_type_witness_receipts.get(qualified_row, [])
        if not isinstance(receipts, list):
            continue
        for receipt in receipts:
            if not isinstance(receipt, dict):
                continue
            payload_safety = str(receipt.get("payload_safety") or "").strip()
            path = str(receipt.get("path") or "").strip()
            occurrence_role = str(
                receipt.get("occurrence_role") or ""
            ).strip()
            normalized_sha = str(
                receipt.get("normalized_type_sha256") or ""
            ).strip().lower()
            if (
                payload_safety == "structural_data"
                or not path
                or occurrence_role != "provided_result"
                or not re.fullmatch(r"[0-9a-f]{64}", normalized_sha)
            ):
                continue
            witness_identity = hashlib.sha256(
                "\0".join((qualified_row, path, normalized_sha)).encode("utf-8")
            ).hexdigest()
            key = (
                f"{row}.type_valued_certificate_result.elaborated."
                f"{witness_identity}"
            )
            if any(item.get("judgment_key") == key for item in items):
                continue
            items.append(
                {
                    "row": row,
                    "judgment_key": key,
                    "source_judgment_key": key,
                    "qualified_declaration": qualified_row,
                    "kind": "type_valued_certificate_result",
                    "source_claim_component_role": "material",
                    "source_claim_component_kind": "elaborated_result_type_witness",
                    "result_wrapper": "elaborated_type_witness",
                    "result_occurrence_role": occurrence_role,
                    "elaborated_witness_path": path,
                    "elaborated_type_witness_payload_receipt": receipt,
                    "structural_type_sha256": normalized_sha,
                    "proposition_sort": "true",
                    "proposition_sort_evidence": "lean_type_witness_payload_safety",
                    "theorem_facing_semantic_role": "proof_bearing",
                    "semantic_restriction_role": "requires_source_or_lean_closure",
                    "semantic_restriction_candidates": [
                        "elaborated_type_witness_requires_source_or_lean_closure"
                    ],
                    "required_check": (
                        "This elaborated result proposition contains a Type-valued witness "
                        "whose payload is not a trusted finite foundation representation. "
                        "Route the witness through a direct source statement or Lean derivation; "
                        "do not treat its Type/Sort alone as data credit."
                    ),
                }
            )
    return sorted(
        items,
        key=lambda item: (
            str(item.get("row") or ""),
            str(item.get("result_wrapper") or ""),
            str(item.get("record") or ""),
            str(item.get("witness_type") or ""),
        ),
    )


def elaborated_dependency_graph_is_complete(
    seed_declaration: str,
    manifest: Mapping[str, Any] | None,
    *,
    include_proof_dependencies: bool = True,
    expected_root_declaration: str | None = None,
) -> bool:
    """Return whether a manifest has a complete exact graph for ``seed``."""

    graph = manifest.get("semantic_dependency_graph") if isinstance(
        manifest, Mapping
    ) else None
    required_complete_field = (
        "realization_complete" if include_proof_dependencies else "complete"
    )
    expected_root = expected_root_declaration or seed_declaration
    if (
        not isinstance(graph, Mapping)
        or graph.get(required_complete_field) is not True
        or str(graph.get("root_declaration") or "").strip() != expected_root
    ):
        return False
    raw_nodes = graph.get("nodes")
    raw_edges = graph.get("edges")
    if not isinstance(raw_nodes, list) or not isinstance(raw_edges, list):
        return False
    node_names = {
        str(node.get("declaration") or "").strip()
        for node in raw_nodes
        if isinstance(node, Mapping)
        and str(node.get("declaration") or "").strip()
    }
    if seed_declaration not in node_names:
        return False
    return all(
        isinstance(edge, Mapping)
        and str(edge.get("source") or "").strip() in node_names
        and str(edge.get("target") or "").strip() in node_names
        and bool(str(edge.get("role") or "").strip())
        for edge in raw_edges
    )


def elaborated_dependency_declaration_closure(
    seed_declaration: str,
    local_declarations: list[LocalDeclaration],
    manifest: Mapping[str, Any] | None,
    *,
    include_proof_dependencies: bool = True,
    expected_root_declaration: str | None = None,
) -> list[LocalDeclaration]:
    """Return the exact paper-local closure emitted from Lean expressions.

    Names in this routine are graph coordinates only. Membership and edges
    come exclusively from Lean's elaborated constant graph, so comments,
    notation spelling, binder names, and helper-name substrings cannot alter
    the closure. Missing, malformed, or incomplete evidence returns no credit.
    """

    if not elaborated_dependency_graph_is_complete(
        seed_declaration,
        manifest,
        include_proof_dependencies=include_proof_dependencies,
        expected_root_declaration=expected_root_declaration,
    ):
        return []
    assert isinstance(manifest, Mapping)
    graph = manifest.get("semantic_dependency_graph")
    assert isinstance(graph, Mapping)
    raw_nodes = graph.get("nodes")
    raw_edges = graph.get("edges")
    if not isinstance(raw_nodes, list) or not isinstance(raw_edges, list):
        return []
    node_names = {
        str(node.get("declaration") or "").strip()
        for node in raw_nodes
        if isinstance(node, Mapping)
        and str(node.get("declaration") or "").strip()
    }
    if seed_declaration not in node_names:
        return []
    adjacency: dict[str, set[str]] = {}
    for edge in raw_edges:
        if not isinstance(edge, Mapping):
            return []
        source = str(edge.get("source") or "").strip()
        target = str(edge.get("target") or "").strip()
        role = str(edge.get("role") or "").strip()
        if source not in node_names or target not in node_names or not role:
            return []
        if not include_proof_dependencies and role == "proof_uses_constant":
            continue
        adjacency.setdefault(source, set()).add(target)
    reached = {seed_declaration}
    pending = [seed_declaration]
    while pending:
        source = pending.pop()
        for target in sorted(adjacency.get(source, set())):
            if target not in reached:
                reached.add(target)
                pending.append(target)
    by_name = {declaration.name: declaration for declaration in local_declarations}
    return [by_name[name] for name in sorted(reached) if name in by_name]


_AUXILIARY_SOURCE_MAP_ROUTE_FIELDS = (
    "lean_declarations",
    "proof_lean_declarations",
    "spec_lean_declarations",
    "support_lean_declarations",
    "semantic_bridge_declarations",
    "paper_equivalence_declarations",
    "source_equivalence_declarations",
    "library_bridge_declarations",
)
_AUXILIARY_SOURCE_MAP_CONTRACT_FIELDS = (
    "evidence_declaration",
    "spec_declaration",
)


def explicitly_qualified_source_map_routes(
    paper_dir: Path,
) -> dict[str, list[dict[str, str]]]:
    """Return source-map routes that can justify a reachable auxiliary.

    This is deliberately an exact fully-qualified route index.  It does not
    recover a short name by suffix or choose a declaration by traversal order:
    a source-map item must state the current Lean identity it supports.  The
    ordinary source-map validators remain responsible for checking the source
    anchor and route's mathematical role; this helper only prevents an
    otherwise invisible PaperInterface dependency from escaping that audit.
    """

    payload = load_json_object(paper_dir / "audit" / "paper_statement_map.json")
    raw_items = payload.get("items") if isinstance(payload, dict) else None
    if not isinstance(raw_items, dict):
        return {}

    routes: dict[str, list[dict[str, str]]] = {}

    def add_route(
        raw_route: object,
        *,
        source_key: str,
        route_field: str,
        source_location: str,
    ) -> None:
        qualified = semantic_contract_fully_qualified_identity(raw_route)
        if not qualified:
            return
        route = {
            "source_key": source_key,
            "route_field": route_field,
            "source_location": source_location,
        }
        bucket = routes.setdefault(qualified, [])
        if route not in bucket:
            bucket.append(route)

    for raw_key, raw_item in raw_items.items():
        if not isinstance(raw_item, dict):
            continue
        source_key = str(raw_key).strip()
        if not source_key:
            continue
        source_location = str(raw_item.get("source_location") or "").strip()
        for field_name in _AUXILIARY_SOURCE_MAP_ROUTE_FIELDS:
            raw_routes = raw_item.get(field_name)
            if not isinstance(raw_routes, list):
                continue
            for raw_route in raw_routes:
                add_route(
                    raw_route,
                    source_key=source_key,
                    route_field=field_name,
                    source_location=source_location,
                )
        contract = raw_item.get("semantic_contract")
        if isinstance(contract, dict):
            for field_name in _AUXILIARY_SOURCE_MAP_CONTRACT_FIELDS:
                add_route(
                    contract.get(field_name),
                    source_key=source_key,
                    route_field=f"semantic_contract.{field_name}",
                    source_location=source_location,
                )

    return {
        qualified: sorted(
            entries,
            key=lambda entry: (
                entry["source_key"],
                entry["route_field"],
                entry["source_location"],
            ),
        )
        for qualified, entries in sorted(routes.items())
    }


def quarantined_auxiliary_source_reasons(
    status_path: Path,
    *,
    quarantined_qualified_names: set[str],
) -> tuple[dict[str, str], list[str]]:
    """Read explicit source reasons for quarantined auxiliary declarations.

    A legacy paper-wide ``quarantined_auxiliary_reason`` is retained as a
    compatibility form because it is already an explicit statement of why all
    listed historical helpers are barred from source credit.  New per-row
    entries may use ``quarantined_auxiliary_source_reasons`` with exact
    fully-qualified Lean identities.  A short name is intentionally not
    accepted in that map: a quarantine cannot move to a same-suffix helper
    after a namespace edit.
    """

    payload = load_json_object(status_path)
    review_surface = payload.get("review_surface") if isinstance(payload, dict) else None
    if not isinstance(review_surface, dict):
        return {}, ["status.json has no review_surface object for auxiliary quarantine reasons"]

    errors: list[str] = []
    reasons: dict[str, str] = {}
    legacy_reason = review_surface.get("quarantined_auxiliary_reason")
    if legacy_reason is not None and (
        not isinstance(legacy_reason, str) or not legacy_reason.strip()
    ):
        errors.append("review_surface.quarantined_auxiliary_reason must be a nonempty string")
    if isinstance(legacy_reason, str) and legacy_reason.strip():
        for qualified in quarantined_qualified_names:
            reasons[qualified] = legacy_reason.strip()

    raw_per_auxiliary = review_surface.get("quarantined_auxiliary_source_reasons")
    if raw_per_auxiliary is None:
        return reasons, errors
    if not isinstance(raw_per_auxiliary, dict):
        errors.append(
            "review_surface.quarantined_auxiliary_source_reasons must be an object "
            "mapping exact fully-qualified declarations to source reasons"
        )
        return reasons, errors
    for raw_name, raw_reason in raw_per_auxiliary.items():
        qualified = semantic_contract_fully_qualified_identity(raw_name)
        if not qualified:
            errors.append(
                "review_surface.quarantined_auxiliary_source_reasons has a "
                "non-fully-qualified declaration key"
            )
            continue
        if qualified not in quarantined_qualified_names:
            errors.append(
                "review_surface.quarantined_auxiliary_source_reasons names a declaration "
                "that is not configured in quarantined_auxiliary_names: " + qualified
            )
            continue
        if not isinstance(raw_reason, str) or not raw_reason.strip():
            errors.append(
                "review_surface.quarantined_auxiliary_source_reasons["
                + qualified
                + "] must be a nonempty source reason"
            )
            continue
        reasons[qualified] = raw_reason.strip()
    return reasons, errors


def reachable_paper_interface_auxiliary_routing(
    *,
    paper_dir: Path,
    status_path: Path,
    interface_declarations: dict[str, str],
    selected_qualified_names: set[str],
    selected_row_names_by_qualified: dict[str, set[str]],
    auxiliary_qualified_names: set[str],
    quarantined_auxiliary_qualified_names: set[str],
    local_declarations: list[LocalDeclaration],
    dependency_graphs_by_qualified: Mapping[str, Mapping[str, Any]] | None = None,
) -> dict[str, Any]:
    """Audit PaperInterface auxiliaries reached by selected review roots.

    A declaration does not become irrelevant merely because it was put in
    ``auxiliary_names``.  For every nonselected declaration physically defined
    in ``PaperInterface.lean`` that is reachable from a selected theorem or
    selected assumption, require an exact source-map route/support or an
    explicit quarantine with a documented source reason.  The reachability
    graph is Lean's elaborated transitive dependency graph. Declaration names
    are diagnostic graph coordinates only: source tokens, comments, binder
    spellings, and local function names never create or suppress an edge.
    Missing or incomplete graph evidence fails closed.
    """

    interface_names = set(interface_declarations)
    candidates = interface_names - selected_qualified_names
    if not candidates or not selected_qualified_names:
        return {
            "reachable_paper_interface_auxiliary_dependencies": [],
            "unresolved_reachable_paper_interface_auxiliaries": [],
            "ambiguous_reachable_paper_interface_auxiliary_references": [],
            "reachable_paper_interface_auxiliary_quarantine_configuration_errors": [],
        }

    declarations_by_name = {declaration.name: declaration for declaration in local_declarations}
    for name, source in interface_declarations.items():
        if name in declarations_by_name:
            continue
        match = DECL_RE.match(source)
        declarations_by_name[name] = LocalDeclaration(
            name=name,
            kind=match.group(1) if match is not None else "unknown",
            source=source,
            source_file=str(paper_dir / "PaperInterface.lean"),
            line=0,
        )

    # Each root keeps one shortest deterministic elaborated dependency path to
    # each auxiliary. This makes the result reviewable while avoiding a
    # quadratic enumeration of equivalent proof paths.
    paths_by_target: dict[str, dict[str, list[str]]] = {}
    ambiguous_rows: dict[tuple[str, str, tuple[str, ...]], dict[str, Any]] = {}
    for root in sorted(selected_qualified_names):
        manifest = (dependency_graphs_by_qualified or {}).get(root)
        graph = manifest.get("semantic_dependency_graph") if isinstance(
            manifest, Mapping
        ) else None
        if (
            not isinstance(graph, Mapping)
            or graph.get("realization_complete") is not True
            or str(graph.get("root_declaration") or "").strip() != root
        ):
            key = (root, root, tuple())
            ambiguous_rows[key] = {
                "selected_declaration": root,
                "selected_review_rows": sorted(
                    selected_row_names_by_qualified.get(root, set())
                ),
                "referenced_from": root,
                "dependency_chain": [root],
                "candidate_auxiliaries": [],
                "disposition": "elaborated_dependency_graph_unavailable",
            }
            continue
        raw_edges = graph.get("edges")
        raw_nodes = graph.get("nodes")
        if not isinstance(raw_edges, list) or not isinstance(raw_nodes, list):
            key = (root, root, tuple())
            ambiguous_rows[key] = {
                "selected_declaration": root,
                "selected_review_rows": sorted(
                    selected_row_names_by_qualified.get(root, set())
                ),
                "referenced_from": root,
                "dependency_chain": [root],
                "candidate_auxiliaries": [],
                "disposition": "elaborated_dependency_graph_malformed",
            }
            continue
        graph_nodes = {
            str(node.get("declaration") or "").strip()
            for node in raw_nodes
            if isinstance(node, Mapping)
            and str(node.get("declaration") or "").strip()
        }
        adjacency: dict[str, set[str]] = {}
        malformed = False
        for edge in raw_edges:
            if not isinstance(edge, Mapping):
                malformed = True
                break
            source = str(edge.get("source") or "").strip()
            target = str(edge.get("target") or "").strip()
            role = str(edge.get("role") or "").strip()
            if source not in graph_nodes or target not in graph_nodes or not role:
                malformed = True
                break
            adjacency.setdefault(source, set()).add(target)
        if malformed or root not in graph_nodes:
            key = (root, root, tuple())
            ambiguous_rows[key] = {
                "selected_declaration": root,
                "selected_review_rows": sorted(
                    selected_row_names_by_qualified.get(root, set())
                ),
                "referenced_from": root,
                "dependency_chain": [root],
                "candidate_auxiliaries": [],
                "disposition": "elaborated_dependency_graph_malformed",
            }
            continue
        queue = deque([(root, [root])])
        seen: set[str] = set()
        while queue:
            current, path = queue.popleft()
            if current in seen:
                continue
            seen.add(current)
            for child in sorted(adjacency.get(current, set())):
                next_path = [*path, child]
                if child in candidates:
                    paths_by_target.setdefault(child, {}).setdefault(root, next_path)
                if child not in seen:
                    queue.append((child, next_path))

    interface_quarantined = quarantined_auxiliary_qualified_names & interface_names
    quarantine_reasons, quarantine_config_errors = quarantined_auxiliary_source_reasons(
        status_path,
        quarantined_qualified_names=interface_quarantined,
    )
    source_routes = explicitly_qualified_source_map_routes(paper_dir)
    dependencies: list[dict[str, Any]] = []
    unresolved: list[dict[str, Any]] = []
    for target in sorted(paths_by_target):
        declaration = declarations_by_name[target]
        route_entries = source_routes.get(target, [])
        quarantine_reason = quarantine_reasons.get(target, "")
        is_quarantined = target in interface_quarantined
        if route_entries and is_quarantined:
            disposition = "conflicting_source_route_and_quarantine"
        elif route_entries:
            disposition = "explicit_source_map_route_or_support"
        elif is_quarantined and quarantine_reason:
            disposition = "explicit_quarantined_source_reason"
        elif is_quarantined:
            disposition = "quarantined_without_source_reason"
        else:
            disposition = "missing_source_map_route_or_quarantine"
        item: dict[str, Any] = {
            "declaration": target,
            "kind": declaration.kind,
            "source_file": declaration.source_file,
            "line": declaration.line,
            "configuration": (
                "configured_auxiliary"
                if target in auxiliary_qualified_names
                else "unconfigured_paper_interface_declaration"
            ),
            "transitively_referenced_from": [
                {
                    "selected_declaration": root,
                    "selected_review_rows": sorted(
                        selected_row_names_by_qualified.get(root, set())
                    ),
                    "dependency_chain": path,
                }
                for root, path in sorted(paths_by_target[target].items())
            ],
            "source_map_routes": route_entries,
            "quarantined": is_quarantined,
            "quarantine_source_reason": quarantine_reason,
            "disposition": disposition,
        }
        dependencies.append(item)
        if disposition not in {
            "explicit_source_map_route_or_support",
            "explicit_quarantined_source_reason",
        }:
            unresolved.append(item)

    return {
        "reachable_paper_interface_auxiliary_dependencies": dependencies,
        "unresolved_reachable_paper_interface_auxiliaries": unresolved,
        "ambiguous_reachable_paper_interface_auxiliary_references": [
            ambiguous_rows[key] for key in sorted(ambiguous_rows)
        ],
        "reachable_paper_interface_auxiliary_quarantine_configuration_errors": sorted(
            set(quarantine_config_errors)
        ),
    }


def proposition_input_result_bridges(
    *,
    reviewed_declaration: str,
    input_type: str,
    row_result_type: str,
    local_declarations: list[LocalDeclaration],
    proposition_aliases: dict[str, PropositionAliasInfo] | None = None,
    dependency_declarations: list[LocalDeclaration],
) -> list[dict[str, Any]]:
    """Find referenced local proofs that turn an aliased premise into a result.

    Delta expansion alone cannot identify a premise whose transparent body is
    stated in one semantic representation and then refined to the paper-facing
    result by another theorem. Restrict this scan to declarations in the
    reviewed proof's elaborated dependency closure: an unrelated theorem
    elsewhere in the paper must not make an ordinary source assumption look
    circular.
    """

    expanded_input = unfold_proposition_aliases(input_type, proposition_aliases)
    if canonical_type(expanded_input) == canonical_type(input_type):
        return []

    bridges: list[dict[str, Any]] = []
    for declaration in dependency_declarations:
        if declaration.name == reviewed_declaration or declaration.kind not in {
            "theorem",
            "lemma",
        }:
            continue
        bridge_result = declaration_terminal_result_type(declaration.source)
        result_relation = proposition_type_relation(
            bridge_result, row_result_type, proposition_aliases
        )
        if result_relation not in RESULT_BEARING_RELATIONS:
            continue
        for bridge_input in visible_inputs_from_declaration(declaration.source):
            bridge_input_type = bridge_input.get("type", "")
            input_relation = proposition_type_relation(
                bridge_input_type, input_type, proposition_aliases
            )
            if input_relation not in RESULT_BEARING_RELATIONS:
                continue
            bridges.append(
                {
                    "declaration": declaration.name,
                    "kind": declaration.kind,
                    "source_file": declaration.source_file,
                    "line": declaration.line,
                    "input_type": bridge_input_type,
                    "expanded_input_type": strip_outer_group(
                        unfold_proposition_aliases(
                            bridge_input_type, proposition_aliases
                        )
                    ),
                    "input_relation": input_relation,
                    "result_type": bridge_result,
                    "result_relation": result_relation,
                }
            )
            break
    return bridges


def proposition_surface_pattern(
    type_text: str,
    *,
    proposition_aliases: dict[str, PropositionAliasInfo] | None,
    bound_names: set[str],
) -> str:
    """Normalize one proposition surface across declaration-local binders.

    A subtype predicate is written in the reviewed theorem's binder scope,
    while a helper theorem normally uses its own parameter names.  This erases
    only those locally bound names before comparing proposition surfaces; it
    does not rewrite declaration/function identifiers or use their suffixes.
    """

    return abstract_free_identifiers(
        unfold_proposition_aliases(type_text, proposition_aliases), bound_names
    )


def subtype_predicate_result_bridges(
    *,
    reviewed_declaration: str,
    reviewed_source: str,
    predicate_type: str,
    row_result_type: str,
    local_declarations: list[LocalDeclaration],
    proposition_aliases: dict[str, PropositionAliasInfo] | None,
    proposition_heads: set[str],
    predicate_bound_names: set[str],
    row_bound_names: set[str],
    dependency_declarations: list[LocalDeclaration],
) -> list[dict[str, Any]]:
    """Find proof-dependency paths from a subtype predicate to the result.

    A value of ``{x // P x}`` stores a proof of ``P x``.  Checking only
    whether ``P x`` is textually the reviewed conclusion misses the ordinary
    smuggling pattern ``P -> Q -> Goal`` through local lemmas used in the
    theorem proof.  We therefore construct a bounded proposition graph over
    the reviewed declaration's Lean-elaborated dependency closure.  Each
    edge is a local declaration that consumes a proposition and returns a
    proposition.  Declaration and binder spelling are navigational only: the
    comparison uses alpha-normalized proposition surfaces.

    This is deliberately a conservative reachability analysis.  A discovered
    path does not claim the helper proof is invalid; it says the stored subtype
    proof participates in a route to the reviewed conclusion and therefore
    cannot be silently classified as nonpropositional domain data.
    """

    predicate_pattern = proposition_surface_pattern(
        predicate_type,
        proposition_aliases=proposition_aliases,
        bound_names=predicate_bound_names,
    )
    result_pattern = proposition_surface_pattern(
        row_result_type,
        proposition_aliases=proposition_aliases,
        bound_names=row_bound_names,
    )
    if not predicate_pattern or not result_pattern:
        return []

    closure = dependency_declarations
    if not closure:
        return []

    # Map each reachable proposition pattern to one shortest proof-dependency
    # path. The finite bound limits only proposition-shape comparison after
    # Lean has selected the exact dependency declarations.
    paths_by_pattern: dict[str, list[dict[str, Any]]] = {predicate_pattern: []}
    queue = [predicate_pattern]
    bridges: list[dict[str, Any]] = []
    seen_bridge_paths: set[tuple[str, ...]] = set()
    max_steps = min(
        64,
        max(1, len(closure) * max(1, len(closure))),
    )
    steps = 0

    while queue and steps < max_steps:
        current_pattern = queue.pop(0)
        current_path = paths_by_pattern[current_pattern]
        steps += 1
        for declaration in closure:
            if declaration.name == reviewed_declaration:
                continue
            result_type = declaration_terminal_result_type(declaration.source)
            if not is_proposition_type(result_type, proposition_heads):
                continue
            declaration_inputs = visible_inputs_from_declaration(
                declaration.source
            )
            declaration_bound_names = {
                name
                for visible_input in declaration_inputs
                for name in binder_names(visible_input.get("names", ""))
            }
            declaration_result_pattern = proposition_surface_pattern(
                result_type,
                proposition_aliases=proposition_aliases,
                bound_names=declaration_bound_names,
            )
            if not declaration_result_pattern:
                continue
            for input_index, declaration_input in enumerate(declaration_inputs):
                input_type = str(declaration_input.get("type") or "")
                if not is_proposition_type(input_type, proposition_heads):
                    continue
                input_pattern = proposition_surface_pattern(
                    input_type,
                    proposition_aliases=proposition_aliases,
                    bound_names=declaration_bound_names,
                )
                input_relation = proposition_type_relation(
                    current_pattern, input_pattern
                )
                # Only a current proposition that supplies the helper input
                # can travel over this edge.  The reverse/component relation
                # is not a proof of an enclosing conjunction or implication.
                if input_relation not in {"equivalent", "provides_target"}:
                    continue
                step = {
                    "declaration": declaration.name,
                    "kind": declaration.kind,
                    "source_file": declaration.source_file,
                    "line": declaration.line,
                    "input_index": input_index,
                    "input_type": input_type,
                    "input_pattern": input_pattern,
                    "input_relation": input_relation,
                    "result_type": result_type,
                    "result_pattern": declaration_result_pattern,
                }
                next_path = current_path + [step]
                result_relation = proposition_type_relation(
                    declaration_result_pattern, result_pattern
                )
                if result_relation in {"equivalent", "provides_target"}:
                    bridge_key = tuple(
                        f"{entry['declaration']}:{entry['input_index']}"
                        for entry in next_path
                    )
                    if bridge_key not in seen_bridge_paths:
                        seen_bridge_paths.add(bridge_key)
                        bridges.append(
                            {
                                "predicate_pattern": predicate_pattern,
                                "row_result_pattern": result_pattern,
                                "result_relation": result_relation,
                                "steps": next_path,
                            }
                        )
                if declaration_result_pattern not in paths_by_pattern:
                    paths_by_pattern[declaration_result_pattern] = next_path
                    queue.append(declaration_result_pattern)

    return bridges



def constructor_candidates(
    *,
    local_declarations: list[LocalDeclaration],
    excluded_declaration: str,
    target_type: str,
    target_structures: set[str],
    forbidden_input_structures: set[str] | None,
    aliases: dict[str, str],
    conclusion_fields: list[FieldInfo],
    row_result_type: str = "",
    structures: dict[str, StructureInfo] | None = None,
    proposition_heads: set[str] | None = None,
    proposition_aliases: dict[str, PropositionAliasInfo] | None = None,
    data_heads: set[str] | None = None,
    semantic_declarations: list[LocalDeclaration] | None = None,
    target_free_names: set[str] | None = None,
    dependency_manifest: Mapping[str, Any] | None = None,
) -> tuple[list[ConstructorCandidate], list[ConstructorCandidate]]:
    """Classify target constructors by expanded input types, not record names.

    Inputs carrying the target record or an alpha-equivalent/provider
    proposition are circular. Inputs whose recursive record closure has other
    proposition fields are conditional on exact source-antecedent judgments.
    Only constructors with data-only record inputs are unconditionally valid.
    """

    _ = forbidden_input_structures
    structures = structures or {}
    semantic_declarations = semantic_declarations or local_declarations
    candidate_structure_parameter_counts = structure_parameter_counts(structures)
    valid: list[ConstructorCandidate] = []
    rejected: list[ConstructorCandidate] = []
    target_key = abstract_free_identifiers(target_type, target_free_names or set())
    for declaration in local_declarations:
        if declaration.name == excluded_declaration:
            continue
        if declaration.kind not in {"theorem", "lemma", "def", "abbrev"}:
            continue
        result_type = declaration_terminal_result_type(declaration.source)
        if not result_type:
            continue
        declaration_inputs = visible_inputs_from_declaration(declaration.source)
        declaration_bound_names = {
            name
            for visible_input in declaration_inputs
            for name in binder_names(visible_input.get("names", ""))
        }
        declaration_namespace = (
            declaration.name.rsplit(".", 1)[0]
            if "." in declaration.name
            else ""
        )
        if target_structures:
            if not type_mentions_any_structure(
                result_type,
                target_structures,
                aliases,
                context_namespace=declaration_namespace,
                shadowed_names=declaration_bound_names,
                structure_parameter_counts=candidate_structure_parameter_counts,
            ):
                continue
            # Mentioning a record in an implication premise is not constructing
            # it. Require the explicit result to start at the record type/alias.
            result_head = _outer_type_head(result_type)
            result_head_structures = mentioned_structures(
                result_head,
                set(structures),
                aliases,
                context_namespace=declaration_namespace,
                shadowed_names=declaration_bound_names,
                structure_parameter_counts=candidate_structure_parameter_counts,
            )
            if not set(result_head_structures) & target_structures:
                continue
        else:
            candidate_free_names = declaration_bound_names
            if (
                not target_key
                or abstract_free_identifiers(result_type, candidate_free_names)
                != target_key
            ):
                continue

        instantiated_conclusion_fields = conclusion_fields
        candidate_data_heads = set(data_heads or KNOWN_DATA_TYPE_HEADS)
        candidate_data_heads.update(declaration_type_variable_heads(declaration.source))
        if target_structures and structures:
            conclusion_keys = {
                (field.structure, field.field) for field in conclusion_fields
            }
            expanded_target_fields: list[FieldInfo] = []
            for target_structure in target_structures:
                expanded_target_fields.extend(
                    recursively_collect_instantiated_fields(
                        target_structure,
                        result_type,
                        structures,
                        aliases,
                        shadowed_names=declaration_bound_names,
                    )
                )
            selected = [
                field
                for field in expanded_target_fields
                if (field.structure, field.field) in conclusion_keys
            ]
            if selected:
                instantiated_conclusion_fields = selected

        conclusion_field_types = [field.type for field in instantiated_conclusion_fields]
        # A direct primitive proof input may establish a source-model field
        # without itself supplying the reviewed result. Keep it conditional in
        # that case. In contrast, a sibling record carrying a target proof
        # field remains a circular/repackaging route below.
        result_bearing_field_types = [
            field.type
            for field in instantiated_conclusion_fields
            if is_proposition_type(field.type, proposition_heads)
            and (
                not row_result_type
                or proposition_type_relation(
                    field.type, row_result_type, proposition_aliases
                )
                in RESULT_BEARING_RELATIONS
            )
        ]
        inputs = declaration_inputs
        scoped_inputs: list[tuple[dict[str, str], set[str]]] = []
        input_scope: set[str] = set()
        for candidate_input in inputs:
            scoped_inputs.append((candidate_input, set(input_scope)))
            input_scope.update(binder_names(candidate_input.get("names", "")))
        circular_inputs: list[str] = []
        conditional_inputs: list[str] = []
        required_fields: list[FieldInfo] = []
        seen_required_fields: set[tuple[str, str]] = set()
        for input_index, (visible_input, input_scope) in enumerate(scoped_inputs):
            names = visible_input.get("names", "")
            input_type = visible_input.get("type", "")
            input_is_proposition = is_proposition_type(
                input_type, proposition_heads
            )
            reason = ""
            if (
                not target_structures
                and input_is_proposition
                and proposition_type_relation(
                    input_type, result_type, proposition_aliases
                )
                in RESULT_BEARING_RELATIONS
            ):
                reason = (
                    "accepts the same conclusion, a provider of it, or a logical "
                    "component of it"
                )
            elif input_is_proposition and any(
                proposition_type_relation(
                    input_type, field_type, proposition_aliases
                )
                in RESULT_BEARING_RELATIONS
                for field_type in result_bearing_field_types
            ):
                reason = "accepts a provider of a conclusion-bearing target field"

            input_structures = mentioned_structures(
                input_type,
                set(structures),
                aliases,
                context_namespace=declaration_namespace,
                shadowed_names=input_scope,
                structure_parameter_counts=candidate_structure_parameter_counts,
            )
            if target_structures and set(input_structures) & target_structures:
                reason = "accepts the target record through a direct or aliased type"

            input_circular_fields: list[FieldInfo] = []
            input_conditional_fields: list[FieldInfo] = []
            for input_structure in input_structures:
                if input_structure in target_structures:
                    continue
                expanded_input_fields = recursively_collect_instantiated_fields(
                    input_structure,
                    input_type,
                    structures,
                    aliases,
                    shadowed_names=input_scope,
                )
                for input_field in expanded_input_fields:
                    if input_field.nested_structures:
                        continue
                    is_proposition = is_proposition_type(
                        input_field.type, proposition_heads
                    )
                    is_data = is_definitely_data_type(
                        input_field.type,
                        proposition_heads=proposition_heads,
                        data_heads=field_data_heads(
                            input_field, structures, candidate_data_heads
                        ),
                    )
                    if not is_proposition and is_data:
                        continue
                    if not is_proposition:
                        input_conditional_fields.append(input_field)
                        continue
                    relations = [
                        proposition_type_relation(
                            input_field.type, field_type, proposition_aliases
                        )
                        for field_type in conclusion_field_types
                    ]
                    if row_result_type:
                        relations.append(
                            proposition_type_relation(
                                input_field.type, row_result_type, proposition_aliases
                            )
                        )
                    if any(
                        relation in RESULT_BEARING_RELATIONS
                        for relation in relations
                    ):
                        input_circular_fields.append(input_field)
                    else:
                        input_conditional_fields.append(input_field)

            if not input_structures and not reason:
                is_proposition = is_proposition_type(input_type, proposition_heads)
                is_data = is_definitely_data_type(
                    input_type,
                    proposition_heads=proposition_heads,
                    data_heads=candidate_data_heads,
                )
                if is_proposition or not is_data:
                    synthetic_field = FieldInfo(
                        structure="ConstructorInput",
                        field=f"{declaration.name}_input_{input_index}",
                        type=input_type,
                        path=f"{declaration.name} input {input_index}",
                        line=declaration.line,
                        source_file=declaration.source_file,
                        nested_structures=[],
                        risk_terms=[],
                    )
                    input_conditional_fields.append(synthetic_field)

            if input_circular_fields:
                keys = ", ".join(
                    f"{field.structure}.{field.field}"
                    for field in input_circular_fields[:4]
                )
                reason = f"recursive input record provides target proposition field(s): {keys}"
            for input_field in input_conditional_fields:
                key = (input_field.structure, input_field.field)
                if key in seen_required_fields:
                    continue
                seen_required_fields.add(key)
                required_fields.append(input_field)
            if input_conditional_fields and not input_circular_fields:
                keys = ", ".join(
                    f"{field.structure}.{field.field}"
                    for field in input_conditional_fields[:4]
                )
                conditional_inputs.append(
                    f"{names} : {input_type} "
                    f"(proof-bearing record input requires exact source antecedent(s): {keys})"
                )
            if reason:
                circular_inputs.append(f"{names} : {input_type} ({reason})")

        # A constructor with no visible proof input can still smuggle the
        # conclusion through an axiom/opaque constant called by a helper. Walk
        # only its Lean-elaborated dependency subgraph. A candidate absent from
        # the selected theorem's graph receives no constructor credit.
        candidate_dependency_closure = elaborated_dependency_declaration_closure(
            declaration.name,
            semantic_declarations,
            dependency_manifest,
            include_proof_dependencies=True,
            expected_root_declaration=excluded_declaration,
        )
        if not any(
            dependency.name == declaration.name
            for dependency in candidate_dependency_closure
        ):
            conditional_inputs.append(
                "candidate constructor has no complete elaborated dependency route "
                "from the selected reviewed declaration"
            )
        for dependency in candidate_dependency_closure:
            if dependency.name == declaration.name or dependency.kind not in {
                "axiom",
                "opaque",
                "constant",
            }:
                continue
            dependency_type = declaration_terminal_result_type(dependency.source)
            dependency_data_heads = candidate_data_heads | declaration_type_variable_heads(
                dependency.source
            )
            dependency_bound_names = {
                name
                for dependency_input in visible_inputs_from_declaration(
                    dependency.source
                )
                for name in binder_names(dependency_input.get("names", ""))
            }
            dependency_structures = mentioned_structures(
                dependency_type,
                set(structures),
                aliases,
                context_namespace=(
                    dependency.name.rsplit(".", 1)[0]
                    if "." in dependency.name
                    else ""
                ),
                shadowed_names=dependency_bound_names,
                structure_parameter_counts=candidate_structure_parameter_counts,
            )
            dependency_circular_fields: list[FieldInfo] = []
            dependency_conditional_fields: list[FieldInfo] = []
            if target_structures and set(dependency_structures) & target_structures:
                circular_inputs.append(
                    f"dependency {dependency.name} : {dependency_type} "
                    "(axiom/opaque/constant provides the target record)"
                )
                continue
            for dependency_structure in dependency_structures:
                for dependency_field in recursively_collect_instantiated_fields(
                    dependency_structure,
                    dependency_type,
                    structures,
                    aliases,
                    shadowed_names=dependency_bound_names,
                ):
                    if dependency_field.nested_structures:
                        continue
                    is_proposition = is_proposition_type(
                        dependency_field.type, proposition_heads
                    )
                    is_data = is_definitely_data_type(
                        dependency_field.type,
                        proposition_heads=proposition_heads,
                        data_heads=field_data_heads(
                            dependency_field, structures, dependency_data_heads
                        ),
                    )
                    if not is_proposition and is_data:
                        continue
                    if not is_proposition:
                        dependency_conditional_fields.append(dependency_field)
                        continue
                    relations = [
                        proposition_type_relation(
                            dependency_field.type, field_type, proposition_aliases
                        )
                        for field_type in conclusion_field_types
                    ]
                    if row_result_type:
                        relations.append(
                            proposition_type_relation(
                                dependency_field.type,
                                row_result_type,
                                proposition_aliases,
                            )
                        )
                    if any(
                        relation in RESULT_BEARING_RELATIONS
                        for relation in relations
                    ):
                        dependency_circular_fields.append(dependency_field)
                    else:
                        dependency_conditional_fields.append(dependency_field)
            direct_relation = ""
            dependency_is_proposition = is_proposition_type(
                dependency_type, proposition_heads
            )
            dependency_is_data = is_definitely_data_type(
                dependency_type,
                proposition_heads=proposition_heads,
                data_heads=dependency_data_heads,
            )
            dependency_is_unknown_nondata = (
                not dependency_is_proposition
                and not dependency_structures
                and not dependency_is_data
            )
            if dependency_is_proposition:
                direct_relations = [
                    proposition_type_relation(
                        dependency_type, field_type, proposition_aliases
                    )
                    for field_type in conclusion_field_types
                ]
                if row_result_type:
                    direct_relations.append(
                        proposition_type_relation(
                            dependency_type, row_result_type, proposition_aliases
                        )
                    )
                direct_relation = next(
                    (
                        relation
                        for relation in direct_relations
                        if relation in RESULT_BEARING_RELATIONS
                    ),
                    "",
                )
            if direct_relation or dependency_circular_fields:
                circular_inputs.append(
                    f"dependency {dependency.name} : {dependency_type} "
                    "(axiom/opaque/constant proposition provides a target conclusion field)"
                )
                continue
            if dependency_is_proposition or dependency_is_unknown_nondata:
                dependency_conditional_fields.append(
                    FieldInfo(
                        structure="LocalDeclaration",
                        field=dependency.name,
                        type=dependency_type,
                        path=f"local {dependency.kind} {dependency.name}",
                        line=dependency.line,
                        source_file=dependency.source_file,
                        nested_structures=[],
                        risk_terms=[dependency.kind],
                    )
                )
            for dependency_field in dependency_conditional_fields:
                key = (dependency_field.structure, dependency_field.field)
                if key in seen_required_fields:
                    continue
                seen_required_fields.add(key)
                required_fields.append(dependency_field)
            if dependency_conditional_fields:
                keys = ", ".join(
                    f"{field.structure}.{field.field}"
                    for field in dependency_conditional_fields[:4]
                )
                conditional_inputs.append(
                    f"dependency {dependency.name} : {dependency_type} "
                    f"(axiom/opaque/constant proof dependency requires exact source antecedent(s): {keys})"
                )

        candidate = ConstructorCandidate(
            declaration=declaration.name,
            kind=declaration.kind,
            source_file=declaration.source_file,
            line=declaration.line,
            result_type=result_type,
            inputs=inputs,
            circular_inputs=circular_inputs,
            conditional_inputs=conditional_inputs,
            required_source_antecedent_fields=required_fields,
        )
        (rejected if circular_inputs or conditional_inputs else valid).append(candidate)
    return valid, rejected


def field_reached_through_function_antecedent(
    root_structure: str,
    field: FieldInfo,
    structures: dict[str, StructureInfo],
    aliases: dict[str, str],
) -> bool:
    """Return whether a nested field was reached through a function premise.

    Recursive record expansion must distinguish a proof stored in a package
    from the fields of a proof object that a package method merely accepts as
    an argument.  In a field such as ``step_refines : ExactStep s t -> LocalRun
    s t``, the constructors of ``ExactStep`` are caller-supplied source
    antecedents.  A coincidental overlap between one constructor field and the
    reviewed row's result must not turn that argument into a stored conclusion.
    Direct fields and nested codomain fields remain fail-closed.
    """

    path_segments = [segment.strip() for segment in field.path.split(" -> ")]
    if len(path_segments) < 3:
        return False
    fields_by_path = {
        raw_field.path: raw_field
        for structure in structures.values()
        for raw_field in structure.fields
    }
    structure_names = set(structures)
    candidate_structure_parameter_counts = structure_parameter_counts(structures)
    for index in range(1, len(path_segments) - 1):
        parent_field = fields_by_path.get(path_segments[index])
        if parent_field is None:
            continue
        child_path = path_segments[index + 1]
        child_structure = next(
            (
                name
                for name in sorted(structure_names, key=len, reverse=True)
                if child_path == name or child_path.startswith(name + ".")
            ),
            "",
        )
        if not child_structure:
            continue
        premise_inputs, _ = result_type_inputs(parent_field.type)
        parent_namespace = (
            parent_field.structure.rsplit(".", 1)[0]
            if "." in parent_field.structure
            else ""
        )
        for premise in premise_inputs:
            premise_type = str(premise.get("type") or "").strip()
            if child_structure in mentioned_structures(
                premise_type,
                structure_names,
                aliases,
                context_namespace=parent_namespace,
                structure_parameter_counts=candidate_structure_parameter_counts,
            ):
                return True
    return False


def scoped_record_binder_dependencies(
    expression: str,
    record_binder_names: set[str],
) -> list[str]:
    """Return earlier record-valued binders used by one dependent expression.

    Binder spelling is used here only for lexical scope, not as a semantic
    classifier.  If a subtype predicate reaches an earlier record argument via
    a projection such as ``model.assumption``, the predicate may depend on a
    hidden proof field even though no record *type* appears in the predicate.
    """

    used: list[str] = []
    for name in sorted(record_binder_names):
        if re.search(rf"(?<![\w'.]){re.escape(name)}(?![\w'])", expression):
            used.append(name)
    return used


def conclusion_dependency_items(
    *,
    row_names: list[str],
    declarations: dict[str, str],
    row_inputs: dict[str, list[dict[str, str]]],
    row_records: dict[str, list[str]],
    fields_by_root: dict[str, list[FieldInfo]],
    local_declarations: list[LocalDeclaration],
    aliases: dict[str, str],
    structures: dict[str, StructureInfo],
    proposition_heads: set[str],
    data_heads: set[str],
    semantic_declarations: list[LocalDeclaration],
    proposition_aliases: dict[str, PropositionAliasInfo] | None = None,
    row_qualified_names: dict[str, str] | None = None,
    elaborated_manifests_by_qualified: Mapping[
        str, Mapping[str, Any]
    ] | None = None,
    elaborated_input_atom_errors: list[str] | None = None,
    delegated_empty_input_rows: Mapping[str, Mapping[str, str]] | None = None,
    positional_signature_manifests_by_row: Mapping[
        str, Mapping[str, Any]
    ] | None = None,
) -> list[dict[str, Any]]:
    """Return reviewed conclusion inputs that need non-circular constructors."""

    proposition_aliases = proposition_aliases or {}
    row_qualified_names = row_qualified_names or {}
    elaborated_manifests_by_qualified = elaborated_manifests_by_qualified or {}
    candidate_structure_parameter_counts = structure_parameter_counts(structures)
    subtype_alias_heads = {
        declaration.name
        for declaration in semantic_declarations
        if declaration.kind in {"def", "abbrev"}
        and subtype_hidden_property(declaration_body_text(declaration.source))
    }
    items: list[dict[str, Any]] = []
    for row in row_names:
        if row in (delegated_empty_input_rows or {}):
            continue
        declaration = declarations[row]
        match = DECL_RE.match(declaration)
        if match is None or match.group(1) not in {"theorem", "lemma"}:
            continue
        result_type = declaration_terminal_result_type(declaration)
        row_free_names = {
            name
            for row_input in row_inputs.get(row, [])
            for name in binder_names(row_input.get("names", ""))
        }
        row_data_heads = set(data_heads)
        row_data_heads.update(declaration_type_variable_heads(declaration))
        context_namespace = (
            row_qualified_names.get(row, row).rsplit(".", 1)[0]
            if "." in row_qualified_names.get(row, row)
            else ""
        )
        row_proposition_aliases = proposition_aliases_in_namespace(
            proposition_aliases, context_namespace
        )
        row_manifest = (positional_signature_manifests_by_row or {}).get(
            row,
            elaborated_manifests_by_qualified.get(row_qualified_names.get(row, row)),
        )
        input_atom_receipts, input_atom_errors = (
            elaborated_visible_input_binder_atom_receipts(
                visible_inputs=row_inputs.get(row, []),
                manifest=row_manifest,
            )
        )
        if input_atom_errors and elaborated_input_atom_errors is not None:
            elaborated_input_atom_errors.extend(
                f"{row_qualified_names.get(row, row)}: {error}"
                for error in input_atom_errors
            )
        row_dependency_graph_complete = elaborated_dependency_graph_is_complete(
            row_qualified_names.get(row, row),
            row_manifest,
            include_proof_dependencies=True,
        )
        row_dependency_declarations = elaborated_dependency_declaration_closure(
            row_qualified_names.get(row, row),
            local_declarations,
            row_manifest,
            include_proof_dependencies=True,
        )
        scoped_row_inputs: list[tuple[dict[str, str], set[str]]] = []
        row_scope: set[str] = set()
        for row_input in row_inputs.get(row, []):
            scoped_row_inputs.append((row_input, set(row_scope)))
            row_scope.update(binder_names(row_input.get("names", "")))
        record_binder_names: set[str] = set()
        for visible_input_index, (visible_input, input_scope) in enumerate(
            scoped_row_inputs
        ):
            binder_names_text = visible_input.get("names", "")
            input_type = visible_input.get("type", "")
            alias_expansion = delta_expand_transparent_proposition_aliases(
                input_type,
                proposition_aliases,
                semantic_declarations,
                context_namespace=context_namespace,
                shadowed_names=input_scope,
            )
            expanded_input_type = alias_expansion.expanded_type

            bool_certificate = bool_certificate_decided_proposition(
                input_type,
                semantic_declarations,
                context_namespace=context_namespace,
            )
            if bool_certificate is not None:
                input_origin = visible_input.get("input_origin", "")
                items.append(
                    {
                        "judgment_key": boundary_input_judgment_key(row, visible_input),
                        "row": row,
                        "binder": binder_names_text,
                        "binder_type": input_type,
                        "row_result_type": result_type,
                        "kind": "bool_certificate_input",
                        "conclusion_fields": [],
                        "valid_constructors": [],
                        "rejected_constructors": [],
                        "conditional_constructors": [],
                        **(
                            {"input_origin": input_origin}
                            if input_origin
                            else {}
                        ),
                        **bool_certificate,
                        "required_check": (
                            "A reviewed theorem places a Boolean certificate "
                            "`checker = true` in a dependent result-level `if` guard. "
                            "Moving a proof-bearing premise under `if` does not construct "
                            "it; expose the conditional boundary or replace the classical "
                            "decision with an independently computed checker."
                            if input_origin == "dependent_if_guard"
                            else
                            "A reviewed theorem accepts a Boolean certificate "
                            "`checker = true` whose local checker encodes a proposition via "
                            "`decide` or a truth-valued `if`. This is proof-bearing input, not bare data; expose "
                            "the proposition directly or prove the checker from source/model "
                            "primitives with an audited constructor."
                        ),
                    }
                )

            selector_certificate = option_success_certificate_proposition(
                input_type,
                semantic_declarations,
                context_namespace=context_namespace,
            )
            if selector_certificate is not None:
                items.append(
                    {
                        "judgment_key": boundary_input_judgment_key(row, visible_input),
                        "row": row,
                        "binder": binder_names_text,
                        "binder_type": input_type,
                        "row_result_type": result_type,
                        "kind": "selector_certificate_input",
                        "conclusion_fields": [],
                        "valid_constructors": [],
                        "rejected_constructors": [],
                        "conditional_constructors": [],
                        **selector_certificate,
                        "required_check": (
                            "A reviewed theorem accepts `selector = some value` where "
                            "success is guarded by a proposition inside a local Option "
                            "selector. This equality carries the selector's existence "
                            "obligation; expose its expanded success specification or "
                            "construct it from audited source/model primitives."
                        ),
                    }
                )

            subtype_domain = transparent_subtype_domain(
                input_type,
                semantic_declarations,
                context_namespace=context_namespace,
                shadowed_names=input_scope,
            )
            if subtype_domain is not None:
                predicate_scope = set(input_scope)
                if subtype_domain.value_binder:
                    predicate_scope.add(subtype_domain.value_binder)
                predicate_expansion = delta_expand_transparent_proposition_aliases(
                    subtype_domain.predicate,
                    proposition_aliases,
                    semantic_declarations,
                    context_namespace=context_namespace,
                    shadowed_names=predicate_scope,
                )
                predicate_relation = (
                    proposition_type_relation(
                        predicate_expansion.expanded_type,
                        result_type,
                        row_proposition_aliases,
                    )
                    if subtype_domain.expansion_complete
                    else ""
                )
                carrier_record_dependencies = mentioned_structures(
                    subtype_domain.carrier_type,
                    set(structures),
                    aliases,
                    context_namespace=context_namespace,
                    shadowed_names=input_scope,
                    structure_parameter_counts=candidate_structure_parameter_counts,
                )
                predicate_record_dependencies = mentioned_structures(
                    predicate_expansion.expanded_type,
                    set(structures),
                    aliases,
                    context_namespace=context_namespace,
                    shadowed_names=predicate_scope,
                    structure_parameter_counts=candidate_structure_parameter_counts,
                )
                predicate_record_binder_dependencies = scoped_record_binder_dependencies(
                    predicate_expansion.expanded_type,
                    record_binder_names,
                )
                predicate_result_bridges = (
                    subtype_predicate_result_bridges(
                        reviewed_declaration=row_qualified_names.get(row, row),
                        reviewed_source=declaration,
                        predicate_type=predicate_expansion.expanded_type,
                        row_result_type=result_type,
                        local_declarations=local_declarations,
                        proposition_aliases=row_proposition_aliases,
                        proposition_heads=proposition_heads,
                        predicate_bound_names=predicate_scope,
                        row_bound_names=row_free_names,
                        dependency_declarations=row_dependency_declarations,
                    )
                    if subtype_domain.expansion_complete
                    else []
                )
                carrier_is_data = (
                    subtype_domain.expansion_complete
                    and is_definitely_data_type(
                        subtype_domain.carrier_type,
                        proposition_heads=proposition_heads,
                        data_heads=row_data_heads,
                    )
                )
                semantic_data_only = bool(
                    subtype_domain.expansion_complete
                    and row_dependency_graph_complete
                    and carrier_is_data
                    and not predicate_relation
                    and not predicate_expansion.blocked_routes
                    and not carrier_record_dependencies
                    and not predicate_record_dependencies
                    and not predicate_record_binder_dependencies
                    and not predicate_result_bridges
                )
                items.append(
                    {
                        "judgment_key": boundary_input_judgment_key(row, visible_input),
                        "row": row,
                        "binder": binder_names_text,
                        "binder_type": input_type,
                        "expanded_binder_type": subtype_domain.expanded_type,
                        "row_result_type": result_type,
                        "kind": "transparent_subtype_domain_input",
                        "subtype_expansion_origin": subtype_domain.expansion_origin,
                        "subtype_expansion_steps": list(subtype_domain.expansion_steps),
                        "subtype_expansion_complete": subtype_domain.expansion_complete,
                        "subtype_expansion_error": subtype_domain.expansion_error,
                        "subtype_value_binder": subtype_domain.value_binder,
                        "expanded_subtype_carrier_type": subtype_domain.carrier_type,
                        "expanded_subtype_predicate": predicate_expansion.expanded_type,
                        "original_subtype_predicate": subtype_domain.predicate,
                        "subtype_predicate_proposition_alias_expansion": {
                            "expanded_type": predicate_expansion.expanded_type,
                            "transparent_steps": predicate_expansion.steps,
                            "blocked_routes": predicate_expansion.blocked_routes,
                        },
                        "subtype_predicate_result_relation": predicate_relation,
                        "subtype_carrier_is_definitely_data": carrier_is_data,
                        "subtype_carrier_record_dependencies": carrier_record_dependencies,
                        "subtype_predicate_record_dependencies": predicate_record_dependencies,
                        "subtype_predicate_record_binder_dependencies": (
                            predicate_record_binder_dependencies
                        ),
                        "subtype_predicate_result_bridges": predicate_result_bridges,
                        "elaborated_dependency_graph_complete": (
                            row_dependency_graph_complete
                        ),
                        # This is only the structural verdict. The later
                        # source-contract association adds the required
                        # byte-pinned restricted-domain context before the
                        # item can become nonpropositional witness data.
                        "subtype_domain_semantic_data_only": semantic_data_only,
                        "domain_data_only": False,
                        "subtype_domain_source_context": {
                            "schema": TRANSPARENT_SUBTYPE_DOMAIN_CONTEXT_SCHEMA,
                            "required_kind": RESTRICTED_SUBTYPE_DOMAIN_CONTEXT_KIND,
                            "status": "missing",
                            "failure_reasons": [
                                "awaiting an exact source association with a byte-pinned restricted subtype-domain context"
                            ],
                            "selected_contexts": [],
                        },
                        **(
                            {
                                "local_type_head": subtype_domain.local_type_head,
                                "local_type_source": subtype_domain.local_type_source,
                            }
                            if subtype_domain.local_type_head
                            else {}
                        ),
                        "conclusion_fields": [],
                        "valid_constructors": [],
                        "rejected_constructors": [],
                        "conditional_constructors": [],
                        "required_check": "This binder transparently expands to a subtype. "
                        "Audit its expanded carrier and stored predicate structurally; "
                        "it is nonpropositional domain data only after the predicate has no "
                        "result relation, no blocked local proposition route, and no record "
                        "dependency or proof-dependency bridge to the result, and an exact "
                        "source route supplies byte-pinned "
                        "`restricted_subtype_domain` context for the restriction.",
                    }
                )
                # A later dependent subtype predicate can reach the carrier's
                # record fields through this binder, so retain it in lexical
                # scope even though the outer binder itself is a Subtype.
                if carrier_record_dependencies:
                    record_binder_names.update(binder_names(binder_names_text))
                continue

            input_is_data = is_definitely_data_type(
                expanded_input_type,
                proposition_heads=proposition_heads,
                data_heads=row_data_heads,
            )

            direct_result_relation = (
                proposition_type_relation(
                    expanded_input_type, result_type, row_proposition_aliases
                )
                if not input_is_data
                else ""
            )
            direct_conclusion_input = (
                direct_result_relation in RESULT_BEARING_RELATIONS
            )
            result_bridges: list[dict[str, Any]] = []
            if (
                not direct_conclusion_input
                and not input_is_data
                and canonical_type(expanded_input_type) != canonical_type(input_type)
            ):
                result_bridges = proposition_input_result_bridges(
                    reviewed_declaration=row_qualified_names.get(row, row),
                    # The bridge search follows a declaration's actual input
                    # type. Its semantic relation is checked after alias
                    # expansion, but searching only the expanded formula would
                    # miss a theorem whose source signature consumes the local
                    # transparent alias.
                    input_type=input_type,
                    row_result_type=result_type,
                    local_declarations=local_declarations,
                    proposition_aliases=row_proposition_aliases,
                    dependency_declarations=row_dependency_declarations,
                )
            if direct_conclusion_input or result_bridges:
                valid, rejected = constructor_candidates(
                    local_declarations=local_declarations,
                    excluded_declaration=row_qualified_names.get(row, row),
                    target_type=input_type,
                    target_structures=set(),
                    forbidden_input_structures=None,
                    aliases=aliases,
                    conclusion_fields=[],
                    row_result_type=result_type,
                    structures=structures,
                    proposition_heads=proposition_heads,
                    proposition_aliases=row_proposition_aliases,
                    data_heads=row_data_heads,
                    semantic_declarations=semantic_declarations,
                    target_free_names=row_free_names,
                    dependency_manifest=row_manifest,
                )
                circular = [candidate for candidate in rejected if candidate.circular_inputs]
                conditional = [
                    candidate
                    for candidate in rejected
                    if not candidate.circular_inputs and candidate.conditional_inputs
                ]
                items.append(
                    {
                        "judgment_key": boundary_input_judgment_key(row, visible_input),
                        "row": row,
                        "binder": binder_names_text,
                        "binder_type": input_type,
                        "expanded_binder_type": expanded_input_type,
                        "row_result_type": result_type,
                        **proposition_alias_expansion_payload(alias_expansion),
                        "kind": (
                            "direct_conclusion_input"
                            if direct_conclusion_input
                            else "aliased_conclusion_bridge_input"
                        ),
                        **(
                            {"result_relation": direct_result_relation}
                            if direct_conclusion_input
                            else {}
                        ),
                        "result_bridges": result_bridges,
                        "conclusion_fields": [],
                        "valid_constructors": [asdict(item) for item in valid],
                        "rejected_constructors": [asdict(item) for item in circular],
                        "conditional_constructors": [asdict(item) for item in conditional],
                        "required_check": (
                            "A reviewed theorem accepts its own conclusion, a provider of "
                            "that conclusion, or a logical component of the advertised "
                            "result. It must have a paper-local non-circular proof from "
                            "source primitives or be exposed as an exact source-domain "
                            "antecedent; an identity wrapper or renamed premise is not a "
                            "derivation."
                            if direct_conclusion_input
                            else
                            "A reviewed theorem consumes a transparent proposition alias and "
                            "a referenced paper-local proof converts that premise into all or "
                            "part of the advertised result. Audit the delta-expanded premise; "
                            "the alias spelling and the bridge declaration name are not source "
                            "evidence."
                        ),
                    }
                )

            input_records = mentioned_structures(
                expanded_input_type,
                set(row_records.get(row, [])),
                aliases,
                context_namespace=context_namespace,
                shadowed_names=input_scope,
                structure_parameter_counts=candidate_structure_parameter_counts,
            )
            for root_structure in input_records:
                root_fields = fields_by_root.get(root_structure, [])
                root_field_keys = {
                    (field.structure, field.field) for field in root_fields
                }
                instantiated_root_fields = [
                    field
                    for field in recursively_collect_instantiated_fields(
                        root_structure,
                        expanded_input_type,
                        structures,
                        aliases,
                        shadowed_names=input_scope,
                    )
                    if (field.structure, field.field) in root_field_keys
                ]
                if instantiated_root_fields:
                    root_fields = instantiated_root_fields
                conclusion_fields: list[FieldInfo] = []
                hidden_subtype_predicates: dict[tuple[str, str], str] = {}
                for field in root_fields:
                    if field.nested_structures:
                        continue
                    current_data_heads = field_data_heads(
                        field, structures, row_data_heads
                    )
                    hidden_subtype_predicate = local_reducible_subtype_type_predicate(
                        field.type,
                        semantic_declarations,
                        aliases,
                        structures,
                        context_namespace=context_namespace,
                        proposition_heads=proposition_heads,
                        data_heads=current_data_heads,
                        shadowed_names=input_scope,
                        subtype_alias_heads=subtype_alias_heads,
                    )
                    if hidden_subtype_predicate:
                        hidden_subtype_predicates[(field.structure, field.field)] = (
                            hidden_subtype_predicate
                        )
                        conclusion_fields.append(field)
                        continue
                    if is_definitely_data_type(
                        field.type,
                        proposition_heads=proposition_heads,
                        data_heads=current_data_heads,
                    ):
                        continue
                    conclusion_fields.append(field)
                if not conclusion_fields:
                    continue
                nested_structures = {root_structure}
                for field in root_fields:
                    nested_structures.update(field.nested_structures)
                valid, rejected = constructor_candidates(
                    local_declarations=local_declarations,
                    excluded_declaration=row_qualified_names.get(row, row),
                    target_type=expanded_input_type,
                    target_structures={root_structure},
                    forbidden_input_structures=nested_structures,
                    aliases=aliases,
                    conclusion_fields=conclusion_fields,
                    row_result_type=result_type,
                    structures=structures,
                    proposition_heads=proposition_heads,
                    proposition_aliases=proposition_aliases,
                    data_heads=row_data_heads,
                    semantic_declarations=semantic_declarations,
                    target_free_names=row_free_names,
                    dependency_manifest=row_manifest,
                )
                circular = [candidate for candidate in rejected if candidate.circular_inputs]
                conditional = [
                    candidate
                    for candidate in rejected
                    if not candidate.circular_inputs and candidate.conditional_inputs
                ]
                fully_qualified_record_type = (
                    fully_qualified_record_input_type_surface(
                        expanded_input_type, root_structure
                    )
                )
                if not fully_qualified_record_type:
                    fully_qualified_record_type = (
                        fully_qualified_record_input_type_from_elaborated_binder(
                            visible_inputs=row_inputs.get(row, []),
                            visible_input_index=visible_input_index,
                            manifest=row_manifest,
                            reviewed_declaration=row_qualified_names.get(row, row),
                            record_root=root_structure,
                            structure_aliases=aliases,
                        )
                    )
                items.append(
                    {
                        "judgment_key": boundary_input_judgment_key(row, visible_input),
                        "row": row,
                        "binder": binder_names_text,
                        "binder_type": input_type,
                        "original_binder_type": input_type,
                        "expanded_binder_type": expanded_input_type,
                        "row_result_type": result_type,
                        **proposition_alias_expansion_payload(alias_expansion),
                        "kind": "record_conclusion_input",
                        "record": root_structure,
                        "elaborated_outer_binder_atoms": input_atom_receipts.get(
                            visible_input_index, []
                        ),
                        "fully_qualified_expanded_binder_type_canonical": (
                            fully_qualified_record_type
                        ),
                        "record_aliases": sorted(names_for_structure(root_structure, aliases) - {root_structure}),
                        "conclusion_fields": [
                            {
                                "judgment_key": f"{field.structure}.{field.field}",
                                "path": field.path,
                                "type": field.type,
                                **(
                                    {
                                        "hidden_subtype_predicate": hidden_subtype_predicates[
                                            (field.structure, field.field)
                                        ]
                                    }
                                    if (field.structure, field.field)
                                    in hidden_subtype_predicates
                                    else {}
                                ),
                                "source_file": field.source_file,
                                "line": field.line,
                                "relation_to_row_result": proposition_type_relation(
                                    hidden_subtype_predicates.get(
                                        (field.structure, field.field), field.type
                                    ),
                                    result_type,
                                    proposition_aliases,
                                ),
                                "source_antecedent_eligible": (
                                    field_reached_through_function_antecedent(
                                        root_structure,
                                        field,
                                        structures,
                                        aliases,
                                    )
                                    or not bool(
                                        proposition_type_relation(
                                            hidden_subtype_predicates.get(
                                                (field.structure, field.field),
                                                field.type,
                                            ),
                                            result_type,
                                            proposition_aliases,
                                        )
                                    )
                                ),
                                "semantic_kind": (
                                    "proposition"
                                    if (field.structure, field.field)
                                    in hidden_subtype_predicates
                                    or (
                                        is_proposition_type(
                                            field.type,
                                            proposition_heads,
                                            current_data_heads,
                                        )
                                        and not is_definitely_data_type(
                                            field.type,
                                            proposition_heads=proposition_heads,
                                            data_heads=current_data_heads,
                                        )
                                    )
                                    else "unknown_nondata"
                                ),
                            }
                            for field in conclusion_fields
                        ],
                        "valid_constructors": [asdict(item) for item in valid],
                        "rejected_constructors": [asdict(item) for item in circular],
                        "conditional_constructors": [asdict(item) for item in conditional],
                        "required_check": "This theorem consumes a record/certificate with "
                        "conclusion-bearing fields. A fresh paper-local builder of the same record "
                        "type does not identify this caller-supplied record. Its proposition-bearing "
                        "fields need current exact source-antecedent judgments (or an explicit "
                        "reviewed equality/reconstruction bridge); alpha-equivalent/provider fields "
                        "are circular.",
                    }
                )

            if mentioned_structures(
                expanded_input_type,
                set(structures),
                aliases,
                context_namespace=context_namespace,
                shadowed_names=input_scope,
                structure_parameter_counts=candidate_structure_parameter_counts,
            ):
                record_binder_names.update(binder_names(binder_names_text))

            if (
                not input_records
                and not is_proposition_type(expanded_input_type, proposition_heads)
                and split_top_level_arrow(normalize_ws(expanded_input_type).strip()) is None
            ):
                hidden_head = unresolved_local_reducible_type_head(
                    expanded_input_type,
                    semantic_declarations,
                    aliases,
                    structures,
                    context_namespace=context_namespace,
                    proposition_heads=proposition_heads,
                    data_heads=row_data_heads,
                    shadowed_names=input_scope,
                )
                if hidden_head is not None:
                    items.append(
                        {
                            "judgment_key": boundary_input_judgment_key(row, visible_input),
                            "row": row,
                            "binder": binder_names_text,
                            "binder_type": input_type,
                            "original_binder_type": input_type,
                            "expanded_binder_type": expanded_input_type,
                            "row_result_type": result_type,
                            **proposition_alias_expansion_payload(alias_expansion),
                            "kind": "unexpanded_local_reducible_type_input",
                            "local_type_head": hidden_head.name,
                            "local_type_source": hidden_head.source,
                            "conclusion_fields": [],
                            "valid_constructors": [],
                            "rejected_constructors": [],
                            "conditional_constructors": [],
                            "required_check": "The binder type is headed by a local reducible "
                            "definition that the static record traversal cannot normalize. It "
                            "may conceal proposition-bearing record fields, so this row fails "
                            "closed until the binder is exposed through a direct audited type/alias "
                            "or a Lean-Meta expansion is added.",
                        }
                    )
                    continue
                if input_is_data:
                    continue
    return items


def source_input_binder_name(
    row_inputs: dict[str, list[dict[str, str]]],
    item: dict[str, Any],
) -> str | None:
    """Return one exact source binder spelling for Lean-Meta lookup.

    This spelling only routes the request to the reviewed binder. Acceptance of
    a constructor route is subsequently decided by Lean Meta on the elaborated
    binder/result types, rather than by this source spelling or declaration
    names. Grouped or synthetic inputs fail closed rather than guessing a
    telescope position after transparent result-type reduction.
    """

    row = str(item.get("row") or "").strip()
    binder = str(item.get("binder") or "").strip()
    binder_type = str(item.get("binder_type") or "").strip()
    if not row or not binder or not binder_type:
        return None
    for visible_input in row_inputs.get(row, []):
        names = str(visible_input.get("names") or "").strip()
        input_type = str(visible_input.get("type") or "").strip()
        names_in_input = binder_names(names)
        if names == binder and input_type == binder_type:
            return names_in_input[0] if len(names_in_input) == 1 else None
    return None


def enforce_elaborated_constructor_result_types(
    *,
    root: Path,
    import_module: str,
    review_source_path: Path,
    conclusion_dependencies: list[dict[str, Any]],
    row_inputs: dict[str, list[dict[str, str]]],
    row_qualified_names: dict[str, str],
    diagnostics_out: dict[str, Any] | None = None,
) -> str:
    """Remove static constructor routes without a matching Lean-Meta result.

    Static source parsing can discover a constructor candidate, but it cannot
    establish that the candidate's result preserves every instantiated record
    parameter.  In particular, matching only a record head would allow a
    fixed `Record 0` witness to discharge a binder of type `Record n`.  Every
    discovered candidate is therefore checked against the exact elaborated
    reviewed binder. Missing or malformed Meta output is a failed route, not a
    provisional success.
    """

    bucket_names = (
        "valid_constructors",
        "conditional_constructors",
        "rejected_constructors",
    )
    routes: set[tuple[str, str, str]] = set()
    item_routes: dict[int, tuple[str, str] | None] = {}
    for item in conclusion_dependencies:
        row = str(item.get("row") or "").strip()
        reviewed = str(row_qualified_names.get(row) or row).strip()
        binder_name = source_input_binder_name(row_inputs, item)
        if not reviewed or binder_name is None:
            item_routes[id(item)] = None
            continue
        item_routes[id(item)] = (reviewed, binder_name)
        for bucket_name in bucket_names:
            for candidate in item.get(bucket_name) or []:
                if not isinstance(candidate, dict):
                    continue
                candidate_name = str(candidate.get("declaration") or "").strip()
                if candidate_name:
                    routes.add((reviewed, binder_name, candidate_name))

    matches: dict[tuple[str, str, str], bool] = {}
    error = ""
    if routes:
        try:
            from scripts.lean_signature_manifest import (
                run_lean_constructor_result_type_matches,
            )

            matches = run_lean_constructor_result_type_matches(
                root,
                import_module,
                sorted(routes),
                review_source_path=review_source_path,
                timeout_seconds=180,
                build_timeout_seconds=600,
                diagnostics_out=diagnostics_out,
            )
        except Exception as exc:  # noqa: BLE001 - callers fail closed below.
            error = (
                "Lean constructor-result compatibility check raised "
                f"{type(exc).__name__}: {exc}"
            )
        if not error and set(matches) != routes:
            error = (
                "Lean constructor-result compatibility check did not return one "
                "elaborated verdict per static constructor route"
            )

    for item in conclusion_dependencies:
        item_route = item_routes.get(id(item))
        incompatible: list[dict[str, Any]] = []
        checked_any = False
        for bucket_name in bucket_names:
            retained: list[dict[str, Any]] = []
            for raw_candidate in item.get(bucket_name) or []:
                if not isinstance(raw_candidate, dict):
                    continue
                candidate = dict(raw_candidate)
                candidate_name = str(candidate.get("declaration") or "").strip()
                checked_any = True
                if item_route is None or not candidate_name:
                    result_check = {
                        "method": "lean_meta_definitional_equality",
                        "matches": False,
                        "reason": "reviewed source binder could not be mapped to one exact elaborated Lean binder",
                    }
                else:
                    reviewed, binder_name = item_route
                    route = (reviewed, binder_name, candidate_name)
                    result_check = {
                        "method": "lean_meta_definitional_equality",
                        "reviewed_declaration": reviewed,
                        "reviewed_binder": binder_name,
                        "matches": matches.get(route, False),
                    }
                    if route not in matches:
                        result_check["reason"] = (
                            error
                            or "Lean constructor-result compatibility verdict is missing"
                        )
                candidate["result_type_compatibility"] = result_check
                if result_check["matches"]:
                    retained.append(candidate)
                else:
                    incompatible.append(
                        {"original_classification": bucket_name, **candidate}
                    )
            item[bucket_name] = retained
        if checked_any:
            item["constructor_result_type_check_schema"] = 1
            item["incompatible_constructors"] = incompatible
    return error


def lean_check(
    root: Path,
    paper_id: str,
    interface_path: Path,
    import_module: str,
    row_namespace: str,
    row_names: list[str],
    assumption_row_names: set[str],
    qualified_row_refs: dict[str, str],
    fields: list[FieldInfo],
    max_output_chars: int,
    diagnose_failed_rows: bool = False,
    assumption_path: Path | None = None,
    proof_source_path: Path | None = None,
) -> dict[str, Any]:
    requested_checked_rows = [
        {
            "row": name,
            "qualified_declaration": qualified_row_refs.get(
                name, f"{row_namespace}.{name}" if row_namespace else name
            ),
        }
        for name in row_names
    ]
    if not row_names and not fields:
        return {
            "command": "skipped Lean check: no source-record rows or fields",
            "returncode": 0,
            "truncated": False,
            "output": "",
            "requested_checked_rows": requested_checked_rows,
            "checked_rows": requested_checked_rows,
        }

    if not interface_path.exists():
        return {
            "command": "source-record current-interface elaboration",
            "returncode": 1,
            "truncated": False,
            "output": f"missing current PaperInterface source at {interface_path}",
        }

    try:
        interface_display = str(interface_path.relative_to(root))
    except ValueError:
        interface_display = str(interface_path)
    interface_sha256 = hashlib.sha256(interface_path.read_bytes()).hexdigest()
    interface_module = lean_module_name(root, interface_path)
    proof_module = ""
    proof_display = ""
    proof_sha256 = ""
    if proof_source_path is not None:
        if not proof_source_path.exists():
            return {
                "command": "source-record current-proof-endpoint elaboration",
                "returncode": 1,
                "truncated": False,
                "output": f"missing configured ProofInterface source at {proof_source_path}",
            }
        proof_module = lean_module_name(root, proof_source_path)
        try:
            proof_display = str(proof_source_path.relative_to(root))
        except ValueError:
            proof_display = str(proof_source_path)
        proof_sha256 = hashlib.sha256(proof_source_path.read_bytes()).hexdigest()

    expected_import_module = proof_module or interface_module
    if import_module != expected_import_module:
        return {
            "command": "source-record complete-review import preflight",
            "returncode": 1,
            "truncated": False,
            "output": (
                "generated review checks must import the smallest module that "
                "exposes every configured semantic Spec and proof endpoint: "
                f"{import_module} != {expected_import_module}"
            ),
        }

    # A bare target with the paper/library name can select Lake's library
    # target and reuse a stale module artifact.  Force the exact import module.
    build_target = f"+{import_module}"
    build_proc = run_source_record_subprocess(
        ["lake", "build", build_target],
        cwd=root,
        phase=f"Lake build of {build_target}",
        timeout_seconds=SOURCE_RECORD_LAKE_BUILD_TIMEOUT_SECONDS,
    )
    if build_proc.returncode != 0:
        output = build_proc.stdout
        truncated = len(output) > max_output_chars
        if truncated:
            output = output[:max_output_chars] + "\n[truncated]\n"
        return {
            "command": f"lake build {build_target}",
            "returncode": build_proc.returncode,
            "truncated": truncated,
            "output": output,
        }

    # Do not let an incremental Lake build turn this into a check of an older
    # module with the same name.  Static source-record expansion is performed
    # from the configured semantic and proof sources above, so the Lean check
    # must elaborate those exact files too.  Stage the paper namespace's built
    # dependencies in a temporary overlay, remove old artifacts for the review
    # modules, then elaborate the current sources in dependency order.  The
    # generated `#check` script imports the overlay before the ordinary build
    # directory.
    artifact_library = root / ".lake" / "build" / "lib" / "lean"
    module_parts = [part for part in import_module.split(".") if part]
    interface_module_parts = [part for part in interface_module.split(".") if part]
    if not module_parts:
        return {
            "command": "source-record current-interface elaboration",
            "returncode": 1,
            "truncated": False,
            "output": f"invalid complete-review module name {import_module!r}",
        }
    namespace_artifacts = artifact_library / module_parts[0]
    if not namespace_artifacts.is_dir():
        return {
            "command": f"lake build {build_target}",
            "returncode": 1,
            "truncated": False,
            "output": (
                "Lake reported a successful build but did not produce the paper namespace "
                f"artifact directory {namespace_artifacts}; cannot verify current "
                "complete review surface against fresh isolated artifacts"
            ),
        }

    # Selected source assumptions are reviewed rows too.  The isolated overlay
    # below compiles their configured current source, so import that module in
    # the generated check rather than accidentally relying on a transitive
    # PaperInterface import.  The sibling fallback preserves callers of this
    # helper that predate configurable assumption surfaces.
    selected_assumptions_path = assumption_path or interface_path.parent / "Assumptions.lean"
    assumption_module = ""
    if assumption_row_names and selected_assumptions_path.exists():
        assumption_module = lean_module_name(root, selected_assumptions_path)

    script_preamble = [f"import {import_module}"]
    if assumption_module:
        script_preamble.append(f"import {assumption_module}")
    script_preamble.append("")
    if row_namespace:
        root_namespace = row_namespace.split(".")[0]
        script_preamble.append(f"open {root_namespace}")
        script_preamble.append("")

    def row_ref(name: str) -> str:
        qualified = qualified_row_refs.get(name)
        if qualified:
            return qualified
        return f"{row_namespace}.{name}" if row_namespace else name

    def check_script(names: list[str]) -> str:
        lines = list(script_preamble)
        for name in names:
            lines.append(f"#check {row_ref(name)}")
        return "\n".join(lines) + "\n"

    # `audit_repository.py` performs the authoritative transitive
    # `#print axioms` pass for every configured PaperInterface row. Repeating
    # it here does not add source-record evidence, but is prohibitively slow
    # for measure-theoretic interfaces. This helper still asks Lean to resolve
    # every reviewed declaration before the static recursive traversal is used.
    # Field declarations are parsed directly from Lean source.  Standalone
    # projection constants are brittle under namespace aliases even when the
    # paper-facing row elaborates dot projections successfully.
    script = check_script(row_names)
    try:
        staging_root = source_record_isolated_staging_root(root)
    except OSError as exc:
        return {
            "command": "source-record current-interface elaboration",
            "returncode": 1,
            "truncated": False,
            "output": "could not prepare isolated worktree staging root: " + str(exc),
        }
    with tempfile.TemporaryDirectory(
        prefix="source-record-fresh-", dir=staging_root
    ) as tmpdir:
        overlay_root = Path(tmpdir)
        try:
            shutil.copytree(
                namespace_artifacts,
                overlay_root / module_parts[0],
                copy_function=source_record_hardlink_or_copy,
            )
        except OSError as exc:
            return {
                "command": f"lake build {build_target}",
                "returncode": 1,
                "truncated": False,
                "output": (
                    "could not stage paper namespace artifacts for current-source "
                    f"verification: {exc}"
                ),
            }

        lake_env_proc = run_source_record_subprocess(
            ["lake", "env"],
            cwd=root,
            phase="Lake environment discovery",
            timeout_seconds=SOURCE_RECORD_LAKE_ENV_TIMEOUT_SECONDS,
        )
        if lake_env_proc.returncode != 0:
            output = lake_env_proc.stdout
            truncated = len(output) > max_output_chars
            if truncated:
                output = output[:max_output_chars] + "\n[truncated]\n"
            return {
                "command": "lake env",
                "returncode": lake_env_proc.returncode,
                "truncated": truncated,
                "output": output,
            }
        base_lean_path = ""
        for line in lake_env_proc.stdout.splitlines():
            if line.startswith("LEAN_PATH="):
                base_lean_path = line.removeprefix("LEAN_PATH=")
                break
        if not base_lean_path:
            return {
                "command": "lake env",
                "returncode": 1,
                "truncated": False,
                "output": (
                    "lake env did not provide LEAN_PATH; cannot import freshly "
                    "elaborated reviewed-source artifacts"
                ),
            }

        interface_artifact = overlay_root.joinpath(*interface_module_parts)
        interface_artifact.parent.mkdir(parents=True, exist_ok=True)
        def remove_overlay_artifact(artifact: Path) -> None:
            """Ensure a failed fresh source pass cannot fall back to copied output."""

            for suffix in (
                ".olean",
                ".ilean",
                ".olean.hash",
                ".ilean.hash",
                ".trace",
                ".c",
            ):
                artifact.with_suffix(suffix).unlink(missing_ok=True)

        fresh_assumption_sources: list[dict[str, Any]] = []
        if assumption_row_names:
            if not selected_assumptions_path.exists():
                return {
                    "command": "source-record current-assumptions elaboration",
                    "returncode": 1,
                    "truncated": False,
                    "output": (
                        "selected assumption-source rows exist but current source is missing at "
                        f"{selected_assumptions_path}"
                    ),
                }
            assumption_module = lean_module_name(root, selected_assumptions_path)
            assumption_artifact = overlay_root.joinpath(
                *[part for part in assumption_module.split(".") if part]
            )
            assumption_artifact.parent.mkdir(parents=True, exist_ok=True)
            remove_overlay_artifact(assumption_artifact)
            assumption_proc = run_source_record_subprocess(
                [
                    "lake",
                    "env",
                    "env",
                    f"LEAN_PATH={overlay_root}{os.pathsep}{base_lean_path}",
                    "lean",
                    "--root",
                    str(root),
                    "-o",
                    str(assumption_artifact.with_suffix(".olean")),
                    "-i",
                    str(assumption_artifact.with_suffix(".ilean")),
                    str(selected_assumptions_path),
                ],
                cwd=root,
                phase="fresh configured assumption-source elaboration",
                timeout_seconds=SOURCE_RECORD_LEAN_ELABORATION_TIMEOUT_SECONDS,
            )
            assumption_identity = source_artifact_identity(
                root, selected_assumptions_path
            )
            assumption_metadata = {
                "source_file": assumption_identity["path"],
                "source_sha256": assumption_identity["sha256"],
                "isolated_artifact": f"{assumption_module}.olean",
                "returncode": assumption_proc.returncode,
            }
            fresh_assumption_sources.append(assumption_metadata)
            assumption_output = assumption_proc.stdout
            assumption_truncated = len(assumption_output) > max_output_chars
            if assumption_truncated:
                assumption_output = assumption_output[:max_output_chars] + "\n[truncated]\n"
            if (
                assumption_proc.returncode != 0
                or not assumption_artifact.with_suffix(".olean").is_file()
            ):
                return {
                    "command": (
                        "lake env env LEAN_PATH=<isolated>:<lake-lean-path> lean "
                        "--root <repository-root> -o <isolated assumptions artifact> "
                        "<configured-assumption-source.lean>"
                    ),
                    "returncode": assumption_proc.returncode or 1,
                    "truncated": assumption_truncated,
                    "output": assumption_output,
                    "fresh_source_elaboration": {
                        "mode": "isolated_temp_overlay",
                        "source_file": interface_display,
                        "source_sha256": interface_sha256,
                        "artifact_path_mode": "temporary_overlay_precedes_lake_build",
                        "selected_assumption_sources": fresh_assumption_sources,
                    },
                }

        # A failed fresh elaboration must never leave a copied stale interface
        # artifact available for the following import check.
        remove_overlay_artifact(interface_artifact)

        fresh_source_proc = run_source_record_subprocess(
            [
                "lake",
                "env",
                "env",
                f"LEAN_PATH={overlay_root}{os.pathsep}{base_lean_path}",
                "lean",
                "--root",
                str(root),
                "-o",
                str(interface_artifact.with_suffix(".olean")),
                "-i",
                str(interface_artifact.with_suffix(".ilean")),
                str(interface_path),
            ],
            cwd=root,
            phase="fresh PaperInterface.lean elaboration",
            timeout_seconds=SOURCE_RECORD_LEAN_ELABORATION_TIMEOUT_SECONDS,
        )
        fresh_source_metadata = {
            "mode": "isolated_temp_overlay",
            "source_file": interface_display,
            "source_sha256": interface_sha256,
            "isolated_artifact": f"{interface_module}.olean",
            "artifact_path_mode": "temporary_overlay_precedes_lake_build",
            "selected_assumption_sources": fresh_assumption_sources,
            "returncode": fresh_source_proc.returncode,
        }
        fresh_output = fresh_source_proc.stdout
        fresh_truncated = len(fresh_output) > max_output_chars
        if fresh_truncated:
            fresh_output = fresh_output[:max_output_chars] + "\n[truncated]\n"
        if fresh_source_proc.returncode != 0:
            return {
                "command": (
                    f"lake build {build_target} && lake env lean --root "
                    f"<repository-root> -o <isolated {import_module}.olean> "
                    f"{interface_display}"
                ),
                "returncode": fresh_source_proc.returncode,
                "truncated": fresh_truncated,
                "output": fresh_output,
                "source_elaboration": fresh_source_metadata,
                "fresh_source_elaboration": fresh_source_metadata,
            }
        if not interface_artifact.with_suffix(".olean").is_file():
            return {
                "command": "source-record current-interface elaboration",
                "returncode": 1,
                "truncated": False,
                "output": (
                    "current PaperInterface elaboration returned success without producing "
                    f"isolated artifact {interface_module}.olean"
                ),
                "source_elaboration": fresh_source_metadata,
                "fresh_source_elaboration": fresh_source_metadata,
            }

        # A separate proof endpoint imports PaperInterface.  Compile it only
        # after the exact current interface artifact exists in the isolated
        # overlay, then import that proof module in the generated row check.
        # This follows Lean's dependency direction and prevents either side of
        # the Spec/proof pair from being read from an older build artifact.
        fresh_proof_sources: list[dict[str, Any]] = []
        if proof_source_path is not None:
            proof_module_parts = [
                part for part in proof_module.split(".") if part
            ]
            proof_artifact = overlay_root.joinpath(*proof_module_parts)
            proof_artifact.parent.mkdir(parents=True, exist_ok=True)
            remove_overlay_artifact(proof_artifact)
            proof_proc = run_source_record_subprocess(
                [
                    "lake",
                    "env",
                    "env",
                    f"LEAN_PATH={overlay_root}{os.pathsep}{base_lean_path}",
                    "lean",
                    "--root",
                    str(root),
                    "-o",
                    str(proof_artifact.with_suffix(".olean")),
                    "-i",
                    str(proof_artifact.with_suffix(".ilean")),
                    str(proof_source_path),
                ],
                cwd=root,
                phase="fresh ProofInterface.lean elaboration",
                timeout_seconds=SOURCE_RECORD_LEAN_ELABORATION_TIMEOUT_SECONDS,
            )
            proof_metadata = {
                "source_file": proof_display,
                "source_sha256": proof_sha256,
                "isolated_artifact": f"{proof_module}.olean",
                "returncode": proof_proc.returncode,
            }
            fresh_proof_sources.append(proof_metadata)
            fresh_source_metadata["selected_proof_endpoint_sources"] = (
                fresh_proof_sources
            )
            proof_output = proof_proc.stdout
            proof_truncated = len(proof_output) > max_output_chars
            if proof_truncated:
                proof_output = proof_output[:max_output_chars] + "\n[truncated]\n"
            if (
                proof_proc.returncode != 0
                or not proof_artifact.with_suffix(".olean").is_file()
            ):
                return {
                    "command": (
                        f"lake build {build_target} && lake env lean --root "
                        f"<repository-root> -o <isolated {proof_module}.olean> "
                        f"{proof_display}"
                    ),
                    "returncode": proof_proc.returncode or 1,
                    "truncated": proof_truncated,
                    "output": proof_output,
                    "source_elaboration": fresh_source_metadata,
                    "fresh_source_elaboration": fresh_source_metadata,
                }

        script_path = overlay_root / "source_record_check.lean"
        script_path.write_text(script, encoding="utf-8")
        proc = run_source_record_subprocess(
            [
                "lake",
                "env",
                "env",
                f"LEAN_PATH={overlay_root}{os.pathsep}{base_lean_path}",
                "lean",
                str(script_path),
            ],
            cwd=root,
            phase="generated complete-review row check",
            timeout_seconds=SOURCE_RECORD_LEAN_CHECK_TIMEOUT_SECONDS,
        )
        failed_checked_rows: list[dict[str, Any]] = []
        row_check_diagnostic_error = ""
        if diagnose_failed_rows and proc.returncode != 0 and row_names:
            if proc.returncode in {124, 125}:
                row_check_diagnostic_error = (
                    "batch generated complete-review row check did not complete; "
                    "row-local checks were not launched"
                )
            else:
                # First separate a broken generated/import environment from a
                # bad configured declaration.  Only the latter has a truthful
                # row-local diagnosis; do not label every row failed merely
                # because the isolated overlay itself could not import.
                base_script_path = overlay_root / "source_record_check_base.lean"
                base_script_path.write_text(check_script([]), encoding="utf-8")
                base_proc = run_source_record_subprocess(
                    [
                        "lake",
                        "env",
                        "env",
                        f"LEAN_PATH={overlay_root}{os.pathsep}{base_lean_path}",
                        "lean",
                        str(base_script_path),
                    ],
                    cwd=root,
                    phase="generated complete-review preflight import check",
                    timeout_seconds=SOURCE_RECORD_LEAN_CHECK_TIMEOUT_SECONDS,
                )
                if base_proc.returncode != 0:
                    row_check_diagnostic_error = (
                        "generated complete-review preflight could not import the "
                        "fresh isolated review surface; row-local declaration "
                        "failures are unavailable"
                    )
                else:
                    for row_index, name in enumerate(row_names):
                        row_script_path = (
                            overlay_root / f"source_record_check_row_{row_index}.lean"
                        )
                        row_script_path.write_text(
                            check_script([name]), encoding="utf-8"
                        )
                        row_proc = run_source_record_subprocess(
                            [
                                "lake",
                                "env",
                                "env",
                                f"LEAN_PATH={overlay_root}{os.pathsep}{base_lean_path}",
                                "lean",
                                str(row_script_path),
                            ],
                            cwd=root,
                            phase=(
                                "configured PaperInterface declaration preflight: "
                                f"{name}"
                            ),
                            timeout_seconds=SOURCE_RECORD_LEAN_CHECK_TIMEOUT_SECONDS,
                        )
                        if row_proc.returncode == 0:
                            continue
                        row_output = row_proc.stdout
                        row_truncated = len(row_output) > min(max_output_chars, 16000)
                        if row_truncated:
                            row_output = (
                                row_output[: min(max_output_chars, 16000)]
                                + "\n[truncated]\n"
                            )
                        failed_checked_rows.append(
                            {
                                "row": name,
                                "qualified_declaration": row_ref(name),
                                "returncode": row_proc.returncode,
                                "truncated": row_truncated,
                                "output": row_output,
                            }
                        )
    output = proc.stdout
    truncated = len(output) > max_output_chars
    if truncated:
        output = output[:max_output_chars] + "\n[truncated]\n"
    result = {
        "command": (
            f"lake build {build_target} && [configured semantic interface"
            + (" and proof endpoint" if proof_source_path is not None else "")
            + " -> isolated overlay] && lake env env "
            "LEAN_PATH=<isolated>:<lake-lean-path> lean "
            "<generated-source-record-audit-script>"
        ),
        "returncode": proc.returncode,
        "truncated": truncated,
        "output": output,
        "requested_checked_rows": requested_checked_rows,
        "checked_rows": requested_checked_rows if proc.returncode == 0 else [],
        "source_elaboration": fresh_source_metadata,
        "fresh_source_elaboration": fresh_source_metadata,
    }
    if diagnose_failed_rows and proc.returncode != 0:
        result["failed_checked_rows"] = failed_checked_rows
        result["row_check_diagnostic_error"] = row_check_diagnostic_error
    return result


def configured_review_reference_preflight(
    *,
    root: Path,
    paper_id: str,
    interface_path: Path,
    import_module: str,
    row_namespace: str,
    configured_rows: list[str],
    qualified_row_refs: dict[str, str],
    assumption_row_names: set[str],
    assumption_path: Path | None = None,
    missing_configured_rows: list[str],
    resolution_failures: list[dict[str, str]],
    no_lean: bool,
    max_output_chars: int,
    proof_source_path: Path | None = None,
) -> dict[str, Any]:
    """Validate configured review references before recursive semantic scans.

    This is deliberately configuration integrity only.  It establishes that a
    status-configured review route resolves to the current isolated Lean
    review surface; it makes no inference from a row label, declaration name,
    or theorem body about the source mathematics.  A successful full preflight
    can be reused as the final row-resolution receipt because it checks a
    superset of every source-selected review row.
    """

    resolved_rows = [
        {
            "row": row,
            "qualified_declaration": qualified_row_refs[row],
        }
        for row in configured_rows
        if row in qualified_row_refs
    ]
    missing_rows = [
        {
            "row": row,
            "configured_reference": row,
            "reason": "not declared in the current configured review sources",
        }
        for row in missing_configured_rows
    ]
    preflight: dict[str, Any] = {
        "schema": 1,
        "configured_rows": resolved_rows,
        "missing_configured_review_rows": missing_rows,
        "failed_configured_review_rows": list(resolution_failures),
        "unverified_configured_review_rows": [],
        "mode": "static_current_review_surface",
    }
    if missing_rows or resolution_failures:
        preflight["status"] = "failed"
        return preflight

    if no_lean:
        preflight["status"] = "static_passed_lean_skipped"
        return preflight

    preflight["mode"] = "fresh_isolated_current_review_surface"
    check = lean_check(
        root=root,
        paper_id=paper_id,
        interface_path=interface_path,
        import_module=import_module,
        row_namespace=row_namespace,
        row_names=[row["row"] for row in resolved_rows],
        assumption_row_names=assumption_row_names,
        qualified_row_refs=qualified_row_refs,
        fields=[],
        max_output_chars=max_output_chars,
        diagnose_failed_rows=True,
        assumption_path=assumption_path,
        proof_source_path=proof_source_path,
    )
    preflight["lean_check"] = check
    if check.get("returncode") == 0:
        preflight["status"] = "passed"
        return preflight

    failed_rows = check.get("failed_checked_rows")
    if isinstance(failed_rows, list):
        preflight["failed_configured_review_rows"].extend(
            row for row in failed_rows if isinstance(row, dict)
        )
    failed_row_names = {
        str(row.get("row") or "").strip()
        for row in preflight["failed_configured_review_rows"]
        if isinstance(row, dict)
    }
    preflight["unverified_configured_review_rows"] = [
        row
        for row in resolved_rows
        if row["row"] not in failed_row_names
    ]
    diagnostic_error = str(check.get("row_check_diagnostic_error") or "").strip()
    if diagnostic_error:
        preflight["diagnostic_error"] = diagnostic_error
    preflight["status"] = "failed"
    return preflight


def configured_review_reference_static_preflight(
    root: Path, paper_dir: Path
) -> dict[str, Any]:
    """Resolve every configured review reference without Lean or graph work."""

    preflight: dict[str, Any] = {
        "schema": 1,
        "configured_rows": [],
        "missing_configured_review_rows": [],
        "failed_configured_review_rows": [],
        "unverified_configured_review_rows": [],
        "mode": "static_current_review_surface",
    }
    status_path = paper_dir / "status.json"
    try:
        configured_rows = parse_status_machine_rows(status_path)
    except (OSError, RuntimeError, UnicodeError, ValueError, json.JSONDecodeError) as exc:
        preflight["status"] = "failed"
        preflight["diagnostic_error"] = (
            f"could not read configured review rows: {exc}"
        )
        return preflight
    if not configured_rows:
        preflight["status"] = "static_passed"
        return preflight

    try:
        interface_path = review_source_path(root, paper_dir, status_path)
        if not interface_path.is_file():
            preflight["status"] = "failed"
            preflight["diagnostic_error"] = (
                f"missing review surface Lean file at {interface_path}"
            )
            return preflight
        row_namespace = first_declaration_namespace(interface_path)
        interface_declarations = parse_declarations(interface_path)
        proof_path = proof_endpoint_source_path(
            root, paper_dir, status_path, interface_path=interface_path
        )
        proof_namespace = ""
        proof_declarations: dict[str, str] = {}
        if proof_path is not None:
            proof_namespace = first_declaration_namespace(proof_path)
            proof_declarations = parse_declarations(proof_path)
        assumptions_path = assumption_source_path(
            root, paper_dir, status_path, interface_path=interface_path
        )
        assumption_namespace = ""
        assumption_declarations: dict[str, str] = {}
        if assumptions_path is not None and assumptions_path.exists():
            assumption_namespace = first_declaration_namespace(assumptions_path)
            assumption_declarations = parse_declarations(assumptions_path)
    except (OSError, RuntimeError, UnicodeError, ValueError, json.JSONDecodeError) as exc:
        preflight["status"] = "failed"
        preflight["diagnostic_error"] = (
            f"could not read current configured review sources: {exc}"
        )
        return preflight

    for row in configured_rows:
        try:
            interface_match = resolve_declaration_reference(
                row, interface_declarations, preferred_namespace=row_namespace
            )
            proof_match = resolve_declaration_reference(
                row, proof_declarations, preferred_namespace=proof_namespace
            )
            assumption_match = resolve_declaration_reference(
                row, assumption_declarations, preferred_namespace=assumption_namespace
            )
        except ValueError as exc:
            preflight["failed_configured_review_rows"].append(
                {
                    "row": row,
                    "configured_reference": row,
                    "reason": str(exc),
                }
            )
            continue
        matches = [
            name for name in (interface_match, proof_match, assumption_match) if name
        ]
        if len(set(matches)) > 1:
            preflight["failed_configured_review_rows"].append(
                {
                    "row": row,
                    "configured_reference": row,
                    "reason": (
                        "ambiguous across current review files: "
                        + ", ".join(sorted(set(matches)))
                    ),
                }
            )
            continue
        if not matches:
            preflight["missing_configured_review_rows"].append(
                {
                    "row": row,
                    "configured_reference": row,
                    "reason": "not declared in the current configured review sources",
                }
            )
            continue
        preflight["configured_rows"].append(
            {"row": row, "qualified_declaration": matches[0]}
        )

    preflight["status"] = (
        "failed"
        if preflight["missing_configured_review_rows"]
        or preflight["failed_configured_review_rows"]
        else "static_passed"
    )
    return preflight


def configured_review_reference_static_error(root: Path, paper_dir: Path) -> str:
    """Return a current configured-review resolution error without Lean work.

    This is a cache-admission guard, not a semantic audit. A reused aggregate
    receipt must not bypass the same stale/ambiguous status-reference check
    that a fresh audit performs before recursive scanning. Empty configured
    review surfaces need no source-file lookup because they name no route to
    validate.
    """

    preflight = configured_review_reference_static_preflight(root, paper_dir)
    if preflight.get("status") != "failed":
        return ""
    diagnostic_error = str(preflight.get("diagnostic_error") or "").strip()
    if diagnostic_error:
        return diagnostic_error
    missing_rows = preflight.get("missing_configured_review_rows")
    if isinstance(missing_rows, list) and missing_rows:
        item = missing_rows[0]
        if isinstance(item, dict):
            row = str(item.get("row") or "").strip()
            reason = str(item.get("reason") or "").strip()
            if row and reason:
                return f"configured review row {row!r} is {reason}"
    failed_rows = preflight.get("failed_configured_review_rows")
    if isinstance(failed_rows, list) and failed_rows:
        item = failed_rows[0]
        if isinstance(item, dict):
            row = str(item.get("row") or "").strip()
            reason = str(item.get("reason") or "").strip()
            if row and reason:
                return f"configured review row {row!r}: {reason}"
    return "configured review reference preflight failed"


def lean_check_subset_from_configured_preflight(
    preflight: dict[str, Any],
    *,
    row_names: list[str],
    row_namespace: str,
    qualified_row_refs: dict[str, str],
) -> dict[str, Any]:
    """Narrow a successful superset preflight to the final review selection."""

    check = preflight.get("lean_check")
    if (
        preflight.get("status") != "passed"
        or not isinstance(check, dict)
        or check.get("returncode") != 0
    ):
        raise ValueError("cannot reuse an unsuccessful configured review preflight")
    requested_rows = [
        {
            "row": name,
            "qualified_declaration": qualified_row_refs.get(
                name, f"{row_namespace}.{name}" if row_namespace else name
            ),
        }
        for name in row_names
    ]
    configured_rows = preflight.get("configured_rows")
    if not isinstance(configured_rows, list):
        raise ValueError("configured review preflight has no verified row inventory")
    verified_rows = {
        (
            str(row.get("row") or "").strip(),
            str(row.get("qualified_declaration") or "").strip(),
        )
        for row in configured_rows
        if isinstance(row, dict)
    }
    unverified_rows = [
        row
        for row in requested_rows
        if (row["row"], row["qualified_declaration"]) not in verified_rows
    ]
    if unverified_rows:
        raise ValueError(
            "cannot reuse configured review preflight for rows it did not verify: "
            + ", ".join(
                f"{row['row']} ({row['qualified_declaration']})"
                for row in unverified_rows
            )
        )
    if not requested_rows:
        # The configured-surface preflight is intentionally stronger than the
        # final source-record selection: it may have elaborated ordinary Specs
        # and proof endpoints even when recursive analysis finds no
        # boundary-shaped rows or fields to audit.  Preserve that distinction
        # in the canonical raw receipt.  Copying the successful superset check
        # with an empty row list would falsely look like an executed empty
        # check and fail the zero-surface postcondition.
        return {
            "command": "skipped Lean check: no source-record rows or fields",
            "returncode": 0,
            "truncated": False,
            "output": "",
            "requested_checked_rows": [],
            "checked_rows": [],
            "fresh_source_elaboration": {"mode": "not_run_without_lean"},
        }
    narrowed = dict(check)
    narrowed["requested_checked_rows"] = requested_rows
    narrowed["checked_rows"] = requested_rows
    # This only occurs on a failed diagnostic preflight, but keep final normal
    # receipts byte-compatible with the pre-existing row-check schema.
    narrowed.pop("failed_checked_rows", None)
    narrowed.pop("row_check_diagnostic_error", None)
    return narrowed


def emit_configured_review_reference_preflight_failure(
    args: argparse.Namespace,
    root: Path,
    paper_dir: Path,
    preflight: dict[str, Any],
) -> int:
    """Emit a non-evidence diagnostic for a stale configured review surface."""

    payload = {
        "schema": 1,
        "paper": args.paper,
        "kind": "configured_review_reference_preflight_failure",
        "missing_configured_review_rows": [
            item.get("row")
            for item in preflight.get("missing_configured_review_rows", [])
            if isinstance(item, dict) and str(item.get("row") or "").strip()
        ],
        "failed_configured_review_rows": preflight.get(
            "failed_configured_review_rows", []
        ),
        "unverified_configured_review_rows": preflight.get(
            "unverified_configured_review_rows", []
        ),
        "configured_review_reference_preflight": preflight,
    }
    encoded = json.dumps(payload, indent=2, sort_keys=True)
    canonical_path = canonical_source_record_audit_path(paper_dir)
    emit_stdout = bool(getattr(args, "stdout", False))
    if args.out:
        output_path = source_record_audit_output_path(args, root, paper_dir)
        if output_path.resolve() == canonical_path.resolve():
            print(
                "refusing to replace canonical source-record audit after a configured "
                "review-reference preflight failure",
                file=sys.stderr,
            )
        else:
            atomic_write_text_if_changed(output_path, encoded + "\n")
    if emit_stdout:
        print(encoded)
    elif not args.out:
        print(
            json.dumps(
                {
                    "paper": args.paper,
                    "missing_configured_review_rows": payload[
                        "missing_configured_review_rows"
                    ],
                    "failed_configured_review_rows": payload[
                        "failed_configured_review_rows"
                    ],
                    "unverified_configured_review_rows": payload[
                        "unverified_configured_review_rows"
                    ],
                },
                sort_keys=True,
            ),
            file=sys.stderr,
        )
    return 2


def source_premise_consistency_items(
    root: Path,
    import_module: str,
    record_roots: set[str],
    diagnostics_out: dict[str, Any] | None = None,
) -> tuple[list[dict[str, Any]], str]:
    """Detect reviewed record inputs with a checked route to ``False``.

    Candidate and binder names are diagnostic identities only.  The underlying
    Lean Meta pass compares elaborated input domains by definitional equality,
    so transparent aliases cannot hide a contradiction and an unrelated
    theorem ending in ``False`` is not a route.  A candidate with another
    proposition premise is rejected by that pass.  Extra non-proposition
    setup remains visible but is not promoted to a direct eliminator.
    """

    targets = sorted({name.strip() for name in record_roots if name.strip()})
    if not targets:
        return [], ""
    try:
        root_text = str(root)
        if root_text not in sys.path:
            sys.path.insert(0, root_text)
        from scripts.lean_signature_manifest import (
            run_lean_source_premise_false_eliminators,
        )

        routes = run_lean_source_premise_false_eliminators(
            root,
            import_module,
            targets,
            timeout_seconds=180,
            build_timeout_seconds=600,
            diagnostics_out=diagnostics_out,
        )
    except Exception as exc:  # noqa: BLE001 - the caller makes this fail closed.
        return [], f"Lean source-premise consistency check raised {type(exc).__name__}: {exc}"
    if set(routes) != set(targets):
        return [], (
            "Lean source-premise consistency check did not return one elaborated "
            "result per reviewed record root"
        )

    items: list[dict[str, Any]] = []
    for target in targets:
        candidates = routes[target]
        if not candidates:
            continue
        direct = [candidate for candidate in candidates if candidate["direct_eliminator"]]
        data_dependent = [
            candidate for candidate in candidates if not candidate["direct_eliminator"]
        ]
        items.append(
            {
                "judgment_key": f"source-premise-consistency::{target}",
                "kind": "elaborated_source_premise_false_eliminator",
                "reviewed_input_type": target,
                "direct_eliminators": direct,
                "candidate_data_dependent_eliminators": data_dependent,
                "required_check": (
                    "Lean found a declaration whose elaborated terminal result is False "
                    "and whose consumed input is definitionally equal to this reviewed "
                    "record type. A direct eliminator means the source-facing model "
                    "premise is inconsistent and cannot support a formalized closeout. "
                    "A data-dependent candidate is not a direct contradiction, but its "
                    "extra data parameters must be audited before using the model."
                ),
            }
        )
    return items, ""


def source_mapped_record_roots(
    paper_dir: Path, structures: dict[str, StructureInfo]
) -> set[str]:
    """Return record roots explicitly routed by the paper source inventory.

    The statement map supplies only source-to-Lean routing.  Once a route
    resolves to an elaborated record identity, the Meta consistency scan below
    decides whether it is contradictory; source labels and declaration spelling
    do not decide that mathematical question.
    """

    # The reachable-auxiliary guard above accepts only exact FQN map routes.
    # Feed every such route into the same elaborated source-premise scan, so a
    # structure supported through a semantic contract or bridge field is not
    # merely listed in a routing ledger without receiving the model-integrity
    # check.  Legacy short routes remain below for historical diagnostics but
    # cannot satisfy the reachable-auxiliary guard.
    roots = {
        qualified
        for qualified in explicitly_qualified_source_map_routes(paper_dir)
        if qualified in structures
    }
    payload = load_json_object(paper_dir / "audit" / "paper_statement_map.json")
    raw_items = payload.get("items") if isinstance(payload, dict) else None
    if isinstance(raw_items, dict):
        # Contradictory source-premise roots are a model-integrity question,
        # not a named-result coverage question.  A source-mapped model must
        # remain visible even when ordinary named-theory mode excludes it.
        items = raw_items.values()
    elif isinstance(raw_items, list):
        items = raw_items
    else:
        return roots
    for raw_item in items:
        if not isinstance(raw_item, dict):
            continue
        for field_name in (
            "lean_declarations",
            "proof_lean_declarations",
            "support_lean_declarations",
        ):
            raw_names = raw_item.get(field_name)
            if not isinstance(raw_names, list):
                continue
            for raw_name in raw_names:
                if not isinstance(raw_name, str):
                    continue
                name = raw_name.strip()
                if not name:
                    continue
                # Prefer an exact fully-qualified record identity.  A legacy
                # short route is admissible only when it identifies exactly
                # one parsed structure; it routes the Meta query but never
                # decides whether the source premise is contradictory.
                if name in structures:
                    roots.add(name)
                    continue
                matches = [
                    structure_name
                    for structure_name in structures
                    if structure_name.endswith(f".{name}")
                ]
                if len(matches) == 1:
                    roots.add(matches[0])
    return roots


def source_proof_fidelity_path(paper_dir: Path) -> Path | None:
    """Resolve the configured paper-local fidelity ledger without path escape."""

    status = load_json_object(paper_dir / "status.json")
    review_surface = status.get("review_surface") if status is not None else None
    config = (
        review_surface.get("source_proof_fidelity_review")
        if isinstance(review_surface, dict)
        else None
    )
    if not isinstance(config, dict):
        organized = paper_dir / "audit" / "source_proof_fidelity.json"
        return organized if organized.exists() else paper_dir / "source_proof_fidelity.json"
    raw_path = config.get("ledger_file")
    if not isinstance(raw_path, str) or not raw_path.strip():
        return None
    relative_path = Path(raw_path.strip())
    if relative_path.is_absolute():
        return None
    repository_root = (
        paper_dir.parent.parent if paper_dir.parent.name == "papers" else paper_dir
    )
    anchor = repository_root if relative_path.parts[:1] == ("papers",) else paper_dir
    try:
        candidate = (anchor / relative_path).resolve()
        candidate.relative_to(paper_dir.resolve())
    except (OSError, RuntimeError, ValueError):
        return None
    return candidate


def source_proof_fidelity_context(paper_dir: Path) -> dict[str, Any] | None:
    """Load the optional source-proof ledger as semantic audit context.

    The ledger deliberately contains source locators and mathematical repair
    obligations rather than Lean declaration-name links. Including it in the
    source-record digest invalidates an old provenance judgment when a recorded
    source-proof defect, model convention, checked proof step, or repair status
    changes.  Conventions and checked steps remain source-located mathematical
    context; no Lean declaration name is used to select or interpret them.
    """

    path = source_proof_fidelity_path(paper_dir)
    if path is None:
        return None
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None
    if not isinstance(payload, dict):
        return None
    return {
        key: payload.get(key)
        for key in (
            "schema",
            "paper",
            "source_artifact_path",
            "source_artifact_sha256",
            "review_status",
            "reviewed_proof_scopes",
            "model_conventions",
            "checked_proof_steps",
            "defects",
        )
    }


def authenticated_lean_review_source(
    path: Path,
    *,
    source_bytes_by_path: Mapping[Path, bytes],
    source_text_by_path: Mapping[Path, str],
    role: str,
) -> tuple[bytes, str]:
    """Return one configured review source from the frozen Lean closure.

    Configured semantic, proof, and assumption files are authoritative inputs,
    not incidental filesystem context.  A raw scan therefore consumes their
    exact bytes only from the Lean-owned closure snapshot and fails with a
    bounded diagnostic when the Lean-owned complete-review import graph omits
    one.  It must never fall back to a live reread after closure acquisition.
    """

    resolved = path.resolve()
    content = source_bytes_by_path.get(resolved)
    text = source_text_by_path.get(resolved)
    if content is None or text is None:
        raise SystemExit(
            f"configured {role} source is absent from the Lean-owned "
            f"complete-review import closure: {path}"
        )
    return content, text




def _run_audit(args: argparse.Namespace, root: Path) -> int:
    paper_dir = root / "papers" / args.paper
    configured_reference_preflight = configured_review_reference_static_preflight(
        root, paper_dir
    )
    if configured_reference_preflight.get("status") == "failed":
        return emit_configured_review_reference_preflight_failure(
            args, root, paper_dir, configured_reference_preflight
        )
    (
        paper_statement_map_sha256,
        paper_statement_map_semantic_sha256,
    ) = paper_statement_map_cache_receipts(paper_dir)
    if args.refresh_judgment_summary:
        audit_path = (
            Path(args.out)
            if args.out
            else paper_dir / "audit" / "source_record_audit.json"
        )
        if not audit_path.is_absolute():
            audit_path = root / audit_path
        payload = refresh_existing_judgment_summary(
            paper_dir,
            args.paper,
            audit_path,
            paper_statement_map_sha256=paper_statement_map_sha256,
            paper_statement_map_semantic_sha256=paper_statement_map_semantic_sha256,
        )
        print(
            "refreshed source-record judgment summary for "
            f"{args.paper}: {payload['current_source_record_judgment_count']} "
            "current judgment(s), "
            f"{payload['unresolved_conclusion_dependency_count']} unresolved "
            "conclusion dependency item(s)"
        )
        return 0

    saved_payload = load_json_object(canonical_source_record_audit_path(paper_dir))
    closure_provider = WorktreeImportClosureProvider(
        root,
        eager_source_snapshot=False,
        allow_dirty_worktree_sources=True,
    )
    lean_import_closure, closure_error = (
        source_record_lean_import_closure_for_paper(
            root,
            paper_dir,
            provider=closure_provider,
            saved_payload=saved_payload,
            allow_live_lean_graph=not bool(args.no_lean),
        )
    )
    if lean_import_closure is None:
        raise SystemExit(
            "could not acquire Lean-owned PaperInterface import closure: "
            + closure_error
        )

    current_input_fingerprint_capture: list[dict[str, Any]] = []
    cached_payload = reusable_source_record_audit(
        args,
        root,
        paper_dir,
        paper_statement_map_sha256=paper_statement_map_sha256,
        paper_statement_map_semantic_sha256=paper_statement_map_semantic_sha256,
        _current_input_fingerprint_capture=current_input_fingerprint_capture,
        lean_import_closure=lean_import_closure,
        saved_payload=saved_payload,
    )
    if cached_payload is not None:
        finalization_error = source_record_lean_import_closure_finalization_error(
            closure_provider
        )
        if finalization_error:
            raise SystemExit(
                "Lean import-closure inputs changed during cache validation: "
                + finalization_error
            )
        if args.out:
            output_path = source_record_audit_output_path(args, root, paper_dir)
            atomic_write_text_if_changed(
                output_path,
                json.dumps(cached_payload, indent=2, sort_keys=True) + "\n",
            )
        else:
            print(json.dumps(cached_payload, indent=2, sort_keys=True))
        return 0
    scan_start_input_fingerprint = (
        current_input_fingerprint_capture[0]
        if current_input_fingerprint_capture
        else source_record_input_fingerprint(
            args,
            root,
            paper_dir,
            paper_statement_map_sha256=paper_statement_map_sha256,
            paper_statement_map_semantic_sha256=(
                paper_statement_map_semantic_sha256
            ),
            lean_import_closure=lean_import_closure,
        )
    )
    semantic_context_items, semantic_context_errors = (
        source_map_semantic_context_requirements(paper_dir)
    )
    if semantic_context_errors:
        raise SystemExit(
            "invalid source-map semantic_context_requirements:\n- "
            + "\n- ".join(semantic_context_errors)
    )
    # Cache priming is intentionally outside the raw producer markers below:
    # it can reduce repeated Lean work but cannot alter which obligations the
    # producer emits or force a raw-receipt reissue on an orchestration edit.
    authenticated_store_manifests = preprime_source_record_manifest_resume_cache(
        args,
        root,
        paper_dir,
        lean_import_closure=lean_import_closure,
    )

    # SOURCE_RECORD_RAW_PRODUCER_BEGIN
    authenticated_lean_source_bytes = (
        source_record_lean_import_closure_source_bytes(lean_import_closure)
    )
    authenticated_lean_source_text = (
        source_record_lean_import_closure_source_text(lean_import_closure)
    )
    status_path = paper_dir / "status.json"
    semantic_model_dimensions, semantic_model_config_errors = (
        semantic_model_review_config(status_path)
    )
    (
        explicit_source_targets,
        explicit_source_target_config_errors,
    ) = explicit_source_target_declarations_for_semantic_review(status_path)
    semantic_model_config_errors.extend(explicit_source_target_config_errors)
    interface_path = review_source_path(root, paper_dir, status_path)
    if not interface_path.exists():
        raise SystemExit(f"missing review surface Lean file at {interface_path}")
    interface_bytes, interface_text = authenticated_lean_review_source(
        interface_path,
        source_bytes_by_path=authenticated_lean_source_bytes,
        source_text_by_path=authenticated_lean_source_text,
        role="semantic review interface",
    )
    interface_source_identity = source_artifact_identity(
        root,
        interface_path,
        content=interface_bytes,
    )
    proof_path = proof_endpoint_source_path(
        root, paper_dir, status_path, interface_path=interface_path
    )
    proof_text = ""
    proof_source_identity: dict[str, str] | None = None
    proof_namespace = ""
    proof_declarations: dict[str, str] = {}
    if proof_path is not None:
        proof_bytes, proof_text = authenticated_lean_review_source(
            proof_path,
            source_bytes_by_path=authenticated_lean_source_bytes,
            source_text_by_path=authenticated_lean_source_text,
            role="proof endpoint",
        )
        proof_source_identity = source_artifact_identity(
            root,
            proof_path,
            content=proof_bytes,
        )
        proof_namespace = first_declaration_namespace(
            proof_path, source_text=proof_text
        )
        proof_declarations = parse_declarations(proof_path, source_text=proof_text)
    # The generated check must see every configured row.  Embedded endpoints
    # use PaperInterface directly; a separate ProofInterface imports that
    # semantic interface and is therefore the smallest correct check root.
    import_module = lean_module_name(root, proof_path or interface_path)

    row_namespace = first_declaration_namespace(
        interface_path, source_text=interface_text
    )
    configured_rows = parse_status_machine_rows(status_path)
    auxiliary_rows = parse_status_auxiliary_rows(status_path)
    quarantined_auxiliary_rows = parse_status_quarantined_auxiliary_rows(status_path)
    interface_declarations = parse_declarations(
        interface_path, source_text=interface_text
    )
    qualified_row_refs: dict[str, str] = {}
    assumptions_path = effective_source_record_assumption_path(
        root,
        paper_dir,
        status_path,
        interface_path=interface_path,
        lean_import_closure=lean_import_closure,
    )
    assumption_declarations: dict[str, str] = {}
    assumption_namespace = ""
    assumption_source_identity: dict[str, str] | None = None
    if assumptions_path is not None and assumptions_path.exists():
        assumption_bytes, assumption_text = authenticated_lean_review_source(
            assumptions_path,
            source_bytes_by_path=authenticated_lean_source_bytes,
            source_text_by_path=authenticated_lean_source_text,
            role="assumption",
        )
        assumption_namespace = first_declaration_namespace(
            assumptions_path, source_text=assumption_text
        )
        assumption_declarations = parse_declarations(
            assumptions_path, source_text=assumption_text
        )
        assumption_source_identity = source_artifact_identity(
            root,
            assumptions_path,
            content=assumption_bytes,
        )

    declarations: dict[str, str] = {}
    selected_qualified_names: set[str] = set()
    assumption_row_names: set[str] = set()
    selected_row_source_paths: dict[str, Path] = {}
    configured_reference_resolution_failures: list[dict[str, str]] = []
    for row in configured_rows:
        try:
            interface_match = resolve_declaration_reference(
                row, interface_declarations, preferred_namespace=row_namespace
            )
            proof_match = resolve_declaration_reference(
                row, proof_declarations, preferred_namespace=proof_namespace
            )
            assumption_match = resolve_declaration_reference(
                row, assumption_declarations, preferred_namespace=assumption_namespace
            )
        except ValueError as exc:
            configured_reference_resolution_failures.append(
                {
                    "row": row,
                    "configured_reference": row,
                    "reason": str(exc),
                }
            )
            continue
        matches = [
            name for name in (interface_match, proof_match, assumption_match) if name
        ]
        if len(set(matches)) > 1:
            configured_reference_resolution_failures.append(
                {
                    "row": row,
                    "configured_reference": row,
                    "reason": (
                        "ambiguous across current review files: "
                        + ", ".join(sorted(set(matches)))
                    ),
                }
            )
            continue
        if not matches:
            continue
        qualified = matches[0]
        source = (
            interface_declarations.get(qualified)
            or proof_declarations.get(qualified)
            or assumption_declarations[qualified]
        )
        declarations[row] = source
        qualified_row_refs[row] = qualified
        selected_qualified_names.add(qualified)
        if qualified in assumption_declarations:
            assumption_row_names.add(row)
            selected_row_source_paths[row] = assumptions_path
        elif qualified in proof_declarations:
            assert proof_path is not None
            selected_row_source_paths[row] = proof_path
        else:
            selected_row_source_paths[row] = interface_path

    configured_present = [name for name in configured_rows if name in declarations]
    resolution_failure_rows = {
        failure["row"] for failure in configured_reference_resolution_failures
    }
    missing_configured_rows = [
        name
        for name in configured_rows
        if name not in declarations and name not in resolution_failure_rows
    ]
    configured_review_preflight = configured_review_reference_preflight(
        root=root,
        paper_id=args.paper,
        interface_path=interface_path,
        import_module=import_module,
        row_namespace=row_namespace,
        configured_rows=configured_rows,
        qualified_row_refs=qualified_row_refs,
        assumption_row_names=assumption_row_names,
        assumption_path=assumptions_path,
        missing_configured_rows=missing_configured_rows,
        resolution_failures=configured_reference_resolution_failures,
        no_lean=bool(args.no_lean),
        max_output_chars=args.max_lean_output_chars,
        proof_source_path=proof_path,
    )
    if configured_review_preflight.get("status") == "failed":
        return emit_configured_review_reference_preflight_failure(
            args, root, paper_dir, configured_review_preflight
        )
    auxiliary_qualified_names: set[str] = set()
    for row in auxiliary_rows:
        interface_match = resolve_declaration_reference(
            row, interface_declarations, preferred_namespace=row_namespace
        )
        assumption_match = resolve_declaration_reference(
            row, assumption_declarations, preferred_namespace=assumption_namespace
        )
        auxiliary_qualified_names.update(
            name for name in (interface_match, assumption_match) if name
        )
    quarantined_auxiliary_qualified_names: set[str] = set()
    for row in quarantined_auxiliary_rows:
        interface_match = resolve_declaration_reference(
            row, interface_declarations, preferred_namespace=row_namespace
        )
        assumption_match = resolve_declaration_reference(
            row, assumption_declarations, preferred_namespace=assumption_namespace
        )
        quarantined_auxiliary_qualified_names.update(
            name for name in (interface_match, assumption_match) if name
        )
    interface_names = set(interface_declarations)
    assumption_names = set(assumption_declarations)
    unconfigured_rows = unconfigured_review_declarations(
        interface_declarations,
        selected_names=selected_qualified_names & interface_names,
        auxiliary_names=auxiliary_qualified_names & interface_names,
        quarantined_auxiliary_names=(
            quarantined_auxiliary_qualified_names & interface_names
        ),
    )
    # Retain Assumptions.lean implementation drift as a distinct diagnostic,
    # but do not call it a PaperInterface review row.  Selected assumption
    # roots are still expanded recursively in the source-premise audit below.
    unconfigured_assumption_support_rows = unconfigured_review_declarations(
        assumption_declarations,
        selected_names=selected_qualified_names & assumption_names,
        auxiliary_names=auxiliary_qualified_names & assumption_names,
        quarantined_auxiliary_names=(
            quarantined_auxiliary_qualified_names & assumption_names
        ),
    )

    # The enforceable source-record lane follows the same source-semantic
    # coverage mode as the dashboard.  The ordinary mode audits only source
    # labelled named theory; deep all-prose mode expands back to every mapped
    # paper-facing row.  Selection uses explicit source-map route identities,
    # never a declaration/function-name heuristic.
    source_selected_rows, source_contract_statement_map, source_coverage_selection = (
        source_coverage_review_rows(
            paper_dir, configured_present, qualified_row_refs
        )
    )
    (
        explicit_source_target_rows,
        explicit_source_target_selection,
    ) = explicit_source_target_review_rows(
        paper_dir,
        configured_present,
        qualified_row_refs,
        explicit_source_targets,
    )
    configured_assumption_references = set(
        parse_status_review_surface_names(status_path, ("assumption_names",))
    )
    configured_assumption_rows = [
        row
        for row in configured_present
        if row in configured_assumption_references
    ]
    scope_targets, scope_target_config_errors = (
        formalization_scope_target_declarations_for_semantic_review(status_path)
    )
    row_names, semantic_row_selection = effective_source_record_review_rows(
        source_selected_rows=source_selected_rows,
        configured_present=configured_present,
        qualified_row_refs=qualified_row_refs,
        configured_assumption_rows=configured_assumption_rows,
        formalization_scope_targets=scope_targets,
        explicit_source_target_rows=explicit_source_target_rows,
    )
    source_coverage_selection.update(semantic_row_selection)
    source_coverage_selection.update(explicit_source_target_selection)
    source_coverage_selection["semantic_model_scope_target_route_errors"] = sorted(
        set(
            source_coverage_selection.get(
                "semantic_model_scope_target_route_errors", []
            )
            + scope_target_config_errors
        )
    )
    source_coverage_selection[
        "semantic_model_explicit_source_target_route_errors"
    ] = sorted(
        set(
            list(
                source_coverage_selection.get(
                    "semantic_model_explicit_source_target_route_errors", []
                )
                or []
            )
            + list(
                source_coverage_selection.get(
                    "semantic_model_explicit_source_target_effective_row_errors", []
                )
                or []
            )
        )
    )
    source_coverage_selection["semantic_model_target_route_errors"] = sorted(
        set(
            list(
                source_coverage_selection.get(
                    "semantic_model_scope_target_route_errors", []
                )
                or []
            )
            + list(
                source_coverage_selection.get(
                    "semantic_model_explicit_source_target_route_errors", []
                )
                or []
            )
        )
    )
    complete_paper_statement_map = load_json_object(
        paper_dir / "audit" / "paper_statement_map.json"
    )
    # Normal coverage's filtered map remains authoritative for named theory.
    # This separate map adds only the source-map items that passed the explicit
    # non-normal target resolver above, so contract pairing and source-context
    # association can inspect their semantics without widening normal scope.
    semantic_model_statement_map = dict(source_contract_statement_map)
    normal_contract_items = source_contract_statement_map.get("items")
    complete_contract_items = complete_paper_statement_map.get("items")
    if isinstance(normal_contract_items, Mapping) and isinstance(
        complete_contract_items, Mapping
    ):
        semantic_model_contract_items = dict(normal_contract_items)
        for source_item_id in source_coverage_selection.get(
            "semantic_model_explicit_source_target_source_items", []
        ) or []:
            source_item = complete_contract_items.get(str(source_item_id))
            if isinstance(source_item, Mapping):
                semantic_model_contract_items[str(source_item_id)] = source_item
        semantic_model_statement_map["items"] = semantic_model_contract_items
    semantic_model_contract_companions: list[dict[str, str]] = []
    seen_semantic_model_contract_companions: set[tuple[str, str, str]] = set()
    for raw_route in (
        list(
            source_coverage_selection.get(
                "source_coverage_semantic_contract_companions", []
            )
            or []
        )
        + list(
            source_coverage_selection.get(
                "semantic_model_explicit_source_target_semantic_contract_companions",
                [],
            )
            or []
        )
    ):
        if not isinstance(raw_route, Mapping):
            continue
        route = {
            field: str(raw_route.get(field) or "").strip()
            for field in ("source_item", "evidence_declaration", "spec_declaration")
        }
        key = (
            route["source_item"],
            route["evidence_declaration"],
            route["spec_declaration"],
        )
        if not all(key) or key in seen_semantic_model_contract_companions:
            continue
        seen_semantic_model_contract_companions.add(key)
        semantic_model_contract_companions.append(route)
    semantic_model_contract_companions.sort(
        key=lambda route: (
            route["source_item"],
            route["evidence_declaration"],
            route["spec_declaration"],
        )
    )
    canonical_lean_files = paper_interface_import_closure_lean_files(
        root,
        interface_path,
        lean_import_closure=lean_import_closure,
    )
    local_lean_files = [
        path
        for path in canonical_lean_files
        if path == interface_path.resolve() or paper_dir.resolve() in path.parents
    ]
    canonical_paper_lean_modules = tuple(
        sorted(lean_module_name(root, path) for path in local_lean_files)
    )
    semantic_declarations = parse_local_declarations(
        root,
        sorted(set(canonical_lean_files)),
        source_text_by_path=authenticated_lean_source_text,
    )
    local_source_files = {
        repository_relative_path(root, path) for path in local_lean_files
    }
    local_declarations = [
        declaration
        for declaration in semantic_declarations
        if declaration.source_file in local_source_files
    ]
    # Every canonical parser and route graph uses the identical closed-world
    # module set. Loose scratch or alternate files cannot create declarations,
    # structures, blockers, or cache misses in a canonical receipt.
    recursive_field_route_lean_files = canonical_lean_files
    recursive_field_route_declarations = semantic_declarations
    recursive_field_route_graph = {
        "schema": 1,
        "kind": "lean_loaded_paper_interface_import_closure",
        SOURCE_RECORD_LEAN_IMPORT_CLOSURE_SHA256_FIELD: (
            lean_import_closure.sha256
        ),
        "interface_source": interface_source_identity,
        "module_count": len(recursive_field_route_lean_files),
        "module_source_sha256": stable_digest(
            [
                source_artifact_identity(
                    root,
                    path,
                    content=authenticated_lean_source_bytes[path.resolve()],
                )
                for path in recursive_field_route_lean_files
            ]
        ),
    }
    lean_files = list(canonical_lean_files)
    structures = parse_structures(
        root,
        sorted(set(lean_files)),
        source_text_by_path=authenticated_lean_source_text,
        local_declarations=semantic_declarations,
    )
    paper_local_structures = {
        name: structure
        for name, structure in structures.items()
        if structure.source_file in local_source_files
    }
    # Route auxiliaries from this raw audit's active semantic-review rows,
    # not from every current status include.  In named-theory mode the latter
    # can contain out-of-mode presentation rows that deliberately received no
    # source-record review in this issuance.  Treating them as roots would
    # manufacture auxiliary blockers without source-model evidence.
    active_selected_qualified_names = {
        qualified_row_refs[row]
        for row in row_names
        if row in qualified_row_refs
    }
    selected_row_names_by_qualified: dict[str, set[str]] = {}
    for row in row_names:
        qualified = qualified_row_refs.get(row)
        if qualified in active_selected_qualified_names:
            selected_row_names_by_qualified.setdefault(qualified, set()).add(row)
    # Auxiliary reachability is populated after Lean emits the exact
    # elaborated dependency graph for every selected root.
    reachable_auxiliary_routing: dict[str, Any] = {}
    proposition_heads = proposition_type_heads(semantic_declarations)
    proposition_aliases = parse_proposition_aliases(semantic_declarations)
    semantic_short_name_counts = local_declaration_short_name_counts(
        semantic_declarations
    )
    for alias_name in proposition_aliases:
        if alias_name.startswith("ambiguous:"):
            continue
        if "." in alias_name:
            proposition_heads.add(alias_name)
            continue
        if semantic_short_name_counts.get(alias_name, 0) == 1:
            proposition_heads.add(alias_name)
    proposition_wrapper_structures = proposition_wrapper_structure_names(
        semantic_declarations
    )
    semantic_data_heads = data_type_heads(semantic_declarations)
    semantic_type_aliases = parse_semantic_type_aliases(semantic_declarations)
    candidate_structures = audit_candidate_structures(structures, paper_local_structures)
    candidate_structure_parameter_counts = structure_parameter_counts(structures)
    structure_aliases = parse_structure_aliases(
        sorted(set(lean_files)),
        structures,
        source_text_by_path=authenticated_lean_source_text,
        local_declarations=semantic_declarations,
    )
    # A PaperInterface row remains the reviewed/source-routed identity.  When
    # it is a complete transparent alias, every source-premise lane below must
    # nevertheless inspect the target's actual binders and result premises.
    # Keeping these maps separate prevents an implementation declaration from
    # acquiring source-map identity or elaborated-signature credit.
    review_surfaces: dict[str, SemanticModelReviewSurface] = {}
    (
        contract_companion_surfaces,
        _provisional_contract_companion_surface_errors,
    ) = semantic_model_review_contract_companion_surfaces(
        companion_routes=semantic_model_contract_companions,
        semantic_declarations=semantic_declarations,
        proposition_aliases=proposition_aliases,
        type_aliases=semantic_type_aliases,
        elaborated_manifests_by_qualified=authenticated_store_manifests,
        defer_manifest_dependent_errors=True,
    )
    analysis_declarations: dict[str, str] = {}
    analysis_qualified_row_refs: dict[str, str] = {}
    # Keep declaration-header and result-telescope binders disjoint.  The
    # latter are conclusion-scoped, so treating `visible_inputs` as headers
    # and then appending them again invents duplicate binders and destroys the
    # Lean-manifest positional correspondence.
    row_inputs: dict[str, list[dict[str, str]]] = {}
    row_conclusion_inputs: dict[str, list[dict[str, str]]] = {}
    row_visible_inputs: dict[str, list[dict[str, str]]] = {}

    def rebuild_review_surface_maps(
        companion_surfaces: Mapping[str, SemanticModelReviewSurface],
    ) -> None:
        """Rebuild parser projections from one phase-owned surface set."""

        review_surfaces.clear()
        analysis_declarations.clear()
        analysis_qualified_row_refs.clear()
        row_inputs.clear()
        row_conclusion_inputs.clear()
        row_visible_inputs.clear()
        for row in row_names:
            review_surface = companion_surfaces.get(qualified_row_refs[row])
            if review_surface is None:
                review_surface = semantic_model_review_effective_surface(
                    reviewed_qualified_name=qualified_row_refs[row],
                    reviewed_declaration=declarations[row],
                    semantic_declarations=semantic_declarations,
                )
            review_surfaces[row] = review_surface
            analysis_declarations[row] = review_surface.analysis_declaration
            analysis_qualified_row_refs[row] = (
                review_surface.analysis_qualified_name
            )
            row_inputs[row] = list(review_surface.header_inputs)
            row_conclusion_inputs[row] = list(review_surface.conclusion_inputs)
            row_visible_inputs[row] = [
                *row_inputs[row],
                *row_conclusion_inputs[row],
            ]

    def discover_row_records() -> dict[str, list[str]]:
        discovered = {
            row: mentioned_structures_in_delta_expanded_scoped_inputs(
                row_visible_inputs[row],
                candidate_structures,
                structure_aliases,
                proposition_aliases=proposition_aliases,
                semantic_declarations=semantic_declarations,
                context_namespace=(
                    analysis_qualified_row_refs[row].rsplit(".", 1)[0]
                    if "." in analysis_qualified_row_refs[row]
                    else ""
                ),
                structure_parameter_counts=candidate_structure_parameter_counts,
            )
            for row in row_names
        }
        return {
            row: records for row, records in discovered.items() if records
        }

    rebuild_review_surface_maps(contract_companion_surfaces)
    row_records = discover_row_records()
    # The source-facing declaration may receive an execution/refinement record
    # defined in another paper-local module.  Use the parser only to enumerate
    # that exact bounded structural closure; Lean's manifest owns the actual
    # type-level ReflTransGen/relation detection below.  No record or field
    # spelling is used as a semantic trigger.
    def record_manifest_names_for(
        records_by_row: Mapping[str, list[str]],
    ) -> set[str]:
        names: set[str] = set()
        for records in records_by_row.values():
            for record in records:
                names.add(record)
                reachable_fields, _reachable_failures = recursively_collect_fields(
                    record,
                    structures,
                    candidate_structures,
                    structure_aliases,
                    args.max_depth,
                    proposition_heads=proposition_heads,
                    data_heads=semantic_data_heads,
                )
                names.update(field.structure for field in reachable_fields)
        return names

    elaborated_record_manifest_names = record_manifest_names_for(row_records)
    source_record_progress(
        "exact elaborated review-signature scan started "
        f"({len(row_names)} configured rows; "
        f"{len(elaborated_record_manifest_names)} reachable model records)"
    )
    requested_review_declaration_sources = {
        qualified_row_refs[row]: declarations[row] for row in row_names
    }
    requested_review_declaration_source_paths = {
        qualified_row_refs[row]: selected_row_source_paths[row] for row in row_names
    }
    authenticated_review_manifests, _authenticated_projection_diagnostics = (
        merge_prevalidated_review_signature_manifests(
            requested_review_declaration_sources,
            authenticated_store_manifests,
            {},
        )
    )
    legacy_requested_declaration_sources = {
        qualified: source
        for qualified, source in requested_review_declaration_sources.items()
        if qualified not in authenticated_review_manifests
    }
    legacy_requested_declaration_source_paths = {
        qualified: source_path
        for qualified, source_path in requested_review_declaration_source_paths.items()
        if qualified in legacy_requested_declaration_sources
    }
    legacy_review_manifests: dict[str, dict[str, Any]] = {}
    prior_review_manifest_diagnostics: dict[str, Any] = {}

    def report_prior_revalidation_batch_progress(event: Mapping[str, Any]) -> None:
        """Expose bounded persisted-root work through the active scan lease."""

        batch_number = event.get("batch_number")
        batch_total = event.get("batch_total")
        root_count = event.get("root_count")
        if event.get("status") == "started":
            source_record_progress(
                "exact persisted-root revalidation batch "
                f"{batch_number}/{batch_total} started ({root_count} roots)"
            )
            return
        source_record_progress(
            "exact persisted-root revalidation batch "
            f"{batch_number}/{batch_total} finished ({root_count} roots; "
            f"{event.get('completed_count')} complete; "
            f"{event.get('missing_count')} missing)"
        )

    if not args.no_lean:
        if legacy_requested_declaration_sources:
            legacy_review_manifests, prior_review_manifest_diagnostics = (
                reusable_prior_review_signature_manifests(
                    root=root,
                    paper_dir=paper_dir,
                    requested_declaration_sources=(
                        legacy_requested_declaration_sources
                    ),
                    requested_declaration_source_paths=(
                        legacy_requested_declaration_source_paths
                    ),
                    source_contract_statement_map=semantic_model_statement_map,
                    progress_callback=report_prior_revalidation_batch_progress,
                )
            )
        seeded_prior_review_names = seed_lean_signature_manifest_context_cache(
            root,
            import_module,
            legacy_review_manifests,
            prior_review_manifest_diagnostics.get(
                "accepted_manifest_pins_by_declaration", {}
            ),
            build_timeout_seconds=SOURCE_RECORD_LAKE_BUILD_TIMEOUT_SECONDS,
            semantic_dependency_modules=canonical_paper_lean_modules,
        )
        legacy_review_manifests = seeded_prior_review_signature_manifests(
            legacy_review_manifests,
            seeded_prior_review_names,
        )
    prior_review_manifests, combined_review_manifest_diagnostics = (
        merge_prevalidated_review_signature_manifests(
            requested_review_declaration_sources,
            authenticated_review_manifests,
            legacy_review_manifests,
        )
    )
    full_manifest_request_names = {
        *requested_review_declaration_sources,
        *analysis_qualified_row_refs.values(),
        *elaborated_record_manifest_names,
    }
    prevalidated_manifests, full_manifest_reuse_diagnostics = (
        merge_prevalidated_review_signature_manifests(
            full_manifest_request_names,
            authenticated_store_manifests,
            legacy_review_manifests,
        )
    )
    if not args.no_lean:
        source_record_progress(
            "exact reviewed-root manifest reuse finished "
            f"({combined_review_manifest_diagnostics['accepted_count']} accepted: "
            f"{combined_review_manifest_diagnostics['authenticated_accepted_count']} "
            "authenticated-store, "
            f"{combined_review_manifest_diagnostics['legacy_only_accepted_count']} "
            "legacy-item; "
            f"{combined_review_manifest_diagnostics['fresh_required_count']} "
            "configured roots require fresh Lean; "
            f"{combined_review_manifest_diagnostics['conflict_count']} conflicts)"
        )
        source_record_progress(
            "exact full-manifest reuse finished "
            f"({full_manifest_reuse_diagnostics['accepted_count']} of "
            f"{full_manifest_reuse_diagnostics['requested_count']} current "
            "declarations prevalidated; "
            f"{full_manifest_reuse_diagnostics['fresh_required_count']} require "
            "fresh Lean; "
            f"{full_manifest_reuse_diagnostics['conflict_count']} conflicts; "
            f"{len(seeded_prior_review_names)} legacy roots newly seeded)"
        )
    (
        elaborated_signature_sha256_by_qualified,
        elaborated_signature_manifests_by_qualified,
        elaborated_review_signature_errors,
    ) = elaborated_review_signature_surfaces(
        root=root,
        import_module=import_module,
        row_names=row_names,
        qualified_row_refs=qualified_row_refs,
        no_lean=bool(args.no_lean),
        analysis_qualified_names=analysis_qualified_row_refs.values(),
        additional_qualified_names=elaborated_record_manifest_names,
        semantic_dependency_modules=canonical_paper_lean_modules,
        prevalidated_manifests=prevalidated_manifests,
    )
    source_record_progress(
        "exact elaborated review-signature scan finished "
        f"({len(elaborated_signature_manifests_by_qualified)} manifests; "
        f"{len(elaborated_review_signature_errors)} errors)"
    )
    # The authenticated store is intentionally only a partial scheduling
    # input.  Repeat every explicit companion contract against the complete
    # configured-root manifest set, and let this phase alone own structural
    # pair failures.  Rebuild the parser-facing maps before any binder, input,
    # or recursive-field audit consumes them.
    (
        contract_companion_surfaces,
        contract_companion_surface_errors,
    ) = semantic_model_review_contract_companion_surfaces(
        companion_routes=semantic_model_contract_companions,
        semantic_declarations=semantic_declarations,
        proposition_aliases=proposition_aliases,
        type_aliases=semantic_type_aliases,
        elaborated_manifests_by_qualified=(
            elaborated_signature_manifests_by_qualified
        ),
    )
    source_coverage_selection["source_coverage_route_errors"] = sorted(
        set(
            list(
                source_coverage_selection.get("source_coverage_route_errors", [])
                or []
            )
            + contract_companion_surface_errors
        )
    )
    rebuild_review_surface_maps(contract_companion_surfaces)
    row_records = discover_row_records()
    delegated_empty_input_rows = semantic_contract_delegated_empty_input_rows(
        review_surfaces
    )

    # A graph-only Spec may reveal structural model roots only after its pair
    # has been authenticated.  Request just those newly discovered roots;
    # every already acquired configured-root manifest is fed back as
    # prevalidated input, so phase correction cannot duplicate fresh Lean
    # work.
    final_record_manifest_names = record_manifest_names_for(row_records)
    newly_discovered_record_manifest_names = (
        final_record_manifest_names - set(elaborated_signature_manifests_by_qualified)
    )
    elaborated_record_manifest_names = final_record_manifest_names
    if newly_discovered_record_manifest_names and not args.no_lean:
        (
            elaborated_signature_sha256_by_qualified,
            elaborated_signature_manifests_by_qualified,
            refreshed_elaborated_review_signature_errors,
        ) = elaborated_review_signature_surfaces(
            root=root,
            import_module=import_module,
            row_names=row_names,
            qualified_row_refs=qualified_row_refs,
            no_lean=False,
            analysis_qualified_names=analysis_qualified_row_refs.values(),
            additional_qualified_names=elaborated_record_manifest_names,
            semantic_dependency_modules=canonical_paper_lean_modules,
            prevalidated_manifests=(
                elaborated_signature_manifests_by_qualified
            ),
        )
        elaborated_review_signature_errors = sorted(
            set(refreshed_elaborated_review_signature_errors)
        )
        source_record_progress(
            "post-contract structural-root manifest scan finished "
            f"({len(newly_discovered_record_manifest_names)} newly scheduled; "
            f"{len(elaborated_review_signature_errors)} errors)"
        )
    (
        positional_signature_manifests_by_row,
        positional_signature_routes_by_row,
        positional_signature_manifest_errors,
    ) = semantic_contract_positional_signature_manifests(
        review_surfaces=review_surfaces,
        elaborated_manifests_by_qualified=elaborated_signature_manifests_by_qualified,
    )
    elaborated_review_signature_errors = sorted(
        set(elaborated_review_signature_errors + positional_signature_manifest_errors)
    )
    semantic_dependency_sha256_by_qualified = {
        qualified: str(
            (manifest.get("semantic_dependency_manifest") or {}).get(
                "semantic_dependency_sha256"
            )
            or ""
        ).strip().lower()
        for qualified, manifest in elaborated_signature_manifests_by_qualified.items()
        if isinstance(manifest.get("semantic_dependency_manifest"), Mapping)
        and SHA256_RE.fullmatch(
            str(
                (manifest.get("semantic_dependency_manifest") or {}).get(
                    "semantic_dependency_sha256"
                )
                or ""
            ).strip().lower()
        )
    }
    reachable_auxiliary_routing = reachable_paper_interface_auxiliary_routing(
        paper_dir=paper_dir,
        status_path=status_path,
        interface_declarations=interface_declarations,
        selected_qualified_names=active_selected_qualified_names,
        selected_row_names_by_qualified=selected_row_names_by_qualified,
        auxiliary_qualified_names=auxiliary_qualified_names,
        quarantined_auxiliary_qualified_names=(
            quarantined_auxiliary_qualified_names
        ),
        local_declarations=semantic_declarations,
        dependency_graphs_by_qualified=(
            elaborated_signature_manifests_by_qualified
        ),
    )
    source_identities_by_path = {
        interface_path.resolve(): interface_source_identity,
    }
    if proof_source_identity is not None and proof_path is not None:
        source_identities_by_path[proof_path.resolve()] = proof_source_identity
    if assumption_source_identity is not None:
        source_identities_by_path[assumptions_path.resolve()] = assumption_source_identity
    configured_review_rows: list[dict[str, Any]] = []
    for row in row_names:
        source_path = selected_row_source_paths[row]
        source_identity = source_identities_by_path.get(source_path.resolve())
        if source_identity is None:
            source_identity = source_artifact_identity(root, source_path)
        configured_review_rows.append(
            {
                "row": row,
                "qualified_declaration": qualified_row_refs[row],
                "source_file": source_identity["path"],
                "source_sha256": source_identity["sha256"],
                "elaborated_signature_sha256": (
                    elaborated_signature_sha256_by_qualified.get(
                        qualified_row_refs[row], ""
                    )
                ),
                "semantic_dependency_sha256": (
                    semantic_dependency_sha256_by_qualified.get(
                        qualified_row_refs[row], ""
                    )
                ),
                "elaborated_proposition_graph_sha256": (
                    elaborated_proposition_graph_sha256(
                        elaborated_signature_manifests_by_qualified.get(
                            qualified_row_refs[row], {}
                        ).get("elaborated_proposition_graph")
                    )
                ),
                "lean_source_declaration": declarations[row],
                "effective_qualified_declaration": analysis_qualified_row_refs[row],
                "effective_lean_source_declaration": analysis_declarations[row],
                "review_alias_expansion": review_surfaces[
                    row
                ].review_alias_expansion,
                "has_discovered_semantic_inputs": bool(
                    row_visible_inputs.get(row) or row_records.get(row)
                ),
            }
        )

    # `assumption_names` can expose a supplemental source-model declaration
    # for semantic comparison without making it a selected source-presentation
    # route.  Its record closure belongs on the ordinary recursive-field
    # surface only when an exact selected review route actually reaches it.
    # Keep all row roots below for semantic-model/conclusion diagnostics; this
    # narrow scope governs only standalone recursive-field judgments.
    recursive_field_route_scope = (
        recursive_field_rows_reachable_from_selected_review_routes(
            source_selected_rows=source_selected_rows,
            formalization_scope_target_rows=(
                source_coverage_selection.get("semantic_model_scope_target_rows")
                or []
            ),
            explicit_source_target_rows=(
                source_coverage_selection.get(
                    "semantic_model_explicit_source_target_rows"
                )
                or []
            ),
            effective_rows=row_names,
            qualified_row_refs=qualified_row_refs,
            local_declarations=recursive_field_route_declarations,
            elaborated_signature_sha256_by_qualified=(
                elaborated_signature_sha256_by_qualified
            ),
            elaborated_manifests_by_qualified=(
                elaborated_signature_manifests_by_qualified
            ),
        )
    )
    recursive_field_scope_rows = {
        str(item.get("row") or ""): item
        for item in recursive_field_route_scope.get("rows", [])
        if isinstance(item, Mapping) and str(item.get("row") or "").strip()
    }
    recursive_field_included_rows = {
        str(row).strip()
        for row in recursive_field_route_scope.get("included_rows", [])
        if str(row).strip()
    }
    recursive_fields: list[FieldInfo] = []
    recursion_failures: list[RecursionFailure] = []
    seen_fields: set[tuple[str, str]] = set()
    fields_by_root: dict[str, list[FieldInfo]] = {}
    recursive_field_selected_route_occurrences: dict[
        tuple[str, str], list[dict[str, Any]]
    ] = {}
    for row in row_names:
        for record in row_records.get(row, []):
            fields, failures = recursively_collect_fields(
                record,
                structures,
                candidate_structures,
                structure_aliases,
                args.max_depth,
                proposition_heads=proposition_heads,
                data_heads=semantic_data_heads,
            )
            # Other audit surfaces retain the complete row-local field closure
            # even where this root is outside selected recursive-field scope.
            fields_by_root.setdefault(record, fields)
            if row not in recursive_field_included_rows:
                continue
            recursion_failures.extend(failures)
            scope_row = recursive_field_scope_rows.get(row, {})
            route_paths = (
                scope_row.get("selected_route_paths", [])
                if isinstance(scope_row, Mapping)
                else []
            )
            if not isinstance(route_paths, list):
                route_paths = []
            for field in fields:
                key = (field.structure, field.field)
                if key not in seen_fields:
                    seen_fields.add(key)
                    recursive_fields.append(field)
                occurrence_base: dict[str, Any] = {
                    "review_row": row,
                    "reviewed_qualified_declaration": qualified_row_refs.get(
                        row, ""
                    ),
                    "record_root": record,
                    "recursive_field_path": field.path,
                }
                reached_signature = str(
                    elaborated_signature_sha256_by_qualified.get(
                        qualified_row_refs.get(row, ""), ""
                    )
                    or ""
                ).strip().lower()
                if SHA256_RE.fullmatch(reached_signature):
                    occurrence_base[
                        "reviewed_elaborated_signature_sha256"
                    ] = reached_signature
                occurrences = route_paths or [
                    {
                        "reachability": str(
                            scope_row.get("disposition")
                            if isinstance(scope_row, Mapping)
                            else "retained_due_to_incomplete_reachability_analysis"
                        )
                    }
                ]
                bucket = recursive_field_selected_route_occurrences.setdefault(
                    key, []
                )
                for route_path in occurrences:
                    if not isinstance(route_path, Mapping):
                        continue
                    occurrence = {
                        **occurrence_base,
                        "selected_route_path": dict(route_path),
                    }
                    if occurrence not in bucket:
                        bucket.append(occurrence)
    recursion_failures = dedupe_recursion_failures(recursion_failures)
    source_record_progress("Lean row-binder sort scan started")
    (
        row_input_proposition_sorts,
        row_input_proposition_sort_errors,
    ) = lean_row_input_proposition_sorts(
        root=root,
        import_module=import_module,
        row_inputs=row_inputs,
        row_conclusion_inputs=row_conclusion_inputs,
        analysis_qualified_row_refs=analysis_qualified_row_refs,
        no_lean=bool(args.no_lean),
        elaborated_signature_manifests=(
            elaborated_signature_manifests_by_qualified
        ),
        semantic_dependency_modules=canonical_paper_lean_modules,
        delegated_empty_input_rows=delegated_empty_input_rows,
        positional_signature_manifests_by_row=positional_signature_manifests_by_row,
    )
    source_record_progress(
        "Lean row-binder sort scan finished "
        f"({len(row_input_proposition_sort_errors)} errors)"
    )
    result_input_paths_by_row: dict[str, dict[int, dict[str, Any]]] = {}
    result_input_path_errors: list[str] = []
    for row in row_names:
        if row in delegated_empty_input_rows:
            continue
        qualified = analysis_qualified_row_refs.get(row, "")
        paths, path_errors = elaborated_result_input_path_receipts(
            header_inputs=row_inputs.get(row, []),
            conclusion_inputs=row_conclusion_inputs.get(row, []),
            manifest=positional_signature_manifests_by_row.get(
                row, elaborated_signature_manifests_by_qualified.get(qualified)
            ),
        )
        if path_errors:
            result_input_path_errors.extend(
                f"{qualified or row}: {error}" for error in path_errors
            )
            continue
        result_input_paths_by_row[row] = paths
    recursive_field_scan_started = time.monotonic()
    source_record_progress(
        f"Lean recursive-field sort scan started ({len(recursive_fields)} fields)"
    )
    recursive_field_scan_diagnostics: dict[str, Any] = {}
    (
        recursive_field_proposition_sorts,
        recursive_field_proposition_sort_errors,
    ) = lean_recursive_field_proposition_sorts(
        root=root,
        import_module=import_module,
        fields=recursive_fields,
        no_lean=bool(args.no_lean),
        diagnostics_out=recursive_field_scan_diagnostics,
    )
    source_record_progress(
        "Lean recursive-field sort scan finished "
        f"({len(recursive_field_proposition_sort_errors)} errors; "
        f"{structural_scan_progress_summary(recursive_field_scan_diagnostics)}; "
        f"{time.monotonic() - recursive_field_scan_started:.1f}s elapsed)"
    )
    constructor_slot_scan_diagnostics: dict[str, Any] = {}
    with source_record_progress_phase("Lean constructor-slot reconciliation"):
        constructor_slot_reconciliation_errors = (
            constructor_field_slot_reconciliation_errors(
                root=root,
                import_module=import_module,
                root_structures={
                    record
                    for row, records in row_records.items()
                    if row in recursive_field_included_rows
                    for record in records
                },
                recursive_fields=recursive_fields,
                structures=structures,
                field_safety_receipts=recursive_field_proposition_sorts,
                no_lean=bool(args.no_lean),
                diagnostics_out=constructor_slot_scan_diagnostics,
            )
        )
    source_record_progress(
        "Lean constructor-slot reconciliation reuse "
        f"({structural_scan_progress_summary(constructor_slot_scan_diagnostics)})"
    )
    if constructor_slot_reconciliation_errors:
        recursive_field_proposition_sort_errors.extend(
            constructor_slot_reconciliation_errors
        )
        recursion_failures.extend(
            RecursionFailure(
                kind="constructor_field_slot_reconciliation",
                structure="<Lean CtorInfo.numFields>",
                path="source-record recursive field surface",
                message=error,
            )
            for error in constructor_slot_reconciliation_errors
        )
        recursion_failures = dedupe_recursion_failures(recursion_failures)
    type_witness_scan_started = time.monotonic()
    source_record_progress("Lean type-certificate payload scan started")
    type_witness_scan_diagnostics: dict[str, Any] = {}
    (
        elaborated_type_witness_payload_receipts,
        elaborated_type_witness_payload_safety_errors,
    ) = lean_type_witness_payload_safeties(
        root=root,
        import_module=import_module,
        qualified_declarations=sorted(
            {qualified for qualified in analysis_qualified_row_refs.values() if qualified}
        ),
        no_lean=bool(args.no_lean),
        diagnostics_out=type_witness_scan_diagnostics,
    )
    source_record_progress(
        "Lean type-certificate payload scan finished "
        f"({len(elaborated_type_witness_payload_safety_errors)} errors; "
        f"{structural_scan_progress_summary(type_witness_scan_diagnostics)}; "
        f"{time.monotonic() - type_witness_scan_started:.1f}s elapsed)"
    )

    # A result-level `Nonempty Record` or existential record witness can hide
    # all of the record's proof fields behind one coarse existence proposition.
    # Keep this separate from theorem *inputs*: it is a source-coverage rule,
    # not a claim that the theorem consumed an unproved premise.
    type_certificate_result_items = type_valued_certificate_result_items(
        row_names=row_names,
        declarations=analysis_declarations,
        structures=structures,
        aliases=structure_aliases,
        proposition_heads=proposition_heads,
        row_qualified_names=analysis_qualified_row_refs,
        proposition_aliases=proposition_aliases,
        proposition_wrapper_structures=proposition_wrapper_structures,
        elaborated_type_witness_receipts=elaborated_type_witness_payload_receipts,
    )

    conclusion_dependency_input_atom_errors: list[str] = []
    conclusion_dependencies = conclusion_dependency_items(
        row_names=row_names,
        declarations=analysis_declarations,
        # Conclusion dependency traversal must see both sections exactly once.
        # Header-only `row_inputs` above is reserved for Lean positional sort
        # matching and boundary diagnostics.
        row_inputs=row_visible_inputs,
        row_records=row_records,
        fields_by_root=fields_by_root,
        local_declarations=local_declarations,
        aliases=structure_aliases,
        structures=structures,
        proposition_heads=proposition_heads,
        proposition_aliases=proposition_aliases,
        data_heads=semantic_data_heads,
        semantic_declarations=semantic_declarations,
        row_qualified_names=analysis_qualified_row_refs,
        elaborated_manifests_by_qualified=(
            elaborated_signature_manifests_by_qualified
        ),
        elaborated_input_atom_errors=(
            conclusion_dependency_input_atom_errors
        ),
        delegated_empty_input_rows=delegated_empty_input_rows,
        positional_signature_manifests_by_row=positional_signature_manifests_by_row,
    )
    result_paths_by_judgment_key: dict[str, list[dict[str, Any]]] = {}
    for row, paths in result_input_paths_by_row.items():
        for input_index, path in paths.items():
            inputs = row_conclusion_inputs.get(row, [])
            if input_index < 0 or input_index >= len(inputs):
                result_input_path_errors.append(
                    f"{analysis_qualified_row_refs.get(row, row)}: result-path receipt has an out-of-range input index"
                )
                continue
            key = boundary_input_judgment_key(row, inputs[input_index])
            result_paths_by_judgment_key.setdefault(key, []).append(path)
    input_proposition_sort_by_judgment_key: dict[str, str] = {}
    input_structural_type_sha256_by_judgment_key: dict[str, str] = {}
    for row in row_names:
        row_free_identifiers = {
            name
            for visible_input in (
                row_inputs.get(row, []) + row_conclusion_inputs.get(row, [])
            )
            for name in binder_names(visible_input.get("names", ""))
        }
        for section, inputs in (
            ("boundary_input_items", row_inputs.get(row, [])),
            ("conclusion_dependency_items", row_conclusion_inputs.get(row, [])),
        ):
            for input_index, visible_input in enumerate(inputs):
                key = boundary_input_judgment_key(row, visible_input)
                proposition_sort = row_input_proposition_sorts.get(
                    (row, section, input_index), "unknown"
                )
                prior = input_proposition_sort_by_judgment_key.get(key)
                input_proposition_sort_by_judgment_key[key] = (
                    proposition_sort
                    if prior in (None, proposition_sort)
                    else "unknown"
                )
                structural_type = structural_type_sha256(
                    visible_input.get("type", ""), row_free_identifiers
                )
                prior_structural_type = input_structural_type_sha256_by_judgment_key.get(
                    key
                )
                input_structural_type_sha256_by_judgment_key[key] = (
                    structural_type
                    if prior_structural_type in (None, structural_type)
                    else ""
                )
    for dependency in conclusion_dependencies:
        row = str(dependency.get("row") or "").strip()
        dependency_key = str(dependency.get("judgment_key") or "").strip()
        proposition_sort = input_proposition_sort_by_judgment_key.get(
            dependency_key,
            "unknown",
        )
        if dependency.get("conclusion_fields"):
            proposition_sort = "false"
        dependency["proposition_sort"] = proposition_sort
        dependency["structural_type_sha256"] = (
            input_structural_type_sha256_by_judgment_key.get(dependency_key, "")
        )
        kind = str(dependency.get("kind") or "").strip()
        dependency["theorem_facing_semantic_role"] = (
            "proof_bearing"
            if (
                kind in PROOF_BEARING_CONCLUSION_DEPENDENCY_KINDS
                or proposition_sort == "true"
            )
            else (
                "unclassified_theorem_input"
                if proposition_sort == "unknown"
                else "data_or_container"
            )
        )
        dependency["semantic_restriction_role"] = (
            "requires_source_or_lean_closure"
            if dependency["theorem_facing_semantic_role"] == "proof_bearing"
            else (
                "unclassified"
                if dependency["theorem_facing_semantic_role"]
                == "unclassified_theorem_input"
                else "carrier_coherence_only"
            )
        )
        dependency["semantic_restriction_candidates"] = sorted(
            {
                *(
                    {"lean_proposition_value"}
                    if proposition_sort == "true"
                    else set()
                ),
                *(
                    {"unavailable_or_opaque_lean_sort"}
                    if proposition_sort == "unknown"
                    else set()
                ),
                *(
                    {"structural_" + kind}
                    if kind in PROOF_BEARING_CONCLUSION_DEPENDENCY_KINDS
                    else set()
                ),
            }
        )
        dependency["source_claim_component_role"] = "material"
        dependency["source_claim_component_kind"] = "dependency_path"
        dependency["elaborated_signature_sha256"] = (
            elaborated_signature_sha256_by_qualified.get(
                analysis_qualified_row_refs.get(row, ""), ""
            )
        )
        matching_paths = result_paths_by_judgment_key.get(dependency_key, [])
        if len(matching_paths) == 1:
            dependency["elaborated_result_path"] = matching_paths[0]
        elif len(matching_paths) > 1:
            result_input_path_errors.append(
                f"{analysis_qualified_row_refs.get(row, row)}: conclusion dependency has multiple result-path receipts"
            )
        dependency["proposition_sort_evidence"] = (
            "lean_row_binder_sort"
            if dependency_key in input_proposition_sort_by_judgment_key
            and not args.no_lean
            else "lean_row_binder_sort_unavailable"
        )
        if row not in review_surfaces:
            continue
        dependency["lean_source_declaration"] = declarations[row]
        dependency["effective_qualified_declaration"] = (
            analysis_qualified_row_refs[row]
        )
        dependency["effective_lean_source_declaration"] = analysis_declarations[row]
        dependency["review_alias_expansion"] = review_surfaces[
            row
        ].review_alias_expansion
    constructor_result_scan_diagnostics: dict[str, Any] = {}
    with source_record_progress_phase(
        "elaborated constructor-result compatibility scan"
    ):
        constructor_result_type_check_error = enforce_elaborated_constructor_result_types(
            root=root,
            import_module=import_module,
            review_source_path=interface_path,
            conclusion_dependencies=conclusion_dependencies,
            row_inputs=row_visible_inputs,
            row_qualified_names=qualified_row_refs,
            diagnostics_out=constructor_result_scan_diagnostics,
        )
    source_record_progress(
        "elaborated constructor-result compatibility reuse "
        f"({structural_scan_progress_summary(constructor_result_scan_diagnostics)})"
    )

    # A conditional constructor is only a type-compatible *possible* route.
    # Its antecedents stay attached to that candidate as diagnostics; they are
    # not recursively audited source debt unless a sidecar later selects the
    # exact route through checked_projection.  Promoting all candidates here
    # made an internal helper theorem look like an additional paper assumption,
    # even when the reviewed proof never uses that helper.  The projection
    # contract remains fail-closed: a selected route must still name exactly
    # these antecedent keys and each must carry current source evidence.
    semantic_row_items = [
        {
            "row": row,
            "visible_inputs": row_visible_inputs.get(row, []),
            "conclusion_inputs": row_conclusion_inputs.get(row, []),
            "record_premises": row_records.get(row, []),
            "lean_source_declaration": declarations[row],
            "effective_qualified_declaration": analysis_qualified_row_refs[row],
            "effective_lean_source_declaration": analysis_declarations[row],
            "review_alias_expansion": review_surfaces[
                row
            ].review_alias_expansion,
            "required_check": "Every declaration-binder input must be semantically matched to "
            "the paper source model, not accepted by name. Result-level forall/arrow clauses "
            "and dependent `if` proof guards are recorded as conclusion_inputs and audited "
            "as visible premises; changing a parenthesized binder into an implication or "
            "moving it under a conditional cannot evade this lane. Every "
            "record/certificate/replay/process/bridge premise below must be recursively "
            "proved from primitives, validated as an explicit paper source assumption, "
            "approved as an external boundary, or marked unresolved proof debt.",
        }
        for row in row_names
        if row_inputs.get(row) or row_conclusion_inputs.get(row) or row_records.get(row)
    ]

    # Keep one canonical, generator-owned ledger for *every* theorem-facing
    # input.  The older boundary and conclusion-dependency projections remain
    # useful specialized diagnostics, but neither is complete: an ordinary
    # result-level implication/forall premise need not look like a conclusion
    # dependency.  This surface is deliberately driven by the parsed actual
    # declaration and Lean's sort receipt, not by binder/function spelling.
    specialized_proof_kinds_by_key: dict[str, set[str]] = {}
    for dependency in conclusion_dependencies:
        dependency_key = str(dependency.get("judgment_key") or "").strip()
        dependency_kind = str(dependency.get("kind") or "").strip()
        if (
            dependency_key
            and dependency_kind in PROOF_BEARING_CONCLUSION_DEPENDENCY_KINDS
        ):
            specialized_proof_kinds_by_key.setdefault(dependency_key, set()).add(
                dependency_kind
            )

    theorem_facing_input_items: list[dict[str, Any]] = []
    for row in row_names:
        qualified_row = analysis_qualified_row_refs.get(row, row)
        context_namespace = (
            qualified_row.rsplit(".", 1)[0] if "." in qualified_row else ""
        )
        row_free_identifiers = {
            name
            for visible_input in (
                row_inputs.get(row, []) + row_conclusion_inputs.get(row, [])
            )
            for name in binder_names(visible_input.get("names", ""))
        }
        row_proposition_aliases = proposition_aliases_in_namespace(
            proposition_aliases, context_namespace
        )
        data_heads = (
            semantic_data_heads
            | declaration_type_variable_heads(analysis_declarations[row])
        )
        input_scope: set[str] = set()
        outer_binder_cursor = 0
        for input_section, visible_inputs in (
            ("header", row_inputs.get(row, [])),
            ("result", row_conclusion_inputs.get(row, [])),
        ):
            sort_section = (
                "boundary_input_items"
                if input_section == "header"
                else "conclusion_dependency_items"
            )
            for input_index, visible_input in enumerate(visible_inputs):
                alias_expansion = delta_expand_transparent_proposition_aliases(
                    visible_input.get("type", ""),
                    proposition_aliases,
                    semantic_declarations,
                    context_namespace=context_namespace,
                    shadowed_names=input_scope,
                )
                expanded_input = {
                    **visible_input,
                    "type": alias_expansion.expanded_type,
                }
                judgment_key = boundary_input_judgment_key(row, visible_input)
                proposition_sort = row_input_proposition_sorts.get(
                    (row, sort_section, input_index), "unknown"
                )
                input_origin = str(
                    visible_input.get("input_origin")
                    or (
                        "header_binder"
                        if input_section == "header"
                        else "result_forall_or_arrow"
                    )
                ).strip()
                is_outer_binder = input_origin != "dependent_if_guard"
                binder_arity = _input_binder_arity(visible_input)
                outer_indices = (
                    list(
                        range(
                            outer_binder_cursor,
                            outer_binder_cursor + binder_arity,
                        )
                    )
                    if is_outer_binder
                    else []
                )
                if is_outer_binder:
                    outer_binder_cursor += binder_arity
                result_path = (
                    result_input_paths_by_row.get(row, {}).get(input_index)
                    if input_section == "result"
                    else None
                )
                # An untyped `∀ terminal, ...` is conclusion-domain data,
                # not an independently supplied theorem premise.  Retain its
                # exact manifest path as scope for later result inputs, but do
                # not manufacture a source-record obligation from a parser
                # placeholder with no Lean-owned domain type.
                if input_origin == "result_forall_inferred_domain":
                    if result_path is None:
                        result_input_path_errors.append(
                            f"{analysis_qualified_row_refs.get(row, row)}: inferred result-domain binder has no elaborated result-path receipt"
                        )
                    if is_outer_binder:
                        input_scope.update(
                            binder_names(visible_input.get("names", ""))
                        )
                    continue
                specialized_kinds = sorted(
                    specialized_proof_kinds_by_key.get(judgment_key, set())
                )
                semantic_input_kind = (
                    boundary_input_kind(
                        row,
                        expanded_input,
                        proposition_heads=proposition_heads,
                        data_heads=data_heads,
                    )
                    or "data_or_container_input"
                )
                semantic_restriction_role, restriction_candidates = (
                    semantic_restriction_metadata(
                        proposition_sort=proposition_sort,
                        semantic_input_kind=semantic_input_kind,
                        input_origin=input_origin,
                        specialized_kinds=specialized_kinds,
                    )
                )
                domain_refinement_candidates = structural_domain_refinement_kinds(
                    alias_expansion.expanded_type,
                    input_origin=input_origin,
                )
                restriction_candidates = sorted(
                    set(restriction_candidates)
                    | set(domain_refinement_candidates)
                )
                if (
                    domain_refinement_candidates
                    and semantic_restriction_role == "carrier_coherence_only"
                ):
                    semantic_restriction_role = "unclassified"
                semantic_role = (
                    "proof_bearing"
                    if semantic_restriction_role == "requires_source_or_lean_closure"
                    else (
                        "unclassified_theorem_input"
                        if semantic_restriction_role == "unclassified"
                        else "data_or_container"
                    )
                )
                theorem_facing_input_items.append(
                    {
                        "row": row,
                        "kind": "theorem_facing_input",
                        "input": visible_input,
                        "input_section": input_section,
                        "input_origin": input_origin,
                        "expanded_input_type": alias_expansion.expanded_type,
                        "structural_type_sha256": structural_type_sha256(
                            alias_expansion.expanded_type,
                            row_free_identifiers,
                        ),
                        **proposition_alias_expansion_payload(alias_expansion),
                        "semantic_input_kind": semantic_input_kind,
                        # Every elaborated theorem input is material until an
                        # explicit source-claim disposition says otherwise.
                        # In particular, a carrier/function value does not
                        # become harmless just because Lean classifies its
                        # sort as non-Prop.
                        "source_claim_component_role": "material",
                        "source_claim_component_kind": "theorem_input",
                        "proposition_sort": proposition_sort,
                        "proposition_sort_evidence": (
                            "lean_row_binder_sort"
                            if not args.no_lean
                            and (row, sort_section, input_index)
                            in row_input_proposition_sorts
                            else "lean_row_binder_sort_unavailable"
                        ),
                        "theorem_facing_semantic_role": semantic_role,
                        "semantic_restriction_role": semantic_restriction_role,
                        "semantic_restriction_candidates": restriction_candidates,
                        "specialized_proof_dependency_kinds": specialized_kinds,
                        "result_relation": boundary_input_result_relation(
                            analysis_declarations[row],
                            expanded_input,
                            proposition_heads=proposition_heads,
                            proposition_aliases=row_proposition_aliases,
                        ),
                        "judgment_key": judgment_key,
                        "source_judgment_key": judgment_key,
                        "lean_outer_binder_indices": outer_indices,
                        "lean_outer_binder_route": (
                            "outer_telescope"
                            if is_outer_binder
                            else "dependent_result_guard"
                        ),
                        "lean_source_declaration": declarations[row],
                        "elaborated_signature_sha256": (
                            elaborated_signature_sha256_by_qualified.get(
                                analysis_qualified_row_refs[row], ""
                            )
                        ),
                        "effective_qualified_declaration": analysis_qualified_row_refs[
                            row
                        ],
                        "effective_lean_source_declaration": analysis_declarations[
                            row
                        ],
                        "review_alias_expansion": review_surfaces[
                            row
                        ].review_alias_expansion,
                        **(
                            {"elaborated_result_path": result_path}
                            if result_path is not None
                            else {}
                        ),
                        "required_check": "This canonical theorem-facing input is audited regardless of whether it is written in the declaration header, as a result-level forall/arrow premise, or as a dependent result guard. A proof-bearing or unclassified semantic role needs an exact source-assumption disposition or a Lean-owned construction route; declaration, binder, and helper names are navigation only.",
                    }
                )
                # A dependent `if h : P` proof name is local to the result
                # branch, not a subsequent outer binder. Do not let its
                # synthetic diagnostic name alter lexical source expansion.
                if is_outer_binder:
                    input_scope.update(
                        binder_names(visible_input.get("names", ""))
                    )

    boundary_input_items: list[dict[str, Any]] = []
    for row in row_names:
        qualified_row = analysis_qualified_row_refs.get(row, row)
        context_namespace = (
            qualified_row.rsplit(".", 1)[0] if "." in qualified_row else ""
        )
        row_free_identifiers = {
            name
            for visible_input in (
                row_inputs.get(row, []) + row_conclusion_inputs.get(row, [])
            )
            for name in binder_names(visible_input.get("names", ""))
        }
        row_proposition_aliases = proposition_aliases_in_namespace(
            proposition_aliases, context_namespace
        )
        input_scope: set[str] = set()
        for input_index, visible_input in enumerate(row_inputs.get(row, [])):
            alias_expansion = delta_expand_transparent_proposition_aliases(
                visible_input.get("type", ""),
                proposition_aliases,
                semantic_declarations,
                context_namespace=context_namespace,
                shadowed_names=input_scope,
            )
            expanded_input = {
                **visible_input,
                "type": alias_expansion.expanded_type,
            }
            kind = boundary_input_kind(
                row,
                expanded_input,
                proposition_heads=proposition_heads,
                data_heads=(
                    semantic_data_heads
                    | declaration_type_variable_heads(analysis_declarations[row])
                ),
            )
            if kind:
                proposition_sort = row_input_proposition_sorts.get(
                    (row, "boundary_input_items", input_index), "unknown"
                )
                boundary_input_items.append(
                    {
                        "row": row,
                        # Keep the original binder spelling in the judgment key
                        # so prior source anchors remain traceable. The expanded
                        # proposition below is the semantic review surface.
                        "input": visible_input,
                        "expanded_input_type": alias_expansion.expanded_type,
                        "structural_type_sha256": structural_type_sha256(
                            alias_expansion.expanded_type,
                            row_free_identifiers,
                        ),
                        **proposition_alias_expansion_payload(alias_expansion),
                        "kind": kind,
                        "proposition_sort": proposition_sort,
                        "proposition_sort_evidence": (
                            "lean_row_binder_sort"
                            if not args.no_lean
                            and (row, "boundary_input_items", input_index)
                            in row_input_proposition_sorts
                            else "lean_row_binder_sort_unavailable"
                        ),
                        "theorem_facing_semantic_role": (
                            "proof_bearing"
                            if proposition_sort == "true"
                            else (
                                "unclassified_theorem_input"
                                if proposition_sort == "unknown"
                                else "data"
                            )
                        ),
                        "semantic_restriction_role": (
                            "requires_source_or_lean_closure"
                            if proposition_sort == "true"
                            else (
                                "unclassified"
                                if proposition_sort == "unknown"
                                else "carrier_coherence_only"
                            )
                        ),
                        "semantic_restriction_candidates": (
                            ["lean_proposition_value"]
                            if proposition_sort == "true"
                            else (
                                ["unavailable_or_opaque_lean_sort"]
                                if proposition_sort == "unknown"
                                else []
                            )
                        ),
                        "result_relation": boundary_input_result_relation(
                            analysis_declarations[row],
                            expanded_input,
                            proposition_heads=proposition_heads,
                            proposition_aliases=row_proposition_aliases,
                        ),
                        "judgment_key": boundary_input_judgment_key(row, visible_input),
                        "lean_source_declaration": declarations[row],
                        "effective_qualified_declaration": analysis_qualified_row_refs[
                            row
                        ],
                        "effective_lean_source_declaration": analysis_declarations[
                            row
                        ],
                        "review_alias_expansion": review_surfaces[
                            row
                        ].review_alias_expansion,
                        "required_check": "This visible theorem input is boundary-shaped. It needs a specific "
                        "source statement/primitive or a Lean-checked constructor from paper primitives; "
                        "the source-looking predicate name is not evidence. When expanded_input_type or "
                        "proposition_alias_expansion is present, audit that literal expanded proposition and "
                        "every blocked route rather than the wrapper spelling. A nonempty result_relation "
                        "means the input is equivalent to, provides, or is a logical component of the "
                        "advertised result. Such an input cannot supply source-facing coverage for that "
                        "same result merely by being caller-provided.",
                    }
                )
            input_scope.update(binder_names(visible_input.get("names", "")))
    judge_items = [
        item for item in semantic_row_items if item.get("record_premises")
    ]
    recursive_field_structural_type_sha256 = {}
    for field in recursive_fields:
        structure_info = structures.get(field.structure)
        parameter_names = (
            set(structure_info.parameters) if structure_info is not None else set()
        )
        if structure_info is not None:
            parameter_names.update(
                f"__arg{index}"
                for index in range(len(structure_info.parameters))
            )
        recursive_field_structural_type_sha256[
            f"{field.structure}.{field.field}"
        ] = structural_type_sha256(field.type, parameter_names)
    def generated_recursive_field_item(field: FieldInfo) -> dict[str, Any]:
        key = f"{field.structure}.{field.field}"
        selected_route_occurrences = recursive_field_selected_route_occurrences.get(
            (field.structure, field.field), []
        )
        safety_entry = recursive_field_proposition_sorts.get(key, {})
        locator = (
            safety_entry.get("locator")
            if isinstance(safety_entry, dict)
            else None
        )
        receipt = (
            safety_entry.get("receipt")
            if isinstance(safety_entry, dict)
            else None
        )
        if not isinstance(locator, dict):
            locator = {}
        if not isinstance(receipt, dict):
            receipt = {
                "value_sort": "unknown",
                "payload_safety": "unknown",
                "status": "error",
                "route": "missing_field_safety_receipt",
                "reason_codes": ["missing_field_safety_receipt"],
            }
        proposition_sort = str(receipt.get("value_sort") or "unknown").strip()
        payload_safety = str(receipt.get("payload_safety") or "unknown").strip()
        if proposition_sort == "true":
            theorem_role = "proof_bearing"
            restriction_role = "requires_source_or_lean_closure"
            restriction_candidates = ["lean_constructor_field_proposition_value"]
        elif proposition_sort != "false" or payload_safety == "unknown":
            theorem_role = "unclassified_theorem_input"
            restriction_role = "unclassified"
            restriction_candidates = ["unavailable_or_opaque_field_safety"]
        elif payload_safety == "structural_data":
            theorem_role = "data_or_container"
            restriction_role = "carrier_coherence_only"
            restriction_candidates = []
        elif payload_safety == "requires_semantic_route":
            theorem_role = "unclassified_theorem_input"
            restriction_role = "requires_semantic_route"
            restriction_candidates = ["prop_valued_function_requires_semantic_route"]
        else:
            theorem_role = "unclassified_theorem_input"
            restriction_role = "requires_source_or_lean_closure"
            restriction_candidates = ["nonfoundation_payload_requires_closure"]
        return {
            **asdict(field),
            "judgment_key": key,
            "source_claim_component_role": "material",
            "source_claim_component_kind": "recursive_record_field",
            "elaborated_field_safety_locator": locator,
            "elaborated_field_safety_receipt": receipt,
            "structural_type_sha256": recursive_field_structural_type_sha256.get(
                key, ""
            ),
            "proposition_sort": proposition_sort,
            "proposition_sort_evidence": "lean_field_slot_safety"
            if not args.no_lean and locator and receipt.get("status") == "ok"
            else "lean_field_slot_safety_unavailable",
            "payload_safety": payload_safety,
            "theorem_facing_semantic_role": theorem_role,
            "semantic_restriction_role": restriction_role,
            "semantic_restriction_candidates": restriction_candidates,
            # This is a generated selection receipt, not source-assumption
            # credit.  It identifies the exact selected review route(s) and
            # current field path(s) that made this otherwise generic Lean slot
            # material to the recursive-field surface.
            "selected_review_route_occurrences": selected_route_occurrences,
            "required_check": "Use the Lean-owned field-slot receipt rather than this field label when "
            "classifying data. Only `structural_data` may receive raw data credit. A nonfoundation "
            "wrapper or Prop-valued function requires an explicit source/Lean closure; a container "
            "classification is valid only when every generated nested field is current. "
            "The selected-route occurrence receipt is a scope boundary only and does not itself "
            "supply source-assumption credit.",
        }

    field_items = [generated_recursive_field_item(field) for field in recursive_fields]
    semantic_model_items = semantic_model_audit_items(
        row_names=row_names,
        declarations=declarations,
        row_inputs=row_visible_inputs,
        row_records=row_records,
        fields_by_root=fields_by_root,
        proposition_aliases=proposition_aliases,
        dimensions=semantic_model_dimensions,
        type_aliases=semantic_type_aliases,
        structures=structures,
        structure_aliases=structure_aliases,
        row_qualified_names=qualified_row_refs,
        semantic_declarations=semantic_declarations,
        elaborated_signature_manifests=elaborated_signature_manifests_by_qualified,
        review_surfaces=review_surfaces,
    )
    # Ordinary source coverage and supplemental convention provenance are
    # intentionally distinct.  A source-ledger field scope may select a
    # non-named model/convention item as the exact provenance parent of a
    # configured semantic row, but that item must not gain ordinary coverage
    # credit.  Keep the complete map only for this explicit scope join; all
    # ordinary coverage/contract lanes below retain the presentation-filtered
    # map.
    source_proof_fidelity = source_proof_fidelity_context(paper_dir)
    recursive_source_scopes, _recursive_source_scope_parse_errors = (
        recursive_field_source_scope_entries(source_proof_fidelity)
    )
    recursive_scope_source_item_ids = {
        str(scope["field_scope"]["source_item"])
        for scope in recursive_source_scopes
    }
    semantic_model_items = collapse_semantic_model_contract_pairs(
        semantic_model_items,
        paper_dir=paper_dir,
        declarations=declarations,
        row_qualified_names=qualified_row_refs,
        proposition_aliases=proposition_aliases,
        type_aliases=semantic_type_aliases,
        paper_statement_map=semantic_model_statement_map,
        elaborated_signature_sha256_by_qualified=(
            elaborated_signature_sha256_by_qualified
        ),
        elaborated_manifests_by_qualified=(
            elaborated_signature_manifests_by_qualified
        ),
    )
    (
        semantic_model_items,
        source_claim_atom_association_errors,
        source_claim_atom_association_counts,
    ) = attach_source_claim_atom_associations(
        semantic_model_items,
        paper_dir=paper_dir,
        paper_statement_map=semantic_model_statement_map,
        declarations=declarations,
        row_qualified_names=qualified_row_refs,
        elaborated_signature_sha256_by_qualified=(
            elaborated_signature_sha256_by_qualified
        ),
    )
    (
        semantic_model_items,
        explicit_direct_route_association_errors,
        explicit_direct_route_association_counts,
    ) = attach_explicit_direct_source_route_associations(
        semantic_model_items,
        paper_dir=paper_dir,
        paper_statement_map=complete_paper_statement_map,
        declarations=declarations,
        row_qualified_names=qualified_row_refs,
        elaborated_signature_sha256_by_qualified=(
            elaborated_signature_sha256_by_qualified
        ),
        additional_selected_source_item_ids=recursive_scope_source_item_ids,
        validated_vocabulary_binding_source_item_ids=(
            source_coverage_selection.get(
                "source_coverage_validated_vocabulary_binding_source_items",
                [],
            )
        ),
        validated_vocabulary_direct_route_source_item_ids=(
            source_coverage_selection.get(
                "source_coverage_validated_vocabulary_direct_route_source_items",
                [],
            )
        ),
    )
    (
        semantic_model_items,
        statement_source_component_association_errors,
        statement_source_component_association_counts,
    ) = attach_statement_source_component_associations(
        semantic_model_items,
        paper_dir=paper_dir,
        paper_statement_map=complete_paper_statement_map,
        source_proof_fidelity=source_proof_fidelity,
        elaborated_signature_manifests_by_qualified=(
            elaborated_signature_manifests_by_qualified
        ),
        elaborated_signature_sha256_by_qualified=(
            elaborated_signature_sha256_by_qualified
        ),
    )
    (
        semantic_model_items,
        assumption_source_review_association_errors,
        assumption_source_review_association_counts,
    ) = attach_assumption_source_review_associations(
        semantic_model_items,
        paper_dir=paper_dir,
        paper_statement_map=complete_paper_statement_map,
        source_proof_fidelity=source_proof_fidelity,
        elaborated_signature_manifests_by_qualified=(
            elaborated_signature_manifests_by_qualified
        ),
        elaborated_signature_sha256_by_qualified=(
            elaborated_signature_sha256_by_qualified
        ),
    )
    (
        semantic_model_items,
        conditional_probability_composition_errors,
        conditional_probability_composition_counts,
    ) = attach_conditional_probability_composition_requirements(
        semantic_model_items,
        paper_statement_map=semantic_model_statement_map,
        elaborated_signature_sha256_by_qualified=(
            elaborated_signature_sha256_by_qualified
        ),
    )
    (
        semantic_model_items,
        equality_defined_partition_errors,
        equality_defined_partition_counts,
    ) = attach_equality_defined_partition_requirements(
        semantic_model_items,
        paper_statement_map=semantic_model_statement_map,
        elaborated_signature_sha256_by_qualified=(
            elaborated_signature_sha256_by_qualified
        ),
    )
    (
        semantic_model_items,
        strategic_observation_totality_errors,
        strategic_observation_totality_counts,
    ) = attach_strategic_observation_totality_requirements(
        semantic_model_items,
        paper_statement_map=semantic_model_statement_map,
        elaborated_signature_sha256_by_qualified=(
            elaborated_signature_sha256_by_qualified
        ),
    )
    (
        semantic_model_items,
        conditioning_information_errors,
        conditioning_information_counts,
    ) = attach_conditioning_information_requirements(
        semantic_model_items,
        paper_statement_map=semantic_model_statement_map,
        elaborated_signature_sha256_by_qualified=(
            elaborated_signature_sha256_by_qualified
        ),
    )
    (
        semantic_model_items,
        source_model_derivation_errors,
        source_model_derivation_counts,
    ) = attach_source_model_derivation_requirements(
        semantic_model_items,
        paper_statement_map=semantic_model_statement_map,
        elaborated_signature_sha256_by_qualified=(
            elaborated_signature_sha256_by_qualified
        ),
    )
    attach_input_reviewed_declaration_identities(
        boundary_input_items,
        declarations=declarations,
        row_qualified_names=qualified_row_refs,
    )
    attach_input_reviewed_declaration_identities(
        theorem_facing_input_items,
        declarations=declarations,
        row_qualified_names=qualified_row_refs,
    )
    attach_input_reviewed_declaration_identities(
        conclusion_dependencies,
        declarations=declarations,
        row_qualified_names=qualified_row_refs,
    )
    attach_input_reviewed_declaration_identities(
        type_certificate_result_items,
        declarations=declarations,
        row_qualified_names=qualified_row_refs,
    )
    (
        source_contract_association_errors,
        source_contract_association_counts,
    ) = attach_source_contract_associations(
        boundary_input_items=boundary_input_items,
        theorem_facing_input_items=theorem_facing_input_items,
        type_valued_certificate_result_items=type_certificate_result_items,
        conclusion_dependency_items=conclusion_dependencies,
        semantic_model_items=semantic_model_items,
        paper_statement_map=semantic_model_statement_map,
        elaborated_signature_sha256_by_qualified=(
            elaborated_signature_sha256_by_qualified
        ),
    )
    (
        theorem_facing_contract_covered_input_keys,
        theorem_facing_input_contract_coverage,
        theorem_facing_contract_coverage_errors,
        theorem_facing_contract_coverage_counts,
    ) = theorem_facing_semantic_contract_coverage(
        theorem_facing_input_items=theorem_facing_input_items,
        type_valued_certificate_result_items=type_certificate_result_items,
        semantic_model_items=semantic_model_items,
    )
    (
        semantic_model_items,
        executable_terminal_receipt_errors,
        executable_terminal_receipt_counts,
    ) = attach_semantic_contract_executable_terminal_receipts(
        semantic_model_items,
        root=root,
        paper_dir=paper_dir,
        import_module=import_module,
        paper_modules=canonical_paper_lean_modules,
        no_lean=bool(args.no_lean),
        paper_statement_map=semantic_model_statement_map,
        elaborated_signature_sha256_by_qualified=(
            elaborated_signature_sha256_by_qualified
        ),
        semantic_dependency_sha256_by_qualified=(
            semantic_dependency_sha256_by_qualified
        ),
    )
    explicit_source_target_generated_item_errors = (
        explicit_source_target_semantic_model_item_errors(
            explicit_targets=explicit_source_targets,
            companion_routes=semantic_model_contract_companions,
            semantic_model_items=semantic_model_items,
        )
    )
    source_coverage_selection[
        "semantic_model_explicit_source_target_generated_item_errors"
    ] = explicit_source_target_generated_item_errors
    source_coverage_selection["semantic_model_target_route_errors"] = sorted(
        set(
            list(
                source_coverage_selection.get(
                    "semantic_model_target_route_errors", []
                )
                or []
            )
            + explicit_source_target_generated_item_errors
        )
    )
    # Route/configuration errors are semantic-model configuration failures,
    # not reviewer judgments.  Expose the detailed lanes separately below,
    # but make every such failure block a source-record closeout immediately.
    semantic_model_config_errors.extend(
        source_coverage_selection.get("semantic_model_target_route_errors", [])
        or []
    )
    semantic_model_config_errors.extend(
        semantic_model_dimension_configuration_errors(
            semantic_model_items, semantic_model_dimensions
        )
    )
    # Recursive-field source credit has a different proof route from an
    # ordinary theorem-boundary association.  Load the source ledger before
    # aggregate association errors are finalized, then attach a receipt only
    # when its exact structural path, current direct parent route, selected
    # source item, and listed convention all agree.
    (
        recursive_field_source_association_errors,
        recursive_field_source_association_counts,
    ) = attach_recursive_field_explicit_parent_route_associations(
        field_items=field_items,
        semantic_model_items=semantic_model_items,
        paper_statement_map=complete_paper_statement_map,
        source_proof_fidelity=source_proof_fidelity,
        elaborated_signature_sha256_by_qualified=(
            elaborated_signature_sha256_by_qualified
        ),
    )
    selection_errors = [
        str(source_coverage_selection.get("source_coverage_selection_error") or "").strip()
    ]
    selection_errors.extend(
        "selected source-coverage item has no explicit direct/Spec Lean route: "
        + str(source_key)
        for source_key in source_coverage_selection.get(
            "source_coverage_unrouted_source_items"
        )
        or []
    )
    selection_errors.extend(
        str(error).strip()
        for error in source_coverage_selection.get("source_coverage_route_errors")
        or []
        if str(error).strip()
    )
    selection_errors.extend(
        [
            str(source_coverage_selection.get("source_coverage_mode_error") or "").strip()
        ]
    )
    selection_errors.extend(
        str(error).strip()
        for error in source_coverage_selection.get(
            "semantic_model_scope_target_route_errors"
        )
        or []
        if str(error).strip()
    )
    selection_errors.extend(
        str(error).strip()
        for error in source_coverage_selection.get(
            "semantic_model_target_route_errors"
        )
        or []
        if str(error).strip()
    )
    if not args.no_lean:
        selection_errors.extend(elaborated_review_signature_errors)
    source_contract_association_errors = sorted(
        set(
            source_contract_association_errors
            + source_claim_atom_association_errors
            + explicit_direct_route_association_errors
            + statement_source_component_association_errors
            + assumption_source_review_association_errors
            + conditional_probability_composition_errors
            + equality_defined_partition_errors
            + strategic_observation_totality_errors
            + conditioning_information_errors
            + source_model_derivation_errors
            + recursive_field_source_association_errors
            + executable_terminal_receipt_errors
            + theorem_facing_contract_coverage_errors
            + [error for error in selection_errors if error]
        )
    )
    source_contract_association_counts = {
        **source_contract_association_counts,
        **source_claim_atom_association_counts,
        **explicit_direct_route_association_counts,
        **statement_source_component_association_counts,
        **assumption_source_review_association_counts,
        **conditional_probability_composition_counts,
        **equality_defined_partition_counts,
        **strategic_observation_totality_counts,
        **conditioning_information_counts,
        **source_model_derivation_counts,
        **recursive_field_source_association_counts,
        **executable_terminal_receipt_counts,
        **theorem_facing_contract_coverage_counts,
    }
    direct_statement_ledger_rows = current_direct_statement_ledger_covered_rows(
        root, paper_dir
    )
    statement_ledger_covered_input_keys = statement_ledger_covered_boundary_input_keys(
        root,
        paper_dir,
        boundary_input_items,
        qualified_row_refs=qualified_row_refs,
        conclusion_dependency_items=conclusion_dependencies,
        direct_covered_rows=direct_statement_ledger_rows,
    )
    precloseout_projection_items: list[dict[str, Any]] = []
    with source_record_progress_phase("precloseout exact-contract projection"):
        precloseout_contract_covered_input_keys = (
            precloseout_contract_covered_boundary_input_keys(
                paper_dir,
                boundary_input_items,
                qualified_row_refs=qualified_row_refs,
                declarations=declarations,
                proposition_aliases=proposition_aliases,
                type_aliases=semantic_type_aliases,
                conclusion_dependency_items=conclusion_dependencies,
                semantic_model_items=semantic_model_items,
                statement_ledger_covered_input_keys=statement_ledger_covered_input_keys,
                projection_items=precloseout_projection_items,
            )
        )
    statement_ledger_covered_input_keys |= precloseout_contract_covered_input_keys
    precloseout_projection = {
        "schema": 1,
        "status": str(
            load_json_object(paper_dir / "status.json").get("status") or ""
        ).strip(),
        "paper_statement_map_sha256": paper_statement_map_sha256,
        "items": precloseout_projection_items,
        "covered_boundary_input_keys": sorted(
            precloseout_contract_covered_input_keys
        ),
        "covered_boundary_input_keys_sha256": stable_digest(
            sorted(precloseout_contract_covered_input_keys)
        ),
    }
    source_premise_record_roots = {
        record
        for records in row_records.values()
        for record in records
    } | source_mapped_record_roots(paper_dir, structures)
    source_premise_items: list[dict[str, Any]] = []
    source_premise_consistency_error = ""
    source_premise_scan_diagnostics: dict[str, Any] = {}
    with source_record_progress_phase("source-premise consistency scan"):
        source_premise_items, source_premise_consistency_error = (
            source_premise_consistency_items(
                root,
                import_module,
                source_premise_record_roots,
                diagnostics_out=source_premise_scan_diagnostics,
            )
        )
    source_record_progress(
        "source-premise consistency reuse "
        f"({structural_scan_progress_summary(source_premise_scan_diagnostics)})"
    )
    semantic_context_digest = (
        stable_digest(semantic_context_items) if semantic_context_items else ""
    )
    formalization_scope = formalization_scope_context(paper_dir)
    source_map_semantic_index = source_record_source_map_semantic_index(
        semantic_model_statement_map
    )
    attach_transparent_subtype_domain_context_receipts(
        conclusion_dependencies,
        source_map_semantic_index=source_map_semantic_index,
    )
    # The full theorem-facing ledger remains mandatory inspection surface. An
    # exact source-contract semantic review compares its whole declaration,
    # including expanded binders and terminal result, so it may discharge its
    # own generated transport components. Everything else still needs an
    # independent sidecar disposition. This avoids both a name-based shortcut
    # and redundant human reviews of the same source theorem.
    theorem_facing_required_input_keys = {
        str(item.get("source_judgment_key") or item.get("judgment_key") or "").strip()
        for item in [*theorem_facing_input_items, *type_certificate_result_items]
        if str(item.get("source_judgment_key") or item.get("judgment_key") or "").strip()
        not in theorem_facing_contract_covered_input_keys
    }
    item_digest_context = {
        # Item-level pins use this keyless source-semantic index rather than
        # the aggregate context/ledger digests.  The aggregate audit still
        # records both complete objects below.
        "source_map_semantic_index": source_map_semantic_index,
        "source_proof_fidelity": source_proof_fidelity,
        "formalization_scope_digest": (
            stable_digest(formalization_scope) if formalization_scope is not None else ""
        ),
        "row_qualified_names": qualified_row_refs,
        "elaborated_signature_sha256_by_qualified": (
            elaborated_signature_sha256_by_qualified
        ),
        "semantic_dependency_sha256_by_qualified": (
            semantic_dependency_sha256_by_qualified
        ),
    }
    attach_source_record_item_digests(conclusion_dependencies, **item_digest_context)
    attach_source_record_item_digests(boundary_input_items, **item_digest_context)
    reusable_specialized_input_keys = {
        str(item.get("judgment_key") or "").strip()
        for item in [*boundary_input_items, *conclusion_dependencies]
        if str(item.get("judgment_key") or "").strip()
        and source_record_item_reuse_eligible(
            item,
            expected_item_digest_schema=SOURCE_RECORD_ITEM_DIGEST_SCHEMA,
        )
    }
    attach_source_record_item_digests(
        theorem_facing_input_items,
        reusable_mirror_keys=reusable_specialized_input_keys,
        **item_digest_context,
    )
    attach_source_record_item_digests(semantic_row_items, **item_digest_context)
    attach_source_record_item_digests(field_items, **item_digest_context)
    attach_source_record_item_digests(semantic_model_items, **item_digest_context)
    attach_source_record_item_digests(
        type_certificate_result_items, **item_digest_context
    )
    attach_source_record_item_digests(source_premise_items, **item_digest_context)
    theorem_realization_components = theorem_realization_component_ledger(
        theorem_inputs=theorem_facing_input_items,
        recursive_fields=field_items,
        conclusion_dependencies=conclusion_dependencies,
        type_certificates=type_certificate_result_items,
        semantic_model_items=semantic_model_items,
    )
    audit_surface = {
        # Schema 1 requires occurrence-level component identities and
        # component-indexed source-claim contracts. Older v10 payloads remain
        # readable as historical evidence but cannot silently receive this
        # closeout credit.
        "theorem_realization_contract_schema": 1,
        # Bind the policy that determines which generated surfaces can reuse
        # source-record evidence. A sidecar cannot be made current by merely
        # relabelling an older prompt version.
        "source_record_policy_version": SOURCE_RECORD_PROMPT_VERSION,
        FORMALIZATION_COVERAGE_PROTOCOL_FIELD: (
            formalization_coverage_protocol_digest()
        ),
        "review_interface_source": interface_source_identity,
        # The source inventory is part of the audited interpretation, even if
        # a particular row's Lean source did not change.
        "paper_statement_map_sha256": paper_statement_map_sha256,
        "source_coverage_mode": source_coverage_selection.get(
            "source_coverage_mode"
        ),
        "source_coverage_selected_source_items": source_coverage_selection.get(
            "source_coverage_selected_source_items"
        ),
        # This is a generated, source-domain selector receipt.  It records
        # only the independently validated vocabulary-definition bindings
        # that may use the exact direct-route association lane; generic
        # byte-indexed presentations never enter by this field.
        "source_coverage_validated_vocabulary_binding_source_items": (
            source_coverage_selection.get(
                "source_coverage_validated_vocabulary_binding_source_items"
            )
        ),
        "source_coverage_validated_vocabulary_direct_route_source_items": (
            source_coverage_selection.get(
                "source_coverage_validated_vocabulary_direct_route_source_items"
            )
        ),
        "source_coverage_mode_error": source_coverage_selection.get(
            "source_coverage_mode_error"
        ),
        "source_coverage_route_errors": source_coverage_selection.get(
            "source_coverage_route_errors"
        ),
        # These supplemental rows receive semantic model review but no normal
        # named-source coverage credit.  Keep their distinct selection causes
        # visible so a status key or declaration spelling cannot masquerade as
        # a source-presentation route.
        "semantic_model_source_selected_rows": source_coverage_selection.get(
            "semantic_model_source_selected_rows"
        ),
        "semantic_model_configured_assumption_rows": source_coverage_selection.get(
            "semantic_model_configured_assumption_rows"
        ),
        "semantic_model_scope_target_declarations": source_coverage_selection.get(
            "semantic_model_scope_target_declarations"
        ),
        "semantic_model_scope_target_rows": source_coverage_selection.get(
            "semantic_model_scope_target_rows"
        ),
        "semantic_model_scope_target_route_errors": source_coverage_selection.get(
            "semantic_model_scope_target_route_errors"
        ),
        "semantic_model_explicit_source_target_declarations": (
            source_coverage_selection.get(
                "semantic_model_explicit_source_target_declarations"
            )
        ),
        "semantic_model_explicit_source_target_source_items": (
            source_coverage_selection.get(
                "semantic_model_explicit_source_target_source_items"
            )
        ),
        "semantic_model_explicit_source_target_rows": source_coverage_selection.get(
            "semantic_model_explicit_source_target_rows"
        ),
        "semantic_model_explicit_source_target_route_errors": (
            source_coverage_selection.get(
                "semantic_model_explicit_source_target_route_errors"
            )
        ),
        "semantic_model_explicit_source_target_generated_item_errors": (
            source_coverage_selection.get(
                "semantic_model_explicit_source_target_generated_item_errors"
            )
        ),
        "semantic_model_explicit_source_target_semantic_contract_companions": (
            source_coverage_selection.get(
                "semantic_model_explicit_source_target_semantic_contract_companions"
            )
        ),
        "semantic_model_target_route_errors": source_coverage_selection.get(
            "semantic_model_target_route_errors"
        ),
        "elaborated_review_signature_errors": elaborated_review_signature_errors,
        "elaborated_result_input_path_errors": sorted(
            set(result_input_path_errors)
        ),
        "conclusion_dependency_input_atom_errors": sorted(
            set(conclusion_dependency_input_atom_errors)
        ),
        "configured_review_rows": configured_review_rows,
        # Source-only context is digest-bound and judge-visible, but has no
        # judgment keys and cannot provide proof/coverage credit.
        "semantic_context_requirements": semantic_context_items,
        "semantic_context_requirements_sha256": semantic_context_digest,
        # Every direct-route boundary/conclusion item must be tied to the
        # generated semantic-contract graph by declaration content, never by a
        # row or binder name.  These errors are part of the digest surface so a
        # stale sidecar cannot hide an ambiguous or missing route.
        "source_contract_association_schema": 2,
        "source_contract_association_errors": source_contract_association_errors,
        "source_contract_association_error_count": len(
            source_contract_association_errors
        ),
        "source_contract_association_counts": source_contract_association_counts,
        "theorem_facing_input_contract_coverage": theorem_facing_input_contract_coverage,
        "theorem_facing_input_contract_coverage_schema": 1,
        "boundary_input_items": boundary_input_items,
        "theorem_facing_input_items": theorem_facing_input_items,
        "theorem_realization_component_items": theorem_realization_components,
        # Bind this optimization into the aggregate audit identity.  It is a
        # generated precloseout projection, never judge-supplied evidence.
        "statement_ledger_covered_boundary_input_keys": sorted(
            statement_ledger_covered_input_keys
        ),
        "precloseout_exact_contract_projection": precloseout_projection,
        "conclusion_dependency_items": conclusion_dependencies,
        "type_valued_certificate_result_items": type_certificate_result_items,
        "rows_with_record_premises": judge_items,
        "rows_with_semantic_inputs": semantic_row_items,
        "row_header_inputs": row_inputs,
        "row_visible_inputs": row_visible_inputs,
        "row_conclusion_inputs": row_conclusion_inputs,
        "row_positional_signature_routes": positional_signature_routes_by_row,
        "row_input_proposition_sort_errors": row_input_proposition_sort_errors,
        "recursive_field_selected_review_route_graph": recursive_field_route_graph,
        "recursive_field_selected_review_route_scope": (
            recursive_field_route_scope
        ),
        "recursive_field_items": field_items,
        "recursive_field_proposition_sort_errors": (
            recursive_field_proposition_sort_errors
        ),
        "constructor_field_slot_reconciliation_errors": (
            constructor_slot_reconciliation_errors
        ),
        "type_witness_payload_safety_errors": (
            elaborated_type_witness_payload_safety_errors
        ),
        "source_premise_consistency_items": source_premise_items,
        "source_premise_consistency_scanned_record_roots": sorted(
            source_premise_record_roots
        ),
        # A configured review root may use a PaperInterface helper or record
        # through a transitive proof/type path. Bind the full routing ledger so
        # an auxiliary-name edit cannot hide that dependency from the source
        # record's semantic closeout checks.
        "reachable_paper_interface_auxiliary_dependencies": (
            reachable_auxiliary_routing[
                "reachable_paper_interface_auxiliary_dependencies"
            ]
        ),
        "unresolved_reachable_paper_interface_auxiliaries": (
            reachable_auxiliary_routing[
                "unresolved_reachable_paper_interface_auxiliaries"
            ]
        ),
        "ambiguous_reachable_paper_interface_auxiliary_references": (
            reachable_auxiliary_routing[
                "ambiguous_reachable_paper_interface_auxiliary_references"
            ]
        ),
        "reachable_paper_interface_auxiliary_quarantine_configuration_errors": (
            reachable_auxiliary_routing[
                "reachable_paper_interface_auxiliary_quarantine_configuration_errors"
            ]
        ),
        "available_local_lean_declarations": sorted(
            {declaration.name for declaration in semantic_declarations}
        ),
        "constructor_result_type_check_error": constructor_result_type_check_error,
        "recursion_failures": [asdict(failure) for failure in recursion_failures],
    }
    audit_surface["source_premise_consistency_schema"] = 1
    if formalization_scope is not None:
        audit_surface["formalization_scope"] = formalization_scope
    if semantic_model_items or semantic_model_config_errors:
        audit_surface["semantic_model_items"] = semantic_model_items
        audit_surface["semantic_model_review_configuration_errors"] = (
            semantic_model_config_errors
        )
    if source_premise_consistency_error:
        audit_surface["source_premise_consistency_error"] = (
            source_premise_consistency_error
        )
    if source_proof_fidelity is not None:
        audit_surface["source_proof_fidelity"] = source_proof_fidelity
    if missing_configured_rows:
        audit_surface["missing_configured_review_rows"] = missing_configured_rows

    # This pre-payload semantic digest is retained only while assembling the
    # payload.  The authoritative aggregate identity is attached below after
    # the complete Lean-facing raw projection exists.  In particular, existing
    # judgment reuse must compare against that final identity, not this older
    # surface-only value.
    audit_digest = stable_digest(
        audit_surface, volatile_keys=AUDIT_SURFACE_DIGEST_VOLATILE_KEYS
    )
    current_judgments: dict[str, dict[str, Any]] = {}
    resolved_conclusion_dependencies: list[dict[str, Any]] = []
    unresolved_conclusion_dependencies: list[dict[str, Any]] = []

    payload: dict[str, Any] = {
        "paper": args.paper,
        "paper_dir": repository_relative_path(root, paper_dir),
        SOURCE_RECORD_LEAN_IMPORT_CLOSURE_FIELD: deepcopy(
            lean_import_closure.record
        ),
        "source_record_input_fingerprint": deepcopy(
            scan_start_input_fingerprint
        ),
        "import_module": import_module,
        "review_interface_source": interface_source_identity,
        "review_assumption_source": assumption_source_identity,
        "paper_statement_map_sha256": paper_statement_map_sha256,
        "source_coverage_mode": source_coverage_selection.get(
            "source_coverage_mode"
        ),
        "source_coverage_selected_source_items": source_coverage_selection.get(
            "source_coverage_selected_source_items"
        ),
        "source_coverage_validated_vocabulary_binding_source_items": (
            source_coverage_selection.get(
                "source_coverage_validated_vocabulary_binding_source_items"
            )
        ),
        "source_coverage_validated_vocabulary_direct_route_source_items": (
            source_coverage_selection.get(
                "source_coverage_validated_vocabulary_direct_route_source_items"
            )
        ),
        "source_coverage_mode_error": source_coverage_selection.get(
            "source_coverage_mode_error"
        ),
        "source_coverage_route_errors": source_coverage_selection.get(
            "source_coverage_route_errors"
        ),
        "source_coverage_unrouted_source_items": source_coverage_selection.get(
            "source_coverage_unrouted_source_items"
        ),
        "out_of_mode_review_surface_rows": source_coverage_selection.get(
            "out_of_mode_review_surface_rows"
        ),
        "semantic_model_source_selected_rows": source_coverage_selection.get(
            "semantic_model_source_selected_rows"
        ),
        "semantic_model_configured_assumption_rows": source_coverage_selection.get(
            "semantic_model_configured_assumption_rows"
        ),
        "semantic_model_scope_target_declarations": source_coverage_selection.get(
            "semantic_model_scope_target_declarations"
        ),
        "semantic_model_scope_target_rows": source_coverage_selection.get(
            "semantic_model_scope_target_rows"
        ),
        "semantic_model_scope_target_route_errors": source_coverage_selection.get(
            "semantic_model_scope_target_route_errors"
        ),
        "semantic_model_explicit_source_target_declarations": (
            source_coverage_selection.get(
                "semantic_model_explicit_source_target_declarations"
            )
        ),
        "semantic_model_explicit_source_target_source_items": (
            source_coverage_selection.get(
                "semantic_model_explicit_source_target_source_items"
            )
        ),
        "semantic_model_explicit_source_target_rows": source_coverage_selection.get(
            "semantic_model_explicit_source_target_rows"
        ),
        "semantic_model_explicit_source_target_route_errors": (
            source_coverage_selection.get(
                "semantic_model_explicit_source_target_route_errors"
            )
        ),
        "semantic_model_explicit_source_target_generated_item_errors": (
            source_coverage_selection.get(
                "semantic_model_explicit_source_target_generated_item_errors"
            )
        ),
        "semantic_model_explicit_source_target_semantic_contract_companions": (
            source_coverage_selection.get(
                "semantic_model_explicit_source_target_semantic_contract_companions"
            )
        ),
        "semantic_model_target_route_errors": source_coverage_selection.get(
            "semantic_model_target_route_errors"
        ),
        "configured_review_rows": configured_review_rows,
        "prompt_version": SOURCE_RECORD_PROMPT_VERSION,
        # Keep the policy visible independently of the digest surface so a
        # reviewer can identify the semantic contract without recomputing it.
        "source_record_policy_version": SOURCE_RECORD_PROMPT_VERSION,
        FORMALIZATION_COVERAGE_PROTOCOL_FIELD: (
            formalization_coverage_protocol_digest()
        ),
        "theorem_realization_contract_schema": 1,
        "source_record_audit_sha256": audit_digest,
        "source_record_judgment_file": "audit/source_record_match_llm.json",
        "current_source_record_judgment_count": len(current_judgments),
        "resolved_structure_aliases": structure_aliases,
        "semantic_context_requirement_count": len(semantic_context_items),
        "semantic_context_requirements": semantic_context_items,
        "semantic_context_requirements_sha256": semantic_context_digest,
        "elaborated_review_signature_errors": elaborated_review_signature_errors,
        "elaborated_result_input_path_errors": sorted(
            set(result_input_path_errors)
        ),
        "conclusion_dependency_input_atom_errors": sorted(
            set(conclusion_dependency_input_atom_errors)
        ),
        "source_contract_association_schema": 2,
        "source_contract_association_errors": source_contract_association_errors,
        "source_contract_association_error_count": len(
            source_contract_association_errors
        ),
        "source_contract_association_counts": source_contract_association_counts,
        "expected_input_judgment_keys": sorted(
            {
                *{str(item["judgment_key"]) for item in boundary_input_items},
                *theorem_facing_required_input_keys,
            }
        ),
        "statement_ledger_covered_boundary_input_keys": sorted(
            statement_ledger_covered_input_keys
        ),
        "precloseout_contract_covered_boundary_input_keys": sorted(
            precloseout_contract_covered_input_keys
        ),
        "precloseout_exact_contract_projection": precloseout_projection,
        "expected_field_judgment_keys": sorted(
            {str(item["judgment_key"]) for item in field_items}
        ),
        "expected_semantic_model_judgment_keys": sorted(
            {str(item["judgment_key"]) for item in semantic_model_items}
        ),
        "conclusion_dependency_count": len(conclusion_dependencies),
        "conclusion_dependency_items": conclusion_dependencies,
        "type_valued_certificate_result_count": len(type_certificate_result_items),
        "type_valued_certificate_result_items": type_certificate_result_items,
        "resolved_conclusion_dependency_count": len(resolved_conclusion_dependencies),
        "resolved_conclusion_dependency_items": resolved_conclusion_dependencies,
        "unresolved_conclusion_dependency_count": len(unresolved_conclusion_dependencies),
        "unresolved_conclusion_dependency_items": unresolved_conclusion_dependencies,
        "review_row_count": len(row_names),
        "configured_review_rows_count": len(configured_review_rows),
        "configured_review_row_count": len(configured_rows),
        "missing_configured_review_rows": missing_configured_rows,
        "quarantined_auxiliary_review_rows": sorted(quarantined_auxiliary_qualified_names),
        "unconfigured_review_surface_rows": unconfigured_rows,
        "unconfigured_paper_interface_rows": unconfigured_rows,
        "unconfigured_assumption_support_rows": (
            unconfigured_assumption_support_rows
        ),
        "reachable_paper_interface_auxiliary_dependencies": (
            reachable_auxiliary_routing[
                "reachable_paper_interface_auxiliary_dependencies"
            ]
        ),
        "unresolved_reachable_paper_interface_auxiliaries": (
            reachable_auxiliary_routing[
                "unresolved_reachable_paper_interface_auxiliaries"
            ]
        ),
        "ambiguous_reachable_paper_interface_auxiliary_references": (
            reachable_auxiliary_routing[
                "ambiguous_reachable_paper_interface_auxiliary_references"
            ]
        ),
        "reachable_paper_interface_auxiliary_quarantine_configuration_errors": (
            reachable_auxiliary_routing[
                "reachable_paper_interface_auxiliary_quarantine_configuration_errors"
            ]
        ),
        "boundary_input_count": len(boundary_input_items),
        "boundary_input_items": boundary_input_items,
        "theorem_facing_input_count": len(theorem_facing_input_items),
        "theorem_facing_input_items": theorem_facing_input_items,
        "theorem_realization_component_count": len(theorem_realization_components),
        "theorem_realization_component_items": theorem_realization_components,
        "rows_with_record_premises": judge_items,
        "rows_with_semantic_inputs": semantic_row_items,
        "row_header_inputs": row_inputs,
        "row_visible_inputs": row_visible_inputs,
        "row_conclusion_inputs": row_conclusion_inputs,
        "row_positional_signature_routes": positional_signature_routes_by_row,
        "row_input_proposition_sort_errors": row_input_proposition_sort_errors,
        "recursive_field_selected_review_route_graph": recursive_field_route_graph,
        "recursive_field_selected_review_route_scope": (
            recursive_field_route_scope
        ),
        "recursive_field_count": len(field_items),
        "recursive_field_items": field_items,
        "recursive_field_proposition_sort_errors": (
            recursive_field_proposition_sort_errors
        ),
        "constructor_field_slot_reconciliation_errors": (
            constructor_slot_reconciliation_errors
        ),
        "type_witness_payload_safety_errors": (
            elaborated_type_witness_payload_safety_errors
        ),
        "semantic_model_item_count": len(semantic_model_items),
        "semantic_model_items": semantic_model_items,
        "source_premise_consistency_item_count": len(source_premise_items),
        "source_premise_consistency_items": source_premise_items,
        "source_premise_consistency_scanned_record_roots": sorted(
            source_premise_record_roots
        ),
        "source_premise_consistency_error": source_premise_consistency_error,
        "source_premise_consistency_schema": 1,
        "available_local_lean_declarations": sorted(
            {declaration.name for declaration in semantic_declarations}
        ),
        "constructor_result_type_check_error": constructor_result_type_check_error,
        "semantic_model_review_configuration_errors": semantic_model_config_errors,
        "recursion_failure_count": len(recursion_failures),
        "recursion_failures": [asdict(failure) for failure in recursion_failures],
        "source_proof_fidelity": source_proof_fidelity,
        "formalization_scope": formalization_scope,
        "fresh_source_elaboration": {
            "mode": "not_run_without_lean",
            "source_file": interface_source_identity["path"],
            "source_sha256": interface_source_identity["sha256"],
        },
    }
    if not args.no_lean:
        # The configuration preflight already elaborated the exact current
        # review surface and resolved every configured declaration.  The final
        # source-selected review rows are a subset, so reuse that stronger
        # receipt instead of launching a second isolated Lean pass after the
        # expensive recursive analysis.
        payload["lean_check"] = lean_check_subset_from_configured_preflight(
            configured_review_preflight,
            row_names=row_names,
            row_namespace=row_namespace,
            qualified_row_refs=qualified_row_refs,
        )
        fresh_elaboration = payload["lean_check"].get("fresh_source_elaboration")
        if isinstance(fresh_elaboration, dict):
            payload["fresh_source_elaboration"] = fresh_elaboration

    # SOURCE_RECORD_RAW_PRODUCER_END
    # The post-scan input check is a transport-integrity guard: it rejects a
    # mixed snapshot but does not choose or construct a raw obligation.  Keep
    # it outside the producer identity slice so improving that guard cannot
    # force every otherwise unchanged paper through a new Lean/source scan.
    scan_input_change_error = source_record_inputs_changed_during_scan_error(
        args,
        root,
        paper_dir,
        scan_start_map_sha256=paper_statement_map_sha256,
        scan_start_semantic_map_sha256=paper_statement_map_semantic_sha256,
        scan_start_input_fingerprint=scan_start_input_fingerprint,
        lean_import_closure=lean_import_closure,
    )
    if scan_input_change_error:
        payload["source_record_input_change_during_scan_error"] = (
            scan_input_change_error
        )
        encoded = json.dumps(payload, indent=2, sort_keys=True)
        lean_returncode = payload.get("lean_check", {}).get("returncode", 0)
        return finalize_source_record_audit_output(
            args,
            root,
            paper_dir,
            encoded,
            lean_returncode=lean_returncode,
            has_recursion_failures=bool(recursion_failures),
            input_change_during_scan_error=scan_input_change_error,
        )

    # Bind the exact serialized evidence projection into the same aggregate
    # semantic surface that owns ``source_record_audit_sha256``. This happens
    # after Lean output is present and before judgment reuse, so sidecar
    # judgments always name the final independently recomputable identity.
    attach_source_record_audit_surface(payload, audit_surface)
    # The exact manual-review queue renders its prompt from this immutable raw
    # surface. Do not duplicate that derived view inside the receipt.
    payload.pop("llm_judge_prompt", None)
    if not args.ignore_current_judgments:
        current_judgments = current_source_record_judgments(
            paper_dir, args.paper, payload
        )
    (
        approved_source_convention_input_keys,
        approved_source_convention_field_keys,
    ) = current_approved_source_convention_antecedent_keys(
        paper_dir,
        payload,
        current_judgments,
    )
    approved_corrected_model_dependency_keys = (
        current_approved_corrected_model_dependency_keys(
            paper_dir, args.paper, payload
        )
    )
    resolved_conclusion_dependencies, unresolved_conclusion_dependencies = (
        partition_conclusion_dependencies(
            conclusion_dependencies,
            current_judgments,
            approved_source_convention_input_keys=(
                approved_source_convention_input_keys
            ),
            approved_source_convention_field_keys=(
                approved_source_convention_field_keys
            ),
            raw_audit=payload,
            approved_corrected_model_dependency_keys=(
                approved_corrected_model_dependency_keys
            ),
        )
    )
    # These judge-sidecar summaries are intentionally outside the aggregate
    # projection, so a cheap refresh can update them without invalidating the
    # expensive Lean/source surface.
    payload.update(
        {
            "current_source_record_judgment_count": len(current_judgments),
            "resolved_conclusion_dependency_count": len(
                resolved_conclusion_dependencies
            ),
            "resolved_conclusion_dependency_items": resolved_conclusion_dependencies,
            "unresolved_conclusion_dependency_count": len(
                unresolved_conclusion_dependencies
            ),
            "unresolved_conclusion_dependency_items": unresolved_conclusion_dependencies,
        }
    )
    # A second receipt binds transport/Lean freshness fields around the final
    # semantic surface. Corrected-model contracts pin this receipt too.
    stamp_source_record_audit_integrity(payload)

    encoded = json.dumps(payload, indent=2, sort_keys=True)
    lean_returncode = payload.get("lean_check", {}).get("returncode", 0)
    closure_finalization_error = (
        source_record_lean_import_closure_finalization_error(closure_provider)
    )
    exit_code = finalize_source_record_audit_output(
        args,
        root,
        paper_dir,
        encoded,
        lean_returncode=lean_returncode,
        has_recursion_failures=bool(recursion_failures),
        input_change_during_scan_error=(
            "Lean import-closure inputs changed during scan: "
            + closure_finalization_error
            if closure_finalization_error
            else ""
        ),
    )
    # The canonical raw receipt is now complete.  Recheck the frozen scan
    # inputs before publishing its manifests as cache authority: a concurrent
    # edit leaves the valid receipt in place as stale evidence, but must never
    # bind old manifests to a newly compiled context.
    if exit_code == 0 and not args.no_lean and not getattr(args, "stdout", False):
        publication_input_change_error = source_record_inputs_changed_during_scan_error(
            args,
            root,
            paper_dir,
            scan_start_map_sha256=paper_statement_map_sha256,
            scan_start_semantic_map_sha256=paper_statement_map_semantic_sha256,
            scan_start_input_fingerprint=scan_start_input_fingerprint,
            lean_import_closure=lean_import_closure,
        )
        if not publication_input_change_error:
            try:
                resume_bindings, resume_binding_duplicates = (
                    source_record_current_manifest_resume_bindings(
                        paper_dir=paper_dir,
                        qualified_row_refs=qualified_row_refs,
                        selected_row_source_paths=selected_row_source_paths,
                        source_text_by_path=authenticated_lean_source_text,
                    )
                )
                for duplicate in resume_binding_duplicates:
                    resume_bindings.pop(duplicate, None)
                local_resume_bindings, local_resume_duplicates = (
                    _local_declaration_manifest_bindings(
                        root=root,
                        paper_dir=paper_dir,
                        declarations=local_declarations,
                        requested_declarations=(
                            elaborated_signature_manifests_by_qualified.keys()
                        ),
                    )
                )
                for duplicate in local_resume_duplicates:
                    local_resume_bindings.pop(duplicate, None)
                local_resume_bindings.update(resume_bindings)
                resume_bindings = local_resume_bindings
            except Exception as exc:  # noqa: BLE001 - a journal miss is harmless.
                resume_bindings = {}
                source_record_progress(
                    "authenticated manifest-store resume binding reconstruction "
                    "unavailable: "
                    + type(exc).__name__
                )
            publish_current_source_record_manifest_store(
                args=args,
                root=root,
                paper_dir=paper_dir,
                import_module=import_module,
                semantic_dependency_modules=canonical_paper_lean_modules,
                configured_review_rows=configured_review_rows,
                manifests=elaborated_signature_manifests_by_qualified,
                resume_bindings=resume_bindings,
            )
        else:
            source_record_progress(
                "authenticated manifest-store publication skipped because "
                + publication_input_change_error
            )
    return exit_code


def emit_reusable_source_record_audit_without_lock(
    args: argparse.Namespace, root: Path
) -> int | None:
    """Emit an exact current raw receipt without contending for the Lean lock.

    The cache validation computes the full current semantic input fingerprint
    and validates the raw aggregate and transport receipts before returning a
    payload.  It performs no Lean work and does not mutate the canonical raw
    artifact, so it is safe to perform before acquiring the repository-wide
    lock reserved for stale-source regeneration.  This keeps independent
    paper closeouts from queueing behind an expensive scan when their evidence
    is already current.
    """

    paper_dir = root / "papers" / args.paper
    if configured_review_reference_static_error(root, paper_dir):
        return None
    (
        paper_statement_map_sha256,
        paper_statement_map_semantic_sha256,
    ) = paper_statement_map_cache_receipts(paper_dir)
    saved_payload = load_json_object(canonical_source_record_audit_path(paper_dir))
    try:
        provider = WorktreeImportClosureProvider(
            root,
            eager_source_snapshot=False,
            allow_dirty_worktree_sources=True,
        )
    except (OSError, RuntimeError):
        return None
    lean_import_closure, _closure_error = (
        source_record_lean_import_closure_for_paper(
            root,
            paper_dir,
            provider=provider,
            saved_payload=saved_payload,
            allow_live_lean_graph=False,
        )
    )
    if lean_import_closure is None:
        return None
    cached_payload = reusable_source_record_audit(
        args,
        root,
        paper_dir,
        paper_statement_map_sha256=paper_statement_map_sha256,
        paper_statement_map_semantic_sha256=paper_statement_map_semantic_sha256,
        lean_import_closure=lean_import_closure,
        saved_payload=saved_payload,
    )
    if cached_payload is None:
        return None
    if source_record_lean_import_closure_finalization_error(provider):
        return None
    emit_stdout = bool(getattr(args, "stdout", False))
    if args.out:
        output_path = source_record_audit_output_path(args, root, paper_dir)
        atomic_write_text_if_changed(
            output_path,
            json.dumps(cached_payload, indent=2, sort_keys=True) + "\n",
        )
    elif emit_stdout:
        print(json.dumps(cached_payload, indent=2, sort_keys=True))
    else:
        print(
            json.dumps(
                {
                    "paper": args.paper,
                    "cached": True,
                    "source_record_audit": str(
                        canonical_source_record_audit_path(paper_dir)
                    ),
                },
                sort_keys=True,
            )
        )
    return 0


def source_record_identity_only_payload(
    args: argparse.Namespace,
    root: Path,
    *,
    failure_reason: list[str] | None = None,
) -> dict[str, Any] | None:
    """Compute the cache/evidence input identity without invoking Lean.

    The fast evidence gate runs this mode in a subprocess instead of importing
    this helper (which would create an import cycle through the evidence gate).
    It deliberately reuses the exact cache fingerprint function, including its
    stored ``max_depth`` and ``no_lean`` options.
    """

    def fail(reason: str) -> None:
        if failure_reason is not None:
            failure_reason[:] = [reason]

    paper_dir = root / "papers" / args.paper
    configured_error = configured_review_reference_static_error(root, paper_dir)
    if configured_error:
        fail("configured review reference is invalid: " + configured_error)
        return None
    try:
        (
            paper_statement_map_sha256,
            paper_statement_map_semantic_sha256,
        ) = paper_statement_map_cache_receipts(paper_dir)
        saved_payload = load_json_object(
            canonical_source_record_audit_path(paper_dir)
        )
    except (OSError, ValueError, json.JSONDecodeError) as exc:
        fail("could not load current source-record inputs: " + str(exc))
        return None
    saved_closure_record = saved_source_record_lean_import_closure(saved_payload)
    saved_closure_is_structurally_current = True
    try:
        validated_lean_import_closure_payload(saved_closure_record)
    except ValueError:
        # Legacy or malformed receipts stay on the former replay path.  This
        # preserves its actionable diagnostics (and its testable provider
        # boundary) without making the ordinary, structurally valid stale-byte
        # case materialize the expensive historical closure validator.
        saved_closure_is_structurally_current = False
    try:
        status_path = paper_dir / "status.json"
        interface_path = review_source_path(root, paper_dir, status_path)
        closure_entry = source_record_lean_closure_entry_for_paper(root, paper_dir)
        lean_import_closure = (
            source_record_lean_import_closure_from_record(
                root,
                closure_entry,
                saved_closure_record,
            )
            if saved_closure_is_structurally_current
            else None
        )
        provider: WorktreeImportClosureProvider | None = None
        closure_error = ""
    except SourceRecordLeanImportClosureStaleError as exc:
        lean_import_closure = None
        provider = None
        closure_error = str(exc)
    except (OSError, RuntimeError, ValueError) as exc:
        fail("could not validate saved Lean import closure: " + str(exc))
        return None

    # Exact-byte reuse retains the strict external-artifact and mutation
    # validator.  A byte miss goes directly to the semantic fallback below.
    if lean_import_closure is not None or not saved_closure_is_structurally_current:
        try:
            provider = WorktreeImportClosureProvider(
                root,
                eager_source_snapshot=False,
                allow_dirty_worktree_sources=True,
            )
        except (OSError, RuntimeError) as exc:
            fail("could not initialize Lean import-closure provider: " + str(exc))
            return None
        lean_import_closure, closure_error = (
            source_record_lean_import_closure_for_paper(
                root,
                paper_dir,
                provider=provider,
                saved_payload=saved_payload,
                allow_live_lean_graph=False,
            )
        )
        if lean_import_closure is None and not saved_closure_is_structurally_current:
            fail("could not replay current Lean import closure: " + closure_error)
            return None
    semantic_reuse: dict[str, Any] | None = None
    if lean_import_closure is None:
        (
            lean_import_closure,
            semantic_reuse,
            semantic_reuse_error,
        ) = current_source_record_semantic_reuse_identity(
            root,
            paper_dir,
            saved_payload=saved_payload,
        )
        if lean_import_closure is None or semantic_reuse is None:
            fail(
                "could not validate current source-record semantics after Lean "
                "closure bytes changed: "
                + (semantic_reuse_error or closure_error)
            )
            return None
    fingerprint = source_record_input_fingerprint(
        args,
        root,
        paper_dir,
        paper_statement_map_sha256=paper_statement_map_sha256,
        paper_statement_map_semantic_sha256=paper_statement_map_semantic_sha256,
        lean_import_closure=lean_import_closure,
    )
    if fingerprint is None:
        fail("could not compute current source-record fingerprint")
        return None
    payload = {
        "schema": 1,
        "paper": args.paper,
        "paper_statement_map_sha256": paper_statement_map_sha256,
        "paper_statement_map_semantic_sha256": paper_statement_map_semantic_sha256,
        "source_record_input_fingerprint": fingerprint,
        SOURCE_RECORD_LEAN_IMPORT_CLOSURE_FIELD: deepcopy(
            lean_import_closure.record
        ),
    }
    if semantic_reuse is not None:
        payload["semantic_receipt_reuse"] = deepcopy(semantic_reuse)
    if getattr(args, "include_legacy_fingerprint", False):
        legacy_v9 = source_record_legacy_v9_protocol_fingerprint(
            fingerprint, paper_dir
        )
        if legacy_v9 is not None:
            payload["legacy_v9_source_record_input_fingerprint"] = legacy_v9
        # Compute the older expensive compatibility identity only when a
        # caller is actually validating a pre-schema-9 receipt. Current
        # receipts never need the duplicate closure/status/fidelity walk.
        payload["legacy_v7_source_record_input_fingerprint"] = (
            source_record_legacy_v7_input_fingerprint(
                args,
                root,
                paper_dir,
                paper_statement_map_sha256=paper_statement_map_sha256,
                paper_statement_map_semantic_sha256=(
                    paper_statement_map_semantic_sha256
                ),
                lean_import_closure=lean_import_closure,
            )
        )
    finalization_error = (
        source_record_lean_import_closure_finalization_error(provider)
        if provider is not None
        else ""
    )
    if finalization_error:
        fail(
            "Lean import-closure inputs changed during identity validation: "
            + finalization_error
        )
        return None
    return payload


def fast_saved_source_record_identity_payload(
    args: argparse.Namespace, root: Path
) -> dict[str, Any]:
    """Check saved raw evidence against current repository source inputs only.

    This is deliberately narrower than ``--identity-only``.  It validates the
    complete serialized raw receipt, the exact Lean-owned repository-source
    closure saved in that receipt, and every source/configuration input used
    to construct its current schema-10 fingerprint.  It does *not* reread the
    thousands of external ``.olean`` artifacts in a loaded Mathlib closure.

    The mode is for responsive dashboard prechecks.  It is not a replacement
    for the strict identity path used by closeout, which additionally checks
    current external artifacts and Lean's loaded-module environment.
    """

    observed_saved_receipt: dict[str, Any] = {}

    def dimension(state: str, reason: str = "") -> dict[str, str]:
        """Return one machine-readable, non-accepting validation dimension."""

        result = {"state": state}
        if reason:
            result["reason"] = reason
        return result

    def set_validation_dimensions(
        *,
        raw_integrity_error: str = "",
        semantic_surface_error: str = "",
        scan_completeness_error: str = "",
        reusable_item_metadata_error: str = "",
        raw_bytes_state: str = "unavailable",
        raw_bytes_reason: str = "",
        source_identity_state: str = "unavailable",
        source_identity_reason: str = "",
    ) -> None:
        """Expose independent preflight dimensions without granting reuse.

        The planner must distinguish a stale source/configuration identity from
        a current raw whose generated semantic surface needs a structural
        repair.  A single rendered diagnostic cannot safely encode that state
        machine, so preserve every validator outcome in a closed, structured
        projection.  This helper is outside fresh raw generation and does not
        alter the raw receipt schema or its producer identity.
        """

        observed_saved_receipt["validation_dimensions"] = {
            "raw_receipt_integrity": dimension(
                "invalid" if raw_integrity_error else "valid", raw_integrity_error
            ),
            "generated_semantic_surface": dimension(
                "invalid" if semantic_surface_error else "valid",
                semantic_surface_error,
            ),
            "raw_scan_completeness": dimension(
                "invalid" if scan_completeness_error else "valid",
                scan_completeness_error,
            ),
            "reusable_item_metadata": dimension(
                "invalid" if reusable_item_metadata_error else "valid",
                reusable_item_metadata_error,
            ),
            "raw_bytes": dimension(raw_bytes_state, raw_bytes_reason),
            "source_configuration_identity": dimension(
                source_identity_state, source_identity_reason
            ),
        }

    def failure(reason: str) -> dict[str, Any]:
        return {
            "schema": 1,
            "paper": args.paper,
            "identity_scope": "repository_sources_and_configuration_only",
            "external_artifacts_revalidated": False,
            "current": False,
            "reason": reason,
            **observed_saved_receipt,
        }

    paper_dir = root / "papers" / args.paper
    raw_path = canonical_source_record_audit_path(paper_dir)
    try:
        raw_bytes = raw_path.read_bytes()
        payload = json.loads(raw_bytes)
    except (OSError, UnicodeDecodeError, json.JSONDecodeError):
        payload = None
    if not isinstance(payload, dict):
        return failure("saved source-record audit is missing or unreadable")
    if payload.get("paper") != args.paper:
        return failure("saved source-record audit belongs to a different paper")
    if payload.get("prompt_version") != SOURCE_RECORD_PROMPT_VERSION:
        return failure("saved source-record audit uses an unsupported prompt version")

    # Preserve the authenticated receipt coordinates before semantic validation.
    # A failed validator still means the raw is unusable, but callers need its
    # schema and digest to distinguish a stale, reissuable raw from an
    # unreadable or pre-schema receipt without reopening the large JSON file.
    stored_fingerprint = payload.get("source_record_input_fingerprint")
    observed_raw_digest = str(payload.get("source_record_audit_sha256") or "").strip()
    if SHA256_RE.fullmatch(observed_raw_digest):
        observed_saved_receipt["observed_source_record_audit_sha256"] = (
            observed_raw_digest
        )
    if isinstance(stored_fingerprint, Mapping) and isinstance(
        stored_fingerprint.get("schema"), int
    ):
        observed_saved_receipt["observed_source_record_fingerprint_schema"] = (
            stored_fingerprint["schema"]
        )

    raw_integrity_error = str(source_record_audit_receipt_error(payload) or "")
    semantic_surface_error = str(
        source_record_raw_semantic_surface_error(payload) or ""
    )
    if semantic_surface_error:
        (
            semantic_contract_revalidation,
            semantic_contract_revalidation_error,
        ) = source_record_semantic_contract_revalidation_context(
            paper_dir, payload
        )
        if semantic_contract_revalidation_error:
            semantic_surface_error = (
                "semantic-contract revalidation is invalid: "
                + semantic_contract_revalidation_error
            )
        else:
            semantic_surface_error = str(
                source_record_effective_semantic_surface_error(
                    payload,
                    semantic_contract_revalidation=(
                        semantic_contract_revalidation
                    ),
                )
                or ""
            )
    scan_completeness_error = str(
        source_record_raw_scan_completeness_error(payload) or ""
    )
    reusable_item_metadata_error = str(
        source_record_raw_reusable_item_metadata_error(
            payload,
            expected_item_digest_schema=SOURCE_RECORD_ITEM_DIGEST_SCHEMA,
        )
        or ""
    )
    raw_validation_error = next(
        (
            error
            for error in (
                raw_integrity_error,
                semantic_surface_error,
                scan_completeness_error,
                reusable_item_metadata_error,
            )
            if error
        ),
        "",
    )
    set_validation_dimensions(
        raw_integrity_error=raw_integrity_error,
        semantic_surface_error=semantic_surface_error,
        scan_completeness_error=scan_completeness_error,
        reusable_item_metadata_error=reusable_item_metadata_error,
    )

    if not isinstance(stored_fingerprint, dict):
        return failure("saved source-record input fingerprint is missing or malformed")
    if stored_fingerprint.get("schema") != 10:
        return failure("fast source-record reuse requires a schema-10 fingerprint")
    max_depth = stored_fingerprint.get("max_depth")
    if not isinstance(max_depth, int) or max_depth < 0:
        return failure("saved source-record fingerprint has malformed max_depth")
    if stored_fingerprint.get("no_lean") is not False:
        return failure("saved source-record fingerprint was not produced by a Lean scan")

    status_path = paper_dir / "status.json"
    try:
        interface_path = review_source_path(root, paper_dir, status_path)
    except (OSError, ValueError) as exc:
        return failure("review interface is unavailable: " + str(exc))

    # Replay the same Lean-owned root used by fresh raw generation.  A separate
    # proof module imports the canonical semantic interface, so that proof
    # module is the smallest root whose closure contains both sides of every
    # configured Spec/proof pair.
    try:
        closure_entry = source_record_lean_closure_entry_for_paper(root, paper_dir)
    except (OSError, ValueError) as exc:
        return failure("review closure entry is unavailable: " + str(exc))

    semantic_reuse: dict[str, Any] | None = None
    try:
        closure = source_record_lean_import_closure_from_record(
            root,
            closure_entry,
            payload.get(SOURCE_RECORD_LEAN_IMPORT_CLOSURE_FIELD),
        )
    except SourceRecordLeanImportClosureStaleError as exc:
        byte_fast_path_error = str(exc)
        cached_result = (
            load_semantic_reuse_cache(
                root=root,
                paper_dir=paper_dir,
                raw_audit_file_sha256=hashlib.sha256(raw_bytes).hexdigest(),
            )
            if not raw_validation_error
            else None
        )
        if cached_result is not None:
            cached_result["semantic_reuse_cache"] = {
                "state": "current_exact_repository_material",
                "acceptance_credential": False,
            }
            return cached_result
        closure, semantic_reuse, semantic_error = (
            current_source_record_semantic_reuse_identity(
                root,
                paper_dir,
                saved_payload=payload,
            )
        )
        if closure is None or semantic_reuse is None:
            closure_error = byte_fast_path_error
            if semantic_error:
                closure_error += "; semantic reuse validation unavailable: " + semantic_error
            set_validation_dimensions(
                raw_integrity_error=raw_integrity_error,
                semantic_surface_error=semantic_surface_error,
                scan_completeness_error=scan_completeness_error,
                reusable_item_metadata_error=reusable_item_metadata_error,
                source_identity_state="stale",
                source_identity_reason=closure_error,
            )
            return failure(
                "saved Lean semantic receipt is not current: " + closure_error
            )
    except ValueError as exc:
        closure_error = str(exc)
        # A structurally valid saved closure may name a former review
        # entrypoint after a paper moves its paired proof endpoints into a
        # dedicated ProofInterface.  That is a material source/interface
        # identity change and requires a fresh raw receipt, not an ambiguous
        # manual-inspection state.
        set_validation_dimensions(
            raw_integrity_error=raw_integrity_error,
            semantic_surface_error=semantic_surface_error,
            scan_completeness_error=scan_completeness_error,
            reusable_item_metadata_error=reusable_item_metadata_error,
            source_identity_state="stale",
            source_identity_reason=closure_error,
        )
        return failure("saved Lean import closure is not current: " + closure_error)
    if semantic_reuse is None and (
        stored_fingerprint.get(SOURCE_RECORD_LEAN_IMPORT_CLOSURE_SHA256_FIELD)
        != closure.sha256
    ):
        return failure("saved Lean import-closure digest does not match its closure receipt")

    map_sha256, semantic_map_sha256 = paper_statement_map_cache_receipts(paper_dir)
    if not (
        SHA256_RE.fullmatch(map_sha256)
        and SHA256_RE.fullmatch(semantic_map_sha256)
    ):
        return failure("current paper statement-map receipts are unavailable")
    fingerprint_args = argparse.Namespace(
        paper=args.paper,
        max_depth=max_depth,
        no_lean=False,
    )
    current_fingerprint = source_record_input_fingerprint(
        fingerprint_args,
        root,
        paper_dir,
        paper_statement_map_sha256=map_sha256,
        paper_statement_map_semantic_sha256=semantic_map_sha256,
        lean_import_closure=closure,
        raw_audit_payload=payload,
    )
    if current_fingerprint is None:
        return failure("could not reconstruct current source-record source identity")
    producer_identity_matches = source_record_raw_producer_code_identity_matches(
        stored_fingerprint,
        current_fingerprint,
        repository_root=REPOSITORY_ROOT,
        semantic_reuse=semantic_reuse,
    )
    if not producer_identity_matches and semantic_reuse is None:
        # A current imported-byte closure does not imply that every other raw
        # fingerprint coordinate is a mathematical change.  In particular, a
        # registered audit-engine edit or a strictly revalidated source-to-Spec
        # carrier refresh can miss the byte fast path while all configured Lean
        # roots retain the same signature, proposition graph, and transitive
        # semantic dependencies.  Run the general current-verifier fallback
        # once before declaring the raw stale.  Its projection still retains
        # exact source artifacts, status obligations, fidelity ledgers,
        # toolchain controls, and every non-Lean semantic input, so a material
        # paper/source change continues to fail below.
        semantic_closure, semantic_candidate, _semantic_error = (
            current_source_record_semantic_reuse_identity(
                root,
                paper_dir,
                saved_payload=payload,
            )
        )
        if semantic_closure is not None and semantic_candidate is not None:
            closure = semantic_closure
            semantic_reuse = semantic_candidate
            current_fingerprint = source_record_input_fingerprint(
                fingerprint_args,
                root,
                paper_dir,
                paper_statement_map_sha256=map_sha256,
                paper_statement_map_semantic_sha256=semantic_map_sha256,
                lean_import_closure=closure,
                raw_audit_payload=payload,
            )
            producer_identity_matches = bool(
                current_fingerprint is not None
                and source_record_raw_producer_code_identity_matches(
                    stored_fingerprint,
                    current_fingerprint,
                    repository_root=REPOSITORY_ROOT,
                    semantic_reuse=semantic_reuse,
                )
            )
    if not producer_identity_matches:
        set_validation_dimensions(
            raw_integrity_error=raw_integrity_error,
            semantic_surface_error=semantic_surface_error,
            scan_completeness_error=scan_completeness_error,
            reusable_item_metadata_error=reusable_item_metadata_error,
            source_identity_state="stale",
            source_identity_reason=(
                "saved source-record source/configuration identity differs from "
                "the current repository"
            ),
        )
        return failure(
            "saved source-record source/configuration identity differs from the current repository"
        )
    set_validation_dimensions(
        raw_integrity_error=raw_integrity_error,
        semantic_surface_error=semantic_surface_error,
        scan_completeness_error=scan_completeness_error,
        reusable_item_metadata_error=reusable_item_metadata_error,
        source_identity_state="current",
    )

    recorded_map_sha256 = str(payload.get("paper_statement_map_sha256") or "").strip()
    if not SHA256_RE.fullmatch(recorded_map_sha256):
        set_validation_dimensions(
            raw_integrity_error=raw_integrity_error,
            semantic_surface_error=semantic_surface_error,
            scan_completeness_error=scan_completeness_error,
            reusable_item_metadata_error=reusable_item_metadata_error,
            source_identity_state="stale",
            source_identity_reason=(
                "saved source-record audit lacks a valid statement-map byte receipt"
            ),
        )
        return failure("saved source-record audit lacks a valid statement-map byte receipt")
    # The aggregate cache explicitly permits source-map administrative edits
    # when their semantic receipt is unchanged.  Keep this narrow exception
    # identical to the normal source-record reuse contract.
    # A successful current-semantic reuse check already compared the exact
    # configured roots and their Lean identities, and separately validated the
    # current map-owned dimensions/defect routes.  Do not let this older
    # aggregate map hash veto that stronger current result.  The byte-only fast
    # path retains the historical exact-or-semantic-map receipt rule.
    if semantic_reuse is None and recorded_map_sha256 != map_sha256 and (
        stored_fingerprint.get("paper_statement_map_semantic_sha256")
        != semantic_map_sha256
    ):
        set_validation_dimensions(
            raw_integrity_error=raw_integrity_error,
            semantic_surface_error=semantic_surface_error,
            scan_completeness_error=scan_completeness_error,
            reusable_item_metadata_error=reusable_item_metadata_error,
            source_identity_state="stale",
            source_identity_reason="saved statement-map receipt is stale for current source semantics",
        )
        return failure("saved statement-map receipt is stale for current source semantics")

    try:
        final_raw_bytes = raw_path.read_bytes()
    except OSError:
        set_validation_dimensions(
            raw_integrity_error=raw_integrity_error,
            semantic_surface_error=semantic_surface_error,
            scan_completeness_error=scan_completeness_error,
            reusable_item_metadata_error=reusable_item_metadata_error,
            raw_bytes_state="unavailable",
            raw_bytes_reason="saved source-record audit disappeared during fast validation",
            source_identity_state="current",
        )
        return failure("saved source-record audit disappeared during fast validation")
    if final_raw_bytes != raw_bytes:
        set_validation_dimensions(
            raw_integrity_error=raw_integrity_error,
            semantic_surface_error=semantic_surface_error,
            scan_completeness_error=scan_completeness_error,
            reusable_item_metadata_error=reusable_item_metadata_error,
            raw_bytes_state="changed",
            raw_bytes_reason="saved source-record audit changed during fast validation",
            source_identity_state="current",
        )
        return failure("saved source-record audit changed during fast validation")

    set_validation_dimensions(
        raw_integrity_error=raw_integrity_error,
        semantic_surface_error=semantic_surface_error,
        scan_completeness_error=scan_completeness_error,
        reusable_item_metadata_error=reusable_item_metadata_error,
        raw_bytes_state="stable",
        source_identity_state="current",
    )
    result = {
        "schema": 1,
        "paper": args.paper,
        "identity_scope": "repository_sources_and_configuration_only",
        "external_artifacts_revalidated": False,
        "current": True,
        "source_record_audit_file_sha256": hashlib.sha256(raw_bytes).hexdigest(),
        "source_record_audit_sha256": str(
            payload.get("source_record_audit_sha256") or ""
        ).strip(),
        "source_record_input_fingerprint_sha256": stable_digest(current_fingerprint),
    }
    hard_raw_validation_error = next(
        (
            error
            for error in (
                raw_integrity_error,
                scan_completeness_error,
                reusable_item_metadata_error,
            )
            if error
        ),
        "",
    )
    if semantic_reuse is not None and not hard_raw_validation_error:
        result["semantic_receipt_reuse"] = deepcopy(semantic_reuse)
    result.update(observed_saved_receipt)
    if semantic_reuse is not None:
        watched_paths = {
            raw_path,
            status_path,
            paper_dir / "audit" / "paper_statement_map.json",
            root / "config" / "formalization_audit_protocol.json",
            closure_entry,
            *closure.repository_sources,
        }
        try:
            watched_paths.update(
                diagnostic_imported_paper_lean_files(root, [closure_entry])
            )
        except (OSError, RuntimeError, ValueError):
            # Cache persistence is only an optimization.  The current result
            # remains valid; a later planner will simply rerun this verifier.
            watched_paths = set()
        if watched_paths:
            # Resolve repository-relative and paper-relative ledger routes
            # through the same guarded helper used by raw generation.  Joining
            # an already ``papers/...`` route to ``paper_dir`` recorded a
            # nonexistent doubled path and failed to watch the real ledger.
            fidelity_path = source_proof_fidelity_path(paper_dir)
            if fidelity_path is not None:
                watched_paths.add(fidelity_path)
        if watched_paths:
            for identity_field in (
                "source_artifact_identities",
                "toolchain_identities",
            ):
                for identity in current_fingerprint.get(identity_field, []):
                    if not isinstance(identity, Mapping):
                        continue
                    relative = str(identity.get("path") or "").strip()
                    if not relative or Path(relative).is_absolute():
                        continue
                    candidate = (root / relative).resolve()
                    try:
                        candidate.relative_to(root.resolve())
                    except ValueError:
                        watched_paths = set()
                        break
                    watched_paths.add(candidate)
                if not watched_paths:
                    break
        if watched_paths:
            write_semantic_reuse_cache(
                root=root,
                paper_dir=paper_dir,
                raw_audit_file_sha256=result["source_record_audit_file_sha256"],
                watched_paths=watched_paths,
                result=result,
            )
    if raw_validation_error:
        # A declaration-semantic authority may still have been published
        # above.  It never repairs this error by itself: the accepting evidence
        # context must independently validate the exact raw receipt and any
        # narrow structural revalidation artifact before using that authority.
        return failure(raw_validation_error)
    return result


def parse_args() -> argparse.Namespace:
    """Parse CLI arguments without starting the serialized Lean work."""

    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--paper",
        help="paper folder id (required unless --lock-status is used)",
    )
    parser.add_argument("--root", default=".", help="repository root containing papers/")
    parser.add_argument(
        "--out",
        help=(
            "optional JSON output path; a successful full scan also refreshes "
            "the canonical paper-local evidence"
        ),
    )
    parser.add_argument(
        "--stdout",
        action="store_true",
        help=(
            "print the full raw JSON payload for diagnostics; this does not "
            "replace canonical evidence unless --out names it"
        ),
    )
    parser.add_argument(
        "--no-lean",
        action="store_true",
        help=(
            "skip the broad Lean #check subprocess; the narrow elaborated "
            "source-premise consistency scan still runs when reviewed records exist"
        ),
    )
    parser.add_argument(
        "--refresh-judgment-summary",
        action="store_true",
        help=(
            "update judgment counts and conclusion-dependency resolutions in an "
            "existing audit without rebuilding its Lean-checked surface"
        ),
    )
    parser.add_argument(
        "--ignore-current-judgments",
        action="store_true",
        help=(
            "build a fresh machine source-record surface without reading the existing "
            "source_record_match_llm.json sidecar"
        ),
    )
    parser.add_argument(
        "--force",
        action="store_true",
        help=(
            "regenerate the aggregate source-record surface even when its effective "
            "source, interface, and audit configuration fingerprint is current"
        ),
    )
    parser.add_argument(
        "--identity-only",
        action="store_true",
        help=(
            "print the current source-record cache/evidence input identity "
            "without scanning Lean or reading/writing the aggregate audit"
        ),
    )
    parser.add_argument(
        "--fast-saved-identity",
        action="store_true",
        help=(
            "validate the saved source-record receipt against current repository "
            "sources and configuration without rereading external .olean artifacts; "
            "for dashboard prechecks only, not strict closeout"
        ),
    )
    parser.add_argument(
        "--rebind-semantic-authority-controls",
        action="store_true",
        help=(
            "rebind a current declaration-semantic authority after proving that "
            "the effective status controls and source-proof-fidelity semantics "
            "are unchanged; this performs no Lean work"
        ),
    )
    parser.add_argument(
        "--include-legacy-fingerprint",
        action="store_true",
        help=(
            "with --identity-only, also compute legacy v9 protocol-split and "
            "v7 compatibility identities; current schema-10 evidence should "
            "omit this extra work"
        ),
    )
    parser.add_argument("--max-depth", type=int, default=4, help="maximum recursive structure depth")
    parser.add_argument("--max-lean-output-chars", type=int, default=120000)
    parser.add_argument(
        "--lock-timeout-seconds",
        type=float,
        default=0.0,
        help=(
            "seconds to wait for another source-record audit of this repository; "
            "the default fails immediately rather than launching overlapping Lean scans"
        ),
    )
    parser.add_argument(
        "--lock-status",
        action="store_true",
        help=(
            "print read-only source-record scan-lock ownership and availability; "
            "this never starts, cancels, or recovers a scan"
        ),
    )
    return parser.parse_args()


def main() -> int:
    args = parse_args()
    if getattr(args, "lock_status", False):
        incompatible = (
            args.out,
            bool(getattr(args, "stdout", False)),
            args.no_lean,
            args.refresh_judgment_summary,
            args.ignore_current_judgments,
            args.force,
            args.identity_only,
            args.fast_saved_identity,
            args.rebind_semantic_authority_controls,
            args.include_legacy_fingerprint,
        )
        if any(incompatible):
            print(
                "error: --lock-status cannot be combined with audit-generation options",
                file=sys.stderr,
            )
            return 2
        print(json.dumps(source_record_audit_lock_status(Path(args.root)), sort_keys=True))
        return 0
    if not args.paper:
        print("error: --paper is required unless --lock-status is used", file=sys.stderr)
        return 2
    if bool(getattr(args, "stdout", False)) and args.out:
        print("error: --stdout cannot be combined with --out", file=sys.stderr)
        return 2
    if getattr(args, "include_legacy_fingerprint", False) and not args.identity_only:
        print(
            "error: --include-legacy-fingerprint requires --identity-only",
            file=sys.stderr,
        )
        return 2
    if getattr(args, "fast_saved_identity", False) and (
        args.identity_only
        or args.refresh_judgment_summary
        or args.ignore_current_judgments
        or args.force
        or args.no_lean
        or args.out
        or getattr(args, "stdout", False)
    ):
        print(
            "error: --fast-saved-identity cannot be combined with audit-generation options",
            file=sys.stderr,
        )
        return 2
    if getattr(args, "rebind_semantic_authority_controls", False) and (
        args.identity_only
        or args.fast_saved_identity
        or args.refresh_judgment_summary
        or args.ignore_current_judgments
        or args.force
        or args.no_lean
        or args.out
        or getattr(args, "stdout", False)
    ):
        print(
            "error: --rebind-semantic-authority-controls cannot be combined "
            "with audit-generation options",
            file=sys.stderr,
        )
        return 2
    root = Path(args.root).resolve()
    # Isolated audit passes spawn several Lean subprocesses.  Keep them within
    # the sandbox descriptor/process budget even when callers omit this env var.
    os.environ.setdefault("LEAN_NUM_THREADS", "1")
    if args.identity_only:
        failure_reason: list[str] = []
        payload = source_record_identity_only_payload(
            args, root, failure_reason=failure_reason
        )
        if payload is None:
            detail = failure_reason[0] if failure_reason else "unknown failure"
            print(
                "error: could not compute source-record input identity: " + detail,
                file=sys.stderr,
            )
            if "no current Lean import-closure receipt" in detail:
                print(
                    "hint: finalize paper-local map and sidecar edits, then run one "
                    "current source-record reissue; do not retry identity-only mode "
                    "until that receipt exists",
                    file=sys.stderr,
                )
            return 2
        print(json.dumps(payload, sort_keys=True))
        return 0
    if getattr(args, "fast_saved_identity", False):
        payload = fast_saved_source_record_identity_payload(args, root)
        print(json.dumps(payload, sort_keys=True))
        return 0 if payload.get("current") is True else 1
    if getattr(args, "rebind_semantic_authority_controls", False):
        paper_dir = root / "papers" / args.paper
        raw_path = paper_dir / "audit" / "source_record_audit.json"
        status_path = paper_dir / "status.json"
        try:
            validate_runtime_engine_registration(root)
            raw_payload = load_json_object(raw_path)
            status_bytes = status_path.read_bytes()
            status_payload = json.loads(status_bytes)
            status_control_sha256 = stable_digest(
                source_record_status_control_projection(
                    paper_dir, status_path, status_payload
                )
            )
            status_file_sha256 = hashlib.sha256(status_bytes).hexdigest()
            fidelity_path = source_proof_fidelity_path(paper_dir)
            fidelity_bytes = (
                fidelity_path.read_bytes() if fidelity_path is not None else b""
            )
            fidelity_sha256 = source_record_proof_fidelity_semantic_sha256(
                paper_dir
            )
            if fidelity_path is not None and fidelity_path.read_bytes() != fidelity_bytes:
                raise RuntimeError(
                    "source-proof fidelity bytes changed while computing semantic controls"
                )
            fidelity_file_sha256 = (
                hashlib.sha256(fidelity_bytes).hexdigest()
                if fidelity_path is not None
                else ""
            )
        except (
            EngineRevisionError,
            OSError,
            RuntimeError,
            ValueError,
            json.JSONDecodeError,
        ) as exc:
            print(
                "error: could not compute current semantic controls: " + str(exc),
                file=sys.stderr,
            )
            return 2
        error = rebind_semantic_validation_authority_controls(
            root=root,
            paper_dir=paper_dir,
            raw_audit=raw_payload,
            current_status_control_sha256=status_control_sha256,
            current_status_file_sha256=status_file_sha256,
            current_source_proof_fidelity_sha256=fidelity_sha256,
            current_source_proof_fidelity_file_sha256=fidelity_file_sha256,
            source_proof_fidelity_path=fidelity_path,
        )
        if error:
            print("error: " + error, file=sys.stderr)
            return 2
        print(
            json.dumps(
                {
                    "paper": args.paper,
                    "rebound": True,
                    "semantic_controls_unchanged": True,
                    "lean_rerun": False,
                },
                sort_keys=True,
            )
        )
        return 0
    # The cache is a receipt-validated semantic identity check, not a weaker
    # name-based shortcut. Check it before taking the lock used exclusively for
    # fresh Lean/source scans so an ordinary current paper never waits behind
    # an unrelated regeneration.
    cached_exit = emit_reusable_source_record_audit_without_lock(args, root)
    if cached_exit is not None:
        return cached_exit
    try:
        with source_record_audit_lock(
            root,
            args.lock_timeout_seconds,
            owner={"paper": args.paper, "operation": "source_record_scan"},
        ):
            return _run_audit(args, root)
    except SourceRecordAuditLockUnavailable as exc:
        print(f"error: {exc}", file=sys.stderr)
        return 4


if __name__ == "__main__":
    sys.exit(main())
